_DYNAMIC_SERVICE_FIELDS = {
    "input_contract", "input_schema", "output_contract", "outputs",
    "resource_requirements", "admission", "workflow", "processing",
    "metadata", "runtime_profile", "workflow_ref", "adapter",
    "operation_catalog_ref", "source_lock_ref",
    "dependencies", "models", "model_targets", "capabilities", "aliases",
}
