# A declarative service describes contracts and reviewed references.  These
# legacy fields can influence host processes or hardware ownership and must
# remain on an operator-controlled runtime/profile path.
_DECLARATIVE_RUNTIME_FIELDS = {
    "systemd_unit", "launch_args", "env_overrides", "model_path", "cpuset",
    "gpu_id", "bundle", "linked_to", "linked_from", "proxy_port",
    "protected", "cpu_only",
}


def _declarative_runtime_field_errors(payload: Mapping[str, Any]) -> list[str]:
    """Reject host/runtime controls from GUI-defined service drafts."""

    safe_empty = {
        "systemd_unit": None,
        "launch_args": [],
        "env_overrides": {},
        "model_path": "",
        "cpuset": "",
        "gpu_id": None,
        "bundle": None,
        "linked_to": [],
        "linked_from": [],
        "proxy_port": None,
    }
    fields: list[str] = []
    for field in sorted(_DECLARATIVE_RUNTIME_FIELDS):
        if field not in payload:
            continue
        if field in safe_empty and payload[field] == safe_empty[field]:
            continue
        fields.append(field)
    return fields

# --- Phase 3 Scheduler Skeleton ---
_scheduler_judged_ready = False
_scheduler_started_at = time.time()
_scheduler_judgement = {}
_grace_window = {'state': 'completed'}
_last_swap_timestamp = 0.0
_current_selected_group = None
_drain_cutoffs = {}
_last_next_decision = {}
# Full ranked demand list from the last phase-3 refresh (warm-pool look-ahead).
_last_pending_groups: list = []


def _maintenance_mode_enabled(scheduling: Mapping[str, Any] | None) -> bool:
    """Normalize maintenance mode, failing closed on malformed values."""
    if not isinstance(scheduling, Mapping):
        return True
    raw = scheduling.get("maintenance_mode", False)
    return raw if isinstance(raw, bool) else True


def _phase3_scheduling_config():
    global _services_config
    try:
        sched = _services_config.get('scheduling', {})
    except NameError:
        sched = {}
    # Stage 5: env-var override for soft live scheduler ownership flip.
    # Default: 'false' (config-file value wins). When GPU Manager systemd unit
    # has GPU_MANAGER_SCHEDULER_OWNS_LOAD=true in its drop-in, this overrides
    # services.json and the scheduler becomes the sole owner of _load_bundle.
    #
    # Invariant: env can only RAISE the flag (OR semantics below) — never lower
    # a config-file True. This avoids a typo'd env var silently flipping
    # ownership off. To turn scheduler ownership off, edit services.json.
    #
    # NOTE: scheduler_dry_run_mode is intentionally NOT env-overridable here.
    # A live scheduler also requires the separate config-file-only
    # ``proactive_scheduling_enabled`` gate. This keeps ownership and telemetry
    # configuration separate from permission to perform a bundle transition.
    #
    # services.json (the source of truth when env-var is unset) is loaded from
    # SERVICES_CONFIG_PATH; see top-of-file for the resolved runtime location.
    env_owns = os.environ.get('GPU_MANAGER_SCHEDULER_OWNS_LOAD', 'false').strip().lower() == 'true'
    maintenance_mode = _maintenance_mode_enabled(sched)
    return {
        'grace_period_seconds': sched.get('grace_period_seconds', 30),
        'grace_min_resume_interval_s': sched.get('grace_min_resume_interval_s', 60),
        'demand_min_lag': sched.get('demand_min_lag', 1),
        'demand_min_ingress': sched.get('demand_min_ingress', 1),
        'min_dwell_seconds': sched.get('min_dwell_seconds', 20),
        # Aging is bounded and only changes the diagnostic/selection score;
        # it does not bypass bundle fencing or scheduler ownership gates.
        'priority_lanes_enabled': bool(sched.get('priority_lanes_enabled', False)),
        'queue_priority_aging_cap': sched.get('queue_priority_aging_cap', 3),
        'priority_aging_interval_s': sched.get('priority_aging_interval_s', 60),
        'priority_aging_cap': sched.get('priority_aging_cap', 100),
        # Queue ownership is deliberately opt-in.  ``split`` preserves the
        # current compatibility behavior while the durable/legacy modes give
        # operators a reversible way to fence one owner during cutover.
        'queue_owner': sched.get('queue_owner', 'split'),
        # Maintenance is an overriding safety fence. An environment override
        # must never grant scheduler ownership while the controller is paused.
        'scheduler_owns_load': False if maintenance_mode else (
            env_owns or sched.get('scheduler_owns_load', False)
        ),
        'scheduler_dry_run_mode': True if maintenance_mode else sched.get(
            'scheduler_dry_run_mode', True
        ),
        'proactive_scheduling_enabled': False if maintenance_mode else sched.get(
            'proactive_scheduling_enabled', False
        ),
        'maintenance_mode': maintenance_mode
    }


_QUEUE_OWNER_MODES = frozenset({'split', 'legacy', 'durable'})


def _queue_owner_mode(scheduling: Mapping[str, Any] | None = None) -> str:
    """Return the normalized startup queue-owner policy.

    ``split`` is the compatibility default because the candidate still has
    legacy ``GPUScheduler`` endpoints and durable Redis worker endpoints.
    Invalid values fail safe to ``split`` and are surfaced in health output;
    they must not silently select one owner and strand the other queue.
    """
    if scheduling is None:
        scheduling = _phase3_scheduling_config()
    raw = scheduling.get('queue_owner', 'split') if isinstance(scheduling, Mapping) else 'split'
    mode = str(raw or 'split').strip().lower()
    if mode not in _QUEUE_OWNER_MODES:
        logger.warning("Invalid scheduling.queue_owner=%r; retaining split compatibility mode", raw)
        return 'split'
    return mode


def _queue_owner_route_fence(route_owner: str, route: str):
    """Return a response when a compatibility route is owned elsewhere.

    The helper is intentionally side-effect free so handlers can call it
    before parsing/admitting a request.  ``None`` means the route is allowed
    under the configured policy.
    """
    configured = _queue_owner_mode()
    if configured == 'split' or configured == route_owner:
        return None
    return web.json_response(
        {
            'error': 'queue_owner_route_fenced',
            'reason': 'queue_owner_cutover_required',
            'configured_owner': configured,
            'route_owner': route_owner,
            'route': route,
        },
        status=503,
    )

def _get_phase3_scheduler_state(groups, all_gpu_states, generation_templates):
    config = _phase3_scheduling_config()
    now = time.time()

    observed_pending = {rg: g.get('queue_lag', 0) for rg, g in groups.items() if g.get('queue_lag', 0) > 0}

    gpu_warm_bundles = {}
    for gid, gs in all_gpu_states.items():
        gs_dict = gs.to_dict() if hasattr(gs, 'to_dict') else {}
        bundle = gs_dict.get('loaded_bundle')
        bundles = gs_dict.get('loaded_bundles', [])
        if bundle or bundles:
            gpu_warm_bundles[gid] = {
                'loaded_bundle': bundle,
                'loaded_bundles': bundles,
                'current_bundle': gs_dict.get('current_bundle'),
                'current_service': gs_dict.get('current_service'),
                'state': gs_dict.get('state')
            }

    try:
        dry_run = _compute_service_group_dry_run(groups, all_gpu_states, generation_templates)
        pending_groups = dry_run.get('pending_groups', [])
    except Exception:
        pending_groups = []

    grace_period_seconds = config.get('grace_period_seconds', 30)
    demand_min_ingress = config.get('demand_min_ingress', 1)
    grace_ends_at = _scheduler_started_at + grace_period_seconds

    global _grace_window
    if 'ingress_counts' not in _grace_window:
        _grace_window['ingress_counts'] = {}
    if 'start_time' not in _grace_window:
        _grace_window['start_time'] = now

    for rg, count in observed_pending.items():
        if count > 0:
            _grace_window['ingress_counts'][rg] = max(_grace_window['ingress_counts'].get(rg, 0), count)
    grace_ingress_counts = _grace_window['ingress_counts']

    grace_started_at = _grace_window.get('start_time', _scheduler_started_at)
    time_in_grace = now - grace_started_at

    has_sufficient_ingress = any(count >= demand_min_ingress for count in grace_ingress_counts.values())

    if now < grace_ends_at:
        if time_in_grace > 5.0 and not has_sufficient_ingress:
            grace_state = 'completed'
            grace_started_at = 0
            grace_ends_at = 0
        else:
            grace_state = 'active'
            grace_started_at = _scheduler_started_at
    else:
        grace_state = 'completed'
        grace_started_at = 0
        grace_ends_at = 0

    global _drain_cutoffs
    if grace_state == 'completed' and pending_groups:
        cand = pending_groups[0].get('group')
        if cand and cand not in _drain_cutoffs:
            _drain_cutoffs[cand] = now

    idle_preferred = (not pending_groups) and (grace_state == 'completed')

    next_decision_val = 'idle'
    next_decision_reason = 'No pending work'
    phase = 'idle'

    if grace_state == 'active':
        next_decision_val = 'awaiting_grace'
        next_decision_reason = f'Grace period active until {grace_ends_at}'
        phase = 'grace'
    elif pending_groups:
        phase = 'demand_driven'
        candidate_group = pending_groups[0].get('group')
        dwell = _last_swap_timestamp
        dwell_time = config.get('min_dwell_seconds', 20)
        if dwell and (now - dwell < dwell_time):
            next_decision_val = 'hold_dwell_time'
            next_decision_reason = f'Holding for dwell time {dwell_time}s on {candidate_group}'
        else:
            next_decision_val = f'demand:{candidate_group}'
            next_decision_reason = f'Pending demand for {candidate_group}'

    global _last_next_decision, _last_pending_groups
    _last_pending_groups = list(pending_groups)
    _last_next_decision = {
        'next_decision': next_decision_val,
        'decision_timestamp': now,
        'idle_preferred': idle_preferred
    }

    return {
        'restart_state_judgement': {
            'phase': phase,
            'previous_state_resumable': False,
            'observed_pending': observed_pending,
            'observed_ingress_window': {},
            'gpu_warm_bundles': gpu_warm_bundles,
            'judgment_timestamp': _scheduler_started_at
        },
        'grace_window_state': {
            'state': grace_state,
            'grace_started_at': grace_started_at,
            'grace_ends_at': grace_ends_at,
            'grace_ingress_counts': grace_ingress_counts
        },

        'next_decision': next_decision_val,
        'next_decision_reason': next_decision_reason,
        'decision_timestamp': now,
        'idle_preferred': idle_preferred,
        'drain_cutoffs': dict(_drain_cutoffs),
        'phase3_scheduler': True
    }

def can_consume(service_name, routing_group):
    config = _phase3_scheduling_config()
    if config.get('maintenance_mode'):
        return False, 'paused_maintenance'
    if not config.get('scheduler_owns_load'):
        return True, 'allowed'

    current_decision_state = _last_next_decision.get('next_decision') if isinstance(_last_next_decision, dict) else ''
    if current_decision_state == 'awaiting_grace':
        return False, 'paused_grace'

    try:
        svc_cfg = _services_config.get('services', {}).get(service_name, {})
    except Exception:
        svc_cfg = {}

    service_name_lower = service_name.lower()
    gpu_id = svc_cfg.get('gpu_id', '').lower()

    if 'ccd0' in service_name_lower or gpu_id in ('cpu', 'ccd0') or svc_cfg.get('cpu_only'):
        return True, 'allowed'

    gen_groups = {'comfyui-gen', 'music-gen', 'video-gen', 'image-gen', 'acestep'}
    is_gen = (
        any(g in service_name_lower for g in gen_groups) or
        any(g in routing_group.lower() for g in gen_groups) or
        svc_cfg.get('type') == 'generation_backend'
    )

    if is_gen:
        bundle = svc_cfg.get('bundle')
        if not bundle:
            try:
                templates = _services_config.get('generation_templates', {})
                for k, tmpl in templates.items():
                    if k == routing_group or tmpl.get('routing_group') == routing_group:
                        bundle = tmpl.get('bundle')
                        if bundle:
                            break
            except Exception:
                pass

        # Bundle-backed generation is admitted by WorkerPool._execute_job. A cold
        # bundle must therefore remain claimable: rejecting it here creates a
        # self-deadlock where no worker can reach the only bundle-load transaction.
        if bundle:
            return True, 'allowed_bundle_admission'

        target_decision = f'demand:{routing_group}'
        current_decision = _last_next_decision.get('next_decision', '') if isinstance(_last_next_decision, dict) else str(_last_next_decision)
        if target_decision not in current_decision and _current_selected_group != routing_group:
            return False, 'paused_demand_swap'

        return True, 'allowed'

    if svc_cfg.get('type') == 'llm_backend':
        # A planned stop is backend-local.  Do not freeze the logical
        # routing group: CPU/secondary GPU members must continue consuming Gemma
        # while the GPU member drains toward a bundle swap.
        if event_bus is not None and event_bus.is_planned_stop(service_name):
            return False, 'paused_planned_stop'
        # Gemma is a logical shared queue.  CPU/secondary GPU members must remain
        # eligible while another Gemma member is draining or a higher
        # priority bundle is waiting for the GPUs.
        if routing_group == 'Gemma':
            return True, 'allowed_logical_group'
        if _current_selected_group:
            return False, 'paused_demand_swap'

    return True, 'allowed'


# ── Pipeline stage dispatch seam ──────────────────────────────────────────────
# The validated worker_pipeline metadata (from compile_generation_pipeline) is
# executed here via PipelineDispatchRunner.  The runner is injected at call
# time so the existing Krea path remains intact when no pipeline is present.
#
# Provider injection contract:
#   executor_provider(executor_class, stages, context) -> PipelineExecutor
#   Default: instantiates KreaPipelineExecutor and calls its async dispatch.
#
# Fail-closed guarantees preserved:
#   • Unknown provider in stages → PipelineError at compile time (already done)
#   • No stages in worker_pipeline → Krea path is taken unchanged (existing code)
#   • Stage dispatch error → logged, returns (ctx, []) so caller can handle


async def _run_pipeline_stages(
    stages: list[dict],
    context,
    *,
    max_retries: int = 3,
    max_loop_count: int = 1,
    executor_provider=None,
    pre_results: list | None = None,
) -> tuple:
    """
    Dispatch validated pipeline stages via the injected executor provider.

    This is the seam between the declarative pipeline (service_pipeline.py)
    and the concrete execution (stage_dispatch.py KreaPipelineExecutor).

    Arguments:
        stages: compiled stage list from worker_pipeline["stages"]
        context: StageContext with original_prompt and any prior artifacts
        max_retries: per-stage retry cap (default 3)
        max_loop_count: correction loop cap (default 1)
        executor_provider: callable (class, stages, ctx) -> PipelineExecutor
                          Defaults to KreaPipelineExecutor with a no-op
                          _call_provider_async that raises on unknown kinds.

    Returns:
        (final_context, results_in_execution_order)
        Each StageResult has: stage_id, kind, provider, status, data, error, retries

    The existing Krea post-generation path is NOT modified; this function is
    called only when a compiled pipeline with stages is present in metadata.
    """
    sd = _get_stage_dispatch()
    StageContext = sd.StageContext
    PipelineExecutor = sd.PipelineExecutor
    KreaPipelineExecutor = sd.KreaPipelineExecutor
    DispatchKindError = sd.DispatchKindError
    DispatchProviderError = sd.DispatchProviderError

    if not stages:
        return context, []

    if executor_provider is None:
        # Closure captures the per-call bounds so the default provider
        # gets the right values instead of hardcoded defaults.
        _mr, _mlc = max_retries, max_loop_count
        def _bounded_provider(cls, stages, ctx):
            return _default_pipeline_executor_provider(cls, stages, ctx, _mr, _mlc)
        executor_provider = _bounded_provider

    # Build a concrete executor from the injected provider.  The live seam
    # intentionally accepts either a factory, an object exposing
    # ``build_executor``, or an already-built executor; it must not import a
    # concrete provider class from another project tree.
    if hasattr(executor_provider, "build_executor"):
        executor = executor_provider.build_executor(
            KreaPipelineExecutor,
            list(stages),
            context,
            pre_results=pre_results,
        )
    elif callable(executor_provider):
        executor = executor_provider(
            KreaPipelineExecutor,
            list(stages),
            context,
        )
    else:
        executor = executor_provider
    # Backward-compat: if the provider returns a bare class (not instance),
    # instantiate it with pipeline bounds.
    import inspect
    if inspect.isclass(executor):
        executor = _build_pipeline_executor(executor, max_retries, max_loop_count)

    try:
        ctx, results = await executor.dispatch(
            list(stages),
            context,
        )
        return ctx, results
    except (DispatchKindError, DispatchProviderError) as exc:
        logger.warning(
            "pipeline_dispatch: stage execution error: %s", exc,
        )
        return context, []


# ── Provider ownership registry ─────────────────────────────────────────────────
# Provider ownership is now managed by execution_boundary.py.
# LIVE_WORKER_OWNED_ADAPTERS replaces _KREA_ONLY_PROVIDERS.
# Providers are registered via register_provider_ownership() during init.
# _KREA_ONLY_PROVIDERS is retained as a frozen compat set for tests that
# directly reference it; all new code should use LIVE_WORKER_OWNED_ADAPTERS
# or classify_stages() / get_dispatch_mode() instead.
_KREA_ONLY_PROVIDERS: frozenset[str] = frozenset({
    "comfyui",
    "comfyui-qwen",
    "combined-gemma",
})


def _has_non_krea_stage(stages: list[dict]) -> bool:
    """
    Return True if any stage in ``stages`` has a provider that is NOT handled
    by the live ComfyUI worker path (i.e. requires the generic HTTP stage
    dispatcher or the inline KreaPipelineExecutor handlers).

    Delegates to execution_boundary.is_external() (backward-compat shim).

    When True, ``run_pipeline_dispatch`` is called instead of
    ``_reconcile_pipeline_evidence`` so that the stage is executed through
    the configured pipeline executor (e.g. HttpPipelineExecutor for ``http``
    provider stages, or the inline KreaPipelineExecutor handlers for other
    non-Krea providers).
    """
    # Keep the historical helper contract for older callers that import the
    # function before the startup registry is populated.  Production dispatch
    # uses get_dispatch_mode() below and remains fail-closed for unknown or
    # mixed ownership; this helper is only a compatibility predicate.
    for stage in stages:
        provider = str(stage.get("provider", ""))
        if not provider:
            return True
        if provider in _KREA_ONLY_PROVIDERS:
            continue
        try:
            if not is_self_owned([stage]):
                return True
        except MissingOwnershipMetadataError:
            return True
    return False


def _fail_mixed_worker_pipeline(
    job_tracker,
    job_id: str,
    *,
    prompt_id: str | None,
    image_data: list[dict],
    qc_report: dict | None,
) -> tuple[str, dict]:
    """Fail a mixed pipeline at the legacy worker boundary.

    Mixed provider ownership must be orchestrated by the controller-level
    coordinator. The legacy worker has already exercised its inline provider
    path, so dispatching external stages here risks duplicate calls.
    """
    code = "pipeline_coordinator_required"
    error = (
        "mixed-ownership pipeline requires pipeline coordinator: worker "
        f"boundary cannot safely dispatch external stages; code={code}"
    )
    payload = {
        "prompt_id": prompt_id,
        "status": "failed",
        "images": image_data,
        "qc": qc_report,
        "code": code,
    }
    if job_tracker:
        job_tracker.update_status(
            job_id,
            "failed",
            error=error,
            result=json.dumps(payload),
        )
    return error, payload


def _reconcile_pipeline_evidence(
    worker_pipeline: dict,
    *,
    original_prompt: str,
    enhanced_prompt: str,
    image_data: list[dict],
    qc_report: dict | None,
) -> tuple:
    """Bind real worker outputs to a declarative pipeline without re-running it.

    The image worker already owns the live prompt-enhancement, ComfyUI, and
    post-generation QC/correction calls.  Re-dispatching those stages here
    would execute synthetic handlers a second time and could falsely claim a
    provider success.  This reconciler therefore creates stage results only
    from evidence produced by those real calls.  An unknown stage kind or a
    missing required artifact is a hard, fail-closed mismatch.

    Returns ``(context, results, reconciled)``.  ``reconciled`` is false when
    the declarative pipeline is not the supported Krea worker contract; callers
    must not silently treat that case as success.
    """
    sd = _get_stage_dispatch()
    StageContext = sd.StageContext
    StageResult = sd.StageResult
    stages = list(worker_pipeline.get("stages") or [])
    if not stages:
        return StageContext(original_prompt=original_prompt), [], False

    context = StageContext(original_prompt=original_prompt)
    results: list = []
    by_id: dict[str, object] = {}
    supported_providers = {
        # The retired controller is gone; n8n remains a valid external
        # prompt_enhance provider dispatched through the generic transport.
        "prompt_enhance": {"n8n"},
        "generate": {"comfyui"},
        "qc": {"combined-gemma"},
        "correct": {"comfyui-qwen"},
    }
    qc = dict(qc_report or {})
    terminal_qc_status = str(qc.get("terminal_qc_status") or "").lower()
    if "qc_pass" in qc:
        qc_pass = bool(qc["qc_pass"])
        terminal_qc_status = terminal_qc_status or ("pass" if qc_pass else "fail")
    else:
        qc_pass = terminal_qc_status in {"pass", "passed", "ok", "success"}
    correction_attempted = bool(qc.get("correction_attempted"))

    for stage in stages:
        stage_id = str(stage.get("id") or "")
        kind = str(stage.get("kind") or "")
        provider = str(stage.get("provider") or "")
        if not stage_id or provider not in supported_providers.get(kind, set()):
            return context, results, False

        for dep in stage.get("depends_on", []) or []:
            dep_result = by_id.get(str(dep))
            if dep_result is None or getattr(dep_result, "status", "failed") == "failed":
                return context, results, False

        if kind == "prompt_enhance":
            if not enhanced_prompt:
                return context, results, False
            result = StageResult(
                stage_id=stage_id, kind=kind, provider=provider, status="ok",
                data={"prompt": enhanced_prompt, "evidence_source": "live_worker"},
            )
            context = context.with_prompt(stage_id, enhanced_prompt)
        elif kind == "generate":
            if not image_data:
                return context, results, False
            result = StageResult(
                stage_id=stage_id, kind=kind, provider=provider, status="ok",
                data={
                    "images": image_data,
                    "artifact_count": len(image_data),
                    "evidence_source": "live_comfyui",
                },
            )
            context = context.with_artifact(stage_id, result.data)
        elif kind == "qc":
            if not qc_report or not terminal_qc_status:
                return context, results, False
            result = StageResult(
                stage_id=stage_id, kind=kind, provider=provider,
                status="ok" if qc_pass else "failed",
                data={**qc, "qc_pass": qc_pass, "evidence_source": "live_qc"},
                error="" if qc_pass else "live QC did not pass",
            )
            context = context.with_qc(stage_id, result.data)
        elif kind == "correct":
            if qc_pass and not correction_attempted:
                result = StageResult(
                    stage_id=stage_id, kind=kind, provider=provider,
                    status="skipped", data={},
                    error="correction not required after passing QC",
                )
            elif correction_attempted:
                result = StageResult(
                    stage_id=stage_id, kind=kind, provider=provider, status="ok",
                    data={"correction_attempted": True, "evidence_source": "live_worker"},
                )
                context = context.with_loop_increment().with_artifact(stage_id, result.data)
            else:
                return context, results, False
        else:
            return context, results, False

        by_id[stage_id] = result
        results.append(result)
        if result.status == "failed":
            return context, results, True

    return context, results, True


def _seed_pipeline_context_from_worker_evidence(
    worker_pipeline: dict,
    *,
    original_prompt: str,
    effective_prompt: str = "",
    image_data: list[dict] | None = None,
    qc_report: dict | None = None,
):
    """Build the handoff context from evidence already produced by the worker.

    Mixed pipelines must not redispatch worker-owned stages.  The worker has
    already performed the local ComfyUI request (and may have performed local
    prompt/QC work), so the generic dispatcher receives a typed evidence bag
    keyed by the declarative stage IDs.  Missing evidence remains visible as an
    empty result and is rejected by the handoff validation/terminal checks.
    """
    sd = _get_stage_dispatch()
    context = sd.StageContext(original_prompt=original_prompt)
    image_data = list(image_data or [])
    qc = dict(qc_report or {})
    terminal_status = str(qc.get("terminal_qc_status") or "").lower()
    if "qc_pass" not in qc and terminal_status:
        qc["qc_pass"] = terminal_status in {"pass", "passed", "ok", "success"}
    correction_attempted = bool(qc.get("correction_attempted"))

    for stage in list(worker_pipeline.get("stages") or []):
        stage_id = str(stage.get("id") or "")
        kind = str(stage.get("kind") or "")
        if not stage_id:
            continue
        if kind == "prompt_enhance" and effective_prompt:
            context = context.with_prompt(stage_id, effective_prompt)
        elif kind in {"generate", "delegate"} and image_data:
            context = context.with_artifact(
                stage_id,
                {
                    "images": image_data,
                    "artifact_count": len(image_data),
                    "evidence_source": "live_comfyui",
                },
            )
        elif kind == "qc" and qc:
            context = context.with_qc(stage_id, qc)
        elif kind == "correct" and correction_attempted:
            context = context.with_loop_increment().with_artifact(
                stage_id,
                {"correction_attempted": True, "evidence_source": "live_worker"},
            )
    return context


class _KreaDispatchRunner:
    """
    PipelineDispatchRunner that wraps KreaPipelineExecutor.

    Injected at worker execution time so tests can substitute a
    FakeKreaPipelineExecutor without modifying the gpu-manager call site.
    """

    def __init__(
        self,
        max_retries: int = 3,
        max_loop_count: int = 1,
    ):
        self.max_retries = max_retries
        self.max_loop_count = max_loop_count

    def build_executor(
        self,
        executor_class,  # type: ignore[override]
        stages=None,
        context=None,
    ) -> "KreaPipelineExecutor":  # type: ignore[name-defined]
        # stages and context are accepted for interface compatibility with
        # _run_pipeline_stages' generic dispatch contract but are not used;
        # _InlineExecutor gets its bounds from self.max_retries / self.max_loop_count.
        return _build_pipeline_executor(executor_class, self.max_retries, self.max_loop_count)


class _MixedOwnershipExecutor:
    """
    Thin wrapper around CompositeProviderExecutor that intercepts dispatch() to
    inject pre-executed worker-owned stage results (seeded from the GPU Manager
    worker's evidence bag) so that external stages can depend on worker-owned
    stages without re-executing them.

    This is the typed seam for the mixed-ownership handoff protocol:
    the GPU Manager worker executes the worker-owned stages (prompt_enhance via
    ComfyUI, qc via Combined-Gemma), collects their
    outputs into a StageContext, and then passes that context to the
    CompositeProviderExecutor via this wrapper.  The wrapper pre-populates the
    fan-in dependency map so external stages (e.g. n8n, http-qc) see the same
    context as if all stages had run in a single sequential pipeline.

    This class never submits worker-owned stages to the GPU or any HTTP backend.

    Parameters
    ----------
    inner : CompositeProviderExecutor
        The underlying multi-provider executor for external stages.
    seeded_results : list[StageResult]
        Pre-executed results for all worker-owned stages.  These are injected
        into the fan-in dependency map before dispatch begins.
    seeded_context : StageContext
        The StageContext carrying evidence from worker-owned stages
        (enhanced_prompts, artifacts, qc_results, correction_loop_count).
        This replaces the caller's context so external stages receive the
        same evidence as if worker stages had run inline.
    """

    __slots__ = ("_inner", "_seeded_results", "_seeded_context", "_external_stages")

    def __init__(
        self,
        inner: "CompositeProviderExecutor",
        seeded_results: list,
        seeded_context: "StageContext",
        external_stages: list[dict] | None = None,
    ) -> None:
        self._inner = inner
        self._seeded_results = seeded_results
        self._seeded_context = seeded_context
        # The external-only stage list produced by safe_handoff_stages().
        # Only these stages are dispatched to the inner executor; worker-owned
        # stages are already recorded in _seeded_results and must NOT be
        # re-executed (would cause duplicate generation/calls).
        self._external_stages = external_stages if external_stages is not None else []

    async def dispatch(
        self,
        stages: list[dict],
        context: "StageContext",
    ):
        """
        Dispatch stages with pre-seeded worker-owned results pre-populated
        in the fan-in map.

        Passes the full ``stages`` graph so that external stages can look up
        worker-owned stages in their fan-in ``depends_on`` chains via the
        seeded results pre-populated in the dependency map.

        Worker-owned stages are never dispatched (they are already in
        ``seeded_results`` and must NOT be re-executed).  Only the external
        stages from ``_external_stages`` are iterated for actual dispatch.
        """
        # The full graph is passed so stage_defs has all stage IDs for
        # depends_on fan-in lookups.  We iterate only dispatch_stages
        # (external-only) to avoid re-executing worker-owned stages.
        dispatch_stages = self._external_stages
        if not dispatch_stages:
            seeded_ids = {
                getattr(result, "stage_id", "")
                for result in (self._seeded_results or [])
            }
            dispatch_stages = [stage for stage in stages if stage.get("id") not in seeded_ids]

        # A valid handoff normally supplies seeded_context, but callers may
        # construct this wrapper with only a caller context while an ownership
        # handoff is being assembled. Never discard that valid context and
        # replace it with None: downstream adapters require StageContext.
        dispatch_context = (
            self._seeded_context
            if self._seeded_context is not None
            else context
        )
        if dispatch_context is None:
            raise TypeError("mixed-ownership dispatch requires a StageContext")
        dispatch_kwargs = {
            "context": dispatch_context,
            "seeded_results": self._seeded_results,
        }
        # Older injected test doubles expose the pre-contract dispatch
        # signature.  Use introspection rather than catching TypeError from
        # the call, so a genuine provider TypeError is never mistaken for a
        # compatibility downgrade.
        import inspect
        try:
            dispatch_signature = inspect.signature(self._inner.dispatch)
        except (TypeError, ValueError):
            dispatch_signature = None
        if dispatch_signature is not None and "stage_defs" in dispatch_signature.parameters:
            # Keep the complete declarative graph available for dependency
            # validation and loop re-entry while only external stages are
            # eligible for actual dispatch.  Passing the full graph as the
            # positional ``stages`` argument would re-run worker-owned stages.
            dispatch_kwargs["stage_defs"] = {
                str(stage.get("id")): stage for stage in stages
            }
        dispatch_result = self._inner.dispatch(dispatch_stages, **dispatch_kwargs)
        # Production executors are async, while hermetic tests and injected
        # adapters may expose a synchronous stub.  Accept either without
        # weakening the typed result contract.
        import inspect
        if inspect.isawaitable(dispatch_result):
            return await dispatch_result
        return dispatch_result


class _GenericPipelineDispatchRunner:
    """
    PipelineDispatchRunner that builds a CompositeProviderExecutor for the
    generic ``execution_mode``, routing each stage to the provider declared
    in the pipeline contract via the PipelineProviderRuntime.

    This is the injected runner for WorkerPool pools when a generic-mode
    pipeline is present.  It uses the GPU Manager's live services.json
    provider registry and the existing aiohttp session to make real HTTP
    calls for ``http_json`` / ``http_openai_compatible`` stages, and uses
    the ``stage_executor_factory`` for ``gpu_manager_generation`` stages.

    Fail-closed on:
      - Unknown provider IDs (not in the provider registry)
      - ``gpu_manager_generation`` stages without a factory (raises
        ``MissingExecutorFactoryError``)
      - ``gpu_manager_generation`` stages when the provider is not in
        the gpu_executor_map (raises ``MissingExecutorFactoryError``)

    The existing Krea path (legacy_reconcile mode, or generic with all
    stages targeting KREA_ONLY_PROVIDERS) is NOT routed here; it uses
    ``_KreaDispatchRunner`` instead, avoiding any duplicate GPU generation.

    Injected at WorkerPool construction time via ``pipeline_dispatch_runner``.
    """

    def __init__(
        self,
        services_config: dict,
        provider_registry: frozenset[str],
        session: "ClientSession",
        max_retries: int = 3,
        max_loop_count: int = 1,
    ):
        self._services_config = services_config
        self._provider_registry = provider_registry
        self._session = session
        self.max_retries = max_retries
        self.max_loop_count = max_loop_count

    def build_executor(
        self,
        executor_class,  # accepted for interface compatibility; ignored
        stages: list[dict] | None = None,
        context=None,
        pre_results: list | None = None,
    ) -> "CompositeProviderExecutor | _MixedOwnershipExecutor":
        """
        Build a CompositeProviderExecutor from the pipeline contract.

        When the pipeline contains both worker-owned and external stages
        (mixed ownership), safe_handoff_stages() is called to:
          1. Filter stages to external-only (worker stages already executed)
          2. Build a seeded StageContext from the worker's evidence bag
          3. Build StageResult objects for all worker-owned stages

        The returned executor wrapper intercepts dispatch() to inject the
        seeded results and context so external stages see the same evidence
        as if worker stages had run inline.

        Parameters
        ----------
        executor_class : type
            Accepted for interface compatibility with _run_pipeline_stages;
            the generic runner always returns a CompositeProviderExecutor.
        stages : list[dict] | None
            The compiled stage list from the pipeline contract.  Required
            for resolving the transport map.  When None (e.g. during
            class-level inspection), returns an unbound executor.
        context : StageContext | None
            The live execution context from the worker.  Required for
            mixed-ownership pipelines so the seeded context can be built
            with the correct original_prompt, enhanced_prompts, artifacts,
            and qc_results.  Ignored for non-mixed pipelines.

        Returns
        -------
        CompositeProviderExecutor | _MixedOwnershipExecutor
            A standard executor for non-mixed pipelines, or a wrapper
            that injects seeded results for mixed-ownership pipelines.
        """
        # Import lazily to keep the pipeline_provider_runtime import at the
        # top of the stage-dispatch seam, not at module load time.
        from pipeline_provider_runtime import (
            PipelineProviderRuntime,
            MissingExecutorFactoryError,
        )
        from stage_dispatch import GenerationStageExecutor

        # ── Mixed-ownership detection ──────────────────────────────────────
        # Check whether the full pipeline is mixed-ownership before filtering.
        # safe_handoff_stages is called below with the evidence from context
        # to produce the filtered external-only stages and seeded results.
        mixed_cls = None
        if stages:
            try:
                mixed_cls = classify_stages(stages)
            except MissingOwnershipMetadataError:
                pass  # Will raise at dispatch time

        if (
            stages
            and mixed_cls is not None
            and mixed_cls.is_mixed_ownership
        ):
            # Mixed-ownership pipeline: extract worker evidence from context
            # and build a handoff result with external-only stages.
            # context may be None in tests; pass empty evidence rather than
            # crashing so that build_executor can be called without a context.
            if context is not None:
                _original_prompt = context.original_prompt
                _enhanced_prompts = dict(context.enhanced_prompts)
                _artifacts = dict(context.artifacts)
                _qc_results = dict(context.qc_results)
                _correction_loop_count = context.correction_loop_count
            else:
                _original_prompt = ""
                _enhanced_prompts = {}
                _artifacts = {}
                _qc_results = {}
                _correction_loop_count = 0
            handoff = safe_handoff_stages(
                stages,
                original_prompt=_original_prompt,
                enhanced_prompts=_enhanced_prompts,
                artifacts=_artifacts,
                qc_results=_qc_results,
                correction_loop_count=_correction_loop_count,
                pre_results=pre_results,
            )
            # Use the filtered external-only stages for building the executor.
            # Worker-owned stages are NOT re-dispatched.
            exec_stages: list[dict] | None = handoff.external_stages
            seeded_ctx = handoff.seeded_context
            seeded_res = handoff.seeded_results
        else:
            exec_stages = stages
            seeded_ctx = None
            seeded_res = None

        runtime = PipelineProviderRuntime(
            services_config=self._services_config,
            provider_registry=self._provider_registry,
        )

        # Build a transport map for every non-gpu_manager_generation provider
        # referenced in the stages.  gpu_manager_generation providers use the
        # stage_executor_factory instead.
        transport_map: dict[str, Any] = {}
        if exec_stages:
            seen_providers: set[str] = set()
            for stage in exec_stages:
                provider_id = str(stage.get("provider", ""))
                if not provider_id or provider_id in seen_providers:
                    continue
                seen_providers.add(provider_id)
                try:
                    cfg = runtime._resolve_provider_config(provider_id)
                except Exception:
                    continue  # will raise at dispatch time if actually used
                adapter = cfg.get("adapter", "")
                if adapter == "gpu_manager_generation":
                    continue  # handled via stage_executor_factory
                # Wrap the aiohttp session as a transport callable
                transport_map[provider_id] = _AiohttpTransport(self._session)

        # Factory for gpu_manager_generation stages
        def _gpu_factory(
            provider_id: str, _transport: Any
        ) -> GenerationStageExecutor:
            # Build a GPU generation executor using the same runtime
            gpu_adapter = runtime.build_gpu_adapter(provider_id, _transport)
            return _GPUSubmissionExecutor(
                provider_id=provider_id,
                gpu_adapter=gpu_adapter,
                max_retries=self.max_retries,
            )

        multi = runtime.build_multi_provider_executor(
            contract={"stages": exec_stages or [], "max_loop_count": self.max_loop_count},
            transport_map=transport_map,
            stage_executor_factory=_gpu_factory,
            max_delegate_depth=3,
            max_retries=self.max_retries,
        )

        # For mixed-ownership: wrap so dispatch() injects seeded results and
        # dispatches only external stages (worker stages are already done).
        if seeded_res is not None and seeded_ctx is not None:
            return _MixedOwnershipExecutor(
                inner=multi,
                seeded_results=seeded_res,
                seeded_context=seeded_ctx,
                external_stages=exec_stages,
            )
        return multi


class _AiohttpTransport:
    """
    Thin adapter that wraps an aiohttp.ClientSession as a transport callable
    usable by PipelineProviderRuntime.

    Signature: (headers, method, url, body_bytes, timeout) -> Awaitable[tuple[int, bytes, dict]]
    """

    def __init__(self, session: "ClientSession", *, owner_loop=None) -> None:
        self._session = session
        self._owner_loop = owner_loop

    async def __call__(
        self,
        headers: dict,
        method: str,
        url: str,
        body: bytes | None,
        timeout: float = 30.0,
    ) -> tuple[int, bytes, dict]:
        """Make an HTTP request and return (status, body_bytes, headers_dict)."""
        if self._owner_loop is not None and asyncio.get_running_loop() is not self._owner_loop:
            # Coordinator stages run in worker threads with their own loops;
            # aiohttp sessions must execute on their original owning loop.
            pending = asyncio.run_coroutine_threadsafe(
                self(headers, method, url, body, timeout), self._owner_loop,
            )
            return await asyncio.wrap_future(pending)
        request_headers = dict(headers)
        self_authenticated = False
        if not any(str(name).lower() == "authorization" for name in request_headers):
            from urllib.parse import urlsplit

            parsed = urlsplit(url)
            try:
                target_port = parsed.port
            except ValueError:
                target_port = None
            if (
                parsed.scheme == "http"
                and (parsed.hostname or "").lower() in {"127.0.0.1", "localhost", "::1"}
                and target_port == int(LISTEN_PORT)
            ):
                token = _api_token()
                if token:
                    request_headers["Authorization"] = f"Bearer {token}"
                    self_authenticated = True
        kwargs: dict = {
            "headers": request_headers,
            "allow_redirects": not self_authenticated,
        }
        if body:
            kwargs["data"] = body
        timeout_obj = __import__("aiohttp", fromlist=["ClientTimeout"]).ClientTimeout(
            total=timeout
        )
        kwargs["timeout"] = timeout_obj

        async with self._session.request(method, url, **kwargs) as resp:
            try:
                body_bytes = await resp.read()
            except Exception:
                body_bytes = b""
            return (
                resp.status,
                body_bytes,
                dict(resp.headers),
            )


class _GPUSubmissionExecutor(GenerationStageExecutor):
    """
    Concrete GenerationStageExecutor that submits to the GPU Manager generation API
    via the GPUMgrLikeAdapter.

    Raises DispatchProviderError fail-closed on submission failure so the bounded
    retry loop in CompositeProviderExecutor can handle it correctly.
    """

    def __init__(
        self,
        provider_id: str,
        gpu_adapter: Any,  # GPUMgrLikeAdapter
        max_retries: int = 3,
    ) -> None:
        self._provider_id = provider_id
        self._gpu_adapter = gpu_adapter
        self.max_retries = max_retries
        self._job_id: str | None = None

    async def dispatch(
        self,
        stage_id: str,
        kind: str,
        provider: str,
        params: dict,
        context: "StageContext",
    ) -> "StageResult":
        """
        Submit a GPU generation job and wait for its completion.

        Raises DispatchProviderError on submission or polling failure,
        which triggers the bounded retry loop in CompositeProviderExecutor.
        """
        from stage_dispatch import StageResult, DispatchProviderError

        # Build the assignment from stage params and context
        assignment = _build_gpu_assignment(stage_id, kind, provider, params, context)

        try:
            receipt = await self._gpu_adapter.submit(
                assignment,
                state_store=None,
                params=params,
            )
        except Exception as exc:
            raise DispatchProviderError(
                f"GPU submit failed for stage {stage_id!r}: {exc}"
            ) from exc

        self._job_id = getattr(receipt, "job_id", None) or getattr(receipt, "id", None)

        # Poll for completion
        try:
            snapshot = await self._gpu_adapter.poll(
                self._job_id,
                deadline_seconds=params.get("timeout", 300.0),
            )
        except Exception as exc:
            raise DispatchProviderError(
                f"GPU poll failed for job {self._job_id!r}: {exc}"
            ) from exc

        status = getattr(snapshot, "status", "failed")
        if status in ("completed", "ok", "done"):
            return StageResult(
                stage_id=stage_id,
                kind=kind,
                provider=provider,
                status="ok",
                data={
                    "job_id": self._job_id,
                    "outputs": getattr(snapshot, "outputs", []),
                },
                error="",
                retries=0,
            )
        elif status in ("failed", "error"):
            return StageResult(
                stage_id=stage_id,
                kind=kind,
                provider=provider,
                status="failed",
                data={},
                error=getattr(snapshot, "error", f"GPU job {status}"),
                retries=0,
            )
        else:
            # Pending or unknown — treat as ok with available data
            return StageResult(
                stage_id=stage_id,
                kind=kind,
                provider=provider,
                status="ok",
                data={
                    "job_id": self._job_id,
                    "status": status,
                },
                error="",
                retries=0,
            )


def _build_gpu_assignment(
    stage_id: str,
    kind: str,
    provider: str,
    params: dict,
    context: "StageContext",
) -> dict:
    """
    Build a GPU Manager generation assignment dict from a pipeline stage.

    Shapes the stage params + context into the assignment dict expected
    by GPUMgrGenerationAdapter.submit().
    """
    # The assignment is the opaque dict that the GPU Manager generation API
    # receives.  Map from pipeline contract fields to the expected shape.
    prompt = (
        context.enhanced_prompts.get(stage_id, "")
        or list(context.enhanced_prompts.values()[-1:] or [""])[0]
        or context.original_prompt
    )
    assignment: dict = {
        "stage_id": stage_id,
        "kind": kind,
        "provider": provider,
        "params": dict(params),
    }
    if context.original_prompt:
        assignment["original_prompt"] = context.original_prompt
    if prompt and prompt != context.original_prompt:
        assignment["prompt"] = prompt
    # Forward any prior artifacts as context
    if context.artifacts:
        assignment["artifacts"] = dict(context.artifacts)
    return assignment


def _build_pipeline_dispatch_runner(
    services_config: dict,
    provider_registry: frozenset[str],
    session: "ClientSession",
    *,
    max_retries: int = 3,
    max_loop_count: int = 1,
    execution_mode: str = "generic",
) -> "_KreaDispatchRunner | _GenericPipelineDispatchRunner":
    """
    Build the appropriate PipelineDispatchRunner for the given execution mode.

    Parameters
    ----------
    services_config : dict
        The GPU Manager's services.json dict.
    provider_registry : frozenset[str]
        The closed set of known provider IDs.
    session : ClientSession
        The shared aiohttp session for HTTP transport.
    max_retries : int
        Per-stage retry cap.
    max_loop_count : int
        Correction loop cap.
    execution_mode : str
        ``"generic"`` → ``_GenericPipelineDispatchRunner`` (multi-provider HTTP
        dispatch via PipelineProviderRuntime + CompositeProviderExecutor).
        ``"legacy_reconcile"`` → ``_KreaDispatchRunner`` (inline handlers,
        no HTTP, for Krea-only pipelines that are reconciled from live
        worker outputs).

    Returns
    -------
    _KreaDispatchRunner | _GenericPipelineDispatchRunner
    """
    if execution_mode == "generic":
        return _GenericPipelineDispatchRunner(
            services_config=services_config,
            provider_registry=provider_registry,
            session=session,
            max_retries=max_retries,
            max_loop_count=max_loop_count,
        )
    # legacy_reconcile — use the inline handler path (no HTTP, no GPU submission)
    return _KreaDispatchRunner(max_retries=max_retries, max_loop_count=max_loop_count)


def _default_pipeline_executor_provider(executor_class, stages, context, max_retries=3, max_loop_count=1):
    """Default: instantiate the given executor class with pipeline bounds."""
    return _build_pipeline_executor(executor_class, max_retries, max_loop_count)


def _build_pipeline_executor(executor_class, max_retries, max_loop_count):
    """
    Build a concrete PipelineExecutor bound to the CLOSED_KINDS handlers.

    The executor uses the inline async handlers from KreaPipelineExecutor
    directly — no network I/O, no live provider calls.  This lets the
    pipeline be dispatched in-process while keeping the Krea worker path
    completely independent.
    """
    sd = _get_stage_dispatch()

    class _InlineExecutor(executor_class):
        """Executor that calls KreaPipelineExecutor typed handlers inline."""

        async def _call_provider_async(
            self, stage_id, kind, provider, params, ctx
        ):
            # Delegate to the KreaPipelineExecutor typed handlers.
            # These run in-process with fake responses; the real I/O
            # providers are wired separately by the Worker's actual
            # executor (e.g. the ComfyUI + local-vision adapter path).
            handler_map = {
                "prompt_enhance": self._handle_prompt_enhance,
                "generate": self._handle_generate,
                "qc": self._handle_qc,
                "correct": self._handle_correct,
                "delegate": self._handle_delegate,
            }
            handler = handler_map.get(kind)
            if handler is None:
                sd_DispatchKindError = sd.DispatchKindError
                raise sd_DispatchKindError(f"unknown stage kind '{kind}'")
            return await handler(stage_id, provider, params, ctx)

    ex = _InlineExecutor()
    ex.max_retries = max_retries
    ex.max_loop_count = max_loop_count
    return ex


async def run_pipeline_dispatch(
    worker_pipeline: dict,
    original_prompt: str,
    *,
    max_retries: int = 3,
    max_loop_count: int = 1,
    initial_context=None,
    executor_provider=None,
    pre_results: list | None = None,
) -> tuple:
    """
    Public entry point for pipeline dispatch from a worker execution context.

    Arguments:
        worker_pipeline: the compiled worker_pipeline metadata dict (from
                       compile_generation_pipeline output, stored in job metadata)
        original_prompt: the raw prompt string
        max_retries: per-stage retry cap (default 3, from pipeline max_retries)
        max_loop_count: correction loop cap (default 1)
        initial_context: optional StageContext seeded with worker evidence for
                         a mixed-ownership handoff
        executor_provider: optional callable(class, stages, ctx) -> PipelineExecutor.
                          When supplied (e.g. an HttpPipelineExecutor factory from
                          pipeline_http_provider), it replaces the default
                          KreaPipelineExecutor-based provider.  This is the injection
                          point used by WorkerPool.pipeline_dispatch_runner.

    Returns:
        (final_context, results_in_execution_order, dispatched: bool)
        dispatched is False when worker_pipeline has no stages (legacy path).

    Usage in _execute_job::
        if compiled_stages:
            ctx, results, dispatched = await run_pipeline_dispatch(
                worker_pipeline,
                original_prompt,
                max_retries=max_retries,
                max_loop_count=max_loop_count,
                executor_provider=self.pipeline_dispatch_runner,
            )
            if dispatched:
                # Pipeline ran; handle ctx.artifacts / ctx.qc_results
    """
    sd = _get_stage_dispatch()
    StageContext = sd.StageContext

    stages = worker_pipeline.get("stages") or []
    if not stages:
        return StageContext(original_prompt=original_prompt), [], False

    context = initial_context or StageContext(original_prompt=original_prompt)
    # Merge pre_results into the initial context for safe_handoff_stages
    if pre_results:
        for _pr in pre_results:
            if _pr.kind == "prompt_enhance":
                _pr_prompt = _pr.data.get("prompt", "")
                if _pr_prompt:
                    context = context.with_prompt(_pr.stage_id, _pr_prompt)
            elif _pr.kind in ("generate", "delegate"):
                context = context.with_artifact(_pr.stage_id, dict(_pr.data))
            elif _pr.kind == "qc":
                context = context.with_qc(_pr.stage_id, dict(_pr.data))
    ctx, results = await _run_pipeline_stages(
        stages,
        context,
        max_retries=max_retries,
        max_loop_count=max_loop_count,
        executor_provider=executor_provider,
        pre_results=pre_results,
    )
    return ctx, results, True


