# --- Phase 4 Scheduler Skeleton ---
_dual_swap_lock = None
_last_decision = {'action': 'noop', 'reason': 'init'}
_last_dual_swap_state = 'idle'
_head_job_pre_checks = []
import threading
_head_job_pre_checks_lock = threading.Lock()
_comfyui_admission_lock = threading.Lock()
_comfyui_admission_leases: dict[str, float] = {}
_load_history = []
_group_failure_state = {}
_scheduler_dry_run_mode = True


# Scheduler state bodies live in gpu_manager/scheduler_state.py.  The mutable
# state above (_dual_swap_lock, _can_consume_last_log) stays owned by this module;
# bind once, after that state exists, and keep the returned class.
(
    _queue_depth_observation,
    _logical_group_quiescent,
    _wait_for_logical_group_quiescence,
    _log_can_consume_pause,
    _get_dual_swap_lock,
    _RestoreAdmissionGuard,
) = _bind_scheduler_state(globals())


def _bundle_worker_in_flight(bundle_name: str | None, bundles: dict | None = None) -> int:
    """Return active workers across a bundle and all linked GPU roles."""
    if not bundle_name:
        return 0
    if bundle_name.startswith("llm:"):
        bundle_name = bundle_name[4:]
    bundles = bundles or _resolve_bundles()
    bundle = bundles.get(bundle_name)
    if not bundle:
        return 0
    bundle = dict(bundle)
    bundle["name"] = bundle_name
    total = 0
    for gpu_id in _collect_linked_gpus(bundle, bundles):
        state = _get_gpu_state(gpu_id)
        total += int(getattr(state, "worker_in_flight", 0) or 0)
    return total


def _comfyui_execution_interrupted(job_entry: dict) -> bool:
    """Recognize ComfyUI's terminal interruption message in history status."""
    status = job_entry.get("status", {}) if isinstance(job_entry, dict) else {}
    messages = status.get("messages", []) if isinstance(status, dict) else []

    def contains_marker(value: Any) -> bool:
        if isinstance(value, str):
            return value == "execution_interrupted"
        if isinstance(value, dict):
            return any(contains_marker(item) for item in value.values())
        if isinstance(value, (list, tuple)):
            return any(contains_marker(item) for item in value)
        return False

    return contains_marker(messages)


def _bundle_transition_is_active() -> bool:
    """Return True while any GPU is in a serialized bundle transition."""
    for state in _gpu_states.values():
        if (
            bool(getattr(state, "loading", False))
            or bool(getattr(state, "evicting", False))
            or bool(getattr(state, "draining", False))
            or str(getattr(state, "state", "")) in {"loading", "evicting", "draining"}
        ):
            return True
    sched_state = getattr(scheduler, "_gpu_state", {}) if scheduler is not None else {}
    if isinstance(sched_state, dict):
        for state in sched_state.values():
            if isinstance(state, dict) and (
                state.get("loading") or state.get("evicting") or state.get("draining")
            ):
                return True
    return False


def _acquire_comfyui_admission(job_id: str, ttl_seconds: float = 1800.0) -> None:
    """Fence ComfyUI from bundle load until its Redis job is worker-owned."""
    if not job_id:
        return
    with _comfyui_admission_lock:
        _comfyui_admission_leases[str(job_id)] = time.monotonic() + ttl_seconds


def _release_comfyui_admission(job_id: str) -> None:
    if not job_id:
        return
    with _comfyui_admission_lock:
        _comfyui_admission_leases.pop(str(job_id), None)


def _comfyui_admission_in_flight() -> int:
    """Return live admission leases, pruning cancelled/abandoned requests."""
    now = time.monotonic()
    with _comfyui_admission_lock:
        expired = [
            job_id for job_id, deadline in _comfyui_admission_leases.items()
            if deadline <= now
        ]
        for job_id in expired:
            _comfyui_admission_leases.pop(job_id, None)
        return len(_comfyui_admission_leases)


def _direct_idle_stop_blockers(
    *,
    comfyui_busy: bool,
    current_backend: str | None,
    worker_in_flight: int,
    transition_active: bool,
    admission_in_flight: int = 0,
) -> list[str]:
    """Return authoritative reasons direct-idle must not stop ComfyUI.

    ComfyUI removes a prompt from its execution queue before the GPUManager
    WorkerPool has fetched /history, downloaded outputs, committed JobTracker,
    and ACKed Redis. The linked WorkerPool lease is therefore the terminal
    ownership signal; an empty ComfyUI queue alone is not sufficient.
    """
    blockers: list[str] = []
    if comfyui_busy:
        blockers.append("comfyui_queue_busy")
    if current_backend:
        blockers.append("scheduler_backend_active")
    if int(worker_in_flight or 0) > 0:
        blockers.append(f"linked_worker_in_flight:{int(worker_in_flight)}")
    if int(admission_in_flight or 0) > 0:
        blockers.append(f"comfyui_admission_in_flight:{int(admission_in_flight)}")
    if transition_active:
        blockers.append("bundle_transition_active")
    return blockers


def _should_run_direct_idle_fence(
    *,
    was_busy: bool,
    comfyui_busy: bool,
    comfyui_terminally_stopped: bool,
) -> bool:
    """Return whether direct-idle may probe ComfyUI's terminal fence.

    A manager-owned auto-stop intentionally closes ComfyUI's port.  Treating
    that closed port as a failed fence re-arms the idle edge forever and turns
    normal cleanup into repeated warnings.
    """
    return bool(was_busy and not comfyui_busy and not comfyui_terminally_stopped)


def _log_direct_idle_fence_state(state: str, *, blockers: list[str]) -> bool:
    """Emit one structured direct-idle transition line per distinct state."""
    global _direct_idle_fence_last_signature
    signature = (str(state), tuple(sorted(str(item) for item in blockers)))
    if signature == _direct_idle_fence_last_signature:
        return False
    _direct_idle_fence_last_signature = signature
    log = logger.warning if state == "probe_failed" else logger.info
    log(
        "direct_idle_fence state=%s blockers=%s",
        state,
        ",".join(signature[1]) if signature[1] else "none",
    )
    return True


def _arm_comfyui_warm_handoff(
    job_id: str,
    terminal_status: str,
    *,
    ttl_seconds: float = 10.0,
) -> str | None:
    """Bridge the terminal-to-next-submit gap for serial ComfyUI batches."""
    if str(terminal_status) != "completed" or not job_id:
        return None
    lease_key = f"warm-handoff:{job_id}"
    _acquire_comfyui_admission(lease_key, ttl_seconds=ttl_seconds)
    return lease_key


def _generation_release_blockers(
    gpu_ids: set[str] | None = None,
    *,
    ignore_scheduler_restoring: bool = False,
    ignore_loaded_bundles: set[str] | None = None,
) -> list[str]:
    """Return service-agnostic reasons idle recovery must remain deferred.

    When ``gpu_ids`` is provided, inspection is restricted to those physical
    GPUs.  This lets a genuine crash on an otherwise-idle GPU recover while a
    different GPU renders.  With no scope, the helper is fail-closed for a
    global restore caller.
    """
    all_states = _get_all_gpu_states()
    states = {
        gpu_id: state for gpu_id, state in all_states.items()
        if gpu_ids is None or gpu_id in gpu_ids
    }
    blockers: list[str] = []
    if any(
        bool(getattr(state, "loading", False))
        or bool(getattr(state, "evicting", False))
        or bool(getattr(state, "draining", False))
        or bool(getattr(state, "restoring", False))
        or str(getattr(state, "state", "")) in {"loading", "evicting", "draining", "restoring"}
        for state in states.values()
    ):
        blockers.append("bundle_transition_active")

    # Scheduler flags carry no physical-GPU identity, so use them only for a
    # global restore. Per-idle-service crash recovery is instead gated by the
    # authoritative state of that service's own GPU.
    if gpu_ids is None:
        active_backend = getattr(scheduler, "_current_backend", None) if scheduler is not None else None
        if active_backend:
            blockers.append("scheduler_backend_active")
        if scheduler is not None and bool(getattr(scheduler, "_swapping", False)):
            blockers.append("scheduler_swapping")
        if (
            not ignore_scheduler_restoring
            and scheduler is not None
            and bool(getattr(scheduler, "_restoring", False))
        ):
            blockers.append("scheduler_restoring")

    worker_in_flight = sum(
        int(getattr(state, "worker_in_flight", 0) or 0)
        for state in states.values()
    )
    if worker_in_flight > 0:
        blockers.append(f"generation_worker_in_flight:{worker_in_flight}")

    bundles = _resolve_bundles()
    ignored = set(ignore_loaded_bundles or ())
    lingering: set[str] = set()
    for gpu_state in states.values():
        # ``loaded_bundle`` is the startup-persisted canonical owner; the
        # list is the post-reconciliation multi-bundle form. Check both so a
        # short startup window cannot fail open.
        bundle_names = set(getattr(gpu_state, "loaded_bundles", []) or [])
        loaded_bundle = getattr(gpu_state, "loaded_bundle", None)
        if loaded_bundle:
            bundle_names.add(str(loaded_bundle))
        for bundle_name in bundle_names:
            if bundle_name in ignored:
                continue
            bundle = bundles.get(bundle_name) or {}
            if bundle_name and not bundle.get("idle", False):
                lingering.add(str(bundle_name))
    if lingering:
        blockers.append("non_idle_bundle_loaded:" + ",".join(sorted(lingering)))
    for gpu_id, state in states.items():
        oom_state = str(getattr(state, "oom_state", "idle"))
        if oom_state in {"detected", "draining", "verifying", "recovering", "oom_failed", "permanent_failed"}:
            blockers.append(f"oom_recovery_{oom_state}:{gpu_id}")
    return blockers


def _idle_service_recovery_blockers(service_name: str) -> list[str]:
    """Return reasons an idle-service port failure is an expected transition.

    An empty list means recovery may treat a failed health probe as a genuine
    crash.  Planned stop stamps are intentionally short-lived caller hints;
    the independently-derived generation-release state keeps recovery
    suppressed for the whole managed transaction even after that stamp clears.
    """
    blockers: list[str] = []
    # Operator intent is an authoritative recovery fence. A disabled idle
    # service may remain in the topology/idle map, but it must not be probed,
    # warned about, or restarted by any recovery path.
    services = (_load_services_config().get("services") or {})
    service_config = services.get(service_name) or {}
    if not service_config.get("enabled", True):
        blockers.append("config_disabled")
    if event_bus is not None and event_bus.is_planned_stop(service_name):
        blockers.append("planned_stop")
    idle_gpus = {
        str(entry.get("gpu_id"))
        for entry in _get_all_idle_services()
        if entry.get("service_name") == service_name and entry.get("gpu_id")
    }
    # Unknown placement cannot be proven unrelated, so global inspection is
    # the fail-closed fallback. Normal configured idle services are scoped.
    blockers.extend(_generation_release_blockers(idle_gpus or None))
    return blockers


def _generation_activity_evidence() -> list[str]:
    """Return live signs that a generation job still owns the GPUs.

    Unlike ``_generation_release_blockers`` this deliberately ignores the
    ``evicting``/``loading``/``draining`` flags themselves: it decides whether
    one of those flags is stale, and counting the flag as its own owner would
    make a stuck flag permanent. The evidence is global, not per GPU, because a
    dual-GPU job holds ``evicting`` on a GPU that runs none of its workers.
    """
    evidence: list[str] = []
    in_flight = sum(
        int(getattr(state, "worker_in_flight", 0) or 0)
        for state in _get_all_gpu_states().values()
    )
    if in_flight > 0:
        evidence.append(f"worker_in_flight:{in_flight}")
    admissions = _comfyui_admission_in_flight()
    if admissions > 0:
        evidence.append(f"comfyui_admission_in_flight:{admissions}")
    sched = globals().get("scheduler")
    if sched is not None:
        if bool(getattr(sched, "_swapping", False)):
            evidence.append("scheduler_swapping")
        if bool(getattr(sched, "_restoring", False)):
            evidence.append("scheduler_restoring")
        queues = getattr(sched, "_gpu_queues", None)
        if isinstance(queues, dict) and any(
            getattr(job, "status", None) in ("queued", "running")
            for jobs in queues.values()
            for job in jobs
        ):
            evidence.append("scheduler_jobs_active")
    return evidence


def _reap_stale_evicting_flags(now: float | None = None) -> list[str]:
    """Clear per-GPU ``evicting`` flags that no owner holds and that outlived the bound.

    ``evicting`` is legitimately held for a whole generation job, so age alone
    never clears it: any live owner (see ``_generation_activity_evidence``) or
    transition keeps it, and the ownerless clock starts at the last sign of
    activity. A stuck flag is expensive: the idle-restore loop and the idle
    bundle auto-evict both skip every GPU while any ``evicting`` flag is set, so
    one stale flag stops LLM restoration fleet-wide. Only the flag is cleared;
    ``_llm_evicted`` is left alone so the normal idle restore then runs.
    Returns the GPU ids whose flag was cleared.
    """
    now = time.time() if now is None else float(now)
    states = dict(_get_all_gpu_states())
    if not any(bool(getattr(state, "evicting", False)) for state in states.values()):
        return []
    evidence = _generation_activity_evidence()
    transitioning = any(
        bool(getattr(state, "loading", False)) or bool(getattr(state, "draining", False))
        for state in states.values()
    )
    cleared: list[str] = []
    for gpu_id, state in states.items():
        if not bool(getattr(state, "evicting", False)):
            continue
        if float(getattr(state, "evicting_since", 0.0) or 0.0) <= 0.0:
            # Set by a path that never stamped it: start its clock now so the
            # flag is bounded rather than immortal.
            state.evicting_since = now
            continue
        decision = evicting_decision(
            evicting=True,
            evicting_since=state.evicting_since,
            last_activity_at=float(getattr(state, "last_activity_at", 0.0) or 0.0),
            now=now,
            worker_in_flight=int(getattr(state, "worker_in_flight", 0) or 0),
            pending_requests=int(getattr(state, "pending_requests", 0) or 0),
            loading=bool(getattr(state, "loading", False)),
            draining=bool(getattr(state, "draining", False)),
            transition_active=transitioning,
            generation_blockers=evidence,
            stale_after_s=EVICTING_STALE_AFTER_S,
        )
        if not decision.stale:
            continue
        logger.warning(
            "[evicting-watchdog] %s: clearing stale evicting flag (%s, bound=%.0fs)",
            gpu_id, decision.reason, EVICTING_STALE_AFTER_S,
        )
        state.set_evicting(False, source="stale_evicting_watchdog")
        _queue_recovery_stats["stale_evicting_cleared"] += 1
        cleared.append(gpu_id)
    return cleared


def _restore_after_gpu_work_blockers() -> list[str]:
    """Authoritative fences that defer destructive idle-service restoration."""
    blockers = _generation_release_blockers()
    # A ComfyUI handoff lease is an additional terminal-ownership fence for
    # that backend only.  The generic helper above remains the source of truth
    # for all backend types and linked GPU reservations.
    admission_in_flight = _comfyui_admission_in_flight()
    if admission_in_flight:
        blockers.append(f"comfyui_admission_in_flight:{admission_in_flight}")
    return blockers


_IDLE_TTL_MIN_S = 5.0
_IDLE_TTL_MAX_S = 3600.0


def _bundle_idle_ttl_seconds(bundle: dict, scheduling: dict, default: float) -> float:
    """Bounded per-bundle idle-hold TTL (bundle key, then scheduling key, then default)."""
    for raw in (
        (bundle or {}).get("idle_ttl_seconds"),
        (scheduling or {}).get("generation_idle_ttl_seconds"),
    ):
        if raw is None:
            continue
        try:
            value = float(raw)
        except (TypeError, ValueError):
            continue
        if value > 0:
            return min(max(value, _IDLE_TTL_MIN_S), _IDLE_TTL_MAX_S)
    return default


def _auto_evict_bundle_blockers(
    bundle_name: str, bundles: dict | None = None
) -> list[str]:
    """Return lifecycle blockers while excluding the eviction candidate.

    A loaded non-idle bundle is normally a restore blocker. During that same
    bundle's auto-eviction decision it cannot block itself; only unrelated
    residents, transitions, active workers, and admission leases may defer the
    unload. Linked reservation-only roles are part of the same candidate.
    """
    bundles = bundles or _resolve_bundles()
    ignored = {bundle_name, *_get_linked_bundles(bundle_name, bundles=bundles)}
    # Scope to the candidate's own GPUs: a bundle resident on another GPU
    # (e.g. the second small-LLM serve) must not pin this one forever.
    blockers = _generation_release_blockers(
        _bundle_physical_gpu_set(bundle_name, bundles=bundles) or None,
        ignore_loaded_bundles=ignored,
    )
    admission_in_flight = _comfyui_admission_in_flight()
    if admission_in_flight:
        blockers.append(f"comfyui_admission_in_flight:{admission_in_flight}")
    return blockers


# A tracker record left "in_flight" by a crashed worker must not pin a bundle
# forever, so only records started within this window veto idle eviction.
_EVICT_TRACKER_IN_FLIGHT_MAX_AGE_S = 1800.0


def _bundle_tracker_in_flight_jobs(
    bundle_name: str,
    bundles: dict | None = None,
    *,
    max_age_s: float = _EVICT_TRACKER_IN_FLIGHT_MAX_AGE_S,
) -> list[str]:
    """Return ids of JobTracker jobs still ``in_flight`` on a bundle's services.

    This is the durable twin of ``worker_in_flight``: it reads the job record,
    so it also covers a job parked in the readiness gate or re-delivered after
    the in-memory counter was lost. The veto clears by itself once the job
    reaches a terminal state (completed/failed/cancelled, including the
    ``readiness_gate_timeout`` failure), because the status is read live.
    Linked bundles are part of the same candidate. Raises on tracker errors so
    the caller can fail closed.
    """
    if job_tracker is None:
        return []
    from datetime import datetime, timezone

    bundles = bundles or _resolve_bundles()
    names = [bundle_name, *_get_linked_bundles(bundle_name, bundles=bundles)]
    services: set[str] = set()
    for name in names:
        services.update(str(s) for s in (bundles.get(name) or {}).get("services", []))
    now = datetime.now(timezone.utc)
    active: list[str] = []
    for svc_name in sorted(services):
        for job in job_tracker.get_jobs_by_status(svc_name, "in_flight") or []:
            started = str(job.get("started_at") or "")
            try:
                _st = datetime.fromisoformat(started.replace("Z", "+00:00"))
                if _st.tzinfo is None:
                    _st = _st.replace(tzinfo=timezone.utc)
                age = (now - _st).total_seconds()
            except (ValueError, TypeError):
                age = 0.0  # unknown start time: treat as fresh (fail closed)
            if age <= max_age_s:
                active.append(str(job.get("job_id") or job.get("id") or svc_name))
    return active


def _normalize_readiness_required_fields(value) -> tuple[str, ...]:
    """Return a stable tuple of required readiness-payload field names.

    Accepts ``None``, a sequence of strings, or a single string. Empty
    strings are dropped. The empty tuple means "no fields required" —
    the caller must then decide whether to fall back to legacy HTTP-200
    semantics or to fail closed. This helper only normalises shape; the
    semantics live in :func:`_evaluate_readiness_payload`.
    """
    if value is None:
        return ()
    if isinstance(value, str):
        candidates = [value]
    else:
        try:
            candidates = list(value)
        except TypeError:
            return ()
    out: list[str] = []
    for name in candidates:
        if not isinstance(name, str):
            continue
        name = name.strip()
        if name and name not in out:
            out.append(name)
    return tuple(out)


def _readiness_payload_lookup(payload, field_path: str) -> tuple[bool, object]:
    """Resolve a readiness field from a JSON object without flattening it.

    A literal top-level key takes precedence for backward compatibility.
    Otherwise ``.`` separates object keys, so a backend may expose a stable
    envelope such as ``{"data": {"models_initialized": true}}`` and use
    ``data.models_initialized`` in its readiness contract.
    """
    if not isinstance(payload, dict) or not isinstance(field_path, str):
        return False, None
    if field_path in payload:
        return True, payload[field_path]
    current = payload
    for component in field_path.split("."):
        if not component or not isinstance(current, dict) or component not in current:
            return False, None
        current = current[component]
    return True, current


def _evaluate_readiness_payload(
    *,
    status: int,
    payload,
    required_fields,
    service_name: str,
    required_value_fields=None,
) -> tuple[bool, str]:
    """Evaluate HTTP status plus configured presence and exact-value contracts."""
    try:
        status_code = int(status or 0)
    except (TypeError, ValueError):
        status_code = 0
    if status_code != 200:
        return False, f"readiness: status {status_code} (expected 200)"

    fields = _normalize_readiness_required_fields(required_fields)
    value_fields = required_value_fields if isinstance(required_value_fields, dict) else {}
    if not fields and not value_fields:
        return True, "readiness: HTTP 200 (no required fields)"
    if not isinstance(payload, dict):
        return False, "readiness: payload not a JSON object"

    missing = [name for name in fields if not _readiness_payload_lookup(payload, name)[0]]
    if missing:
        return False, f"readiness: missing required field(s) {missing} for service '{service_name}'"

    mismatched = {}
    for name, expected in value_fields.items():
        present, observed = _readiness_payload_lookup(payload, name)
        if not present or observed != expected:
            mismatched[name] = {"expected": expected, "observed": observed if present else None}
    if mismatched:
        return False, f"readiness: required value mismatch(es) {mismatched} for service '{service_name}'"

    return True, f"readiness: configured fields satisfied for service '{service_name}'"


def _bundle_commit_preconditions(
    *,
    systemd_running: bool,
    health_http_200: bool,
    worker_pool_ready: bool,
    gpu_resident: bool,
    worker_in_flight: int,
    transition_active: bool,
    allow_worker_in_flight: bool = False,
) -> tuple[bool, list[str]]:
    """Evaluate authoritative prerequisites for committing bundle ownership."""
    reasons: list[str] = []
    if not systemd_running:
        reasons.append("systemd_running")
    if not health_http_200:
        reasons.append("health_http_200")
    if not worker_pool_ready:
        reasons.append("worker_pool_ready")
    if not gpu_resident:
        reasons.append("gpu_resident")
    if int(worker_in_flight or 0) > 0 and not allow_worker_in_flight:
        reasons.append("worker_in_flight")
    if transition_active:
        reasons.append("transition_active")
    return not reasons, reasons


