class _TargetStateUnreadable(Exception):
    """Raised when a target GPU's state cannot be inspected.

    The evaluator catches this and converts it into a non-dispatch
    action/reason — the dispatcher's authoritative atomic path stays the
    only place where eviction actually happens, and it must never run on
    state we cannot see.
    """

    def __init__(self, group: str, gpu_id: str):
        super().__init__(f"target state unreadable for group {group!r} gpu {gpu_id!r}")
        self.group = group
        self.gpu_id = gpu_id


