def _resolve_acestep_service(service_name: str = "acestep") -> dict:
    """Resolve one configured ACE-Step backend fail-closed per job."""
    services = (_load_services_config() or {}).get("services", {}) or {}
    service = services.get(service_name)
    if not isinstance(service, dict) or service.get("type") != "generation_backend":
        raise ValueError(f"Unknown ACE-Step service: {service_name}")
    if not service.get("enabled", True):
        raise ValueError(f"ACE-Step service is disabled: {service_name}")
    port = service.get("port")
    endpoint = str(service.get("endpoint") or (f"http://127.0.0.1:{port}" if port else ""))
    if not endpoint:
        raise ValueError(f"ACE-Step service has no endpoint/port: {service_name}")
    audio_dir = str(service.get("audio_dir") or "")
    if not audio_dir:
        if service_name == "acestep":
            audio_dir = str(
                Path(
                    os.environ.get("GPU_MANAGER_ACESTEP_ROOT")
                    or (PROJECT_ROOT.parent / "ACE-Step-1.5")
                )
                / ".cache/acestep/tmp/api_audio"
            )
        else:
            raise ValueError(f"ACE-Step service has no audio_dir: {service_name}")
    return {
        "service_name": service_name,
        "endpoint": endpoint.rstrip("/"),
        "audio_dir": audio_dir,
        "bundle_name": service.get("bundle"),
    }


# ── Phase 5.2.69: Orphan reaper ──────────────────────────────────────
# Background sweep that detects VRAM-holding processes gpu-manager did not
# start (PPID=1 orphans from rapid LoadBundle restarts that systemd didn't
# reap, manually-spawned python/llama-server, etc.) and either kills them
# or logs them. Runs from the scheduler loop on a fixed cadence.
# See PHASE5268/PHASE5.2.69_OUTCOME.md for the design rationale and the
# 2026-06-28 incident (orphaned ComfyUI python PID 2547085, 2 GB VRAM).
def _env_bool(name: str, default: bool) -> bool:
    """Parse a boolean environment switch, falling back safely on bad input."""
    raw = os.getenv(name)
    if raw is None:
        return default
    value = raw.strip().lower()
    if value in {"1", "true", "yes", "on"}:
        return True
    if value in {"0", "false", "no", "off"}:
        return False
    return default


def _env_float_min(name: str, default: float, minimum: float) -> float:
    """Parse a finite environment float and enforce a conservative floor."""
    raw = os.getenv(name)
    if raw is None:
        return max(float(default), float(minimum))
    try:
        value = float(raw.strip())
    except (TypeError, ValueError):
        value = float(default)
    if not math.isfinite(value):
        value = float(default)
    return max(value, float(minimum))


ORPHAN_REAPER_INTERVAL_S = 30.0       # seconds between reaper scans
ORPHAN_REAPER_GRACE_S = 60.0          # SIGTERM → SIGKILL grace window
ORPHAN_REAPER_VRAM_THRESHOLD_MB = 100 # ignore tenants below this VRAM
ORPHAN_REAPER_ENABLED = _env_bool("ORPHAN_REAPER_ENABLED", True)
GPU_PROBE_STARTUP_GRACE_S = _env_float_min(
    "GPU_PROBE_STARTUP_GRACE_S", 60.0, 60.0
)
ORPHAN_REAPER_STARTUP_GRACE_S = max(
    GPU_PROBE_STARTUP_GRACE_S,
    _env_float_min("ORPHAN_REAPER_STARTUP_GRACE_S", 60.0, 60.0),
)
# Conservative: only kill processes whose name matches known VRAM-holding
# backends. Prevents the reaper from touching arbitrary desktop processes
# (Xorg, kwin, plasmashell, etc.) even if they appear to be orphans.
ORPHAN_REAPER_TARGET_NAMES = (
    "python",        # ComfyUI / sd-server / sd-webui
    "python3",
    "llama-server",  # llama.cpp server
    "llama-cli",
    "koboldcpp",
    "ollama",
    "vllm",
    "sglang",
)


def _orphan_reaper_status(*, now: float | None = None) -> dict[str, Any]:
    """Return explicit orphan-reaper state without treating maintenance as healthy."""
    current = time.time() if now is None else float(now)
    state: dict[str, Any] = {
        "enabled": bool(ORPHAN_REAPER_ENABLED),
        "interval_s": ORPHAN_REAPER_INTERVAL_S,
        "grace_s": ORPHAN_REAPER_GRACE_S,
        "vram_threshold_mib": ORPHAN_REAPER_VRAM_THRESHOLD_MB,
        "target_names": list(ORPHAN_REAPER_TARGET_NAMES),
        "state": "disabled",
        "reason": "configuration_disabled",
        "last_tick_age_s": None,
        "last_tick_ts": None,
        "expected_pids": [],
        "terminated_pids": {},
    }
    if not ORPHAN_REAPER_ENABLED:
        return state

    manager = scheduler
    last_tick = float(getattr(manager, "_last_orphan_reaper_at", 0.0) or 0.0)
    state["last_tick_ts"] = last_tick or None
    state["last_tick_age_s"] = current - last_tick if last_tick > 0 else None
    if manager is not None:
        state["expected_pids"] = sorted(
            int(pid) for pid in (getattr(manager, "_expected_pids", set()) or set())
        )
        state["terminated_pids"] = {
            int(pid): float(ts)
            for pid, ts in (getattr(manager, "_terminated_pids", {}) or {}).items()
        }

    config = _services_config if isinstance(_services_config, Mapping) else {}
    scheduling = config.get("scheduling", {}) or {}
    if _maintenance_mode_enabled(scheduling):
        state.update(state="paused", reason="maintenance_mode")
    elif manager is None or getattr(manager, "_running", False) is not True:
        # the reaper ticks inside the legacy scheduler loop; with the durable
        # queue owner that loop is fenced, so "off" is by design, not a fault
        durable = _queue_owner_mode(scheduling) == "durable"
        state.update(state="off" if durable else "paused",
                     reason="durable_queue_owner" if durable else "scheduler_not_running")
    elif (
        state["last_tick_age_s"] is None
        or state["last_tick_age_s"] > max(ORPHAN_REAPER_INTERVAL_S * 2, 60.0)
    ):
        state.update(state="paused", reason="stale_tick")
    else:
        state.update(state="running", reason="fresh_tick")
    return state


