# ── OOM health section (shared by /health and the WebSocket full-state) ──
# /health and the websocket full-state payload must surface the same fields
# so dashboards don't need two decoders. The helper below is the single
# source of truth — callers (handle_health, _websocket_handler) just plug
# the result into their payload.
#
# Scope/retention/cache-freshness contract:
#   * process_events.* — sum of per-GpuBundleState counters that live in
#     process memory and are reset on restart. These are "events observed
#     by THIS process since it started".
#   * dead_letter_retained.* — length / metadata of the in-memory cache
#     backed by Redis zset ``oom:dead_letters``. Retention is 30 days from
#     the latest mutation (TTL refreshed on every add) and entries are
#     capped at _OOM_DEAD_LETTER_CAP (100). The cache is NOT reset on
#     process restart if Redis is reachable.
#   * cache_age_seconds / cache_fresh — explicit staleness signal for the
#     dead-letter cache, computed from _dead_letter_cache_refresh_ts that
#     the watchdog stamps on each successful refresh. /health does NOT
#     issue a synchronous Redis call just to compute this.
_OOM_CACHE_FRESH_WINDOW_S = 60.0   # within this window, cache_fresh=True


def _oom_health_section(
    gpu_states_map: dict | None = None,
    events_last_hour: list | None = None,
    watchdog_heartbeat_ts: float | None = None,
    now: float | None = None,
) -> dict:
    """Build the OOM section for /health and the websocket full-state payload.

    The function is pure-ish: it reads module-level state but never issues a
    blocking I/O call. The caller supplies ``now`` (default ``time.time()``)
    so tests can pin the wall clock and assert cache_age_seconds.
    """
    if gpu_states_map is None:
        gpu_states_map = globals().get("_gpu_states", {}) or {}
    if events_last_hour is None:
        events_last_hour = []
    if watchdog_heartbeat_ts is None:
        watchdog_heartbeat_ts = float(
            globals().get("_last_oom_heartbeat_ts", 0.0) or 0.0
        )
    if now is None:
        now = time.time()
    gpu_states_map = gpu_states_map or {}

    # ── process_events — restart-reset, in-memory only ────────────────
    process_events = {
        "scope": "process_memory",
        "resets_on_restart": True,
        "total_events": sum(int(getattr(bs, "oom_event_count", 0) or 0)
                            for bs in gpu_states_map.values()),
        "total_recoveries": sum(int(getattr(bs, "oom_recovery_count", 0) or 0)
                                for bs in gpu_states_map.values()),
        "total_permanent_failures": sum(int(getattr(bs, "oom_permanent_failure_count", 0) or 0)
                                        for bs in gpu_states_map.values()),
        "active_recoveries": {
            gpu_id: getattr(bs, "oom_state", "idle")
            for gpu_id, bs in gpu_states_map.items()
            if getattr(bs, "oom_state", "idle") not in ("idle", "restored")
        },
        "events_last_hour": events_last_hour,
        "last_event": events_last_hour[-1] if events_last_hour else None,
    }

    # ── dead_letter_retained — Redis zset (30d TTL, cap 100) ──────────
    dead_letter_cache = list(globals().get("_dead_letter_cache", []) or [])
    refresh_ts = float(
        globals().get("_dead_letter_cache_refresh_ts", 0.0) or 0.0
    )
    if refresh_ts > 0:
        cache_age_seconds = max(0.0, now - refresh_ts)
        cache_refresh_ts = refresh_ts
        cache_fresh = cache_age_seconds < _OOM_CACHE_FRESH_WINDOW_S
    else:
        cache_age_seconds = None
        cache_refresh_ts = None
        cache_fresh = False

    keyed_identities = [
        (str(row.get("job_id")), str(row.get("gpu_id", "")))
        for row in dead_letter_cache
        if isinstance(row, dict) and str(row.get("job_id", "")).strip()
    ]
    unique_identities = set(keyed_identities)
    unkeyed_count = sum(
        1 for row in dead_letter_cache
        if not isinstance(row, dict) or not str(row.get("job_id", "")).strip()
    )
    entry_timestamps = [
        float(row["ts"])
        for row in dead_letter_cache
        if isinstance(row, dict)
        and isinstance(row.get("ts"), (int, float))
        and not isinstance(row.get("ts"), bool)
    ]
    dead_letter_retained = {
        "scope": "redis_zset",
        "redis_key": OOM_REDIS_DEAD_LETTER,
        "resets_on_restart": False,
        "count": len(dead_letter_cache),
        "raw_entry_count": len(dead_letter_cache),
        "unique_job_count": len(unique_identities),
        "duplicate_entry_count": max(0, len(keyed_identities) - len(unique_identities)),
        "unkeyed_entry_count": unkeyed_count,
        "oldest_entry_ts": min(entry_timestamps) if entry_timestamps else None,
        "newest_entry_ts": max(entry_timestamps) if entry_timestamps else None,
        "historical_archive": True,
        "affects_current_health": False,
        # Legacy alias preserved for dashboards that already chart it.
        "dead_letter_count": len(dead_letter_cache),
        "cap": _OOM_DEAD_LETTER_CAP,
        "retention_seconds": _OOM_DEAD_LETTER_TTL_S,
        "cache_refresh_ts": cache_refresh_ts,
        "cache_age_seconds": cache_age_seconds,
        "cache_fresh": cache_fresh,
    }

    # ── watchdog health — read off the module-level heartbeat ts ──────
    if watchdog_heartbeat_ts > 0:
        wdt_age_s = max(0.0, now - watchdog_heartbeat_ts)
        wdt_fresh = wdt_age_s < 30
    else:
        wdt_age_s = None
        wdt_fresh = False
    watchdog = {
        "heartbeat_ts": watchdog_heartbeat_ts,
        "heartbeat_age_s": wdt_age_s,
        "heartbeat_fresh": wdt_fresh,
        "inflight": dict(globals().get("_oom_recovery_in_progress", {}) or {}),
    }

    return {
        "process_events": process_events,
        "dead_letter_retained": dead_letter_retained,
        "watchdog": watchdog,
        "current_oom_active": bool(
            process_events["active_recoveries"] or process_events["events_last_hour"]
        ),
        # Legacy top-level keys — keep so existing dashboards do not break.
        "total_events": process_events["total_events"],
        "total_recoveries": process_events["total_recoveries"],
        "total_permanent_failures": process_events["total_permanent_failures"],
        "active_recoveries": process_events["active_recoveries"],
        "dead_letter_count": dead_letter_retained["count"],
        "last_event": process_events["last_event"],
        "events_last_hour": events_last_hour,
        "watchdog_heartbeat_age_s": wdt_age_s,
        "watchdog_heartbeat_fresh": wdt_fresh,
        "watchdog_heartbeat_ts": watchdog_heartbeat_ts,
        "watchdog_inflight": watchdog["inflight"],
    }


# ── Phase 5: Rate-limit helper for oom_recovery_force_reset ─────────
def _check_force_reset_rate_limit(gpu_id: str) -> tuple[bool, float]:
    """Check whether oom_recovery_force_reset may run for `gpu_id` now.

    Per adversarial #26: at most one call per OOM_FORCE_RESET_MIN_INTERVAL_S
    per GPU. Returns (allowed, retry_after_seconds).
    """
    now = time.time()
    last_ts = _oom_force_reset_last_call_ts.get(gpu_id, 0.0)
    elapsed = now - last_ts
    if elapsed < OOM_FORCE_RESET_MIN_INTERVAL_S:
        return False, OOM_FORCE_RESET_MIN_INTERVAL_S - elapsed
    return True, 0.0


def _handle_oom_event(
    gpu_id: str,
    service_name: str,
    job_id: str = "",
    detection_source: str = "unknown",
    reason: str = "",
    details: str = "",
) -> dict:
    """Central OOM event handler. Called from worker error paths and watchdog.

    Behaviour:
    - Looks up GpuBundleState via _gpu_states[gpu_id]
    - Calls bundle_state.record_oom_event(reason=reason, job_id=job_id)
    - Sets oom_state = 'detected' (the recovery pipeline will pick this up)
    - Appends the event to _recent_oom_events_log for /health surfacing
    - Returns the OOM event dict for logging/Redis persistence

    IMPORTANT: This is Phase 2 (DETECTION only). It records the event and sets
    state. Phase 3 will add the recovery pipeline that transitions through
    detected -> draining -> verifying -> recovering -> restored. For now, the
    watchdog will pick up 'detected' state and log a warning.
    """
    bundle_state = _gpu_states.get(gpu_id)
    if bundle_state is None:
        # Unknown GPU — try the primary so we still surface the event
        primary = globals().get("_vram_cache", {}) or {}
        logger.warning(
            f"[oom-detect] OOM event for unknown GPU {gpu_id}: {reason[:160]}"
        )
        # Still record in the ring buffer so /health sees it
        _recent_oom_events_log.append({
            "gpu_id": gpu_id, "ts": time.time(), "reason": reason,
            "service": service_name, "job_id": job_id, "source": detection_source,
        })
        return {"recorded": False, "reason": "unknown_gpu", "gpu_id": gpu_id}

    bundle_state.record_oom_event(reason=reason, job_id=job_id)
    bundle_state.set_oom_state("detected", source=f"_handle_oom_event({detection_source})", reason=reason)
    _recent_oom_events_log.append({
        "gpu_id": gpu_id, "ts": time.time(), "reason": reason,
        "service": service_name, "job_id": job_id, "source": detection_source,
    })
    logger.warning(
        f"[oom-detect] OOM on {gpu_id} (service={service_name}, job={job_id}): "
        f"source={detection_source} reason={reason[:200]!r} details={details[:200]}"
    )
    return {
        "recorded": True,
        "gpu_id": gpu_id,
        "service_name": service_name,
        "job_id": job_id,
        "detection_source": detection_source,
        "reason": reason,
        "details": details[:500],
        "ts": time.time(),
    }


# ── Phase 3: OOM Recovery Pipeline ─────────────────────────────────
#
# The detection half (Phase 2) records OOMs and sets oom_state='detected'.
# The recovery half (THIS phase) consumes that 'detected' state and walks
# the GPU bundle state through the state machine defined in §A.2 of
# OOM_RECOVERY_STATE_MACHINE_DESIGN.md:
#
#     detected -> draining -> verifying -> recovering -> restored
#                                    \-> permanent_failed (after 3 in 5min)
#
# Adversarial-check fixes applied here (every one is annotated inline):
#   #1 Corrected atomic eviction: allow if other GPU has only idle baseline
#      displaced (e.g. sulphur-2 displacing LLM-Secondary)
#   #2 First-OOM auto-retry with reduced params
#      (height*0.85, width*0.85, batch//4 via OOM_RETRY_DIM_SCALE /
#      OOM_RETRY_BATCH_DIVISOR)
#   #3 Restore BOTH GPUs' idle LLMs (not single restore_llm)
#   #4 OOM_LOCK (asyncio.Lock) for concurrent protection
#   #5 Reentrancy lock on _force_recover_failed_service
#   #6 Cancel prompt with 10s timeout (OOM_CANCEL_PROMPT_TIMEOUT_S)
#   #7 Snapshot pre-OOM idle map for correct restoration
#   #8 Idempotent state transitions so watchdog-driven re-entry is safe


def _get_idle_service_for_gpu(gpu_id: str) -> str | None:
    """Return the idle LLM service name for `gpu_id`, or None.

    Reads services.json `scheduling.idle_services[gpu_id]` first, then
    falls back to `scheduling.idle_service`. Returns the service NAME
    (e.g. "LLM-Secondary"), not the systemd unit — the caller resolves the
    unit via the services config.

    Per adversarial #7: we resolve at *recovery time*, not at OOM time,
    so a snapshot reflects what was the idle baseline before the OOM
    event disturbed it. If both GPUs had generation bundles loaded and
    the user changed the idle map mid-OOM, we still restore to the
    pre-OOM snapshot.
    """
    try:
        config = _load_services_config()
    except Exception as e:
        logger.debug(f"[oom-recovery] _get_idle_service_for_gpu: _load_services_config failed: {e}")
        return None
    scheduling = config.get("scheduling", {}) or {}
    idle_services = scheduling.get("idle_services", {}) or {}
    name = idle_services.get(gpu_id) or scheduling.get("idle_service")
    services = config.get("services", {}) or {}
    service = services.get(name, {}) if name else {}
    # A global CPU idle tenant (for example Gemma CPU P2) is not a GPU
    # baseline and must never be started on both dGPUs during recovery.
    if not isinstance(service, dict) or service.get("enabled") is False:
        return None
    if service.get("gpu_id") != gpu_id:
        return None
    return name


def _check_both_gpus_safe_to_recover(failed_gpu_id: str, timeout_s: float = 30.0) -> dict:
    """Atomic multi-GPU eviction check.

    Per adversarial #1 (CORRECTED): allow recovery if the OTHER GPU has
    only its idle baseline displaced by a generation bundle. The OLD
    check refused recovery if the other GPU had ANY loaded bundle — this
    caused a deadlock where a sulphur-diffusion job on gpu_primary (linked
    to sulphur-encoder on gpu_secondary) would OOM and the recovery would refuse
    to evict because gpu_secondary still had LLM-Secondary displaced. The corrected
    logic only BLOCKS when the other GPU is mid-loading the idle
    baseline OR mid-eviction (i.e. actively transitioning, not stably
    occupied).

    Returns a dict:
        {
          "safe": bool,
          "reason": str,
          "other_state": str|None,  # "loading" | "evicting" | "draining" | None
          "other_loaded": list,    # bundles loaded on the other GPU
          "idle_for_other": str|None,  # idle service name we expect there
        }

    This function does NOT do any waiting — it returns synchronously. The
    caller (the pipeline) is responsible for sleeping / polling if the
    other GPU is transitioning.
    """
    if failed_gpu_id == "gpu_primary":
        other_gpu_id = "gpu_secondary"
    elif failed_gpu_id == "gpu_secondary":
        other_gpu_id = "gpu_primary"
    else:
        # Unknown GPU — only one GPU or misnamed; allow recovery
        return {"safe": True, "reason": "unknown_gpu_id", "other_state": None}

    other_bs = _gpu_states.get(other_gpu_id)
    if other_bs is None:
        # Unknown other GPU — log and allow (caller will discover at restart)
        return {
            "safe": True,
            "reason": "other_gpu_unknown",
            "other_state": None,
            "idle_for_other": _get_idle_service_for_gpu(other_gpu_id),
        }

    # If other GPU is mid-loading the idle baseline, BLOCK.
    # mid-loading means a restore_llm / _load_bundle is in progress on it.
    if other_bs.loading:
        return {
            "safe": False,
            "reason": f"other_gpu {other_gpu_id} is mid-loading idle baseline",
            "other_state": "loading",
            "other_loaded": list(other_bs.loaded_bundles),
            "idle_for_other": _get_idle_service_for_gpu(other_gpu_id),
        }

    # If other GPU is evicting or draining, BLOCK.
    if other_bs.evicting or other_bs.draining:
        return {
            "safe": False,
            "reason": f"other_gpu {other_gpu_id} is mid-eviction (evicting={other_bs.evicting}, draining={other_bs.draining})",
            "other_state": "evicting" if other_bs.evicting else "draining",
            "other_loaded": list(other_bs.loaded_bundles),
            "idle_for_other": _get_idle_service_for_gpu(other_gpu_id),
        }

    # Otherwise ALLOW — even if other GPU has a bundle loaded (e.g. sulphur-2
    # displacing LLM-Secondary on the gpu_secondary). We will only evict the FAILED
    # GPU's bundles, not the other's.
    return {
        "safe": True,
        "reason": "other_gpu_idle_or_displaced_baseline",
        "other_state": None,
        "other_loaded": list(other_bs.loaded_bundles),
        "idle_for_other": _get_idle_service_for_gpu(other_gpu_id),
    }


def _snapshot_pre_oom_state() -> dict:
    """Capture per-GPU idle baseline expectations before OOM recovery runs.

    Per adversarial #7: returning a snapshot (not reading services.json
    at restore time) ensures we restore to the SAME state we had before
    the OOM disturbed things. If a generation bundle displaced the
    idle LLM on a GPU, we record the displaced idle's service NAME so
    the restore step can put the idle LLM back even if the live
    services.json has changed.

    Returns: {gpu_id: idle_service_name_or_None}
        - None means the GPU was at idle baseline (nothing to restore)
        - "LLM-Secondary" means LLM-Secondary was the idle LLM and we should
          restart it after recovery.
    """
    snapshot: dict[str, str | None] = {}
    for gpu_id, bs in _get_all_gpu_states().items():
        # The target is configuration intent, not a stale loaded GPU Gemma
        # bundle from before the current CPU-only idle policy was applied.
        snapshot[gpu_id] = _get_idle_service_for_gpu(gpu_id)
        _ = bs.loaded_bundles
    return snapshot


async def _free_comfyui_models_for_oom(service_name: str, timeout_s: float = 10.0) -> dict:
    """Unload ComfyUI model residency in-process; never stop or restart its unit."""
    config = _load_services_config()
    services = config.get("services", {}) or {}
    comfy_cfg = services.get("comfyui", {})
    if not isinstance(comfy_cfg, dict) or not comfy_cfg.get("enabled", True):
        return {"ok": False, "reason": "comfyui_not_configured_or_disabled"}
    service_cfg = services.get(service_name, {})
    if service_name != "comfyui" and not (
        isinstance(service_cfg, dict)
        and service_cfg.get("backend") == "comfyui"
    ):
        return {"ok": False, "reason": "unsupported_or_unknown_backend_owner"}

    base_url = str(comfy_cfg.get("base_url") or comfy_cfg.get("url") or COMFYUI_URL).rstrip("/")
    if base_url.endswith("/prompt"):
        base_url = base_url[:-len("/prompt")]
    import aiohttp

    timeout = ClientTimeout(total=max(0.1, min(float(timeout_s), 15.0)))
    client = globals().get("session")
    owns_client = client is None or bool(getattr(client, "closed", False))
    if owns_client:
        client = aiohttp.ClientSession(timeout=timeout)
    if client is None:
        return {"ok": False, "reason": "http_session_unavailable"}
    try:
        async with client.post(
            f"{base_url}/free",
            json={"unload_models": True, "free_memory": True},
            timeout=timeout,
        ) as response:
            if not 200 <= response.status < 300:
                return {
                    "ok": False,
                    "reason": "comfyui_free_http_error",
                    "status": int(response.status),
                }
            await response.read()
        return {"ok": True, "reason": "comfyui_models_unloaded_in_process"}
    except asyncio.TimeoutError:
        return {"ok": False, "reason": "comfyui_free_timeout"}
    except Exception as exc:
        logger.warning("[oom-recovery] ComfyUI /free failed: %s", type(exc).__name__)
        return {"ok": False, "reason": "comfyui_free_error", "error": type(exc).__name__}
    finally:
        if owns_client:
            await client.close()


async def _restore_both_idle_llms(snapshot: dict | None = None) -> dict:
    """Restore each GPU's configured idle LLM after OOM recovery.

    Per adversarial #3: do NOT use single restore_llm (which targets one
    GPU). This iterates per GPU and starts the idle service via systemd.

    Per adversarial #7: uses `snapshot` if provided to know what to
    restore. If snapshot is None, reads services.json idle map (current
    config, may differ from pre-OOM state — caller decides which).

    Returns: {gpu_id: restore_status_dict}
        Each status has keys: restored (bool), unit (str|None),
        reason (str|None), error (str|None).

    Phase 6 (OOM fix 2): guard ``systemctl start`` with an ``is-active``
    probe so we don't re-issue ``start`` on a unit that's already running
    (which can confuse systemd, race with the unit's own restart, and
    adds latency in the OOM recovery critical path). If the unit is
    already active we probe /health and treat it as restored when
    healthy; otherwise we issue ``try-restart``.
    """
    results: dict[str, dict] = {}
    planned_gpus: set[str] = set()
    if not snapshot:
        snapshot = {}
        _plan = _IDLE_PLANNER.plan(_services_config or {}, time.time())
        # Every GPU with a configured idle service is a restore target even if
        # no code path has materialized its state yet (e.g. after a restart);
        # iterating only the already-created states silently skipped a GPU.
        try:
            _known_gpus = set(_get_all_gpu_states())
        except Exception:
            _known_gpus = set(_gpu_states)
        _configured_idle = ((_services_config or {}).get("scheduling") or {}).get("idle_services") or {}
        _known_gpus.update(str(g) for g in _configured_idle)
        for gpu_id in sorted(_known_gpus):
            entry = _plan.get(gpu_id)
            if entry is None:
                snapshot[gpu_id] = _get_idle_service_for_gpu(gpu_id)
                continue
            planned_gpus.add(gpu_id)
            if not entry["service"]:
                results[gpu_id] = {"restored": False, "reason": "idle_target_unavailable"}
            elif not entry["ready"]:
                results[gpu_id] = {"restored": False, "reason": "idle_target_backoff"}
            else:
                snapshot[gpu_id] = entry["service"]

    for gpu_id, idle_service_name in snapshot.items():
        if not idle_service_name:
            results[gpu_id] = {
                "restored": True,
                "reason": "configured_policy_has_no_gpu_idle_service",
            }
            continue
        try:
            services = _services_config.get("services", {}) if isinstance(_services_config, dict) else {}
            svc = services.get(idle_service_name, {}) if isinstance(services, dict) else {}
            unit = svc.get("systemd_unit") if isinstance(svc, dict) else None
            if not unit:
                results[gpu_id] = {"restored": False, "reason": "no_systemd_unit"}
                continue
            # Lifecycle Guard 2026-08-07: disabled services stay disabled.
            # A direct ``systemctl start`` here would override the operator's
            # intent and is a violation of the disabled service contract.
            if svc.get("enabled") is False:
                results[gpu_id] = {
                    "restored": True,
                    "unit": unit,
                    "reason": "configured_idle_service_disabled_by_operator",
                }
                logger.info(
                    "[oom-recovery] %s is disabled in services config; "
                    "leaving untouched on %s",
                    idle_service_name,
                    gpu_id,
                )
                continue
            # Lifecycle Guard 2026-08-07: bundle-managed idle services must
            # be admitted via the controller-owned bundle admission path,
            # never via direct systemctl. Direct start would race the
            # scheduler/bundle controller and break atomic fence guarantees.
            service_bundle = _get_bundle_for_service(idle_service_name)
            if service_bundle is not None:
                bundle_name = service_bundle.get("bundle_name")
                if vram is None or scheduler is None:
                    results[gpu_id] = {
                        "restored": False,
                        "unit": unit,
                        "reason": "controller_unavailable_for_bundle_restoration",
                    }
                    logger.error(
                        "[oom-recovery] controller unavailable; cannot restore "
                        "bundle-backed idle %s on %s (refusing direct systemctl)",
                        idle_service_name,
                        gpu_id,
                    )
                    continue
                # Admission evicts the GPU's resident bundles before loading, so
                # a baseline that is already resident and serving must not be
                # re-admitted: that would stop and reload it on every call.
                _gs_now = _gpu_states.get(gpu_id)
                _resident = {str(b).removeprefix("llm:") for b in (
                    list(getattr(_gs_now, "loaded_bundles", None) or [])
                    + [getattr(_gs_now, "loaded_bundle", None)]) if b}
                if bundle_name in _resident and await _probe_health_inline(
                    svc.get("port"), health_path=svc.get("health_path") or "/health"
                ):
                    results[gpu_id] = {
                        "restored": True,
                        "unit": unit,
                        "bundle": bundle_name,
                        "reason": "already_loaded_healthy",
                    }
                    continue
                admitted, _ = await _admit_bundle_backed_llm_service(
                    idle_service_name,
                    priority=service_bundle.get("priority", 0) or 0,
                )
                results[gpu_id] = {
                    "restored": bool(admitted),
                    "unit": unit,
                    "bundle": bundle_name,
                    "reason": (
                        "bundle_admission" if admitted
                        else "bundle_admission_failed"
                    ),
                }
                if admitted:
                    logger.info(
                        "[oom-recovery] Restored bundle-backed idle %s (%s) on %s via admission",
                        idle_service_name,
                        bundle_name,
                        gpu_id,
                    )
                else:
                    logger.warning(
                        "[oom-recovery] Bundle admission refused for %s on %s",
                        idle_service_name,
                        gpu_id,
                    )
                continue
            # Lifecycle Guard 2026-08-07: standalone (non-bundle) services
            # can only be restored directly when the controller stack is
            # available. If scheduler/vram are missing, we have no way to
            # reason about whether restoring this unit is safe — fail
            # closed rather than racing systemd in isolation.
            if vram is None or scheduler is None:
                results[gpu_id] = {
                    "restored": False,
                    "unit": unit,
                    "reason": "controller_unavailable_for_direct_restoration",
                }
                logger.error(
                    "[oom-recovery] controller unavailable; refusing direct "
                    "systemctl start for standalone idle %s on %s",
                    idle_service_name,
                    gpu_id,
                )
                continue
            # Phase 6: probe is-active before issuing start to avoid
            # re-starting a unit that is already running (which can
            # race with the unit's own restart loop and slows OOM
            # recovery). If the unit is already active, fall through to
            # a health check; healthy ⇒ treat as restored, unhealthy
            # ⇒ try-restart so systemd gets a clean restart signal.
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL,
            )
            try:
                rc_active, _ = await asyncio.wait_for(proc.communicate(), timeout=5.0)
            except asyncio.TimeoutError:
                # is-active hung — treat as inactive and try start below
                rc_active = 1
            already_active = (rc_active == 0)
            port = svc.get("port")
            health_path = svc.get("health_path") or "/health"
            if already_active:
                health_ok = await _probe_health_inline(port, health_path=health_path)
                if health_ok:
                    results[gpu_id] = {
                        "restored": True,
                        "unit": unit,
                        "rc": 0,
                        "reason": "already_active_healthy",
                    }
                    logger.info(
                        f"[oom-recovery] {unit} already active+healthy on {gpu_id}; skipping start"
                    )
                    continue
                # B6: a broker pool member is never restarted under its
                # in-flight jobs; the broker drains it on failed probes.
                if _combined_gemma_broker_owns_service(idle_service_name, svc):
                    results[gpu_id] = {"restored": False, "unit": unit,
                                       "reason": "broker_member_unhealthy_left_to_broker"}
                    continue
                # Active but unhealthy — try-restart to nudge it
                proc = await asyncio.create_subprocess_exec(
                    "systemctl", "try-restart", unit,
                    stdout=asyncio.subprocess.DEVNULL,
                    stderr=asyncio.subprocess.DEVNULL,
                )
                try:
                    rc = await asyncio.wait_for(proc.wait(), timeout=10.0)
                except asyncio.TimeoutError:
                    results[gpu_id] = {
                        "restored": False,
                        "unit": unit,
                        "reason": "systemctl_try_restart_timeout",
                    }
                    logger.warning(
                        f"[oom-recovery] systemctl try-restart {unit} timed out (>10s)"
                    )
                    continue
                results[gpu_id] = {
                    "restored": rc == 0,
                    "unit": unit,
                    "rc": rc,
                    "reason": "already_active_unhealthy_try_restart",
                }
                if rc == 0:
                    logger.info(
                        f"[oom-recovery] {unit} was active but unhealthy; try-restart ok on {gpu_id}"
                    )
                else:
                    logger.warning(
                        f"[oom-recovery] systemctl try-restart {unit} failed rc={rc}"
                    )
                continue
            # Inactive — start it (original behaviour)
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "start", unit,
                stdout=asyncio.subprocess.DEVNULL,
                stderr=asyncio.subprocess.DEVNULL,
            )
            try:
                rc = await asyncio.wait_for(proc.wait(), timeout=10.0)
            except asyncio.TimeoutError:
                results[gpu_id] = {
                    "restored": False,
                    "unit": unit,
                    "reason": "systemctl_start_timeout",
                }
                logger.warning(
                    f"[oom-recovery] systemctl start {unit} timed out (>10s)"
                )
                continue
            results[gpu_id] = {"restored": rc == 0, "unit": unit, "rc": rc}
            if rc == 0 and _combined_gemma_broker_owns_service(idle_service_name, svc):
                # B6: a started pool member serves only after the fenced rejoin
                rejoined = await _rejoin_combined_gemma_member_after_start(
                    idle_service_name, timeout=min(DRAIN_TIMEOUT, 30.0))
                results[gpu_id].update(restored=bool(rejoined), rejoined=bool(rejoined))
            if rc == 0:
                logger.info(
                    f"[oom-recovery] Restored {idle_service_name} on {gpu_id} via {unit}"
                )
            else:
                logger.warning(
                    f"[oom-recovery] systemctl start {unit} failed rc={rc}"
                )
        except Exception as e:
            results[gpu_id] = {"restored": False, "error": str(e)}
            logger.error(
                f"[oom-recovery] Failed to restore {idle_service_name} on {gpu_id}: {e}"
            )

    _now = time.time()
    for gpu_id in planned_gpus:
        if results.get(gpu_id, {}).get("reason") in {"idle_target_unavailable", "idle_target_backoff"}:
            continue
        _IDLE_PLANNER.report_result(gpu_id, bool(results.get(gpu_id, {}).get("restored")), _now)
    return results


async def _probe_health_inline(port, health_path: str = "/health", timeout: float = 2.0) -> bool:
    """Module-level liveness probe used by _restore_both_idle_llms.

    Mirrors ``WorkerSupervisor._check_health``'s HTTP-first-then-TCP
    fallback behaviour (PR4 fix). Lives at module level so the free
    function ``_restore_both_idle_llms`` can call it without needing a
    ``WorkerSupervisor`` instance. Returns True on any 2xx from the
    health_path, OR a successful raw TCP connect to the port.
    """
    if not port:
        return False
    try:
        import aiohttp  # local import — module already imports it elsewhere
        timeout_obj = aiohttp.ClientTimeout(total=timeout)
        async with aiohttp.ClientSession(timeout=timeout_obj) as _sess:
            async with _sess.get(f"http://127.0.0.1:{int(port)}{health_path}") as resp:
                if resp.status == 200:
                    return True
    except Exception:
        pass
    # Fallback: TCP connect to the port (matches LoadBundle port-ready gate)
    try:
        fut = asyncio.open_connection("127.0.0.1", int(port))
        _reader, writer = await asyncio.wait_for(fut, timeout=timeout)
        writer.close()
        try:
            await writer.wait_closed()
        except Exception:
            pass
        return True
    except Exception:
        return False


def _resolve_service_for_gpu(gpu_id: str) -> str:
    """Best-effort service name lookup for a GPU.

    Used by the watchdog to pass a service name into
    _oom_recovery_pipeline (which in turn hands it to
    _force_recover_failed_service for reentrancy-locked eviction).

    Strategy:
      1. If a bundle is loaded on the GPU, look up its first service.
      2. Otherwise return "unknown".

    Returns service NAME (not systemd unit).
    """
    bs = _gpu_states.get(gpu_id)
    if bs is None or not bs.loaded_bundles:
        # Phase 5: fall back to the OOM-implicated service name (if any).
        # This is the only signal we have when the GPU is mid-recovery
        # and the bundle is no longer loaded. Skip the literal "unknown"
        # value to avoid masking a real previous service.
        fallback = getattr(bs, "oom_last_service_name", None) if bs is not None else None
        if fallback and fallback != "unknown":
            return fallback
        return "unknown"
    bundle_name = bs.loaded_bundles[0]
    try:
        bundles = _resolve_bundles() or {}
        bundle_cfg = bundles.get(bundle_name, {}) if isinstance(bundles, dict) else {}
        svcs = bundle_cfg.get("services") or []
        if svcs:
            return svcs[0]
    except Exception as e:
        logger.debug(f"[oom-recovery] _resolve_service_for_gpu lookup failed: {e}")
    return bundle_name  # fall back to bundle name as proxy


async def _oom_recovery_pipeline(
    gpu_id: str,
    service_name: str,
    job_id: str = "",
    oom_reason: str = "",
    oom_details: str = "",
) -> dict:
    """OOM recovery state machine. Phase 3 main entry.

    Transitions GpuBundleState through:
        detected -> draining -> verifying -> recovering -> restored
    or
        detected -> permanent_failed (after 3 OOMs in 5 min, or blocked)

    Per adversarial #2: first OOM auto-retry with reduced params.
    Per adversarial #3: restores BOTH GPUs' idle LLMs.
    Per adversarial #4: protected by asyncio.Lock.
    Per adversarial #5: per-service lock on _force_recover_failed_service.
    Per adversarial #6: cancel prompt with 10s timeout.
    Per adversarial #7: snapshot pre-OOM idle map.
    Per adversarial #8: idempotent — re-entry on the same GPU is safe.

    Returns a result dict with keys: state, reason, restore_results (optional).
    """
    bs = _gpu_states.get(gpu_id)
    if bs is None:
        logger.warning(
            f"[oom-recovery] No GpuBundleState for {gpu_id}; cannot recover"
        )
        return {"state": "skipped", "reason": "unknown_gpu", "gpu_id": gpu_id}

    # Idempotency: if this GPU is already past 'detected', don't restart
    # the pipeline. The watchdog may fire repeatedly while a recovery is
    # in flight; we want exactly ONE pipeline per OOM.
    if bs.oom_state in ("recovering", "verifying", "restored", "oom_failed", "permanent_failed"):
        logger.debug(
            f"[oom-recovery] {gpu_id} already in oom_state={bs.oom_state!r}; "
            f"skipping re-entry"
        )
        return {"state": "skipped", "reason": f"already_in_{bs.oom_state}"}

    # Acquire the global OOM_LOCK so concurrent recoveries serialise.
    # Per adversarial #4. If we can't get the lock in 5s the watchdog
    # has piled up too many events; bail rather than wedge.
    lock_acquired = False
    if _oom_lock is not None:
        try:
            await asyncio.wait_for(_oom_lock.acquire(), timeout=5.0)
            lock_acquired = True
        except asyncio.TimeoutError:
            logger.warning(
                f"[oom-recovery] Lock timeout for {gpu_id}; another recovery is "
                f"in flight. Skipping."
            )
            return {"state": "skipped", "reason": "lock_timeout"}
        except Exception as e:
            bs.set_oom_state("oom_failed", source="recovery_lock_error", reason=type(e).__name__)
            logger.error("[oom-recovery] %s lock acquisition failed (%s); admission remains closed", gpu_id, type(e).__name__)
            return {"state": "oom_failed", "reason": "recovery_lock_error", "gpu_id": gpu_id}

    try:
        # Snapshot pre-OOM state for correct restoration (#7)
        pre_oom_snapshot = _snapshot_pre_oom_state()

        # Mark "in progress" so the watchdog won't re-enter while we run.
        _oom_recovery_in_progress[gpu_id] = time.time()

        # Detection already records the event before setting state=detected.
        # The watchdog may also enter this pipeline directly, so record only
        # when this job/GPU has not already passed through the detector.
        already_recorded = (
            bs.oom_state == "detected"
            and (
                not job_id
                or bs.oom_active_recovery_job_id == job_id
            )
            and bs.oom_event_count > 0
        )
        if not already_recorded:
            bs.record_oom_event(reason=oom_reason or "watchdog_detected", job_id=job_id)

        # Stage 1: DETECTED -> DRAINING
        bs.set_oom_state("draining", source="recovery_pipeline", reason=oom_reason)
        logger.info(
            f"[oom-recovery] {gpu_id}: detected -> draining "
            f"(reason={oom_reason!r}, job={job_id!r})"
        )

        # Atomic multi-GPU check (per adversarial #1 — corrected)
        check = _check_both_gpus_safe_to_recover(gpu_id)
        if not check.get("safe"):
            failure_reason = f"recovery ownership/transition check failed: {check.get('reason')}"
            bs.set_oom_state("oom_failed", source="recovery_pipeline", reason=failure_reason)
            bs.oom_permanent_failure_count += 1
            logger.error("[oom-recovery] %s: %s; admission remains closed; operator intervention required", gpu_id, failure_reason)
            if job_id:
                if job_tracker is not None:
                    job_tracker.update_status(
                        job_id, "failed", error_type="oom", oom_recovery_state="oom_failed",
                        oom_reason=oom_reason or "oom_detected", oom_recovery_error=failure_reason,
                    )
                try:
                    await _add_to_dead_letter(job_id=job_id, gpu_id=gpu_id, reason=failure_reason, last_state="oom_failed")
                except Exception as _dl_err:
                    logger.warning("[oom-recovery] OOM dead-letter write failed for %s: %s", job_id, type(_dl_err).__name__)
            return {
                "state": "oom_failed",
                "reason": failure_reason,
                "gpu_id": gpu_id,
            }

        # Cancel any in-flight prompt with 10s timeout (#6).
        # We look for a comfyui_client / comfyui_service / interrupt helper
        # in module globals. If absent, this is a no-op (e.g. ACE-Step OOM
        # where we don't have a global cancel handle).
        if job_id:
            cancel_target = (
                globals().get("comfyui_service")
                or globals().get("_comfyui_client")
                or globals().get("comfyui_client")
            )
            if cancel_target is not None and hasattr(cancel_target, "interrupt"):
                try:
                    await asyncio.wait_for(
                        cancel_target.interrupt(),
                        timeout=OOM_CANCEL_PROMPT_TIMEOUT_S,
                    )
                except asyncio.TimeoutError:
                    logger.warning(
                        f"[oom-recovery] Cancel prompt timeout for {job_id} "
                        f"(>{OOM_CANCEL_PROMPT_TIMEOUT_S}s)"
                    )
                except Exception as e:
                    logger.debug(f"[oom-recovery] Cancel prompt error: {e}")

        # Stage 2: drain the owned prompt, then ask ComfyUI to unload its
        # own model state. Unknown/non-ComfyUI owners cannot be cleaned up
        # safely here; do not stop/restart a backend or guess at a PID.
        bs.set_oom_state("verifying", source="recovery_pipeline")
        service_cfg = (_load_services_config().get("services", {}) or {}).get(service_name, {})
        comfyui_owned = service_name == "comfyui" or (
            isinstance(service_cfg, dict) and service_cfg.get("backend") == "comfyui"
        )
        cleanup = {"ok": False, "reason": "unknown_or_unsupported_backend_owner"}
        if comfyui_owned:
            try:
                cleanup = await asyncio.wait_for(
                    _free_comfyui_models_for_oom(service_name, timeout_s=10.0),
                    timeout=12.0,
                )
            except Exception as exc:
                cleanup = {"ok": False, "reason": "comfyui_free_exception", "error": type(exc).__name__}
        if not cleanup.get("ok"):
            failure_reason = str(cleanup.get("reason", "comfyui_cleanup_failed"))
            bs.set_oom_state("oom_failed", source="recovery_pipeline", reason=failure_reason)
            logger.error("[oom-recovery] %s cleanup unresolved (%s); admission closed; manual intervention required", gpu_id, failure_reason)
            if job_id:
                if job_tracker is not None:
                    job_tracker.update_status(
                        job_id, "failed", error_type="oom", oom_recovery_state="oom_failed",
                        oom_reason=oom_reason or "oom_detected", oom_recovery_error=failure_reason,
                        oom_diagnostics=json.dumps({"gpu_id": gpu_id, "service": service_name, "cleanup": cleanup})[:2000],
                    )
                try:
                    await _add_to_dead_letter(job_id=job_id, gpu_id=gpu_id, reason=failure_reason, last_state="oom_failed")
                except Exception as _dl_err:
                    logger.warning("[oom-recovery] OOM dead-letter write failed for %s: %s", job_id, type(_dl_err).__name__)
            return {"state": "oom_failed", "reason": failure_reason, "gpu_id": gpu_id, "cleanup": cleanup}

        # Retained VRAM is an unresolved owner, not a successful recovery.
        bs.set_oom_state("recovering", source="recovery_pipeline")
        vram = {"available": False}
        for _ in range(12):
            try:
                vram = _verify_oom_via_vram(gpu_id)
            except Exception as exc:
                vram = {"available": False, "error": type(exc).__name__}
            if vram.get("available") and not vram.get("pressure", True):
                break
            await asyncio.sleep(1.0)
        if not (vram.get("available") and not vram.get("pressure", True)):
            failure_reason = "vram_retained_or_unverifiable_after_comfyui_free"
            bs.set_oom_state("oom_failed", source="recovery_pipeline", reason=failure_reason)
            logger.error("[oom-recovery] %s VRAM not safely restored (%s); admission closed; manual intervention required", gpu_id, vram)
            if job_id:
                if job_tracker is not None:
                    job_tracker.update_status(
                        job_id, "failed", error_type="oom", oom_recovery_state="oom_failed",
                        oom_reason=oom_reason or "oom_detected", oom_recovery_error=failure_reason,
                        oom_diagnostics=json.dumps({"gpu_id": gpu_id, "service": service_name, "vram": vram})[:2000],
                    )
                try:
                    await _add_to_dead_letter(job_id=job_id, gpu_id=gpu_id, reason=failure_reason, last_state="oom_failed")
                except Exception as _dl_err:
                    logger.warning("[oom-recovery] OOM dead-letter write failed for %s: %s", job_id, type(_dl_err).__name__)
            return {"state": "oom_failed", "reason": failure_reason, "gpu_id": gpu_id, "vram": vram}

        # Restore only the GPU-local configured idle policy (CPU-only global
        # tenants are deliberately not started on either dGPU).
        try:
            restore_results = await asyncio.wait_for(
                _restore_both_idle_llms(pre_oom_snapshot),
                timeout=OOM_RECOVERY_TIMEOUT_S,
            )
        except Exception as exc:
            restore_results = {"error": {"restored": False, "reason": type(exc).__name__}}
        if not isinstance(restore_results, dict) or not all(
            isinstance(item, dict) and item.get("restored") is True
            for item in restore_results.values()
        ):
            failure_reason = "configured_gpu_idle_restore_failed"
            bs.set_oom_state("oom_failed", source="recovery_pipeline", reason=failure_reason)
            logger.error("[oom-recovery] %s idle restore failed (%s); admission closed; manual intervention required", gpu_id, restore_results)
            if job_id:
                if job_tracker is not None:
                    job_tracker.update_status(
                        job_id, "failed", error_type="oom", oom_recovery_state="oom_failed",
                        oom_reason=oom_reason or "oom_detected", oom_recovery_error=failure_reason,
                        oom_diagnostics=json.dumps({"gpu_id": gpu_id, "service": service_name, "restore": restore_results})[:2000],
                    )
                try:
                    await _add_to_dead_letter(job_id=job_id, gpu_id=gpu_id, reason=failure_reason, last_state="oom_failed")
                except Exception as _dl_err:
                    logger.warning("[oom-recovery] OOM dead-letter write failed for %s: %s", job_id, type(_dl_err).__name__)
            return {"state": "oom_failed", "reason": failure_reason, "gpu_id": gpu_id, "restore_results": restore_results}

        bs.oom_recovery_count += 1

        # Recovery is complete only after cleanup, VRAM verification, and
        # configured GPU-local idle restoration have all succeeded.
        bs.set_oom_state("restored", source="recovery_pipeline")
        logger.info(f"[oom-recovery] {gpu_id}: recovering -> restored")

        # Restore BOTH GPUs' idle LLMs (#3) using the pre-OOM snapshot (#7).
        logger.info(
            f"[oom-recovery] Restore results: {restore_results}"
        )

        # Check permanent failure threshold (3 OOMs in 5 min on same GPU).
        # We check AFTER restore so we don't double-count the very OOM we
        # just recovered from (it's already in oom_recent_failure_times).
        now = time.time()
        recent = [
            t for t in bs.oom_recent_failure_times
            if now - t < OOM_PERMANENT_FAILURE_WINDOW_S
        ]
        bs.oom_recent_failure_times.clear()
        bs.oom_recent_failure_times.extend(recent + [now])
        if len(bs.oom_recent_failure_times) >= OOM_PERMANENT_FAILURE_THRESHOLD:
            bs.set_oom_state(
                "permanent_failed",
                source="recovery_pipeline",
                reason=(
                    f"{len(bs.oom_recent_failure_times)} OOMs in "
                    f"{OOM_PERMANENT_FAILURE_WINDOW_S}s window"
                ),
            )
            bs.oom_permanent_failure_count += 1
            logger.error(
                f"[oom-recovery] {gpu_id}: PERMANENT FAILED "
                f"({len(bs.oom_recent_failure_times)} OOMs in "
                f"{OOM_PERMANENT_FAILURE_WINDOW_S}s)"
            )
            # Phase 5: record to dead-letter list (best-effort)
            if job_id:
                try:
                    await _add_to_dead_letter(
                        job_id=job_id,
                        gpu_id=gpu_id,
                        reason=f"{len(bs.oom_recent_failure_times)} OOMs in {OOM_PERMANENT_FAILURE_WINDOW_S}s window",
                        last_state="permanent_failed",
                    )
                except Exception as _dl_err:
                    logger.debug(f"[oom-recovery] dead-letter add failed: {_dl_err}")
            return {
                "state": "permanent_failed",
                "recent_oom_count": len(bs.oom_recent_failure_times),
                "gpu_id": gpu_id,
            }

        return {
            "state": "restored",
            "gpu_id": gpu_id,
            "restore_results": restore_results,
        }
    except Exception as exc:
        reason = f"recovery_exception:{type(exc).__name__}"
        bs.set_oom_state("oom_failed", source="recovery_pipeline_exception", reason=reason)
        if job_id and job_tracker is not None:
            try:
                job_tracker.update_status(
                    job_id, "failed", error_type="oom", oom_recovery_state="oom_failed",
                    oom_recovery_error=reason,
                )
            except Exception:
                pass
        logger.exception("[oom-recovery] %s recovery failed; admission remains closed; manual intervention required", gpu_id)
        return {"state": "oom_failed", "reason": reason, "gpu_id": gpu_id}
    finally:
        _oom_recovery_in_progress.pop(gpu_id, None)
        if lock_acquired and _oom_lock is not None:
            try:
                _oom_lock.release()
            except RuntimeError:
                # Already released — defensive
                pass


def _sync_legacy_gpu_state(gpu_id: str, bundle_state: "GpuBundleState") -> None:
    """Mirror GpuBundleState fields into scheduler._gpu_state[gpu_id] (if present).

    Phase 0: GpuBundleState is the single source of truth. This helper keeps
    the legacy scheduler._gpu_state dict in sync for read-only callers (the
    /health endpoint serializes dict(self._gpu_state)). Writes should always
    go through GpuBundleState setters, never directly to scheduler._gpu_state.
    Safe to call when scheduler is not yet initialised — silently no-ops.
    """
    try:
        sched = globals().get("scheduler")  # global GPUScheduler instance
        if sched is None:
            return
        legacy = getattr(sched, "_gpu_state", None)
        if not isinstance(legacy, dict):
            return
        if gpu_id not in legacy:
            legacy[gpu_id] = {
                "loaded_bundles": [],
                "evicting": False,
                "draining": False,
                "current_priority": 0,
            }
        st = legacy[gpu_id]
        st["loaded_bundles"] = list(bundle_state.loaded_bundles)
        st["evicting"] = bundle_state.evicting
        st["draining"] = bundle_state.draining
        st["current_priority"] = bundle_state.current_priority
        if "loading" in st or bundle_state.loading:
            st["loading"] = bool(bundle_state.loading)
    except Exception as e:  # pragma: no cover — defensive
        logger.debug(f"_sync_legacy_gpu_state({gpu_id}) failed: {e}")


def _get_gpu_state(gpu_id: str) -> GpuBundleState:
    """Get or create the state tracker for a GPU."""
    if gpu_id not in _gpu_states:
        _gpu_states[gpu_id] = GpuBundleState(gpu_id)
    return _gpu_states[gpu_id]


def _get_all_gpu_states() -> dict[str, GpuBundleState]:
    """Return all per-GPU states, creating entries for configured GPUs."""
    config = _load_services_config()
    bundles = _resolve_bundles()
    # Ensure all GPUs mentioned in bundles have state entries
    for _name, bundle in bundles.items():
        gpu_id = bundle.get("gpu_id")
        if gpu_id:
            _get_gpu_state(gpu_id)
    return _gpu_states


def _oom_recovery_status_snapshot(*, gpu_id: str | None = None, now: float | None = None) -> dict:
    """Build a stable OOM-status projection for every configured GPU.

    Status reads must not omit a configured GPU merely because no recovery
    path has materialized its mutable state yet. Such an entry is reported as
    idle with ``state_present=false`` rather than silently disappearing.
    """
    observed_now = time.time() if now is None else float(now)
    configured = _services_config.get("gpu_devices", {}) if isinstance(_services_config, dict) else {}
    known_ids = set(configured) if isinstance(configured, dict) else set()
    known_ids.update(_gpu_states)
    if gpu_id is not None:
        if gpu_id not in known_ids:
            return {"schema_version": 1, "error": f"unknown gpu_id: {gpu_id}"}
        ids = [gpu_id]
    else:
        ids = sorted(known_ids)

    heartbeat_age = observed_now - _last_oom_heartbeat_ts if _last_oom_heartbeat_ts > 0 else None
    result = {
        "schema_version": 1,
        "watchdog_heartbeat_age_s": heartbeat_age,
        "watchdog_heartbeat_fresh": heartbeat_age is not None and heartbeat_age < 30,
    }
    states = {}
    for gid in ids:
        state = _gpu_states.get(gid)
        present = state is not None
        states[gid] = {
            "gpu_id": gid,
            "state_present": present,
            "oom_state": state.oom_state if state else "idle",
            "oom_state_since": state.oom_state_since if state else 0.0,
            "oom_event_count": state.oom_event_count if state else 0,
            "oom_recovery_count": state.oom_recovery_count if state else 0,
            "oom_permanent_failure_count": state.oom_permanent_failure_count if state else 0,
            "oom_last_event_ts": state.oom_last_event_ts if state else 0.0,
            "oom_last_reason": state.oom_last_reason if state else "",
            "oom_retry_attempted": state.oom_retry_attempted if state else False,
            "inflight_started_ts": _oom_recovery_in_progress.get(gid),
        }
    if gpu_id is not None:
        result["gpu"] = states[gpu_id]
    else:
        result["gpus"] = states
        result["inflight"] = dict(_oom_recovery_in_progress)
    return result


async def _check_port_healthy(port: int | str | None) -> bool:
    """Quick check if a port is responding on localhost with HTTP 200."""
    if not port:
        return False
    try:
        async with session.get(
            f"http://127.0.0.1:{int(port)}/health",
            timeout=ClientTimeout(total=3),
        ) as resp:
            return resp.status == 200
    except Exception:
        return False




