class WorkerPool:
    """Pool of persistent workers for a single service.

    Each worker: acquire semaphore → blocking dequeue → execute → release semaphore.
    Semaphore count = max parallel jobs for this service.
    """

    @staticmethod
    def _resolve_routing_groups(service_name: str, service_config: dict) -> list[str | None]:
        """Return every routing_group this service should consume from.

        Why this exists: the unified-queue submit path enqueues to
        ``queue:{routing_group}`` where ``routing_group`` is resolved from
        ``services.json::generation_templates`` (each template has a
        ``backend`` + ``routing_group``).  WorkerPool used to read
        ``routing_group`` only from the *per-service* config, which is
        ``None`` for several generation backends (comfyui, acestep) and so the pool would silently fall back to
        ``queue:{service_name}`` — an empty stream — while entries piled
        up in the correct ``queue:image-gen`` etc.  This helper walks
        generation_templates to find every routing_group the service is a
        backend for, falling back to the per-service config when the
        service has its own routing_group (e.g. ``sulphur-unet`` →
        ``video-gen``), and finally to ``[None]`` so legacy per-service
        pools keep working.
        """
        rgs: list[str | None] = []
        seen: set[str] = set()

        def _add(rg):
            if rg and rg not in seen:
                seen.add(rg)
                rgs.append(rg)

        # 1) Per-service config wins when explicitly set (LLM backends,
        #    and generation backends that already declare their group).
        svc_rg = service_config.get("routing_group")
        _add(svc_rg)

        # 2) Scan generation_templates for any template whose backend
        #    points at this service.  This is the submit-side resolution
        #    run in reverse, so producer and consumer agree on the
        #    routing_group for every backend the templates define.
        try:
            cfg = _services_config.get("generation_templates", {}) or {}
            for _tmpl_name, _tmpl in cfg.items():
                if not isinstance(_tmpl, dict):
                    continue
                if _tmpl.get("backend") == service_name:
                    _add(_tmpl.get("routing_group"))
        except Exception:
            logger.exception(
                "WorkerPool: failed to scan generation_templates for %s",
                service_name,
            )

        # 3) Legacy fallback: a single ``None`` keeps the old
        #    ``queue:{service_name}`` behaviour so a service with no
        #    templates and no routing_group isn't silently dropped.
        if not rgs:
            rgs.append(None)
        return rgs

    def __init__(
        self,
        service_name: str,
        service_config: dict,
        desired_slots: int,
        session: ClientSession,
        pipeline_dispatch_runner=None,
        coordinator_admission=None,
    ):
        self.service_name = service_name
        self.service_config = service_config
        self.session = session
        # A supervisor-built runner is shared by the pool for the lifetime of
        # the service.  It is refreshed when a pool is recreated after a
        # registry reload, so adding a service does not require controller
        # code changes or a process-local provider table edit.
        self.pipeline_dispatch_runner = pipeline_dispatch_runner
        # Optional explicit handoff for workflow.v1 parents.  The default is
        # None, leaving legacy/Krea workers as the sole owner until a staging
        # bootstrap attaches a reviewed coordinator runtime.
        self.coordinator_admission = coordinator_admission
        # Resolve the routing_group(s) this pool should consume from.
        # Multiple routing_groups are possible (e.g. comfyui is the
        # backend for image-edit, video, ltx-video, and tts templates
        # which target different routing_groups).
        self.routing_groups: list[str | None] = self._resolve_routing_groups(
            service_name, service_config
        )
        # Back-compat: keep ``routing_group`` (singular) pointing at the
        # primary stream so existing log lines, capacity_tracker calls,
        # and ack/nack paths keep working unchanged.
        self.routing_group = self.routing_groups[0]
        logger.info(
            f"WorkerPool.__init__: {service_name} routing_groups={self.routing_groups} cfg_keys={list(service_config.keys())[:5]}"
        )
        self.desired_slots = desired_slots
        self._semaphore = asyncio.Semaphore(desired_slots)
        self._workers: list[asyncio.Task] = []
        self._busy_worker_tasks: set[asyncio.Task] = set()
        self._retire_worker_debt = 0
        self._semaphore_reduction_debt = 0
        self._running = False

        # Phase 5.2 — per-service format gate. Read once at pool construction.
        # Resolution: explicit service_config field → routing_group_type default
        # → raw_json/raw_bytes. See format_converter.py "REGISTER NEW FORMAT
        # HERE" block for the dispatch table.
        _rgt = (self.service_config or {}).get("routing_group_type", "generation")
        self.input_format  = resolve_input_format(self.service_config, _rgt)
        self.output_format = resolve_output_format(self.service_config, _rgt)
        self.input_needs_conversion  = self.input_format  not in _PASSTHROUGH_INPUT
        self.output_needs_conversion = self.output_format not in _PASSTHROUGH_OUTPUT
        logger.info(
            f"WorkerPool.__init__: {service_name} format_gate "
            f"in={self.input_format} out={self.output_format} "
            f"rgt={_rgt}"
        )

    @property
    def slots_free(self) -> int:
        """How many slots are available right now."""
        return self._semaphore._value

    @property
    def slots_total(self) -> int:
        return self.desired_slots

    @property
    def active_workers(self) -> int:
        return self.desired_slots - self._semaphore._value

    def try_reserve(self) -> bool:
        """Non-blocking attempt to reserve a slot. Returns True if successful."""
        return self._semaphore._value > 0 and self._acquire_nonblocking()

    def _acquire_nonblocking(self) -> bool:
        """Try to acquire semaphore without blocking."""
        try:
            # asyncio.Semaphore doesn't have try_acquire, use internal _value check + acquire
            if self._semaphore._value <= 0:
                return False
            # Directly decrement the internal counter (safe within event loop)
            if self._semaphore._value > 0:
                self._semaphore._value -= 1
                return True
            return False
        except Exception:
            return False

    def resize(self, new_slots: int):
        """Adjust pool size without cancelling an in-flight forward."""
        if new_slots < 0:
            raise ValueError("new_slots must be non-negative")
        old = self.desired_slots
        self.desired_slots = new_slots

        if new_slots > old:
            # Scale up — spawn additional workers and increase semaphore
            for _ in range(new_slots - old):
                self._semaphore.release()
            for i in range(new_slots - old):
                idx = len(self._workers)
                t = asyncio.create_task(self._worker_loop(idx))
                self._workers.append(t)
        elif new_slots < old:
            reduction = old - new_slots
            live = [task for task in self._workers if not task.done()]
            idle = [task for task in live if task not in self._busy_worker_tasks]
            retiring_now = idle[-reduction:]
            retiring_set = set(retiring_now)
            for task in retiring_now:
                task.cancel()
            # Remove deliberately retired tasks immediately so the keeper loop
            # cannot mistake them for crashes and restart them.
            self._workers = [task for task in live if task not in retiring_set]

            busy_retirements = reduction - len(retiring_now)
            self._retire_worker_debt += busy_retirements

            free_reduction = min(reduction, self._semaphore._value)
            self._semaphore._value -= free_reduction
            self._semaphore_reduction_debt += reduction - free_reduction

        logger.info(f"Pool {self.service_name}: resized {old} -> {new_slots}")

    async def run(self):
        """Spawn workers and keep them alive."""
        self._running = True
        for i in range(self.desired_slots):
            t = asyncio.create_task(self._worker_loop(i))
            self._workers.append(t)
        logger.info(f"Pool {self.service_name}: started {self.desired_slots} workers")

        # Keep alive — restart crashed workers
        while self._running:
            await asyncio.sleep(5)
            alive = []
            for t in self._workers:
                if t.done():
                    exc = None if t.cancelled() else t.exception()
                    if exc:
                        logger.error(f"Worker for {self.service_name} crashed: {exc}")
                else:
                    alive.append(t)
            while self._running and len(alive) < self.desired_slots:
                worker_id = len(alive)
                alive.append(asyncio.create_task(self._worker_loop(worker_id)))
                logger.info(f"Restarted worker {worker_id} for {self.service_name}")
            self._workers = alive

    async def shutdown(self):
        """Gracefully shutdown all workers."""
        self._running = False
        for t in self._workers:
            if not t.done():
                t.cancel()
        if self._workers:
            await asyncio.gather(*self._workers, return_exceptions=True)
        self._workers.clear()
        logger.info(f"Pool {self.service_name}: shutdown complete")

    async def _worker_loop(self, worker_id: int):
        """Single persistent worker: poll for job -> acquire semaphore -> execute -> release.

        Polls every routing_group this pool owns.  When the producer enqueues
        to ``queue:{routing_group}`` (one stream per routing_group), the
        matching routing_group's dequeue wins and the worker hands the job
        off to ``_execute_job`` — the entry's own ``routing_group`` field is
        used downstream for ack/nack so multi-stream pools ack on the right
        stream.
        """
        import base64 as _b64
        port = self.service_config.get("port")
        routing_groups = self.routing_groups  # snapshot for the loop
        consumer_name = f"{self.service_name}-w{worker_id}"
        # Do not let the first configured stream win forever when one pool
        # serves several generation groups. Each worker rotates its starting
        # point; the durable stream still decides FIFO within a group.
        routing_cursor = worker_id % max(1, len(routing_groups))

        while self._running:
            slot_id = None              # Track outside inner try for cleanup
            semaphore_held = False      # Track semaphore acquisition
            retire_after_lease = False
            capacity_started = False    # CapacityTracker ownership for this lease
            try:
                if not async_queue:
                    await asyncio.sleep(1)
                    continue

                # Step 1: Poll for a job WITHOUT holding the semaphore.
                # Try each routing_group the pool owns.  The first one
                # that returns a job wins.  block_ms is split across the
                # streams so the worker doesn't spend its whole budget
                # blocked on an empty stream while work sits in another.
                job = None
                if len(routing_groups) <= 1:
                    rg = routing_groups[0]
                    allowed, reason = can_consume(self.service_name, rg)
                    if not allowed:
                        _log_can_consume_pause(self.service_name, rg, reason, worker_id)
                        await asyncio.sleep(1)
                    else:
                        jobs = await async_queue.dequeue(
                            self.service_name,
                            consumer_name,
                            count=1,
                            block_ms=200,
                            routing_group=rg,
                        )
                        if jobs:
                            job = jobs[0]
                else:
                    per_stream_block = max(50, 200 // len(routing_groups))
                    ordered_groups = (
                        routing_groups[routing_cursor:]
                        + routing_groups[:routing_cursor]
                    )
                    routing_cursor = (routing_cursor + 1) % len(routing_groups)
                    for rg in ordered_groups:
                        allowed, reason = can_consume(self.service_name, rg)
                        if not allowed:
                            _log_can_consume_pause(self.service_name, rg, reason, worker_id)
                            continue
                        jobs = await async_queue.dequeue(
                            self.service_name,
                            consumer_name,
                            count=1,
                            block_ms=per_stream_block,
                            routing_group=rg,
                        )
                        if jobs:
                            job = jobs[0]
                            break

                if job is None:
                    await asyncio.sleep(0.3)
                    continue

                job_id = job.get("job_id", "")
                entry_id = job.get("_entry_id", "")

                # Step 2: Acquire semaphore (controls concurrency)
                await self._semaphore.acquire()
                semaphore_held = True
                current_task = asyncio.current_task()
                if current_task is not None:
                    self._busy_worker_tasks.add(current_task)

                # Phase 3: post-claim recheck/nack
                job_rg = job.get("routing_group") or self.routing_group
                allowed, reason = can_consume(self.service_name, job_rg)
                if not allowed:
                    _log_can_consume_pause(self.service_name, job_rg, f"post_claim_pause:{reason}", worker_id)
                    success = await async_queue.yield_pending(self.service_name, entry_id, routing_group=job_rg)
                    if not success:
                        logger.error(f"Worker {worker_id}: yield_pending failed for {entry_id}, falling back to nack")
                        await async_queue.nack(
                            self.service_name, entry_id,
                            routing_group=job_rg, max_retries=4,
                        )
                    continue

                # Step 3: Mark slot busy in SlotManager (for routing accuracy)
                if slot_manager:
                    slot_id = slot_manager.acquire_slot(self.service_name, job_id)
                if capacity_tracker and (slot_manager is None or slot_id is not None):
                    capacity_tracker.on_start(self.service_name, routing_group=job_rg)
                    capacity_started = True

                if not self._running:
                    # Will clean up in finally below
                    break

                # Execute the job
                try:
                    await self._execute_job(job, port, worker_id, _b64)
                except Exception as e:
                    logger.error(f"Worker {worker_id} job {job_id} failed: {e}")

            except asyncio.CancelledError:
                # CancelledError: pool shutdown or task cancellation.
                # Do NOT re-raise — clean up resources in finally below, then break.
                logger.debug(f"Worker {worker_id} cancelled, cleaning up")
                break

            except Exception as e:
                logger.error(f"Worker {worker_id} for {self.service_name} error: {e}")
                await asyncio.sleep(1)

            finally:
                # GUARANTEED cleanup — runs on EVERY path including CancelledError
                if capacity_tracker and capacity_started:
                    capacity_tracker.on_complete(self.service_name)
                if slot_manager and slot_id is not None:
                    slot_manager.release_slot(self.service_name, slot_id)
                current_task = asyncio.current_task()
                if current_task is not None:
                    self._busy_worker_tasks.discard(current_task)
                if semaphore_held:
                    if self._semaphore_reduction_debt > 0:
                        self._semaphore_reduction_debt -= 1
                    else:
                        self._semaphore.release()
                    if self._retire_worker_debt > 0:
                        self._retire_worker_debt -= 1
                        retire_after_lease = True
            if retire_after_lease:
                break


    async def _execute_internal_workflow(
        self, job: dict, worker_id: int, _b64, *, job_rg: str | None
    ) -> None:
        """Run a reviewed internal workflow adapter without a backend port.

        A compiled workflow.v1 entry is admitted to the explicitly attached
        durable coordinator before any provider work can run.  Only the
        historical all-in-one adapter path executes directly, and only for a
        legacy entry without a compiled graph.  Coordinator store outages are
        left pending/requeued; malformed identity is terminal and ACKed.
        """
        global _queue_total_served

        job_id = job.get("job_id", "")
        entry_id = job.get("_entry_id", "")
        adapter = job.get("workflow_adapter")
        configured_adapter = (self.service_config or {}).get("adapter")
        async def _ack() -> None:
            if entry_id and async_queue:
                await async_queue.ack(
                    self.service_name,
                    "worker",
                    entry_id,
                    routing_group=job_rg,
                )

        pinned_revision = job.get("service_revision")
        pinned_fingerprint = job.get("service_revision_fingerprint")
        if pinned_revision not in (None, "") or pinned_fingerprint:
            try:
                revision_number = int(pinned_revision)
                registry = _load_services_config()
                catalog = service_revision_catalog_from_document(
                    registry.get("service_revision_catalog")
                )
                pinned = catalog.get(self.service_name, revision_number)
                if pinned.fingerprint != pinned_fingerprint:
                    raise ServiceRevisionError(
                        "queued service revision fingerprint does not match catalog"
                    )
                configured_adapter = pinned.definition.get("adapter")
            except (TypeError, ValueError, ServiceRevisionError) as exc:
                error = f"cannot resolve queued service revision: {exc}"
                if job_tracker:
                    job_tracker.update_status(job_id, "failed", error=error)
                await _ack()
                return

        if (
            adapter not in _INTERNAL_WORKFLOW_ADAPTERS
            or adapter != configured_adapter
        ):
            error = "workflow adapter identity does not match the registered service"
            if job_tracker:
                job_tracker.update_status(job_id, "failed", error=error)
            await _ack()
            return

        started_at = time.time()
        try:
            raw = _b64.b64decode(job.get("body_b64", ""), validate=True)
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, Mapping):
                raise ValueError("workflow payload must be an object")
        except Exception as exc:
            error = f"invalid internal workflow payload: {exc}"
            if job_tracker:
                job_tracker.update_status(job_id, "failed", error=error)
            await _ack()
            return

        # A resolved workflow.v1 graph is authoritative.  It must cross the
        # explicit durable coordinator boundary before any provider work runs;
        # never silently fall through to the historical all-in-one adapter.
        # The source queue entry remains the priority/lease owner until this
        # admission succeeds, then the coordinator parent stream owns the DAG.
        try:
            _job_metadata = json.loads(job.get("metadata") or "{}")
        except (TypeError, json.JSONDecodeError):
            _job_metadata = {}
        if isinstance(_job_metadata.get("workflow_pipeline"), Mapping):
            admission = self.coordinator_admission
            if admission is None:
                error = "workflow coordinator runtime is not attached"
                if job_tracker:
                    job_tracker.update_status(
                        job_id,
                        "failed",
                        error=error,
                        error_type="workflow_coordinator_unavailable",
                    )
                await _ack()
                return

            try:
                receipt = admission.admit_entry(job)
            except Exception as exc:
                retryable = bool(getattr(exc, "retryable", False))
                error = f"workflow coordinator admission failed: {str(exc)[:500]}"
                if retryable and entry_id and async_queue:
                    retry_number = int(job.get("_nack_count", 0) or 0) + 1
                    requeued = bool(
                        await async_queue.nack(
                            self.service_name,
                            entry_id,
                            routing_group=job_rg,
                            max_retries=4,
                        )
                    )
                    if job_tracker:
                        if requeued and retry_number < 4:
                            job_tracker.update_status(
                                job_id,
                                "queued",
                                error=f"retry {retry_number}/4: {error}",
                                error_type="workflow_coordinator_unavailable",
                            )
                        elif requeued:
                            job_tracker.update_status(
                                job_id,
                                "failed",
                                error=f"{error}; admission retries exhausted",
                                error_type="workflow_coordinator_unavailable",
                            )
                        else:
                            # Redis ownership could not be changed.  Leave the
                            # claim pending for the normal reaper/recovery path
                            # instead of ACKing a job whose parent is unknown.
                            job_tracker.update_status(
                                job_id,
                                "in_flight",
                                error=error,
                                error_type="workflow_coordinator_unavailable",
                            )
                    return

                if job_tracker:
                    job_tracker.update_status(
                        job_id,
                        "failed",
                        error=error,
                        error_type="workflow_coordinator_admission",
                    )
                await _ack()
                return

            if not isinstance(receipt, Mapping) or not receipt.get("accepted"):
                retry_number = int(job.get("_nack_count", 0) or 0) + 1
                requeued = bool(
                    entry_id
                    and async_queue
                    and await async_queue.nack(
                        self.service_name,
                        entry_id,
                        routing_group=job_rg,
                        max_retries=4,
                    )
                )
                error = "coordinator parent admission was not accepted"
                if job_tracker:
                    if requeued and retry_number < 4:
                        job_tracker.update_status(
                            job_id,
                            "queued",
                            error=f"retry {retry_number}/4: {error}",
                            error_type="workflow_coordinator_unavailable",
                        )
                    elif requeued:
                        job_tracker.update_status(
                            job_id,
                            "failed",
                            error=f"{error}; admission retries exhausted",
                            error_type="workflow_coordinator_unavailable",
                        )
                    else:
                        job_tracker.update_status(
                            job_id,
                            "in_flight",
                            error=error,
                            error_type="workflow_coordinator_unavailable",
                        )
                return

            if job_tracker:
                job_tracker.update_status(
                    job_id,
                    "in_flight",
                    workflow_execution_authority="coordinator",
                    coordinator_run_id=str(receipt.get("run_id") or ""),
                    coordinator_pipeline_id=str(receipt.get("pipeline_id") or ""),
                    coordinator_admitted_at=time.time(),
                    coordinator_already_admitted=bool(
                        receipt.get("already_admitted")
                    ),
                )
            # The parent stream is now the durable owner.  ACKing the source
            # entry is safe even on redelivery because run_id admission is
            # deterministic and idempotent.
            await _ack()
            return

        try:
            if adapter == "minimax-music3-pinned-cli":
                from minimax_music3_adapter import run_pipeline

                adapter_task = asyncio.create_task(
                    run_pipeline(
                        payload,
                        parent_job_id=job_id,
                        priority=int(job.get("priority", 50)),
                        priority_class=str(job.get("priority_class") or "normal"),
                    )
                )
                consecutive_renewal_failures = 0
                while True:
                    done, _ = await asyncio.wait(
                        {adapter_task}, timeout=30, return_when=asyncio.FIRST_COMPLETED
                    )
                    if done:
                        result = adapter_task.result()
                        break
                    renewed = bool(
                        entry_id
                        and async_queue
                        and hasattr(async_queue, "renew_pending")
                        and await async_queue.renew_pending(
                            self.service_name,
                            f"{self.service_name}-w{worker_id}",
                            entry_id,
                            routing_group=job_rg,
                        )
                    )
                    consecutive_renewal_failures = (
                        0 if renewed else consecutive_renewal_failures + 1
                    )
                    if job_tracker:
                        try:
                            job_tracker.update_heartbeat(
                                job_id,
                                workflow_heartbeat_at=time.time(),
                                workflow_claim_renewed=renewed,
                            )
                        except Exception:
                            logger.exception(
                                "Worker-%s: workflow heartbeat persistence failed for %s",
                                worker_id,
                                job_id,
                            )
                    if consecutive_renewal_failures >= 3:
                        adapter_task.cancel()
                        await asyncio.gather(adapter_task, return_exceptions=True)
                        raise RuntimeError(
                            "workflow queue ownership could not be renewed; "
                            "provider outcome requires reconciliation"
                        )
            else:  # Defensive: the allowlist and identity check above own this.
                raise RuntimeError(f"unimplemented workflow adapter: {adapter}")
        except asyncio.CancelledError:
            task = locals().get("adapter_task")
            if task is not None and not task.done():
                task.cancel()
                await asyncio.gather(task, return_exceptions=True)
            if job_tracker:
                job_tracker.update_status(
                    job_id,
                    "failed",
                    error="workflow worker cancelled; provider outcome requires reconciliation",
                    error_type="outcome_unknown",
                )
            await asyncio.shield(_ack())
            raise
        except Exception as exc:
            error = str(exc)
            task = locals().get("adapter_task")
            if task is not None and not task.done():
                task.cancel()
                await asyncio.gather(task, return_exceptions=True)
            outcome_unknown = "provider outcome requires reconciliation" in error
            logger.error(
                "Worker-%s: internal workflow %s failed for %s: %s",
                worker_id,
                adapter,
                job_id,
                error,
            )
            if job_tracker:
                job_tracker.update_status(
                    job_id,
                    "failed",
                    error=error,
                    error_type=(
                        "outcome_unknown"
                        if outcome_unknown
                        else "workflow_adapter_failure"
                    ),
                )
            if queue_metrics:
                loop = asyncio.get_event_loop()
                await loop.run_in_executor(
                    None,
                    queue_metrics.record_failure,
                    self.service_name,
                    "workflow_adapter_failure",
                )
            await _ack()
            return

        if result.get("status") != "completed":
            generation = result.get("generation")
            reason = (
                generation.get("submission_status")
                if isinstance(generation, Mapping)
                else result.get("error")
            ) or "workflow_adapter_failure"
            result_text = json.dumps(
                result, sort_keys=True, separators=(",", ":"), ensure_ascii=False
            )
            if job_tracker:
                job_tracker.update_status(
                    job_id,
                    "failed",
                    error=f"MiniMax workflow failed: {reason}",
                    error_type="workflow_adapter_failure",
                    result=result_text,
                    review_status=result.get("review_status", "not_ready"),
                )
            if queue_metrics:
                loop = asyncio.get_event_loop()
                await loop.run_in_executor(
                    None,
                    queue_metrics.record_failure,
                    self.service_name,
                    "workflow_adapter_failure",
                )
            await _ack()
            return

        result_text = json.dumps(
            result, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        )
        if job_tracker:
            job_tracker.update_status(
                job_id,
                "completed",
                result=result_text,
                review_status=result.get("review_status", "awaiting_human_review"),
                workflow_adapter=adapter,
            )
        _queue_total_served += 1
        if queue_metrics:
            loop = asyncio.get_event_loop()
            await loop.run_in_executor(
                None,
                queue_metrics.record_completion,
                self.service_name,
                int((time.time() - started_at) * 1000),
            )
        await _ack()
        logger.info(
            "Worker-%s: completed internal workflow %s for %s",
            worker_id,
            adapter,
            job_id,
        )

    async def _dispatch_declared_pipeline(
        self, job: dict, *, job_id: str, entry_id: str, job_rg: str | None,
    ) -> tuple[bool, bool]:
        """Run an external-only declarative pipeline at the worker boundary.

        The legacy backend forward path is intentionally bypassed for
        ``execution_mode=generic``.  This prevents a newly registered
        pipeline from accidentally dispatching its stages and then forwarding
        the same job to a second backend.  Mixed ownership remains a hard
        coordinator boundary until the durable parent coordinator claims it.

        Returns ``(handled, transport_settled)``.  The second value suppresses
        the outer best-effort ACK when this method already ACKed, requeued,
        dead-lettered, or deliberately left a claim pending for recovery.
        """

        try:
            metadata = json.loads(job.get("metadata") or "{}")
        except (TypeError, json.JSONDecodeError):
            metadata = {}
        pipeline = metadata.get("worker_pipeline") or {}
        stages = list(pipeline.get("stages") or [])
        if not stages:
            return False, False

        try:
            mode = get_dispatch_mode(stages, str(pipeline.get("execution_mode") or ""))
        except MissingOwnershipMetadataError as exc:
            error = f"pipeline provider ownership is unknown: {exc}"
            mode = DispatchMode.UNSUPPORTED

        if mode == DispatchMode.RECONCILE:
            # Worker-owned stages (for example the reviewed Krea/ComfyUI
            # route) stay on the existing backend path.  Their evidence is
            # reconciled by the worker-specific completion path.
            return False, False

        if mode == DispatchMode.MIXED_OWNERSHIP:
            admission = self.coordinator_admission
            if admission is None:
                error = "workflow coordinator runtime is not attached"
            else:
                try:
                    receipt = admission.admit_entry(job)
                except Exception as exc:
                    retryable = bool(getattr(exc, "retryable", False))
                    error = (
                        "workflow coordinator admission failed: "
                        f"{str(exc)[:500]}"
                    )
                    if retryable and entry_id and async_queue:
                        retry_number = int(job.get("_nack_count", 0) or 0) + 1
                        requeued = bool(
                            await async_queue.nack(
                                self.service_name,
                                entry_id,
                                routing_group=job_rg,
                                max_retries=4,
                            )
                        )
                        if job_tracker:
                            if requeued and retry_number < 4:
                                job_tracker.update_status(
                                    job_id,
                                    "queued",
                                    error=f"retry {retry_number}/4: {error}",
                                    error_type="workflow_coordinator_unavailable",
                                )
                            elif requeued:
                                job_tracker.update_status(
                                    job_id,
                                    "failed",
                                    error=f"{error}; admission retries exhausted",
                                    error_type="workflow_coordinator_unavailable",
                                )
                            else:
                                job_tracker.update_status(
                                    job_id,
                                    "in_flight",
                                    error=error,
                                    error_type="workflow_coordinator_unavailable",
                                )
                        # ``True`` means the source transport was deliberately
                        # settled (ACKed, requeued, DLQ'd, or left pending).
                        # The outer finally must not ACK a requeued claim.
                        return True, True
                else:
                    if not isinstance(receipt, Mapping) or not receipt.get("accepted"):
                        error = "coordinator parent admission was not accepted"
                        retry_number = int(job.get("_nack_count", 0) or 0) + 1
                        requeued = bool(
                            entry_id
                            and async_queue
                            and await async_queue.nack(
                                self.service_name,
                                entry_id,
                                routing_group=job_rg,
                                max_retries=4,
                            )
                        )
                        if job_tracker:
                            if requeued and retry_number < 4:
                                job_tracker.update_status(
                                    job_id,
                                    "queued",
                                    error=f"retry {retry_number}/4: {error}",
                                    error_type="workflow_coordinator_unavailable",
                                )
                            elif requeued:
                                job_tracker.update_status(
                                    job_id,
                                    "failed",
                                    error=f"{error}; admission retries exhausted",
                                    error_type="workflow_coordinator_unavailable",
                                )
                            else:
                                job_tracker.update_status(
                                    job_id,
                                    "in_flight",
                                    error=error,
                                    error_type="workflow_coordinator_unavailable",
                                )
                        return True, True

                    if job_tracker:
                        job_tracker.update_status(
                            job_id,
                            "in_flight",
                            workflow_execution_authority="coordinator",
                            coordinator_run_id=str(receipt.get("run_id") or ""),
                            coordinator_pipeline_id=str(
                                receipt.get("pipeline_id") or ""
                            ),
                            coordinator_admitted_at=time.time(),
                            coordinator_already_admitted=bool(
                                receipt.get("already_admitted")
                            ),
                        )
                    if entry_id and async_queue:
                        acked = bool(
                            await async_queue.ack(
                                self.service_name,
                                "worker",
                                entry_id,
                                routing_group=job_rg,
                            )
                        )
                        return True, acked
                    return True, False
        elif mode == DispatchMode.UNSUPPORTED:
            error = locals().get(
                "error", "pipeline dispatch mode is unsupported"
            )
        elif mode == DispatchMode.GENERIC:
            if self.pipeline_dispatch_runner is None:
                error = "generic pipeline runner is unavailable"
            else:
                try:
                    original_prompt = str(pipeline.get("original_prompt") or "")
                    ctx, results, dispatched = await run_pipeline_dispatch(
                        pipeline,
                        original_prompt=original_prompt,
                        max_retries=int(pipeline.get("max_retries", 3)),
                        max_loop_count=int(pipeline.get("max_loop_count", 1)),
                        executor_provider=self.pipeline_dispatch_runner,
                    )
                    if not dispatched:
                        raise RuntimeError("pipeline contained no dispatchable stages")
                    result_dicts = [dataclasses.asdict(result) for result in results]
                    failed = [
                        result for result in result_dicts
                        if result.get("status") == "failed"
                    ]
                    payload = {
                        "status": "failed" if failed else "success",
                        "artifacts": dict(ctx.artifacts),
                        "qc": dict(ctx.qc_results),
                        "enhanced_prompts": dict(ctx.enhanced_prompts),
                        "stages": result_dicts,
                    }
                    if job_tracker:
                        job_tracker.update_status(
                            job_id,
                            "failed" if failed else "completed",
                            result=json.dumps(payload, ensure_ascii=False),
                            error=(
                                failed[0].get("error")
                                if failed else None
                            ),
                        )
                    if not failed:
                        global _queue_total_served
                        _queue_total_served += 1
                    if queue_metrics:
                        loop = asyncio.get_event_loop()
                        await loop.run_in_executor(
                            None,
                            (
                                queue_metrics.record_failure
                                if failed else queue_metrics.record_completion
                            ),
                            self.service_name,
                            "pipeline_stage_failure" if failed else 0,
                        )
                    if entry_id and async_queue:
                        acked = bool(
                            await async_queue.ack(
                                self.service_name,
                                "worker",
                                entry_id,
                                routing_group=job_rg,
                            )
                        )
                        return True, acked
                    return True, False
                except Exception as exc:
                    error = f"generic pipeline dispatch failed: {exc}"
        else:
            error = "pipeline dispatch mode is unsupported"

        logger.error(
            "Worker-%s: refusing pipeline %s for %s: %s",
            self.service_name,
            mode,
            job_id,
            error,
        )
        if job_tracker:
            job_tracker.update_status(job_id, "failed", error=error)
        if entry_id and async_queue:
            acked = bool(
                await async_queue.ack(
                    self.service_name,
                    "worker",
                    entry_id,
                    routing_group=job_rg,
                )
            )
            return True, acked
        return True, False

    async def _execute_job(self, job: dict, port: int, worker_id: int, _b64):
        """Forward job to backend, handle result."""
        global _queue_total_served

        job_id = job.get("job_id", "")
        entry_id = job.get("_entry_id", "")
        # Pull the entry's own routing_group (set by the producer in
        # _build_generation_entry) so ack/nack target the right stream.
        # Falls back to the pool's primary routing_group for legacy
        # per-service entries that don't carry the field.
        job_rg = job.get("routing_group") or self.routing_group

        if _job_cancel_requested(job_tracker, job_id):
            logger.info(
                f"Worker-{worker_id}: cancelled job {job_id} claimed before admission; "
                "skipping bundle reservation and backend forward"
            )
            await _terminalize_pre_forward_job(
                job_id=job_id,
                entry_id=entry_id,
                service_name=self.service_name,
                routing_group=job_rg,
                consumer_name=f"{self.service_name}-w{worker_id}",
                status="cancelled",
                reason="cancelled before admission/bundle reservation",
            )
            _release_comfyui_admission(job_id)
            return

        # A terminal internal workflow may be reclaimed only because its Redis
        # ACK previously failed. Never invoke its provider/generation path a
        # second time; finish the transport acknowledgement only.
        if job.get("request_kind") == "internal_workflow" and job_tracker:
            existing = job_tracker.get_job(job_id)
            existing_status = (
                existing.get("status", "") if isinstance(existing, Mapping) else ""
            )
            if existing_status in {"completed", "failed", "cancelled"}:
                if entry_id and async_queue:
                    await async_queue.ack(
                        self.service_name,
                        "worker",
                        entry_id,
                        routing_group=job_rg,
                    )
                logger.info(
                    "Worker-%s: ACKed reclaimed terminal workflow %s (%s)",
                    worker_id,
                    job_id,
                    existing_status,
                )
                return

        if job_tracker:
            # Phase 5.2.51: also persist comfyui_prompt_id so /v1/job/<id>
            # can return it for clients. Without this, the in-memory `job`
            # dict has the prompt_id but the Redis copy doesn't, leading to
            # stale-job reaper false positives that re-queue completed jobs.
            _prompt_id_for_update = job.get("comfyui_prompt_id")
            update_kwargs = {"assigned_slot": f"worker-{worker_id}"}
            if _prompt_id_for_update:
                update_kwargs["comfyui_prompt_id"] = _prompt_id_for_update
            job_tracker.update_status(job_id, "in_flight", **update_kwargs)

        if job.get("request_kind") == "internal_workflow":
            await self._execute_internal_workflow(
                job, worker_id, _b64, job_rg=job_rg
            )
            return

        # Parents orchestrate; only their admitted leaf may acquire an engine.
        # Doing this after bundle loading both evicts idle models during prompt
        # preparation and leaks the pre-forward GPU lease on the early return.
        _pipeline_handled, _ = await self._dispatch_declared_pipeline(
            job, job_id=job_id, entry_id=entry_id, job_rg=job_rg,
        )
        if _pipeline_handled:
            _release_comfyui_admission(job_id)
            return

        # Phase-image-reservation: if the job was enqueued with a bundle
        # reservation, ensure that bundle is actually loaded on its target
        # GPU before we forward the request. The enqueue path already calls
        # _evict_then_load_bundle, but a concurrent eviction or a restart
        # could leave the worker seeing an unloaded bundle.
        bundle_name = job.get("bundle")
        if bundle_name:
            try:
                _bundles = _resolve_bundles()
                _bundle = _bundles.get(bundle_name, {})
                _primary_gpu = _bundle.get("gpu_id")
                _loaded = False
                if _primary_gpu:
                    _gs = _get_gpu_state(_primary_gpu)
                    if _gs is not None and _gs.loaded_bundle == bundle_name:
                        _loaded = True
                if not _loaded:
                    logger.info(
                        f"Worker-{worker_id}: bundle '{bundle_name}' not loaded, "
                        f"loading before job {job_id}"
                    )
                    # Phase 5.2.1 Fix 1b: budget-match the bundle load to the
                    # service's forward_timeout × 0.6. Without this, a 120s
                    # _wait_port_ready inside _load_bundle can outlive the
                    # slot reaper's 150s threshold, causing the slot to be
                    # force-released mid-load (matches the observed 154s
                    # "Slot lease expired" pattern).
                    _ft = int(
                        (self.service_config or {}).get("forward_timeout", 600)
                    )
                    _load_budget = max(10, int(_ft * 0.6))
                    try:
                        _loaded = await asyncio.wait_for(
                            _evict_then_load_bundle(
                                bundle_name,
                                reason=f"worker_reserve:{self.service_name}",
                                priority=int(job.get("priority", _bundle.get("priority", 5))),
                            ),
                            timeout=_load_budget,
                        )
                    except asyncio.TimeoutError:
                        logger.warning(
                            f"Worker-{worker_id}: bundle load for '{bundle_name}' "
                            f"timed out after {_load_budget}s"
                        )
                        _loaded = False
                if not _loaded:
                    raise RuntimeError(f"bundle '{bundle_name}' could not be loaded")
                # Phase 4g: stamp bundle activity now that the reservation is
                # confirmed. This protects the bundle from the auto-evict tick
                # while this job is in flight.
                if _primary_gpu:
                    _gs = _get_gpu_state(_primary_gpu)
                    if _gs is not None:
                        _gs.touch_activity(source=f"worker_reserve:{job_id}")
            except BundleAdmissionDeferred as deferred:
                # Another lifecycle transaction owns the GPU. This request
                # has not reached its backend: retain it without burning the
                # backend retry budget or spinning through a hot NACK loop.
                if job_tracker:
                    job_tracker.update_status(job_id, "queued", admission_wait=str(deferred))
                await asyncio.sleep(2)
                if entry_id and async_queue:
                    await async_queue.yield_pending(
                        self.service_name, entry_id, routing_group=job_rg,
                    )
                _release_comfyui_admission(job_id)
                return
            except Exception as _bundle_err:
                logger.error(
                    f"Worker-{worker_id}: bundle reservation failed for {job_id}: {_bundle_err}"
                )
                if job_tracker:
                    job_tracker.update_status(
                        job_id, "failed", error=f"bundle reservation failed: {_bundle_err}"
                    )
                if entry_id and async_queue:
                    await async_queue.nack(
                        self.service_name, entry_id,
                        routing_group=job_rg, max_retries=4,
                    )
                _release_comfyui_admission(job_id)
                return

        # A claimed generation job must own its bundle throughout the post-load
        # grace window.  Previously this lease began only after the grace sleep,
        # allowing auto-eviction to restore Gemma while the worker was waiting
        # to forward the ComfyUI prompt.
        _pool_gpu = self.service_config.get("gpu_id", "")
        _pool_gs = _get_gpu_state(_pool_gpu) if _pool_gpu else None
        _pool_lease_held = False
        if _pool_gs is not None:
            _pool_gs.worker_in_flight += 1
            _pool_lease_held = True
            logger.debug(
                f"Worker-{worker_id}: worker_in_flight={_pool_gs.worker_in_flight} "
                f"on {_pool_gpu} for {self.service_name} (pre-grace)"
            )
        _comfyui_job_admission_held = job_rg in {"comfyui-gen", "qwen-edit-gen"} or str(
            self.service_name
        ).startswith("comfyui")
        # Redis ownership has now transferred to the canonical WorkerPool
        # lease. Keep the ComfyUI admission fence until terminal cleanup so
        # scheduler/restore logic cannot act while /prompt or /history polling
        # is still in flight.
        if not _comfyui_job_admission_held:
            _release_comfyui_admission(job_id)

        _acked_locally: bool = False

        # Phase 5.2.2 Fix B: post-load grace period. Some backends
        # (notably ComfyUI) open the TCP port before their HTTP handler
        # thread is ready — `forward_timeout` doesn't fire on body-write
        # hangs. Sleeping for `post_load_grace_seconds` after a fresh
        # bundle load gives the server time to finish warmup.
        readiness_gate_enabled = bool(self.service_config.get("readiness_gate_enabled", False))
        _grace = int(self.service_config.get("post_load_grace_seconds", 0) or 0)
        if readiness_gate_enabled:
            readiness_service_name = self.service_config.get("readiness_gate_service_name") or self.service_name
            readiness_path = self.service_config.get("readiness_gate_path") or ""
            readiness_timeout_s = float(
                self.service_config.get(
                    "readiness_timeout_seconds",
                    self.service_config.get("readiness_gate_timeout_s", 0),
                )
                or 0
            )
            readiness_poll_interval_s = float(
                self.service_config.get(
                    "readiness_poll_interval_seconds",
                    self.service_config.get("readiness_gate_poll_interval_s", 0.1),
                )
                or 0.1
            )
            predicate_field = self.service_config.get("readiness_gate_predicate_field")
            predicate_value = self.service_config.get("readiness_gate_predicate_value")
            readiness_required_fields = self.service_config.get(
                "readiness_gate_required_fields"
            )
            readiness_required_value_fields = self.service_config.get(
                "readiness_gate_required_value_fields"
            )
            logger.info(
                f"Worker-{worker_id}: readiness gate enabled for {self.service_name} "
                f"-> {readiness_service_name}{readiness_path or ''}"
            )
            try:
                gate_ok = await _wait_service_readiness_gate(
                    session_obj=self.session,
                    job_id=job_id,
                    entry_id=entry_id,
                    routing_group=job_rg,
                    consumer_name=f"{self.service_name}-w{worker_id}",
                    worker_id=worker_id,
                    service_name=self.service_name,
                    readiness_service_name=readiness_service_name,
                    readiness_path=readiness_path,
                    readiness_timeout_s=readiness_timeout_s,
                    readiness_poll_interval_s=readiness_poll_interval_s,
                    predicate_field=predicate_field,
                    predicate_value=predicate_value,
                    readiness_required_fields=readiness_required_fields,
                    readiness_required_value_fields=readiness_required_value_fields,
                )
            except BaseException:
                if _pool_gs is not None and _pool_lease_held:
                    _pool_gs.worker_in_flight = max(0, _pool_gs.worker_in_flight - 1)
                    _pool_lease_held = False
                raise
            if not gate_ok:
                if _pool_gs is not None and _pool_lease_held:
                    _pool_gs.worker_in_flight = max(0, _pool_gs.worker_in_flight - 1)
                    _pool_lease_held = False
                return
        elif _grace > 0:
            _svc_gpu_id = self.service_config.get("gpu_id", "")
            _gs = _get_gpu_state(_svc_gpu_id) if _svc_gpu_id else None
            if _gs is not None:
                _loaded_at = float(getattr(_gs, "bundle_loaded_at", 0) or 0)
                if _loaded_at > 0:
                    _elapsed = time.time() - _loaded_at
                    if _elapsed < _grace:
                        _wait = _grace - _elapsed
                        logger.info(
                            f"Worker-{worker_id}: post-load grace {_wait:.1f}s "
                            f"for {self.service_name} (bundle loaded {_elapsed:.1f}s ago)"
                        )
                        try:
                            await asyncio.sleep(_wait)
                        except BaseException as grace_exc:
                            if isinstance(grace_exc, asyncio.CancelledError):
                                planned = bool(
                                    event_bus is not None
                                    and event_bus.is_planned_stop(self.service_name)
                                )
                                requeued = False
                                if planned and entry_id and async_queue:
                                    requeued = await asyncio.shield(
                                        async_queue.yield_pending(
                                            self.service_name,
                                            entry_id,
                                            routing_group=job_rg,
                                        )
                                    )
                                if requeued:
                                    _acked_locally = True
                                    if job_tracker:
                                        job_tracker.update_status(
                                            job_id,
                                            "queued",
                                            requeued_from=self.service_name,
                                            error=(
                                                "requeued: planned_stop during "
                                                "post-load grace"
                                            ),
                                        )
                                else:
                                    if job_tracker:
                                        job_tracker.update_status(
                                            job_id,
                                            "cancelled",
                                            error=(
                                                "worker cancelled during post-load "
                                                f"grace on {self.service_name}"
                                            ),
                                        )
                                    if entry_id and async_queue:
                                        await asyncio.shield(
                                            async_queue.ack(
                                                self.service_name,
                                                "worker",
                                                entry_id,
                                                routing_group=job_rg,
                                            )
                                        )
                                        _acked_locally = True
                            # The main forwarding try/finally starts after the
                            # grace block, so release the pre-grace lease here.
                            if _pool_gs is not None and _pool_lease_held:
                                _pool_gs.worker_in_flight = max(
                                    0, _pool_gs.worker_in_flight - 1
                                )
                                _pool_lease_held = False
                            raise

        if _job_cancel_requested(job_tracker, job_id):
            logger.info(
                f"Worker-{worker_id}: cooperative cancel observed for {job_id} "
                f"before backend forward; bypassing session.request"
            )
            try:
                await _terminalize_pre_forward_job(
                    job_id=job_id,
                    entry_id=entry_id,
                    service_name=self.service_name,
                    routing_group=job_rg,
                    consumer_name=f"{self.service_name}-w{worker_id}",
                    status="cancelled",
                    reason="cancelled before forward (cooperative cancel)",
                )
            finally:
                if _pool_gs is not None and _pool_lease_held:
                    _pool_gs.worker_in_flight = max(0, _pool_gs.worker_in_flight - 1)
                    _pool_lease_held = False
            return

        # Build request
        # Honor entry["endpoint"] when set (lets comfyui point
        # at http://127.0.0.1:8188 without being tied to the pool's port).
        # Fall back to the legacy http://localhost:{port}{path} form for
        # existing entries that don't carry an endpoint.
        endpoint = job.get("endpoint", "")
        if endpoint:
            url = endpoint.rstrip("/") + job.get("http_path", "/")
        else:
            url = f"http://localhost:{port}{job.get('http_path', '/v1/chat/completions')}"

        # Phase 5.2.35 Bug C (now superseded by worker_in_flight):
        # touch_activity was the prior fix attempt. The new
        # worker_in_flight counter (checked by _auto_evict_idle_bundles)
        # is strictly stronger: it covers the entire _execute_job
        # window, not just the moment before the forward call.
        body = None
        _claimed_prompt_evidence = None
        body_b64 = job.get("body_b64", "")
        if body_b64:
            try:
                body = _b64.b64decode(body_b64)
            except Exception:
                body = None

        # Phase 5.2.35 debug: trace forward call (MOVED here after the
        # body_b64 assignment in 5.2.36 — the previous position was
        # before body_b64 existed, causing UnboundLocalError when the
        # worker finally reached this code path).
        logger.info(
            f"Worker-{worker_id}: FORWARD {job.get('http_method', 'POST')} {url} "
            f"job_id={job_id} routing_group={job_rg} service={self.service_name} "
            f"body_len={len(body_b64) if body_b64 else 0}"
        )

        fwd_headers = {}
        try:
            fwd_headers = json.loads(job.get("headers", "{}"))
        except Exception:
            pass

        _job_start_time = time.time()
        # The worker lease was acquired before the post-load grace above and is
        # released by the existing finally block on every forwarding path.
        # Phase 5.2.79 (R3): track whether an in-body ack already ran, so the
        # finally's ack at line ~8429 doesn't double-ack. XACK is idempotent
        # in Redis (no data corruption), but an UNGUARDED await in finally
        # can RAISE and convert a clean `return` into a propagated exception
        # — that was the latent bug behind reaper-nacks-completed-jobs after
        # redis jitter. Set True inside any in-body ack site; the finally
        # gates its ack on this flag.
        try:
            # Queue-first prompt policy: the admitted raw prompt is verified
            # against the exact server-owned workflow target after this
            # worker owns the Redis entry and linked GPU lease.
            if job.get("request_kind") == "comfyui_workflow" and body:
                source_artifact = job.get("coordinator_source_artifact")
                if source_artifact:
                    from pathlib import Path
                    if isinstance(source_artifact, str):
                        source_artifact = json.loads(source_artifact)
                    source_path = Path(source_artifact["path_or_url"]).resolve(strict=True)
                    output_root = Path(os.environ.get("GPU_MANAGER_GENERATION_OUTPUT_DIR",
                                       str(PROJECT_ROOT / "output" / "gpu-manager"))).resolve()
                    # Accepted jobs may reference the preceding release.
                    # Only explicitly host-allowlisted legacy output roots are
                    # readable; clients cannot expand this path boundary.
                    allowed_roots = [output_root, *(
                        Path(item).resolve() for item in os.environ.get(
                            "GPU_MANAGER_GENERATION_LEGACY_OUTPUT_DIRS", ""
                        ).split(os.pathsep) if item
                    )]
                    if not any(source_path.is_relative_to(root) for root in allowed_roots):
                        raise RuntimeError("coordinator image source is outside the artifact store")
                    source_bytes = await asyncio.to_thread(source_path.read_bytes)
                    if hashlib.sha256(source_bytes).hexdigest() != source_artifact["sha256"]:
                        raise RuntimeError("coordinator image source hash mismatch")
                    staged_name = await _stage_image_to_comfyui_input(
                        session=self.session, comfyui_base=url.removesuffix("/prompt"),
                        image_bytes=source_bytes, filename=f"{job_id}-source.png",
                    )
                    source_metadata = json.loads(job.get("metadata") or "{}")
                    node, field = source_metadata["source_image_target"]
                    source_body = json.loads(body)
                    source_body["prompt"][node]["inputs"][field] = staged_name
                    body = json.dumps(source_body).encode()
                body, _claimed_prompt_evidence = await _prepare_comfyui_body_after_claim(
                    job, body
                )
                if _claimed_prompt_evidence and job_tracker:
                    job_tracker.update_status(
                        job_id,
                        "in_flight",
                        prompt_evidence=json.dumps(
                            _claimed_prompt_evidence,
                            sort_keys=True,
                            separators=(",", ":"),
                            ensure_ascii=False,
                        ),
                        effective_prompt_sha256=_claimed_prompt_evidence.get(
                            "effective_prompt_sha256"
                        ),
                        workflow_sha256=_claimed_prompt_evidence.get("workflow_sha256"),
                        prompt_target=_claimed_prompt_evidence.get("prompt_target"),
                    )

            # ── Format conversion: input → LEAN ──
            # Phase 5.2 per-service gate. input_needs_conversion is False
            # for passthrough formats (comfyui_workflow, sd_server_*,
            # acestep_music, raw_json, passthrough) so those bodies reach
            # the backend byte-identical.
            if _FMT_AVAILABLE and body and self.input_needs_conversion:
                try:
                    body = convert_request_for_format(self.input_format, body)
                except Exception as _fc_err:
                    logger.debug(f"Worker-{worker_id}: input fmt[{self.input_format}] failed (passthrough): {_fc_err}")

            if job.get("request_kind") == "comfyui_workflow" and job_tracker:
                # Persist the pre-ACK boundary too. A slow model load or a
                # blocked /prompt handler has no ComfyUI prompt ID yet, but
                # operators must still be able to distinguish that real
                # in-flight submission from a worker that never forwarded.
                job_tracker.update_status(
                    job_id,
                    "in_flight",
                    comfyui_submit_started_at=time.time(),
                    comfyui_endpoint=url,
                )

            if job.get("request_kind") == "audio_cpp_task" and self.service_config.get("native_task_host_url"):
                from native_task_client import native_task_request
                host_url = self.service_config["native_task_host_url"]
                native_helper_token_file = _required_native_helper_token_file()
                if job_tracker is None:
                    raise RuntimeError("native task ownership requires durable job tracking")
                native_tracked = _coordinator_job_dict(job_tracker.get_job(job_id)) or {}
                native_admission_started = str(native_tracked.get("native_task_admission_started", "")).lower() == "true"
                job_tracker.update_fields(job_id, native_task_handle=job_id,
                                          native_task_host_url=host_url)

                def native_state(record):
                    fields = {}
                    if record.get("status") in {"submit_intent", "accepted", "in_flight", "completed", "failed"}:
                        fields["native_task_admission_started"] = True
                    recorded = job_tracker.update_fields(
                        job_id, native_task_state=str(record.get("status") or "unknown"),
                        native_upstream_submit_count=str(record.get("upstream_submit_count", "")),
                        native_observation_error=str(record.get("reason") or ""), **fields,
                    )
                    if not recorded:
                        raise RuntimeError("native task observation could not be persisted")

                forward_request = native_task_request(
                    self.session, host_url=host_url, task_id=job_id,
                    body=body, on_state=native_state, admission_started=native_admission_started,
                    service_token_file=native_helper_token_file,
                )
            else:
                forward_request = self.session.request(
                    method=job.get("http_method", "POST"),
                    url=url,
                    data=body,
                    headers=fwd_headers,
                    timeout=ClientTimeout(
                        total=int(self.service_config.get("forward_timeout", 600)),
                        sock_connect=5,
                        sock_read=int(self.service_config.get(
                            "forward_sock_read_timeout", self.service_config.get("forward_timeout", 600)
                        )),
                    ),
                )
            async with forward_request as resp:
                resp_body = await resp.read()
                resp_text = resp_body.decode("utf-8", errors="replace")

                # ── Format conversion: output → JSON ──
                # Phase 5.2 per-service gate. output_needs_conversion is False
                # for raw_bytes / raw_json_out / comfyui_ack / sd_server_*_out /
                # acestep_audio_out — non-JSON backends (sd-server image,
                # ComfyUI workflow acks, etc.) reach the caller verbatim.
                # The OOM substring heuristic below still works because
                # resp_text is the raw upstream body in those cases.
                if _FMT_AVAILABLE and self.output_needs_conversion:
                    try:
                        resp_text = convert_response_for_format(self.output_format, resp_text)
                    except Exception as _fc_err:
                        logger.debug(f"Worker-{worker_id}: output fmt[{self.output_format}] failed (passthrough): {_fc_err}")

                # Any non-2xx backend response is a failed forward.  A 404 body
                # must never be committed as a successful generation result.
                _oom_detected = False
                _oom_info = None
                _oom_gpu_id = (self.service_config or {}).get("gpu_id", "") or "gpu_primary"
                if resp.status >= 400:
                    # Treat as a failure - the backend itself reported OOM/error
                    error_msg = f"HTTP {resp.status}: {resp_text[:200]}"
                    logger.error(f"Worker-{worker_id}: backend error for {job_id}: {error_msg}")
                    # Phase 2: OOM detection — record the event on the
                    # GpuBundleState so /health surfaces it and the watchdog
                    # (Phase 3) can drive recovery. The existing inline
                    # _force_recover_failed_service call below is preserved
                    # unchanged; Phase 3 will replace the inline path.
                    try:
                        _oom_gpu_id = (self.service_config or {}).get("gpu_id", "") or "gpu_primary"
                        _oom_info = _detect_oom_in_history(
                            status_str="error" if resp.status >= 500 else "",
                            response_body=resp_text,
                            status_code=resp.status,
                        )
                        if _oom_info is not None:
                            _oom_detected = True
                            # Phase 5: remember which service tripped the OOM
                            # so _resolve_service_for_gpu can attribute the
                            # failure when the GPU has no loaded bundles yet
                            # (typical race: OOM fires during first request).
                            _oom_bs = _gpu_states.get(_oom_gpu_id)
                            if _oom_bs is not None:
                                _oom_bs.oom_last_service_name = self.service_name
                            _handle_oom_event(
                                gpu_id=_oom_gpu_id,
                                service_name=self.service_name,
                                job_id=job_id,
                                detection_source="worker_inline",
                                reason=_oom_info.get("reason", "oom detected"),
                                details=str(_oom_info.get("details", ""))[:500],
                            )
                    except Exception as _oom_hook_err:
                        # Never let OOM recording break the worker
                        logger.debug(f"Worker-{worker_id}: oom detection hook failed: {_oom_hook_err}")
                    if job_tracker:
                        status_fields = {"error": error_msg}
                        if _oom_detected:
                            status_fields.update({
                                "error_type": "oom",
                                "oom_reason": str((_oom_info or {}).get("reason", "oom_detected"))[:500],
                                "oom_details": str((_oom_info or {}).get("details", ""))[:500],
                                "oom_recovery_state": "detected",
                            })
                        job_tracker.update_status(job_id, "failed", **status_fields)
                    if queue_metrics:
                        loop = asyncio.get_event_loop()
                        await loop.run_in_executor(
                            None, queue_metrics.record_failure, self.service_name, f"HTTP_{resp.status}")
                    # Only a positively classified OOM enters recovery. Bad
                    # prompts and ordinary backend 4xx/5xx responses are not
                    # GPU ownership evidence and must not trigger teardown.
                    if _oom_detected:
                        try:
                            recovery = await asyncio.wait_for(
                                _oom_recovery_pipeline(
                                    gpu_id=_oom_gpu_id,
                                    service_name=self.service_name,
                                    job_id=job_id,
                                    oom_reason=str((_oom_info or {}).get("reason", "oom detected")),
                                    oom_details=str((_oom_info or {}).get("details", ""))[:500],
                                ),
                                timeout=75.0,
                            )
                            if job_tracker:
                                job_tracker.update_status(
                                    job_id, "failed", error=error_msg, error_type="oom",
                                    oom_recovery_state=str(recovery.get("state", "unknown")),
                                    oom_recovery_error=str(recovery.get("reason", ""))[:500],
                                    oom_diagnostics=json.dumps(recovery, default=str)[:2000],
                                )
                        except Exception as rec_err:
                            failed_state = _gpu_states.get(_oom_gpu_id)
                            if failed_state is not None:
                                failed_state.set_oom_state(
                                    "oom_failed", source="worker_recovery_timeout_or_exception",
                                    reason=type(rec_err).__name__,
                                )
                            if job_tracker:
                                job_tracker.update_status(
                                    job_id, "failed", error=error_msg, error_type="oom",
                                    oom_recovery_state="oom_failed",
                                    oom_recovery_error=type(rec_err).__name__,
                                )
                            logger.error(
                                "Worker-%s: OOM recovery for %s failed (%s); admission remains closed; manual intervention required",
                                worker_id, job_id, type(rec_err).__name__,
                            )
                    if entry_id and async_queue:
                        if _oom_detected or job.get("request_kind") == "audio_cpp_task":
                            await async_queue.ack(
                                self.service_name, "worker", entry_id,
                                routing_group=job_rg,
                            )
                            _acked_locally = True
                            logger.warning(
                                f"Worker-{worker_id}: ACKed terminal backend job {job_id}; "
                                "not requeueing a definitive failure"
                            )
                        else:
                            await async_queue.nack(
                                self.service_name, entry_id,
                                routing_group=job_rg, max_retries=4,
                            )
                    return

                # For ComfyUI workflows, the /prompt response is just
                # `{"prompt_id": "..."}` — the actual image is generated asynchronously.
                # Poll /history/{prompt_id} until the job completes (or times out),
                # then fetch each output image via /view and store base64-encoded
                # bytes as the job result. Falls through to the legacy sync-completion
                # block for non-comfyui jobs.
                if job.get("request_kind") == "comfyui_workflow":
                    try:
                        prompt_id = json.loads(resp_text).get("prompt_id", "")
                    except Exception:
                        prompt_id = ""
                    if prompt_id:
                        # A /prompt ACK is the authoritative hand-off from
                        # GPU Manager to ComfyUI. Persist its correlation ID
                        # before sleeping/polling so a long forward, worker
                        # restart, or history-retention race never leaves a
                        # durable job record with no upstream identity.
                        if job_tracker:
                            job_tracker.update_status(
                                job_id,
                                "in_flight",
                                comfyui_prompt_id=prompt_id,
                                comfyui_prompt_ack_at=time.time(),
                            )
                        job["comfyui_prompt_id"] = prompt_id
                        logger.info(
                            "Worker-%s: ComfyUI /prompt ACK for %s -> prompt_id=%s",
                            worker_id,
                            job_id,
                            prompt_id,
                        )
                        # Derive the ComfyUI base URL from the endpoint we POSTed to.
                        comfyui_base = url.rstrip("/")
                        if comfyui_base.endswith("/prompt"):
                            comfyui_base = comfyui_base[: -len("/prompt")]
                        poll_url = f"{comfyui_base}/history/{prompt_id}"
                        try:
                            _poll_metadata = json.loads(job.get("metadata") or "{}")
                        except (TypeError, json.JSONDecodeError):
                            _poll_metadata = {}
                        _workflow_timeout_s = generation_poll_deadline_s(_poll_metadata)
                        poll_deadline = time.time() + _workflow_timeout_s
                        poll_started_at = time.time()  # Phase 5.2.49: for accurate timeout error message
                        poll_interval = 5
                        completed = False
                        # Phase 5.2.52: track "no images" retries. When ComfyUI
                        # auto-frees models mid-poll, the history response is OK
                        # but /view returns empty. Instead of failing immediately,
                        # reset the loop and re-poll — the model state will
                        # re-freeze (auto-free is a one-shot event).
                        _no_images_retries = 0
                        _no_images_max_retries = 3
                        # A /prompt ACK is not a completion. If ComfyUI forgets
                        # the prompt or stops answering for the grace window the
                        # job ends typed (never replayed) instead of holding the
                        # worker lease until the full poll deadline.
                        _lost_tracker = LostCompletionTracker(
                            grace_s=lost_completion_grace_s(_poll_metadata)
                        )
                        _lost_reason = None
                        while time.time() < poll_deadline:
                            await asyncio.sleep(poll_interval)
                            # The supervisor may have durably terminalized this
                            # accepted job after confirming its unit died. Stop
                            # polling promptly; the existing finally owns ACK and
                            # worker-slot/lease release.
                            if job_tracker:
                                try:
                                    _observed = _coordinator_job_dict(
                                        job_tracker.get_job(job_id)
                                    ) or {}
                                    if _observed.get("status") in {
                                        "failed", "cancelled", "completed", "dead_lettered",
                                    }:
                                        logger.info(
                                            "Worker-%d: ending poll for %s; tracker is terminal (%s)",
                                            worker_id, job_id, _observed.get("status"),
                                        )
                                        return
                                except Exception:
                                    # Tracker unavailability is not evidence of
                                    # terminality; preserve normal polling behavior.
                                    pass
                            try:
                                async with self.session.get(
                                    poll_url, timeout=ClientTimeout(total=10)
                                ) as hist_resp:
                                    hist_text = await hist_resp.text()
                            except Exception as poll_err:
                                logger.debug(
                                    f"Worker-{worker_id}: history poll failed: {poll_err}"
                                )
                                _lost_tracker.observe(
                                    PromptLiveness.UNREACHABLE, time.time()
                                )
                                _lost_reason = _lost_tracker.lost_reason(time.time())
                                if _lost_reason:
                                    break
                                continue
                            try:
                                hist_data = json.loads(hist_text)
                            except Exception:
                                continue
                            job_entry = hist_data.get(prompt_id)
                            if not job_entry:
                                _oom_bs = _gpu_states.get(
                                    (self.service_config or {}).get("gpu_id", "") or "gpu_primary"
                                )
                                if _oom_bs is not None and float(getattr(_oom_bs, "oom_last_event_ts", 0.0) or 0.0) >= poll_started_at:
                                    _oom_error = "ComfyUI history disappeared after OOM recovery"
                                    if job_tracker:
                                        job_tracker.update_status(
                                            job_id, "failed",
                                            error=_oom_error,
                                            error_type="oom",
                                            oom_reason="oom_during_history_poll",
                                            comfyui_prompt_id=prompt_id,
                                        )
                                    if entry_id and async_queue:
                                        await async_queue.ack(
                                            self.service_name, "worker", entry_id,
                                            routing_group=job_rg,
                                        )
                                        _acked_locally = True
                                    logger.error(
                                        f"Worker-{worker_id}: terminal OOM for {job_id} "
                                        f"during ComfyUI history polling"
                                    )
                                    return
                                _lost_tracker.observe(
                                    await probe_prompt(
                                        self.session, comfyui_base, prompt_id
                                    ),
                                    time.time(),
                                )
                                _lost_reason = _lost_tracker.lost_reason(time.time())
                                if _lost_reason:
                                    break
                                continue
                            _lost_tracker.observe(PromptLiveness.PRESENT, time.time())
                            status = job_entry.get("status", {})
                            if _comfyui_execution_interrupted(job_entry):
                                _interrupted_error = (
                                    f"ComfyUI execution {prompt_id} was interrupted"
                                )
                                if job_tracker:
                                    job_tracker.update_status(
                                        job_id,
                                        "failed",
                                        error=_interrupted_error,
                                        error_type="execution_interrupted",
                                        comfyui_prompt_id=prompt_id,
                                    )
                                logger.error(
                                    "Worker-%s: terminal ComfyUI interruption for %s "
                                    "(prompt_id=%s)",
                                    worker_id,
                                    job_id,
                                    prompt_id,
                                )
                                completed = True
                                break
                            if status.get("completed", False):
                                # Check for node errors
                                if job_entry.get("node_errors"):
                                    node_err = json.dumps(job_entry["node_errors"])[:500]
                                    if job_tracker:
                                        job_tracker.update_status(
                                            job_id, "failed",
                                            error=f"ComfyUI node errors: {node_err}",
                                        )
                                    if queue_metrics:
                                        loop = asyncio.get_event_loop()
                                        await loop.run_in_executor(
                                            None, queue_metrics.record_failure,
                                            self.service_name, "comfyui_node_errors",
                                        )
                                    logger.error(
                                        f"Worker-{worker_id}: comfyui job {prompt_id} "
                                        f"failed: {node_err}"
                                    )
                                    completed = True
                                    break
                                # Extract image bytes from outputs
                                outputs = job_entry.get("outputs", {}) or {}
                                image_data = []
                                for _nid, out in outputs.items():
                                    for img in (out.get("images") or []):
                                        try:
                                            view_params = {
                                                "filename": img.get("filename", ""),
                                                "type": img.get("type", "output"),
                                                "subfolder": img.get("subfolder", ""),
                                            }
                                            view_url = f"{comfyui_base}/view"
                                            async with self.session.get(
                                                view_url,
                                                params=view_params,
                                                timeout=ClientTimeout(total=60),
                                            ) as view_resp:
                                                img_bytes = await view_resp.read()
                                                _view_content_type = str(
                                                    view_resp.headers.get("Content-Type") or ""
                                                )
                                                if (
                                                    view_resp.status != 200
                                                    or not _view_content_type.startswith("image/")
                                                ):
                                                    raise RuntimeError(
                                                        "ComfyUI view returned invalid status/type: "
                                                        f"{view_resp.status} {_view_content_type}"
                                                    )
                                                _verified_image_bytes(img_bytes)
                                                image_data.append({
                                                    "filename": view_params["filename"],
                                                    "subfolder": view_params["subfolder"],
                                                    "type": view_params["type"],
                                                    "data_b64": _b64.b64encode(
                                                        img_bytes
                                                    ).decode("ascii"),
                                                })
                                        except Exception as img_err:
                                            logger.warning(
                                                f"Worker-{worker_id}: failed to fetch "
                                                f"image {view_params}: {img_err}"
                                            )
                                _qc_report = None
                                if image_data:
                                    try:
                                        _job_metadata = json.loads(job.get("metadata") or "{}")
                                    except (TypeError, json.JSONDecodeError):
                                        _job_metadata = {}
                                    _worker_pipeline_cfg = _job_metadata.get("worker_pipeline") or {}
                                    _post_policy = _worker_pipeline_cfg.get("post_generate") or {}
                                    if _post_policy.get("enabled"):
                                        _effective_for_qc = (
                                            (_claimed_prompt_evidence or {}).get("effective_prompt")
                                            or _worker_pipeline_cfg.get("original_prompt")
                                            or ""
                                        )
                                        image_data, _qc_report = await _run_post_generation_image_pipeline(
                                            image_data,
                                            prompt=str(_effective_for_qc),
                                            policy=dict(_post_policy),
                                            session=self.session,
                                            comfyui_base=comfyui_base,
                                            job_id=job_id,
                                        )
                                        _qc_terminal_failure = _fail_closed_post_generation_reason(
                                            _qc_report
                                        )
                                        if _qc_terminal_failure:
                                            _qc_error = (
                                                "post-generation QC fail-closed: "
                                                f"{_qc_terminal_failure}"
                                            )
                                            if job_tracker:
                                                _fail_kwargs = {
                                                    "error": _qc_error,
                                                    "result": json.dumps({
                                                        "prompt_id": prompt_id,
                                                        "status": "failed",
                                                        "images": image_data,
                                                        "qc": _qc_report,
                                                    }),
                                                }
                                                if prompt_id:
                                                    _fail_kwargs["comfyui_prompt_id"] = prompt_id
                                                job_tracker.update_status(
                                                    job_id, "failed", **_fail_kwargs,
                                                )
                                            logger.error(
                                                "Worker-%d: %s job=%s",
                                                worker_id, _qc_error, job_id,
                                            )
                                            if entry_id and async_queue:
                                                try:
                                                    await async_queue.ack(
                                                        self.service_name, "worker", entry_id,
                                                        routing_group=job_rg,
                                                    )
                                                    _acked_locally = True
                                                except Exception:
                                                    pass
                                            return
                                if image_data:
                                    result_payload = {
                                        "prompt_id": prompt_id,
                                        "status": "success",
                                        "images": image_data,
                                    }
                                    artifacts = await asyncio.to_thread(
                                        lambda: [_persist_generated_image(job_id, item, index)
                                                 for index, item in enumerate(image_data)]
                                    )
                                    result_payload["artifact"] = artifacts[0]
                                    result_payload["artifacts"] = artifacts
                                    if _qc_report is not None:
                                        result_payload["qc"] = _qc_report
                                    if job_tracker:
                                        # Phase 5.2.51: include comfyui_prompt_id in the
                                        # completion update too — otherwise the
                                        # result=json.dumps(...) overwrites the in_flight
                                        # record that had the prompt_id, and the
                                        # completed record in Redis loses it.
                                        _finish_kwargs = {"result": json.dumps(result_payload)}
                                        if prompt_id:
                                            _finish_kwargs["comfyui_prompt_id"] = prompt_id
                                        job_tracker.update_status(
                                            job_id, "completed",
                                            **_finish_kwargs,
                                        )
                                    _queue_total_served += 1
                                    logger.info(
                                        f"Worker-{worker_id}: completed {job_id} on "
                                        f"{self.service_name} (comfyui "
                                        f"{len(image_data)} images)"
                                    )
                                else:
                                    _no_images_retries += 1
                                    if _no_images_retries <= _no_images_max_retries:
                                        # Phase 5.2.52: re-poll. ComfyUI may be in the
                                        # middle of auto-freeing models — /view returns empty
                                        # transiently. The history endpoint will re-freeze.
                                        # Backoff: 10s, 20s, 40s (capped at 60s).
                                        _backoff = min(60, 10 * (2 ** (_no_images_retries - 1)))
                                        logger.warning(
                                            f"Worker-{worker_id}: comfyui {prompt_id} "
                                            f"no images on attempt {_no_images_retries}/{_no_images_max_retries}, "
                                            f"retrying in {_backoff}s"
                                        )
                                        await asyncio.sleep(_backoff)
                                        continue  # re-poll the history endpoint
                                    # Exhausted retries — mark failed
                                    if job_tracker:
                                        # Phase 5.2.51: also persist comfyui_prompt_id
                                        # in the failure record so /v1/job/<id> can
                                        # return it for diagnostics.
                                        _fail_kwargs = {
                                            "error": (
                                                f"ComfyUI job {prompt_id} completed "
                                                f"but no images in output after "
                                                f"{_no_images_max_retries} retries"
                                            ),
                                        }
                                        if prompt_id:
                                            _fail_kwargs["comfyui_prompt_id"] = prompt_id
                                        job_tracker.update_status(
                                            job_id, "failed",
                                            **_fail_kwargs,
                                        )
                                    logger.warning(
                                        f"Worker-{worker_id}: comfyui {prompt_id} "
                                        f"completed with no images after "
                                        f"{_no_images_max_retries} retries"
                                    )
                                completed = True
                                # Phase 5.2.76 ack+return, tightened 5.2.79 (R3):
                                # the previous implementation fell through to the
                                # sync-completion block below, which double-logged
                                # "Worker-N: completed", double-marked the job in
                                # job_tracker, and relied on the outer finally block
                                # to ack the queue entry. That was the root cause of
                                # the reaper-nacks-completed-jobs loop: if the finally
                                # block's await was slow (large redis pipeline,
                                # network jitter), the reaper saw the entry still in
                                # the PEL 5+ min later and nacked it, causing the
                                # same job to be re-FORWARDed. Ack here, then return,
                                # so the entry is removed from the PEL BEFORE the
                                # reaper re-checks it; the image is on disk by the
                                # time we get here.
                                if entry_id and async_queue:
                                    try:
                                        await async_queue.ack(
                                            self.service_name, "worker", entry_id,
                                            routing_group=job_rg,
                                        )
                                        # Phase 5.2.79 (R3): flag so the finally's
                                        # ack skips this entry — XACK is idempotent
                                        # but the finally's await is unguarded and
                                        # can RAISE during a return.
                                        _acked_locally = True
                                    except Exception:
                                        pass
                                return
                        if not completed:
                            # Phase 5.2.49: compute actual elapsed seconds
                            # rather than hardcoded "300s" — poll_deadline
                            # is now 900s (15 min) but error said 300s.
                            elapsed_s = int(time.time() - poll_started_at) if 'poll_started_at' in dir() else _workflow_timeout_s
                            if job_tracker:
                                # Phase 5.2.51: persist prompt_id in timeout record too
                                _timeout_kwargs = {
                                    "error": (
                                        f"ComfyUI job {prompt_id} timed out "
                                        f"after {elapsed_s}s"
                                    ),
                                }
                                if prompt_id:
                                    _timeout_kwargs["comfyui_prompt_id"] = prompt_id
                                if _lost_reason:
                                    _timeout_kwargs["error"] = (
                                        f"ComfyUI job {prompt_id} lost completion: "
                                        f"{_lost_reason}"
                                    )
                                    _timeout_kwargs["error_type"] = (
                                        LOST_COMPLETION_ERROR_TYPE
                                    )
                                job_tracker.update_status(
                                    job_id, "failed",
                                    **_timeout_kwargs,
                                )
                            logger.error(
                                f"Worker-{worker_id}: comfyui {prompt_id} timed out"
                            )
                        # Ack the queue entry and exit — the async-poll branch
                        # has fully handled this job, so skip the sync-completion
                        # block below.
                        if entry_id and async_queue:
                            try:
                                await async_queue.ack(
                                    self.service_name, "worker", entry_id,
                                    routing_group=job_rg,
                                )
                                # Phase 5.2.79 (R3): same flag as the success path;
                                # tells finally to skip its ack.
                                _acked_locally = True
                            except Exception:
                                pass
                        return
                    # Phase 5.2.74 Fix #2: prompt_id is empty — ComfyUI returned
                    # HTTP 200 but no prompt_id. That's a real failure (workflow
                    # rejected: missing node, missing model, malformed JSON, etc.).
                    # Without this branch, the code falls through to the legacy
                    # sync-completion block below and silently logs "completed"
                    # with the error body as result. Now we mark the job failed
                    # with the actual response so the operator can see what went
                    # wrong, and we nack the queue entry so the bundle supervisor
                    # doesn't immediately retry the same broken input.
                    else:
                        error_preview = resp_text[:500] if resp_text else "(empty body)"
                        logger.error(
                            "Worker-%d: comfyui /prompt returned no prompt_id for job %s "
                            "(status=%d, body=%s)",
                            worker_id, job_id, resp.status, error_preview,
                        )
                        if job_tracker:
                            try:
                                job_tracker.update_status(
                                    job_id, "failed",
                                    error=f"ComfyUI returned no prompt_id: {error_preview}",
                                )
                            except Exception:
                                pass
                        if entry_id and async_queue:
                            try:
                                await async_queue.nack(
                                    self.service_name, entry_id,
                                    routing_group=job_rg, max_retries=4,
                                )
                            except Exception:
                                pass
                        return

                if job.get("request_kind") == "audio_cpp_task":
                    loop = asyncio.get_event_loop()
                    resp_text = await loop.run_in_executor(
                        None, _persist_audio_cpp_result, job_id, resp_text
                    )

                # Store RAW response (no envelope wrapping)
                if job_tracker:
                    job_tracker.update_status(job_id, "completed", result=resp_text)
                # Publish the warm handoff lease in the same non-awaiting critical
                # section as the terminal JobTracker commit. The supervisor idle
                # loop can run at the next await, so arming only in finally leaves
                # a scheduler-sized gap after completion.
                if self.service_name == "comfyui":
                    _arm_comfyui_warm_handoff(job_id, "completed")
                _queue_total_served += 1
                logger.info(f"Worker-{worker_id}: completed {job_id} on {self.service_name}")
                if queue_metrics:
                    _duration_ms = int((time.time() - _job_start_time) * 1000)
                    loop = asyncio.get_event_loop()
                    await loop.run_in_executor(
                        None, queue_metrics.record_completion, self.service_name, _duration_ms)

        except asyncio.CancelledError:
            if (
                _controller_shutdown_in_progress
                and job.get("request_kind") == "comfyui_workflow"
                and job.get("comfyui_prompt_id")
            ):
                # A controller shutdown is not a user cancellation.  ComfyUI
                # owns the accepted prompt and can continue independently;
                # leave the Redis PEL entry unACKed so startup reconciliation
                # resumes polling this exact prompt without resubmitting it.
                _acked_locally = True
                if job_tracker:
                    job_tracker.update_fields(
                        job_id,
                        restart_recovery="pending_controller_restart",
                        comfyui_prompt_id=job.get("comfyui_prompt_id"),
                    )
                logger.info(
                    "Worker-%s: preserving forwarded ComfyUI job %s for controller restart "
                    "(prompt_id=%s)",
                    worker_id,
                    job_id,
                    job.get("comfyui_prompt_id"),
                )
                raise
            planned = bool(
                event_bus is not None
                and event_bus.is_planned_stop(self.service_name)
            )
            native_owned = bool(job.get("request_kind") == "audio_cpp_task"
                                and self.service_config.get("native_task_host_url"))
            requeued = False
            if (planned or native_owned) and entry_id and async_queue:
                requeued = await asyncio.shield(
                    async_queue.yield_pending(
                        self.service_name,
                        entry_id,
                        routing_group=job_rg,
                    )
                )
            if requeued:
                _acked_locally = True
                if job_tracker:
                    job_tracker.update_status(
                        job_id,
                        "queued",
                        requeued_from=self.service_name,
                        error=f"requeued: planned_stop cancelled {self.service_name}",
                    )
                logger.info(
                    f"Worker-{worker_id}: yielded cancelled planned-stop job "
                    f"{job_id} from {self.service_name}"
                )
            elif native_owned:
                # Retain the PEL entry if Redis could not requeue it. A new
                # worker must reconnect to the owned task, not terminalize it.
                _acked_locally = True
                if job_tracker:
                    job_tracker.update_fields(job_id, native_task_state="observer_disconnected")
            else:
                logger.warning(
                    f"Worker-{worker_id}: cancelled while processing {job_id} "
                    f"on {self.service_name}"
                )
                if job_tracker:
                    job_tracker.update_status(
                        job_id,
                        "cancelled",
                        error=f"worker cancelled on {self.service_name}",
                    )
            raise
        except Exception as e:
            error_str = str(e)
            logger.error(f"Worker-{worker_id}: forwarding failed for {job_id}: {e}")
            # Phase 2: opportunistic OOM detection on generic exception path.
            # Catches things like connection resets, asyncio timeouts, or
            # proxies that swallowed a backend 5xx into an exception.
            try:
                _oom_gpu_id2 = (self.service_config or {}).get("gpu_id", "") or "gpu_primary"
                _oom_info2 = _detect_oom_in_history(
                    status_str="error",
                    response_body=error_str,
                    status_code=0,
                )
                if _oom_info2 is not None:
                    _handle_oom_event(
                        gpu_id=_oom_gpu_id2,
                        service_name=self.service_name,
                        job_id=job_id,
                        detection_source="worker_exception",
                        reason=_oom_info2.get("reason", "oom detected in exception"),
                        details=str(_oom_info2.get("details", ""))[:500],
                    )
            except Exception as _oom_hook_err2:
                logger.debug(f"Worker-{worker_id}: oom detection hook (exception path) failed: {_oom_hook_err2}")
            # A planned bundle transition is not a backend failure.  If the
            # service was intentionally stopped between claim and forward,
            # return the job to its logical routing stream so CPU/secondary GPU or the
            # post-swap worker can complete it.  Do not fail, nack, or trigger
            # crash recovery for this expected connection refusal.
            planned_stop = (
                event_bus is not None
                and event_bus.is_planned_stop(self.service_name)
            )
            connection_refused = (
                "Connection refused" in error_str
                or "Connection reset by peer" in error_str
                or "ClientConnectorError" in error_str
                or "Cannot connect to host" in error_str
            )
            swap_owned_gpu = False
            if connection_refused and self.service_config:
                try:
                    _swap_gpu_id = self.service_config.get("gpu_id")
                    _swap_state = _get_gpu_state(_swap_gpu_id) if _swap_gpu_id else None
                    _swap_bundle = getattr(_swap_state, "loaded_bundle", "") if _swap_state else ""
                    if isinstance(_swap_bundle, str) and _swap_bundle.startswith("llm:"):
                        _swap_bundle = _swap_bundle[4:]
                    swap_owned_gpu = bool(
                        _swap_bundle
                        and not _swap_bundle.lower().startswith("gemma")
                        and str(job_rg).lower() == "gemma"
                    )
                except Exception:
                    swap_owned_gpu = False
            if (planned_stop or swap_owned_gpu) and connection_refused and entry_id and async_queue:
                try:
                    requeued = await async_queue.yield_pending(
                        self.service_name, entry_id, routing_group=job_rg
                    )
                    if requeued:
                        if job_tracker:
                            job_tracker.update_status(
                                job_id, "queued",
                                requeued_from=self.service_name,
                                error=f"requeued: planned_stop on {self.service_name}",
                            )
                        logger.info(
                            f"Worker-{worker_id}: requeued {job_id} from planned-stop "
                            f"{self.service_name} to logical group {job_rg}"
                        )
                        return
                except Exception as requeue_error:
                    logger.warning(
                        f"Worker-{worker_id}: planned-stop requeue failed for "
                        f"{job_id}: {requeue_error}; treating as failure"
                    )

            if queue_metrics:
                loop = asyncio.get_event_loop()
                await loop.run_in_executor(
                    None, queue_metrics.record_failure, self.service_name, str(type(e).__name__))
            # Force-recover the service on any error (OOM, 5xx, crash, etc.)
            # The user wants GPU state reset after job failures — desktop
            # processes are preserved because we only stop the service's
            # own systemd unit, not the GPU's processes globally.
            try:
                recovery = await _force_recover_failed_service(
                    self.service_name, job_id, error_str
                )
                if recovery.get("ok"):
                    logger.warning(
                        f"Worker-{worker_id}: force-recovery actions for {self.service_name}: "
                        f"{recovery.get('actions', [])}"
                    )
            except Exception as rec_err:
                logger.error(
                    f"Worker-{worker_id}: force-recovery failed for {self.service_name}: {rec_err}"
                )
            _retry_number = int(job.get("_nack_count", 0) or 0) + 1
            _nack_ok = False
            if entry_id and async_queue:
                _nack_ok = bool(
                    await async_queue.nack(
                        self.service_name,
                        entry_id,
                        routing_group=job_rg, max_retries=4,
                    )
                )
            if _nack_ok and _retry_number < 4:
                if job_tracker:
                    job_tracker.update_status(
                        job_id,
                        "queued",
                        error=(
                            f"retry {_retry_number}/4 after {self.service_name} "
                            f"forward failure: {error_str}"
                        ),
                    )
                logger.info(
                    f"Worker-{worker_id}: retrying {job_id} after forward "
                    f"failure ({_retry_number}/4); terminal state withheld"
                )
                return
            if job_tracker:
                job_tracker.update_status(job_id, "failed", error=error_str)
            raise

        finally:
            # S4: stamp activity on completion so the auto-evict clock
            # measures from "bundle is no longer being used" not
            # "bundle is about to be used". Matches M3's start stamp.
            try:
                _svc_gpu = (self.service_config or {}).get("gpu_id")
                if _svc_gpu:
                    _gs = _get_gpu_state(_svc_gpu)
                    if _gs is not None:
                        _gs.touch_activity(
                            source=f"worker_complete:{job.get('id', '')}"
                        )
            except Exception:
                pass  # activity stamp is best-effort
            if not _acked_locally and entry_id and async_queue:
                # Phase 5.2.79 (R3): only ack here if no in-body ack already ran.
                # XACK is idempotent in Redis, but the swallow of any redis-jitter
                # exception is required so a finally fault doesn't convert a
                # clean `return` into a propagated exception.
                try:
                    await async_queue.ack(self.service_name, f"worker", entry_id,
                                           routing_group=job_rg)
                except Exception:
                    pass
            # Bridge serial warm batches across the brief gap between this
            # terminal commit and the next HTTP submit. Without this lease the
            # idle-service monitor can begin restore_prep one second before the
            # next row acquires its own admission fence.
            if self.service_name == "comfyui" and job_tracker:
                try:
                    _tracked = job_tracker.get_job(job_id)
                    _terminal_status = (
                        _tracked.get("status")
                        if isinstance(_tracked, dict)
                        else getattr(_tracked, "status", "")
                    )
                    _arm_comfyui_warm_handoff(job_id, str(_terminal_status or ""))
                except Exception as _handoff_exc:
                    logger.debug(
                        f"Worker-{worker_id}: warm handoff lease skipped for "
                        f"{job_id}: {_handoff_exc}"
                    )

            # Phase 5.2.36 Bug C: decrement worker_in_flight. The outer
            # try-block's finally handles exception/early-return paths;
            # this is the normal completion path. _pool_gs is None
            # if the worker didn't reach the increment (e.g. bundle
            # reservation failed at line 7293).
            if _pool_gs is not None and _pool_lease_held:
                _pool_gs.worker_in_flight = max(0, _pool_gs.worker_in_flight - 1)
                _pool_lease_held = False
                logger.debug(
                    f"Worker-{worker_id}: worker_in_flight={_pool_gs.worker_in_flight} "
                    f"(decremented) on {_pool_gpu}"
                )
            if locals().get("_comfyui_job_admission_held", False):
                _release_comfyui_admission(job_id)


class WorkerSupervisor:
    """Manages dynamic worker pools per service.

    Event-driven: ServiceEventBus notifies of state changes → supervisor
    spawns/kills pools immediately.

    Fallback: every 5 seconds, validates pool state against actual health.
    """

    def __init__(self, session: ClientSession, coordinator_admission=None):
        self.session = session
        # Explicitly injected parent handoff; absent in the default controller
        # so ordinary workers do not create a second workflow authority.
        self.coordinator_admission = coordinator_admission
        self._pools: dict[str, WorkerPool] = {}
        # Phase 5.2.34 Bug A: keep strong refs to pool.run() tasks so they
        # aren't GC'd while workers are polling. asyncio only holds weak
        # refs to create_task() results; without this, the worker_loop
        # tasks die and jobs sit in queue:comfyui-gen forever.
        self._pool_tasks: dict[str, asyncio.Task] = {}
        self._running = False

    def _build_pipeline_runner(self):
        """Build a provider runner from the current declarative registry."""

        services_config = _services_config or _load_services_config()
        try:
            return _build_pipeline_dispatch_runner(
                services_config,
                _get_pipeline_provider_registry(),
                self.session,
                max_retries=3,
                max_loop_count=1,
                execution_mode="generic",
            )
        except Exception as exc:
            # A registry error must not prevent ordinary LLM pools from
            # starting.  Pipeline jobs fail closed at their dispatch boundary
            # until the next pool recreation/reload supplies a valid runner.
            logger.error("WorkerSupervisor: pipeline runner unavailable: %s", exc)
            return None

    def _new_pool(self, service_name: str, service_config: dict, slots: int) -> WorkerPool:
        return WorkerPool(
            service_name,
            service_config,
            slots,
            self.session,
            pipeline_dispatch_runner=self._build_pipeline_runner(),
            coordinator_admission=self.coordinator_admission,
        )

    async def _backend_failure_facts(self, service_config: dict) -> dict:
        """Return positive systemd failure evidence without changing lifecycle state."""
        unit = service_config.get("systemd_unit")
        if not isinstance(unit, str) or not unit.endswith(".service"):
            return {"confirmed_failed": False}
        try:
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "show", "--no-pager",
                "--property=ActiveState,SubState,Result,ExecMainCode,ExecMainStatus",
                unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL,
            )
            stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=3)
            if proc.returncode != 0:
                return {"confirmed_failed": False}
            facts = {}
            for line in stdout.decode("utf-8", "replace").splitlines():
                key, sep, value = line.partition("=")
                if sep:
                    facts[key] = value.strip()
            active_state = facts.get("ActiveState", "")
            sub_state = facts.get("SubState", "")
            result = facts.get("Result", "")
            restart_window_death = (
                sub_state == "auto-restart"
                and result in {"signal", "exit-code", "core-dump"}
            )
            failed = active_state == "failed" or result == "oom-kill" or restart_window_death
            return {
                "confirmed_failed": failed,
                "active_state": active_state,
                "sub_state": sub_state,
                "result": result,
                "exec_main_code": facts.get("ExecMainCode", ""),
                "exec_main_status": facts.get("ExecMainStatus", ""),
                "unit": unit,
            }
        except Exception:
            # A failed probe is not proof of backend death. Keep work owned.
            return {"confirmed_failed": False}

    async def _terminalize_accepted_backend_jobs(
        self, service_name: str, service_config: dict, facts: dict
    ) -> None:
        """Fail only accepted coordinator children still owned by this service slot."""
        if not facts.get("confirmed_failed") or not job_tracker or async_slot_manager is None:
            return
        unit = str(facts.get("unit") or service_config.get("systemd_unit") or "unknown unit")
        result = str(facts.get("result") or "failed")
        detail = (
            f"Backend {service_name} ({unit}) confirmed failed: "
            f"systemd result={result}, active_state={facts.get('active_state', 'unknown')}"
        )[:500]
        try:
            slots = await async_slot_manager.get_slots(service_name)
        except Exception:
            return
        owned_ids = {
            str(slot.get("job_id") or "")
            for slot in (slots or {}).values()
            if isinstance(slot, dict) and slot.get("status") == "busy" and slot.get("job_id")
        }
        for job_id in owned_ids:
            try:
                tracked = _coordinator_job_dict(job_tracker.get_job(job_id)) or {}
                if (
                    tracked.get("status") != "in_flight"
                    or tracked.get("service_name") != service_name
                    or tracked.get("source") != "pipeline_coordinator_child"
                ):
                    continue
                # Re-read before writing so terminal/cancelled/successor state wins.
                current = _coordinator_job_dict(job_tracker.get_job(job_id)) or {}
                if (
                    current.get("status") != "in_flight"
                    or current.get("service_name") != service_name
                    or current.get("source") != "pipeline_coordinator_child"
                ):
                    continue
                job_tracker.update_status(
                    job_id,
                    "failed",
                    error=detail,
                    error_type="backend_died",
                    backend_service=service_name,
                    backend_unit=unit,
                    backend_systemd_result=result[:100],
                    backend_active_state=str(facts.get("active_state") or "")[:40],
                )
            except Exception as exc:
                logger.warning(
                    "Supervisor: could not terminalize accepted child %s after %s failure: %s",
                    job_id, service_name, type(exc).__name__,
                )

    async def run(self):
        """Event-driven pool management with periodic validation."""
        self._running = True
        logger.info("WorkerSupervisor: starting")

        logger.info(
            "WorkerSupervisor startup grace: waiting %.1fs before pool bootstrap",
            GPU_PROBE_STARTUP_GRACE_S,
        )
        try:
            await asyncio.sleep(GPU_PROBE_STARTUP_GRACE_S)
        except asyncio.CancelledError:
            # Cancellation during the startup grace used to escape before the
            # supervisor's main-loop cleanup path, leaving pool/task state
            # ambiguous during controller shutdown.  Treat it exactly like a
            # normal supervisor cancellation; no pools should be created yet.
            logger.info("WorkerSupervisor: cancelled during startup grace")
            self._running = False
            await self.shutdown()
            return

        # Initial bootstrap: check all services and spawn pools for healthy ones
        await self._validate_pools()

        while self._running:
            try:
                # PRIMARY: Wait for event-driven state changes
                if event_bus:
                    await event_bus.wait_for_change(timeout=5.0)

                    # Process any pending state changes
                    changed = event_bus.get_changed_services()
                    for svc_name, new_state in changed:
                        await self._handle_state_change(svc_name, new_state)

                # VALIDATION: Periodic health check (catches missed events)
                await self._validate_pools()

                # REAPER: Check for stale in_flight jobs
                await self._reap_stale_jobs()
                # SLOT REAPER: Force-release slots stuck busy beyond their lease
                await self._reap_stale_slots()
                # SLOT RECONCILE: Fix SlotManager drift from semaphore reality
                await self._reconcile_slots()

            except asyncio.CancelledError:
                logger.info("WorkerSupervisor: cancelled")
                self._running = False
                await self.shutdown()
                break
            except Exception as e:
                logger.error(f"WorkerSupervisor error: {e}")
                await asyncio.sleep(5)

        logger.info("WorkerSupervisor: stopped")

    async def shutdown(self):
        """Graceful shutdown: stop accepting, wait for in-flight."""
        self._running = False

        shutdown_tasks = []
        for pool in self._pools.values():
            shutdown_tasks.append(asyncio.create_task(pool.shutdown()))

        if shutdown_tasks:
            done, pending = await asyncio.wait(shutdown_tasks, timeout=30)
            if pending:
                logger.warning(f"Supervisor: {len(pending)} pools still active after 30s timeout")

        # Phase 5.2.34 Bug A: cancel pool.run() tasks too.
        for task in list(self._pool_tasks.values()):
            if not task.done():
                task.cancel()
        self._pool_tasks.clear()
        self._pools.clear()
        logger.info("WorkerSupervisor: shutdown complete")

    async def _handle_state_change(self, svc_name: str, new_state: str):
        """React to a service state change immediately."""
        cfg = _services_config.get("services", {}).get(svc_name, {})

        # The durable combined-Gemma broker is the sole consumer of the
        # logical queue when explicitly enabled.  Concrete service pins still
        # use the existing per-GPU/direct paths; only shared-group WorkerPools
        # are suppressed here.
        if _combined_gemma_broker_owns_service(svc_name, cfg):
            if svc_name in self._pools:
                await self._pools[svc_name].shutdown()
                self._pool_tasks.pop(svc_name, None)
                del self._pools[svc_name]
            return

        if _is_internal_workflow_service(cfg):
            desired_workers = int(
                cfg.get("worker_parallel", cfg.get("queue_parallel", 1))
            )
            if svc_name not in self._pools:
                pool = self._new_pool(svc_name, cfg, desired_workers)
                self._pools[svc_name] = pool
                self._pool_tasks[svc_name] = asyncio.create_task(pool.run())
                logger.info(
                    "Supervisor: %s internal adapter -> spawned %s workers",
                    svc_name,
                    desired_workers,
                )
            elif self._pools[svc_name].desired_slots != desired_workers:
                self._pools[svc_name].resize(desired_workers)
            return

        if cfg.get("type") not in ("llm_backend", "generation_backend") or not cfg.get("enabled"):
            # Non-LLM or disabled — kill pool if exists
            if svc_name in self._pools:
                await self._pools[svc_name].shutdown()
                self._pool_tasks.pop(svc_name, None)
                del self._pools[svc_name]
            return

        if new_state == "healthy":
            desired_workers = int(cfg.get("worker_parallel", cfg.get("queue_parallel", cfg.get("parallel", 1))))

            if svc_name not in self._pools:
                # Service came up — spawn queue workers. This is deliberately
                # separate from the backend model's --parallel slot count so a
                # slow CPU fallback can keep multiple llama-server slots/context
                # without GPUManager feeding every slot concurrently.
                slots = desired_workers
                pool = self._new_pool(svc_name, cfg, slots)
                self._pools[svc_name] = pool
                self._pool_tasks[svc_name] = asyncio.create_task(pool.run())
                logger.info(f"Supervisor: {svc_name} healthy -> spawned {slots} workers")
            elif self._pools[svc_name].desired_slots != desired_workers:
                # Queue worker count changed — resize.
                self._pools[svc_name].resize(desired_workers)

        elif new_state in ("unhealthy", "stopping"):
            if svc_name in self._pools:
                # Phase 5.1.5: if we asked systemd to stop this service
                # ourselves (evict_first / evict_llm / _unload_bundle /
                # evict_for_vram), the "unhealthy" probe is the EXPECTED
                # outcome of our own action — not a crash. Defer the
                # pool shutdown so we don't tear down a freshly-spawned
                # worker pool for a different service whose port briefly
                # flapped during the systemd stop cascade.
                if event_bus is not None and event_bus.is_planned_stop(svc_name):
                    logger.info(
                        f"Supervisor: {svc_name} {new_state} -> planned_stop within "
                        f"grace, NOT shutting down pool"
                    )
                    # Don't kill the pool. The systemd stop we initiated
                    # will eventually take the service down; the OOM
                    # recovery / watchdog paths will handle any genuine
                    # failure that follows the planned_stop window.
                    return
                logger.info(f"Supervisor: {svc_name} {new_state} -> shutting down pool")
                # Rebalance queue before shutting down
                await self._rebalance_queue(svc_name)
                await self._pools[svc_name].shutdown()
                self._pool_tasks.pop(svc_name, None)
                del self._pools[svc_name]

        elif new_state == "starting":
            pass  # Don't spawn yet — wait for "healthy"

    @staticmethod
    def _needs_bundle_cold_start_pool(svc_name: str, svc_cfg: dict) -> bool:
        """Whether a stopped generation service needs a worker to admit its first bundled job."""
        if svc_cfg.get("type") != "generation_backend" or not svc_cfg.get("enabled"):
            return False
        templates = _services_config.get("generation_templates", {}) or {}
        return any(
            isinstance(template, dict)
            and template.get("backend") == svc_name
            and bool(template.get("bundle"))
            for template in templates.values()
        )

    async def _validate_pools(self):
        """Periodic health validation — catches anything events missed."""
        services = _services_config.get("services", {})

        for svc_name, svc_cfg in services.items():
            if _combined_gemma_broker_owns_service(svc_name, svc_cfg):
                if svc_name in self._pools:
                    await self._pools[svc_name].shutdown()
                    self._pool_tasks.pop(svc_name, None)
                    del self._pools[svc_name]
                continue
            if svc_cfg.get("type") == "orchestrator":
                has_pool = svc_name in self._pools
                if _is_internal_workflow_service(svc_cfg):
                    desired_workers = int(
                        svc_cfg.get(
                            "worker_parallel", svc_cfg.get("queue_parallel", 1)
                        )
                    )
                    if not has_pool:
                        pool = self._new_pool(svc_name, svc_cfg, desired_workers)
                        self._pools[svc_name] = pool
                        self._pool_tasks[svc_name] = asyncio.create_task(pool.run())
                        logger.info(
                            "Supervisor: %s internal adapter -> spawned %s workers",
                            svc_name,
                            desired_workers,
                        )
                    elif self._pools[svc_name].desired_slots != desired_workers:
                        self._pools[svc_name].resize(desired_workers)
                elif has_pool:
                    await self._pools[svc_name].shutdown()
                    self._pool_tasks.pop(svc_name, None)
                    del self._pools[svc_name]
                continue
            if svc_cfg.get("type") not in ("llm_backend", "generation_backend") or not svc_cfg.get("enabled"):
                continue

            has_pool = svc_name in self._pools
            port = svc_cfg.get("port")
            # Respect per-service health_path (some backends
            # use "/").  Falling back to "/health" preserves the old
            # behaviour for services that don't set the field.
            health_path = svc_cfg.get("health_path") or "/health"
            is_healthy = await self._check_health(port, health_path=health_path)

            if not is_healthy and not (
                event_bus is not None and event_bus.is_planned_stop(svc_name)
            ):
                failure_facts = await self._backend_failure_facts(svc_cfg)
                await self._terminalize_accepted_backend_jobs(
                    svc_name, svc_cfg, failure_facts
                )

            if is_healthy:
                # Phase 5.2.6: clear any leftover planned_stop stamp. The
                # 5.1.5 design relied on TTL expiry, but the probe-side
                # re-stamp at line ~7654 prevented that, leaving the pool
                # as a permanent zombie. Now we clear on recovery so a
                # real crash after a successful stop is not silently
                # swallowed.
                if event_bus is not None and event_bus.is_planned_stop(svc_name):
                    event_bus.clear_planned_stop(svc_name)
                    logger.debug(
                        f"supervisor: cleared planned_stop on healthy {svc_name}"
                    )

            if is_healthy and not has_pool:
                logger.warning(f"Supervisor: {svc_name} healthy but no pool (missed event) -> spawning")
                slots = int(svc_cfg.get("worker_parallel", svc_cfg.get("queue_parallel", svc_cfg.get("parallel", 1))))
                pool = self._new_pool(svc_name, svc_cfg, slots)
                self._pools[svc_name] = pool
                self._pool_tasks[svc_name] = asyncio.create_task(pool.run())

            elif not is_healthy and not has_pool and self._needs_bundle_cold_start_pool(svc_name, svc_cfg):
                # Bundle-backed generation starts are worker-owned: the poller must
                # survive while the backend is stopped so it can claim the first job
                # and drive bundle admission/readiness itself.
                slots = int(svc_cfg.get("worker_parallel", svc_cfg.get("queue_parallel", svc_cfg.get("parallel", 1))))
                pool = self._new_pool(svc_name, svc_cfg, slots)
                self._pools[svc_name] = pool
                self._pool_tasks[svc_name] = asyncio.create_task(pool.run())
                logger.info(f"Supervisor: {svc_name} stopped but bundle-backed -> spawned cold-start pool")

            elif not is_healthy and has_pool:
                if self._needs_bundle_cold_start_pool(svc_name, svc_cfg):
                    # Keep the admission poller alive across normal bundle teardown
                    # and cold idle; it is the only path that can start this backend.
                    continue
                # Planned-stop guard. An intentional stop may briefly make
                # its health probe fail; defer pool shutdown for the original
                # bounded grace window. Do not renew the timestamp here: a
                # stopped or crashed service must eventually leave grace so
                # crash recovery can own the restart.
                if event_bus is not None and event_bus.is_planned_stop(svc_name):
                    logger.info(
                        f"supervisor: skipping pool shutdown for {svc_name} "
                        f"(planned_stop grace active)"
                    )
                    continue
                # Phase 7 (OOM fix 3): do NOT kill the pool if an OOM
                # recovery is actively in progress. The recovery pipeline
                # may have legitimately drained the service (e.g. unloaded
                # the model, restarted systemd unit) and a transient
                # unhealthy probe in that window would otherwise race the
                # recovery into a full pool shutdown. TTL-escape via
                # OOM_SUPERVISOR_TTL_S so a stuck recovery still gets
                # force-killed eventually.
                _bs = _gpu_states.get(svc_cfg.get("gpu_id", "gpu_primary"))
                if _bs is not None and _bs.oom_state in (
                    "detected", "draining", "verifying", "recovering"
                ):
                    _age = time.time() - float(_bs.oom_state_changed_at or 0.0)
                    if _age < OOM_SUPERVISOR_TTL_S:
                        logger.info(
                            f"supervisor: skipping pool shutdown (OOM recovery in progress, age={_age:.1f}s)"
                        )
                        continue
                    logger.warning(
                        f"supervisor: OOM recovery stuck for {_age:.1f}s (>= {OOM_SUPERVISOR_TTL_S}s), forcing pool shutdown"
                    )
                logger.warning(f"Supervisor: {svc_name} unhealthy but pool exists (missed event) -> shutting down")
                await self._pools[svc_name].shutdown()
                self._pool_tasks.pop(svc_name, None)
                del self._pools[svc_name]

    async def _check_health(self, port: int | None,
                            health_path: str = "/health",
                            fallback_tcp: bool = True) -> bool:
        """Probe service liveness on *port*.

        PR4 fix: respect the per-service ``health_path`` advertised by
        services.json (e.g. ``stable-diffusion.cpp`` uses ``"/"``,
        comfyui/gemma use ``"/health"``).  The previous hardcoded
        ``/health`` returned 404 for backends like stable-diffusion.cpp
        whose only 200 is the root, causing the WorkerSupervisor's
        periodic ``_validate_pools`` to mark a freshly-spawned pool as
        ``unhealthy`` and shut it down within the same loop tick (the
        race behind the "consumer registered but never reads" symptom:
        spawn → validate-kill → PEL entry orphaned).

        When ``fallback_tcp`` is True and the HTTP probe fails or
        returns non-200, we accept a successful raw TCP connect as
        evidence the port is up.  This matches the LoadBundle "port
        ready" check the EventBus uses to emit ``healthy`` in the
        first place — keeping the event-driven spawn and the periodic
        re-validation in agreement so they don't fight each other.
        """
        if not port:
            return False
        # Use a non-2xx-acceptable probe first so a 200 root works
        # identically to a 200 health path.
        try:
            async with self.session.get(
                f"http://127.0.0.1:{int(port)}{health_path}",
                timeout=ClientTimeout(total=2),
            ) as resp:
                if resp.status == 200:
                    return True
        except Exception:
            pass
        if not fallback_tcp:
            return False
        # Fallback: TCP connect to the port.  Matches LoadBundle's
        # port-readiness gate so EventBus-emitted "healthy" survives
        # the next _validate_pools sweep even when the backend has
        # no real /health endpoint.
        try:
            fut = asyncio.open_connection("127.0.0.1", int(port))
            reader, writer = await asyncio.wait_for(fut, timeout=2)
            writer.close()
            try:
                await writer.wait_closed()
            except Exception:
                pass
            return True
        except Exception:
            return False

    async def _reap_stale_jobs(self):
        """Mark in_flight jobs as failed if stuck > 5 minutes.

        Phase 5.2.1 Fix A: iterate the pool's `routing_groups` instead of
        querying the wrong stream (the queue for each routing_group is
        named `queue:{routing_group}`, NOT `queue:{service_name}`). The
        previous code looked at `queue:comfyui` (no entries) when comfyui
        jobs actually live on `queue:comfyui-gen`.

        Phase 5.2.1 P1 (adversarial): skip services in the planned_stop
        window — the dying worker is intentionally stopping, the reaper
        must not nack an entry the worker is mid-flight on.
        """
        if not job_tracker:
            return
        try:
            services = _services_config.get("services", {})
            for svc_name, svc_cfg in services.items():
                if not svc_cfg.get("enabled") or not (
                    svc_cfg.get("type") in ("llm_backend", "generation_backend")
                    or _is_internal_workflow_service(svc_cfg)
                ):
                    continue
                if not async_queue:
                    continue
                # Phase 5.2.1 P1: skip services in planned_stop window
                if event_bus is not None and event_bus.is_planned_stop(svc_name):
                    continue
                try:
                    # Phase 5.2.1 Fix A: pull the routing_groups from the live pool
                    pool = self._pools.get(svc_name)
                    if pool is not None and getattr(pool, "routing_groups", None):
                        routing_groups = list(pool.routing_groups)
                    else:
                        routing_groups = [None]
                    for rg in routing_groups:
                        pending = await async_queue.get_pending(svc_name, routing_group=rg)
                        pending_max_idle_ms = _pending_reaper_max_idle_ms(svc_cfg)
                        orphan_ttl_ms = _pending_orphan_ttl_ms(svc_cfg)
                        for p in pending:
                            # PEL idle proves that the claim stopped being renewed;
                            # stream ID age proves this is an old submission. Require
                            # both so a recently claimed/continued job is never requeued.
                            entry_age_ms = _pending_entry_submission_age_ms(
                                p.get("entry_id", ""),
                                submitted_at_ms=p.get("entry_created_ms"),
                            )
                            if p.get("idle_ms", 0) > pending_max_idle_ms:
                                entry_id = p.get("entry_id", "")
                                job_id = str(p.get("job_id") or "")
                                if not job_id or job_tracker is None:
                                    logger.info(
                                        "Reaper: preserving %s on %s/%s; ownership evidence unavailable",
                                        entry_id, svc_name, rg,
                                    )
                                    continue
                                try:
                                    tracked_job = await asyncio.to_thread(
                                        job_tracker.get_job, job_id
                                    )
                                    if not tracked_job:
                                        logger.info(
                                            "Reaper: preserving %s on %s/%s; tracker unreadable or missing",
                                            entry_id, svc_name, rg,
                                        )
                                        continue
                                    active_slot = False
                                    if async_slot_manager is not None:
                                        slots = await async_slot_manager.get_slots(svc_name)
                                        active_slot = any(
                                            isinstance(slot, dict)
                                            and slot.get("status") == "busy"
                                            and str(slot.get("job_id") or "") == job_id
                                            for slot in slots.values()
                                        )
                                    recovery_active = job_id in _active_recovery_job_ids()
                                    if active_slot or recovery_active:
                                        logger.info(
                                            "Reaper: preserving %s on %s/%s; active slot/recovery owns job=%s",
                                            entry_id, svc_name, rg, job_id,
                                        )
                                        continue
                                    if tracked_job.get("status") in {
                                        "completed", "failed", "cancelled", "dead_lettered",
                                    }:
                                        logger.info(
                                            "Reaper: preserving %s on %s/%s; tracker is terminal (%s)",
                                            entry_id, svc_name, rg, tracked_job.get("status"),
                                        )
                                        continue
                                    if tracked_job.get("status") != "in_flight":
                                        logger.info(
                                            "Reaper: preserving %s on %s/%s; tracker status is not reclaimable (%r)",
                                            entry_id, svc_name, rg, tracked_job.get("status"),
                                        )
                                        continue
                                except Exception:
                                    logger.exception(
                                        "Reaper: preserving %s; ownership inspection failed",
                                        entry_id,
                                    )
                                    continue
                                logger.warning(
                                    f"Reaper: stuck job {entry_id} on "
                                    f"{svc_name}/{rg} (idle {p['idle_ms']}ms), nacking"
                                )
                                # Recently submitted stuck work keeps its retry
                                # budget. Once the submission-age TTL expires, do
                                # not resurrect an orphan that can evict idle baselines.
                                retry_budget = 1 if entry_age_ms >= orphan_ttl_ms else 4
                                recovered = await async_queue.nack(
                                    svc_name, entry_id,
                                    routing_group=rg,
                                    max_retries=retry_budget,
                                    dead_letter_reason=(
                                        "stale_orphan_ttl" if retry_budget == 1 else None
                                    ),
                                    orphan_tracker_key=(
                                        job_tracker._key(job_id) if retry_budget == 1 else None
                                    ),
                                    orphan_slot_key=(
                                        async_slot_manager._key(svc_name)
                                        if retry_budget == 1 and async_slot_manager is not None
                                        else None
                                    ),
                                    minimum_idle_ms=(
                                        pending_max_idle_ms if retry_budget == 1 else None
                                    ),
                                )
                                if recovered and retry_budget == 1:
                                    logger.info("Reaper: terminalized expired orphan job=%s", job_id)
                except Exception:
                    pass
        except Exception as e:
            logger.debug(f"Reaper error: {e}")


    async def _reap_stale_slots(self):
        """Force-release SlotManager entries that have been busy too long."""
        if not slot_manager:
            return
        try:
            services = _services_config.get("services", {})
            loop = asyncio.get_event_loop()
            for svc_name, svc_cfg in services.items():
                if svc_cfg.get("type") not in ("llm_backend", "generation_backend") or not svc_cfg.get("enabled"):
                    continue
                # Lease TTL = forward_timeout + 60s buffer
                # Phase 5.2.8: also include post_load_grace_seconds so
                # services that sleep after bundle load (e.g. ComfyUI's
                # 90s grace for ComfyRegistry fetch + HTTP handler warmup)
                # are not reaped while the grace is still in effect.
                # For comfyui (forward_timeout=90, post_load_grace_seconds=90):
                #   max_age = 90 + 60 + 90 = 240s
                # For services with grace=0 (legacy): unchanged.
                # Defensive `or 0` cast handles None / "" / missing key
                # safely (same pattern as the worker post-load grace at
                # line ~7149). Without it, a bad config raises TypeError
                # inside `int()` which is swallowed by the broad
                # `except Exception` at the bottom of this function —
                # leaving the reaper stuck on that service forever.
                max_age = _slot_reaper_max_age(svc_cfg)

                reaped = await loop.run_in_executor(
                    None, slot_manager.reap_stale_slots, svc_name, max_age,
                )
                if reaped:
                    for r in reaped:
                        logger.warning(
                            "SlotReaper: force-released %s slot %s (job %s, age %.0fs)",
                            svc_name, r["slot_id"], r["job_id"], r["age_seconds"],
                        )
                        # Also update job tracker if present
                        if job_tracker and r["job_id"]:
                            try:
                                job_tracker.update_status(
                                    r["job_id"], "failed",
                                    error=f"Slot lease expired after {r['age_seconds']:.0f}s",
                                )
                            except Exception:
                                pass
        except Exception as e:
            logger.error(f"SlotReaper error: {e}")

    async def _reconcile_slots(self):
        """Compare SlotManager busy count vs WorkerPool semaphore state. Reset if drifted."""
        if not slot_manager:
            return
        try:
            services = _services_config.get("services", {})
            loop = asyncio.get_event_loop()
            for svc_name, svc_cfg in services.items():
                if svc_cfg.get("type") != "llm_backend" or not svc_cfg.get("enabled"):
                    continue
                if svc_name not in self._pools:
                    continue

                pool = self._pools[svc_name]
                port = svc_cfg.get("port")
                # PR4 fix: respect per-service health_path.
                health_path = svc_cfg.get("health_path") or "/health"
                is_healthy = await self._check_health(port, health_path=health_path)
                if not is_healthy:
                    continue

                actual_free = pool.slots_free
                actual_total = pool.slots_total
                actual_busy = actual_total - actual_free

                redis_slots = await loop.run_in_executor(
                    None, slot_manager.get_slots, svc_name,
                )
                redis_busy = 0
                for v in redis_slots.values():
                    if isinstance(v, dict) and v.get("status") == "busy":
                        redis_busy += 1
                    elif isinstance(v, str):
                        try:
                            d = json.loads(v)
                            if d.get("status") == "busy":
                                redis_busy += 1
                        except Exception:
                            pass

                if redis_busy > actual_busy:
                    logger.warning(
                        "SlotReconcile: %s SlotManager says %d busy, semaphore says %d busy - resetting",
                        svc_name, redis_busy, actual_busy,
                    )
                    await loop.run_in_executor(
                        None, self._reset_slots_to_match, svc_name, actual_busy, actual_total,
                    )
        except Exception as e:
            logger.error(f"SlotReconcile error: {e}")

    def _reset_slots_to_match(self, service_name: str, actual_busy: int, actual_total: int):
        """Reset SlotManager to match local pool semaphore state."""
        if not slot_manager:
            return
        try:
            key = slot_manager._key(service_name)
            all_slots = slot_manager.r.hgetall(key)
            pipe = slot_manager.r.pipeline()
            for slot_id_str in all_slots:
                pipe.hset(key, slot_id_str, json.dumps({
                    "job_id": "",
                    "started_at": "",
                    "status": "free",
                }))
            pipe.execute()
            logger.info("SlotReconcile: %s reset all %d slots to free (semaphore had %d busy)",
                         service_name, actual_total, actual_busy)
        except Exception as e:
            logger.error("SlotReconcile: failed to reset %s: %s", service_name, e)


    async def _rebalance_queue(self, dead_service: str):
        """Move queued jobs from dead service to healthy routing group members."""
        cfg = _services_config.get("services", {}).get(dead_service, {})
        group = cfg.get("routing_group")
        if not group or not async_queue or not routing_engine:
            return

        # Find healthy alternatives
        members = routing_engine.get_group_members(group)
        healthy = []
        for m in members:
            svc = m["service"]
            if svc == dead_service:
                continue
            svc_cfg_for_health = _services_config.get("services", {}).get(svc, {})
            if not _MEMBER_REPORTER.probeable(svc, svc_cfg_for_health):
                continue
            port = svc_cfg_for_health.get("port")
            # PR4 fix: respect per-service health_path.
            health_path = svc_cfg_for_health.get("health_path") or "/health"
            if await self._check_health(port, health_path=health_path):
                healthy.append(svc)

        if not healthy:
            logger.warning(f"Rebalance: no healthy alternatives for {dead_service}")
            return

        # Drain the dead service's queue and re-enqueue to alternatives
        depth = await async_queue.get_queue_depth(dead_service)
        if depth == 0:
            return

        logger.info(f"Rebalance: moving {depth} jobs from {dead_service} -> {healthy}")
        moved = 0
        for i in range(depth):
            try:
                jobs = await async_queue.dequeue(dead_service, "rebalancer", count=1)
                if not jobs:
                    break
                job = jobs[0]
                target = healthy[moved % len(healthy)]  # Round-robin
                await async_queue.enqueue(target, job)
                entry_id = job.get("_entry_id")
                if entry_id:
                    await async_queue.ack(dead_service, "rebalancer", entry_id)
                moved += 1
            except Exception as e:
                logger.error(f"Rebalance error: {e}")
                break

        logger.info(f"Rebalance: moved {moved} jobs from {dead_service}")


# ── Model Validator ────────────────────────────────────────────────

class ModelValidator:
    """Prevents models from taking jobs they're too small/incapable to handle."""

    def __init__(self, providers_config: dict):
        self.providers = providers_config.get("providers", {})
        self.rules = {r["hint"]: r for r in providers_config.get("routing_rules", [])}

    def validate(self, model_id: str, task_hint: str = None,
                 requirements: dict = None) -> dict:
        """
        Returns: {"ok": bool, "action": "route"|"reject"|"upgrade",
                  "reason": str, "suggested_model": str|None}
        """
        if self._is_cloud_provider(model_id):
            return {"ok": True, "action": "route"}

        model = self._find_model(model_id)
        if not model:
            return {"ok": True, "action": "route"}

        if task_hint and task_hint in self.rules:
            rule = self.rules[task_hint]

            if ("require" in rule and model_id != rule["require"]
                    and self._find_model(rule["require"])):
                return {
                    "ok": False,
                    "action": "upgrade",
                    "reason": rule.get("reason", f"Task '{task_hint}' requires {rule['require']}"),
                    "suggested_model": rule["require"]
                }

            if "never_fallback_to" in rule and model_id in rule["never_fallback_to"]:
                preferred = rule.get("prefer", rule.get("require"))
                if not (preferred and self._find_model(preferred)):
                    preferred = None
            else:
                preferred = None
            if preferred:
                return {
                    "ok": False,
                    "action": "upgrade",
                    "reason": rule.get("reason", f"Model {model_id} blocked for '{task_hint}'"),
                    "suggested_model": preferred
                }

        caps = model.get("capabilities", {})

        if requirements:
            if requirements.get("min_context", 0) > model.get("context_length", 0):
                return {
                    "ok": False, "action": "reject",
                    "reason": f"Context {requirements['min_context']} exceeds model max {model['context_length']}"
                }

            if requirements.get("require_vision") and not caps.get("vision"):
                return {
                    "ok": False, "action": "reject",
                    "reason": "Task requires vision capability"
                }

        if requirements and requirements.get("min_complexity") == "high":
            if caps.get("min_complexity") == "low":
                better = self._eligible_upgrade(model_id, requirements)
                if better:
                    return {
                        "ok": False, "action": "upgrade",
                        "reason": f"{model_id} is too small for high-complexity work",
                        "suggested_model": better
                    }

        return {"ok": True, "action": "route"}

    def _eligible_upgrade(self, model_id: str, requirements: dict) -> str | None:
        """Largest-context local instance in this registry that is not low-complexity."""
        local = self.providers.get("local", {}).get("instances", {})
        best = None
        for name, inst in local.items():
            caps = inst.get("capabilities", {})
            if name == model_id or caps.get("min_complexity") == "low":
                continue
            if requirements.get("min_context", 0) > inst.get("context_length", 0):
                continue
            if requirements.get("require_vision") and not caps.get("vision"):
                continue
            key = (-inst.get("context_length", 0), name)
            if best is None or key < best[0]:
                best = (key, name)
        return best[1] if best else None

    def _find_model(self, model_id: str) -> dict | None:
        """Find a model across all providers (local + cloud)."""
        local = self.providers.get("local", {}).get("instances", {})
        if model_id in local:
            return local[model_id]

        if "/" in model_id:
            provider_name, model_name = model_id.split("/", 1)
            cloud = self.providers.get(provider_name, {})
            return cloud.get("models", {}).get(model_name)

        for provider_name, prov in self.providers.items():
            if provider_name == "local":
                continue
            if prov.get("type") == "cloud" and model_id in prov.get("models", {}):
                return prov["models"][model_id]

        return None

    def _is_cloud_provider(self, name: str) -> bool:
        """Check if name is a known cloud provider."""
        prov = self.providers.get(name, {})
        return prov.get("type") == "cloud"

    def get_fallback(self, task_hint: str) -> str | None:
        rule = self.rules.get(task_hint, {})
        if "fallback" in rule:
            return rule["fallback"]
        if "prefer" in rule:
            return rule["prefer"]
        return None


_model_validator: ModelValidator | None = None

# ── LLM Proxy Handlers ────────────────────────────────────────────

async def handle_liveness(request: web.Request):
    """GET /health/live — cheap process liveness for container supervision."""
    return web.json_response({"status": "ok"})


_OBSERVABILITY_EVENT_LIMIT = 500
_observability_events = deque(maxlen=_OBSERVABILITY_EVENT_LIMIT)
_observability_event_lock = Lock()
_observability_event_sequence = 0


def _record_transition_event(
    event_type: str,
    resource: str,
    from_state: str | None,
    to_state: str | None,
    *,
    transition: str | None = None,
) -> None:
    """Append a bounded, secret-free structured lifecycle/node event."""
    global _observability_event_sequence
    with _observability_event_lock:
        _observability_event_sequence += 1
        event = {
            "event_id": _observability_event_sequence,
            "timestamp": time.time(),
            "event_type": str(event_type)[:64],
            "resource": str(resource or "")[:128],
            "from_state": str(from_state)[:64] if from_state is not None else None,
            "to_state": str(to_state)[:64] if to_state is not None else None,
        }
        if transition is not None:
            event["transition"] = str(transition)[:64]
        _observability_events.append(event)
    logger.info("gpu_manager_transition %s", json.dumps(event, sort_keys=True, separators=(",", ":")))


def _transition_events(limit: int = 100) -> list[dict]:
    """Return a bounded copy of newest events, oldest first."""
    bounded = max(1, min(int(limit), _OBSERVABILITY_EVENT_LIMIT))
    with _observability_event_lock:
        return [dict(event) for event in list(_observability_events)[-bounded:]]


def _safe_counter(value: Any) -> int | None:
    if isinstance(value, bool):
        return None
    try:
        result = int(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return result if result >= 0 else None


def _gpu_capacity_snapshot(config: Any, telemetry: Any, observed_at: float) -> dict:
    """Project configured devices beside measured telemetry without inventing zeros."""
    devices = config.get("gpu_devices", {}) if isinstance(config, Mapping) else {}
    devices = devices if isinstance(devices, Mapping) else {}
    telemetry_ok = isinstance(telemetry, list)
    all_telemetry_rows = [row for row in telemetry if isinstance(row, Mapping)] if telemetry_ok else []

    def is_integrated_gpu(device: Mapping) -> bool:
        return device.get("gpu_type") == "iGPU" or device.get("integrated") is True

    # Integrated graphics remain in device/identity telemetry for display, but
    # they do not represent discrete accelerator capacity. Keep the filter
    # local to this capacity projection rather than changing _detect_gpus().
    integrated_rows = [row for row in all_telemetry_rows if is_integrated_gpu(row)]
    telemetry_rows = [row for row in all_telemetry_rows if not is_integrated_gpu(row)]
    rows: list[dict] = []
    matched_cards: set[str] = set()

    configured = list(devices.items())
    if not configured:
        configured = [
            (str(row.get("gpu_id") or row.get("card") or f"gpu-{index}"), {})
            for index, row in enumerate(telemetry_rows)
        ]
    else:
        def matches_integrated(device_id: Any, raw_config: Any) -> bool:
            config = raw_config if isinstance(raw_config, Mapping) else {}
            card = str(config.get("card") or "")
            pci = str(config.get("pci") or "").lower()
            if is_integrated_gpu(config):
                return True
            return any(
                (card and card == str(row.get("card") or ""))
                or str(device_id) == str(row.get("gpu_id") or "")
                or (pci and pci == str(row.get("pci_address") or "").lower())
                for row in integrated_rows
            )
        configured = [
            (device_id, config) for device_id, config in configured
            if not matches_integrated(device_id, config)
        ]

    for device_id, raw_config in configured:
        device_config = raw_config if isinstance(raw_config, Mapping) else {}
        card = str(device_config.get("card") or "")
        pci = str(device_config.get("pci") or "").lower()
        observed = next((row for row in telemetry_rows
                         if (card and row.get("card") == card)
                         or str(row.get("gpu_id") or "") == str(device_id)
                         or (pci and str(row.get("pci_address") or "").lower() == pci)), None)
        if observed is None:
            rows.append({
                "gpu_id": str(device_id),
                "status": "missing" if telemetry_ok else "unknown",
                "capacity_state": "unknown",
                "reason": "configured_device_not_observed" if telemetry_ok else "gpu_telemetry_unavailable",
                "vram_total_mib": None,
                "vram_used_mib": None,
                "vram_free_mib": None,
                "observed_at": observed_at if telemetry_ok else None,
            })
            continue

        if observed.get("card"):
            matched_cards.add(str(observed["card"]))
        total = _safe_counter(observed.get("vram_total_mib"))
        used = _safe_counter(observed.get("vram_used_mib"))
        # _detect_gpus retains a legacy vram_free_mib=0 when the used counter
        # is unreadable. Only derive free capacity when both source readings exist.
        measured = total is not None and total > 0 and used is not None and used <= total
        rows.append({
            "gpu_id": str(device_id),
            "status": str(observed.get("status") or "observed"),
            "capacity_state": "measured" if measured else "unknown",
            "reason": None if measured else "vram_measurement_incomplete",
            "vram_total_mib": total if total and total > 0 else None,
            "vram_used_mib": used if measured else None,
            "vram_free_mib": total - used if measured else None,
            "observed_at": observed_at,
        })

    # Include measured devices absent from a partial registry; do not silently
    # discard runtime hardware merely because configuration is stale.
    configured_cards = {str((cfg or {}).get("card") or "") for _, cfg in configured if isinstance(cfg, Mapping)}
    for index, observed in enumerate(telemetry_rows):
        card = str(observed.get("card") or "")
        if card and (card in matched_cards or card in configured_cards):
            continue
        total = _safe_counter(observed.get("vram_total_mib"))
        used = _safe_counter(observed.get("vram_used_mib"))
        measured = total is not None and total > 0 and used is not None and used <= total
        rows.append({
            "gpu_id": str(observed.get("gpu_id") or card or f"gpu-{index}"),
            "status": str(observed.get("status") or "observed"),
            "capacity_state": "measured" if measured else "unknown",
            "reason": None if measured else "vram_measurement_incomplete",
            "vram_total_mib": total if total and total > 0 else None,
            "vram_used_mib": used if measured else None,
            "vram_free_mib": total - used if measured else None,
            "observed_at": observed_at,
        })

    measured_rows = [row for row in rows if row["capacity_state"] == "measured"]
    unknown_count = len(rows) - len(measured_rows)
    if rows and unknown_count == 0:
        state = "measured"
    elif measured_rows:
        state = "partial"
    else:
        state = "unknown"
    known_free = sum(row["vram_free_mib"] for row in measured_rows)
    return {
        "status": state,
        "gpu_count": len(rows),
        "measured_gpu_count": len(measured_rows),
        "unknown_gpu_count": unknown_count,
        "measured_free_vram_mib": known_free,
        "free_vram_mib": known_free if rows and unknown_count == 0 else None,
        "gpus": rows,
        "observed_at": observed_at if telemetry_ok else None,
    }


def _node_lease_snapshot(request: web.Request) -> dict:
    """Return live node leases without peer endpoints, lease tokens, or host IPs."""
    api = request.app.get("gpu_manager_node_api")
    registry = getattr(api, "registry", None)
    snapshot = getattr(registry, "snapshot", None)
    if not callable(snapshot):
        return {"status": "unknown", "reason": "node_registry_unavailable", "nodes": []}
    try:
        try:
            raw_nodes = snapshot(include_expired=True)
        except TypeError:
            raw_nodes = snapshot()
    except Exception:
        logger.exception("node registry snapshot failed")
        return {"status": "unknown", "reason": "node_registry_unavailable", "nodes": []}
    nodes = []
    for item in raw_nodes if isinstance(raw_nodes, list) else []:
        if not isinstance(item, Mapping):
            continue
        caps = item.get("caps") if isinstance(item.get("caps"), Mapping) else {}
        hardware = item.get("hardware") if isinstance(item.get("hardware"), Mapping) else {}
        gpus = []
        for gpu in hardware.get("gpus", []) if isinstance(hardware.get("gpus", []), list) else []:
            if isinstance(gpu, Mapping):
                gpus.append({key: gpu[key] for key in ("id", "name", "vram_total_mib") if key in gpu})
        expires_in = max(0.0, float(item.get("expires_in_seconds") or 0))
        lease_state = "expired" if expires_in <= 0 else ("draining" if item.get("draining") is True else "active")
        nodes.append({
            "node_id": str(item.get("node_id") or ""),
            "lease_state": lease_state,
            "expires_in_seconds": expires_in,
            "sequence": _safe_counter(item.get("sequence")),
            "caps": {key: _safe_counter(caps.get(key)) for key in ("available_slots", "free_vram_mib", "active_requests")},
            "hardware": {
                "models": [str(name)[:128] for name in hardware.get("models", [])[:32]
                           if isinstance(name, str)] if isinstance(hardware.get("models", []), list) else [],
                "platform": str(hardware.get("platform") or "")[:128],
                "gpus": gpus,
            },
        })
    return {
        "status": "observed",
        "active_count": sum(node["lease_state"] == "active" for node in nodes),
        "draining_count": sum(node["lease_state"] == "draining" for node in nodes),
        "expired_count": sum(node["lease_state"] == "expired" for node in nodes),
        "nodes": nodes,
        "observed_at": time.time(),
    }


def _queue_counters_snapshot() -> dict:
    manager = globals().get("llm")
    counters = {
        "active_requests": _safe_counter(getattr(manager, "active_requests", None)) if manager else None,
        "pending_requests": _safe_counter(getattr(manager, "queued_requests", None)) if manager else None,
        "total_served": _safe_counter(globals().get("_queue_total_served")),
    }
    known = sum(value is not None for value in counters.values())
    return {"status": "observed" if known else "unknown", **counters}


def _oom_counters_snapshot_for_api(now: float | None = None) -> dict:
    sample_time = time.time() if now is None else float(now)
    try:
        events = _recent_oom_events(limit=500)
        if not isinstance(events, list):
            raise ValueError("OOM event reader returned non-list")
        recent = [event for event in events if isinstance(event, Mapping)]
        unresolved_states = {"detected", "draining", "verifying", "recovering", "oom_failed", "permanent_failed"}
        states = globals().get("_gpu_states", {})
        unresolved = sum(
            str(getattr(state, "oom_state", "idle")) in unresolved_states
            for state in states.values()
        ) if isinstance(states, Mapping) else None
        return {
            "status": "observed",
            "recent_event_count": len(recent),
            "events_last_hour": sum(
                0 <= sample_time - float(event.get("ts", 0) or 0) < 3600
                for event in recent
            ),
            "unresolved_gpu_count": unresolved,
        }
    except Exception:
        return {"status": "unknown", "recent_event_count": None,
                "events_last_hour": None, "unresolved_gpu_count": None}


def _admission_state_snapshot() -> dict:
    """Expose the exact OOM states that currently close GPU admission."""
    states = globals().get("_gpu_states")
    if not isinstance(states, Mapping):
        return {"status": "unknown", "closed": None, "closed_gpu_ids": []}
    closed_states = {"detected", "draining", "verifying", "recovering", "oom_failed", "permanent_failed"}
    closed_gpu_ids = sorted(
        str(gpu_id)[:128] for gpu_id, state in states.items()
        if str(getattr(state, "oom_state", "idle")) in closed_states
    )
    return {"status": "observed", "closed": bool(closed_gpu_ids), "closed_gpu_ids": closed_gpu_ids}


async def _observability_snapshot(request: web.Request) -> dict:
    now = time.time()
    telemetry = None
    try:
        sample = await _poll_vram()
        if isinstance(sample, Mapping) and not sample.get("error") and isinstance(sample.get("gpus"), list):
            telemetry = sample["gpus"]
    except Exception:
        logger.exception("GPU capacity telemetry is unavailable")
    try:
        config = _load_services_config()
    except Exception:
        config = {}
    gpu_capacity = _gpu_capacity_snapshot(config, telemetry, now)
    nodes = _node_lease_snapshot(request)
    return {
        "schema_version": 1,
        "observed_at": now,
        "gpu_capacity": gpu_capacity,
        "nodes": nodes,
        "queue": _queue_counters_snapshot(),
        "oom": _oom_counters_snapshot_for_api(now),
        "admission": _admission_state_snapshot(),
        "transition_event_count": len(_transition_events()),
    }


async def handle_capacity(request: web.Request):
    """GET /capacity — authenticated measured/unknown GPU and queue capacity."""
    return web.json_response(await _observability_snapshot(request))


async def handle_nodes(request: web.Request):
    """GET /nodes — authenticated live node lease and drain state."""
    return web.json_response(_node_lease_snapshot(request))


async def handle_transition_events(request: web.Request):
    """GET /events — bounded authenticated structured lifecycle transitions."""
    try:
        limit = int(request.query.get("limit", "100"))
    except (TypeError, ValueError):
        return web.json_response({"error": "invalid_limit"}, status=400)
    if not 1 <= limit <= _OBSERVABILITY_EVENT_LIMIT:
        return web.json_response({"error": "invalid_limit"}, status=400)
    events = _transition_events(limit)
    return web.json_response({"schema_version": 1, "count": len(events), "events": events})


async def handle_observability_metrics(request: web.Request):
    """JSON metrics projection for measured capacity, queue, OOM, and leases."""
    snapshot = await _observability_snapshot(request)
    return web.json_response({
        "schema_version": snapshot["schema_version"],
        "observed_at": snapshot["observed_at"],
        "gpu_capacity": snapshot["gpu_capacity"],
        "nodes": snapshot["nodes"],
        "queue": snapshot["queue"],
        "oom": snapshot["oom"],
        "admission": snapshot["admission"],
        "transition_event_count": snapshot["transition_event_count"],
    })


def _register_observability_routes(app: web.Application) -> None:
    """Register the health/capacity/node/event routes on the authenticated app."""
    app.router.add_get("/health/live", handle_liveness)
    app.router.add_get("/health", handle_health)
    app.router.add_get("/capacity", handle_capacity)
    app.router.add_get("/nodes", handle_nodes)
    app.router.add_get("/events", handle_transition_events)
    app.router.add_get("/v1/metrics/observability", handle_observability_metrics)


def _queue_authority_snapshot() -> dict[str, Any]:
    """Describe the queue owners without implying they are one authority.

    The candidate still has a compatibility scheduler for legacy
    ``/pipeline/*``/queue routes and a Redis-backed ``WorkerSupervisor`` for
    ``/v1`` generation streams.  Keeping this split explicit in health output
    prevents a green process liveness result from being read as proof that
    every route has one live dispatcher.  This is deliberately observational;
    it does not start, stop, or reconcile either owner.
    """

    legacy = globals().get("scheduler")
    durable = globals().get("worker_supervisor")
    legacy_present = legacy is not None
    durable_present = durable is not None
    legacy_running = bool(
        getattr(legacy, "_running", False) or getattr(legacy, "running", False)
    )
    durable_running = bool(
        getattr(durable, "_running", False) or getattr(durable, "running", False)
    )
    if legacy_running and durable_running:
        ownership = "split"
    elif legacy_running:
        ownership = "legacy_only"
    elif durable_running:
        ownership = "durable_only"
    elif legacy_present or durable_present:
        ownership = "present_but_stopped"
    else:
        ownership = "unavailable"
    pools = getattr(durable, "_pools", {}) if durable is not None else {}
    scheduling = _phase3_scheduling_config()
    configured_owner = _queue_owner_mode(scheduling)
    return {
        "ownership": ownership,
        "configured_owner": configured_owner,
        "single_owner_required": True,
        "priority": {
            "lanes_enabled": bool(scheduling.get("priority_lanes_enabled", False)),
            "aging_interval_s": scheduling.get("priority_aging_interval_s", 60),
            "aging_cap": scheduling.get("queue_priority_aging_cap", 3),
            "legacy_stream_drained": True,
        },
        "legacy_scheduler": {
            "present": legacy_present,
            "running": legacy_running,
            "routes": ["/pipeline/*", "legacy queue/generate"],
        },
        "worker_supervisor": {
            "present": durable_present,
            "running": durable_running,
            "pool_count": len(pools) if isinstance(pools, Mapping) else 0,
            "routes": ["/v1/*", "Redis generation streams"],
        },
    }


async def handle_health(request: web.Request):
    """GET /health — overall status including GPU state machine."""
    if (
        _scoped_gemma_request_is_authorized(request)
        or _honcho_gemma_request_is_authorized(request)
    ):
        # Scoped pre-claim probes must reflect actual broker readiness, not the
        # generic controller liveness response or private fleet telemetry.
        try:
            _, code = _CombinedGemmaAPIProxy().health_ready()
        except Exception:
            code = 503
        ready = code == 200
        return web.json_response(
            {"status": "ok" if ready else "unavailable"},
            status=200 if ready else 503,
            headers={"Cache-Control": "no-store"},
        )
    status = llm.status()
    status["queue_total_served"] = _queue_total_served
    status["scheduler"] = scheduler.get_queue_status() if scheduler else {}
    status["queue_authority"] = _queue_authority_snapshot()
    status["vram"] = vram.status() if vram else {}
    config = _load_services_config()
    # Safe registry identity: callers can compare this with the broker's
    # diagnostic without receiving paths, credentials, or runtime state.
    status["registry"] = registry_summary(config, owner="controller")
    try:
        status["checked_runtimes"] = (
            await _get_checked_runtime_controller().health_summary()
        )
    except Exception:
        logger.exception("checked runtime state could not be read")
        status["checked_runtimes"] = {
            "status": "unavailable",
            "error": "runtime_state_unavailable",
        }
    readiness = await _llm_readiness_snapshot(config)
    status["idle_llm_healthy"] = status.get("llm_healthy", False)
    status["llm_readiness"] = readiness
    status["llm_available"] = readiness["available"]
    status["llm_healthy"] = readiness["available"]
    status["maintenance_mode"] = _maintenance_mode_enabled(config.get("scheduling", {}))
    # ── Phase 1: OOM state surfaced for dashboard ────────────────────
    gpu_states_map = globals().get("_gpu_states", {})
    # Phase 2: include the recent OOM events (last hour) so the dashboard
    # can show a live count and operators can see what's been happening.
    now_ts = time.time()
    try:
        events_last_hour = [
            {"gpu_id": ev.get("gpu_id"), "ts": ev.get("ts"),
             "reason": ev.get("reason", ""), "service": ev.get("service", ""),
             "job_id": ev.get("job_id", ""), "source": ev.get("source", "")}
            for ev in _recent_oom_events(limit=200)
            if (now_ts - float(ev.get("ts", 0) or 0)) < 3600
        ]
    except Exception as _oom_health_err:
        events_last_hour = []
        logger.debug(f"oom events_last_hour build failed: {_oom_health_err}")
    # ── Phase 4: explicit watchdog heartbeat fields ────────────────────
    # Sourced from _last_oom_heartbeat_ts which _oom_recovery_watchdog_loop
    # updates every OOM_WATCHDOG_POLL_INTERVAL_S. Operators can read this
    # to confirm the watchdog is alive without grepping the journal.
    try:
        _wdt_heartbeat_ts = float(
            globals().get("_last_oom_heartbeat_ts", 0.0) or 0.0
        )
    except Exception:
        _wdt_heartbeat_ts = 0.0

    # ── Single source of truth: shared with the websocket full-state ──
    # `now` is pinned to the start of the handler so cache_age_seconds and
    # watchdog_age_s reflect the same wall-clock as the rest of the payload.
    status["oom"] = _oom_health_section(
        gpu_states_map=gpu_states_map,
        events_last_hour=events_last_hour,
        watchdog_heartbeat_ts=_wdt_heartbeat_ts,
        now=now_ts,
    )
    # ── Phase 5.2.69: orphan-reaper summary ──────────────────────────
    # Keep maintenance, disabled and stale-tick states explicit; an enabled
    # reaper that cannot tick is not healthy.
    status["orphan_reaper"] = _orphan_reaper_status()
    _apply_runtime_semantics(status, readiness)
    observability = await _observability_snapshot(request)
    status["gpu_capacity"] = observability["gpu_capacity"]
    status["nodes"] = observability["nodes"]
    status["queue_counters"] = observability["queue"]
    status["oom_counters"] = observability["oom"]
    status["admission"] = observability["admission"]
    status["transition_event_count"] = observability["transition_event_count"]
    return web.json_response(status)


async def handle_lifecycle(request: web.Request):
    """GET /lifecycle — current GPU lifecycle transition state with step details."""
    if not scheduler:
        return web.json_response({"state": "idle", "error": "Scheduler not running"}, status=503)
    return web.json_response(scheduler.get_lifecycle_status())


def _extract_requirements(body: bytes | None) -> dict:
    """Parse LLM request body to extract capability requirements."""
    requirements = {}
    if not body:
        return requirements
    try:
        data = json.loads(body)
    except Exception:
        return requirements

    messages = data.get("messages", [])
    if messages:
        system_text = ""
        for msg in messages:
            if msg.get("role") == "system":
                system_text += msg.get("content", "")
        total_text = system_text + " " + json.dumps(messages)
        context_estimate = len(total_text)
        requirements["min_context"] = max(context_estimate, 4096)

    if data.get("require_vision"):
        requirements["require_vision"] = True

    if data.get("min_complexity"):
        requirements["min_complexity"] = data["min_complexity"]

    return requirements


# ── Mutex Group Logic ────────────────────────────────────────────────
# Services sharing a mutex_group on the same GPU are mutually exclusive.
# Only one can be active at a time. When one is requested, siblings are stopped.

_mutex_activation_locks: dict[str, asyncio.Lock] = {}  # group_name -> lock


async def _ensure_mutex_exclusive(service_name: str) -> str:
    """Ensure only one service per mutex_group is active.

    Called before forwarding an LLM request. If the target service isn't running:
    1. Stops all other services in the same mutex_group
    2. Starts the target service
    3. Waits for it to become healthy

    Returns the backend URL on success, raises on failure.
    """
    svc = _services_config.get("services", {}).get(service_name)
    if not svc or not svc.get("mutex_group"):
        # No mutex — just return the backend URL
        return f"http://localhost:{svc['port']}" if svc else None

    group = svc["mutex_group"]

    # Bundle-backed services are exclusively owned by
    # BundleLifecycleController. This legacy mutex path performs raw systemd
    # operations, so fail before probing a managed target or sibling.
    bundles = _resolve_bundles()
    managed_group_members = []
    for member_name, member_svc in _services_config.get("services", {}).items():
        if member_svc.get("mutex_group") != group:
            continue
        if _get_bundle_for_service(member_name, bundles) is not None:
            managed_group_members.append(member_name)
    if managed_group_members:
        raise RuntimeError(
            "bundle_controller_required_for_mutex_group:"
            + ",".join(sorted(managed_group_members))
        )

    # Serialize activations per group to prevent races
    if group not in _mutex_activation_locks:
        _mutex_activation_locks[group] = asyncio.Lock()

    async with _mutex_activation_locks[group]:
        # Check if target is already running
        unit = svc.get("systemd_unit", f"{service_name}.service")
        proc = await asyncio.create_subprocess_exec(
            "systemctl", "is-active", unit,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL
        )
        stdout, _ = await proc.communicate()
        target_running = stdout.decode().strip() == "active"

        if target_running:
            logger.debug(f"MUTEX ({group}): {service_name} already active")
            return f"http://localhost:{svc['port']}"

        # Find and stop all running siblings in the same mutex group
        for other_name, other_svc in _services_config.get("services", {}).items():
            if other_name == service_name:
                continue
            if other_svc.get("mutex_group") != group:
                continue
            other_unit = other_svc.get("systemd_unit", f"{other_name}.service")
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", other_unit,
                stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL
            )
            stdout, _ = await proc.communicate()
            if stdout.decode().strip() == "active":
                logger.info(f"MUTEX ({group}): stopping {other_name} to make room for {service_name}")
                stop_proc = await asyncio.create_subprocess_exec(
                    "sudo", "systemctl", "stop", other_unit,
                    stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.PIPE
                )
                await asyncio.wait_for(stop_proc.communicate(), timeout=30)
                if stop_proc.returncode == 0:
                    logger.info(f"MUTEX ({group}): {other_name} stopped")
                    if event_bus:
                        event_bus.emit(other_name, "unhealthy")
                else:
                    logger.error(f"MUTEX ({group}): failed to stop {other_name}")

        # Start the target service
        logger.info(f"MUTEX ({group}): starting {service_name}")
        start_proc = await asyncio.create_subprocess_exec(
            "sudo", "systemctl", "start", unit,
            stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.PIPE
        )
        _, stderr = await asyncio.wait_for(start_proc.communicate(), timeout=60)

        if start_proc.returncode != 0:
            err = stderr.decode().strip()
            logger.error(f"MUTEX ({group}): failed to start {service_name}: {err}")
            raise RuntimeError(f"Failed to start {service_name}: {err}")

        # Wait for health (poll /health endpoint)
        port = svc["port"]
        for attempt in range(30):  # 30 × 2s = 60s max wait
            await asyncio.sleep(2)
            try:
                async with session.get(
                    f"http://localhost:{port}/health",
                    timeout=ClientTimeout(total=3)
                ) as resp:
                    if resp.status == 200:
                        if event_bus:
                            event_bus.emit(service_name, "healthy")
                        logger.info(f"MUTEX ({group}): {service_name} healthy after {attempt*2}s")
                        return f"http://localhost:{port}"
            except Exception:
                pass
            # Check if process is still alive
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", unit,
                stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL
            )
            stdout, _ = await proc.communicate()
            if stdout.decode().strip() != "active":
                raise RuntimeError(f"{service_name} died during startup")

        raise RuntimeError(f"{service_name} failed to become healthy within 60s")


# ── Queue API Handlers ─────────────────────────────────────────────

async def _forward_remote_job(job_id, peer_host, peer_port, prompt, messages, max_tokens, model):
    """Forward a job to a remote peer LLM endpoint and store the result."""
    try:
        body = {}
        if messages:
            body = {"model": model, "messages": messages, "max_tokens": max_tokens}
        else:
            body = {"model": model, "prompt": prompt or "", "max_tokens": max_tokens}

        url = f"http://{peer_host}:{int(peer_port)}/v1/completions"
        async with session.post(url, json=body, timeout=ClientTimeout(total=120)) as resp:
            resp_body = await resp.text()
            result_data = {
                "status": resp.status,
                "body": resp_body,
                "headers": dict(resp.headers),
                "forwarded_to": url,
            }
            job_tracker.update_status(job_id, "completed",
                                      result=json.dumps(result_data),
                                      http_status=resp.status)
    except asyncio.TimeoutError:
        job_tracker.update_status(job_id, "failed",
                                  error="Remote request timed out (120s)")
    except Exception as e:
        job_tracker.update_status(job_id, "failed",
                                  error=f"Remote forward failed: {e}")


_IDEMPOTENCY_KEY_MAX_LENGTH = 256


def _request_idempotency_contract(
    request: web.Request,
    data: Mapping[str, Any],
    *,
    operation: str,
) -> tuple[str | None, str | None]:
    """Resolve one explicit idempotency key and canonical request digest.

    Header and JSON forms are equivalent and must agree when both are sent.
    The operation is part of the digest so a key cannot replay a different
    endpoint whose JSON happens to have the same shape. Caller keys are never
    logged or copied into queue/job records.
    """
    headers = getattr(request, "headers", {}) or {}
    header_value = headers.get("Idempotency-Key") or headers.get(
        "idempotency-key"
    )
    body_supplied = "idempotency_key" in data
    body_value = data.get("idempotency_key") if body_supplied else None

    normalized: list[str] = []
    for source, value in (("header", header_value), ("body", body_value)):
        if value is None and not (source == "body" and body_supplied):
            continue
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{source} idempotency key must be a non-empty string")
        candidate = value.strip()
        if len(candidate) > _IDEMPOTENCY_KEY_MAX_LENGTH:
            raise ValueError(
                f"{source} idempotency key exceeds "
                f"{_IDEMPOTENCY_KEY_MAX_LENGTH} characters"
            )
        normalized.append(candidate)

    if not normalized:
        return None, None
    if len(set(normalized)) != 1:
        raise ValueError("header and body idempotency keys do not match")

    canonical_body = dict(data)
    canonical_body.pop("idempotency_key", None)
    canonical = json.dumps(
        {"operation": operation, "body": canonical_body},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    return normalized[0], hashlib.sha256(canonical).hexdigest()


def _idempotency_outcome_response(
    outcome: Mapping[str, Any],
    *,
    response_fields: Mapping[str, Any] | None = None,
) -> web.Response | None:
    """Translate a non-claimed admission outcome into an HTTP response."""
    status = str(outcome.get("status") or "unavailable")
    if status == "claimed":
        return None
    if status == "conflict":
        return web.json_response(
            {
                "error": "idempotency key was already used for a different request",
                "reason": "idempotency_conflict",
            },
            status=409,
        )
    if status != "replay":
        return web.json_response(
            {
                "error": "idempotency state is temporarily unavailable",
                "reason": "idempotency_unavailable",
            },
            status=503,
        )

    job_id = str(outcome.get("job_id") or "")
    prior = job_tracker.get_job(job_id) if job_tracker and job_id else None
    if not isinstance(prior, Mapping):
        return web.json_response(
            {
                "error": "prior idempotent admission requires reconciliation",
                "reason": "idempotency_record_unavailable",
                "job_id": job_id,
                "idempotent_replay": True,
            },
            status=503,
        )

    current_status = str(prior.get("status") or "unknown")
    payload = {
        "job_id": job_id,
        "status": current_status,
        "service": prior.get("service_name") or outcome.get("service_name") or "",
        "routing_group": (
            prior.get("routing_group") or outcome.get("routing_group") or ""
        ),
        "idempotent_replay": True,
    }
    if response_fields:
        payload.update(response_fields)
    terminal = current_status in {"completed", "failed", "cancelled"}
    return web.json_response(payload, status=200 if terminal else 202)


def _submit_request_envelope(code: str, message: str, *, status: int) -> web.Response:
    """Wrap :func:`api_contracts.error_envelope` into a stable JSON response.

    Lives next to the submit handlers because the helper exists only to
    translate :class:`api_contracts.ContractError` outcomes into the
    controller's public envelope shape — without leaking either raw
    exception text or partial parse state to the caller.
    """
    envelope = _error_envelope(code, message, status=status)
    return web.json_response(envelope, status=status)


# ── Admission + placement gate (GPU Manager v2) ────────────────────
# Every request that could trigger a model load or eviction is checked here
# BEFORE any queue claim, capacity reservation, eviction or unload.
# GPUScheduler remains the sole allocator: PlacementOrchestrator only vets the
# placement (all participating GPUs before any eviction) and never evicts.
_placement_orchestrator: PlacementOrchestrator | None = None


def _get_placement_orchestrator() -> PlacementOrchestrator:
    global _placement_orchestrator
    if _placement_orchestrator is None:
        _placement_orchestrator = PlacementOrchestrator({})
    return _placement_orchestrator


def _admission_telemetry() -> dict | None:
    """Live GPU telemetry for admission; None when it cannot be read."""
    try:
        return {"gpus": _detect_gpus()}
    except Exception as exc:
        logger.warning("ADMISSION: telemetry unavailable: %s", exc)
        return None


def _admission_rejection_response(reason: str, alternative: dict | None) -> web.Response:
    return web.json_response(
        {
            "status": "rejected",
            "error": reason,
            "code": "admission_rejected",
            "reason": reason,
            # No device can host it: the CPU route is the nearest alternative.
            "nearest_alternative": alternative or {"device": "cpu"},
        },
        status=422,
    )


def _admission_gate(
    service_name: str | None,
    data: Mapping[str, Any] | None = None,
) -> tuple[web.Response | None, dict | None]:
    """Admission + placement check. Returns (rejection_response, info).

    rejection_response is not None only for ``rejected``; ``queued`` returns
    (None, {"status": "queued", ...}) so the caller continues into its
    existing queue path (the scheduler performs any eviction later); accepted
    returns (None, {"status": "accepted", ...}). Requests that do not target a
    GPU-backed service (CPU Gemma, unknown names, routing groups) pass through
    untouched. A failure inside the gate itself never takes the service down.
    """
    data = data or {}
    try:
        config = _services_config or {}
        services = config.get("services", {}) or {}
        svc = services.get(service_name or "") or {}
        model_set = data.get("model_set") if isinstance(data.get("model_set"), Mapping) else None
        gpu_id = svc.get("gpu_id")
        requested_gpu_ids = {str(gpu_id)} if gpu_id else set()
        if model_set:
            for component in model_set.get("components", []) or []:
                if isinstance(component, Mapping) and component.get("device"):
                    requested_gpu_ids.add(str(component["device"]))
        for requested_gpu_id in requested_gpu_ids:
            state = _gpu_states.get(requested_gpu_id)
            oom_state = str(getattr(state, "oom_state", "idle")) if state is not None else "idle"
            if oom_state in {"detected", "draining", "verifying", "recovering", "oom_failed", "permanent_failed"}:
                return _admission_rejection_response(
                    f"GPU {requested_gpu_id} OOM recovery unresolved ({oom_state})",
                    {"device": "cpu"},
                ), None
        if not model_set and not gpu_id:
            return None, None

        telemetry = _admission_telemetry()
        gpu_devices = config.get("gpu_devices", {}) or {}
        registry = {}
        for dev_id, dev_cfg in gpu_devices.items():
            telem_dev = None
            for g in (telemetry or {}).get("gpus", []):
                if g.get("card") and g.get("card") == (dev_cfg or {}).get("card"):
                    telem_dev = g
                    break
            registry[dev_id] = recognize_hardware_device(dev_id, dev_cfg or {}, telem_dev)

        controller = AdmissionController(registry)
        orchestrator = _get_placement_orchestrator()
        orchestrator.hardware_registry = dict(registry)

        if model_set:
            decision = orchestrator.place_model_set(
                model_set,
                {
                    gid: {
                        "loaded_bundle": st.loaded_bundle,
                        "bundle_priority": st.bundle_priority,
                        "state": st.state,
                    }
                    for gid, st in _gpu_states.items()
                },
                queue_depth=0,
            )
            if decision.status == PlacementDecisionStatus.REJECTED:
                return _admission_rejection_response(decision.reason, decision.nearest_alternative), None
            if decision.status == PlacementDecisionStatus.QUEUED:
                return None, {"status": "queued", "position": decision.position, "reason": decision.reason}
            if decision.lease:
                orchestrator.release_lease(decision.lease.lease_id)
                orchestrator._active_leases.pop(decision.lease.lease_id, None)
            return None, {"status": "accepted", "placement": dict(decision.lease.allocations) if decision.lease else {}}

        admission_request = {
            "kind": "llm",
            "service": service_name,
            "model": service_name,
            "device": gpu_id,
            "precision": svc.get("precision") or data.get("precision") or "",
            "compute_api": svc.get("compute_api") or "rocm",
            "min_vram_mib": int(
                data.get("min_vram_mib") or svc.get("min_vram_mib") or svc.get("vram_mib") or 0
            ),
        }
        decision = controller.evaluate_admission(admission_request, config, telemetry)
        if decision.status == AdmissionStatus.REJECTED:
            return _admission_rejection_response(decision.reason, decision.nearest_alternative), None
        if decision.status == AdmissionStatus.QUEUED:
            return None, decision.to_dict()

        orchestrator.hardware_registry = dict(controller.hardware_registry)
        placement = orchestrator.place_model_set(
            {
                "id": service_name,
                "components": [{
                    "device": gpu_id,
                    "model": service_name,
                    "precision": admission_request["precision"],
                    "min_vram_mib": admission_request["min_vram_mib"],
                }],
            },
            {},
        )
        if placement.lease:
            orchestrator.release_lease(placement.lease.lease_id)
            orchestrator._active_leases.pop(placement.lease.lease_id, None)
        if placement.status == PlacementDecisionStatus.REJECTED:
            return _admission_rejection_response(placement.reason, placement.nearest_alternative), None
        if placement.status == PlacementDecisionStatus.QUEUED:
            return None, {"status": "queued", "position": placement.position, "reason": placement.reason}
        return None, decision.to_dict()
    except Exception:
        logger.exception("ADMISSION: gate error; falling through to existing routing")
        return None, None


def _service_gpu_transitioning(service_name: str | None) -> bool:
    """True while the service's GPU is evicting, loading or draining."""
    svc = ((_services_config or {}).get("services") or {}).get(service_name or "") or {}
    gpu_id = svc.get("gpu_id")
    state = _gpu_states.get(gpu_id) if gpu_id else None
    return bool(
        state is not None
        and (state.evicting or state.loading or state.draining)
    )


async def _queue_position_fields(
    service_name: str | None,
    routing_group: str | None,
    entry_id: str | None,
    job: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Additive queue fields for submit and job-status responses.

    ``queue_reason`` always says why the job has not started. ``queue_ahead`` is
    the exact count of undelivered entries ahead of this one and appears only
    when the broker can prove it; ``queue_position_exact`` is False when
    priority lanes or the scan cap make it a lower bound. The historical
    ``queue_position``/``position`` depth fields are left untouched.
    """
    fields: dict[str, Any] = {
        "queue_reason": _queue_reason_code(
            job, gpu_transitioning=_service_gpu_transitioning(service_name)
        )
    }
    getter = getattr(queue_engine, "get_entry_position", None) if queue_engine else None
    if entry_id and service_name and callable(getter):
        try:
            loop = asyncio.get_running_loop()
            observed = await loop.run_in_executor(
                None, getter, service_name, entry_id, routing_group or None
            )
        except Exception:
            observed = None
        if isinstance(observed, dict) and observed.get("known") is True:
            fields["queue_ahead"] = observed.get("ahead")
            fields["queue_position_exact"] = bool(observed.get("exact"))
    return fields


def _queue_recovery_summary() -> dict[str, Any]:
    """Recovery counters and the bounds they run under, for GET /v1/queue."""
    return {
        "counters": dict(_queue_recovery_stats),
        "restart_requeue_max": RESTART_REQUEUE_MAX,
        "evicting_stale_after_s": EVICTING_STALE_AFTER_S,
        "generation_poll_deadline_max_s": GENERATION_POLL_DEADLINE_MAX_S,
        "process_started_at": _PROCESS_STARTED_AT,
    }


def _admission_fields(info: dict | None) -> dict:
    """Additive response fields describing a queued admission."""
    if not info or info.get("status") != "queued":
        return {}
    return {"admission": {k: info.get(k) for k in ("status", "position", "reason")}}


async def handle_submit_job(request: web.Request):
    """POST /v1/submit — Submit a job to the Redis queue."""
    _owner_fence = _queue_owner_route_fence('durable', '/v1/submit')
    if _owner_fence is not None:
        return _owner_fence
    if not queue_engine or not job_tracker or not routing_engine:
        return web.json_response({"error": "Queue engine not available"}, status=503)
    if not session:
        return web.json_response({"error": "HTTP session not initialized, try again shortly"}, status=503)
    try:
        raw_body = await request.read()
    except web.HTTPRequestEntityTooLarge:
        # aiohttp's default client_max_size fired before parse_json_object
        # could see the body; treat it the same as the contract's size gate.
        return _submit_request_envelope(
            "body_too_large", "request body is too large", status=413
        )
    except Exception:
        return _submit_request_envelope(
            "invalid_json", "valid JSON required", status=400
        )
    try:
        data = _parse_json_object(raw_body)
    except _ContractError as exc:
        status = 413 if exc.code == "body_too_large" else 400
        return _submit_request_envelope(exc.code, exc.message, status=status)
    try:
        _idempotency_key, _request_sha256 = _request_idempotency_contract(
            request, data, operation="submit.llm.v1"
        )
    except (TypeError, ValueError) as exc:
        return web.json_response({"error": str(exc)}, status=400)
    _idempotency_key_sha256 = (
        hashlib.sha256(_idempotency_key.encode("utf-8")).hexdigest()
        if _idempotency_key else None
    )

    # ``/v1/submit`` predates the generation endpoint and historically used
    # the lower-number-is-more-urgent convention in the queue/broker.  Make
    # that translation explicit at ingress so the effective priority is
    # visible in the durable job record as well as in the Redis entry.  A
    # caller may name a different convention when migrating, but it must be
    # valid and is never inferred from an arbitrary numeric value.
    _requested_convention = (
        data.get("priority_convention")
        or PriorityConvention.LEGACY_LOWER_IS_URGENT
    )
    try:
        _priority_payload = apply_priority_contract(
            {
                "priority": data.get("priority"),
                "priority_class": data.get("priority_class"),
            },
            convention=_requested_convention,
        )
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)

    model = data.get("model", "")
    routing_group = data.get("routing_group", "")
    prompt = data.get("prompt", "")
    messages = data.get("messages")
    max_tokens = data.get("max_tokens", 1024)
    source = data.get("source", "api")

    # If model given, look up routing_group from services config
    if model and not routing_group:
        svc_cfg = _services_config.get("services", {}).get(model, {})
        routing_group = svc_cfg.get("routing_group", "")
        if not routing_group:
            # Maybe model is a routing_group itself, or a direct service name
            # Check if model is itself a service
            if model in _services_config.get("services", {}):
                routing_group = model  # use as-is for direct routing

    if not routing_group:
        return web.json_response({"error": "model or routing_group required"}, status=400)

    # Admission + placement BEFORE any capacity reservation / queue claim.
    _admission_target = model or (
        routing_group if routing_group in _services_config.get("services", {}) else ""
    )
    _admission_rejection, _admission_info = _admission_gate(_admission_target, data)
    if _admission_rejection is not None:
        return _admission_rejection

    # Use RoutingEngine to find best service, with health awareness
    # Try each candidate in the routing group until we find one that's healthy
    service_name = None
    tried = set()
    # Lane-based routing: prefer lane-fill (Tier 1) when the group is
    # quiet (queue_depth <= threshold) to keep the fastest lane saturated;
    # fall back to slot-weighted spread (Tier 2) when busy.
    qd = _queue_depth_for_group(routing_group)
    prefer_priority = qd <= _PREFER_PRIORITY_DEPTH_THRESHOLD
    for _ in range(8):  # max attempts to prevent infinite loop
        candidate = routing_engine.find_service_for_group(
            routing_group,
            exclude=tried,
            queue_depth=qd,
            prefer_priority=prefer_priority,
        )
        if not candidate:
            break
        # Reserve capacity IMMEDIATELY to prevent race condition.
        # All concurrent requests will now see the decremented capacity.
        if capacity_tracker:
            capacity_tracker.on_submit(candidate, routing_group=routing_group)
        # Check if this service is actually running
        svc_cfg_c = _services_config.get("services", {}).get(candidate, {})
        svc_port = svc_cfg_c.get("port")
        is_healthy = False
        if svc_port:
            try:
                async with session.get(
                    f"http://127.0.0.1:{int(svc_port)}/health",
                    timeout=ClientTimeout(total=2),
                ) as resp:
                    if resp.status == 200:
                        is_healthy = True
            except Exception:
                pass
        if is_healthy:
            service_name = candidate
            break
        # Roll back every failed health reservation, including malformed
        # services with no configured port.
        if capacity_tracker:
            capacity_tracker.on_cancel(candidate, routing_group=routing_group)
        logger.debug(f"SUBMIT: {candidate} not healthy, trying next in group")
        tried.add(candidate)

    if not service_name:
        # ── Remote routing: check fleet peers for matching routing group ──
        remote_found = False
        if async_gossiper:
            remote = await async_gossiper.find_remote_service(routing_group)
            if remote:
                peer_mid, peer_svc, peer_info = remote
                peer_host = peer_info.get('host', '')
                peer_port = peer_info.get('port', '')
                if peer_host and peer_port:
                    # Create job as "remote" — won't go through local queue
                    job_id = job_tracker.next_job_id()
                    if job_id:
                        _remote_service = f"{peer_svc}@{peer_mid}"
                        if _idempotency_key:
                            _idem_outcome = job_tracker.claim_idempotency(
                                _idempotency_key,
                                _request_sha256,
                                job_id,
                                service_name=_remote_service,
                                routing_group=routing_group,
                            )
                            _idem_response = _idempotency_outcome_response(
                                _idem_outcome,
                            )
                            if _idem_response is not None:
                                return _idem_response
                        _created = job_tracker.create_job(
                            job_id=job_id,
                            service_name=_remote_service,
                            source=source,
                            prompt=prompt or (json.dumps(messages)[:200] if messages else ""),
                            max_tokens=max_tokens,
                            routing_group=routing_group,
                            priority=_priority_payload["priority"],
                            priority_class=_priority_payload["priority_class"],
                            broker_priority=_priority_payload["broker_priority"],
                            priority_convention=_priority_payload["priority_convention"],
                            priority_source="request",
                            idempotency_key_sha256=_idempotency_key_sha256,
                            request_sha256=_request_sha256,
                        )
                        if _created is None:
                            return web.json_response(
                                {"error": "Failed to persist remote job admission"},
                                status=503,
                            )
                        job_tracker.update_status(job_id, "remote")
                        # Fire-and-forget async forward to peer
                        asyncio.create_task(_forward_remote_job(
                            job_id, peer_host, peer_port,
                            prompt, messages, max_tokens, model or peer_svc,
                        ))
                        return web.json_response({
                            "job_id": job_id,
                            "status": "remote",
                            "service": _remote_service,
                            "routing_group": routing_group,
                            "priority": _priority_payload["priority"],
                            "priority_class": _priority_payload["priority_class"],
                            "broker_priority": _priority_payload["broker_priority"],
                            "priority_convention": _priority_payload["priority_convention"],
                            **(
                                {"idempotent_replay": False}
                                if _idempotency_key else {}
                            ),
                        }, status=202)

        # No capacity — pick the least-loaded service in the group to queue on
        members = routing_engine.get_group_members(routing_group)
        if members:
            # Sort by total_load ascending, pick least-loaded
            members.sort(key=lambda m: m.get("total_load", 999), reverse=False)
            service_name = members[0]["service"]
        else:
            # Try using routing_group as a direct service name
            if routing_group in _services_config.get("services", {}):
                service_name = routing_group
            else:
                return web.json_response(
                    {"error": f"No services in routing group '{routing_group}'"},
                    status=404,
                )
        # Reserve capacity for fallback service selection
        if capacity_tracker and service_name:
            capacity_tracker.on_submit(service_name, routing_group=routing_group)

    # CPU admission is an explicit opt-in.  The monitoring layer supplies a
    # captured evidence envelope; missing evidence remains fail-closed when
    # the operator enables the gate, while the default-off path is unchanged.
    if bool(_services_config.get("cpu_admission_gate_enabled", False)):
        evidence = _services_config.get("cpu_admission_evidence", {})
        if not isinstance(evidence, dict):
            evidence = {}
        admitted = _should_admit_generation(
            evidence.get("cfg", {}),
            junction=evidence.get("junction"),
            psi=evidence.get("psi"),
            prior_boot=evidence.get("prior_boot"),
        )
        if not admitted:
            if capacity_tracker and service_name:
                capacity_tracker.on_cancel(service_name, routing_group=routing_group)
            return web.json_response(
                {"error": "CPU generation admission refused"},
                status=503,
            )

    # Create job
    job_id = job_tracker.next_job_id()
    if not job_id:
        if capacity_tracker and service_name:
            capacity_tracker.on_cancel(service_name, routing_group=routing_group)
        return web.json_response({"error": "Failed to allocate job ID"}, status=500)

    if _idempotency_key:
        _idem_outcome = job_tracker.claim_idempotency(
            _idempotency_key,
            _request_sha256,
            job_id,
            service_name=service_name,
            routing_group=routing_group,
        )
        _idem_response = _idempotency_outcome_response(_idem_outcome)
        if _idem_response is not None:
            if capacity_tracker:
                capacity_tracker.on_cancel(
                    service_name, routing_group=routing_group
                )
            return _idem_response

    # Build the actual completions request body for the backend
    # Forward all sampling parameters (repeat_penalty, temperature, etc.)
    sampling_params = {}
    for key in ("temperature", "top_p", "top_k", "repeat_penalty",
                "frequency_penalty", "presence_penalty", "seed",
                "stop", "response_format"):
        if key in data and data[key] is not None:
            sampling_params[key] = data[key]

    if messages:
        completions_body = json.dumps({
            "model": model or service_name,
            "messages": messages,
            "max_tokens": max_tokens,
            **sampling_params,
        })
    else:
        completions_body = json.dumps({
            "model": model or service_name,
            "prompt": prompt or "",
            "max_tokens": max_tokens,
            **sampling_params,
        })

    import base64 as _b64
    # Build the full request payload for the worker to forward later
    request_payload = {
        "job_id": job_id,
        "prompt": prompt or "",
        "messages": json.dumps(messages) if messages else "",
        "max_tokens": str(max_tokens),
        "source": source,
        "model": model,
        "routing_group": routing_group,
        **_priority_payload,
        "priority_source": "request",
        "http_method": "POST",
        "http_path": "/v1/completions",  # always forward to completions endpoint
        # Base64-encoded body for the backend
        "body_b64": _b64.b64encode(completions_body.encode()).decode(),
        # Preserve original headers for forwarding
        "headers": json.dumps({"Content-Type": "application/json"}),
    }

    # Persist the admission before XADD. This gives an idempotent retry a
    # stable record to return and makes a pre-queue failure terminal instead
    # of leaving the request unobservable.
    _created = job_tracker.create_job(
        job_id=job_id,
        service_name=service_name,
        source=source,
        prompt=prompt or (json.dumps(messages)[:200] if messages else ""),
        max_tokens=max_tokens,
        routing_group=routing_group,
        priority=_priority_payload["priority"],
        priority_class=_priority_payload["priority_class"],
        broker_priority=_priority_payload["broker_priority"],
        priority_convention=_priority_payload["priority_convention"],
        priority_source="request",
        idempotency_key_sha256=_idempotency_key_sha256,
        request_sha256=_request_sha256,
    )
    if _created is None:
        if capacity_tracker:
            capacity_tracker.on_cancel(service_name, routing_group=routing_group)
        return web.json_response(
            {"error": "Failed to persist job admission"}, status=503
        )

    loop = asyncio.get_event_loop()
    logger.info(f"handle_submit_job: enqueueing job_id={job_id} routing_group={routing_group} service_name={service_name} source={source}")
    # FC4 §4.4: the pending reservation taken at candidate selection must be
    # released on EITHER a falsy enqueue return OR an enqueue exception. A
    # try/except/finally that flips a single ``released`` flag guarantees the
    # rollback runs exactly once and is skipped on the success path.
    entry_id = None
    _capacity_released = False
    try:
        entry_id = await loop.run_in_executor(None, queue_engine.enqueue, service_name, request_payload, routing_group)
        if not entry_id:
            if capacity_tracker:
                capacity_tracker.on_cancel(service_name, routing_group=routing_group)
                _capacity_released = True
            job_tracker.update_status(job_id, "failed", error="queue enqueue failed")
            return web.json_response({"error": "Failed to enqueue"}, status=500)
    except Exception:
        if capacity_tracker and not _capacity_released:
            capacity_tracker.on_cancel(service_name, routing_group=routing_group)
            _capacity_released = True
        job_tracker.update_status(job_id, "failed", error="queue enqueue raised")
        return web.json_response({"error": "Failed to enqueue"}, status=503)
    if entry_id:
        logger.info(f"handle_submit_job: enqueued job_id={job_id} entry_id={entry_id}")
    # Capacity already tracked at selection time (see for-loop above).
    # Removed late on_submit() to fix race condition.

    job_tracker.update_status(job_id, "queued", entry_id=entry_id)

    # Calculate queue position
    queue_depth = await loop.run_in_executor(None, queue_engine.get_queue_depth, service_name, routing_group)
    # Accurate estimate: ~200 tokens per job / service speed (tok/s) * queue depth
    # Ensure svc_cfg is available (may not have been set in all code paths)
    _svc_cfg_final = _services_config.get("services", {}).get(service_name, {})
    _svc_speed = int(_svc_cfg_final.get("speed", 50))
    estimated_wait_secs = int(queue_depth * (200 / max(_svc_speed, 1)))
    estimated_wait = f"~{estimated_wait_secs}s"
    _queue_fields = await _queue_position_fields(service_name, routing_group, entry_id)

    return web.json_response({
        "job_id": job_id,
        "status": "queued",
        "service": service_name,
        "queue_position": queue_depth,
        **_queue_fields,
        **_admission_fields(_admission_info),
        "estimated_wait": estimated_wait,
        "routing_group": routing_group,
        "priority": _priority_payload["priority"],
        "priority_class": _priority_payload["priority_class"],
        "broker_priority": _priority_payload["broker_priority"],
        "priority_convention": _priority_payload["priority_convention"],
        **({"idempotent_replay": False} if _idempotency_key else {}),
    }, status=202)


# ── Generation Submit (asynchronous queue contract) ────
# PR5 introduces a dedicated, asynchronous entry point for generation
# jobs (image, image-edit, video, ltx-video, music, tts).  The existing
# handle_generate runs synchronously against the backend; this new
# endpoint looks up the gen-type in services.json::generation_templates,
# reshapes the request body via the template's `param_map`, sets
# `http_path` per the template, and pushes the work onto the Redis
# stream so the WorkerPool consumes it asynchronously.  The response
# shape is the same 202 + job_id used by /v1/submit so clients can use
# the same `GET /v1/job/{job_id}` polling machinery.

# Legacy routing_group values that existing generation templates may resolve
# to. New values must be declared under ``routing_groups`` in the registry;
# the builder keeps this compatibility set so old configs remain valid while
# removing the need for a controller edit per new service.
_GENERATION_ROUTING_GROUPS = frozenset({
    "image-gen", "video-gen", "comfyui-gen", "qwen-edit-gen",
    # Audio services registered in services.json must pass the generation
    # ingress whitelist before dispatch.
    "apollo-restoration-gen",
    "audio-separation-gen",
    "resemble-enhance-gen",
})

# Reviewed in-process queue consumers. A service may select one of these
# adapters declaratively; adding a genuinely new execution protocol still
# requires reviewed code, while adding another service using an existing
# adapter does not require a controller routing conditional.
_INTERNAL_WORKFLOW_ADAPTERS = frozenset({"minimax-music3-pinned-cli", "workflow-coordinator"})


_PUBLIC_SERVICE_ACTIVATION_STATUSES = frozenset({
    "enabled",
    "qualified",
    "ready",
    "active",
    "activated",
    "production-qualified",
})


def _service_is_publicly_qualified(service: Mapping[str, Any]) -> bool:
    """Keep explicitly staged/retired services out of worker admission.

    A missing status preserves compatibility with older registries. Once a
    service declares activation/qualification state, the activation field is
    authoritative and non-public records must remain inventory-only until
    their normal revision gate qualifies them.
    """

    return service_is_publicly_eligible(service)


def _is_internal_workflow_service(service: Mapping[str, Any]) -> bool:
    return bool(
        isinstance(service, Mapping)
        and service.get("enabled", True) is True
        and _service_is_publicly_qualified(service)
        and service.get("type") == "orchestrator"
        and service.get("routing_group_type") == "orchestrator"
        and service.get("adapter") in _INTERNAL_WORKFLOW_ADAPTERS
        and isinstance(service.get("routing_group"), str)
        and service.get("routing_group")
    )


def _is_queue_consumer_service(service: Mapping[str, Any]) -> bool:
    """Return whether a registry entry owns a durable queue consumer."""

    return bool(
        isinstance(service, Mapping)
        and service.get("enabled") is True
        and _service_is_publicly_qualified(service)
        and (
            service.get("type") in _REDIS_QUEUE_ADMIT_TYPES
            or _is_internal_workflow_service(service)
        )
    )


def _declared_generation_routing_groups(
    config: Mapping[str, Any],
) -> set[str]:
    """Return legacy plus explicitly registered generation routing groups."""

    groups = set(_GENERATION_ROUTING_GROUPS)
    declared = config.get("routing_groups", {}) if isinstance(config, Mapping) else {}
    if isinstance(declared, Mapping):
        for name, value in declared.items():
            if isinstance(name, str) and name and isinstance(value, Mapping) and (
                value.get("routing_group_type") == "generation"
                or value.get("type") == "generation"
            ):
                groups.add(name)
    return groups


def _resolve_generation_alias(
    config: Mapping[str, Any], requested_type: Any,
) -> tuple[str | None, dict[str, Any] | None]:
    """Resolve a user-facing generation alias from registered services.

    Aliases are declarative service metadata.  This keeps ``music`` (and future
    GUI-created aliases) out of controller conditionals.  More than one enabled
    owner is rejected.  The retired ACE default is explicitly fail-closed until
    the MiniMax workflow service is activated; it is never selected as a
    silent fallback for the generic ``music`` request.
    """
    if not isinstance(requested_type, str) or not requested_type:
        return None, {"error": "generation type must be a non-empty string", "status": 400}
    services = config.get("services", {}) if isinstance(config, Mapping) else {}
    templates = (
        config.get("generation_templates", {})
        if isinstance(config, Mapping) else {}
    )
    if not isinstance(services, Mapping):
        services = {}
    if not isinstance(templates, Mapping):
        templates = {}

    owners = sorted(
        str(name)
        for name, service in services.items()
        if isinstance(service, Mapping)
        and service.get("enabled", True) is True
        and _service_is_publicly_qualified(service)
        and isinstance(service.get("aliases"), list)
        and requested_type in service["aliases"]
    )
    if len(owners) > 1:
        return None, {
            "error": f"generation alias {requested_type!r} has multiple enabled owners",
            "status": 409,
            "reason": "generation_alias_conflict",
            "owners": owners,
        }
    if owners:
        target = owners[0]
        retired = _retired_minimax_comfyui_template(target, templates.get(target))
        if retired is not None:
            return None, retired
        if target in templates:
            return target, None
        service = services.get(target, {})
        if _is_internal_workflow_service(service):
            return target, None
        if isinstance(service, Mapping) and service.get("type") == "orchestrator":
            return None, {
                "error": f"workflow service {target!r} is not attached to the runtime coordinator",
                "status": 503,
                "reason": "workflow_service_unavailable",
                "service": target,
            }
        return None, {
            "error": f"generation alias target {target!r} has no generation template",
            "status": 503,
            "reason": "generation_alias_target_unavailable",
            "service": target,
        }

    template = templates.get(requested_type)
    retired = _retired_minimax_comfyui_template(requested_type, template)
    if retired is not None:
        return None, retired
    backend = template.get("backend") if isinstance(template, Mapping) else None
    if requested_type == "music":
        return None, {
            "error": "MiniMax Music 3 is not yet activated as the canonical music workflow",
            "status": 503,
            "reason": (
                "legacy_music_default_retired"
                if str(backend or "").startswith("acestep")
                else "music_workflow_not_activated"
            ),
            "service": "minimax-music3-full",
            "configured_legacy_backend": backend,
        }
    return requested_type, None


def _retired_minimax_comfyui_template(
    gen_type: str, tmpl: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Describe the historical MiniMax ComfyUI leaves that are inventory-only.

    The accepted music route is the native audio.cpp service.  The old
    ``minimax-music3`` ComfyUI aliases are retained in registry snapshots so
    old receipts and qualification evidence remain addressable, but they must
    never acquire a queue lease or become a fallback when their qualification
    field is absent from an older registry revision.
    """
    if not isinstance(tmpl, Mapping):
        return None
    if not is_retired_minimax_comfyui_template(tmpl):
        return None
    return {
        "error": (
            f"Historical MiniMax ComfyUI template '{gen_type}' is retired; "
            "use the native MiniMax Music 3 workflow"
        ),
        "status": 410,
        "reason": "legacy_minimax_comfyui_retired",
        "template": gen_type,
        "replacement": "minimax-music3-full",
    }


def _validate_template_qualification(
    gen_type: str, tmpl: dict, *, metadata: dict | None = None
) -> dict | None:
    """Fail closed for templates deliberately retained as non-public candidates.

    A missing status preserves compatibility for established templates. Once a
    template declares a qualification status, only ``enabled`` and
    ``qualified`` may reach submission; static candidates must never acquire
    admission leases merely because they are present in services.json.
    """
    retired = _retired_minimax_comfyui_template(gen_type, tmpl)
    if retired is not None:
        return retired
    status = tmpl.get("qualification_status")
    if status is None:
        return None
    normalized = str(status).strip().lower()
    if normalized in {"enabled", "qualified"}:
        return None
    if normalized == "qualification_only":
        marker = (metadata or {}).get("qualification_harness")
        approved_markers = {
            "qwen_dualgpu_v1": {"image-edit-q5-qualification"},
            "semantic_scene_krea_v1": {"semantic-scene-krea-candidate"},
        }
        if gen_type in approved_markers.get(marker, set()):
            return None
    return {
        "error": (
            f"Generation template '{gen_type}' is not enabled for public submission "
            f"(qualification_status={status!r})"
        ),
        "status": 409,
        "template": gen_type,
        "qualification_status": status,
    }


def _validate_q5_template_identity(gen_type: str, tmpl: dict) -> dict | None:
    """Fail closed when Q5 benchmark and dual-GPU route identities drift.

    The generic benchmark is deliberately a ``comfyui-gen`` workflow.  The
    multi-GPU candidate is deliberately a ``comfyui-qwen``/``qwen-edit-gen``
    workflow.  Treat either cross-wiring as a submission error before a job
    can acquire an admission lease or trigger a bundle transition.
    """
    if gen_type in {"image-edit-q5-dualgpu", "image-edit-q5-qualification"}:
        expected = {
            "backend": "comfyui-qwen",
            "routing_group": "qwen-edit-gen",
            "workflow_backend": "comfyui",
        }
        expected_workflow_suffix = (
            "qwen-image-edit-2511-q5-dualgpu.json"
            if gen_type == "image-edit-q5-dualgpu"
            else "qwen-image-edit-2511-q5-distorch-896-qualification.json"
        )
        observed = {key: tmpl.get(key) for key in expected}
        mismatches = {
            key: {"expected": value, "observed": observed[key]}
            for key, value in expected.items()
            if observed[key] != value
        }
        workflow_path = str(tmpl.get("workflow_template") or "")
        if not workflow_path.endswith(expected_workflow_suffix):
            mismatches["workflow_template"] = {
                "expected_suffix": expected_workflow_suffix,
                "observed": workflow_path,
            }
        if mismatches:
            return {
                "error": (
                    "Q5 dual-GPU template identity mismatch; expected "
                    "comfyui-qwen/qwen-edit-gen with the route-specific Q5 workflow"
                ),
                "status": 400,
                "expected": {**expected, "workflow_template_suffix": expected_workflow_suffix},
                "observed": observed,
                "mismatches": mismatches,
            }
    elif gen_type == "image-edit-q5-bars-masked-qualification":
        # Q5 LIVE strict-locality template.  Plan line 258 + line 260:
        # wired to comfyui-qwen/qwen-edit-gen and the Q5 bars-masked
        # workflow.  Q3/Q4 templates are explicitly excluded; they remain
        # static reference fixtures only and must not reach this validator.
        expected = {
            "backend": "comfyui-qwen",
            "routing_group": "qwen-edit-gen",
            "workflow_backend": "comfyui",
            "model_key": "qwen-image-edit-2511-Q5_K_M.gguf",
            "qualification_status": "qualified",
            "strict_locality": True,
        }
        expected_workflow_suffix = (
            "qwen-image-edit-2511-q5-distorch-896-bars-masked-qualification.json"
        )
        observed = {key: tmpl.get(key) for key in expected}
        mismatches = {
            key: {"expected": value, "observed": observed[key]}
            for key, value in expected.items()
            if observed[key] != value
        }
        workflow_path = str(tmpl.get("workflow_template") or "")
        if not workflow_path.endswith(expected_workflow_suffix):
            mismatches["workflow_template"] = {
                "expected_suffix": expected_workflow_suffix,
                "observed": workflow_path,
            }
        if mismatches:
            return {
                "error": (
                    "Q5 strict-locality template identity mismatch; expected "
                    "comfyui-qwen/qwen-edit-gen qualified template with the "
                    "Q5 bars-masked workflow and strict_locality=true"
                ),
                "status": 400,
                "expected": {**expected, "workflow_template_suffix": expected_workflow_suffix},
                "observed": observed,
                "mismatches": mismatches,
            }
    elif gen_type == "image-edit-q5-benchmark":
        if (
            tmpl.get("backend") != "comfyui"
            or tmpl.get("routing_group") != "comfyui-gen"
            or "q5-benchmark" not in str(tmpl.get("workflow_template") or "")
        ):
            return {
                "error": (
                    "Q5 benchmark template identity mismatch; benchmark must "
                    "remain on comfyui/comfyui-gen and must not target Qwen"
                ),
                "status": 400,
            }
    return None


# ── Strict-locality submission gating (Task 7) ─────────────────────────
# Plan line 262: "Require explicit strict_locality=true or a strict edit
# class; do not use an 'only' keyword heuristic as the sole enforcement
# control."  These helpers back that policy without any keyword sniffing.

# Allowed top-level locations where a caller may declare strict locality.
_STRICT_LOCALITY_FLAG_KEYS = ("strict_locality", "strict_local_edit", "strict_edit")
# Edit classes that imply strict locality (used by metadata.edit_class).
_STRICT_LOCALITY_EDIT_CLASSES = {"strict-locality", "strict_locality", "q5-strict-bars"}


def _request_asserts_strict_locality(metadata: dict | None) -> bool:
    """Return True when the request metadata explicitly declares strict
    locality via a flag, an edit class, or a schema version.  A plain
    keyword heuristic is intentionally NOT considered.
    """
    md = metadata or {}
    if not isinstance(md, dict):
        return False
    for key in _STRICT_LOCALITY_FLAG_KEYS:
        if md.get(key) is True:
            return True
    edit_class = md.get("edit_class")
    if isinstance(edit_class, str) and edit_class.lower() in _STRICT_LOCALITY_EDIT_CLASSES:
        return True
    return False


def _template_declares_strict_locality(tmpl: dict) -> bool:
    """Return True when the generation template marks itself strict-locality
    capable.  Templates must opt in explicitly; absence is rejection.
    """
    if not isinstance(tmpl, dict):
        return False
    if tmpl.get("strict_locality") is True:
        return True
    edit_class = tmpl.get("edit_class")
    if isinstance(edit_class, str) and edit_class.lower() in _STRICT_LOCALITY_EDIT_CLASSES:
        return True
    return False


def _strict_locality_rejection(
    *, gen_type: str, reason: str, suggested: str | None = None,
) -> dict:
    """Build a structured 400 rejection for a strict-locality violation.

    ``reason`` is a short machine-readable tag; ``suggested`` (when present)
    names the only template that may serve this kind of request.
    """
    parts = [
        f"strict-locality request rejected for template '{gen_type}': {reason}.",
        "Use 'image-edit-q5-bars-masked-qualification' with explicit "
        "metadata.strict_locality=true and a contract-derived "
        "metadata.mask_provenance (see qualification/"
        "qwen-local-bars-masked-pair-contract.json).",
    ]
    if suggested:
        parts.append(f"Suggested template: {suggested}.")
    return {
        "error": " ".join(parts),
        "status": 400,
        "reason": f"strict_locality::{reason}",
        "template": gen_type,
        "suggested_template": suggested,
    }


def _load_bars_mask_provenance_contract() -> dict | None:
    """Return the parsed Q5 strict-locality bars-mask contract, or None.

    The contract is the only authoritative source for canonical mask SHA,
    resolution, alignment canvas, source binding, bbox, grow, and
    composite node IDs.  Missing or unreadable contract → fail closed.
    """
    import os as _os
    contract_path = _os.path.join(
        _os.path.dirname(_os.path.dirname(_os.path.abspath(__file__))),
        "qualification",
        "qwen-local-bars-masked-pair-contract.json",
    )
    try:
        with open(contract_path, encoding="utf-8") as _cf:
            return json.load(_cf)
    except (OSError, json.JSONDecodeError):
        return None


def _validate_mask_provenance(provenance: object, *, contract: dict | None = None) -> dict | None:
    """Fail-closed validator for the strict-locality mask provenance record.

    Required keys (plan line 261): ``file``, ``sha256``, ``resolution``
    (``{width, height}``), ``bbox`` (one canonical component), an
    ``alignment_canvas`` mirroring node 5's ImageScale transform, a
    ``source_binding`` with the frozen source SHA, ``grow`` matching the
    contract value, and a ``node_ids`` map naming the source/inpaint/
    protected-composite/save/mask nodes.

    Returns ``None`` on success or a structured 400 error on rejection.
    """
    if contract is None:
        contract = _load_bars_mask_provenance_contract()
    if contract is None:
        return {
            "error": "strict-locality mask_provenance rejected: contract "
                     "qualification/qwen-local-bars-masked-pair-contract.json "
                     "could not be loaded",
            "status": 400,
            "reason": "strict_locality::contract_missing",
        }
    if not isinstance(provenance, dict):
        return {
            "error": "strict-locality mask_provenance must be an object "
                     "with file/sha256/resolution/bbox/alignment_canvas/"
                     "source_binding/grow/node_ids keys",
            "status": 400,
            "reason": "strict_locality::provenance_shape",
        }

    contract_mask = contract.get("mask") or {}
    contract_source = contract.get("source") or {}
    contract_canonical = contract.get("canonical_transform") or {}
    contract_topology = contract.get("topology") or {}

    required = ("file", "sha256", "resolution", "bbox", "alignment_canvas",
                "source_binding", "grow")
    missing = [k for k in required if k not in provenance]
    if missing:
        return {
            "error": (
                "strict-locality mask_provenance missing required field(s): "
                f"{', '.join(missing)}"
            ),
            "status": 400,
            "reason": "strict_locality::provenance_incomplete",
            "missing": missing,
        }

    # Mask filename + SHA must match the contract.
    if provenance["file"] != contract_mask.get("file"):
        return {
            "error": (
                "strict-locality mask_provenance.file does not match contract "
                f"(expected {contract_mask.get('file')!r}, got "
                f"{provenance['file']!r})"
            ),
            "status": 400,
            "reason": "strict_locality::mask_file_mismatch",
        }
    if str(provenance["sha256"]).lower() != str(contract_mask.get("sha256") or "").lower():
        return {
            "error": (
                "strict-locality mask_provenance.sha256 does not match contract"
            ),
            "status": 400,
            "reason": "strict_locality::mask_sha_mismatch",
        }

    # Resolution must be exactly 896x896.
    res = provenance.get("resolution") or {}
    if int(res.get("width") or 0) != 896 or int(res.get("height") or 0) != 896:
        return {
            "error": (
                "strict-locality mask_provenance.resolution must be 896x896 "
                f"(got {res.get('width')}x{res.get('height')})"
            ),
            "status": 400,
            "reason": "strict_locality::mask_resolution_mismatch",
        }
    if res.get("width") != int((contract_mask.get("size") or {}).get("width") or 0) or \
       res.get("height") != int((contract_mask.get("size") or {}).get("height") or 0):
        return {
            "error": (
                "strict-locality mask_provenance.resolution does not match "
                "contract mask size"
            ),
            "status": 400,
            "reason": "strict_locality::mask_resolution_mismatch",
        }

    # Bounding box: must match one of the contract components byte-for-byte.
    contract_bboxes = [
        tuple(comp.get("canonical_bbox_xyxy_exclusive") or ())
        for comp in (contract_mask.get("components") or [])
    ]
    provided_bbox = tuple(provenance.get("bbox") or ())
    if provided_bbox not in contract_bboxes:
        return {
            "error": (
                "strict-locality mask_provenance.bbox does not match any "
                "contract component bounding box"
            ),
            "status": 400,
            "reason": "strict_locality::mask_bbox_mismatch",
            "expected_bboxes": [list(b) for b in contract_bboxes],
            "observed_bbox": list(provided_bbox),
        }

    # Alignment canvas: must mirror the canonical transform.
    canvas = provenance.get("alignment_canvas") or {}
    expected_canvas = {
        "node_id": contract_canonical.get("node_id"),
        "class_type": contract_canonical.get("class_type"),
        "width": int(contract_canonical.get("width") or 0),
        "height": int(contract_canonical.get("height") or 0),
        "upscale_method": contract_canonical.get("upscale_method"),
        "crop": contract_canonical.get("crop"),
    }
    observed_canvas = {
        "node_id": canvas.get("node_id"),
        "class_type": canvas.get("class_type"),
        "width": int(canvas.get("width") or 0),
        "height": int(canvas.get("height") or 0),
        "upscale_method": canvas.get("upscale_method"),
        "crop": canvas.get("crop"),
    }
    if observed_canvas != expected_canvas:
        return {
            "error": (
                "strict-locality mask_provenance.alignment_canvas does not "
                "match the canonical ImageScale transform"
            ),
            "status": 400,
            "reason": "strict_locality::alignment_canvas_mismatch",
            "expected": expected_canvas,
            "observed": observed_canvas,
        }

    # Source binding: SHA + file must match the contract.
    binding = provenance.get("source_binding") or {}
    if str(binding.get("source_sha256") or "").lower() != \
       str(contract_source.get("sha256") or "").lower():
        return {
            "error": (
                "strict-locality mask_provenance.source_binding.source_sha256 "
                "does not match contract source SHA"
            ),
            "status": 400,
            "reason": "strict_locality::source_binding_sha_mismatch",
        }
    if binding.get("source_file") != contract_source.get("file"):
        return {
            "error": (
                "strict-locality mask_provenance.source_binding.source_file "
                "does not match contract source file"
            ),
            "status": 400,
            "reason": "strict_locality::source_binding_file_mismatch",
        }

    # Grow amount: must match contract value.
    if int(provenance.get("grow") or -1) != int(contract.get("grow_mask_by") or -2):
        return {
            "error": (
                "strict-locality mask_provenance.grow does not match contract "
                "grow_mask_by"
            ),
            "status": 400,
            "reason": "strict_locality::grow_mismatch",
            "expected": int(contract.get("grow_mask_by") or -1),
            "observed": int(provenance.get("grow") or -1),
        }

    # node_ids: source/inpaint/protected_composite/save/mask wiring.
    node_ids = provenance.get("node_ids") or {}
    expected_node_ids = {
        "source_node": str(contract_topology.get("canonical_source_node") or ""),
        "inpaint_node": str((contract_topology.get("inpaint") or {}).get("node_id") or ""),
        "protected_composite_node": str(
            (contract_topology.get("protected_composite") or {}).get("node_id") or ""
        ),
        "save_node": str((contract_topology.get("save") or {}).get("node_id") or ""),
    }
    for key, expected in expected_node_ids.items():
        observed = str(node_ids.get(key) or "")
        if expected and observed != expected:
            return {
                "error": (
                    f"strict-locality mask_provenance.node_ids.{key} must be "
                    f"{expected!r} (got {observed!r})"
                ),
                "status": 400,
                "reason": f"strict_locality::node_id_{key}_mismatch",
            }
    if node_ids.get("mask_node") != "16":
        return {
            "error": (
                "strict-locality mask_provenance.node_ids.mask_node must be "
                "'16' (the LoadImageMask node feeding VAEEncodeForInpaint)"
            ),
            "status": 400,
            "reason": "strict_locality::mask_node_mismatch",
        }

    return None


def _annotate_pipeline_authority(
    compiled: Mapping[str, Any],
) -> tuple[dict | None, dict | None]:
    """Attach reviewed ownership/adapter metadata to a compiled graph.

    ``service_pipeline`` deliberately validates only provider IDs.  The
    controller adds the server-owned adapter identity here so a coordinator
    can resolve the exact ``(provider, adapter)`` binding without accepting
    adapter names from a request or GUI draft.
    """
    try:
        stages = [dict(stage) for stage in list(compiled.get("stages") or [])]
        # ``run_on_qc_fail`` is a worker-side compatibility flag, not a
        # coordinator control-flow declaration.  The coordinator advances to
        # the next dependency-ready stage after a passing QC result, so a
        # correction stage carrying this flag would otherwise run on both
        # pass and fail when no explicit loop binds it to the QC stage.  Keep
        # the recovered Krea graph fail-closed until its reviewed loop
        # declaration is present.
        declared_loops = [
            loop for loop in list(compiled.get("loops") or [])
            if isinstance(loop, Mapping)
        ]
        loop_correction_ids = {
            str(loop.get("correction_stage_id") or "")
            for loop in declared_loops
        }
        unbound_conditional_corrections = [
            str(stage.get("id") or "")
            for stage in stages
            if stage.get("kind") == "correct"
            and isinstance(stage.get("params"), Mapping)
            and bool(stage["params"].get("run_on_qc_fail"))
            and str(stage.get("id") or "") not in loop_correction_ids
        ]
        if unbound_conditional_corrections:
            return None, {
                "error": "pipeline_control_flow_invalid",
                "detail": (
                    "conditional correction stages require an explicit "
                    "loops[] correction binding: "
                    + ", ".join(sorted(unbound_conditional_corrections))
                ),
                "status": 500,
                "reason": "conditional_correction_loop_missing",
            }
        active_config = _services_config or _services_config_cache or {}
        configured_providers = (
            active_config.get("pipeline_providers", {})
            if isinstance(active_config, Mapping)
            else {}
        )
        for stage in stages:
            provider = str(stage.get("provider") or "").strip()
            stage["adapter"] = get_provider_adapter(provider)
            provider_config = (
                configured_providers.get(provider, {})
                if isinstance(configured_providers, Mapping)
                else {}
            )
            if isinstance(provider_config, Mapping):
                service_ref = (
                    provider_config.get("service_ref")
                    or provider_config.get("endpoint_ref")
                    or provider_config.get("service")
                )
                if isinstance(service_ref, str) and service_ref.strip():
                    stage["service_id"] = service_ref.strip()
            if (
                "service_id" not in stage
                and stage["adapter"] == "gpu_manager_generation"
            ):
                stage["service_id"] = provider
            # Leaf generation adapters need a reviewed resource/template ID;
            # never ask them to infer it from a caller-controlled endpoint.
            params = stage.get("params")
            if isinstance(params, Mapping):
                resource_id = (
                    params.get("resource_id")
                    or params.get("template")
                    or params.get("qwen_template")
                )
                if isinstance(resource_id, str) and resource_id.strip():
                    stage["resource_id"] = resource_id.strip()
        classification = classify_stages(stages)
    except MissingOwnershipMetadataError as exc:
        return None, {
            "error": "pipeline_ownership_unsupported",
            "detail": str(exc),
            "status": 500,
            "reason": "missing_provider_ownership",
        }

    if classification.dispatch_mode == DispatchMode.UNSUPPORTED:
        return None, {
            "error": "pipeline_ownership_unsupported",
            "detail": "; ".join(classification.errors)
            or "unsupported pipeline ownership",
            "unknown_providers": sorted(classification.unknown_providers),
            "status": 500,
            "reason": "unsupported_provider_ownership",
        }

    annotated = dict(compiled)
    annotated["stages"] = stages
    annotated["pipeline_dispatch_mode"] = classification.dispatch_mode.value
    annotated["pipeline_coordinator_required"] = (
        classification.dispatch_mode == DispatchMode.MIXED_OWNERSHIP
    )
    return annotated, None


async def _resolve_ingress_pipeline(
    gen_type: str,
    params: dict,
    template: dict,
) -> tuple[dict | None, dict | None]:
    """Resolve and compile the server-owned pipeline for one ingress request."""
    from service_pipeline import resolve_and_compile_pipeline

    declared_id = template.get("service_pipeline_id") if isinstance(template, Mapping) else None
    requested_id = params.get("service_pipeline_id") if isinstance(params, Mapping) else None
    if _service_pipeline_registry_error and (declared_id or requested_id):
        return None, {
            "error": "service_pipeline_registry_unavailable",
            "detail": _service_pipeline_registry_error,
            "status": 503,
            "reason": "service_pipeline_registry_unavailable",
        }

    pipeline_defs: dict[str, dict] = {}
    for service_id, pipeline in _service_pipeline_registry.items():
        definition = pipeline.to_dict()
        # The original Krea registry predates the generic compiler's explicit
        # prompt_target field.  The server-owned generation template already
        # declares the exact node/field injection, so carry that declaration
        # into the frozen compile input rather than rejecting a known-good
        # graph or guessing from caller data.
        prompt_target = None
        if isinstance(template, Mapping):
            for inject in template.get("inject_keys") or []:
                if (
                    isinstance(inject, (list, tuple))
                    and len(inject) == 3
                    and str(inject[0]) == "prompt"
                ):
                    prompt_target = f"{inject[1]}.inputs.{inject[2]}"
                    break
            if prompt_target is None:
                param_map = template.get("param_map") or {}
                mapped = param_map.get("prompt") if isinstance(param_map, Mapping) else None
                if isinstance(mapped, str) and ".inputs." in mapped:
                    prompt_target = mapped
        if prompt_target:
            for stage in definition.get("stages") or []:
                if not isinstance(stage, dict) or stage.get("kind") != "generate":
                    continue
                stage.setdefault("params", {})
                if isinstance(stage["params"], dict):
                    stage["params"].setdefault("prompt_target", prompt_target)
        pipeline_defs[service_id] = definition
    generation_templates = {"service_pipelines": pipeline_defs}
    compiled, error = resolve_and_compile_pipeline(
        gen_type=gen_type,
        template=template if isinstance(template, dict) else {},
        request_params=params if isinstance(params, dict) else {},
        generation_templates=generation_templates,
        provider_registry=_get_pipeline_provider_registry(),
    )
    if error or compiled is None:
        return compiled, error
    return _annotate_pipeline_authority(compiled)


def _coordinator_runtime_attached(request: Any) -> bool:
    """Return whether this HTTP app has the one explicit coordinator seam."""
    app = getattr(request, "app", None)
    try:
        return app is not None and app.get(WORKFLOW_COORDINATOR_RUNTIME_KEY) is not None
    except (AttributeError, TypeError):
        # Small hermetic request doubles and legacy callers have no app map;
        # they must retain the safe legacy path, not crash at ingress.
        return False


async def _build_generation_entry(
    *, gen_type, params, priority, callback_url, metadata,
    priority_class=None, parent_priority=None, parent_priority_class=None,
    compiled_pipeline: Mapping[str, Any] | None = None,
):
    """Build the Redis stream entry for a generation job.

    Returns (entry, err).  On success, `entry` is a dict ready to be
    passed to ``queue_engine.enqueue(...)``.  On failure, `err` is a
    dict with ``error`` (and optional ``status``) suitable for
    ``web.json_response``.
    """
    try:
        _priority_payload = apply_priority_contract(
            {"priority": priority, "priority_class": priority_class},
            parent=(
                {"priority": parent_priority, "priority_class": parent_priority_class}
                if parent_priority is not None or parent_priority_class is not None
                else None
            ),
            convention=PriorityConvention.GENERATION_HIGHER_IS_URGENT,
        )
    except ValueError as exc:
        return None, {"error": str(exc), "status": 400}
    priority = _priority_payload["priority"]
    cfg = _load_services_config() or {}
    templates = cfg.get("generation_templates", {}) or {}
    services_cfg = cfg.get("services", {}) or {}
    orchestrator_cfg = services_cfg.get(gen_type, {})
    if _is_internal_workflow_service(orchestrator_cfg):
        from minimax_music3_adapter import MiniMaxAdapterError, validate_request
        from workflow_pipeline_bridge import WorkflowCompilationError, compile_workflow_pipeline

        adapter = str(orchestrator_cfg.get("adapter") or "")
        if adapter == "minimax-music3-pinned-cli":
            try:
                normalized_params = validate_request(params or {})
            except MiniMaxAdapterError as exc:
                return None, {"error": str(exc), "status": 400}
        else:
            normalized_params = copy.deepcopy(dict(params or {}))
            for name, spec in (orchestrator_cfg.get("input_contract") or {}).items():
                if not isinstance(spec, Mapping):
                    continue
                value = normalized_params.get(name)
                if value is None and spec.get("required"):
                    return None, {"error": f"required workflow input: {name}", "status": 400}
                expected = {"string": str, "integer": int, "number": (int, float),
                            "boolean": bool, "object": dict, "array": list}.get(spec.get("type"))
                if value is not None and expected is not None and (
                    not isinstance(value, expected)
                    or (spec.get("type") in {"integer", "number"} and isinstance(value, bool))
                ):
                    return None, {"error": f"invalid workflow input type: {name}", "status": 400}
        if callback_url:
            return None, {
                "error": "Workflow callbacks are not enabled; poll the durable job",
                "status": 400,
            }
        import base64 as _b64

        job_id = str(uuid.uuid4())[:8]
        priority_fields = priority_envelope(
            priority,
            priority_class=_priority_payload.get("priority_class"),
            convention=PriorityConvention.GENERATION_HIGHER_IS_URGENT,
        ).to_fields()
        workflow_identity: dict[str, Any] = {}
        workflow_ref = orchestrator_cfg.get("workflow_ref")
        workflow_registry = cfg.get("workflows") or {}
        workflow_document = (
            workflow_registry.get(workflow_ref)
            if isinstance(workflow_registry, Mapping)
            else None
        )
        if not isinstance(workflow_document, Mapping) and isinstance(
            orchestrator_cfg.get("workflow"), Mapping
        ):
            workflow_document = orchestrator_cfg.get("workflow")
        operation_catalog_ref = orchestrator_cfg.get("operation_catalog_ref")
        catalog_registry = cfg.get("operation_catalogs") or {}
        operation_catalog = (
            catalog_registry.get(operation_catalog_ref)
            if isinstance(catalog_registry, Mapping)
            else None
        )
        if not isinstance(operation_catalog, Mapping) and isinstance(
            orchestrator_cfg.get("operation_catalog"), Mapping
        ):
            operation_catalog = orchestrator_cfg.get("operation_catalog")
        if isinstance(workflow_document, Mapping):
            workflow_identity = {
                "workflow_revision": int(workflow_document.get("revision", 1)),
                "workflow_fingerprint": workflow_fingerprint(workflow_document),
            }
        if not isinstance(workflow_document, Mapping) or not isinstance(
            operation_catalog, Mapping
        ):
            return None, {
                "error": "internal workflow graph/catalog is not resolved",
                "status": 503,
                "reason": "workflow_contract_unavailable",
                "service": gen_type,
            }

        # Compile once at admission.  The frozen graph is persisted with the
        # job so a later registry edit cannot retarget accepted work.  Provider
        # endpoint/service names come only from the server-owned registry;
        # request fields never participate in this mapping.
        provider_services: dict[str, str] = {}
        pipeline_providers = cfg.get("pipeline_providers") or {}
        if isinstance(pipeline_providers, Mapping):
            for provider_id, provider_cfg in pipeline_providers.items():
                if not isinstance(provider_cfg, Mapping):
                    continue
                service_ref = (
                    provider_cfg.get("service_ref")
                    or provider_cfg.get("endpoint_ref")
                    or provider_cfg.get("service")
                )
                if isinstance(service_ref, str) and service_ref.strip():
                    provider_services[str(provider_id)] = service_ref.strip()
        # Portable registry fragments expose generation backend identity via a
        # template rather than a separate pipeline_providers entry.  Resolve
        # that mapping from the reviewed audio.cpp template when present.
        if isinstance(templates, Mapping):
            for template_cfg in templates.values():
                if not isinstance(template_cfg, Mapping):
                    continue
                if template_cfg.get("workflow_backend") != "audio-cpp":
                    continue
                backend_name = template_cfg.get("backend")
                if isinstance(backend_name, str) and backend_name.strip():
                    provider_services.setdefault("audio-cpp", backend_name.strip())
        try:
            compiled_workflow = compile_workflow_pipeline(
                workflow_document,
                operation_catalog,
                service_name=gen_type,
                service_revision=str(orchestrator_cfg.get("service_revision") or ""),
                service_revision_fingerprint=str(
                    orchestrator_cfg.get("service_revision_fingerprint") or ""
                ),
                service_definitions=services_cfg if isinstance(services_cfg, Mapping) else None,
                runtime_profiles=(
                    cfg.get("runtime_profiles")
                    if isinstance(cfg.get("runtime_profiles"), Mapping)
                    else None
                ),
                provider_services=provider_services,
            )
        except WorkflowCompilationError as exc:
            return None, {
                "error": "internal workflow graph failed coordinator compilation",
                "status": 503,
                "reason": "workflow_contract_invalid",
                "service": gen_type,
                "details": list(exc.errors),
            }
        workflow_identity["workflow_pipeline"] = compiled_workflow
        workflow_identity["workflow_execution_authority"] = "coordinator"
        return {
            "job_id": job_id,
            "routing_group": orchestrator_cfg["routing_group"],
            "routing_group_type": "orchestrator",
            "service_name": gen_type,
            "bundle": "",
            "request_kind": "internal_workflow",
            "workflow_adapter": adapter,
            "service_revision": orchestrator_cfg.get("service_revision", ""),
            "service_revision_fingerprint": orchestrator_cfg.get(
                "service_revision_fingerprint", ""
            ),
            **workflow_identity,
            "body_b64": _b64.b64encode(
                json.dumps(normalized_params, separators=(",", ":")).encode("utf-8")
            ).decode("ascii"),
            "callback_url": "",
            "metadata": json.dumps(
                {
                    **(metadata or {}),
                    **workflow_identity,
                }
            ),
            **priority_fields,
            "priority_source": "request",
            "submitted_at": time.time(),
        }, None
    tmpl = templates.get(gen_type)
    if not tmpl:
        return None, {
            "error": f"No generation_template for type '{gen_type}'",
            "status": 400,
        }
    qualification_error = _validate_template_qualification(gen_type, tmpl, metadata=metadata)
    if qualification_error:
        return None, qualification_error
    q5_identity_error = _validate_q5_template_identity(gen_type, tmpl)
    if q5_identity_error:
        return None, q5_identity_error

    # Strict-locality gate (Task 7, plan line 262):
    #   * If the request asserts strict locality, only templates that opt in
    #     via ``strict_locality: true`` may serve it.  Unmasked generic
    #     ``image-edit`` (which has no strict-locality marker) is rejected.
    #   * If the template is strict-locality capable, the caller MUST supply
    #     a contract-derived ``metadata.mask_provenance``.  We validate it
    #     here so any tampering or drift fails closed before enqueue.
    request_strict = _request_asserts_strict_locality(metadata)
    template_strict = _template_declares_strict_locality(tmpl)
    if request_strict and not template_strict:
        return None, _strict_locality_rejection(
            gen_type=gen_type,
            reason="request_declared_strict_locality_but_template_not_strict",
            suggested="image-edit-q5-bars-masked-qualification",
        )
    if template_strict:
        provenance = (metadata or {}).get("mask_provenance")
        if not provenance:
            return None, _strict_locality_rejection(
                gen_type=gen_type,
                reason="missing_mask_provenance",
                suggested="image-edit-q5-bars-masked-qualification",
            )
        provenance_error = _validate_mask_provenance(provenance)
        if provenance_error:
            return None, provenance_error

    routing_group = tmpl.get("routing_group") or (gen_type + "-gen")
    allowed_routing_groups = _declared_generation_routing_groups(cfg)
    if routing_group not in allowed_routing_groups:
        return None, {
            "error": (
                f"Unknown routing_group: {routing_group!r}. Expected one of "
                f"{sorted(allowed_routing_groups)}; add a declared routing group "
                f"field to the '{gen_type}' entry in services.json "
                f"::generation_templates (PR3 / PR5)."),
            "status": 400,
        }

    # Cross-type guard (mirrors PR4's config-load guard, at submit time).
    # The template's `backend` must point to a service with
    # routing_group_type=="generation"; otherwise we'd be queueing an LLM-
    # shaped (or undefined) entry onto a generation stream.
    backend = tmpl.get("backend", "")
    svc_cfg = services_cfg.get(backend, {})
    if svc_cfg.get("routing_group_type", "llm") != "generation":
        return None, {
            "error": (
                f"Template '{gen_type}' does not target a generation_backend "
                f"(service '{backend}' has routing_group_type="
                f"{svc_cfg.get('routing_group_type', 'llm')!r})"),
            "status": 400,
        }
    if svc_cfg.get("enabled", True) is False:
        return None, {
            "error": f"Generation backend service '{backend}' is disabled",
            "status": 409,
        }

    # ComfyUI-compatible workflow backend — load the declared workflow,
    # inject caller params, and target the independently managed service
    # named by `backend`. Existing backend="comfyui" templates remain
    # supported without needing to opt into the explicit protocol field.
    workflow_backend = tmpl.get("workflow_backend")
    if workflow_backend is not None and workflow_backend not in {"comfyui", "audio-cpp"}:
        return None, {
            "error": f"Unknown workflow_backend: {workflow_backend!r}",
            "status": 400,
        }
    if backend.startswith("comfyui-") and workflow_backend is None:
        return None, {
            "error": "Named ComfyUI service requires workflow_backend='comfyui'",
            "status": 400,
        }
    if backend == "comfyui" or workflow_backend == "comfyui":
        return await _build_comfyui_workflow_entry(
            service_name=backend,
            tmpl=tmpl,
            params=params,
            job_id=str(uuid.uuid4())[:8],
            priority=priority,
            callback_url=callback_url,
            metadata=metadata,
            priority_class=_priority_payload.get("priority_class"),
            compiled_pipeline=compiled_pipeline,
        )

    if workflow_backend == "audio-cpp":
        if str((svc_cfg.get("metadata") or {}).get("runtime") or "audio-cpp") != "audio-cpp":
            return None, {
                "error": "audio.cpp template does not target an audio.cpp runtime",
                "status": 409,
            }

    endpoint = tmpl.get("endpoint")               # e.g. http://127.0.0.1:8120
    req_path = tmpl.get("request_path", svc_cfg.get("http_path", "/"))
    param_map = tmpl.get("param_map", {}) or {}

    # Apply param_map (src→dst renames) then pass through any extra params
    # the caller supplied that aren't routing/control fields.
    body = {}
    for src, dst in param_map.items():
        if src in params:
            body[dst] = params[src]
    for src, val in params.items():
        if src in param_map or src in body:
            continue
        if src in (
            "callback_url", "metadata", "priority", "priority_class",
            "priority_convention", "parent_job_id", "service_pipeline_id",
        ):
            continue
        body[src] = val

    import base64 as _b64
    job_id = str(uuid.uuid4())[:8]
    _priority_fields = priority_envelope(
        priority,
        priority_class=_priority_payload.get("priority_class"),
        convention=PriorityConvention.GENERATION_HIGHER_IS_URGENT,
    ).to_fields()
    _entry_metadata = dict(metadata or {})
    if isinstance(compiled_pipeline, Mapping) and compiled_pipeline.get("stages"):
        _entry_metadata["worker_pipeline"] = copy.deepcopy(dict(compiled_pipeline))
    entry = {
        "job_id": job_id,
        "routing_group": routing_group,
        "routing_group_type": "generation",
        "service_name": backend,
        "bundle": tmpl.get("bundle"),
        "endpoint": endpoint or "",
        "http_method": "POST",
        "http_path": req_path,
        "body_b64": _b64.b64encode(
            json.dumps(body).encode("utf-8")
        ).decode("ascii"),
        "headers": json.dumps({"Content-Type": "application/json"}),
        "callback_url": callback_url or "",
        "metadata": json.dumps(_entry_metadata),
        **_priority_fields,
        "priority_source": "request",
        "submitted_at": time.time(),
    }
    if workflow_backend == "audio-cpp":
        entry["request_kind"] = "audio_cpp_task"
        entry["native_model_id"] = str(tmpl.get("model_key") or body.get("model") or "")
    return entry, None


def _resolve_inject_keys(tmpl: dict) -> tuple:
    """Return inject_keys for a generation template.

    Per-template override lets each ComfyUI workflow specify its own
    (src_param, node_id, field) triple, so a new workflow doesn't require a
    code change to gpu-manager.  If the template doesn't set `inject_keys`,
    this returns an empty tuple and the injection loop is a no-op (workflow
    defaults are left untouched).

    Args:
        tmpl: a generation_templates entry from services.json.

    Returns:
        Tuple of (src_param, node_id_str, field_name) triples, normalised
        so node_id is a string (workflow JSON keys are strings).
    """
    keys = (tmpl or {}).get("inject_keys")
    if not keys:
        return ()
    return tuple((str(k[0]), str(k[1]), str(k[2])) for k in keys)


def _extract_json_object_text(text: str):
    """Parse a bounded JSON object, tolerating a single fenced wrapper."""
    value = (text or "").strip()
    if value.startswith("```") and value.endswith("```"):
        lines = value.splitlines()
        if len(lines) >= 3:
            value = "\n".join(lines[1:-1]).strip()
    try:
        parsed = json.loads(value)
    except (TypeError, json.JSONDecodeError):
        return None
    return parsed if isinstance(parsed, dict) else None


def _derive_prompt_atomic_requirements(prompt: str) -> list[str]:
    """Extract explicit count, exclusion, and must-preserve clauses."""
    import re
    result: list[str] = []
    seen: set[str] = set()
    for sentence in re.split(r"[.;\n]+", str(prompt or "")):
        for clause in re.split(r",\s*", sentence):
            value = clause.strip(" -:\t")
            if not 3 <= len(value) <= 300:
                continue
            if not re.search(
                r"\b(exactly|single|only|no|not|without|must|one|two|three|four|five)\b",
                value,
                flags=re.IGNORECASE,
            ):
                continue
            key = value.casefold()
            if key in seen:
                continue
            seen.add(key)
            result.append(value)
            if len(result) >= 32:
                return result
    return result


def _build_visual_check_plan(prompt: str, policy: dict) -> list[dict]:
    """Split prompt obligations into small, independently verifiable checks."""
    import re

    requirements = list(policy.get("requirements") or [])
    requirements.extend(_derive_prompt_atomic_requirements(prompt))
    import re
    for sentence in re.split(r"[.;\n]+", str(prompt or "")):
        sentence_has_no_list = sentence.strip().casefold().startswith("no ")
        for clause_index, clause in enumerate(re.split(r",\s*", sentence)):
            value = clause.strip(" -:\t")
            if sentence_has_no_list and clause_index > 0:
                value = re.sub(r"^or\s+", "", value, flags=re.IGNORECASE)
                if value and not value.casefold().startswith("no "):
                    value = f"No {value}"
            if value and re.search(
                r"\b(above|below|left|right|center|centered|arranged|between|color|colour|lighting|light|shadow|palette|pose|anatom|text|logos?|watermarks?|background|framing|camera|view)\b",
                value,
                flags=re.IGNORECASE,
            ):
                requirements.append(value)
    prompt_folded = str(prompt or "").casefold()
    normalized = []
    exclusion_terms = {
        "text": "text", "logo": "logo", "logos": "logos",
        "watermark": "watermark", "watermarks": "watermarks",
        "people": "people", "letters": "letters", "numbers": "numbers",
    }
    for item in requirements:
        value = str(item).strip()
        folded = re.sub(r"^or\s+", "", value.casefold()).strip()
        if folded in exclusion_terms and re.search(
            rf"\bno\b[^.\n]{{0,240}}\b{re.escape(exclusion_terms[folded])}\b",
            prompt_folded,
        ):
            value = f"No {folded}"
        normalized.append(value)
    requirements = list(dict.fromkeys(item for item in normalized if item))
    categories = []
    for requirement in requirements:
        text = requirement.casefold()
        if re.search(r"\b(exactly|single|one|two|three|four|five|count|number)\b", text):
            category = "count"
        elif re.search(r"\b(above|below|left|right|center|centered|arranged|between|position|spatial)\b", text):
            category = "spatial"
        elif re.search(r"\b(text|logo|watermark|letter|word|spelling|legible)\b", text):
            category = "text"
        elif re.search(r"\b(color|colour|lighting|light|shadow|palette|amber|orange|blue|red)\b", text):
            category = "lighting"
        elif re.search(r"\b(pose|anatom|limb|hand|face|action|gesture)\b", text):
            category = "pose"
        elif re.search(r"\b(composition|framing|background|camera|view|crop)\b", text):
            category = "composition"
        else:
            category = "appearance"
        categories.append((category, requirement))
    order = {"count": 0, "spatial": 1, "text": 2, "lighting": 3, "pose": 4, "composition": 5, "appearance": 6}
    return [
        {"id": f"check-{index + 1}", "category": category, "requirement": requirement}
        for index, (category, requirement) in enumerate(sorted(categories, key=lambda item: (order[item[0]], requirements.index(item[1]))))
    ]


def _slot_reaper_max_age(service_config: dict) -> int:
    """Return the bounded worker-slot lease for one service.

    A service that polls ComfyUI workflow history is never leased for less than
    the longest generation poll (plus margin): the reaper must not fail a job
    whose poll loop is still legitimately running.
    """
    timeout = int(service_config.get("forward_timeout", 600))
    grace = int(service_config.get("post_load_grace_seconds", 0) or 0)
    return bounded_lease_s(
        timeout + 60 + grace,
        polls_workflows=service_polls_workflows(service_config),
    )


def _pending_reaper_max_idle_ms(service_config: dict) -> int:
    """Return the pending-entry lease, preserving the historical 15-minute floor.

    The same poll-deadline floor as the slot lease applies to an explicit
    ``pending_lease_seconds`` override, so no configuration can make the PEL
    lease expire before a generation poll deadline.
    """
    admission = service_config.get("admission", {}) or {}
    polls = service_polls_workflows(service_config)
    if isinstance(admission, Mapping) and admission.get("pending_lease_seconds") is not None:
        try:
            requested = int(admission["pending_lease_seconds"])
        except (TypeError, ValueError):
            requested = 0
        if requested > 0:
            return max(60_000, bounded_lease_s(requested, polls_workflows=polls) * 1000)
    return max(900_000, _slot_reaper_max_age(service_config) * 1000)


def _pending_orphan_ttl_ms(service_config: dict) -> int:
    """Return the bounded age-from-submission TTL before pending work is orphaned."""
    admission = service_config.get("admission", {}) or {}
    raw = admission.get("orphan_ttl_seconds", 1800) if isinstance(admission, Mapping) else 1800
    try:
        requested = int(raw)
    except (TypeError, ValueError):
        requested = 1800
    return min(86_400_000, max(60_000, requested * 1000))


def _pending_entry_submission_age_ms(
    entry_id: str,
    now_ms: int | None = None,
    submitted_at_ms: int | None = None,
) -> int:
    """Return immutable submission age; missing legacy identity fails closed as fresh."""
    try:
        if submitted_at_ms is None:
            return 0
        submitted_ms = int(submitted_at_ms)
        current_ms = int(now_ms if now_ms is not None else time.time() * 1000)
        return max(0, current_ms - submitted_ms)
    except (TypeError, ValueError):
        return 0


REAPER_STALE_DEAD_LETTER_FLOOR_MS = 3_600_000


def _reaper_nack_max_retries(idle_ms: int | float, lease_ms: int | float) -> int:
    """Return the nack retry budget for a reaped pending entry.

    An entry idle far beyond its lease belongs to a submitter that is long
    gone; re-queueing it would load a generation bundle and evict the idle
    baselines for a job nobody wants (2026-10-06 13:52 incident). A budget of
    1 makes ``nack`` dead-letter it instead. Ordinary stuck entries keep 4.
    """
    ceiling = max(REAPER_STALE_DEAD_LETTER_FLOOR_MS, 4 * int(lease_ms or 0))
    return 1 if float(idle_ms or 0) > ceiling else 4


def _background_crop_regions(width: int, height: int) -> dict[str, tuple[int, int, int, int]]:
    """Return outer-edge crops that exclude the centered foreground subject."""
    edge = max(1, int(width * 0.28))
    return {
        "left background": (0, 0, edge, height),
        "right background": (max(0, width - edge), 0, width, height),
    }


def _vision_request_headers(url: str, policy: Mapping[str, Any]) -> tuple[dict[str, str], bool]:
    """Headers for a vision QC call; a self-call becomes a combined Gemma broker job.

    When ``vision_url`` is this controller's own loopback listener (plan 5.1),
    the call carries the controller token and ``X-Backend`` (policy
    ``vision_backend``, default the Gemma group) so it queues on the broker:
    Gemini first, GPU Gemma when the cloud vision member is unavailable.
    Redirects are refused so the token never leaves loopback.
    """
    from urllib.parse import urlsplit

    parsed = urlsplit(url)
    try:
        port = parsed.port
    except ValueError:
        port = None
    if not (
        parsed.scheme == "http"
        and (parsed.hostname or "").lower() in {"127.0.0.1", "localhost", "::1"}
        and port == int(LISTEN_PORT)
    ):
        return {}, True
    headers = {"X-Backend": str(policy.get("vision_backend") or _COMBINED_GEMMA_ROUTING_GROUP)}
    token = _api_token()
    if token:
        headers["Authorization"] = f"Bearer {token}"
    return headers, False


async def _analyze_image_with_local_vision(
    image_bytes: bytes, *, prompt: str, policy: dict,
):
    """Use local Gemma multimodal as the pixel-grounded observation layer."""
    import base64 as _base64
    import io
    import re

    if not image_bytes:
        raise RuntimeError("local vision received empty image")
    # Fail closed: the former CPU Gemma vision fallback was retired 2026-10-10.
    # Vision is served by the fleet LLM router, so the policy must name vision_url.
    vision_url = str(policy.get("vision_url") or "").strip()
    if not vision_url:
        raise RuntimeError(
            "local vision policy has no vision_url; refusing to call a default endpoint "
            "(the CPU vision backend was retired 2026-10-10, configure generation template "
            "post_generate.vision_url to the fleet LLM router)"
        )
    try:
        from PIL import Image
        source_image = Image.open(io.BytesIO(image_bytes)).convert("RGB")
        image = source_image.copy()
        image.thumbnail((384, 384))
        buf = io.BytesIO()
        image.save(buf, format="PNG")
        vision_bytes = buf.getvalue()
    except Exception as exc:
        raise RuntimeError(f"local vision image decode failed: {exc}") from exc

    requirements = list(policy.get("requirements") or [])
    requirements.extend(_derive_prompt_atomic_requirements(prompt))
    requirements = list(dict.fromkeys(str(item).strip() for item in requirements if str(item).strip()))[:32]
    request_text = (
        "Inspect the supplied generated image pixels against the requested image prompt and "
        "every atomic requirement below. Report only visible evidence; never infer hidden "
        "details. Inspect foreground and background, including blurred or partially visible "
        "objects. Counts and exclusions such as exactly/no/without are strict: create one "
        "separate atomic check for every listed requirement and do not merge them. "
        "Return ONLY valid JSON with keys observations (string array), atomic_checks "
        "(array of {requirement,status,evidence}, status pass|fail|uncertain), "
        "quality_defects (string array), and summary (string).\n\n"
        f"REQUESTED PROMPT:\n{prompt}\n\n"
        f"ATOMIC REQUIREMENTS:\n{json.dumps(requirements, ensure_ascii=False)}"
    )
    data_url = "data:image/png;base64," + _base64.b64encode(vision_bytes).decode("ascii")
    body = {
        "model": str(policy.get("vision_model") or "gemma-4"),
        "messages": [
            {"role": "system", "content": "You are a strict visual evidence recorder. Output JSON only."},
            {"role": "user", "content": [
                {"type": "image_url", "image_url": {"url": data_url}},
                {"type": "text", "text": request_text},
            ]},
        ],
        "max_tokens": int(policy.get("vision_max_tokens", 900)),
        "temperature": 0.0,
        "response_format": {"type": "json_object"},
    }
    import aiohttp as _aiohttp
    url = vision_url
    timeout_s = int(policy.get("vision_timeout_s", 180))
    headers, allow_redirects = _vision_request_headers(url, policy)
    async with _aiohttp.ClientSession(
        timeout=_aiohttp.ClientTimeout(total=timeout_s, connect=3),
    ) as sess:
        async with sess.post(
            url, json=body, headers=headers, allow_redirects=allow_redirects,
        ) as resp:
            text = await resp.text()
            if resp.status != 200:
                raise RuntimeError(f"local vision HTTP {resp.status}: {text[:200]}")
            try:
                response = json.loads(text)
                content = response["choices"][0]["message"]["content"]
            except (json.JSONDecodeError, KeyError, IndexError, TypeError) as exc:
                raise RuntimeError("local vision returned malformed response") from exc
    parsed = _extract_json_object_text(content)
    if not parsed or not isinstance(parsed.get("atomic_checks"), list):
        raise RuntimeError("local vision returned invalid observation JSON")

    # A single 384px overview can hide small prohibited background objects.
    # When the prompt contains explicit exclusions, inspect left/right crops in
    # separate 384px requests.  Sequential calls avoid ik_llama's fatal 768-grid
    # flash-attention path while preserving small-object evidence.
    if not policy.get("_detail_pass"):
        exclusions = [
            item for item in _derive_prompt_atomic_requirements(prompt)
            if re.search(r"^(no|not|without)\b", item.strip(), flags=re.IGNORECASE)
        ]
        if exclusions:
            width, height = source_image.size
            regions = _background_crop_regions(width, height)
            for region_name, box in regions.items():
                crop_buffer = io.BytesIO()
                source_image.crop(box).save(crop_buffer, format="PNG")
                child_policy = dict(policy)
                child_policy["_detail_pass"] = True
                child_policy["requirements"] = exclusions
                child_policy["vision_max_tokens"] = min(
                    1000, int(policy.get("vision_max_tokens", 900))
                )
                child_prompt = (
                    f"Background region inspection: {region_name}. "
                    "Ignore any cropped fragment of the main centered subject at the inner edge. "
                    "Blurred, partial, or out-of-focus separate objects still count. Requirements: "
                    + "; ".join(exclusions)
                )
                try:
                    detail = await _analyze_image_with_local_vision(
                        crop_buffer.getvalue(),
                        prompt=child_prompt,
                        policy=child_policy,
                    )
                    parsed.setdefault("observations", []).extend(
                        f"{region_name}: {item}"
                        for item in detail.get("observations") or []
                    )
                    parsed["atomic_checks"].extend(detail.get("atomic_checks") or [])
                    parsed.setdefault("quality_defects", []).extend(
                        detail.get("quality_defects") or []
                    )
                except Exception as exc:
                    logger.warning(
                        "local vision detail crop failed region=%s err=%s",
                        region_name,
                        exc,
                    )
                    parsed["atomic_checks"].extend({
                        "requirement": item,
                        "status": "uncertain",
                        "evidence": f"{region_name} detail inspection unavailable",
                    } for item in exclusions)
    return parsed


async def _run_granular_visual_checks(image_bytes: bytes, *, prompt: str, policy: dict) -> list[dict]:
    """Run independently bounded local-vision checks for each planned obligation."""
    plan = _build_visual_check_plan(prompt, policy)
    max_checks = max(1, int(policy.get("granular_max_checks", 12)))
    results = []
    for item in plan[:max_checks]:
        requirement = item["requirement"]
        child_policy = dict(policy)
        child_policy["_detail_pass"] = True
        child_policy["requirements"] = [requirement]
        child_policy["vision_max_tokens"] = min(900, int(policy.get("vision_max_tokens", 1400)))
        check_prompt = (
            "Perform only this one visual check. Do not assess unrelated attributes. "
            "Report visible evidence and mark uncertain when pixels are ambiguous.\n\n"
            f"CHECK CATEGORY: {item['category']}\nREQUIREMENT: {requirement}"
        )
        try:
            observation = await _analyze_image_with_local_vision(
                image_bytes, prompt=check_prompt, policy=child_policy,
            )
            atomic = [
                check for check in observation.get("atomic_checks") or []
                if str(check.get("requirement") or "").strip()
            ]
            selected = atomic[0] if atomic else {
                "requirement": requirement,
                "status": "uncertain",
                "evidence": "No atomic result was returned for this check",
            }
            results.append({**item, **selected})
        except Exception as exc:
            results.append({
                **item,
                "status": "uncertain",
                "evidence": f"Granular visual check unavailable: {str(exc)[:240]}",
            })
    return results

def _reduce_visual_qc_decision(
    observations: dict, critique_decision: dict, policy: dict,
) -> dict:
    """Deterministically reduce atomic evidence into one terminal verdict.

    The critique input is advisory only.  Atomic evidence and the policy gate the
    terminal result, so a critique ``pass`` cannot erase a blocking P0 observation.

    Task 3 (anti-lineup atoms) is additive: when ``observations`` carries an
    ``anti_lineup_atoms`` envelope, the reducer folds each emitted atom into
    ``observations.atomic_checks`` (deduped by requirement name) and applies
    the closed P0 fail-closed rules below.  The legacy path is preserved when
    no envelope is present.
    """
    observations = copy.deepcopy(observations) if isinstance(observations, dict) else {}
    critique_decision = copy.deepcopy(critique_decision) if isinstance(critique_decision, dict) else {}
    policy = copy.deepcopy(policy) if isinstance(policy, dict) else {}

    # ── Task 3: anti_lineup_atoms envelope handling (additive) ───────────
    # The six closed atom names in the order required by the producer.
    _ATOMIC_P0_NAMES = (
        "interaction_clusters",
        "gaze_alignment",
        "spatial_distribution",
    )
    _ATOMIC_STATUSES = {"pass", "fail", "uncertain"}
    _ATOMIC_NAMES = {"count", "role_diversity", "instrument_diversity", *_ATOMIC_P0_NAMES}
    # Function-local identity sentinel: no supplied JSON value can collide with it.
    _MISSING = object()

    envelope = observations.get("anti_lineup_atoms", _MISSING)
    if envelope is _MISSING:
        # Legacy path — no envelope was provided. Continue with the existing
        # reduction. The reducer remains byte-identical to its Task 2 form
        # when ``anti_lineup_atoms`` is absent from observations.
        folded_atoms_view = None
        envelope_malformed_p0 = False
    else:
        if envelope is None:
            # Evaluator unavailable — fail closed to review with the closed
            # rule id. Nothing is folded; the raw envelope (None) is still
            # preserved verbatim below.
            reducer_input = {
                "observations": copy.deepcopy(observations),
                "critique_decision": copy.deepcopy(critique_decision),
                "policy": copy.deepcopy(policy),
            }
            return {
                "reducer_version": "visual-qc-reducer.v1",
                "terminal_status": "review",
                "decision": "review",
                "terminal_failure": None,
                "human_review_required": True,
                "applied_rule_ids": ["anti_lineup_atoms_evaluator_unavailable"],
                "input_sha256": hashlib.sha256(
                    json.dumps(
                        reducer_input,
                        sort_keys=True,
                        separators=(",", ":"),
                        ensure_ascii=False,
                    ).encode("utf-8")
                ).hexdigest(),
                "conflict_pairs": [],
                "aggregates": {
                    "hard_failures": 0,
                    "hard_uncertain": 0,
                    "soft_failures": 0,
                    "soft_uncertain": 0,
                },
                "overrides": (
                    ["critique_pass_blocked_by_atomic_evidence"]
                    if str(critique_decision.get("decision") or "").strip().casefold()
                    == "pass"
                    else []
                ),
                "raw_observations": copy.deepcopy(observations),
            }

        # Validate through the one public closed-envelope validator before
        # folding. A reducer-local subset would let schema/provenance/order
        # failures reach a critique pass path.
        try:
            from semantic_scene_anti_lineup_observations import validate_anti_lineup_atoms
            validator_errors = validate_anti_lineup_atoms(envelope)
        except Exception as exc:
            validator_errors = [{"code": "VALIDATOR_UNAVAILABLE", "message": str(exc)}]

        atoms_list = envelope.get("atoms") if isinstance(envelope, dict) else None
        atoms_by_name = {}
        envelope_malformed_p0 = False
        envelope_malformed = bool(validator_errors) or not isinstance(envelope, dict) or not isinstance(atoms_list, list)
        if isinstance(atoms_list, list):
            for atom in atoms_list:
                if not isinstance(atom, dict):
                    envelope_malformed = True
                    continue
                name = str(atom.get("name") or "").strip()
                status = str(atom.get("status") or "").strip().casefold()
                evidence = atom.get("evidence")
                if name not in _ATOMIC_NAMES:
                    envelope_malformed = True
                    continue
                if name in atoms_by_name:
                    envelope_malformed = True
                    continue
                if status not in _ATOMIC_STATUSES or not isinstance(evidence, list) or len(evidence) == 0:
                    envelope_malformed = True
                atoms_by_name[name] = atom

        for p0_name in _ATOMIC_P0_NAMES:
            if p0_name not in atoms_by_name:
                envelope_malformed_p0 = True
        if envelope_malformed:
            envelope_malformed_p0 = True
        folded_atoms_view = atoms_by_name

    # Project the folded atoms into ``atomic_checks`` entries, deduping by
    # requirement name against any pre-existing entries so the same name is
    # never folded twice.
    atomic = observations.get("atomic_checks") or []
    if not isinstance(atomic, list):
        atomic = []
    if folded_atoms_view:
        atom_names = {str(name).casefold() for name in folded_atoms_view}
        atomic = [item for item in atomic if not (isinstance(item, dict) and str(item.get("requirement") or item.get("requirement_id") or "").strip().casefold() in atom_names)]
    pre_existing_requirements = set()
    folded_checks = []
    if folded_atoms_view:
        for atom_name, atom in folded_atoms_view.items():
            status = str(atom.get("status") or "").strip().casefold()
            if status not in _ATOMIC_STATUSES:
                continue
            evidence = atom.get("evidence")
            if not isinstance(evidence, list) or len(evidence) == 0:
                continue
            raw_signals = atom.get("raw_signals") if isinstance(atom, dict) else {}
            if not isinstance(raw_signals, dict):
                raw_signals = {}
            if atom_name in _ATOMIC_P0_NAMES:
                hard = True
            elif atom_name == "count":
                hard = str(raw_signals.get("count_status") or "").strip().casefold() == "user_authorized_literal"
            elif atom_name == "role_diversity":
                try:
                    role_floor = int(raw_signals.get("role_floor") or 0)
                except (TypeError, ValueError):
                    role_floor = 0
                hard = role_floor >= 3
            else:
                hard = False
            folded_checks.append({"requirement": atom_name, "status": status, "severity": "hard" if hard else "soft", "hard": hard, "evidence": copy.deepcopy(evidence), "source": "anti_lineup_atoms"})
    atomic = list(atomic) + folded_checks

    if envelope_malformed_p0:
        # The closed P0-missing rule id is recorded later in the decision
        # tree (see ``p0_missing_review`` branch). The actual ``review``
        # status is also applied there so the legacy aggregate path still
        # owns the terminal decision.
        pass

    p0_names = {
        str(item).strip().casefold()
        for key in ("p0_requirements", "hard_requirements")
        for item in (policy.get(key) or [])
        if isinstance(item, (str, int, float)) and str(item).strip()
    }
    for item in policy.get("requirements") or []:
        if isinstance(item, dict):
            name = str(item.get("requirement") or item.get("id") or "").strip()
            severity = str(item.get("severity") or item.get("priority") or "").casefold()
            if name and (severity in {"hard", "p0", "0"} or severity.startswith("p0")):
                p0_names.add(name.casefold())
        elif isinstance(item, str):
            # Legacy string requirements are soft unless explicitly listed P0.
            continue

    checks = []
    statuses_by_requirement = {}
    for index, check in enumerate(atomic):
        if not isinstance(check, dict):
            continue
        requirement = str(check.get("requirement") or check.get("requirement_id") or "").strip()
        status = str(check.get("status") or "").strip().casefold()
        if not requirement or status not in {"pass", "fail", "uncertain"}:
            continue
        severity = str(check.get("severity") or "").casefold()
        hard = requirement.casefold() in p0_names or severity in {"hard", "p0", "0"} or severity.startswith("p0")
        entry = {"index": index, "requirement": requirement, "status": status, "hard": hard}
        checks.append(entry)
        statuses_by_requirement.setdefault(requirement, set()).add(status)

    aggregates = {
        "hard_failures": sum(item["hard"] and item["status"] == "fail" for item in checks),
        "hard_uncertain": sum(item["hard"] and item["status"] == "uncertain" for item in checks),
        "soft_failures": sum(not item["hard"] and item["status"] == "fail" for item in checks),
        "soft_uncertain": sum(not item["hard"] and item["status"] == "uncertain" for item in checks),
    }
    status_order = {"fail": 0, "uncertain": 1, "pass": 2}
    conflict_pairs = []
    for requirement in sorted(statuses_by_requirement, key=str.casefold):
        statuses = statuses_by_requirement[requirement]
        if len(statuses) > 1:
            ordered = sorted(statuses, key=lambda value: status_order[value])
            conflict_pairs.append([requirement, ordered[0], ordered[-1]])

    applied_rule_ids = []
    overrides = []
    terminal_failure = None
    human_review_required = False
    p0_missing_review = envelope_malformed_p0
    if p0_missing_review:
        # Preserve the established P0-specific rule for malformed P0 evidence,
        # while also surfacing the stricter closed-envelope failure reason.
        applied_rule_ids.append("anti_lineup_atoms_missing_for_p0")
        if envelope is not _MISSING and envelope is not None and envelope_malformed:
            applied_rule_ids.append("anti_lineup_atoms_malformed_envelope")
    if conflict_pairs:
        applied_rule_ids.append("same_requirement_contradiction_requires_review")
        terminal_status = "review"
        human_review_required = True
    elif aggregates["hard_failures"]:
        applied_rule_ids.append("hard_p0_fail_reject")
        terminal_status = "reject"
        terminal_failure = "p0_requirement_failed"
    elif aggregates["hard_uncertain"]:
        applied_rule_ids.append("hard_p0_uncertain_review")
        terminal_status = "review"
        human_review_required = True
    elif aggregates["soft_failures"] or aggregates["soft_uncertain"]:
        if p0_names:
            if aggregates["soft_failures"]:
                applied_rule_ids.append("soft_fail_review")
            if aggregates["soft_uncertain"]:
                applied_rule_ids.append("soft_uncertain_review")
            terminal_status = "review"
            human_review_required = True
        else:
            # Without a declared P0 gate, the critique verdict remains advisory in
            # the intended sense: ordinary atomic observations must not turn
            # an otherwise valid edit decision into an unsolicited review.
            terminal_status = str(
                critique_decision.get("decision") or "review"
            ).strip().casefold()
            if terminal_status not in {"pass", "edit", "review", "reject"}:
                terminal_status = "review"
            applied_rule_ids.append("critique_decision_advisory")
            human_review_required = terminal_status in {"review", "reject"}
    else:
        terminal_status = str(critique_decision.get("decision") or "review").strip().casefold()
        if terminal_status not in {"pass", "edit", "review", "reject"}:
            terminal_status = "review"
        applied_rule_ids.append("critique_decision_advisory")
        human_review_required = terminal_status in {"review", "reject"}

    if p0_missing_review:
        # P0 missing/malformed always fails closed to review and blocks any
        # critique ``pass`` regardless of aggregate counts.
        terminal_status = "review"
        human_review_required = True

    if str(critique_decision.get("decision") or "").casefold() == "pass" and terminal_status != "pass":
        if p0_missing_review:
            overrides.append("critique_pass_blocked_by_atomic_p0_fail")
        else:
            overrides.append(
                "critique_pass_blocked_by_atomic_"
                + (
                    "p0_fail"
                    if aggregates["hard_failures"]
                    else "p0_uncertain"
                    if aggregates["hard_uncertain"]
                    else "evidence"
                )
            )

    reducer_input = {"observations": observations, "critique_decision": critique_decision, "policy": policy}
    # Project the folded checks back into a copy of ``observations`` so the
    # caller (and ``raw_observations``) can see the fold without mutating
    # the input dict (which would perturb ``input_sha256``).
    if folded_checks:
        raw_observations = copy.deepcopy(observations)
        raw_observations["atomic_checks"] = copy.deepcopy(atomic)
    else:
        raw_observations = copy.deepcopy(observations)
    return {
        "reducer_version": "visual-qc-reducer.v1",
        "terminal_status": terminal_status,
        "decision": terminal_status,
        "terminal_failure": terminal_failure,
        "human_review_required": human_review_required,
        "applied_rule_ids": applied_rule_ids,
        "input_sha256": hashlib.sha256(json.dumps(reducer_input, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).hexdigest(),
        "conflict_pairs": conflict_pairs,
        "aggregates": aggregates,
        "overrides": overrides,
        "raw_observations": raw_observations,
    }
async def _run_grounded_image_qc(
    image_bytes: bytes, *, prompt: str, policy: dict, image_name: str,
):
    """Run local pixel observations and reduce them without external critique."""
    # Fail closed: the vision endpoint must come from the policy. No hard-coded
    # fallback endpoint is consulted from this path.
    if not str(policy.get("vision_url") or "").strip():
        logger.warning("image_qc: fail_closed reason=vision_url_not_configured")
        return {
            "decision": "review",
            "score": 0,
            "issues": [],
            "edit_instruction": "",
            "summary": "QC unavailable: no vision_url configured in the QC policy",
            "qc_status": "unavailable",
            "qc_failure": True,
            "failure_reason": "qc_unavailable",
            "error": "vision_url_not_configured",
        }
    try:
        observations = await _analyze_image_with_local_vision(
            image_bytes, prompt=prompt, policy=policy,
        )
        if policy.get("granular_checks_enabled", False):
            granular = await _run_granular_visual_checks(
                image_bytes, prompt=prompt, policy=policy,
            )
            observations["granular_checks"] = granular
            observations.setdefault("atomic_checks", []).extend(granular)
        # No external controller is consulted. Without a locally produced
        # approval signal the critique input stays neutral; the reducer may only
        # fail or review from grounded evidence and must never manufacture a pass.
        decision = {"decision": "review", "provider": "local-observations"}
        reduced = _reduce_visual_qc_decision(observations, decision, policy)
        decision.update(reduced)
        decision["grounded_observations"] = observations
        return decision
    except Exception as exc:
        # Phase 0A: typed unavailable review — NEVER a synthetic 'pass'.
        # The validator hard-rejects malformed payloads (e.g. edit_instruction_required);
        # surface that as decision='review' with qc_status='unavailable', qc_failure=True,
        # and a typed failure_reason so the caller can distinguish unavailable QC from
        # an accepted (pass) result.
        reason = str(exc)
        logger.warning("image_qc: fail_open reason=%s", exc)
        return {
            "decision": "review",
            "score": 0,
            "issues": [],
            "edit_instruction": "",
            "summary": "QC unavailable; raw Krea output returned",
            "qc_status": "unavailable",
            "qc_failure": True,
            "failure_reason": "qc_unavailable",
            "error": reason[:500],
        }


def _build_generic_qwen_handoff_provenance(
    *, source_bytes: bytes, source_descriptor: dict, staged_source: str,
    workflow_path: str, instruction: str,
) -> dict:
    """Build immutable evidence for a non-masked Krea -> Qwen correction handoff.

    This is deliberately distinct from strict-locality mask provenance.  The
    generic editor is allowed to affect the full image, so consumers must not
    infer a region-preservation guarantee from this record.
    """
    import hashlib
    from pathlib import Path

    normalized_descriptor = {
        key: str(source_descriptor.get(key) or "")
        for key in ("filename", "subfolder", "type")
    }
    workflow_bytes = Path(workflow_path).read_bytes()
    return {
        "schema": "gpu-manager.generic-qwen-handoff.v1",
        "source": {
            "sha256": hashlib.sha256(source_bytes).hexdigest(),
            "descriptor": normalized_descriptor,
        },
        "staged_source": {
            "filename": str(staged_source),
            "sha256": hashlib.sha256(source_bytes).hexdigest(),
        },
        "qwen_workflow": {
            "path": str(Path(workflow_path).resolve()),
            "sha256": hashlib.sha256(workflow_bytes).hexdigest(),
        },
        "instruction_sha256": hashlib.sha256(instruction.encode("utf-8")).hexdigest(),
        "strict_locality": False,
    }


def _sanitize_qwen_denoise(denoise):
    """Canonical sanitizer for the Qwen edit workflow KSampler denoise value.

    This is the single workflow-injection boundary for node 13 denoise.
    It rejects non-finite values, out-of-range finite values, and any
    non-numeric types BEFORE the value can reach ComfyUI's KSampler.

    Contract (see test_gpu_runtime_remediations.py denoise-boundary block):
      * Finite numeric in [0.0, 0.6]   -> returned unchanged.
      * Finite numeric > 0.6           -> clamped to 0.6 (high-value cap).
      * Finite numeric < 0.0           -> ValueError (out of range).
      * Non-finite (nan / +inf / -inf) -> ValueError.
      * Non-numeric (None / str / bool) -> ValueError (no silent coercion).
    """
    if not isinstance(denoise, (int, float)) or isinstance(denoise, bool):
        raise ValueError(
            f"qwen denoise must be a real number, got {type(denoise).__name__}: {denoise!r}"
        )
    value = float(denoise)
    if value != value or value in (float("inf"), float("-inf")):
        raise ValueError(f"qwen denoise must be finite, got {value!r}")
    if value < 0.0:
        raise ValueError(
            f"qwen denoise must be >= 0.0, got {value!r}"
        )
    return min(value, 0.6)


def _render_qwen_edit_workflow(
    *, workflow_path: str, source_image: str, prompt: str, seed: int,
    steps: int, cfg: float, denoise: float, prefix: str,
):
    """Render the server-owned Qwen 2511 correction workflow exactly."""
    sanitized_denoise = _sanitize_qwen_denoise(denoise)
    with open(workflow_path) as handle:
        workflow = json.load(handle)
    from comfyui_workflow_sanitize import sanitize_comfyui_workflow
    workflow = sanitize_comfyui_workflow(
        workflow, source=f"_render_qwen_edit_workflow:{workflow_path}",
    )
    workflow["4"]["inputs"]["image"] = source_image
    workflow["8"]["inputs"]["prompt"] = prompt
    workflow["13"]["inputs"]["seed"] = int(seed)
    workflow["13"]["inputs"]["steps"] = int(steps)
    workflow["13"]["inputs"]["cfg"] = float(cfg)
    workflow["13"]["inputs"]["denoise"] = sanitized_denoise
    workflow["15"]["inputs"]["filename_prefix"] = str(prefix)
    return workflow


def _resolve_inline_qwen_template(policy: dict) -> dict:
    """Resolve an optional named Qwen editor template for a parent correction.

    Named templates are subject to the same qualification and Q5 topology gates
    as standalone submissions. Legacy raw workflow policies remain supported.
    """
    template_name = str(policy.get("qwen_template") or "").strip()
    if not template_name:
        return {}
    templates = (_load_services_config() or {}).get("generation_templates", {}) or {}
    template = templates.get(template_name)
    if not isinstance(template, dict):
        raise RuntimeError(f"inline Qwen template not found: {template_name}")
    qualification_error = _validate_template_qualification(template_name, template)
    if qualification_error:
        raise RuntimeError(str(qualification_error["error"]))
    identity_error = _validate_q5_template_identity(template_name, template)
    if identity_error:
        raise RuntimeError(str(identity_error["error"]))
    if template.get("backend") != "comfyui-qwen" or template.get("routing_group") != "qwen-edit-gen":
        raise RuntimeError("inline Qwen template must target comfyui-qwen/qwen-edit-gen")
    workflow_path = str(template.get("workflow_template") or "").strip()
    if not workflow_path:
        raise RuntimeError("inline Qwen template declares no workflow_template")
    return {"template": template_name, "workflow_path": workflow_path, "defaults": dict(template.get("defaults") or {})}


def _verified_image_bytes(image_bytes: bytes) -> None:
    import io
    from PIL import Image
    if not image_bytes:
        raise RuntimeError("empty image response")
    try:
        with Image.open(io.BytesIO(image_bytes)) as image:
            image.verify()
    except Exception as exc:
        raise RuntimeError(f"invalid image response: {exc}") from exc


async def _stage_image_to_comfyui_input(
    *, session, comfyui_base: str, image_bytes: bytes, filename: str,
):
    import aiohttp as _aiohttp
    _verified_image_bytes(image_bytes)
    safe_name = "".join(
        char for char in str(filename) if char.isalnum() or char in {"-", "_", "."}
    ) or "qc-source.png"
    form = _aiohttp.FormData()
    form.add_field("image", image_bytes, filename=safe_name, content_type="image/png")
    form.add_field("type", "input")
    form.add_field("overwrite", "true")
    async with session.post(
        f"{comfyui_base.rstrip('/')}/upload/image", data=form,
        timeout=ClientTimeout(total=60),
    ) as resp:
        text = await resp.text()
        if resp.status not in {200, 201}:
            raise RuntimeError(f"ComfyUI input upload HTTP {resp.status}: {text[:200]}")
        try:
            payload = json.loads(text)
        except json.JSONDecodeError as exc:
            raise RuntimeError("ComfyUI input upload returned non-JSON") from exc
    name = str(payload.get("name") or "").strip()
    if not name:
        raise RuntimeError("ComfyUI input upload returned no filename")
    subfolder = str(payload.get("subfolder") or "").strip().strip("/")
    return f"{subfolder}/{name}" if subfolder else name


async def _run_inline_comfyui_workflow(
    *, session, comfyui_base: str, workflow: dict, timeout_s: int,
):
    base = comfyui_base.rstrip("/")
    async with session.post(
        f"{base}/prompt", json={"prompt": workflow},
        timeout=ClientTimeout(total=60),
    ) as resp:
        text = await resp.text()
        if resp.status != 200:
            raise RuntimeError(f"inline ComfyUI submit HTTP {resp.status}: {text[:300]}")
        try:
            prompt_id = str(json.loads(text).get("prompt_id") or "")
        except json.JSONDecodeError as exc:
            raise RuntimeError("inline ComfyUI submit returned non-JSON") from exc
    if not prompt_id:
        raise RuntimeError("inline ComfyUI submit returned no prompt_id")

    deadline = time.monotonic() + int(timeout_s)
    while time.monotonic() < deadline:
        await asyncio.sleep(5)
        async with session.get(
            f"{base}/history/{prompt_id}", timeout=ClientTimeout(total=15),
        ) as hist_resp:
            if hist_resp.status != 200:
                continue
            try:
                history = await hist_resp.json()
            except Exception:
                continue
        entry = history.get(prompt_id)
        if not entry or not (entry.get("status") or {}).get("completed", False):
            continue
        if entry.get("node_errors"):
            raise RuntimeError(
                "inline ComfyUI node errors: " + json.dumps(entry["node_errors"])[:500]
            )
        for output in (entry.get("outputs") or {}).values():
            for image in output.get("images") or []:
                descriptor = {
                    "filename": str(image.get("filename") or ""),
                    "subfolder": str(image.get("subfolder") or ""),
                    "type": str(image.get("type") or "output"),
                }
                async with session.get(
                    f"{base}/view", params=descriptor,
                    timeout=ClientTimeout(total=60),
                ) as view_resp:
                    image_bytes = await view_resp.read()
                    content_type = str(view_resp.headers.get("Content-Type") or "")
                    if view_resp.status != 200 or not content_type.startswith("image/"):
                        raise RuntimeError(
                            f"inline ComfyUI view invalid status/type: "
                            f"{view_resp.status} {content_type}"
                        )
                _verified_image_bytes(image_bytes)
                import base64 as _base64
                descriptor["data_b64"] = _base64.b64encode(image_bytes).decode("ascii")
                descriptor["prompt_id"] = prompt_id
                return descriptor
        raise RuntimeError("inline ComfyUI completed without image output")
    raise TimeoutError(f"inline ComfyUI workflow timed out after {timeout_s}s")


async def _run_qwen_correction_inline(
    *, image_bytes: bytes, instruction: str, policy: dict, session,
    comfyui_base: str, job_id: str, source_descriptor: dict | None = None,
):
    """Run one Qwen correction inside the parent job's ComfyUI ownership."""
    import hashlib
    template_binding = _resolve_inline_qwen_template(policy)
    template_defaults = template_binding.get("defaults", {})
    workflow_path = template_binding.get("workflow_path") or str(
        policy.get("qwen_workflow")
        or str(PROJECT_ROOT / "workflows/qwen-image-edit-2511.json")
    )
    safe_job = "".join(char for char in job_id if char.isalnum() or char in {"-", "_"})
    staged_name = await _stage_image_to_comfyui_input(
        session=session,
        comfyui_base=comfyui_base,
        image_bytes=image_bytes,
        filename=f"qc-source-{safe_job}.png",
    )
    # Explicit model-family boundary: unload Krea before loading Qwen.
    async with session.post(
        f"{comfyui_base.rstrip('/')}/free",
        json={"unload_models": True, "free_memory": True},
        timeout=ClientTimeout(total=120),
    ) as free_resp:
        if free_resp.status != 200:
            raise RuntimeError(f"ComfyUI free before Qwen failed: HTTP {free_resp.status}")
    seed_material = f"{job_id}\n{instruction}".encode("utf-8")
    seed = int.from_bytes(hashlib.sha256(seed_material).digest()[:4], "big")
    workflow = _render_qwen_edit_workflow(
        workflow_path=workflow_path,
        source_image=staged_name,
        prompt=instruction,
        seed=seed,
        steps=int(policy.get("qwen_steps", template_defaults.get("steps", 10))),
        cfg=float(policy.get("qwen_cfg", template_defaults.get("cfg", 4.0))),
        denoise=float(policy.get("qwen_denoise", template_defaults.get("denoise", 1.0))),
        prefix=f"qc-edit-{safe_job}",
    )
    result = await _run_inline_comfyui_workflow(
        session=session,
        comfyui_base=comfyui_base,
        workflow=workflow,
        timeout_s=int(policy.get("qwen_timeout_s", 1800)),
    )
    if policy.get("record_generic_qwen_handoff"):
        result["generic_qwen_handoff"] = _build_generic_qwen_handoff_provenance(
            source_bytes=image_bytes,
            source_descriptor=source_descriptor or {},
            staged_source=staged_name,
            workflow_path=workflow_path,
            instruction=instruction,
        )
    return result


def _fail_closed_post_generation_reason(report) -> str:
    """Return only an explicit policy-selected terminal QC failure reason."""
    if not isinstance(report, dict):
        return ""
    return str(report.get("terminal_failure") or "").strip()


# Task 4 micro-slice B — the three intended-layout P0 atom names from the
# closed six-atom anti-lineup envelope (Task 3 contract). Only these atoms
# can route an image through the anti-lineup correction branch at the
# post-generation seam.
_ANTI_LINEUP_P0_ATOM_NAMES = (
    "interaction_clusters",
    "gaze_alignment",
    "spatial_distribution",
)


def _anti_lineup_p0_atom_statuses(initial) -> list[tuple[str, str]]:
    """Return ``[(atom_name, status), ...]`` for the anti-lineup P0 atoms
    present in the initial QC result, looking through both the closed
    envelope path (``grounded_observations.anti_lineup_atoms.atoms``) and
    the flattened ``atomic_checks`` projection that the pipeline already
    uses for decision reporting.

    Returns an empty list when ``initial`` is not a dict or carries no
    recognizable anti-lineup P0 evidence.
    """
    if not isinstance(initial, dict):
        return []
    out: list[tuple[str, str]] = []
    seen: set[str] = set()

    # Closed envelope path — preferred when available because it carries
    # the full producer/contract provenance the slice relies on.
    envelope = (
        (initial.get("grounded_observations") or {}).get("anti_lineup_atoms")
    )
    if isinstance(envelope, dict):
        for atom in envelope.get("atoms") or []:
            if not isinstance(atom, dict):
                continue
            name = str(atom.get("name") or "").strip()
            if name not in _ANTI_LINEUP_P0_ATOM_NAMES or name in seen:
                continue
            out.append((name, str(atom.get("status") or "").strip().lower()))
            seen.add(name)

    # Flattened atomic_checks projection (used by the existing pipeline
    # for decision reporting). Falls back to ``requirement`` so we accept
    # either field name.
    for check in initial.get("atomic_checks") or []:
        if not isinstance(check, dict):
            continue
        # Honor the explicit ``hard`` flag when present, fall back to the
        # atom-name whitelist for backward compatibility.
        name = str(check.get("requirement") or check.get("name") or "").strip()
        if name not in _ANTI_LINEUP_P0_ATOM_NAMES or name in seen:
            continue
        if "hard" in check and not bool(check.get("hard")):
            continue
        out.append((name, str(check.get("status") or "").strip().lower()))
        seen.add(name)

    return out


def _is_anti_lineup_correction_eligible(initial, policy) -> tuple[bool, str]:
    """Task 4 micro-slice B eligibility guard for the anti-lineup
    correction branch.

    Returns ``(eligible, reason)`` where ``eligible`` is True only when
    ALL of the following hold:

      * ``initial`` is a mapping carrying an ``edit`` or ``reject``
        decision (NOT a terminal ``pass``).
      * ``initial["edit_instruction"]`` is a non-empty string (the bounded
        instruction we are willing to hand to Qwen once).
      * The closed six-atom anti-lineup envelope (or its flattened
        ``atomic_checks`` projection) reports at least one intended-layout
        P0 atom (``interaction_clusters``, ``gaze_alignment``, or
        ``spatial_distribution``) with status ``fail`` or ``uncertain``.

    Rejection reasons:

      * ``"absent_or_malformed_initial"`` — ``initial`` missing/empty.
      * ``"terminal_pass"`` — decision is ``pass`` (regardless of
        ``enhance_on_pass`` policy; the anti-lineup path is path-scoped).
      * ``"missing_bounded_edit_instruction"`` — no usable instruction.
      * ``"decision_not_eligible"`` — decision is something other than
        ``edit``/``reject``/``pass`` (defensive).
      * ``"no_failing_p0_atom"`` — no failing/uncertain P0 atom found.
      * ``"malformed_p0_evidence"`` — neither envelope nor atomic_checks
        projection was found at all.

    The helper is intentionally path-scoped: ``enhance_on_pass`` callers
    are rejected on principle because they are outside the anti-lineup
    contract — even if a P0 atom is also failing.
    """
    if not isinstance(initial, dict) or not initial:
        return False, "absent_or_malformed_initial"
    decision = str(initial.get("decision") or "").strip().lower()
    if decision == "pass":
        return False, "terminal_pass"
    if decision not in {"edit", "reject"}:
        return False, "decision_not_eligible"
    instruction = initial.get("edit_instruction")
    if not isinstance(instruction, str) or not instruction.strip():
        return False, "missing_bounded_edit_instruction"
    p0_statuses = _anti_lineup_p0_atom_statuses(initial)
    if not p0_statuses:
        return False, "malformed_p0_evidence"
    failing = [name for name, status in p0_statuses if status in {"fail", "uncertain"}]
    if not failing:
        return False, "no_failing_p0_atom"
    return True, f"ok:p0_failing={','.join(sorted(failing))}"


async def _run_post_generation_image_pipeline(
    image_data: list, *, prompt: str, policy: dict, session,
    comfyui_base: str, job_id: str,
):
    """Analyze Krea output, optionally correct once, and select the better image."""
    import base64 as _base64
    if not policy.get("enabled") or not image_data:
        return image_data, {
            "selected": "original", "correction_attempted": False,
            "qc_status": "disabled", "qc_blocked": False,
            "terminal_qc_status": "disabled", "human_review_required": False,
        }
    original = dict(image_data[0])
    try:
        original_bytes = _base64.b64decode(original.get("data_b64") or "", validate=True)
        _verified_image_bytes(original_bytes)
    except Exception as exc:
        return image_data, {
            "selected": "original", "correction_attempted": False,
            "qc_status": "invalid_original", "error": str(exc)[:300],
            "qc_blocked": True, "terminal_qc_status": "unavailable",
            "human_review_required": True,
        }
    initial = await _run_grounded_image_qc(
        original_bytes,
        prompt=prompt,
        policy=policy,
        image_name=str(original.get("filename") or "krea-output.png"),
    )
    report = {
        "initial": initial,
        "final": initial,
        "selected": "original",
        "correction_attempted": False,
        "max_corrections": max(0, int(policy.get("max_corrections", 1))),
        "qc_blocked": initial.get("qc_status") == "unavailable",
        "terminal_qc_status": (
            "unavailable"
            if initial.get("qc_status") == "unavailable"
            else str(initial.get("decision") or initial.get("qc_status") or "unknown")
        ),
        "human_review_required": (
            initial.get("qc_status") == "unavailable"
            or initial.get("decision") in {"review", "reject"}
        ),
    }
    if initial.get("qc_status") == "unavailable":
        report["correction_rejected"] = "initial_qc_unavailable"
        if policy.get("fail_closed_on_qc_unavailable"):
            report["terminal_failure"] = (
                "initial_qc_unavailable:"
                f"{str(initial.get('failure_reason') or 'qc_unavailable')}"
            )
        return image_data, report
    correction_instruction = str(initial.get("edit_instruction") or "").strip()
    decision = str(initial.get("decision") or "").strip().lower()
    correction_reason = decision
    configured_plan = []
    actionable = False
    if decision == "pass":
        try:
            below_score = float(initial.get("score", 0)) < float(
                policy.get("enhance_below_score", 10)
            )
        except (TypeError, ValueError):
            below_score = False
        if bool(policy.get("enhance_on_pass")) and below_score:
            correction_reason = "enhance_on_pass"
            configured_plan = [
                item for item in (policy.get("enhance_plan") or [])
                if isinstance(item, dict) and str(item.get("instruction") or "").strip()
            ]
            if not configured_plan:
                configured_instruction = str(
                    policy.get("enhance_instruction") or ""
                ).strip()
                if configured_instruction:
                    configured_plan = [{
                        "requirement": correction_reason,
                        "instruction": configured_instruction,
                    }]
            actionable = bool(configured_plan)
    elif decision in {"edit", "reject"} and correction_instruction:
        configured_plan = [
            item for item in (initial.get("edit_plan") or [])
            if isinstance(item, dict) and str(item.get("instruction") or "").strip()
        ]
        if not configured_plan:
            configured_plan = [{
                "requirement": correction_reason,
                "instruction": correction_instruction,
            }]
        actionable = True
    elif decision == "review" and correction_instruction:
        correction_execution = policy.get("correction_execution")
        correction_enabled = (
            correction_execution is True
            or str(correction_execution or "").strip().lower() == "enabled"
        )
        aggregate = initial.get("aggregate_counts")
        aggregate = aggregate if isinstance(aggregate, dict) else {}
        try:
            hard_failures = int(aggregate.get("hard_failures", 0) or 0)
            hard_uncertain = int(aggregate.get("hard_uncertain", 0) or 0)
        except (TypeError, ValueError):
            hard_failures = 1
            hard_uncertain = 1
        if correction_enabled and hard_failures == 0 and hard_uncertain == 0:
            correction_reason = "actionable_review"
            configured_plan = [
                item for item in (initial.get("edit_plan") or [])
                if isinstance(item, dict)
                and str(item.get("instruction") or "").strip()
            ]
            if not configured_plan:
                configured_plan = [{
                    "requirement": correction_reason,
                    "instruction": correction_instruction,
                }]
            actionable = True

    # Anti-lineup evidence remains strictly fail-closed.  Generic validated
    # edit/reject and explicit enhancement plans do not require anti-lineup
    # atoms, but a supplied envelope or flattened P0 projection is path-owned
    # and must pass the closed eligibility guard.
    grounded = initial.get("grounded_observations")
    has_anti_lineup_envelope = (
        isinstance(grounded, dict) and "anti_lineup_atoms" in grounded
    )
    has_anti_lineup_projection = bool(_anti_lineup_p0_atom_statuses(initial))
    if has_anti_lineup_envelope or has_anti_lineup_projection:
        anti_lineup_eligible, anti_lineup_reason = (
            _is_anti_lineup_correction_eligible(initial, policy or {})
        )
        if not anti_lineup_eligible:
            report["correction_rejected"] = (
                f"anti_lineup_ineligible:{anti_lineup_reason}"
            )
            return image_data, report

    if decision == "review" and policy.get("fail_closed_on_qc_review"):
        report["terminal_failure"] = "initial_qc_review"
    if not actionable or report["max_corrections"] == 0:
        return image_data, report

    try:
        max_edit_stages = max(1, int(policy.get("max_edit_stages", 1)))
    except (TypeError, ValueError):
        max_edit_stages = 1
    max_stages = min(report["max_corrections"], max_edit_stages)
    report["correction_reason"] = correction_reason
    report["correction_attempted"] = True
    report["stages"] = []
    current_images = list(image_data)
    current_bytes = original_bytes
    current_score = float(initial.get("score") or 0)
    bounded_plan = configured_plan[:max_stages]
    for stage_index, stage in enumerate(bounded_plan, start=1):
        instruction = str(stage.get("instruction") or "").strip()
        if not instruction:
            continue
        stage_record = {
            "index": stage_index,
            "requirement": str(stage.get("requirement") or ""),
            "instruction": instruction,
            "selected": False,
        }
        try:
            qwen_kwargs = {
                "image_bytes": current_bytes,
                "instruction": instruction,
                "policy": policy,
                "session": session,
                "comfyui_base": comfyui_base,
                "job_id": f"{job_id}-stage-{stage_index}",
            }
            if policy.get("record_generic_qwen_handoff"):
                qwen_kwargs["source_descriptor"] = current_images[0] if current_images else {}
            edited = await _run_qwen_correction_inline(**qwen_kwargs)
            edited_bytes = _base64.b64decode(edited.get("data_b64") or "", validate=True)
            _verified_image_bytes(edited_bytes)
            # Task 4 micro-slice C — run a final (re-QC) pass on the
            # edited bytes. The terminal-pass verdict decides whether
            # the edited image is selected. Only a final `pass` from
            # QC marks the stage selected; review/reject or unavailable
            # keeps the original and records the rejection reason.
            # A post-edit QC exception is an unavailable terminal verdict,
            # not a reason to accept unverified edited bytes.  Normalize it
            # into the same fail-closed path as an explicit unavailable QC.
            try:
                final_qc = await _run_grounded_image_qc(
                    edited_bytes,
                    prompt=prompt,
                    policy=policy,
                    image_name=str(
                        edited.get("filename") or f"{job_id}-edited.png"
                    ),
                )
            except Exception as qc_exc:
                final_qc = {
                    "decision": "review",
                    "qc_status": "unavailable",
                    "qc_failure": True,
                    "failure_reason": (
                        f"final_qc_call_failed:{type(qc_exc).__name__}"
                    ),
                    "error": str(qc_exc)[:500],
                }
            stage_record["qc"] = final_qc
            report["final"] = final_qc
            final_qc_unavailable = (
                final_qc.get("qc_status") == "unavailable"
                or final_qc.get("qc_failure") is True
            )
            final_decision = str(final_qc.get("decision") or "").strip().lower()
            if final_qc_unavailable:
                stage_record["selected"] = False
                stage_record["rejected"] = "final_qc_unavailable"
                report["stages"].append(stage_record)
                report["qc_blocked"] = True
                report["terminal_qc_status"] = "unavailable"
                report["human_review_required"] = True
                report["correction_rejected"] = "final_qc_unavailable"
                if policy.get("fail_closed_on_qc_unavailable"):
                    report["terminal_failure"] = (
                        "final_qc_unavailable:"
                        f"{str(final_qc.get('failure_reason') or 'qc_unavailable')}"
                    )
                report["selected"] = "last_accepted"
                if any(stage.get("selected") for stage in report["stages"]):
                    return current_images, report
                report["selected"] = "original"
                return image_data, report
            if final_decision != "pass":
                stage_record["selected"] = False
                stage_record["rejected"] = (
                    f"final_qc_{final_decision or 'non_pass'}"
                )
                report["stages"].append(stage_record)
                report["correction_rejected"] = (
                    f"final_qc_{final_decision or 'non_pass'}"
                )
                if any(stage.get("selected") for stage in report["stages"]):
                    report["selected"] = "edited"
                    return current_images, report
                report["selected"] = "original"
                return image_data, report
            current_images = [edited, *current_images[1:]]
            current_bytes = edited_bytes
            stage_record["selected"] = True
            report["stages"].append(stage_record)
            report["terminal_qc_status"] = str(
                final_qc.get("decision") or final_qc.get("qc_status") or "pass"
            )
            report["human_review_required"] = (
                final_qc.get("decision") in {"review", "reject"}
            )
            report["selected"] = "edited"
            report.pop("terminal_failure", None)
            if stage_index < len(bounded_plan):
                continue
            return current_images, report
        except Exception as exc:
            stage_record["rejected"] = "correction_error"
            stage_record["error"] = str(exc)[:500]
            report["stages"].append(stage_record)
            logger.warning(
                "image_qc: qwen correction failed job=%s stage=%s err=%s",
                job_id, stage_index, exc,
            )
            break

    if report["stages"] and report["stages"][-1].get("rejected"):
        report["correction_rejected"] = report["stages"][-1]["rejected"]
    # Slice 0B: when final/post-edit QC is unavailable AFTER an earlier
    # accepted stage, we may still return the last accepted artifact's bytes
    # (current_images already holds them) but we MUST NOT report
    # selected='edited' — the post-edit image never received a trustworthy
    # QC verdict, so callers must not be told to treat it as the chosen
    # edit. Use the stable 'last_accepted' value so downstream consumers
    # can distinguish "this edit cleared QC" from "QC went down mid-edit".
    last_stage = report["stages"][-1] if report["stages"] else {}
    final_qc_block = (
        last_stage.get("rejected") == "final_qc_unavailable"
        and report.get("qc_blocked") is True
        and report.get("terminal_qc_status") == "unavailable"
    )
    any_accepted = any(stage.get("selected") for stage in report["stages"])
    if final_qc_block and any_accepted:
        report["selected"] = "last_accepted"
        return current_images, report
    if any_accepted:
        report["selected"] = "edited"
        return current_images, report
    if report["stages"]:
        report["correction_rejected"] = report["stages"][-1].get("rejected", "no_measured_improvement")
    return image_data, report

def _build_prompt_evidence(
    *,
    original_prompt,
    effective_prompt,
    workflow: dict,
    prompt_target: str,
    enhancer: dict | None = None,
    mask_provenance: dict | None = None,
) -> dict:
    """Build deterministic, bounded evidence for the exact workflow prompt.

    The full workflow body is intentionally not duplicated in Redis. Prompts
    up to 16 KiB are retained exactly (production Krea prompts are far smaller);
    oversized prompts retain hashes, lengths, and bounded head/tail evidence.

    When ``mask_provenance`` is supplied, the schema is bumped to
    ``gpu-manager.prompt-evidence.v2`` and the provenance record is added
    verbatim; every v1 field remains present so downstream consumers can
    read either schema.  v2 emission is used only by the strict-locality
    Q5 bars-masked route (plan line 261).
    """
    import hashlib

    original = "" if original_prompt is None else str(original_prompt)
    effective = "" if effective_prompt is None else str(effective_prompt)
    canonical_workflow = json.dumps(
        workflow, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )
    max_chars = 16384
    exact = len(effective) <= max_chars
    evidence = {
        "schema": "gpu-manager.prompt-evidence.v2" if mask_provenance else
                  "gpu-manager.prompt-evidence.v1",
        "prompt_target": prompt_target,
        "original_prompt_sha256": hashlib.sha256(original.encode("utf-8")).hexdigest(),
        "original_prompt_chars": len(original),
        "effective_prompt_sha256": hashlib.sha256(effective.encode("utf-8")).hexdigest(),
        "effective_prompt_chars": len(effective),
        "effective_prompt_exact": exact,
        "workflow_sha256": hashlib.sha256(
            canonical_workflow.encode("utf-8")
        ).hexdigest(),
        "enhancer": dict(enhancer or {"provider": "none"}),
    }
    if exact:
        evidence["effective_prompt"] = effective
    else:
        evidence["effective_prompt_head"] = effective[:8192]
        evidence["effective_prompt_tail"] = effective[-2048:]
    if mask_provenance:
        # v2: retain every v1 field and add the durable provenance record.
        evidence["mask_provenance"] = dict(mask_provenance)
    return evidence


async def _prepare_comfyui_body_after_claim(job: dict, body: bytes):
    """Verify the admitted raw prompt survived to the claimed workflow.

    Returns ``(body_bytes, prompt_evidence_or_none)``.  The body is forwarded
    byte-for-byte: nothing rewrites the prompt here, so no outbound enhancement
    call is made and no retired-provider provenance is recorded.  Evidence
    names the admitted raw prompt explicitly, and a workflow whose prompt target
    no longer carries it is refused instead of forwarded.
    """
    try:
        metadata = json.loads(job.get("metadata") or "{}")
    except (TypeError, json.JSONDecodeError):
        metadata = {}
    pipeline = metadata.get("worker_pipeline") or {}
    raw_prompt = str(pipeline.get("original_prompt") or "")
    prompt_target = str(pipeline.get("prompt_target") or "")
    if not raw_prompt or ".inputs." not in prompt_target:
        return body, None

    try:
        workflow = json.loads(body.decode("utf-8"))["prompt"]
        node_id, field = prompt_target.split(".inputs.", 1)
        effective_prompt = str(workflow[node_id]["inputs"][field])
    except (UnicodeDecodeError, json.JSONDecodeError, KeyError, TypeError) as exc:
        raise RuntimeError(
            f"could not verify prompt target {prompt_target}: {exc}"
        ) from exc
    if effective_prompt != raw_prompt:
        raise RuntimeError(
            f"prompt target {prompt_target} no longer carries the admitted "
            "raw prompt"
        )
    evidence = _build_prompt_evidence(
        original_prompt=raw_prompt,
        effective_prompt=effective_prompt,
        workflow=workflow,
        prompt_target=prompt_target,
        enhancer={"provider": "none"},
    )
    return body, evidence


async def _build_comfyui_workflow_entry(
    *, service_name="comfyui", tmpl, params, job_id, priority, callback_url, metadata,
    priority_class=None, compiled_pipeline: Mapping[str, Any] | None = None,
):
    """Build a Redis-stream entry whose body is a fully-rendered ComfyUI workflow.

    Used when a generation template selects the ComfyUI protocol. Reviewed
    declarative templates may embed a ``workflow`` object; legacy templates
    may still use ``workflow_template``. Caller params are injected into the
    workflow's widget slots and the result is base64-encoded into ``body_b64``
    for the WorkerPool.

    Returns ``(entry, None)`` on success or ``(None, {"error": str, "status": int})``
    on failure.
    """
    import base64 as _b64
    params = {**(tmpl.get("defaults") or {}), **(params or {})}
    allowed_params = set(tmpl.get("allowed_params") or [])
    if allowed_params:
        unsupported = sorted(set(params) - allowed_params)
        if unsupported:
            return None, {
                "error": "unsupported_params",
                "message": f"Unsupported parameters: {', '.join(unsupported)}",
                "unsupported": unsupported,
                "allowed": sorted(allowed_params),
                "status": 400,
            }
    required_params = list(tmpl.get("required_params") or [])
    missing = [
        key for key in required_params
        if key not in params or params.get(key) is None or params.get(key) == ""
    ]
    if missing:
        return None, {
            "error": "missing_required_params",
            "message": f"Missing required parameters: {', '.join(missing)}",
            "missing": missing,
            "status": 400,
        }
    inline_workflow = tmpl.get("workflow")
    workflow_path = tmpl.get("workflow_template")
    if inline_workflow is not None:
        if not isinstance(inline_workflow, Mapping):
            return None, {
                "error": "generation template workflow must be an object",
                "status": 400,
            }
        workflow = copy.deepcopy(dict(inline_workflow))
        workflow_source = "inline-registry-workflow"
    elif workflow_path:
        try:
            if not os.path.isabs(workflow_path):
                workflow_path = str(PROJECT_ROOT / workflow_path)
            with open(workflow_path) as _wf:
                workflow = json.load(_wf)
        except (OSError, json.JSONDecodeError) as e:
            # A graph the release does not ship (or ships corrupt) cannot be
            # fixed by a retry: carry a stable reason so the coordinator ends
            # the job typed instead of re-ticking an untyped 500 forever.
            _asset_reason = (
                "workflow_asset_invalid"
                if isinstance(e, json.JSONDecodeError)
                else "workflow_asset_missing"
            )
            logger.error("%s: %s (%s)", _asset_reason, workflow_path, e)
            return None, {
                "error": f"Could not load workflow {workflow_path}: {e}",
                "reason": _asset_reason,
                "workflow": str(workflow_path),
                "status": 500,
            }
        workflow_source = str(workflow_path)
    else:
        return None, {
            "error": (
                "ComfyUI generation template must provide an inline 'workflow' "
                "or a legacy 'workflow_template' path"
            ),
            # A registry-declared generation type without a reviewed graph is
            # a configuration/admission gap, not a controller failure.  Keep
            # it out of the durable queue and make the compatibility clients
            # distinguish it from an engine crash.  This is especially
            # important for the historical video/ltx-video aliases: their
            # old in-process templates are not an acceptable second queue
            # authority once durable ownership is selected.
            "reason": "generation_workflow_unregistered",
            "status": 503,
        }

    # Phase 5.2.74: strip ComfyUI-rejected metadata keys before POST.
    # ComfyUI treats every top-level key as a node id and rejects
    # any entry that lacks `class_type` with HTTP 200 + error body
    # `{"error":{"type":"missing_node_type", ...}}` (see job:673937ce,
    # job:13d589b5). Authors use `_meta` for documentation; we keep it
    # out of the wire payload. The same rules live in the canonical
    # sanitizer (scripts/comfyui_workflow_sanitize.py); we delegate here
    # so the behaviour is identical at every entry point.
    from comfyui_workflow_sanitize import sanitize_comfyui_workflow as _sanitize
    _sanitized = _sanitize(
        workflow, source=f"_build_comfyui_workflow_entry:{workflow_source}"
    )
    # mutate workflow in-place so the rest of this function (which reads
    # workflow[node_id]) sees the cleaned keys without refactor.
    workflow.clear()
    workflow.update(_sanitized)

    # ── Universal input-adapter + raw prompt admission ─────────────
    # The HTTP ingress enqueues the raw request first; the worker verifies the
    # admitted raw prompt against the claimed workflow before /prompt.
    _adapter_warnings: list[str] = []
    _original_prompt = params.get("prompt")
    _enhancer_evidence: dict = {"provider": "none"}
    _worker_pipeline: dict = (
        copy.deepcopy(dict(compiled_pipeline))
        if isinstance(compiled_pipeline, Mapping) and compiled_pipeline.get("stages")
        else {}
    )
    _post_generate = dict(tmpl.get("post_generate") or {})

    if tmpl.get("prompt_format"):
        raw_prompt = params.get("prompt")
        if raw_prompt is None:
            return None, {
                "error": "params.prompt is required",
                "status": 400,
            }
        # Per-prompt_format adapters were removed in Phase 5.2.59. Reintroduce
        # them as a table-driven lookup when a future template needs one.
        params["prompt"] = raw_prompt

    # Inject caller params (if provided) into the workflow's widget slots.
    # If a key isn't in params, leave the workflow default untouched.
    # Per-template: each generation_template may override the inject map.
    _inject_keys = _resolve_inject_keys(tmpl)
    for src, node_id, field in _inject_keys:
        if src in params and node_id in workflow and "inputs" in workflow[node_id]:
            workflow[node_id]["inputs"][field] = params[src]

    # Persist exact prompt-target evidence separately from the large body.
    _prompt_evidence = None
    for src, node_id, field in _inject_keys:
        if src != "prompt":
            continue
        if node_id not in workflow or "inputs" not in workflow[node_id]:
            continue
        _effective_prompt = workflow[node_id]["inputs"].get(field, "")
        _prompt_target = f"{node_id}.inputs.{field}"
        if _post_generate.get("enabled") or _worker_pipeline.get("stages"):
            _worker_pipeline.update({
                "schema": "image-pipeline.v1",
                "original_prompt": str(_original_prompt),
                "prompt_target": _prompt_target,
            })
            if _post_generate.get("enabled"):
                _worker_pipeline["post_generate"] = _post_generate
        _prompt_evidence = _build_prompt_evidence(
            original_prompt=_original_prompt,
            effective_prompt=_effective_prompt,
            workflow=workflow,
            prompt_target=_prompt_target,
            enhancer=_enhancer_evidence,
            mask_provenance=(
                (metadata or {}).get("mask_provenance")
                if _template_declares_strict_locality(tmpl) else None
            ),
        )
        break

    _entry_metadata = dict(metadata or {})
    _entry_metadata["workflow_timeout_s"] = max(
        60, min(7200, int(tmpl.get("timeout", 900)))
    )
    if _worker_pipeline:
        _entry_metadata["worker_pipeline"] = _worker_pipeline
    if _prompt_evidence is not None:
        _prompt_evidence["injected_inputs"] = {
            f"{node_id}.inputs.{field}": workflow[node_id]["inputs"].get(field)
            for src, node_id, field in _inject_keys
            if src != "prompt"
            and src in params
            and node_id in workflow
            and "inputs" in workflow[node_id]
        }
        _entry_metadata["prompt_evidence"] = _prompt_evidence

    body = {"prompt": workflow}

    # Endpoint / http_path resolution (matches _build_generation_entry).
    # Prefer tmpl.get("endpoint"); else fall back to comfyui service config.
    _cfg = _load_services_config() or {}
    _svc_cfg = (_cfg.get("services", {}) or {}).get(service_name, {}) or {}
    endpoint = (
        tmpl.get("endpoint")
        or f"http://127.0.0.1:{_svc_cfg.get('port', 8188)}"
    )
    http_path = (
        tmpl.get("request_path")
        or _svc_cfg.get("http_path", "/prompt")
    )

    _priority_fields = priority_envelope(
        priority,
        priority_class=priority_class,
        convention=PriorityConvention.GENERATION_HIGHER_IS_URGENT,
    ).to_fields()

    return {
        "job_id": job_id,
        "routing_group": tmpl.get("routing_group", "image-gen"),
        "routing_group_type": "generation",
        "service_name": service_name,
        "bundle": tmpl.get("bundle"),
        "endpoint": endpoint,
        "http_method": "POST",
        "http_path": http_path,
        "request_kind": "comfyui_workflow",
        "body_b64": _b64.b64encode(
            json.dumps(body).encode("utf-8")
        ).decode("ascii"),
        "headers": json.dumps({"Content-Type": "application/json"}),
        "callback_url": callback_url or "",
        "metadata": json.dumps(_entry_metadata),
        **_priority_fields,
        "priority_source": "request",
        "submitted_at": time.time(),
    }, None


async def handle_submit_generation(
    request: web.Request, *, data_override: Mapping[str, Any] | None = None
):
    """POST /v1/submit/generation — Enqueue a generation job to Redis.

    Body shape (matches MCP submit_generation):
        {
          "type": "image" | "image-edit" | "image-edit-q5-benchmark"
                | "video" | "ltx-video" | "music" | "tts",
          "params": { ...type-specific prompt/params... },
          "priority": int,            # optional, default 50
          "callback_url": str,        # optional
          "metadata": { ... }         # optional, echoed in completion callback
        }

    Returns 202 with job_id, or 4xx with an error.  Bundle-load
    precheck: if the matched template declares a `bundle` and that
    bundle isn't loaded, ``_load_bundle`` is awaited first.  We refuse
    to enqueue when the bundle can't come up — better to fail fast
    with 500 than to leave a job stranded in the stream.
    """
    _owner_fence = _queue_owner_route_fence('durable', '/v1/submit/generation')
    if _owner_fence is not None:
        return _owner_fence
    if data_override is None:
        try:
            raw_body = await request.read()
        except web.HTTPRequestEntityTooLarge:
            return _submit_request_envelope(
                "body_too_large", "request body is too large", status=413
            )
        except Exception:
            return _submit_request_envelope(
                "invalid_json", "valid JSON required", status=400
            )
        try:
            data = _parse_json_object(raw_body)
        except _ContractError as exc:
            status = 413 if exc.code == "body_too_large" else 400
            return _submit_request_envelope(exc.code, exc.message, status=status)
    else:
        data = dict(data_override)
    try:
        _idempotency_key, _request_sha256 = _request_idempotency_contract(
            request, data, operation="submit.generation.v1"
        )
    except (TypeError, ValueError) as exc:
        return web.json_response({"error": str(exc)}, status=400)
    _idempotency_key_sha256 = (
        hashlib.sha256(_idempotency_key.encode("utf-8")).hexdigest()
        if _idempotency_key else None
    )

    requested_gen_type = data.get("type")
    cfg = _load_services_config() or {}
    gen_type, alias_error = _resolve_generation_alias(cfg, requested_gen_type)
    if alias_error:
        return web.json_response(
            alias_error, status=int(alias_error.get("status", 400))
        )

    # Retired ACE templates remain visible only so old registry snapshots fail
    # with a permanent replacement response instead of reaching any scheduler.
    declared_templates = cfg.get("generation_templates", {}) or {}
    declared_template = declared_templates.get(gen_type)
    is_acestep_template = (
        isinstance(declared_template, dict)
        and str(declared_template.get("backend") or "").startswith("acestep")
    )
    if gen_type in {"music-acestep", "music-acestep-candidate"} or is_acestep_template:
        legacy_data = dict(data.get("params") or {}) if isinstance(data, Mapping) else {}
        if isinstance(data, Mapping) and data.get("metadata") is not None:
            legacy_data["metadata"] = data.get("metadata")
        return await handle_acestep_generate(
            request, gen_type=gen_type, data_override=legacy_data
        )

    if not queue_engine:
        return web.json_response({"error": "Queue engine not available"}, status=503)

    declared_templates = (cfg.get("generation_templates", {}) or {})
    declared_service = (cfg.get("services", {}) or {}).get(gen_type, {})
    legacy_types = {
        "image", "image-edit", "image-edit-krea2",
        "image-edit-q5-benchmark",
        "video", "ltx-video", "music", "tts", "sulphur-video",
    }
    if not isinstance(gen_type, str) or (
        gen_type not in legacy_types
        and gen_type not in declared_templates
        and not _is_internal_workflow_service(declared_service)
    ):
        return web.json_response(
            {"error": f"Unknown gen type: {gen_type}"}, status=400
        )

    # Compile a template-owned declarative pipeline before any bundle or queue
    # side effect.  The request may repeat the owned ID, but cannot retarget a
    # template to a different graph.  Mixed ownership is left on the source
    # queue only when an explicitly attached coordinator runtime can admit it.
    if data.get("params") is not None and not isinstance(data.get("params"), Mapping):
        return web.json_response({"error": "params must be an object"}, status=400)
    if data.get("metadata") is not None and not isinstance(data.get("metadata"), Mapping):
        return web.json_response({"error": "metadata must be an object"}, status=400)
    _metadata = dict(data.get("metadata") or {})
    _params = dict(data.get("params") or {})
    if "service_pipeline_id" not in _params and "service_pipeline_id" in data:
        _params["service_pipeline_id"] = data.get("service_pipeline_id")
    _compiled_pipeline, _pipeline_err = await _resolve_ingress_pipeline(
        gen_type,
        _params,
        declared_templates.get(gen_type) or {},
    )
    if _pipeline_err:
        return web.json_response(
            _pipeline_err, status=int(_pipeline_err.get("status", 400))
        )
    if (
        ((_compiled_pipeline and _compiled_pipeline.get("pipeline_coordinator_required"))
         or _is_internal_workflow_service(declared_service))
        and not _coordinator_runtime_attached(request)
    ):
        return web.json_response(
            {
                "error": "pipeline_coordinator_unavailable",
                "reason": "pipeline_coordinator_unavailable",
                "pipeline_id": (_compiled_pipeline or {}).get("pipeline_id", gen_type),
            },
            status=503,
        )

    try:
        _request_priority = apply_priority_contract(
            {
                "priority": data.get("priority"),
                "priority_class": data.get("priority_class"),
            },
            convention=PriorityConvention.GENERATION_HIGHER_IS_URGENT,
        )
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)

    entry, err = await _build_generation_entry(
        gen_type=gen_type,
        params=_params,
        priority=_request_priority["priority"],
        priority_class=_request_priority["priority_class"],
        callback_url=data.get("callback_url"),
        metadata=_metadata,
        compiled_pipeline=_compiled_pipeline,
    )
    if err:
        return web.json_response(err, status=err.get("status", 400))
    if entry is None:
        return web.json_response(
            {"error": "internal: generation entry missing after err=None"},
            status=500,
        )
    job_id = entry["job_id"]

    if _idempotency_key:
        if not job_tracker:
            return web.json_response(
                {
                    "error": "idempotent admission requires the job tracker",
                    "reason": "idempotency_unavailable",
                },
                status=503,
            )
        _idem_outcome = job_tracker.claim_idempotency(
            _idempotency_key,
            _request_sha256,
            job_id,
            service_name=(entry.get("service_name") or entry.get("service") or ""),
            routing_group=entry.get("routing_group", "") or "",
        )
        _idem_response = _idempotency_outcome_response(
            _idem_outcome,
            response_fields={"type": gen_type},
        )
        if _idem_response is not None:
            return _idem_response

    # Phase 5.2.5 Fix A: register the job in job_tracker so /v1/job/<id>
    # can return its status. The legacy handle_submit_job calls
    # create_job + update_status at lines 8410-8465; mirror that pattern.
    # P0 from PHASE5.2.5_ADVERSARIAL.md: create_job catches redis errors
    # internally and returns None — must check return value, not just exception.
    if job_tracker:
        try:
            # create_job is synchronous (it does hset on redis). Call directly.
            _gjob = job_tracker.create_job(
                job_id=job_id,
                service_name=(
                    entry.get("service_name") or entry.get("service") or ""
                ),
                source="api",
                prompt=(
                    (data.get("params") or {}).get("brief")
                    or (data.get("params") or {}).get("prompt")
                    or ""
                ),
                max_tokens=0,
                routing_group=entry.get("routing_group", "") or "",
                priority=entry.get("priority"),
                priority_class=entry.get("priority_class"),
                broker_priority=entry.get("broker_priority"),
                priority_convention=entry.get("priority_convention"),
                priority_source=entry.get("priority_source"),
                idempotency_key_sha256=_idempotency_key_sha256,
                request_sha256=_request_sha256,
                service_revision=entry.get("service_revision"),
                service_revision_fingerprint=entry.get(
                    "service_revision_fingerprint"
                ),
                workflow_revision=entry.get("workflow_revision"),
                workflow_fingerprint=entry.get("workflow_fingerprint"),
            )
            if _gjob is None:
                return web.json_response(
                    {"error": "job_tracker.create_job returned None (redis error?)"},
                    status=503,
                )
            # Surface exact prompt evidence through /v1/job/<id> without
            # duplicating the full workflow body. This lets operators prove
            # which node-6 text and workflow hash were actually enqueued.
            try:
                _entry_metadata = json.loads(entry.get("metadata") or "{}")
            except (TypeError, json.JSONDecodeError):
                _entry_metadata = {}
            _prompt_evidence = _entry_metadata.get("prompt_evidence")
            if isinstance(_prompt_evidence, dict):
                job_tracker.update_status(
                    job_id,
                    "queued",
                    prompt_evidence=json.dumps(
                        _prompt_evidence,
                        sort_keys=True,
                        separators=(",", ":"),
                        ensure_ascii=False,
                    ),
                    effective_prompt_sha256=_prompt_evidence.get(
                        "effective_prompt_sha256"
                    ),
                    workflow_sha256=_prompt_evidence.get("workflow_sha256"),
                    prompt_target=_prompt_evidence.get("prompt_target"),
                )
        except Exception as _e:
            return web.json_response(
                {"error": f"job_tracker.create_job failed: {_e}"},
                status=500,
            )

    def _terminalize_submit_failure(error: str) -> None:
        """Best-effort terminal write for a job created before admission/enqueue."""
        if not job_tracker:
            return
        try:
            job_tracker.update_status(job_id, "failed", error=error)
        except Exception:
            logger.exception(
                "submit/generation: failed to terminalize %s after %s",
                job_id,
                error,
            )

    _comfyui_admission_held = (
        entry.get("routing_group") == "comfyui-gen"
        or entry.get("request_kind") == "comfyui_workflow"
    )
    if _comfyui_admission_held:
        _acquire_comfyui_admission(job_id)

    # ── Bundle-load precheck (PR5 / Step 5) ─────────────────────
    # Resolve the template again for the bundle field; cheap and keeps
    # the precheck logic close to the enqueue call site.
    tmpl = (cfg.get("generation_templates", {}) or {}).get(gen_type, {}) or {}
    bundle_name = tmpl.get("bundle")
    # Use the effective scheduler setting, including GPU_MANAGER_SCHEDULER_OWNS_LOAD.
    # Reading only services.json here can make ingress synchronously load a
    # bundle even though the live scheduler owns loading, delaying the 202
    # acknowledgement long enough for a client timeout to orphan the request.
    # Durable queue ownership makes WorkerPool the generation lifecycle
    # authority even when an older registry still has scheduler_owns_load=false.
    # Otherwise ingress can synchronously load/evict a bundle and the worker
    # then repeats the same transition after claiming the entry.
    scheduler_owns_load = (
        _queue_owner_mode() == "durable"
        or bool(_phase3_scheduling_config().get("scheduler_owns_load", False))
    )
    _bundle_already_ready = False
    if scheduler_owns_load:
        logger.info("submit/generation: enqueue accepted without handler pre-load")
    if bundle_name and not scheduler_owns_load:
        try:
            _bundle_already_ready = await _bundle_group_owned_and_healthy(bundle_name)
            if _bundle_already_ready:
                logger.info(
                    "submit/generation: reusing already-owned healthy bundle %s",
                    bundle_name,
                )
                ok = True
            else:
                ok = await _evict_then_load_bundle(
                    bundle_name, reason="submit_generation"
                )
        except Exception as e:
            logger.error(
                "submit/generation: bundle load raised for %s: %s",
                bundle_name, e,
            )
            error = f"Bundle load failed: {e}"
            _terminalize_submit_failure(error)
            _release_comfyui_admission(job_id)
            return web.json_response(
                {"error": error}, status=500
            )
        if not ok:
            error = f"Bundle '{bundle_name}' failed to load"
            _terminalize_submit_failure(error)
            _release_comfyui_admission(job_id)
            return web.json_response(
                {"error": error},
                status=500,
            )

    # Also evict any required_services before enqueueing so
    # the LLM doesn't keep holding VRAM while ComfyUI tries to load its
    # models.  We look up each service's systemd_unit from services.json
    # and systemctl stop it; failures are logged but don't block enqueue
    # (the worker will surface real OOM via the existing recovery path).
    _evict_list = tmpl.get("evict_first", []) or []
    if _evict_list and not scheduler_owns_load and not _bundle_already_ready:
        _svc_cfg_root = (cfg.get("services") or {})
        for _svc_name in _evict_list:
            _unit = (_svc_cfg_root.get(_svc_name) or {}).get(
                "systemd_unit", ""
            )
            if not _unit:
                logger.warning(
                    "submit/generation: evict_first service %r has no "
                    "systemd_unit in services.json — skipping",
                    _svc_name,
                )
                continue
            try:
                logger.info(
                    "submit/generation: evicting %s (unit=%s) for %s",
                    _svc_name, _unit, gen_type,
                )
                # Phase 5.1.5: tell the EventBus this stop is PLANNED
                # (we asked for it) so the Supervisor doesn't tear
                # down unrelated pools when the service briefly
                # looks unhealthy during the systemd stop cascade.
                if event_bus is not None:
                    event_bus.mark_planned_stop(_svc_name)
                _ev_proc = await asyncio.create_subprocess_exec(
                    "sudo", "systemctl", "stop", _unit,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                try:
                    _ev_out, _ev_err = await asyncio.wait_for(
                        _ev_proc.communicate(), timeout=30.0,
                    )
                except asyncio.TimeoutError:
                    _ev_proc.kill()
                    logger.warning(
                        "submit/generation: systemctl stop %s timed out",
                        _unit,
                    )
                    continue
                if _ev_proc.returncode != 0:
                    logger.warning(
                        "submit/generation: systemctl stop %s failed "
                        "(rc=%s): %s",
                        _unit, _ev_proc.returncode,
                        _ev_err.decode("utf-8", errors="replace")[:300],
                    )
            except Exception as _evict_err:
                logger.warning(
                    "submit/generation: failed to evict %s: %s",
                    _svc_name, _evict_err,
                )
            finally:
                # Phase 5.2.6: caller-side clear. The stamp's only purpose
                # was to absorb the systemd stop cascade; release the
                # supervisor's deferral once the stop returns (success,
                # failure, or timeout — the inner `continue` already
                # runs the finally on its way out).
                if event_bus is not None:
                    event_bus.clear_planned_stop(_svc_name)

    # ── Enqueue to the per-routing_group Redis stream ─────────────
    loop = asyncio.get_event_loop()
    routing_group = entry["routing_group"]
    service_name = entry.get("service_name") or routing_group
    logger.info(f"handle_submit_generation: enqueueing job_id={job_id} routing_group={routing_group} service_name={service_name}")
    try:
        entry_id = await loop.run_in_executor(
            None, queue_engine.enqueue, service_name, entry, routing_group,
        )
        if entry_id:
            logger.info(f"handle_submit_generation: enqueued job_id={job_id} entry_id={entry_id}")
    except Exception as e:
        logger.error("submit/generation: redis xadd failed: %s", e)
        error = f"redis enqueue failed: {e}"
        _terminalize_submit_failure(error)
        _release_comfyui_admission(job_id)
        return web.json_response(
            {"error": error}, status=503
        )
    if not entry_id:
        error = "Failed to enqueue (redis stream error)"
        _terminalize_submit_failure(error)
        _release_comfyui_admission(job_id)
        return web.json_response(
            {"error": error}, status=503
        )
    if job_tracker:
        # A worker may already have claimed the XADD by the time this
        # response-side bookkeeping runs. Never rewind its lifecycle.
        job_tracker.update_fields(job_id, entry_id=entry_id)

    # Queue depth for client-side backpressure hint (XLEN-style).
    try:
        position = await loop.run_in_executor(
            None, queue_engine.get_queue_depth, service_name, routing_group,
        )
    except Exception:
        position = None
    _queue_fields = await _queue_position_fields(service_name, routing_group, entry_id)

    return web.json_response(
        {
            "job_id": entry["job_id"],
            "entry_id": entry_id,
            "type": gen_type,
            "routing_group": routing_group,
            "status": "queued",
            "position": position,
            **_queue_fields,
            **({"idempotent_replay": False} if _idempotency_key else {}),
        },
        status=202,
    )


async def handle_get_job(request: web.Request):
    """GET /v1/job/{job_id} — Get job status."""
    if not job_tracker:
        return web.json_response({"error": "Queue engine not available"}, status=503)
    job_id = request.match_info["job_id"]
    loop = asyncio.get_event_loop()
    job = await loop.run_in_executor(None, job_tracker.get_job, job_id)
    if not job:
        return web.json_response({"error": f"Job {job_id} not found"}, status=404)

    # Phase 5.2.51: serialize via to_dict() so all fields (including
    # comfyui_prompt_id) appear in the response. Previously we returned
    # the raw object and aiohttp's default JSON encoder dropped unannotated
    # attributes, so clients never saw comfyui_prompt_id even when set.
    # get_job may return a Job object OR a plain dict (re-hydrated from
    # Redis), so handle both.
    if hasattr(job, "to_dict"):
        try:
            job_dict = job.to_dict()
        except Exception as _td_err:
            logger.debug("to_dict failed for %s: %s", job_id, _td_err)
            job_dict = None
    else:
        job_dict = None
    if job_dict is None:
        if isinstance(job, dict):
            job_dict = dict(job)  # shallow copy to avoid mutating cached state
        else:
            job_dict = {k: v for k, v in vars(job).items()}

    # Calculate queue position for queued jobs
    if job_dict.get("status") == "queued" and queue_engine:
        try:
            # service_name may live in metadata for some job types
            svc_name = (
                job_dict.get("service_name")
                or job_dict.get("metadata", {}).get("service_name", "")
            )
            # Phase 5.2.61: routing_group is the real stream key when present
            # (queue_engine.RedisQueue._stream returns queue:{routing_group},
            # not queue:{service_name}, when routing_group is set). Without
            # this, handle_get_job reports the depth of an unrelated Redis
            # stream — typically one polluted by stale LLM-proxy timeouts.
            routing_group = (
                job_dict.get("routing_group")
                or job_dict.get("metadata", {}).get("routing_group", "")
                or None
            )
            depth = await loop.run_in_executor(
                None, queue_engine.get_queue_depth, svc_name, routing_group
            )
            job_dict["queue_position"] = depth
            job_dict.update(
                await _queue_position_fields(
                    svc_name, routing_group, job_dict.get("entry_id"), job=job_dict
                )
            )
        except Exception:
            pass

    # Calculate elapsed time
    # Phase 5.2.51: created_at is a Unix epoch float, not an ISO string.
    # Use datetime.fromtimestamp() for the float case, and fromisoformat()
    # as fallback if a string was ever stored.
    created = job_dict.get("created_at") or job_dict.get("submitted_at", "")
    if created:
        try:
            from datetime import datetime as _dt, timezone as _tz
            if isinstance(created, (int, float)):
                sub_t = _dt.fromtimestamp(created, tz=_tz.utc)
            else:
                sub_t = _dt.fromisoformat(created)
            elapsed = (_dt.now(_tz.utc) - sub_t).total_seconds()
            job_dict["elapsed_seconds"] = round(elapsed, 1)
        except Exception:
            pass

    return web.json_response(job_dict)


async def handle_cancel_job(request: web.Request):
    """DELETE /v1/job/{job_id} — Cancel a queued job."""
    if not job_tracker or not queue_engine:
        return web.json_response({"error": "Queue engine not available"}, status=503)
    qe = queue_engine
    job_id = request.match_info["job_id"]
    loop = asyncio.get_event_loop()
    job = await loop.run_in_executor(None, job_tracker.get_job, job_id)
    if not job:
        return web.json_response({"error": f"Job {job_id} not found"}, status=404)

    status = job.get("status", "")
    if status == "completed" or status == "failed" or status == "cancelled":
        return web.json_response({"error": f"Job {job_id} already {status}"}, status=410)

    if status == "in_flight":
        if (
            job.get("workflow_execution_authority") == "coordinator"
            and job.get("coordinator_run_id")
        ):
            runtime = request.app.get(WORKFLOW_COORDINATOR_RUNTIME_KEY)
            cancel = getattr(runtime, "cancel", None)
            if not callable(cancel):
                return web.json_response(
                    {"error": "pipeline coordinator unavailable", "job_id": job_id},
                    status=503,
                )
            try:
                accepted = await loop.run_in_executor(
                    None, cancel, str(job["coordinator_run_id"])
                )
            except Exception as exc:
                logger.exception("coordinator cancel failed for %s", job_id)
                return web.json_response(
                    {"error": f"failed to request coordinator cancellation: {exc}",
                     "job_id": job_id, "status": "cancellation_failed"},
                    status=503,
                )
            if not accepted:
                return web.json_response(
                    {"error": f"coordinator run for job {job_id} is unavailable or terminal",
                     "job_id": job_id, "status": "cancellation_failed"},
                    status=409,
                )
            return web.json_response(
                {"job_id": job_id, "status": "cancellation_requested"}
            )
        # Cooperative cancellation: the worker owns the terminal transition.
        # The intent write is part of the API contract; never return a clean
        # acceptance when Redis rejected it.
        last_error = "job tracker unavailable"
        tracker = job_tracker
        marker = getattr(tracker, "mark_cancellation_intent_if_in_flight", None)
        if tracker is not None and callable(marker):
            for attempt in range(1, 4):
                try:
                    result = await loop.run_in_executor(None, marker, job_id)
                    if isinstance(result, dict):
                        if result.get("updated") is True:
                            return web.json_response(
                                {"job_id": job_id, "status": "cancellation_requested"}
                            )
                        current_status = str(result.get("status", "unknown"))
                        if current_status in ("completed", "failed", "cancelled"):
                            return web.json_response(
                                {"error": f"Job {job_id} already {current_status}"},
                                status=410,
                            )
                        raise RuntimeError(
                            result.get("error")
                            or f"cancellation CAS did not update ({current_status})"
                        )
                    if result is not True:
                        raise RuntimeError("cancellation CAS returned false")
                    return web.json_response(
                        {"job_id": job_id, "status": "cancellation_requested"}
                    )
                except Exception as exc:
                    last_error = str(exc)
                    logger.exception(
                        "cooperative cancel intent failed for %s (attempt %d/3)",
                        job_id,
                        attempt,
                    )
                    if attempt < 3:
                        await asyncio.sleep(0.05)
        return web.json_response(
            {
                "error": f"failed to persist cancellation intent: {last_error}",
                "job_id": job_id,
                "status": "cancellation_failed",
            },
            status=503,
        )

    if status == "queued":
        # Cancellation is terminal. The new Redis-side primitive
        # ``RedisQueue.cancel_queued_atomically`` combines the stream
        # entry removal AND the durable tracker terminal write into
        # ONE atomic operation. The handler MUST NOT release
        # slot / capacity / admission lease unless the primitive
        # returned ``removed_and_terminalized`` — otherwise we
        # either split-brain (entry gone but tracker still queued)
        # or double-release (two DELETEs each running the release
        # path).
        service_name = job.get("service_name", "")
        entry_id = job.get("entry_id", "")
        routing_group = (job.get("routing_group") or "").strip()
        primitive = getattr(qe, "cancel_queued_atomically", None)
        cancel_outcome = None
        if entry_id and service_name and callable(primitive):
            def _cancel_atomically():
                return primitive(
                    service_name=service_name,
                    routing_group=routing_group or None,
                    entry_id=entry_id,
                    consumer="cancel-api",
                    job_id=job_id,
                    error="user_cancel",
                    audit_source="cancel-api",
                    cancelled_by="cancel-api",
                )
            try:
                cancel_outcome = await loop.run_in_executor(
                    None, _cancel_atomically
                )
            except Exception as exc:
                logger.exception(
                    "queued cancel primitive failed for %s", job_id
                )
                return web.json_response(
                    {
                        "error": f"failed to cancel queued stream entry: {exc}",
                        "job_id": job_id,
                        "status": "cancellation_failed",
                    },
                    status=503,
                )
        elif entry_id and service_name:
            # Backwards-compat shim: production was deployed before the
            # primitive existed. Fall back to the old ack + update_status
            # sequence. This path is intentionally NOT release-safe — we
            # only emit the legacy 503 contract when no primitive is
            # available, so existing tests that probe the old contract
            # keep passing. New deployments must ship the primitive.
            def _cancel_stream_entry():
                return qe.ack(
                    service_name,
                    "cancel-api",
                    entry_id,
                    routing_group=routing_group or None,
                )
            try:
                stream_cancelled = await loop.run_in_executor(
                    None, _cancel_stream_entry
                )
            except Exception as exc:
                logger.exception(
                    "queued cancel ACK failed for %s (legacy shim)", job_id
                )
                return web.json_response(
                    {
                        "error": f"failed to cancel queued stream entry: {exc}",
                        "job_id": job_id,
                        "status": "cancellation_failed",
                    },
                    status=503,
                )
            if stream_cancelled is not True:
                return web.json_response(
                    {
                        "error": "failed to cancel queued stream entry",
                        "job_id": job_id,
                        "status": "cancellation_failed",
                    },
                    status=503,
                )
            await loop.run_in_executor(
                None, job_tracker.update_status, job_id, "cancelled"
            )
            cancel_outcome = {
                "outcome": "removed_and_terminalized",
                "stream": "",
                "entry_id": entry_id,
                "previous_status": "queued",
            }
        else:
            # No entry_id recorded on the tracker (shouldn't happen for
            # a queued job, but be defensive). Terminalize the tracker
            # only — there is nothing in the stream to remove.
            await loop.run_in_executor(
                None, job_tracker.update_status, job_id, "cancelled"
            )
            cancel_outcome = {
                "outcome": "removed_and_terminalized",
                "stream": "",
                "entry_id": entry_id or "",
                "previous_status": "queued",
            }

        # If a worker won the queued->in_flight race, do not delete its
        # PEL entry or release its resources. Re-enter the handler so it
        # reloads the durable in_flight state and persists the normal
        # cooperative cancellation intent instead.
        if (
            isinstance(cancel_outcome, dict)
            and cancel_outcome.get("outcome") == "not_queued"
            and cancel_outcome.get("current_status") == "in_flight"
        ):
            # A normal re-entry reloads the now-durable in_flight status
            # and persists cooperative cancellation intent. Bound it to
            # one hop so a broken tracker/Redis implementation cannot
            # recurse this HTTP request indefinitely.
            if request.get("_queued_cancel_reentry", False):
                return web.json_response(
                    {
                        "error": "queued cancellation raced with an in-flight worker",
                        "job_id": job_id,
                        "status": "cancellation_conflict",
                    },
                    status=409,
                )
            request["_queued_cancel_reentry"] = True
            return await handle_cancel_job(request)

        # Gate every side-effect release on the primitive's outcome.
        # This is the core safety contract of this slice:
        # - ``removed_and_terminalized`` -> the entry is gone AND the
        #   tracker is terminal; release slot/capacity/admission once.
        # - ``no_entry`` / ``already_terminal`` / ``error`` -> another
        #   caller already did the work (or the durable state is
        #   unchanged). Releasing here would split-brain or double-count.
        if not isinstance(cancel_outcome, dict) or cancel_outcome.get(
            "outcome"
        ) != "removed_and_terminalized":
            current = ""
            if isinstance(cancel_outcome, dict):
                current = str(
                    cancel_outcome.get("current_status")
                    or cancel_outcome.get("outcome")
                    or ""
                )
            logger.info(
                "queued cancel for %s noop on release path (%s)",
                job_id,
                current,
            )
            # 410 if the durable state is already terminal (the user
            # is hitting DELETE on a job that already finished); 503
            # otherwise (transient — caller should retry, the retry
            # will land on no_entry / already_terminal).
            if isinstance(cancel_outcome, dict) and cancel_outcome.get(
                "outcome"
            ) == "already_terminal":
                return web.json_response(
                    {
                        "error": f"Job {job_id} already "
                        f"{cancel_outcome.get('current_status') or 'terminal'}",
                        "job_id": job_id,
                        "status": cancel_outcome.get(
                            "current_status", "cancelled"
                        ),
                    },
                    status=410,
                )
            return web.json_response(
                {
                    "error": "queued cancel did not terminalize; "
                    "no release performed",
                    "job_id": job_id,
                    "status": "cancellation_failed",
                    "primitive_outcome": (
                        cancel_outcome.get("outcome")
                        if isinstance(cancel_outcome, dict)
                        else "error"
                    ),
                },
                status=503,
            )

        _release_comfyui_admission(job_id)
        # Release slot if held (idempotent on a free slot).
        # Track capacity for routing (idempotent on a missing key).
        if capacity_tracker:
            capacity_tracker.on_cancel(
                service_name, routing_group=routing_group or None
            )
        if slot_manager and service_name:
            slot_id = slot_manager.get_slot_for_job(service_name, job_id)
            if slot_id is not None:
                slot_manager.release_slot(service_name, slot_id)
        return web.json_response({"job_id": job_id, "status": "cancelled"})

    return web.json_response({"job_id": job_id, "status": status})


async def handle_queue_status(request: web.Request):
    """GET /v1/queue/{service_name} — Status for one service."""
    if not slot_manager or not queue_engine:
        return web.json_response({"error": "Queue engine not available"}, status=503)
    service_name = request.match_info["service_name"]
    service_cfg = _services_config.get("services", {}).get(service_name, {})
    routing_group = service_cfg.get("routing_group")
    loop = asyncio.get_event_loop()
    slots = await loop.run_in_executor(None, slot_manager.get_slots, service_name)
    total = len(slots)
    active = sum(1 for s in slots.values() if s.get("status") == "busy")
    depth = await loop.run_in_executor(None, queue_engine.get_queue_depth, service_name, routing_group)
    return web.json_response({
        "service_name": service_name,
        "routing_group": routing_group,
        "slots_total": total,
        "slots_active": active,
        "slots_available": total - active,
        "queue_depth": depth,
        # Required capacity contract fields
        "capacity_source": "slot_manager",
        "identity_echo": service_name,
        "observed_at": time.time(),
        "freshness": "current",
    })


def _apply_combined_gemma_visibility(
    services_status: dict,
    routing_groups: dict,
    broker_payload: dict | None,
    *,
    error: str | None = None,
) -> None:
    """Overlay Combined Gemma telemetry from its authoritative broker.

    The legacy Redis SlotManager is not on the standalone broker execution
    path.  Never present those counters as live Gemma capacity.  A missing,
    malformed, stale, or partial broker snapshot is represented as unknown and
    non-accepting rather than falling back to false free capacity.
    """
    group_name = _COMBINED_GEMMA_ROUTING_GROUP
    members = {
        name: status
        for name, status in services_status.items()
        if status.get("routing_group") == group_name
    }
    group = routing_groups.get(group_name)
    if not members or group is None:
        return

    source = "combined_gemma_broker"
    group_member_rows = {
        row.get("service"): row
        for row in group.get("members", [])
        if isinstance(row, dict) and isinstance(row.get("service"), str)
    }

    def fail_closed(reason: str) -> None:
        for name, status in members.items():
            unknown_fields = {
                "slots_total": None,
                "slots_active": None,
                "slots_available": None,
                "queue_depth": None,
                "capacity_source": source,
                "queue_source": source,
                "capacity_fresh": False,
                "capacity_unknown": True,
                "visibility_error": reason,
            }
            status.update(unknown_fields)
            row = group_member_rows.get(name)
            if row is not None:
                row.update({
                    **unknown_fields,
                    "slots_free": None,
                    "total_load": None,
                })
        group.update({
            "slots_total": None,
            "slots_active": None,
            "slots_free": None,
            "queue_depth": None,
            "can_accept": False,
            "capacity_source": source,
            "queue_source": source,
            "capacity_fresh": False,
            "capacity_unknown": True,
            "visibility_error": reason,
        })

    if not isinstance(broker_payload, dict):
        fail_closed(error or "broker_unavailable")
        return
    if broker_payload.get("schema") != "combined-gemma.broker-metric.v1":
        fail_closed("invalid_broker_schema")
        return
    queue = broker_payload.get("queue")
    raw_members = broker_payload.get("members")
    if (
        not isinstance(queue, dict)
        or type(queue.get("depth")) is not int
        or queue["depth"] < 0
        or queue.get("fresh") is not True
        or not isinstance(raw_members, list)
    ):
        fail_closed("invalid_or_stale_broker_snapshot")
        return

    observed = {}
    for item in raw_members:
        if not isinstance(item, dict) or not isinstance(item.get("name"), str):
            fail_closed("invalid_broker_member_entry")
            return
        name = item["name"]
        if name in observed:
            fail_closed(f"duplicate_broker_member:{name}")
            return
        observed[name] = item
    if not set(members).issubset(observed):
        fail_closed("broker_member_set_mismatch")
        return

    normalized_members = {}
    total_slots = 0
    total_busy = 0
    total_free = 0
    latest_observed_at = None
    for name, item in observed.items():
        inactive_by_systemd = (
            item.get("accepting") is False
            and isinstance(item.get("reason_codes"), list)
            and "MEMBER_SYSTEMD_INACTIVE" in item["reason_codes"]
        )
        if inactive_by_systemd:
            # An explicitly inactive systemd member is intentionally outside
            # the broker's capacity pool. Preserve its unknown per-member
            # telemetry, but do not let it poison live group capacity.
            normalized_members[name] = {
                "slots_total": None,
                "slots_active": None,
                "slots_available": None,
                "slots_free": None,
                "queue_depth": queue["depth"],
                "total_load": None,
                "capacity_source": source,
                "queue_source": source,
                "capacity_fresh": False,
                "capacity_unknown": True,
                "observed_at": item.get("observed_at"),
            }
            continue

        total = item.get("backend_slots_total")
        busy = item.get("backend_slots_busy")
        free = item.get("compatible_free_slots")
        accepting = item.get("accepting")
        observed_at = item.get("observed_at")
        fresh = item.get("fresh") is True and item.get("stale") is False and item.get("unknown") is False
        if (
            type(total) is not int
            or type(busy) is not int
            or type(free) is not int
            or type(accepting) is not bool
            or not isinstance(observed_at, (int, float))
            or isinstance(observed_at, bool)
            or total < 0
            or busy < 0
            or free < 0
            or busy > total
            or free > total
            or busy + free > total
            or (not accepting and free != 0)
            or not fresh
        ):
            fail_closed(f"invalid_or_stale_broker_member:{name}")
            return
        normalized_members[name] = {
            "slots_total": total,
            "slots_active": busy,
            "slots_available": free,
            "slots_free": free,
            "queue_depth": queue["depth"],
            "total_load": busy + queue["depth"],
            "capacity_source": source,
            "queue_source": source,
            "capacity_fresh": True,
            "capacity_unknown": False,
            "observed_at": observed_at,
        }
        total_slots += total
        total_busy += busy
        total_free += free
        latest_observed_at = max(latest_observed_at or observed_at, observed_at)

    for name, status in members.items():
        item = normalized_members[name]
        status.update({
            key: item[key]
            for key in (
                "slots_total", "slots_active", "slots_available",
                "queue_depth", "capacity_source", "queue_source",
                "capacity_fresh", "capacity_unknown", "observed_at",
            )
        })

    # The broker may own members that are intentionally absent from GPU
    # Manager's local service catalog (for example cloud spillover members).
    # Surface those members in the authoritative group aggregate without
    # pretending they are locally managed systemd services.
    for name, item in normalized_members.items():
        row = group_member_rows.get(name)
        if row is None:
            row = {"service": name, "routing_group": group_name}
            group.setdefault("members", []).append(row)
            group_member_rows[name] = row
        row.update(item)

    group.update({
        "slots_total": total_slots,
        "slots_active": total_busy,
        "slots_free": total_free,
        "queue_depth": queue["depth"],
        "can_accept": total_free > 0,
        "capacity_source": source,
        "queue_source": source,
        "capacity_fresh": True,
        "capacity_unknown": False,
        "observed_at": latest_observed_at,
    })


async def _fetch_combined_gemma_visibility() -> tuple[dict | None, str | None]:
    if not _combined_gemma_broker_enabled():
        # The broker feature is opt-in. Disabled controllers must neither
        # touch the embedded proxy nor open any HTTP session; doing so would
        # silently leak probes into a production broker just because the
        # loopback default happens to be reachable.
        return None, "broker_disabled"
    if _combined_gemma_broker_embedded():
        try:
            payload = _combined_gemma_api_proxy.broker_metrics()
            if inspect.isawaitable(payload):
                payload = await payload
            if not isinstance(payload, dict):
                return None, "broker_invalid_json"
            return payload, None
        except Exception as exc:
            return None, f"broker_unavailable:{type(exc).__name__}"
    if session is None or session.closed:
        return None, "http_session_unavailable"
    url = os.environ.get(
        "COMBINED_GEMMA_BROKER_METRICS_URL",
        "http://127.0.0.1:18095/v1/metrics/broker?durable=0",
    )
    # An empty override is an explicit deployment boundary: staging or an
    # isolated controller must not probe a host-networked production broker
    # merely because the loopback default happens to be reachable.
    if not url.strip():
        return None, "broker_probe_disabled"
    from urllib.parse import urlsplit
    parsed = urlsplit(url)
    if parsed.scheme not in {"http", "https"} or parsed.hostname not in {"127.0.0.1", "localhost", "::1"}:
        return None, "broker_url_not_loopback"
    try:
        # Readiness uses the broker's lightweight authoritative snapshot. Full
        # durable counts are intentionally excluded because historical attempt
        # scans are observability work, not a readiness prerequisite.
        timeout = ClientTimeout(total=3.0, connect=0.5, sock_read=2.5)
        async with session.get(url, timeout=timeout) as response:
            if response.status != 200:
                return None, f"broker_http_{response.status}"
            payload = await response.json(content_type=None)
            if not isinstance(payload, dict):
                return None, "broker_invalid_json"
            return payload, None
    except asyncio.TimeoutError:
        return None, "probe_timeout"
    except Exception as exc:
        return None, f"broker_unavailable:{type(exc).__name__}"


def _summarize_combined_router_readiness(broker_payload: dict | None, error: str | None) -> dict:
    """Reduce authoritative broker telemetry into a fail-closed readiness view."""
    result = {
        "up": isinstance(broker_payload, dict), "schema_valid": False,
        "available": False, "live_member_count": 0,
        "accepting_member_count": 0, "members": {},
        "reason": error or "broker_unavailable",
    }
    if not isinstance(broker_payload, dict):
        return result
    if broker_payload.get("schema") != "combined-gemma.broker-metric.v1":
        result["reason"] = "invalid_broker_schema"
        return result
    queue = broker_payload.get("queue")
    raw_members = broker_payload.get("members")
    if (not isinstance(queue, dict) or queue.get("fresh") is not True
            or type(queue.get("depth")) is not int or queue["depth"] < 0
            or not isinstance(raw_members, list)):
        result["reason"] = "invalid_or_stale_broker_snapshot"
        return result
    result["schema_valid"] = True
    dispatch = broker_payload.get("dispatch_loop")
    fail_counters = dispatch.get("fail_counters") if isinstance(dispatch, dict) else None
    fencing_token = dispatch.get("fencing_token") if isinstance(dispatch, dict) else None
    reservation_stale = fail_counters.get("reservation_stale") if isinstance(fail_counters, dict) else None
    dispatch_ready = (
        isinstance(dispatch, dict)
        and type(fencing_token) is int and fencing_token > 0
        and type(reservation_stale) is int and reservation_stale >= 0
        and not (queue["depth"] > 0 and reservation_stale > 0)
    )
    result["dispatcher"] = {
        "ready": dispatch_ready,
        "fencing_token": fencing_token if type(fencing_token) is int else None,
        "reservation_stale": reservation_stale if type(reservation_stale) is int else None,
    }
    if not dispatch_ready:
        result["reason"] = "dispatcher_not_ready"
        return result
    seen = set()
    for row in raw_members:
        if not isinstance(row, dict) or not isinstance(row.get("name"), str):
            result.update(schema_valid=False, reason="invalid_broker_member_entry", members={})
            return result
        name = row["name"]
        if name in seen:
            result.update(schema_valid=False, reason=f"duplicate_broker_member:{name}", members={})
            return result
        seen.add(name)
        total = row.get("backend_slots_total")
        live = (row.get("fresh") is True and row.get("stale") is False
                and row.get("unknown") is False and type(total) is int and total > 0)
        accepting = live and row.get("accepting") is True
        result["members"][name] = {
            "live": live, "accepting": accepting,
            "fresh": row.get("fresh") is True, "stale": row.get("stale") is True,
            "unknown": row.get("unknown") is True,
            "backend_slots_total": total if type(total) is int else None,
            "backend_slots_busy": row.get("backend_slots_busy"),
            "compatible_free_slots": row.get("compatible_free_slots"),
            "observed_at": row.get("observed_at"),
        }
        result["live_member_count"] += int(live)
        result["accepting_member_count"] += int(accepting)
    # available requires the broker snapshot to be schema-valid AND at least
    # one constituent to be live (fresh, non-stale, non-unknown, with positive
    # backend capacity) AND actively accepting work. A live-but-draining
    # member must not flip this gate green.
    result["available"] = result["accepting_member_count"] > 0
    result["reason"] = "ready" if result["available"] else "no_live_constituents"
    return result


def _reduce_llm_readiness(*, combined_router: dict, pinned_route: dict, idle_route: dict) -> dict:
    sources = []
    if combined_router.get("available") is True: sources.append("combined_router")
    if pinned_route.get("healthy") is True: sources.append("pinned_route")
    if idle_route.get("healthy") is True: sources.append("idle_route")
    return {
        "available": bool(sources), "availability_sources": sources,
        "combined_router": combined_router, "pinned_route": pinned_route,
        "idle_route": idle_route,
    }


async def _probe_configured_llm_service(config: dict, service_name: str | None) -> dict:
    result = {"configured": service_name or None, "healthy": False, "reason": "not_configured"}
    if not service_name: return result
    service = (config.get("services", {}) or {}).get(service_name)
    if not isinstance(service, dict) or service.get("enabled") is not True:
        result["reason"] = "missing_or_disabled"; return result
    port = service.get("port")
    if type(port) is not int or port <= 0:
        result["reason"] = "invalid_port"; return result
    result.update(port=port, health_path=service.get("health_path") or "/health")
    if session is None or session.closed:
        result["reason"] = "http_session_unavailable"; return result
    try:
        url = f"http://127.0.0.1:{port}{result['health_path']}"
        async with session.get(url, timeout=ClientTimeout(total=1.0, connect=0.25)) as response:
            result["http_status"] = response.status
            result["healthy"] = response.status == 200
            result["reason"] = "ready" if result["healthy"] else f"http_{response.status}"
    except asyncio.TimeoutError:
        result["reason"] = "probe_timeout"
    except Exception as exc:
        result["reason"] = f"probe_failed:{type(exc).__name__}"
    return result


async def _llm_readiness_snapshot(config: dict) -> dict:
    broker_payload, broker_error = await _fetch_combined_gemma_visibility()
    combined = _summarize_combined_router_readiness(broker_payload, broker_error)
    # disabled placeholders (Qwen-Dual) are not members anyone can route to
    services = config.get("services", {}) or {}
    for name in [n for n in combined["members"] if (services.get(n) or {}).get("enabled") is False]:
        combined["members"].pop(name)
    if _combined_gemma_broker_config_stale:
        combined["config_stale"] = _combined_gemma_broker_config_stale
    scheduling = config.get("scheduling", {}) or {}
    runtime_pin_raw = getattr(scheduler, "_pinned_service", None) if scheduler is not None else None
    runtime_pin = runtime_pin_raw if isinstance(runtime_pin_raw, str) and runtime_pin_raw else None
    pinned = await _probe_configured_llm_service(
        config, runtime_pin or scheduling.get("pinned_service")
    )
    idle_target = _configured_llm_health_target(config)
    idle = {
        "configured": scheduling.get("idle_service"), "healthy": bool(llm._llm_healthy),
        "reason": (
            "ready"
            if llm._llm_healthy
            else ("not_configured" if idle_target is None else "registry_probe_unready")
        ),
    }
    return _reduce_llm_readiness(combined_router=combined, pinned_route=pinned, idle_route=idle)


async def handle_all_queues(request: web.Request):
    """GET /v1/queue — Aggregated status for all services."""
    if not routing_engine or not capacity_reporter:
        return web.json_response({"error": "Queue engine not available"}, status=503)

    loop = asyncio.get_event_loop()
    services_status = {}
    services = _services_config.get("services", {})
    seen_groups = set()
    routing_groups = {}

    for svc_name, svc_cfg in services.items():
        if svc_cfg.get("type") != "llm_backend" or not svc_cfg.get("enabled"):
            continue
        rg = svc_cfg.get("routing_group", "")
        if rg:
            seen_groups.add(rg)

        svc_status = {}
        if slot_manager:
            slots = await loop.run_in_executor(None, slot_manager.get_slots, svc_name)
            total = len(slots)
            active = sum(1 for s in slots.values() if s.get("status") == "busy")
            svc_status["slots_total"] = total
            svc_status["slots_active"] = active
            svc_status["slots_available"] = total - active
        if queue_engine:
            routing_group = svc_cfg.get("routing_group")
            svc_status["queue_depth"] = await loop.run_in_executor(
                None, queue_engine.get_queue_depth, svc_name, routing_group)
            if routing_group:
                svc_status["routing_group"] = routing_group
        services_status[svc_name] = svc_status

    for rg in seen_groups:
        routing_groups[rg] = await loop.run_in_executor(
            None, routing_engine.get_group_status, rg)

    if _COMBINED_GEMMA_ROUTING_GROUP in seen_groups:
        broker_payload, visibility_error = await _fetch_combined_gemma_visibility()
        _apply_combined_gemma_visibility(
            services_status,
            routing_groups,
            broker_payload,
            error=visibility_error,
        )

    return web.json_response({
        "services": services_status,
        "routing_groups": routing_groups,
        "recovery": _queue_recovery_summary(),
    })


async def handle_fleet_status(request: web.Request):
    """GET /v1/fleet — Fleet gossip status showing all known peers."""
    if not async_gossiper:
        return web.json_response({"error": "Fleet gossip not available"}, status=503)

    peers = await async_gossiper.read_all_peers()
    local_mid = socket.gethostname()

    # Get local capacity too
    local_cap = {}
    if async_capacity:
        try:
            local_cap = await async_capacity.get_local_capacity()
        except Exception:
            pass

    return web.json_response({
        "machine_id": local_mid,
        "peers": {mid: cap for mid, cap in peers.items()},
        "local": local_cap,
        "local_services": local_cap.get("services", {}) if isinstance(local_cap, dict) else {},
    })


async def handle_workers_status(request: web.Request):
    """GET /v1/workers — Detailed worker pool status."""
    if not worker_supervisor:
        return web.json_response({"error": "Worker supervisor not available"}, status=503)

    pools = []
    for svc_name, pool in worker_supervisor._pools.items():
        pools.append({
            "service": svc_name,
            "desired_slots": pool.desired_slots,
            "slots_free": pool.slots_free,
            "slots_active": pool.active_workers,
            "running": pool._running,
            "workers_alive": sum(1 for w in pool._workers if not w.done()),
        })

    return web.json_response({
        "pools": pools,
        "total_slots": sum(p["desired_slots"] for p in pools),
        "total_free": sum(p["slots_free"] for p in pools),
        "total_active": sum(p["slots_active"] for p in pools),
    })


async def handle_workers_active(request: web.Request):
    """GET /v1/workers/active — Workers currently processing jobs."""
    if not worker_supervisor:
        return web.json_response({"error": "supervisor not ready"}, status=503)
    out = []
    for svc, pool in worker_supervisor._pools.items():
        out.append({
            "service": svc,
            "active": pool.active_workers,
            "free": pool.slots_free,
            "desired": pool.desired_slots,
            "alive": sum(1 for w in pool._workers if not w.done()),
        })
    return web.json_response({
        "pools": out,
        "total_active": sum(p["active"] for p in out),
        "timestamp": time.time(),
    })


async def handle_workers_free(request: web.Request):
    """GET /v1/workers/free — Services with free capacity, ranked by slack."""
    if not worker_supervisor:
        return web.json_response({"error": "supervisor not ready"}, status=503)
    rows = []
    for svc, pool in worker_supervisor._pools.items():
        if pool.slots_free > 0:
            rows.append({
                "service": svc,
                "slots_free": pool.slots_free,
                "desired": pool.desired_slots,
            })
    rows.sort(key=lambda r: r["slots_free"], reverse=True)
    return web.json_response({
        "free_pools": rows,
        "total_free": sum(r["slots_free"] for r in rows),
        "timestamp": time.time(),
    })


async def handle_slots(request: web.Request):
    """GET /v1/slots?service=NAME — Per-slot busy/free view."""
    if not slot_manager:
        return web.json_response({"error": "slot_manager not ready"}, status=503)
    service = request.query.get("service")
    services = [service] if service else [
        s for s, c in _services_config.get("services", {}).items()
        if c.get("type") == "llm_backend" and c.get("enabled")
    ]
    out = {}
    for svc in services:
        try:
            slots = slot_manager.get_slots(svc)
            out[svc] = {
                "total": len(slots) if slots else 0,
                "busy": sum(1 for s in (slots or {}).values() if s.get("status") == "busy"),
                "free": sum(1 for s in (slots or {}).values() if s.get("status") != "busy"),
            }
        except Exception as e:
            out[svc] = {"error": str(e)}
    out.update(deprecated=True, see="/v1/catalog")
    return web.json_response(out, headers=_CATALOG_DEPRECATION_HEADERS)


async def handle_stats(request: web.Request):
    """GET /v1/stats — High-level system counters."""
    out = {"queue_depths": {}, "totals": {}, "timestamp": time.time()}
    if queue_engine:
        for svc, cfg in _services_config.get("services", {}).items():
            if cfg.get("type") == "llm_backend" and cfg.get("enabled"):
                try:
                    out["queue_depths"][svc] = queue_engine.get_queue_depth(
                        svc,
                        cfg.get("routing_group"),
                    )
                except Exception:
                    out["queue_depths"][svc] = -1
    if worker_supervisor:
        tp = sum(p.desired_slots for p in worker_supervisor._pools.values())
        tf = sum(p.slots_free for p in worker_supervisor._pools.values())
        ta = sum(p.active_workers for p in worker_supervisor._pools.values())
        out["totals"] = {"slots_desired": tp, "slots_free": tf, "slots_active": ta}
    return web.json_response(out)


async def handle_routing(request: web.Request):
    """GET /v1/routing — Per-routing-group status."""
    if not routing_engine:
        return web.json_response({"error": "routing_engine not ready"}, status=503)
    groups = set()
    for svc, cfg in _services_config.get("services", {}).items():
        rg = cfg.get("routing_group")
        # Phase 5.2.79 (R1): include generation_backend routing groups too;
        # the prior llm_backend-only filter was dropping comfyui-gen / video-gen
        # from /v1/routing even though those backends were alive and accepting jobs.
        if rg and cfg.get("type") in ("llm_backend", "generation_backend") and cfg.get("enabled"):
            groups.add(rg)
    out = {}
    for rg in groups:
        try:
            out[rg] = routing_engine.get_group_status(rg)
        except Exception as e:
            out[rg] = {"error": str(e)}
    return web.json_response(
        {"routing_groups": out, "timestamp": time.time(), "deprecated": True, "see": "/v1/catalog"},
        headers=_CATALOG_DEPRECATION_HEADERS,
    )


def _coerce_group_priority(priority_value, default=50, allow_cpu_fallback=False) -> int:
    try:
        priority = int(priority_value)
    except (TypeError, ValueError):
        return default
    if priority <= 0:
        return default
    if priority == 30 and not allow_cpu_fallback:
        return default
    return priority


def _service_group_priority(group_name: str, groups_data: dict, generation_templates: dict) -> int:
    """Helper to compute canonical routing-group ownership priority.
    Convention: higher_number_higher_priority.
    """
    routing_groups_config = {}
    try:
        routing_groups_config = _services_config.get("routing_groups", {}) or {}
    except Exception:
        routing_groups_config = {}

    explicit_rg = routing_groups_config.get(group_name, {}) or {}
    if "priority" in explicit_rg:
        return _coerce_group_priority(explicit_rg.get("priority"), allow_cpu_fallback=True)

    priority = 50
    if group_name in groups_data:
        p = groups_data[group_name].get("priority", 50)
        p = _coerce_group_priority(p)
        if p != 50:
            priority = p

    # Try generation templates if it matches
    for t_name, t_cfg in generation_templates.items():
        t_rg = t_cfg.get("routing_group")
        if t_rg == group_name or t_name == group_name:
            t_pri = _coerce_group_priority(t_cfg.get("priority"))
            if t_pri != 50:
                priority = max(priority, t_pri)

    return priority

def _infer_active_service_group(gpu_state_dict: dict, groups_data: dict) -> dict:
    """Helper to infer active group from GPU state."""
    loaded_bundles = gpu_state_dict.get("loaded_bundles", [])
    if not loaded_bundles:
        return {"group": None, "confidence": "high", "reason": "No bundles loaded"}
    bundle = loaded_bundles[0]

    # Try to map bundle to group based on members
    possible_groups = []
    if bundle in groups_data:
        possible_groups.append(bundle)

    for rg, data in groups_data.items():
        if rg == bundle and rg not in possible_groups:
            possible_groups.append(rg)
        for member in data.get("members", []):
            if member.get("service_name") == bundle or member.get("routing_group") == bundle:
                if rg not in possible_groups:
                    possible_groups.append(rg)

    if possible_groups:
        return {"group": possible_groups[0], "confidence": "medium", "reason": f"Matched bundle {bundle}"}
    return {"group": None, "confidence": "low", "reason": f"Could not map bundle {bundle} to a group"}

def _compute_service_group_dry_run(groups: dict, all_gpu_states: dict, generation_templates: dict) -> dict:
    """Computes scheduler dry run recommendations based on Phase 2 requirements."""
    active_groups = {}
    for gid, gs in all_gpu_states.items():
        gs_dict = gs.to_dict() if hasattr(gs, "to_dict") else {}
        active_groups[gid] = _infer_active_service_group(gs_dict, groups)

    pending_groups = []
    scheduling = _phase3_scheduling_config()
    try:
        aging_interval = max(1.0, float(scheduling.get('priority_aging_interval_s', 60)))
    except (TypeError, ValueError):
        aging_interval = 60.0
    try:
        aging_cap = max(0, int(scheduling.get('priority_aging_cap', 100)))
    except (TypeError, ValueError):
        aging_cap = 100
    for rg, data in groups.items():
        queue_lag = data.get("queue_lag")
        if queue_lag is not None and queue_lag > 0:
            base_priority = _service_group_priority(rg, groups, generation_templates)
            try:
                oldest_wait = max(0.0, float(data.get("oldest_wait_seconds") or 0.0))
            except (TypeError, ValueError):
                oldest_wait = 0.0
            age_boost = min(aging_cap, int(oldest_wait // aging_interval))
            pending_groups.append({
                "group": rg,
                "priority": base_priority,
                "priority_age_boost": age_boost,
                "effective_priority": base_priority + age_boost,
                "oldest_wait_seconds": oldest_wait,
                "queue_lag": queue_lag,
            })

    # Preserve the existing higher-number-is-urgent policy while allowing a
    # long-waiting lower tier to compete.  Queue lag and age break ties; no
    # request is preempted by this ordering alone.
    pending_groups.sort(
        key=lambda x: (
            x["effective_priority"],
            x["oldest_wait_seconds"],
            x["queue_lag"],
        ),
        reverse=True,
    )

    active_group_names = [info["group"] for info in active_groups.values() if info["group"]]
    next_candidate = None
    blocked_by = []

    if not pending_groups:
        blocked_by.append("no pending groups")
    else:
        for candidate in pending_groups:
            if candidate["group"] not in active_group_names:
                next_candidate = candidate
                break
        if not next_candidate:
            blocked_by.append("all pending groups are already active")

    drain_decision = {
        "would_hold_active_group_until_drain": True if next_candidate else False,
        "drain_cutoff_required": True,
        "drain_cutoff_supported": False,
        "would_swap_now": False,
        "blocked_by": blocked_by
    }

    required_gpus_inference = {}
    for rg, data in groups.items():
        if data.get("type") == "generation":
            required_gpus_inference[rg] = {
                "inferred_gap": "diagnostic only",
                "current_bundle_declares": "unknown unless config says otherwise"
            }

    return {
        "priority_convention": "higher_number_higher_priority",
        "active_groups": active_groups,
        "pending_groups": pending_groups,
        "next_group_candidate_dry_run": next_candidate,
        "drain_decision": drain_decision,
        "required_gpus": required_gpus_inference,
        "recommended_transition_log": []
    }

async def handle_service_groups_state(request: web.Request):
    """GET /v1/service-groups — Phase 1: Observability-only service-group state/logging endpoint."""
    loop = asyncio.get_event_loop()

    # Mirror safe top-level gpu_states
    all_gpu_states = _get_all_gpu_states()
    generation_templates = _services_config.get("generation_templates", {})
    routing_groups = _services_config.get("routing_groups", {})

    out = {
        "observability_only": True,
        "timestamp": time.time(),
        "groups": {},
        "generation_templates": generation_templates,
        "routing_groups": routing_groups,
        "priority_convention": "higher_number_higher_priority",
        "gpu_states": {
            gid: (gs.to_dict() if hasattr(gs, "to_dict") else {})
            for gid, gs in all_gpu_states.items()
        },
    }

    # Infer generation templates by group
    templates_by_group = {}
    for t_name, t_cfg in generation_templates.items():
        t_rg = t_cfg.get("routing_group")
        if not t_rg:
            bundle = t_cfg.get("bundle", "")
            if bundle == "comfyui":
                t_rg = "comfyui-gen"
            elif bundle == "music":
                t_rg = "music-gen"
            else:
                t_rg = t_name

        if t_rg not in templates_by_group:
            templates_by_group[t_rg] = []
        templates_by_group[t_rg].append({
            "name": t_name,
            "backend": t_cfg.get("backend"),
            "bundle": t_cfg.get("bundle"),
            "priority": t_cfg.get("priority")
        })
    out["generation_templates_by_group"] = templates_by_group

    # Aggregate members by routing group
    groups = {}
    for svc_name, cfg in _services_config.get("services", {}).items():
        if not _is_queue_consumer_service(cfg):
            continue
        rg = cfg.get("routing_group", "")
        # Try to infer routing group for generation templates if empty
        if not rg:
            # check if it matches a bundle
            bundle = cfg.get("bundle", "")
            if bundle == "comfyui":
                rg = "comfyui-gen"
            elif bundle == "music":
                rg = "music-gen"
            else:
                rg = svc_name

        if rg not in groups:
            groups[rg] = {
                "type": "unknown",
                "priority": cfg.get("priority", 50),
                "queue_stream": f"queue:{rg}",
                "members": [],
                "queue_lag": None,
                "pool_summary": None,
            }

        # Determine group type
        if cfg.get("type") == "llm_backend":
            groups[rg]["type"] = "llm"
        elif cfg.get("type") == "generation_backend" or cfg.get("bundle"):
            groups[rg]["type"] = "generation"

        groups[rg]["members"].append({
            "service_name": svc_name,
            "type": cfg.get("type"),
            "gpu_id": cfg.get("gpu_id"),
            "port": cfg.get("port"),
            "proxy_port": cfg.get("proxy_port"),
            "enabled": cfg.get("enabled", False),
            "priority": cfg.get("priority", 50),
            "parallel": cfg.get("parallel"),
            "queue": cfg.get("queue"),
            "routing_group": rg,
            "routing_group_type": cfg.get("routing_group_type"),
        })

    # Add queue depth and worker pool summary
    for rg, group_info in groups.items():
        # Queue depth safely
        if queue_engine:
            try:
                # queue_engine.get_queue_depth signature is (service_name, routing_group)
                # passing (rg, rg) is acceptable because for grouped streams the name and rg match
                # use run_in_executor for sync queue_engine.get_queue_depth
                observation = await loop.run_in_executor(
                    None, _queue_depth_observation, queue_engine, rg, rg
                )
                group_info["queue_lag"] = (
                    observation["depth"] if observation["known"] else 0
                )
                group_info["queue_lag_observed"] = observation["depth"]
                group_info["queue_lag_known"] = observation["known"]
                group_info["queue_lag_reason"] = observation["reason"]
                age_reader = getattr(queue_engine, "get_oldest_wait_seconds", None)
                if callable(age_reader):
                    group_info["oldest_wait_seconds"] = await loop.run_in_executor(
                        None, age_reader, rg, rg
                    )
            except Exception as e:
                group_info["queue_lag_error"] = str(e)
        else:
            group_info["queue_lag"] = None
            group_info["queue_lag_reason"] = "queue_engine is None"

        # Worker pool summary safely
        if worker_supervisor and hasattr(worker_supervisor, "_pools"):
            group_desired = 0
            group_active = 0
            group_free = 0
            for member in group_info["members"]:
                svc_name = member["service_name"]
                pool = worker_supervisor._pools.get(svc_name)
                if pool:
                    m_desired = getattr(pool, "desired_slots", 0)
                    m_active = getattr(pool, "active_workers", 0)
                    m_free = getattr(pool, "slots_free", 0)
                    member["pool_summary"] = {
                        "desired_slots": m_desired,
                        "active_workers": m_active,
                        "slots_free": m_free,
                    }
                    group_desired += m_desired
                    group_active += m_active
                    group_free += m_free

            group_info["pool_summary"] = {
                "desired_slots": group_desired,
                "active_workers": group_active,
                "slots_free": group_free,
            }

    routing_groups_view = _derive_group_reservations(groups, generation_templates)
    for rg, group_info in groups.items():
        if rg in routing_groups_view:
            group_info["priority"] = routing_groups_view[rg].get("priority", group_info.get("priority", 50))

    out["groups"] = groups
    out["routing_groups"] = routing_groups_view
    dry_run = _compute_service_group_dry_run(groups, all_gpu_states, generation_templates)
    out["scheduler_dry_run"] = dry_run

    # Add Phase 3 observability fields
    phase3_state = _get_phase3_scheduler_state(groups, all_gpu_states, generation_templates)
    for k in ["restart_state_judgement", "grace_window_state", "next_decision", "next_decision_reason", "decision_timestamp", "idle_preferred", "drain_cutoffs"]:
        if k in phase3_state:
            out[k] = phase3_state[k]
    out["phase3_scheduler"] = phase3_state

    # Phase 4 observability
    config = _phase3_scheduling_config()
    scheduler_owns_load = config.get('scheduler_owns_load', False)
    now = time.time()
    last_eval_time = _last_decision.get('decided_at', 0)
    if now - last_eval_time > 5.0:
        _scheduler_evaluate_load(now)

    with _head_job_pre_checks_lock:
        pre_checks_snapshot = list(_head_job_pre_checks)

    out["phase4_scheduler"] = {
        "last_decision": _last_decision,
        "last_dual_swap_state": _last_dual_swap_state,
        "head_job_pre_checks": pre_checks_snapshot,
        "load_history": list(_load_history),
        "group_failure_state": _group_failure_state,
        "scheduler_owns_load": scheduler_owns_load,
        "scheduler_dry_run_mode": config.get('scheduler_dry_run_mode', _scheduler_dry_run_mode)
    }

    # Proactive dispatch telemetry
    out["proactive_dispatch"] = dict(_proactive_dispatch_state)
    # Cap the errors list size in the response (don't dump the full list every poll)
    if "errors" in out["proactive_dispatch"] and len(out["proactive_dispatch"]["errors"]) > 3:
        out["proactive_dispatch"]["errors"] = out["proactive_dispatch"]["errors"][-3:]

    # Phase 5 observability
    global _group_reservations, _reservation_config_warnings
    _group_reservations = routing_groups_view
    warns = _validate_reservation_config(_group_reservations)

    config_warnings = []
    if scheduler_owns_load:
        try:
            templates = _services_config.get('generation_templates', {})
            for name, tmpl in templates.items():
                if tmpl.get('evict_first'):
                    config_warnings.append(f"template '{name}': evict_first is forbidden when scheduler_owns_load=true (runtime ignores it; remove from config)")
        except Exception:
            pass
    config_warnings.extend(_reservation_config_warnings)
    config_warnings.extend(warns)
    out["config_warnings"] = list(set(config_warnings))

    all_known_gpus = set()
    try:
        all_known_gpus.update(_services_config.get('gpu_devices', {}).keys())
    except Exception:
        pass
    all_known_gpus.update(all_gpu_states.keys())
    all_known_gpus.update(_gpu_reservations.keys())

    gpu_res_out = {}
    for gid in all_known_gpus:
        gpu_res_out[gid] = _gpu_reservations.get(gid)

    out['group_reservations'] = _group_reservations
    out['gpu_reservations'] = gpu_res_out
    out['last_reservation_change'] = _last_reservation_change
    out['reservation_history'] = _reservation_history
    out['ingress_blocked_by_reservation'] = _ingress_blocked_by_reservation
    out['ingress_blocked_by_reservation_by_group'] = _ingress_blocked_by_reservation_by_group

    out["phase5_reservations"] = {
        "path": _reservation_persistence_path(),
        "groups": _group_reservations,
        "gpu_reservations": gpu_res_out,
        "warnings": list(set(warns)),
        "last_reservation_change": _last_reservation_change,
        "reservation_history": _reservation_history,
        "ingress_blocked_by_reservation": _ingress_blocked_by_reservation,
        "ingress_blocked_by_reservation_by_group": _ingress_blocked_by_reservation_by_group
    }

    return web.json_response(out)


async def handle_format_stats(request: web.Request):
    """GET /v1/format/stats — Format converter statistics.

    Phase 5.2: returns a per-service gate map (input/output format per
    pool). Legacy `enabled` boolean is kept for backwards compat with
    existing clients/monitors.
    """
    if not _FMT_AVAILABLE:
        return web.json_response({"enabled": False})
    per_service = {}
    try:
        for svc_name, pool in worker_supervisor._pools.items():
            if pool is None:
                continue
            per_service[svc_name] = {
                "input":  getattr(pool, "input_format",  "raw_json"),
                "output": getattr(pool, "output_format", "raw_bytes"),
            }
    except Exception as e:
        per_service = {"_error": str(e)}
    return web.json_response({
        "enabled": True,
        "per_service": per_service,
    })


async def handle_oom_recovery_status(request: web.Request):
    """GET /oom/recovery/status — authoritative per-GPU OOM recovery view."""
    gpu_id = request.query.get("gpu_id")
    payload = _oom_recovery_status_snapshot(gpu_id=gpu_id)
    return web.json_response(payload, status=400 if "error" in payload else 200)


async def handle_oom_dead_letters(request: web.Request):
    """GET /v1/oom/dead-letters — Read-only retained OOM records."""
    try:
        limit = max(1, min(int(request.query.get("limit", "100")), 100))
    except (TypeError, ValueError):
        return web.json_response({"error": "limit must be an integer"}, status=400)

    try:
        entries = await _get_dead_letters(limit=limit)
    except Exception as exc:
        return web.json_response({
            "error": "OOM dead-letter store unavailable",
            "detail": str(exc),
        }, status=503)

    return web.json_response({
        "schema_version": 1,
        "read_only": True,
        "historical_archive": True,
        "redis_key": OOM_REDIS_DEAD_LETTER,
        "count": len(entries),
        "entries": entries,
    })


async def handle_oom_retry_classify(request: web.Request):
    """GET /v1/oom/retry/classify — read-only retry eligibility."""
    entries = await _get_dead_letters(limit=1000)
    requested = {
        value.strip()
        for value in request.query.get("job_ids", "").split(",")
        if value.strip()
    }
    if requested:
        entries = [entry for entry in entries if entry.get("job_id") in requested]
    classified = await _oom_retry_check_redis_state(entries)
    return web.json_response({
        "schema_version": 1,
        "read_only": True,
        "archive_immutable": True,
        "count": len(classified),
        "classifications": classified,
    })


async def handle_oom_retry_correlation(request: web.Request):
    """GET /v1/oom/retry/correlation — read-only cross-store audit."""
    try:
        limit = max(1, min(int(request.query.get("limit", "100")), 1000))
    except (TypeError, ValueError):
        return web.json_response({"error": "limit must be an integer"}, status=400)
    return web.json_response(await _oom_retry_correlation_snapshot(limit=limit))


async def handle_health_all(request: web.Request):
    """GET /v1/health/all — Combined health for every configured service."""
    out = {}
    for svc_name, cfg in _services_config.get("services", {}).items():
        if not cfg.get("enabled"):
            out[svc_name] = {"enabled": False}
            continue
        port = cfg.get("port")
        entry = {"enabled": True, "port": port, "type": cfg.get("type")}
        health_path = cfg.get("health_path") or "/health"
        if port:
            try:
                async with ClientSession() as sess:
                    async with sess.get(
                        f"http://127.0.0.1:{port}{health_path}",
                        timeout=ClientTimeout(total=2),
                    ) as resp:
                        entry["http_status"] = resp.status
                        entry["healthy"] = resp.status == 200
            except Exception as e:
                # Phase 5.2.79 (R1): mirror WorkerSupervisor._check_health
                # pattern — HTTP probe failure is informational, not fatal.
                # Some backends (comfyui exposes /system_stats, various LLM
                # servers have no /health endpoint) won't 200 on the literal
                # /health path. Fall back to a TCP-connect to determine
                # liveness; mark the service healthy if the port answers.
                entry["healthy"] = False
                entry["error"] = str(e)
                try:
                    fut = asyncio.open_connection("127.0.0.1", int(port))
                    _r, _w = await asyncio.wait_for(fut, timeout=2)
                    _w.close()
                    try:
                        await _w.wait_closed()
                    except Exception:
                        pass
                    entry["healthy"] = True
                    entry["error"] = None
                except Exception:
                    pass  # TCP also unreachable; leave healthy=False
        out[svc_name] = entry
    response = {"services": out, "timestamp": time.time()}
    _apply_runtime_semantics(response)
    intentionally_idle = set(response["intentionally_idle"])
    for service_name, entry in out.items():
        service_cfg = (_services_config.get("services", {}).get(service_name, {}) or {})
        service_unit = service_cfg.get("systemd_unit") or service_name
        if service_unit in intentionally_idle:
            entry["intentionally_idle"] = True
            entry["status"] = "intentionally_idle"
            entry["observed_healthy"] = entry.get("healthy")
            entry["healthy"] = None
            entry.pop("error", None)
    return web.json_response(response)


