SERVICES_CONFIG_PATH = os.environ.get("SERVICES_CONFIG_PATH") or os.path.expanduser("~/.config/gpu-manager/services.json")
STATE_FILE = os.environ.get("GPU_MANAGER_STATE_FILE") or os.path.expanduser("~/.config/gpu-manager/state.json")
RUNTIME_STATE_FILE = os.environ.get("GPU_MANAGER_RUNTIME_STATE_FILE") or os.path.expanduser("~/.config/gpu-manager/runtime-state.json")
