# ── Service-pipeline provider registry ────────────────────────────────
# Provider IDs are derived from the declarative registry at pool creation
# time.  This is the dynamic-registration seam: services can reuse a reviewed
# provider without adding another controller conditional.
_service_pipeline_registry: dict = {}
_service_pipeline_registry_error: str | None = None


def _refresh_execution_boundary_registry(config: Mapping[str, Any]) -> None:
    """Refresh provider ownership atomically from the active registry.

    Dispatch classification used to depend on a process-start side effect that
    was never actually populated.  Keep the ownership map in step with every
    successful services.json promotion so a GUI-added provider is either
    immediately classified by its reviewed ``managed`` field or rejected as
    unknown.  Endpoints and executable controls remain outside this map.
    """

    providers = config.get("pipeline_providers", {}) if isinstance(config, Mapping) else {}
    if not isinstance(providers, Mapping):
        providers = {}
    next_entries: list[tuple[str, str, str]] = []
    for provider_id, provider_cfg in providers.items():
        if not isinstance(provider_cfg, Mapping):
            continue
        adapter = provider_cfg.get("adapter")
        if not isinstance(provider_id, str) or not provider_id.strip():
            continue
        if not isinstance(adapter, str) or not adapter.strip():
            logger.warning(
                "execution boundary: provider %r has no adapter; leaving it unknown",
                provider_id,
            )
            continue
        managed = provider_cfg.get("managed", "")
        if managed not in ("", "worker", "external"):
            logger.warning(
                "execution boundary: provider %r has invalid managed=%r; leaving it unknown",
                provider_id,
                managed,
            )
            continue
        next_entries.append((provider_id.strip(), adapter.strip(), str(managed)))

    # The global maps are deliberately replaced as one short critical section;
    # no request should observe stale ownership for an entry that has already
    # been accepted into the new registry.
    clear_provider_ownership()
    for provider_id, adapter, managed in next_entries:
        register_provider_ownership(provider_id, adapter, managed)


def _pipeline_provider_ids(config: Mapping[str, Any]) -> frozenset[str]:
    """Return provider IDs that a server-owned config may reference.

    This helper intentionally accepts the already-parsed config so registry
    loading does not recursively call ``_load_services_config`` while the
    config cache is being promoted.
    """
    ids: set[str] = set()

    providers = (_providers_config or {}).get("providers", {})
    if isinstance(providers, Mapping):
        for name, cfg in providers.items():
            if name == "*":
                continue
            if isinstance(cfg, Mapping) and isinstance(cfg.get("capabilities", []), list):
                ids.add(str(name))

    pipeline_providers = config.get("pipeline_providers", {}) or {}
    if isinstance(pipeline_providers, Mapping):
        for name, provider_cfg in pipeline_providers.items():
            if (
                name != "*"
                and isinstance(provider_cfg, Mapping)
                and provider_cfg.get("enabled", True)
            ):
                ids.add(str(name))

    templates = config.get("generation_templates", {}) or {}
    if isinstance(templates, Mapping):
        for template in templates.values():
            if isinstance(template, Mapping) and template.get("backend"):
                ids.add(str(template["backend"]))
    return frozenset(ids)


def _load_service_pipelines_from_config(config: Mapping[str, Any]) -> None:
    """Atomically load the declarative pipeline registry from one config.

    Invalid graphs clear the active registry and retain a bounded error rather
    than leaving a stale graph that could retarget a newly registered service.
    Legacy templates without ``service_pipeline_id`` remain unaffected.
    """
    global _service_pipeline_registry, _service_pipeline_registry_error
    raw = config.get("service_pipelines") or {}
    if not isinstance(raw, Mapping) or not raw:
        _service_pipeline_registry = {}
        _service_pipeline_registry_error = None
        return
    try:
        from service_pipeline import load_service_pipelines

        registry = load_service_pipelines(
            dict(raw), _pipeline_provider_ids(config)
        )
    except Exception as exc:
        _service_pipeline_registry = {}
        _service_pipeline_registry_error = str(exc)[:500]
        logger.warning(
            "service_pipeline: registry rejected; declarative pipeline admission "
            "is disabled until config is repaired: %s",
            _service_pipeline_registry_error,
        )
        return
    _service_pipeline_registry = dict(registry)
    _service_pipeline_registry_error = None


def _get_pipeline_provider_registry(
    config: Mapping[str, Any] | None = None,
) -> frozenset[str]:
    """Return the closed set of provider IDs admitted by current config."""
    if config is None:
        config = _services_config or _services_config_cache or {}
        if not config:
            config = _load_services_config()
    if not isinstance(config, Mapping):
        config = {}
    return _pipeline_provider_ids(config)


def _load_providers_config() -> dict:
    """Load providers config from disk, falling back to empty registry."""
    try:
        if os.path.exists(PROVIDERS_CONFIG_PATH):
            with open(PROVIDERS_CONFIG_PATH) as f:
                return json.load(f)
    except Exception as e:
        logger.warning(f"Failed to load providers config: {e}")
    return {"providers": {}}
_service_health_cache: dict = {}
_service_health_counter: int = 0
_nginx_status_cache: dict = {"state": "unknown", "config_valid": None, "proxy_ports": []}
_vram_cache_ts: float = 0.0
_vram_poll_lock: asyncio.Lock | None = None
_VRAM_POLL_TTL = 1.0


def _parse_amdgpu_top(json_text: str) -> dict:
    """Parse amdgpu_top -p --json output into structured VRAM data with per-GPU processes."""
    import json as _json
    try:
        data = _json.loads(json_text)
    except _json.JSONDecodeError:
        logger.warning("VRAM poll: failed to parse amdgpu_top JSON")
        return {"total_vram_mib": 0, "used_vram_mib": 0, "free_vram_mib": 0,
                "usage_pct": 0, "total_gtt_mib": 0, "used_gtt_mib": 0,
                "processes": [], "process_count": 0, "devices": []}

    devices = data.get("devices", [])
    all_processes = []
    total_vram = 0
    total_used = 0
    total_gtt = 0
    total_gtt_used = 0
    # Discrete-only aggregates: an APU's VRAM is a BIOS carve-out of system
    # RAM, so adding it to the discrete total overstates GPU capacity.  The
    # legacy totals above stay all-device for existing consumers.
    dgpu_vram = 0
    dgpu_used = 0
    apu_vram = 0
    per_device = []  # per-device process lists for merging into _detect_gpus

    for dev in devices:
        info = dev.get("Info", {})
        pci = info.get("PCI", "")
        card_path = info.get("DevicePath", {}).get("card", "")
        # Extract card name from /dev/dri/card1 -> card1
        card_name = card_path.rsplit("/", 1)[-1] if "/" in card_path else ""
        device_name = info.get("DevicePath", {}).get("DeviceName", "")
        # amdgpu_top reports libdrm's classification: "APU" or "dGPU".
        is_apu = str(info.get("GPU Type") or "").strip().upper() == "APU"

        # VRAM totals from this device
        vram_info = dev.get("VRAM", {})
        dev_total_vram = vram_info.get("Total VRAM", {}).get("value", 0)
        dev_used_vram = vram_info.get("Total VRAM Usage", {}).get("value", 0)
        dev_total_gtt = vram_info.get("Total GTT", {}).get("value", 0)
        dev_used_gtt = vram_info.get("Total GTT Usage", {}).get("value", 0)

        total_vram += dev_total_vram
        total_used += dev_used_vram
        total_gtt += dev_total_gtt
        total_gtt_used += dev_used_gtt
        if is_apu:
            apu_vram += dev_total_vram
        else:
            dgpu_vram += dev_total_vram
            dgpu_used += dev_used_vram

        # Parse per-process fdinfo
        fdinfo = dev.get("fdinfo", {})
        dev_processes = []
        for pid_str, proc_data in fdinfo.items():
            usage = proc_data.get("usage", {})
            if isinstance(usage, dict) and "usage" in usage:
                usage = usage["usage"]
            proc_name = proc_data.get("name", proc_data.get("usage", {}).get("name", ""))
            vram_mib = 0
            gtt_mib = 0
            try:
                vram_mib = usage.get("VRAM", {}).get("value", 0) if isinstance(usage.get("VRAM"), dict) else 0
                gtt_mib = usage.get("GTT", {}).get("value", 0) if isinstance(usage.get("GTT"), dict) else 0
            except (AttributeError, TypeError):
                pass

            proc_vram_pct = round(vram_mib / dev_total_vram * 100) if dev_total_vram else 0
            entry = {
                "name": proc_name,
                "pid": int(pid_str),
                "vram_mib": vram_mib,
                "vram_pct": proc_vram_pct,
                "gtt_mib": gtt_mib,
            }
            # Categorize
            entry["category"] = "other"
            name_lower = proc_name.lower()
            if any(kw in name_lower for kw in ("llama", "nomic", "embed", "ollama", "vllm")):
                entry["category"] = "llm"
            elif "python" in name_lower:
                entry["category"] = "python"
            elif proc_name in ("plasmashell", "kwin_wayland", "Xwayland", "chromium", "alacritty"):
                entry["category"] = "desktop"

            dev_processes.append(entry)
            all_processes.append(entry)

        dev_processes.sort(key=lambda p: p["vram_mib"], reverse=True)
        per_device.append({
            "pci": pci,
            "card": card_name,
            "device_name": device_name,
            "integrated": is_apu,
            "processes": dev_processes,
            "vram_total_mib": dev_total_vram,
            "vram_used_mib": dev_used_vram,
            "vram_usage_pct": round(dev_used_vram / dev_total_vram * 100, 1) if dev_total_vram else 0,
        })

    all_processes.sort(key=lambda p: p["vram_mib"], reverse=True)

    return {
        "total_vram_mib": total_vram,
        "used_vram_mib": total_used,
        "free_vram_mib": total_vram - total_used,
        "usage_pct": round(total_used / total_vram * 100, 1) if total_vram else 0,
        "total_gtt_mib": total_gtt,
        "used_gtt_mib": total_gtt_used,
        "dgpu_total_vram_mib": dgpu_vram,
        "dgpu_used_vram_mib": dgpu_used,
        "dgpu_usage_pct": round(dgpu_used / dgpu_vram * 100, 1) if dgpu_vram else 0,
        "apu_vram_mib": apu_vram,
        "processes": all_processes,
        "process_count": len(all_processes),
        "devices": per_device,
    }


def _sysfs_attr_path(card: str, attr: str) -> str | None:
    """Return an existing sysfs attribute path for *card*.

    Linux normally exposes these attributes through ``cardN/device``.  The
    direct ``cardN`` path is also valid for a number of DRM symlink layouts
    and keeps this reader compatible with older kernels and offline sysfs
    fixtures.  Prefer the direct path when both exist: it is the path exposed
    by the DRM class entry and avoids accidentally mixing a card symlink with
    a stale device path.
    """
    card_path = f"/sys/class/drm/{card}"
    for base in (card_path, f"{card_path}/device"):
        path = f"{base}/{attr}"
        if os.path.exists(path):
            return path
    return None


def _read_sysfs_text(path: str | None) -> str | None:
    """Read a sysfs text attribute without inventing a value on failure."""
    if not path:
        return None
    try:
        with open(path) as handle:
            return handle.read().strip()
    except (OSError, ValueError):
        return None


def _read_sysfs_int(path: str | None) -> int | None:
    """Read an integer sysfs attribute, returning ``None`` when unavailable."""
    raw = _read_sysfs_text(path)
    if raw is None or raw == "":
        return None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


_GFX_ARCH_MAP_ENV = "GPU_MANAGER_GFX_ARCH_MAP"


def _kfd_gfx_arch(gfx_target_version: int) -> str | None:
    """Convert a KFD ``gfx_target_version`` (major*10000 + minor*100 + step) into ``gfxNNN``."""
    if gfx_target_version <= 0:
        return None
    major, rest = divmod(gfx_target_version, 10000)
    minor, step = divmod(rest, 100)
    return f"gfx{major}{minor}{step:x}"


def _drm_render_minor(card: str, sys_root: str = "/sys") -> int | None:
    """Return the render-node minor (128+) that belongs to a DRM card, read-only."""
    drm_dir = os.path.join(sys_root, "class", "drm", card, "device", "drm")
    try:
        entries = sorted(os.listdir(drm_dir))
    except OSError:
        return None
    for entry in entries:
        if entry.startswith("renderD") and entry[len("renderD"):].isdigit():
            return int(entry[len("renderD"):])
    return None


def _kfd_gfx_arch_for_render_minor(render_minor: int | None, sys_root: str = "/sys") -> str | None:
    """Find the KFD topology node bound to *render_minor* and return its gfx arch."""
    if render_minor is None:
        return None
    nodes_dir = os.path.join(sys_root, "class", "kfd", "kfd", "topology", "nodes")
    try:
        node_names = sorted(os.listdir(nodes_dir))
    except OSError:
        return None
    for node in node_names:
        text = _read_sysfs_text(os.path.join(nodes_dir, node, "properties"))
        if not text:
            continue
        props = {}
        for line in text.splitlines():
            parts = line.split()
            if len(parts) == 2:
                props[parts[0]] = parts[1]
        try:
            if int(props.get("drm_render_minor", "0")) != render_minor:
                continue
            return _kfd_gfx_arch(int(props.get("gfx_target_version", "0")))
        except ValueError:
            continue
    return None


def _load_gfx_arch_map() -> dict:
    """Optional hints from the JSON file named by GPU_MANAGER_GFX_ARCH_MAP.

    Shape: {"device_ids": {"<pci device id>": "gfxNNN"}, "name_hints": {"<substring>": "gfxNNN"},
    "bf16_unsupported": ["gfxNNN"]}.
    Empty when the variable is unset or the file cannot be read.
    """
    path = os.environ.get(_GFX_ARCH_MAP_ENV, "").strip()
    if not path:
        return {}
    try:
        with open(path, encoding="utf-8") as handle:
            data = json.load(handle)
    except (OSError, ValueError):
        return {}
    return data if isinstance(data, dict) else {}


def _gfx_arch_bf16_unsupported() -> set:
    """Architectures the operator's data marks as lacking native BF16 (empty by default)."""
    values = _load_gfx_arch_map().get("bf16_unsupported") or []
    return {str(item) for item in values} if isinstance(values, list) else set()


def _gfx_arch_for_card(card: str, gpu_name: str, sys_root: str = "/sys") -> str | None:
    """Return the gfx architecture of *card*, or None when it cannot be determined."""
    arch = _kfd_gfx_arch_for_render_minor(_drm_render_minor(card, sys_root), sys_root)
    if arch:
        return arch
    hints = _load_gfx_arch_map()
    dev_id_raw = None
    for dev_path in (f"/sys/class/drm/{card}/device/device", _sysfs_attr_path(card, "device")):
        if dev_path and os.path.isfile(dev_path):
            dev_id_raw = _read_sysfs_text(dev_path)
            if dev_id_raw:
                break
    if dev_id_raw:
        dev_id_clean = dev_id_raw.lower()
        for dev_id, hinted in (hints.get("device_ids") or {}).items():
            if str(dev_id).lower() in dev_id_clean:
                return str(hinted)
    upper_name = gpu_name.upper()
    for needle, hinted in (hints.get("name_hints") or {}).items():
        if str(needle).upper() in upper_name:
            return str(hinted)
    return None


def is_junction_critical(telemetry: Mapping) -> bool:
    """Return whether junction temperature has reached its reported limit.

    This is deliberately a pure, fail-closed predicate.  Missing or malformed
    readings are *not* treated as safe evidence and therefore do not produce a
    positive abort signal here; callers can use
    :func:`junction_critical_threshold_known` to distinguish that state from a
    known sub-critical reading.
    """
    try:
        junction = telemetry.get("temp_junction_c")
        critical = telemetry.get("temp_junction_crit_c")
        if junction is None or critical is None:
            return False
        return float(junction) >= float(critical)
    except (AttributeError, TypeError, ValueError):
        return False


def junction_critical_threshold_known(telemetry: Mapping) -> bool:
    """Return whether the device-reported junction critical value is known."""
    try:
        critical = telemetry.get("temp_junction_crit_c")
        if critical is None:
            return False
        float(critical)
        return True
    except (AttributeError, TypeError, ValueError):
        return False


def _read_card_pci_uevent(card: str) -> str:
    """Return the PCI device uevent text for a DRM *card*.

    ``/sys/class/drm/cardN/uevent`` is the DRM minor's own uevent
    (MAJOR/MINOR/DEVNAME) and carries no PCI identity; the PCI_ID and
    PCI_SLOT_NAME lines live in ``cardN/device/uevent``.  Prefer the first
    candidate that actually carries PCI identity, so a direct-path fixture
    that holds PCI lines keeps working, and return "" when none does.
    """
    card_path = f"/sys/class/drm/{card}"
    for path in (f"{card_path}/device/uevent", f"{card_path}/uevent"):
        text = _read_sysfs_text(path if os.path.exists(path) else None) or ""
        if "PCI_SLOT_NAME=" in text or "PCI_ID=" in text:
            return text
    return ""


def _detect_gpus() -> list:
    """Detect AMD GPUs and expose stable per-card telemetry.

    The returned shape is additive with respect to the legacy API.  Existing
    consumers can continue using ``gpu_type``, ``gpu_name``, VRAM fields and
    the five legacy telemetry keys, while thermal consumers get labeled edge,
    junction/hotspot and memory channels plus their device-reported critical
    thresholds.  Unreadable attributes remain ``None`` rather than becoming
    a fabricated zero or safe value.
    """
    gpus = []
    try:
        all_cards = sorted(
            card for card in os.listdir("/sys/class/drm")
            if card.startswith("card") and "-" not in card
        )
    except OSError:
        all_cards = ["card0", "card1", "card2"]

    for card in all_cards:
        vendor_path = _sysfs_attr_path(card, "vendor")
        vendor = _read_sysfs_text(vendor_path)
        if vendor != "0x1002":
            continue

        # Name: product_name is preferred, with the legacy name/uevent paths
        # retained for kernels that do not expose product_name.
        gpu_name = _read_sysfs_text(_sysfs_attr_path(card, "product_name")) or ""
        if not gpu_name:
            gpu_name = _read_sysfs_text(_sysfs_attr_path(card, "name")) or ""
        if not gpu_name:
            uevent = _read_card_pci_uevent(card)
            device_id = None
            for line in uevent.splitlines():
                if line.startswith("PCI_ID="):
                    raw_pci_id = line.split("=", 1)[1].strip()
                    device_id = raw_pci_id.split(":", 1)[-1].upper()
                    break
            gpu_name = (
                f"AMD GPU ({device_id})" if device_id else "Unknown AMD GPU"
            )

        upper_name = gpu_name.upper()
        is_igpu = any(
            marker in upper_name
            for marker in ("RAPHAEL", "MENDOCINO", "RENOIR", "CEZANNE", "PHOENIX")
        )
        if not is_igpu:
            vram_probe = _read_sysfs_int(_sysfs_attr_path(card, "mem_info/vram"))
            if vram_probe is not None:
                is_igpu = vram_probe // (1024 * 1024) < 1000
        gpu_type = "iGPU" if is_igpu else "dGPU"

        vram_total = 0
        if not is_igpu:
            for attr in (
                "mem_info_vram",
                "mem_info_vram_total",
                "mem_info_vis_vram_total",
            ):
                raw = _read_sysfs_int(_sysfs_attr_path(card, attr))
                if raw is not None:
                    vram_total = raw // (1024 * 1024)
                    break

        uevent = _read_card_pci_uevent(card)
        pci_address = None
        for line in uevent.splitlines():
            if line.startswith("PCI_SLOT_NAME="):
                pci_address = line.split("=", 1)[1].strip()
                break

        # Prefer the hwmon directory exposed directly below the card, then
        # fall back to the conventional card/device/hwmon layout.
        card_path = f"/sys/class/drm/{card}"
        hwmon = None
        for hwmon_base in (f"{card_path}/hwmon", f"{card_path}/device/hwmon"):
            try:
                hwmons = os.listdir(hwmon_base)
            except OSError:
                hwmons = []
            if hwmons:
                hwmon = f"{hwmon_base}/{sorted(hwmons)[0]}"
                break

        def hwmon_attr_path(name: str) -> str | None:
            """Resolve both real flat hwmon files and nested offline fixtures."""
            flat = f"{hwmon}/{name}" if hwmon else None
            if flat and os.path.exists(flat):
                return flat
            if hwmon and "_" in name:
                prefix, suffix = name.split("_", 1)
                nested = f"{hwmon}/{prefix}/{name}"
                if os.path.exists(nested):
                    return nested
            return None

        def read_hwmon(name: str, scale: float = 1) -> float | int | None:
            raw = _read_sysfs_int(hwmon_attr_path(name))
            if raw is None:
                return None
            return raw / scale if scale != 1 else raw

        def read_hwmon_text(name: str) -> str | None:
            return _read_sysfs_text(hwmon_attr_path(name))

        # Read all labeled temperature channels.  Real hwmon devices expose
        # flat names (temp1_input); the nested form is accepted for offline
        # fixtures and older compatibility shims.  temp1/2/3 remain the
        # fallback mapping when a channel has no label.
        channels: dict[str, tuple[float | None, float | None]] = {}
        fixed_names = {1: "edge", 2: "junction", 3: "mem"}
        aliases = {
            "edge": "edge",
            "junction": "junction",
            "hotspot": "junction",
            "hot spot": "junction",
            "mem": "mem",
            "memory": "mem",
        }
        if hwmon:
            try:
                hwmon_names = os.listdir(hwmon)
            except OSError:
                hwmon_names = []
            temp_indices = set()
            for name in hwmon_names:
                candidate = name[4:-6] if name.startswith("temp") and name.endswith("_input") else name[4:] if name.startswith("temp") else ""
                if candidate.isdigit():
                    temp_indices.add(int(candidate))
            for index in sorted(temp_indices):
                label = (read_hwmon_text(f"temp{index}_label") or "").strip().lower()
                logical = aliases.get(label) or fixed_names.get(index)
                if logical is None:
                    continue
                current = read_hwmon(f"temp{index}_input", 1000)
                critical = read_hwmon(f"temp{index}_crit", 1000)
                channels.setdefault(logical, (current, critical))

        edge_c, edge_crit_c = channels.get("edge", (None, None))
        junction_c, junction_crit_c = channels.get("junction", (None, None))
        mem_c, mem_crit_c = channels.get("mem", (None, None))

        gpu_util = _read_sysfs_int(_sysfs_attr_path(card, "gpu_busy_percent"))
        # ``temp_c`` historically represented the primary thermal reading.  A
        # junction value is the safer and more useful primary reading when it
        # exists; edge remains the fallback on older hwmon devices.
        temp_c = junction_c if junction_c is not None else edge_c
        power_w = read_hwmon("power1_average", 1_000_000)
        sclk_mhz = read_hwmon("freq1_input", 1_000_000)
        mclk_mhz = read_hwmon("freq2_input", 1_000_000)
        telemetry = {
            "gpu_util_pct": gpu_util,
            "temp_c": temp_c,
            "power_w": power_w,
            "sclk_mhz": sclk_mhz,
            "mclk_mhz": mclk_mhz,
            "temp_edge_c": edge_c,
            "temp_edge_crit_c": edge_crit_c,
            "temp_junction_c": junction_c,
            "temp_junction_crit_c": junction_crit_c,
            "temp_mem_c": mem_c,
            "temp_mem_crit_c": mem_crit_c,
        }

        # Hardware recognition and capability traits (ROCm/Vulkan/CPU, BF16 constraints)
        gfx_arch = None
        device_vendor = "AMD"
        device_status = "observed"
        native_bf16 = False
        compute_apis = ["rocm", "vulkan"]
        supported_precisions = ["fp32", "fp16", "int8", "int4"]
        unsupported_precisions = ["bf16"]

        # Detect architecture from read-only kernel topology (KFD gfx target version
        # of this card's DRM render node). Operator-supplied hints are used only
        # when the kernel does not report it; none are compiled into this file.
        gfx_arch = _gfx_arch_for_card(card, gpu_name)

        if gfx_arch and gfx_arch in _gfx_arch_bf16_unsupported():
            native_bf16 = False
            unsupported_precisions = ["bf16"]
            supported_precisions = ["fp32", "fp16", "int8", "int4"]
        elif is_igpu:
            native_bf16 = False
            compute_apis = ["vulkan"]

        vram_used_mib = None
        if not is_igpu:
            for attr in ("mem_info_vram_used", "mem_info_vis_vram_used"):
                raw = _read_sysfs_int(_sysfs_attr_path(card, attr))
                if raw is not None:
                    vram_used_mib = raw // (1024 * 1024)
                    break

        vram_free_mib = max(0, vram_total - (vram_used_mib or 0)) if vram_total else 0

        gpu_entry = {
            "card": card,
            "gpu_type": gpu_type,
            "gpu_name": gpu_name,
            "vendor": device_vendor,
            "gfx_arch": gfx_arch,
            "status": device_status,
            "compute_apis": compute_apis,
            "native_bf16": native_bf16,
            "supported_precisions": supported_precisions,
            "unsupported_precisions": unsupported_precisions,
            "vram_total_mib": vram_total,
            "vram_free_mib": vram_free_mib,
            "pci_address": pci_address,
            # Keep this top-level compatibility field: older /vram clients
            # read it directly instead of traversing telemetry.
            "gpu_util_pct": gpu_util,
            "telemetry": telemetry,
        }

        if vram_used_mib is not None:
            gpu_entry["vram_used_mib"] = vram_used_mib
            if vram_total:
                gpu_entry["vram_usage_pct"] = round(
                    vram_used_mib / vram_total * 100, 1
                )

        gpus.append(gpu_entry)

    return gpus


def _read_system_ram() -> dict:
    """Read system RAM from /proc/meminfo (for iGPU shared memory display)."""
    try:
        with open("/proc/meminfo") as f:
            lines = f.readlines()
        info = {}
        for line in lines:
            parts = line.split()
            if len(parts) >= 2:
                key = parts[0].rstrip(":")
                # All values in /proc/meminfo are in kB
                info[key] = int(parts[1])  # kB
        total = info.get("MemTotal", 0)
        free = info.get("MemAvailable", info.get("MemFree", 0))
        used = total - free
        return {
            "total_mib": round(total / 1024),
            "used_mib": round(used / 1024),
            "free_mib": round(free / 1024),
            "usage_pct": round(used / total * 100, 1) if total else 0,
        }
    except Exception:
        return {}


def _read_gpu_telemetry() -> dict:
    """Read telemetry for the first detected discrete GPU."""
    gpus = _detect_gpus()
    for gpu in gpus:
        if gpu.get("gpu_type") == "dGPU":
            return gpu.get("telemetry", {})
    return {}


_PORT_PURPOSE = {
    8090: "Vision (Gemma 4)",
    8092: "LLM Backend (Qwen3.6)",
}


def _enrich_process_with_identity(processes: list) -> list:
    """Enrich llama-server processes with model path, port, and purpose."""
    new_cache = {}
    for p in processes:
        if "llama-server" not in p.get("name", "").lower():
            p["model_name"] = None
            p["model_path"] = None
            p["service_port"] = None
            p["service_purpose"] = None
            p["gpu_offload"] = None
            continue

        pid = p["pid"]
        cmdline = ""
        try:
            cmdline = open(f"/proc/{pid}/cmdline").read().replace("\0", " ").strip()
        except OSError:
            pass

        # Parse model path
        model_path = None
        for flag in ["-m ", "--model "]:
            if flag in cmdline:
                idx = cmdline.index(flag)
                rest = cmdline[idx + len(flag):]
                parts = rest.split()
                if parts:
                    model_path = parts[0]
                    break

        # Parse port
        port = None
        for flag in ["--port ", "-sp "]:
            if flag in cmdline:
                idx = cmdline.index(flag)
                rest = cmdline[idx + len(flag):]
                m = __import__("re").search(r"\d+", rest)
                if m:
                    port = int(m.group())

        # Parse GPU layers
        ngl = None
        for flag in ["-ngl ", "--n-gpu-layers "]:
            if flag in cmdline:
                idx = cmdline.index(flag)
                rest = cmdline[idx + len(flag):]
                m = __import__("re").search(r"\d+", rest)
                if m:
                    ngl = int(m.group())
                    break

        purpose = _PORT_PURPOSE.get(port, "unknown") if port else "unknown"
        if ngl is not None and ngl >= 99:
            offload = "full"
        elif ngl is not None:
            offload = "partial"
        else:
            offload = "unknown"

        p["model_path"] = model_path
        p["model_name"] = os.path.basename(model_path) if model_path else None
        p["service_port"] = port
        p["service_purpose"] = purpose
        p["gpu_offload"] = offload

        new_cache[pid] = {"model_path": model_path, "port": port, "ngl": ngl}

    return processes


async def _poll_vram_background(max_age_s: float | None = None) -> dict:
    """Reuse idle-pusher telemetry while it is within the idle polling window.

    ``max_age_s`` lets a slow background caller (e.g. the orphan reaper, which
    scans every ``ORPHAN_REAPER_INTERVAL_S`` = 30 s) reuse the shared cache for
    longer than the idle-pusher's own refresh cadence without forcing an
    expensive probe on every tick. ``None`` keeps the 5 s idle-pusher default.
    """
    window = (VRAM_IDLE_POLL_EVERY * VRAM_POLL_INTERVAL if max_age_s is None else max_age_s)
    if _vram_cache and (time.monotonic() - _vram_cache_ts) < window:
        return _vram_cache
    return await _poll_vram()


async def _poll_vram() -> dict:
    """Run amdgpu_top and return parsed VRAM data.

    Coalesce concurrent callers and apply a short TTL cache so repeated
    consumers (~1 Hz) share one expensive `amdgpu_top` invocation.
    """
    global _vram_cache, _vram_cache_ts, _vram_poll_lock
    now = time.monotonic()
    if _vram_cache and (now - _vram_cache_ts) < _VRAM_POLL_TTL:
        return _vram_cache

    if _vram_poll_lock is None:
        _vram_poll_lock = asyncio.Lock()

    async with _vram_poll_lock:
        now = time.monotonic()
        if _vram_cache and (now - _vram_cache_ts) < _VRAM_POLL_TTL:
            return _vram_cache
        result = await _poll_vram_once()
        if not result.get("error"):
            _vram_cache = result
            _vram_cache_ts = time.monotonic()
        return result


def _normalize_pci_address(value: str | None) -> str | None:
    """Return a canonical domain:bus:device.function PCI address."""
    text = str(value or "").strip().lower()
    match = re.search(
        r"(?:(?P<domain>[0-9a-f]{4}):)?(?P<bus>[0-9a-f]{2}):"
        r"(?P<device>[0-9a-f]{2})\.(?P<function>[0-7])$",
        text,
    )
    if not match:
        return None
    domain = match.group("domain") or "0000"
    return (
        f"{domain}:{match.group('bus')}:{match.group('device')}."
        f"{match.group('function')}"
    )


def _is_generic_gpu_name(name: str | None) -> bool:
    text = str(name or "").strip()
    return not text or text == "Unknown AMD GPU" or text.startswith("AMD GPU (")


def _annotate_gpu_identity(gpus: list, gpu_devices: Mapping | None) -> list:
    """Attach the configured ``gpu_id`` (and a readable name) to /vram rows.

    Scheduler state, bundles and the dashboard key GPUs by configured id
    (e.g. ``gpu_a``) while sysfs rows are keyed by ``card``.  Match by
    PCI address first, then by the configured ``card``.  A configured PCI
    address that disagrees with the row's PCI address never falls back to the
    card match.  A configured ``name`` replaces only a generic detected name.
    """
    devices = gpu_devices if isinstance(gpu_devices, Mapping) else {}
    for gpu in gpus or []:
        if not isinstance(gpu, dict):
            continue
        row_pci = _normalize_pci_address(gpu.get("pci_address"))
        card = str(gpu.get("card") or "")
        matched_gid = None
        for gid, cfg in devices.items():
            if not isinstance(cfg, Mapping):
                continue
            cfg_pci = _normalize_pci_address(cfg.get("pci"))
            if cfg_pci and row_pci:
                if cfg_pci == row_pci:
                    matched_gid = gid
                    break
                continue
            if card and str(cfg.get("card") or "") == card:
                matched_gid = gid
                break
        if matched_gid is None:
            continue
        gpu["gpu_id"] = str(matched_gid)
        cfg_name = str((devices.get(matched_gid) or {}).get("name") or "").strip()
        if cfg_name and _is_generic_gpu_name(gpu.get("gpu_name")):
            gpu["gpu_name"] = cfg_name
    return gpus


def _get_vram_entry_for_gpu(vram_data: dict, gpu_id: str | None) -> dict | None:
    if not gpu_id:
        return None
    cfg = _load_services_config().get("gpu_devices", {}) or {}
    target = cfg.get(gpu_id, {})
    target_pci = _normalize_pci_address(target.get("pci"))
    target_card = str(target.get("card", "")).strip()
    for gpu in vram_data.get("gpus", []):
        if target_pci and _normalize_pci_address(gpu.get("pci_address")) == target_pci:
            return gpu
    if target_pci:
        # The normalized ``gpus`` projection can lack PCI addresses when
        # _detect_gpus() cannot enrich its entries. Raw amdgpu_top device
        # telemetry still carries the authoritative PCI identity; use it
        # before failing closed. Do not fall back to card-only matching when
        # a configured PCI address disagrees.
        for device in vram_data.get("devices", []):
            if _normalize_pci_address(device.get("pci")) == target_pci:
                return device
        return None
    for gpu in vram_data.get("gpus", []):
        card = gpu.get("card", "")
        if gpu.get("gpu_id") == gpu_id:
            return gpu
        if card == gpu_id:
            return gpu
        if target_card and card == target_card:
            return gpu
    return None


def _gpu_vram_ceiling_mib(gpu_id: str | None) -> int | None:
    """Return the effective ceiling from the registry's capacity contract."""
    if not gpu_id:
        return None
    device = (_load_services_config().get("gpu_devices", {}) or {}).get(gpu_id, {}) or {}
    try:
        physical = int(device.get("vram_mib") or 0)
        ceiling = int(device.get("vram_ceiling_mib") or 0)
        reserve = int(device.get("vram_reserve_mib") or 0)
    except (TypeError, ValueError):
        return None
    candidates = [
        value
        for value in (ceiling, physical - reserve if physical and reserve else 0)
        if value > 0
    ]
    # The RX 6950 XT drives the desktop. Preserve at least 1,536 MiB for
    # Xorg/KWin/display regardless of an unsafe larger configured value. A stricter
    # configured ceiling still wins through min().
    if gpu_id == "rx6950xt":
        candidates.append(14832)
    return min(candidates) if candidates else None


async def _check_gpu_vram_ceiling(gpu_id: str | None, *, phase: str) -> tuple[bool, str]:
    """Fail closed for a configured GPU when telemetry is missing or over cap."""
    ceiling = _gpu_vram_ceiling_mib(gpu_id)
    if ceiling is None:
        return True, "no configured ceiling"
    try:
        data = await _poll_vram()
        entry = _get_vram_entry_for_gpu(data, gpu_id)
        if not entry:
            return False, f"{gpu_id}: no VRAM telemetry during {phase}"
        used = int(entry.get("vram_used_mib") or entry.get("used_mib") or 0)
        total = int(entry.get("vram_total_mib") or entry.get("total_mib") or 0)
        if total <= 0:
            return False, f"{gpu_id}: invalid total VRAM telemetry during {phase}"
        if used > ceiling:
            return False, (
                f"{gpu_id}: {used} MiB used exceeds configured ceiling "
                f"{ceiling} MiB during {phase}"
            )
        return True, f"{gpu_id}: {used}/{ceiling} MiB during {phase}"
    except Exception as exc:
        return False, f"{gpu_id}: VRAM ceiling telemetry failed during {phase}: {exc}"


async def _poll_vram_once() -> dict:
    """Run amdgpu_top and return parsed VRAM data."""
    try:
        proc = await asyncio.create_subprocess_exec(
            "sudo", "amdgpu_top", "-p", "--json",
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.DEVNULL,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=5)
        text = stdout.decode("utf-8", errors="replace")
        if not text.strip():
            logger.warning("VRAM poll: amdgpu_top returned empty output")
            return _vram_cache if _vram_cache else {"error": "empty output", "processes": []}
        result = _parse_amdgpu_top(text)
        # Enrich llama-server processes with model identity
        result["processes"] = _enrich_process_with_identity(result["processes"])
        # Merge per-device process lists into _detect_gpus() output
        gpus = await asyncio.get_event_loop().run_in_executor(None, _detect_gpus)
        per_device = result.get("devices", [])
        for gpu in gpus:
            pci = gpu.get("pci_address")
            card = gpu.get("card", "")
            # Match by PCI address or card name
            matched = None
            for dev in per_device:
                if pci and dev.get("pci") == pci:
                    matched = dev
                    break
                if dev.get("card") and card and dev["card"] == card:
                    matched = dev
                    break
            if matched:
                gpu["processes"] = matched["processes"]
                # Additive flag only: gpu_type stays as _detect_gpus set it,
                # so admission and capacity inputs are unchanged.
                gpu["integrated"] = bool(matched.get("integrated"))
                if matched.get("vram_used_mib") is not None and not gpu.get("vram_used_mib"):
                    gpu["vram_used_mib"] = matched["vram_used_mib"]
                total_mib = matched.get("vram_total_mib") or 0
                if total_mib:
                    gpu["vram_total_mib"] = total_mib
                    used_mib = gpu.get("vram_used_mib")
                    if used_mib is not None:
                        gpu["vram_usage_pct"] = round(used_mib / total_mib * 100, 1)
            else:
                gpu["processes"] = []
        try:
            _annotate_gpu_identity(
                gpus, (_load_services_config() or {}).get("gpu_devices", {})
            )
        except Exception as e:
            logger.debug(f"GPU identity annotation failed: {e}")
        result["gpus"] = gpus
        # Augment with Vulkan/GEM-fd tenant data — visible to fdinfo
        # but not to amdgpu_top's per-process VRAM line. This is
        # important for hybrid GPU backends (HIP DiT + Vulkan text
        # encoder) where the Vulkan half is otherwise invisible to
        # GPU Manager.
        try:
            gem_scan = await asyncio.get_event_loop().run_in_executor(
                None, _scan_render_node_fdinfo_cached
            )
            config_v = _load_services_config()
            gpu_devices_v = config_v.get("gpu_devices", {}) or {}
            rn_to_gpu = _build_render_node_to_gpu_map_cached(gpu_devices_v)
            vulkan_tenants_by_gpu: dict = {}
            for pid, rn_data in gem_scan.items():
                for rn, info in rn_data.items():
                    gid = rn_to_gpu.get(rn)
                    if not gid:
                        continue
                    if info["drm_vm_bytes"] == 0:
                        continue
                    proc_info = {
                        "pid": pid,
                        "name": _read_proc_name(pid) or f"pid={pid}",
                        "render_node": rn,
                        "drm_vm_mib": info["drm_vm_bytes"] // (1024 * 1024),
                        "amdgpu_vram_mib": info["amdgpu_vram_bytes"] // (1024 * 1024),
                        "fd_count": info["fd_count"],
                        "category": (
                            "vulkan"
                            if info["drm_vm_bytes"] > info["amdgpu_vram_bytes"]
                            else "rocm-gem"
                        ),
                    }
                    vulkan_tenants_by_gpu.setdefault(gid, []).append(proc_info)
            pci_to_gid = {
                cfg["pci"]: gid
                for gid, cfg in gpu_devices_v.items()
                if cfg.get("pci")
            }
            for gpu in gpus:
                matched_gid = pci_to_gid.get(gpu.get("pci_address", ""))
                if matched_gid:
                    gpu["gpu_id"] = matched_gid
                    gpu["vulkan_tenants"] = vulkan_tenants_by_gpu.get(matched_gid, [])
            result["vulkan_tenants"] = vulkan_tenants_by_gpu
        except Exception as e:
            logger.debug(f"Vulkan fdinfo scan failed: {e}")
        # Add system RAM metrics
        result["system_ram"] = await asyncio.get_event_loop().run_in_executor(None, _read_system_ram)
        logger.info(f"VRAM poll: {result.get('process_count',0)} processes, "
                    f"used={result.get('used_vram_mib')}/{result.get('total_vram_mib')} MiB")
        return result
    except Exception as e:
        logger.warning(f"VRAM poll failed: {e}")
        return _vram_cache if _vram_cache else {"error": str(e), "processes": []}


async def _broadcast_ws(message: dict):
    """Push a JSON message to all connected WebSocket clients."""
    global _ws_clients
    dead = set()
    for ws in _ws_clients:
        try:
            await ws.send_json(message)
        except Exception:
            dead.add(ws)
    _ws_clients -= dead

def _get_lifecycle_snapshot() -> dict:
    """Return a serializable snapshot of the current lifecycle state."""
    if not scheduler:
        return {"state": "idle"}
    return scheduler.get_lifecycle_status()

async def _broadcast_lifecycle():
    """Push current lifecycle state to all WebSocket clients."""
    await _broadcast_ws({"type": "update", "lifecycle": _get_lifecycle_snapshot()})


async def _websocket_handler(request: web.Request) -> web.WebSocketResponse:
    """WebSocket endpoint — pushes VRAM + queue state every second."""
    global _vram_cache, _ws_clients
    ws = web.WebSocketResponse()
    await ws.prepare(request)
    if not await ws_enforce_first_frame_auth(ws):
        return ws
    _ws_clients.add(ws)
    logger.info(f"WebSocket client connected ({len(_ws_clients)} total)")

    try:
        # Send initial full state
        # ── Phase 1: build OOM section once for both initial + refresh payloads ──
        _gpu_states_map = globals().get("_gpu_states", {})
        # Phase 4: heartbeat age comes from _last_oom_heartbeat_ts, which is
        # updated by _oom_recovery_watchdog_loop on every poll. We compute
        # the age here so /health can surface "watchdog fresh?" without
        # importing extra modules.
        _watchdog_heartbeat_ts = float(
            globals().get("_last_oom_heartbeat_ts", 0.0) or 0.0
        )
        _now_ts = time.time()
        _oom_section = _oom_health_section(
            gpu_states_map=_gpu_states_map,
            events_last_hour=[],
            watchdog_heartbeat_ts=_watchdog_heartbeat_ts,
            now=_now_ts,
        )
        _full_state = {
            "type": "full_state",
            "vram": _vram_cache,
            "queue": scheduler.get_queue_status() if scheduler else {},
            "gpu_state": vram.gpu_state.value if vram else "unknown",
            "services": _services_config,
            "service_health": _service_health_cache or await _check_all_services_health(),
            "lifecycle": scheduler.get_lifecycle_status() if scheduler else {"state": "idle"},
            "gpu_states": {gid: gs.to_dict() for gid, gs in _gpu_states.items()},
            "bundles": _resolve_bundles(),
            "nginx_status": _nginx_status_cache,
            "oom": _oom_section,
        }
        _apply_runtime_semantics(_full_state)
        await ws.send_json(_full_state)

        async for msg in ws:
            if msg.type == web.WSMsgType.TEXT:
                data = json.loads(msg.data)
                # Client can request immediate refresh
                if data.get("action") == "refresh":
                    vram_data = await _poll_vram()
                    _vram_cache = vram_data
                    # Rebuild OOM section on refresh so event counts update in real-time
                    _gpu_states_map = globals().get("_gpu_states", {})
                    # Phase 4: same heartbeat fields as initial payload.
                    _watchdog_heartbeat_ts = float(
                        globals().get("_last_oom_heartbeat_ts", 0.0) or 0.0
                    )
                    _now_ts = time.time()
                    _oom_section = _oom_health_section(
                        gpu_states_map=_gpu_states_map,
                        events_last_hour=[],
                        watchdog_heartbeat_ts=_watchdog_heartbeat_ts,
                        now=_now_ts,
                    )
                    _full_state = {
                        "type": "full_state",
                        "vram": vram_data,
                        "queue": scheduler.get_queue_status() if scheduler else {},
                        "gpu_state": vram.gpu_state.value if vram else "unknown",
                        "services": _services_config,
                        "service_health": _service_health_cache or await _check_all_services_health(),
                        "lifecycle": scheduler.get_lifecycle_status() if scheduler else {"state": "idle"},
                        "nginx_status": _nginx_status_cache,
                        "oom": _oom_section,
                    }
                    _apply_runtime_semantics(_full_state)
                    await ws.send_json(_full_state)
            elif msg.type == web.WSMsgType.ERROR:
                logger.error(f"WebSocket error: {ws.exception()}")
    except Exception as e:
        logger.warning(f"WebSocket client error: {e}")
    finally:
        _ws_clients.discard(ws)
        logger.info(f"WebSocket client disconnected ({len(_ws_clients)} total)")

    return ws


# ── MCP Server (Model Context Protocol) ─────────────────────────────

_MCP_INITIALIZED = False
_MCP_TOOLS = None
_MCP_HTTP_SESSION: ClientSession | None = None  # For tools that call the main HTTP API


async def _mcp_http(
    method: str,
    path: str,
    body: dict = None,
    *,
    timeout_seconds: float | None = None,
) -> dict:
    """Call the configured authenticated GPU Manager HTTP API."""
    global _MCP_HTTP_SESSION
    owns_session = timeout_seconds is not None
    if owns_session:
        client = ClientSession(
            timeout=ClientTimeout(total=max(1.0, float(timeout_seconds)))
        )
    else:
        if _MCP_HTTP_SESSION is None or _MCP_HTTP_SESSION.closed:
            _MCP_HTTP_SESSION = ClientSession(timeout=ClientTimeout(total=30))
        client = _MCP_HTTP_SESSION
    base_url = os.environ.get(
        "GPU_MANAGER_API_URL"
    ) or os.environ.get("GPU_MANAGER_HTTP_URL", f"http://127.0.0.1:{LISTEN_PORT}")
    base_url = base_url.rstrip("/")
    url = f"{base_url}{path}"
    try:
        kwargs = {"headers": {"Content-Type": "application/json"}}
        token = _api_token()
        if token:
            kwargs["headers"]["Authorization"] = f"Bearer {token}"
        if body:
            kwargs["json"] = body
        async with client.request(method, url, **kwargs) as resp:
            result = await resp.json()
            result["_http_status"] = resp.status
            if resp.status in {401, 503}:
                result["_auth_error"] = (
                    "api_token_unconfigured" if not token else "api_auth_rejected"
                )
            return result
    except Exception as e:
        return {"error": f"HTTP API unreachable: {e}", "_http_status": 0}
    finally:
        if owns_session:
            await client.close()


def _mcp_supported_generation_types() -> list[str]:
    """Return the MCP generation-type enum from the live config.

    Include configured eligible templates and registry-owned aliases. The MCP process
    is a control-plane client; its advertised schema must not lag the HTTP
    manager's template registry.
    """
    supported = set()
    try:
        config = _load_services_config() or {}
        templates = config.get("generation_templates", {}) or {}
        services = config.get("services", {}) or {}
        supported.update(
            str(name)
            for name, template in templates.items()
            if (
                isinstance(template, dict)
                and template.get("backend")
                and service_is_publicly_eligible(template)
                and service_is_publicly_eligible(services.get(template.get("backend"), {}))
                and bool(services.get(template.get("backend")))
                and not is_retired_minimax_comfyui_template(template)
                and not str(template.get("backend") or "").startswith("acestep")
                and not str(name).startswith("music-acestep")
            )
        )
        for service_name, service in services.items():
            if not isinstance(service, Mapping) or not service_is_publicly_eligible(service):
                continue
            if service_name in supported or _is_internal_workflow_service(service):
                supported.add(service_name)
                supported.update(alias for alias in service.get("aliases", [])
                                 if isinstance(alias, str))
    except Exception:
        # Missing registry is not evidence that a legacy route can execute.
        return []
    return sorted(supported)


