async def _mcp_preload_via_live_controller(arguments: dict) -> dict:
    """Delegate bundle preload to the canonical authenticated HTTP helper."""
    bundle_name = arguments.get("bundle_name")
    if not bundle_name:
        return {"ok": False, "preload_state": "invalid_request", "errors": ["bundle_name is required"]}
    result = await _mcp_http(
        "POST",
        "/v1/bundles/preload",
        arguments,
        timeout_seconds=float(arguments.get("wait_timeout", 120.0)) + 30.0,
    )
    if isinstance(result, dict):
        result.setdefault("bundle", bundle_name)
    return result


async def _mcp_call_tool(name: str, arguments: dict) -> dict:
    """Dispatch an MCP tool call to the appropriate handler."""
    # Lazily initialize scheduler and vram on first tool call
    global scheduler, vram, session, _services_config
    if scheduler is None:
        scheduler = GPUScheduler(session, logger)
    if vram is None:
        vram = VRAMLifecycleManager(session, logger)
    if _services_config is None or not _services_config.get("services"):
        _services_config = _load_services_config()

    if name == "poll_vram":
        result = await _poll_vram()
        return result

    elif name == "get_vulkan_tenants":
        min_mib = int(arguments.get("min_mib", 64))
        scan = await asyncio.get_event_loop().run_in_executor(
            None, _scan_render_node_fdinfo_cached
        )
        config_vt = _load_services_config()
        gpu_devices_vt = config_vt.get("gpu_devices", {}) or {}
        rn_to_gpu = _build_render_node_to_gpu_map_cached(gpu_devices_vt)
        result = {}
        for pid, rn_data in scan.items():
            for rn, info in rn_data.items():
                gid = rn_to_gpu.get(rn)
                if not gid:
                    continue
                drm_vm_mib = info["drm_vm_bytes"] // (1024 * 1024)
                if drm_vm_mib < min_mib:
                    continue
                result.setdefault(gid, []).append({
                    "pid": pid,
                    "name": _read_proc_name(pid) or f"pid={pid}",
                    "render_node": rn,
                    "drm_vm_mib": drm_vm_mib,
                    "amdgpu_vram_mib": info["amdgpu_vram_bytes"] // (1024 * 1024),
                    "fd_count": info["fd_count"],
                    "category": (
                        "vulkan"
                        if info["drm_vm_bytes"] > info["amdgpu_vram_bytes"]
                        else "rocm-gem"
                    ),
                })
        return {"vulkan_tenants": result, "scan_min_mib": min_mib}

    elif name == "preload_bundle":
        return await _mcp_preload_via_live_controller(arguments)

    elif name == "evict_llm":
        success = await _evict_llm_unless_protected_busy(vram, reason="mcp_tool")
        return {"success": success, "evicted": vram._llm_evicted}

    elif name == "restore_llm":
        success = await vram.restore_llm(reason="mcp_tool")
        return {"success": success, "llm_running": not vram._llm_evicted}

    elif name == "stop_comfyui":
        success = await vram.stop_comfyui(reason="mcp_tool")
        return {"success": success, "comfyui_stopped": vram._comfyui_stopped}

    elif name == "start_comfyui":
        return await _start_comfyui_via_controller()

    elif name == "comfyui_unload_models":
        # Call POST /free on the running ComfyUI to unload all models
        # but keep the process alive. Use this when GPU Manager needs the
        # VRAM back temporarily (e.g., to load an LLM).
        try:
            import aiohttp
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    f"http://127.0.0.1:8188/free",
                    json={"unload_models": True, "free_memory": True},
                    timeout=ClientTimeout(total=30),
                ) as resp:
                    status = resp.status
                    body = await resp.text()
                    return {
                        "success": status == 200,
                        "status": status,
                        "body": body,
                        "note": "unload is async; takes effect at next prompt boundary",
                    }
        except Exception as e:
            return {"success": False, "error": str(e)}

    elif name == "comfyui_interrupt":
        # Call POST /interrupt on the running ComfyUI to cancel the
        # currently-executing prompt.
        try:
            import aiohttp
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    "http://127.0.0.1:8188/interrupt",
                    json={},
                    timeout=ClientTimeout(total=10),
                ) as resp:
                    return {
                        "success": resp.status == 200,
                        "status": resp.status,
                    }
        except Exception as e:
            return {"success": False, "error": str(e)}

    elif name == "comfyui_install_node":
        # Install a ComfyUI custom node via ComfyUI-Manager API.
        # Arguments:
        #   node_id: string, the node id (e.g. "ComfyUI-GGUF")
        node_id = arguments.get("node_id", "")
        if not node_id:
            return {"success": False, "error": "node_id is required"}
        try:
            import aiohttp
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    f"http://127.0.0.1:8188/manager/customnode/install",
                    json={"node_id": node_id},
                    timeout=ClientTimeout(total=300),
                ) as resp:
                    return {
                        "success": resp.status == 200,
                        "status": resp.status,
                        "node_id": node_id,
                    }
        except Exception as e:
            return {"success": False, "error": str(e)}

    elif name == "comfyui_update_all_nodes":
        # Trigger ComfyUI-Manager to update all installed custom nodes.
        try:
            import aiohttp
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    "http://127.0.0.1:8188/manager/queue/update_all",
                    json={},
                    timeout=ClientTimeout(total=10),
                ) as resp:
                    return {
                        "success": resp.status == 200,
                        "status": resp.status,
                        "note": "update runs in background; check /manager/queue/status for progress",
                    }
        except Exception as e:
            return {"success": False, "error": str(e)}

    elif name == "comfyui_list_models":
        # List models ComfyUI can see. Calls /models endpoint.
        try:
            import aiohttp
            async with aiohttp.ClientSession() as session:
                async with session.get(
                    "http://127.0.0.1:8188/models",
                    timeout=ClientTimeout(total=10),
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        # The /models endpoint returns a dict like {"checkpoints": [...], "vae": [...], etc}
                        # Add metadata about how many models are in each category
                        summary = {}
                        for category, models in data.items():
                            if isinstance(models, list):
                                summary[category] = {
                                    "count": len(models),
                                    "items": models[:20],  # First 20 to avoid huge responses
                                }
                            else:
                                summary[category] = models
                        return {
                            "success": True,
                            "models": summary,
                        }
                    return {
                        "success": False,
                        "status": resp.status,
                        "note": "ComfyUI may not be running or endpoint may differ in v0.25.0",
                    }
        except Exception as e:
            return {"success": False, "error": str(e)}

    elif name == "comfyui_set_vram_mode":
        # Change the VRAM mode for the comfyui service. Requires a restart
        # to take effect (ComfyUI sets vram_state at startup).
        # Arguments:
        #   mode: one of "highvram", "normalvram" (default), "lowvram", "novram", "disabled"
        #   restart: bool, whether to restart the service after the change (default True)
        valid_modes = ["highvram", "normalvram", "lowvram", "novram", "disabled"]
        mode = arguments.get("mode", "").lower()
        if mode not in valid_modes:
            return {
                "success": False,
                "error": f"invalid mode '{mode}', must be one of {valid_modes}",
            }
        do_restart = arguments.get("restart", True)
        try:
            # Use systemctl set-environment to change the env var
            proc = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", "set-environment",
                f"COMFYUI_VRAM_MODE={mode}",
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await proc.communicate()
            result = {
                "success": proc.returncode == 0,
                "mode": mode,
                "setenv_stdout": stdout.decode() if stdout else "",
                "setenv_stderr": stderr.decode() if stderr else "",
            }
            if do_restart and proc.returncode == 0:
                # Restart the service
                proc2 = await asyncio.create_subprocess_exec(
                    "sudo", "systemctl", "restart", "comfyui.service",
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                stdout2, stderr2 = await proc2.communicate()
                result["restart_triggered"] = True
                result["restart_returncode"] = proc2.returncode
                result["restart_stderr"] = stderr2.decode() if stderr2 else ""
                # Give it a moment to come up
                await asyncio.sleep(3)
                # Check it's back
                proc3 = await asyncio.create_subprocess_exec(
                    "systemctl", "is-active", "comfyui.service",
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                stdout3, _ = await proc3.communicate()
                result["is_active"] = stdout3.decode().strip() if stdout3 else ""
            return result
        except Exception as e:
            return {"success": False, "error": str(e)}

    elif name == "list_queue":
        # MCP runs in its own process. Its local scheduler object can be stale
        # after gpu-manager.service restarts, so read the authoritative state
        # from the running HTTP API instead of this MCP process.
        health = await _mcp_http("GET", "/health")
        return health.get("scheduler", {})

    elif name == "cancel_job":
        job_id = arguments.get("job_id")
        if not job_id:
            return {"error": "job_id is required"}
        # Find job in queues and cancel via scheduler
        for queue_name in ["_comfyui_queue", "_acestep_queue"]:
            queue = getattr(scheduler, queue_name, [])
            for job in list(queue):
                if job.id == job_id:
                    try:
                        await scheduler.cancel(job_id)
                    except Exception as e:
                        return {"error": f"Cancel failed: {e}"}
                    return {"success": True, "job_id": job_id, "cancelled": True}
        return {"error": f"Job {job_id} not found", "job_id": job_id}

    elif name == "start_bundle":
        bundle_name = arguments.get("bundle_name")
        if not bundle_name:
            return {"error": "bundle_name is required"}
        bundles = _resolve_bundles()
        if bundle_name not in bundles:
            return {"error": f"Unknown bundle '{bundle_name}'", "available": list(bundles.keys())}
        _sb_transition_lease = None
        _sb_resource_lease = None
        if bundle_lifecycle_controller is not None:
            try:
                _sb_attempt = await bundle_lifecycle_controller.begin_transition(
                    bundle_name,
                    desired_state=BundleDesiredState.RUNNING,
                    reason="operator:start_bundle",
                )
            except Exception as exc:
                logger.error(
                    "bundle lifecycle admission unavailable for start_bundle %s: %s",
                    bundle_name,
                    exc,
                    exc_info=True,
                )
                return {
                    "success": False,
                    "bundle": bundle_name,
                    "healthy": False,
                    "error": "bundle_lifecycle_unavailable",
                }
            if not _sb_attempt.acquired or _sb_attempt.lease is None:
                return {
                    "success": False,
                    "bundle": bundle_name,
                    "healthy": False,
                    "error": "bundle_transition_in_progress",
                    "reason": _sb_attempt.reason,
                }
            _sb_transition_lease = _sb_attempt.lease
            _sb_resource_lease, _sb_resource_guard_enabled = await _acquire_bundle_resource_lease(
                bundle_lifecycle_controller,
                _bundle_resource_ids(bundle_name, bundles=bundles),
                reason="operator:start_bundle",
            )
            if _sb_resource_guard_enabled and _sb_resource_lease is None:
                try:
                    await bundle_lifecycle_controller.finish_transition(
                        _sb_transition_lease,
                        success=False,
                        reason="operator:start_bundle",
                        error="resource admission unavailable",
                    )
                except Exception:
                    logger.error(
                        "failed to persist start_bundle resource refusal for %s",
                        bundle_name,
                        exc_info=True,
                    )
                return {
                    "success": False,
                    "bundle": bundle_name,
                    "healthy": False,
                    "error": "resource_admission_unavailable",
                }
        _sb_transition_success = False
        _sb_transition_error = None
        _sb_bundle = bundles.get(bundle_name, {})
        _sb_gpu_id = _sb_bundle.get("gpu_id")
        _sb_gs = _get_gpu_state(_sb_gpu_id) if _sb_gpu_id else None
        _sb_component = _linked_bundle_unload_order(bundle_name, bundles)
        _sb_preexisting: set[str] = set()
        for _sb_name in _sb_component:
            _sb_cfg = bundles.get(_sb_name, {}) or {}
            _sb_member_gpu = _sb_cfg.get("gpu_id")
            _sb_member_state = _get_gpu_state(_sb_member_gpu) if _sb_member_gpu else None
            if _sb_member_state is not None and (
                _sb_name in _sb_member_state.loaded_bundles
                or _sb_member_state.loaded_bundle == _sb_name
            ):
                _sb_preexisting.add(_sb_name)
        if _sb_gs is not None:
            _sb_gs.state = "loading"
        # Phase 0: route through setter (single source of truth).
        if _sb_gs is not None and scheduler is not None and _sb_gpu_id in getattr(scheduler, "_gpu_state", {}):
            _sb_gs.set_loading(True, source="_start_bundle")
        try:
            load_ok = await _load_bundle(bundle_name)
            health = await _get_bundle_health(bundle_name) if load_ok else {
                "ok": False,
                "primary_healthy": False,
                "linked_healthy": "none",
                "services": {},
                "errors": [f"bundle '{bundle_name}' failed to load"],
            }
            health_ok = bool(health.get("ok"))
            rollback = None
            if not (load_ok and health_ok):
                rollback = await _rollback_bundle_graph(
                    bundle_name,
                    bundles=bundles,
                    preserve=_sb_preexisting,
                )
            if _sb_gs is not None:
                _sb_gs.state = "loaded" if load_ok and health_ok else (
                    "idle" if not _sb_gs.loaded_bundles else "loaded"
                )
            if not (load_ok and health_ok):
                errors = list(health.get("errors", [])) or [
                    f"start_bundle failed for '{bundle_name}'"
                ]
                if rollback and rollback.get("errors"):
                    errors.extend(rollback["errors"])
                return {
                    "success": False,
                    "bundle": bundle_name,
                    "healthy": False,
                    "ok": False,
                    "primary_healthy": bool(health.get("primary_healthy")),
                    "linked_healthy": health.get("linked_healthy"),
                    "services": health.get("services", {}),
                    "errors": errors,
                    "rollback": rollback,
                }
            _sb_transition_success = True
            return {
                "success": True,
                "bundle": bundle_name,
                "healthy": True,
                "ok": True,
                "primary_healthy": health["primary_healthy"],
                "linked_healthy": health["linked_healthy"],
                "services": health["services"],
                "errors": health["errors"],
            }
        except Exception as e:
            _sb_transition_error = f"{type(e).__name__}: {e}"
            rollback = await _rollback_bundle_graph(
                bundle_name,
                bundles=bundles,
                preserve=_sb_preexisting,
            )
            errors = [f"start_bundle failed: {e}"]
            errors.extend(rollback.get("errors", []))
            return {
                "success": False,
                "bundle": bundle_name,
                "healthy": False,
                "ok": False,
                "errors": errors,
                "rollback": rollback,
            }
        finally:
            if _sb_resource_lease is not None and bundle_lifecycle_controller is not None:
                await _release_bundle_resource_lease(
                    bundle_lifecycle_controller,
                    _sb_resource_lease,
                    reason="operator:start_bundle",
                )
            if _sb_transition_lease is not None and bundle_lifecycle_controller is not None:
                try:
                    persisted = await bundle_lifecycle_controller.finish_transition(
                        _sb_transition_lease,
                        success=_sb_transition_success,
                        reason="operator:start_bundle",
                        error=_sb_transition_error
                        or (None if _sb_transition_success else "start_bundle returned unhealthy"),
                    )
                    if not persisted:
                        logger.error(
                            "start_bundle lifecycle fence was lost for %s",
                            bundle_name,
                        )
                except Exception:
                    logger.error(
                        "failed to persist start_bundle lifecycle result for %s",
                        bundle_name,
                        exc_info=True,
                    )
            # Cleanup only: authoritative ownership is committed on the
            # success path above, not here. This finalizer just clears the
            # loading flag so a failure cannot leave the GPU stuck.
            if _sb_gs is not None and scheduler is not None and _sb_gpu_id in getattr(scheduler, "_gpu_state", {}):
                _sb_gs.set_loading(False, source="_start_bundle")

    elif name == "submit_generation":
        gen_type = arguments.get("type")
        params = arguments.get("params", {})
        if not gen_type:
            return {"error": "type is required"}

        # Resolve the gen_type's template + backend BEFORE the queue_engine guard
        # so the legacy comfyui/acestep paths can still submit jobs even when
        # the new Redis-stream queue engine is unavailable.
        config = _load_services_config() or {}
        templates = (config.get("generation_templates", {}) or {})
        tmpl = templates.get(gen_type, {}) or {}
        backend = tmpl.get("backend", gen_type)

        # BLOCKER 1 fix: comfyui-without-workflow-template (image-edit, video,
        # ltx-video, tts) falls back to the in-memory scheduler.submit_comfyui()
        # path using the legacy _build_workflow, exactly like the pre-PR code at
        # backup line 11539. Only the new "image" type (which has a
        # workflow_template field) goes through the Redis-stream comfyui path.
        if backend == "comfyui" and not tmpl.get("workflow_template"):
            if _queue_owner_mode() == 'durable':
                # MCP is a control-plane client. Reuse the manager's durable
                # compatibility endpoint so it cannot build a second local
                # scheduler/queue authority. The HTTP route normalizes the
                # legacy image/image-edit body into the canonical submit path.
                response = await _mcp_http(
                    "POST",
                    f"/generate/{gen_type}",
                    {
                        "params": params,
                        "priority": int(arguments.get("priority", 50)),
                        "callback_url": arguments.get("callback_url"),
                        "metadata": arguments.get("metadata") or {},
                    },
                )
                if response.get("_http_status", 0) not in (200, 201, 202):
                    return {
                        "error": response.get("error", "generation submit failed"),
                        **response,
                    }
                return {"submitted": True, **response}
            try:
                data = dict(params)
                data["type"] = gen_type
                workflow = _build_workflow(gen_type, data)
            except (ValueError, FileNotFoundError) as e:
                return {"error": str(e)}
            callback_url = arguments.get("callback_url")
            priority = int(arguments.get("priority", 5))
            metadata = arguments.get("metadata") or {}
            try:
                job = scheduler.submit_comfyui(workflow, callback_url, priority, metadata)
            except Exception as e:
                return {"error": f"submit_comfyui failed: {e}"}
            return {
                "submitted": True,
                "type": gen_type,
                "job_id": job.id,
                "queue": "comfyui",
            }

        # ACE-Step is retained only for historical job/status handling.
        if str(backend).startswith("acestep"):
            return {
                "error": "ACE-Step generation is retired",
                "reason": "acestep_retired",
                "replacement": "minimax-music3-full",
                "_http_status": 410,
            }

        # Template-backed work must use the main HTTP scheduler. The MCP process
        # is a separate control-plane client and must not make local admission
        # or bundle decisions: otherwise its queue-engine state can disagree
        # with the running manager after startup/reload.
        if tmpl.get("workflow_template"):
            response = await _mcp_http("POST", "/v1/submit/generation", {
                "type": gen_type,
                "params": params,
                "priority": int(arguments.get("priority", 50)),
                "callback_url": arguments.get("callback_url"),
                "metadata": arguments.get("metadata") or {},
            })
            if response.get("_http_status", 0) not in (200, 202):
                return {"error": response.get("error", "generation submit failed"), **response}
            return {"submitted": True, **response}

        # Rest of the existing path for sd-server and any other backend handled
        # locally by _build_generation_entry.
        if _queue_owner_mode() == 'legacy':
            return {
                "error": "queue_owner_route_fenced",
                "reason": "queue_owner_cutover_required",
                "configured_owner": "legacy",
                "route_owner": "durable",
                "route": "mcp.submit_generation",
                "_http_status": 503,
            }
        if not queue_engine:
            return {"error": "Queue engine not available"}

        # Dispatch via _build_generation_entry, which now handles
        # backend="comfyui" by emitting a comfyui_workflow entry. The old
        # if/elif on backend name is gone — backend specifics are entirely
        # inside services.json::generation_templates and _build_generation_entry.
        entry, err = await _build_generation_entry(
            gen_type=gen_type,
            params=params,
            priority=int(arguments.get("priority", 50)),
            callback_url=arguments.get("callback_url"),
            metadata=arguments.get("metadata") or {},
        )
        if err is not None:
            return {"error": err["error"]}
        # _build_generation_entry returns (dict, None) on success and
        # (None, dict) on failure. After `if err is not None: return`, the
        # only remaining state is (dict, None) — re-bind so Pyright can narrow.
        if entry is None:
            return {"error": "internal: entry missing after err=None"}

        # Bundle-load precheck (mirrors handle_submit_generation). Only
        # blocks the enqueue if the matched template declares a `bundle`
        # and that bundle can't come up — fail-fast is better than a
        # stranded job in the stream.
        bundle_name = tmpl.get("bundle")
        # Use the effective scheduler setting, including GPU_MANAGER_SCHEDULER_OWNS_LOAD.
        # Reading only services.json here can make ingress synchronously load a
        # bundle even though the live scheduler owns loading, delaying the 202
        # acknowledgement long enough for a client timeout to orphan the request.
        # The MCP compatibility client must use the same lifecycle ownership
        # rule as the HTTP generation route. Durable mode delegates bundle
        # transitions to WorkerPool; split/legacy retain their configured
        # behavior.
        scheduler_owns_load = (
            _queue_owner_mode() == "durable"
            or bool(_phase3_scheduling_config().get("scheduler_owns_load", False))
        )
        if scheduler_owns_load:
            logger.info("handle_generate: enqueue accepted without handler pre-load")
        if bundle_name and not scheduler_owns_load:
            try:
                ok = await _evict_then_load_bundle(bundle_name, reason="mcp_submit_generation")
            except Exception as e:
                logger.error(
                    "submit_generation: bundle load raised for %s: %s",
                    bundle_name, e,
                )
                return {"error": f"Bundle load failed: {e}"}
            if not ok:
                return {"error": f"Bundle '{bundle_name}' failed to load"}

        # Enqueue onto the per-routing_group Redis stream.
        loop = asyncio.get_event_loop()
        routing_group = entry["routing_group"]
        service_name = entry.get("service_name") or routing_group
        try:
            entry_id = await loop.run_in_executor(
                None, queue_engine.enqueue, service_name, entry, routing_group,
            )
        except Exception as e:
            logger.error("submit_generation: redis enqueue failed: %s", e)
            return {"error": f"redis enqueue failed: {e}"}
        if not entry_id:
            return {"error": "Failed to enqueue (redis stream error)"}

        # Queue depth for client-side backpressure hint (XLEN-style).
        try:
            position = await loop.run_in_executor(
                None, queue_engine.get_queue_depth, service_name, routing_group,
            )
        except Exception:
            position = None

        return {
            "submitted": True,
            "job_id": entry["job_id"],
            "entry_id": entry_id,
            "type": gen_type,
            "routing_group": routing_group,
            "status": "queued",
            "position": position,
        }

    elif name == "list_services":
        # Always fetch fresh state from the running HTTP API instead of cached config
        try:
            return await _mcp_http("GET", "/services")
        except Exception:
            return _services_config

    elif name == "get_service_catalog":
        from urllib.parse import quote

        public_id = arguments.get("public_id") or None
        path = "/v1/catalog" + (f"/{quote(str(public_id), safe='')}" if public_id else "")
        result = await _mcp_http("GET", path)
        if result.get("_http_status") in {200, 404}:
            result.pop("_http_status", None)
            return result
        # The stdio MCP process has no embedded broker: serve the static projection.
        catalog = _build_service_catalog(_load_services_config(), None, _cliproxy_max_input_chars())
        return _service_catalog_response(catalog, public_id)[1]

    elif name == "restart_service":
        svc_name = arguments.get("service_name")
        if not svc_name:
            return {"error": "service_name is required"}
        svc = _services_config.get("services", {}).get(svc_name, {})
        unit = svc.get("systemd_unit")
        if not unit:
            return {"error": f"No systemd_unit configured for service {svc_name}"}
        try:
            proc = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", "restart", unit,
                stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
            if proc.returncode == 0:
                return {"success": True, "service": svc_name, "unit": unit}
            else:
                return {"error": f"Failed to restart {svc_name}: {stderr.decode().strip()}"}
        except asyncio.TimeoutError:
            return {"error": f"Timeout restarting {svc_name}"}
        except Exception as e:
            return {"error": f"Exception restarting {svc_name}: {e}"}

    elif name == "get_health":
        # MCP runs in its own process. Its local llm/scheduler objects can be
        # stale after gpu-manager.service restarts. Return the authoritative
        # health document from the live HTTP service.
        return await _mcp_http("GET", "/health")

    # ── Service management tools (via HTTP API to main process) ──

    elif name == "update_service":
        svc_name = arguments.get("service_name")
        changes = arguments.get("changes", {})
        # MCP clients occasionally serialize the nested `changes` object as a
        # JSON-encoded string instead of an embedded object.  Defensively
        # decode so the dict form reaches the HTTP handler intact; if the
        # payload really is empty/missing, surface the original error.
        if isinstance(changes, str):
            try:
                changes = json.loads(changes)
            except (TypeError, ValueError):
                return {"error": "service_name and changes are required"}
        if not isinstance(changes, dict) or not svc_name or not changes:
            return {"error": "service_name and changes are required"}
        return await _mcp_http("PUT", f"/services/{svc_name}", changes)

    elif name == "toggle_service":
        svc_name = arguments.get("service_name")
        if not svc_name:
            return {"error": "service_name is required"}
        return await _mcp_http("POST", f"/services/{svc_name}/toggle")

    elif name == "fix_degraded_service":
        svc_name = arguments.get("service_name")
        if not svc_name:
            return {"error": "service_name is required"}
        return await _mcp_http("POST", f"/services/{svc_name}/fix-degraded")

    elif name == "list_port_proxies":
        return await _mcp_http("GET", "/port-proxies")

    elif name == "manage_port_proxy":
        svc_name = arguments.get("service_name")
        action = arguments.get("action")
        if not svc_name or not action:
            return {"error": "service_name and action are required"}
        if action not in ("start", "stop"):
            return {"error": "action must be 'start' or 'stop'"}
        return await _mcp_http("POST", f"/port-proxies/{svc_name}/{action}")

    elif name == "set_idle_service":
        svc_name = arguments.get("service_name", "")
        gpu_id = arguments.get("gpu_id")
        payload = {"idle_service": svc_name}
        if gpu_id:
            payload["gpu_id"] = gpu_id
        return await _mcp_http("PUT", "/scheduling/idle-service", payload)

    elif name == "pin_service":
        svc_name = arguments.get("service_name", "")
        if not svc_name:
            return await _mcp_http("POST", "/scheduling/pin", {"service": None})
        return await _mcp_http("POST", "/scheduling/pin", {"service": svc_name})

    elif name == "set_maintenance":
        enabled = arguments.get("enabled", True)
        action = "enable" if enabled else "disable"
        return await _mcp_http("POST", f"/maintenance/{action}")

    # ── Queue management tools (via HTTP API to main process) ──

    elif name == "move_job":
        job_id = arguments.get("job_id")
        action = arguments.get("action")
        if not job_id or not action:
            return {"error": "job_id and action are required"}
        if action == "bump":
            return await _mcp_http("POST", f"/queue/bump/{job_id}")
        elif action == "demote":
            return await _mcp_http("POST", f"/queue/demote/{job_id}")
        elif action == "move_top":
            # Move to position 0 via queue/move endpoint
            return await _mcp_http("POST", "/queue/move", {"job_id": job_id, "position": 0})
        elif action == "move_bottom":
            # Get queue length first, then move to end
            queue = await _mcp_http("GET", "/queue/detail")
            if "error" not in queue:
                queued = queue.get("queued_detail", [])
                bottom = max(0, len(queued) - 1)
                return await _mcp_http("POST", "/queue/move", {"job_id": job_id, "position": bottom})
            return queue
        else:
            return {"error": f"Unknown action: {action}"}

    elif name == "clear_queue":
        backend = arguments.get("backend", "all")
        return await _mcp_http("POST", "/queue/clear", {"backend": None if backend == "all" else backend})

    # ── Phase 5: OOM recovery tool surface ──────────────────────────
    # All returns include schema_version: 1 per adversarial #20.
    elif name == "oom_history":
        gpu_id = arguments.get("gpu_id")
        since = arguments.get("since")
        limit = min(int(arguments.get("limit", OOM_HISTORY_DEFAULT_LIMIT)), OOM_HISTORY_MAX_LIMIT)
        # Filter the whole bounded ring first; applying the limit before the
        # gpu_id/since filters would drop matching history behind other GPUs.
        events = _recent_oom_events(limit=OOM_HISTORY_MAX_LIMIT)
        if gpu_id:
            events = [e for e in events if e.get("gpu_id") == gpu_id]
        if since:
            events = [e for e in events if e.get("ts", 0) >= since]
        return {
            "schema_version": 1,
            "events": events[-limit:] if limit > 0 else [],
            "count": len(events),
            "filter": {"gpu_id": gpu_id, "since": since, "limit": limit},
        }

    elif name == "oom_recovery_status":
        # The MCP process can outlive gpu-manager.service. Query the running
        # manager so per-GPU state and watchdog timestamps cannot be stale.
        gpu_id = arguments.get("gpu_id")
        suffix = f"?gpu_id={gpu_id}" if gpu_id else ""
        return await _mcp_http("GET", f"/oom/recovery/status{suffix}")

    elif name == "oom_recovery_force_reset":
        gpu_id = arguments.get("gpu_id")
        reason = arguments.get("reason", "")
        if not gpu_id:
            return {"schema_version": 1, "ok": False, "error": "gpu_id required"}
        allowed, retry_after = _check_force_reset_rate_limit(gpu_id)
        if not allowed:
            return {
                "schema_version": 1,
                "ok": False,
                "throttled": True,
                "retry_after_s": retry_after,
            }
        bs = _gpu_states.get(gpu_id)
        if bs is None:
            return {"schema_version": 1, "ok": False, "error": f"unknown gpu_id: {gpu_id}"}
        old_state = bs.oom_state
        bs.set_oom_state("idle", source=f"oom_recovery_force_reset (reason={reason})")
        _oom_force_reset_last_call_ts[gpu_id] = time.time()
        _oom_recovery_in_progress.pop(gpu_id, None)
        logger.warning(f"[oom-recovery] Force reset on {gpu_id}: {old_state} -> idle (reason={reason})")
        return {
            "schema_version": 1,
            "ok": True,
            "gpu_id": gpu_id,
            "old_state": old_state,
            "new_state": "idle",
            "reason": reason,
        }

    elif name in ("requeue_oom_jobs", "classify_oom_retry", "retry_oom_job"):
        dead_letters = await _get_dead_letters(limit=1000)
        by_id = {
            str(item.get("job_id")): item
            for item in dead_letters
            if item.get("job_id")
        }

        if name == "retry_oom_job":
            requested_ids = [str(arguments.get("job_id", "")).strip()]
            dry_run = False
        else:
            raw_ids = arguments.get("job_ids")
            if name == "requeue_oom_jobs" and raw_ids is None:
                preview = await _oom_retry_check_redis_state(dead_letters)
                return {
                    "schema_version": 2,
                    "outcome": "default_all_rejected",
                    "dry_run": True,
                    "classifications": preview,
                    "archive_immutable": True,
                }
            requested_ids = (
                [str(value).strip() for value in raw_ids if str(value).strip()]
                if isinstance(raw_ids, list)
                else list(by_id)
            )
            dry_run = name == "classify_oom_retry" or arguments.get("dry_run", True) is not False

        selected = [by_id[job_id] for job_id in dict.fromkeys(requested_ids) if job_id in by_id]
        classified = await _oom_retry_check_redis_state(selected)
        missing = [job_id for job_id in dict.fromkeys(requested_ids) if job_id not in by_id]
        if dry_run:
            return {
                "schema_version": 2,
                "outcome": "classified",
                "dry_run": True,
                "classifications": classified,
                "missing_job_ids": missing,
                "archive_immutable": True,
            }

        idempotency_key = str(arguments.get("idempotency_key", "")).strip()
        if not idempotency_key:
            return {
                "schema_version": 2,
                "outcome": "refused",
                "reason": "missing_idempotency_key",
                "classifications": classified,
                "missing_job_ids": missing,
                "archive_immutable": True,
            }

        results = []
        for item in classified:
            if item.get("classification") != _OOM_RETRY_CLASS_ELIGIBLE:
                results.append({
                    "outcome": "refused",
                    "orig_job_id": item.get("job_id"),
                    "reason": item.get("classification"),
                })
                continue
            refs_raw = item.get("tracker_artifact_refs") or ""
            try:
                refs = json.loads(refs_raw) if refs_raw else []
            except (TypeError, ValueError, json.JSONDecodeError):
                refs = []
            if not isinstance(refs, list):
                refs = [str(refs)]
            results.append(await _atomic_retry_oom_job(
                item,
                actor=str(arguments.get("actor", "mcp")),
                reason=str(arguments.get("reason", "operator_requested")),
                idempotency_key=f"{idempotency_key}:{item.get('job_id')}",
                payload_hash=item.get("tracker_payload_hash"),
                artifact_refs=refs,
                service_name=item.get("tracker_service_name"),
                routing_group=item.get("tracker_routing_group"),
            ))
        return {
            "schema_version": 2,
            "outcome": "processed",
            "dry_run": False,
            "results": results,
            "missing_job_ids": missing,
            "archive_immutable": True,
        }

    else:
        return {"error": f"Unknown tool: {name}"}


async def _check_all_services_health() -> dict:
    """Check health of all configured services via systemctl + TCP connect.

    All services are checked concurrently for speed (vs sequential ~14s worst case).
    """
    global _services_config
    if _services_config is None or not _services_config.get("services"):
        _services_config = _load_services_config()

    services = _services_config.get("services", {})
    service_names = list(services.keys())

    async def _check_single(name: str, svc: dict) -> tuple[str, dict]:
        """Check one service's health (systemctl + TCP).

        Phase 6 fix: when the service is "gpu-manager" itself, skip the
        systemctl check. We are the calling process — the systemd status of
        gpu-manager.service is unreliable here (potential chicken-and-egg
        when invoked from inside the unit), and port 8091 being reachable
        is sufficient proof we are running. Without this special case
        gpu-manager.overall was reported as "degraded" forever.
        """
        unit = svc.get("systemd_unit")
        port = svc.get("port")
        svc_health = {"systemd_active": False, "port_open": False, "overall": "down",
                      "intentionally_idle": False}

        if name == "gpu-manager":
            # Self-check: we are gpu-manager. Port_open is sufficient evidence.
            svc_health["systemd_active"] = True
        elif unit:
            try:
                proc = await asyncio.create_subprocess_exec(
                    "systemctl", "is-active", "--quiet", unit,
                    stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL,
                )
                await asyncio.wait_for(proc.wait(), timeout=3)
                svc_health["systemd_active"] = proc.returncode == 0
            except Exception:
                pass

        if port:
            try:
                reader, writer = await asyncio.wait_for(
                    asyncio.open_connection("localhost", port),
                    timeout=2,
                )
                writer.close()
                await writer.wait_closed()
                svc_health["port_open"] = True
            except Exception:
                pass

        if svc_health["systemd_active"] and svc_health["port_open"]:
            svc_health["overall"] = "healthy"
        elif svc_health["port_open"]:
            svc_health["overall"] = "degraded"
        elif _is_intentionally_idle_service(name, svc):
            # Enabled but expected to be off (e.g. generation backends when idle).
            # Distinguishes from "down" so the dashboard doesn't page on them.
            svc_health["intentionally_idle"] = True
            svc_health["overall"] = "intentionally_idle"
        else:
            svc_health["overall"] = "down"

        return name, svc_health

    # Run all checks concurrently
    tasks = [_check_single(name, svc) for name, svc in services.items()]
    results = await asyncio.gather(*tasks, return_exceptions=True)

    health = {}
    for result in results:
        if isinstance(result, Exception):
            continue
        name, svc_health = result
        health[name] = svc_health
    return health


async def run_mcp_server():
    """Run the MCP stdio server. Reads JSON-RPC messages from stdin, writes to stdout."""
    global _MCP_TOOLS, _MCP_INITIALIZED
    _MCP_TOOLS = _build_mcp_tools()
    logger.info("MCP server started (stdio mode)")

    loop = asyncio.get_event_loop()
    reader = asyncio.StreamReader()
    protocol = asyncio.StreamReaderProtocol(reader)
    await loop.connect_read_pipe(lambda: protocol, sys.stdin)

    try:
        while True:
            line = await reader.readline()
            if not line:
                break
            line = line.decode("utf-8").strip()
            if not line:
                continue
            try:
                msg = json.loads(line)
            except json.JSONDecodeError:
                logger.warning(f"MCP: invalid JSON received: {line}")
                continue

            method = msg.get("method", "")
            msg_id = msg.get("id")
            params = msg.get("params", {})

            if method == "initialize":
                response = {
                    "jsonrpc": "2.0",
                    "id": msg_id,
                    "result": {
                        "protocolVersion": "2024-11-05",
                        "capabilities": {"tools": {}},
                        "serverInfo": {
                            "name": "gpu-manager-mcp",
                            "version": "1.0.0",
                        },
                    },
                }
                sys.stdout.write(json.dumps(response) + "\n")
                sys.stdout.flush()
                _MCP_INITIALIZED = True

            elif method == "notifications/initialized":
                pass

            elif method == "tools/list" and _MCP_INITIALIZED:
                response = {
                    "jsonrpc": "2.0",
                    "id": msg_id,
                    "result": _MCP_TOOLS,
                }
                sys.stdout.write(json.dumps(response) + "\n")
                sys.stdout.flush()

            elif method == "tools/call" and _MCP_INITIALIZED:
                tool_name = params.get("name", "")
                tool_args = params.get("arguments", {})
                try:
                    result = await _mcp_call_tool(tool_name, tool_args)
                    response = {
                        "jsonrpc": "2.0",
                        "id": msg_id,
                        "result": {
                            "content": [
                                {"type": "text", "text": json.dumps(result)}
                            ]
                        },
                    }
                except Exception as e:
                    logger.error(f"MCP tool {tool_name} error: {e}")
                    response = {
                        "jsonrpc": "2.0",
                        "id": msg_id,
                        "result": {
                            "content": [
                                {"type": "text", "text": json.dumps({"error": str(e)})}
                            ]
                        },
                    }
                sys.stdout.write(json.dumps(response) + "\n")
                sys.stdout.flush()

            elif method == "ping":
                response = {
                    "jsonrpc": "2.0",
                    "id": msg_id,
                    "result": {}
                }
                sys.stdout.write(json.dumps(response) + "\n")
                sys.stdout.flush()

            else:
                if not _MCP_INITIALIZED and method != "initialize":
                    response = {
                        "jsonrpc": "2.0",
                        "id": msg_id,
                        "error": {"code": -32000, "message": "Server not initialized"},
                    }
                else:
                    response = {
                        "jsonrpc": "2.0",
                        "id": msg_id,
                        "error": {"code": -32601, "message": "Method not found"},
                    }
                sys.stdout.write(json.dumps(response) + "\n")
                sys.stdout.flush()
    except asyncio.CancelledError:
        pass
    logger.info("MCP server stopped")


def _vram_loop_should_poll(ws_clients_present: bool, cache_present: bool,
                           idle_ticks: int, every: int | None = None) -> bool:
    """Decide whether the pusher loop refreshes VRAM on this tick."""
    if ws_clients_present or not cache_present:
        return True
    return idle_ticks >= (VRAM_IDLE_POLL_EVERY if every is None else every)


async def _vram_pusher_loop():
    """Background task: poll VRAM every second and push to WebSocket clients."""
    global _vram_cache, _queue_cache, _service_health_cache, _service_health_counter
    push_count = 0
    # Phase 0: state consistency poll counter. Runs verify_state_consistency()
    # every 6 polls (≈6s) so any direct write to scheduler._gpu_state that
    # bypassed GpuBundleState setters gets logged promptly.
    consistency_count = 0
    # The recovered secondary GPU PSP incident was correlated with telemetry immediately
    # after gpu-manager startup. Keep autonomous full-GPU probes out of the
    # process-wide startup window; explicit operator/API probes remain available.
    await asyncio.sleep(GPU_PROBE_STARTUP_GRACE_S)
    idle_ticks = VRAM_IDLE_POLL_EVERY
    while True:
        try:
            if _vram_loop_should_poll(bool(_ws_clients), bool(_vram_cache), idle_ticks):
                vram_data = await _poll_vram()
                idle_ticks = 1
            else:
                vram_data = _vram_cache
                idle_ticks += 1
            _vram_cache = vram_data
            queue_data = scheduler.get_queue_status() if scheduler else {}

            # Only push if there are connected clients
            if _ws_clients:
                push_count += 1
                broadcast = {
                    "type": "update",
                    "vram": vram_data,
                    "queue": queue_data,
                    "gpu_state": vram.gpu_state.value if vram else "unknown",
                    "lifecycle": scheduler.get_lifecycle_status() if scheduler else {"state": "idle"},
                    "timestamp": time.time(),
                    "gpu_states": {gid: gs.to_dict() for gid, gs in _gpu_states.items()},
                    "bundles": _resolve_bundles(),
                }
                # Include service health every 5th poll cycle (every 5s)
                if push_count % 5 == 0:
                    broadcast["service_health"] = await _check_all_services_health()
                    _service_health_cache = broadcast["service_health"]
                    broadcast["nginx_status"] = await _check_nginx_status()
                await _broadcast_ws(broadcast)

            # Phase 0: state consistency check (every 6th poll ≈ 6s).
            # Cheap (4 fields × N GPUs), and divergences are rare, so
            # logger.warning on each divergence is the right signal.
            consistency_count += 1
            if consistency_count >= 6:
                consistency_count = 0
                if scheduler is not None:
                    try:
                        scheduler.verify_state_consistency()
                    except Exception as e:
                        logger.warning(
                            f"[state-consistency] verify_state_consistency() raised: {e}"
                        )

            # Phase 2: silent-OOM detection via dmesg (every 10th poll ≈ 10s).
            # Cheap when dmesg is short; fallback to last-200-lines if --since
            # is unavailable. Each detected OOM-kill of a GPU-using process
            # is recorded via _handle_oom_event so the recovery pipeline
            # (Phase 3) can pick it up.
            global _oom_dmesg_counter, _last_dmesg_ts
            _oom_dmesg_counter += 1
            if _oom_dmesg_counter >= 10:
                _oom_dmesg_counter = 0
                try:
                    oom_events = _detect_silent_oom_via_dmesg(since_ts=_last_dmesg_ts)
                    _last_dmesg_ts = time.time()
                    for ev in oom_events:
                        # Heuristic: assume primary GPU; Phase 3 will refine
                        # using per-process render-node info from /proc.
                        target_gpu = "gpu_primary" if ev.get("gpu_hint") == "gpu_likely" else "gpu_primary"
                        _handle_oom_event(
                            gpu_id=target_gpu,
                            service_name="unknown",
                            job_id="",
                            detection_source="dmesg",
                            reason=f"OOM-killer: {ev.get('name','?')} pid={ev.get('pid','?')}",
                            details=str(ev.get("raw_line", ""))[:300],
                        )
                except Exception as _oom_dmesg_err:
                    logger.debug(f"[oom-detect] dmesg scan hook failed: {_oom_dmesg_err}")

            # Phase 3: scan for GPUs in 'detected' state and kick off recovery.
            # This is the FIRST behavior change in three phases — the watchdog
            # now actively runs the recovery pipeline (Phase 2 only logged).
            # Idempotent: the pipeline itself refuses to re-enter an in-flight
            # recovery, so multiple polls within a recovery window are safe.
            try:
                for _gpu_id, _bs in list(_gpu_states.items()):
                    if _bs.oom_state == "detected":
                        # Avoid double-scheduling if a recovery is already in
                        # flight for this GPU.
                        if _gpu_id in _oom_recovery_in_progress:
                            continue
                        # Best-effort service name lookup. If unknown (e.g.
                        # dmesg-killed PID), the pipeline skips force_recover
                        # but still walks the state machine and restores
                        # both idle LLMs.
                        _service_name = _resolve_service_for_gpu(_gpu_id)
                        _active_job_id = _bs.oom_active_recovery_job_id or ""
                        asyncio.create_task(_oom_recovery_pipeline(
                            gpu_id=_gpu_id,
                            service_name=_service_name,
                            job_id=_active_job_id,
                            oom_reason=_bs.oom_last_reason or "watchdog_detected",
                            oom_details="",
                        ))
                        logger.info(
                            f"[oom-recovery] watchdog: scheduled recovery for "
                            f"{_gpu_id} (service={_service_name!r}, "
                            f"job={_active_job_id!r})"
                        )
            except Exception as _watchdog_err:
                logger.warning(
                    f"[oom-recovery] watchdog dispatch failed: {_watchdog_err}"
                )

        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.error(f"VRAM pusher error: {e}")

        await asyncio.sleep(VRAM_POLL_INTERVAL)


# ── Service Config System ───────────────────────────────────────────

SERVICE_TYPES = ["llm_backend", "generation_backend", "orchestrator", "other"]
DEFAULT_SERVICES_CONFIG = empty_services_config()


_services_config_cache: dict = {}
# Filesystem signature for change detection. inode + mtime_ns + size is the
# minimum that survives atomic-replace (write-temp + os.replace): mtime alone
# can collide on rapid successive writes (coarse utime resolution), but inode
# is bumped by rename and size catches in-place overwrites that happen to
# land in the same nanosecond.
_services_config_signature: tuple = ()   # (inode, mtime_ns, size) of the loaded file
_services_config_last_check: float = 0.0
_SERVICES_CONFIG_STAT_TTL_SECONDS = 2.0
_services_config_cache_is_default: bool = False


def _stat_services_config() -> tuple | None:
    """Return the (inode, mtime_ns, size) signature for SERVICES_CONFIG_PATH,
    or None if the file does not exist / cannot be statted."""
    try:
        st = os.stat(SERVICES_CONFIG_PATH)
    except (FileNotFoundError, OSError):
        return None
    return (st.st_ino, st.st_mtime_ns, st.st_size)


def _quarantine_invalid_config(config: dict) -> dict:
    """Dry-run the config; drop invalid entries, log them, keep the rest.

    A bad gpu_devices/template/service entry must never take the service
    down or discard the valid entries around it.
    """
    try:
        _ok, errors, cleaned = dry_run_config(config)
        cleaned = dict(cleaned)
        services = cleaned.get("services")
        if isinstance(services, dict):
            bad = {k: v for k, v in services.items() if not isinstance(v, dict)}
            if bad:
                errors.append(f"services: non-object entries {sorted(bad)}")
                cleaned["services"] = {k: v for k, v in services.items() if k not in bad}
                cleaned["_quarantined_services"] = bad
        for err in errors:
            logger.warning("CONFIG QUARANTINE: %s", err)
        return cleaned
    except Exception:
        logger.exception("CONFIG QUARANTINE: dry run failed; using config as parsed")
        return config


def _load_services_config() -> dict:
    """Load services config from disk, falling back to defaults.

    Change detection uses an (inode, mtime_ns, size) signature so atomic
    replacement (write-temp + os.replace) is detected even when the new
    file's mtime happens to collide with the previous value. Cache is
    short-circuited when the signature is unchanged.

    Behavioural contract:
      * A successfully parsed dict is promoted to BOTH the local cache
        AND the module-level ``_services_config`` (the global scheduler
        and active endpoints read).
      * ``_bundle_cache`` is invalidated whenever a new dict replaces the
        cached one, because derived bundle resolution depends on it.
      * On a transient invalid JSON / mid-write, the LAST KNOWN GOOD
        config is preserved in both cache and the module-level global;
        production routing does NOT flip back to DEFAULT_SERVICES_CONFIG.
      * When the file does not exist or first-ever load fails, the cache
        starts from DEFAULT_SERVICES_CONFIG (preserving the prior
        bootstrap behaviour).
      * Plan 06 validation: every successful load (and the default
        bootstrap path) is classified by
        ``_validate_linked_bundle_graph`` and
        ``_validate_config_policy``. Results are stored in the
        module-level ``_config_validation_errors`` and
        ``_config_validation_warnings`` lists so that ``/status`` can
        surface them. Validation is read-only — the parsed config is
        never mutated.
    """
    global _services_config_cache, _services_config_signature
    global _services_config_last_check, _services_config_cache_is_default
    global _services_config
    global _config_validation_errors, _config_validation_warnings

    now = time.time()
    if (
        _services_config_cache
        and (now - _services_config_last_check) < _SERVICES_CONFIG_STAT_TTL_SECONDS
    ):
        return copy.deepcopy(_services_config_cache)

    _services_config_last_check = now
    sig = _stat_services_config()

    if sig is None:
        # File missing → bootstrap from defaults exactly once. We do not
        # clobber a previously populated cache on subsequent missing-file
        # stats so a transient mount/visibility blip cannot wipe routing.
        if not _services_config_cache:
            _services_config_cache = copy.deepcopy(DEFAULT_SERVICES_CONFIG)
            _services_config_cache_is_default = True
            _services_config_signature = ()
            _services_config = copy.deepcopy(_services_config_cache)
            _refresh_execution_boundary_registry(_services_config_cache)
            _load_service_pipelines_from_config(_services_config_cache)
            _config_validation_errors, _config_validation_warnings = (
                _validate_config_for_observability(_services_config_cache)
            )
        return copy.deepcopy(_services_config_cache)

    if sig == _services_config_signature and _services_config_cache:
        # Signature unchanged → short-circuit (file contents identical).
        return copy.deepcopy(_services_config_cache)

    try:
        with open(SERVICES_CONFIG_PATH) as f:
            new_config = json.load(f)
        if not isinstance(new_config, dict):
            raise ValueError(
                "services config top level must be a JSON object, "
                f"got {type(new_config).__name__}"
            )
        new_config = _quarantine_invalid_config(new_config)
        _validate_production_parallel_invariant(new_config)
        candidate_errors, candidate_warnings = _validate_config_for_observability(
            new_config
        )
        if candidate_errors:
            raise ValueError(
                "services config policy validation failed: "
                + "; ".join(candidate_errors)
            )
    except Exception as e:
        # Mid-write / invalid JSON: preserve last known good. We only
        # boot into defaults on the very first ever failure (no cache).
        logger.warning(
            f"Failed to parse services config at {SERVICES_CONFIG_PATH} "
            f"(signature={sig}); keeping last-known-good: {e}"
        )
        if not _services_config_cache:
            _services_config_cache = copy.deepcopy(DEFAULT_SERVICES_CONFIG)
            _services_config_cache_is_default = True
            _services_config_signature = sig
            _services_config = copy.deepcopy(_services_config_cache)
            _refresh_execution_boundary_registry(_services_config_cache)
            _load_service_pipelines_from_config(_services_config_cache)
            _config_validation_errors, _config_validation_warnings = (
                _validate_config_for_observability(_services_config_cache)
            )
        return copy.deepcopy(_services_config_cache)

    # Promote the fully parsed dict to BOTH the cache and the global live
    # configuration. Active endpoints and the scheduler read the module-level
    # global — without this assignment a successful external reload would be
    # invisible to them until process restart.
    new_config_dict: dict = new_config
    prior_cache = _services_config_cache
    _services_config_cache = copy.deepcopy(new_config_dict)
    _services_config_cache_is_default = False
    _services_config_signature = sig
    _services_config = copy.deepcopy(new_config_dict)
    _refresh_execution_boundary_registry(new_config_dict)
    _load_service_pipelines_from_config(new_config_dict)

    # Candidate policy errors were rejected before promotion. Preserve warnings
    # for status/health observability without re-running the validator.
    _config_validation_errors = []
    _config_validation_warnings = list(candidate_warnings)
    if _config_validation_warnings:
        logger.info(
            "services config validation produced %d warning(s): %s",
            len(_config_validation_warnings),
            _config_validation_warnings,
        )

    # Invalidate the derived bundle cache iff the config content actually
    # changed (a no-op rewrite must not waste a rebuild).
    if prior_cache != _services_config_cache:
        try:
            _invalidate_bundle_cache()
        except Exception as e:
            logger.debug(f"bundle cache invalidation failed: {e}")

    return copy.deepcopy(_services_config_cache)


def _first_boot_config_failed() -> bool:
    """True when services.json exists but no valid copy was ever loaded (audit C4).

    The loader then runs on the empty default config; the HTTP server must not
    serve on that, so main() exits and systemd retries until the file is fixed.
    """
    _load_services_config()
    return _services_config_cache_is_default and _stat_services_config() is not None


def _pinned_service_blocks_idle_restore(pinned_service: str | None) -> bool:
    """Whether a queue pin owns GPU residency while no work is active.

    LLM pins are routing preferences: they select the only eligible LLM for a
    request but do not keep that model resident between requests. Generation
    backend pins retain their queue-override semantics and suppress idle LLM
    restoration until the pin is cleared.
    """
    if not pinned_service:
        return False
    services = (_load_services_config() or {}).get("services", {})
    return (services.get(pinned_service) or {}).get("type") == "generation_backend"


def _pin_service_rejection(config: Mapping[str, Any], service_name: str) -> tuple[int, dict] | None:
    """Reject disabled or retired services before they become queue policy."""

    service = (config.get("services") or {}).get(service_name)
    if not isinstance(service, Mapping):
        return 404, {"error": f"Service '{service_name}' not found"}
    metadata = service.get("metadata")
    is_acestep = str(service_name).lower().startswith("acestep")
    retired = (
        is_acestep
        or (
            isinstance(metadata, Mapping)
            and str(metadata.get("activation_status") or "").lower() == "retired"
        )
    )
    if retired:
        body = {
            "error": f"Service '{service_name}' is retired and cannot be pinned",
            "reason": "service_retired",
        }
        replacement = metadata.get("replacement") if isinstance(metadata, Mapping) else None
        if not replacement and is_acestep:
            replacement = "minimax-music3-full"
        if replacement:
            body["replacement"] = replacement
        return 410, body
    if service.get("enabled", True) is not True:
        return 409, {
            "error": f"Service '{service_name}' is disabled and cannot be pinned",
            "reason": "service_disabled",
        }
    if service.get("type") == "generation_backend" and service_name != "comfyui":
        return 409, {
            "error": (
                f"Service '{service_name}' uses declarative queue/resource routing "
                "and cannot be controlled by the legacy scheduler pin"
            ),
            "reason": "legacy_pin_unsupported",
        }
    return None


def _save_services_config(config: dict):
    """Persist services config to disk and synchronise the live cache/global."""
    global _services_config_cache, _services_config_signature
    global _services_config_last_check, _services_config_cache_is_default
    global _services_config
    errors, _warnings = _validate_config_for_observability(config)
    if errors:
        raise ValueError(
            "refusing to save invalid services config: " + "; ".join(errors)
        )
    os.makedirs(os.path.dirname(SERVICES_CONFIG_PATH), exist_ok=True)
    # Atomic-replace so concurrent readers never see a half-written file.
    tmp = SERVICES_CONFIG_PATH + ".tmp"
    with open(tmp, "w") as f:
        json.dump(config, f, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, SERVICES_CONFIG_PATH)
    # Persist the rename itself when the filesystem supports directory fsync;
    # a sudden host loss must not acknowledge a registry edit that vanished
    # after the atomic replace.
    try:
        directory_fd = os.open(
            os.path.dirname(SERVICES_CONFIG_PATH) or ".", os.O_DIRECTORY
        )
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    except OSError:
        logger.debug("services registry directory fsync unavailable", exc_info=True)
    sig = _stat_services_config()
    _services_config = copy.deepcopy(config)
    _services_config_cache = copy.deepcopy(config)
    _services_config_cache_is_default = False
    _services_config_signature = sig or ()
    _services_config_last_check = time.time()
    _refresh_execution_boundary_registry(config)
    _load_service_pipelines_from_config(config)
    try:
        _invalidate_bundle_cache()
    except Exception as e:
        logger.debug(f"bundle cache invalidation failed after save: {e}")


# ── Nginx Config & Status ──────────────────────────────────────────

NGINX_MANAGER_SH = os.environ.get(
    "GPU_MANAGER_NGINX_MANAGER", str(PROJECT_ROOT / "scripts/nginx-manager.sh")
)

async def _regenerate_nginx_config():
    """Regenerate nginx config by calling nginx-manager.sh regenerate."""
    global _nginx_status_cache
    try:
        proc = await asyncio.create_subprocess_exec(
            "sudo", NGINX_MANAGER_SH, "regenerate",
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=15)
        out = stdout.decode().strip() if stdout else ""
        err = stderr.decode().strip() if stderr else ""
        if proc.returncode == 0:
            logger.info(f"Nginx config regenerated: {out[:200]}")
        else:
            logger.warning(f"Nginx config regenerate failed (rc={proc.returncode}): {err[:200]}")
        # Refresh status after regeneration
        _nginx_status_cache = await _check_nginx_status()
    except asyncio.TimeoutError:
        logger.warning("Nginx config regenerate timed out")
    except Exception as e:
        logger.error(f"Nginx config regenerate error: {e}")


async def _check_nginx_status() -> dict:
    """Check nginx status: running/stopped/config_error, proxy ports, config validity."""
    global _nginx_status_cache
    result = {"state": "unknown", "config_valid": None, "proxy_ports": []}
    try:
        # Check systemd status
        proc = await asyncio.create_subprocess_exec(
            "systemctl", "is-active", "nginx",
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=5)
        active_status = stdout.decode().strip() if stdout else ""
    except Exception:
        active_status = ""

    try:
        # Check proxy ports 8110/8111/8112
        proc = await asyncio.create_subprocess_shell(
            "ss -tlnp 2>/dev/null | grep -oP '811[012]' || true",
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=5)
        ports_text = stdout.decode().strip() if stdout else ""
        listening_ports = sorted(set(ports_text.split())) if ports_text else []
    except Exception:
        listening_ports = []

    try:
        # Check config validity
        proc = await asyncio.create_subprocess_shell(
            "sudo nginx -t 2>&1",
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=5)
        config_output = stdout.decode().strip() if stdout else ""
        config_valid = "test is successful" in config_output
    except Exception:
        config_valid = None

    # Determine state
    if active_status == "active":
        result["state"] = "running"
    elif active_status == "activating":
        result["state"] = "restarting"
    elif active_status in ("failed", "dead"):
        result["state"] = "stopped" if config_valid else "config_error"
    else:
        result["state"] = "stopped"

    if config_valid is False and result["state"] != "stopped":
        result["state"] = "config_error"

    result["config_valid"] = config_valid
    result["proxy_ports"] = listening_ports

    _nginx_status_cache = result
    return result


# ── Bundle Resolution Layer ────────────────────────────────────────

_bundle_cache: dict = {}          # cached resolved bundles
_bundle_cache_ts: float = 0.0     # monotonic timestamp of last refresh
_BUNDLE_CACHE_TTL: float = 30.0   # seconds before cache is considered stale


def _resolve_bundles(config: dict | None = None) -> dict:
    """Resolve service bundles from config, with a 30-second cache.

    If *config* is explicitly passed (e.g. from ``_migrate_config``),
    caching is bypassed so callers always get a fresh result.

    Otherwise the result is cached for ``_BUNDLE_CACHE_TTL`` seconds
    so repeated calls within that window do not re-read the config file.

    If the config contains a 'bundles' section, use it directly.
    Otherwise, auto-generate bundles from the old 'services' format
    for backward compatibility.

    Returns:
        {bundle_name: {
            gpu_id: str,
            priority: int,
            proxy_port: int | None,
            services: [str, ...],
            linked_to: [str, ...],
            linked_from: [str, ...],
            idle: bool,
        }}
    """
    # When called with an explicit config, bypass cache (migration path)
    if config is not None:
        return _resolve_bundles_uncached(config)

    global _bundle_cache, _bundle_cache_ts
    now = time.monotonic()
    if _bundle_cache and (now - _bundle_cache_ts) < _BUNDLE_CACHE_TTL:
        return _bundle_cache

    result = _resolve_bundles_uncached(_load_services_config())
    _bundle_cache = result
    _bundle_cache_ts = now
    return result


def _resolve_bundles_uncached(config: dict) -> dict:
    """Internal: resolve bundles from *config* without caching."""
    # If bundles section exists, use it
    if "bundles" in config and config["bundles"]:
        bundles = config["bundles"]
        # Normalize: ensure every bundle has the required fields
        for name, bundle in bundles.items():
            bundle.setdefault("gpu_id", None)
            bundle.setdefault("priority", 5)
            bundle.setdefault("proxy_port", None)
            bundle.setdefault("services", [])
            bundle.setdefault("linked_to", [])
            bundle.setdefault("linked_from", [])
            bundle.setdefault("idle", False)
        return bundles

    # ── Backward compatibility: auto-generate from old format ──
    logger.info("No 'bundles' section in config — auto-generating from services + idle_services")
    services = config.get("services", {})
    scheduling = config.get("scheduling", {})
    idle_services = scheduling.get("idle_services", {})

    bundles: dict = {}

    # 1) Create idle bundles from idle_services mapping
    for gpu_id, svc_name in idle_services.items():
        if svc_name not in services:
            logger.warning(f"idle_services[{gpu_id}] = '{svc_name}' not found in services section, skipping")
            continue
        svc = services[svc_name]
        bundles[svc_name] = {
            "gpu_id": gpu_id,
            "priority": svc.get("priority", 1),
            "proxy_port": svc.get("proxy_port"),
            "services": [svc_name],
            "linked_to": [],
            "linked_from": [],
            "idle": True,
        }

    # 2) Create bundles for every service that has a gpu_id
    #    (skip services already created as idle bundles)
    for svc_name, svc in services.items():
        gpu_id = svc.get("gpu_id")
        if not gpu_id:
            # No gpu_id = orchestrator / CPU-only service — skip bundling
            continue
        if svc_name in bundles:
            # Already created as idle bundle
            continue

        bundles[svc_name] = {
            "gpu_id": gpu_id,
            "priority": svc.get("priority", 5),
            "proxy_port": svc.get("proxy_port"),
            "services": [svc_name],
            "linked_to": [],
            "linked_from": [],
            "idle": False,
        }

    return bundles


def _collect_linked_gpus(
    bundle: dict,
    bundles: dict,
    *,
    bundle_name: str | None = None,
) -> list[str]:
    """Return primary + linked GPUs for bundle, preserving order, deduped.

    ``bundle_name`` must be supplied by callers that hold a raw config dict;
    bundle mappings do not persist their own key as a ``name`` field.
    """
    primary = bundle.get("gpu_id")
    gpus: list[str] = []
    if primary:
        gpus.append(primary)
    _bundle_name = (
        bundle_name
        or bundle.get("name")
        or bundle.get("bundle_name")
        or ""
    )
    for linked_name in _get_linked_bundles(
        _bundle_name, bundles=bundles,
    ):
        lgid = bundles.get(linked_name, {}).get("gpu_id")
        if lgid and lgid not in gpus:
            gpus.append(lgid)
    return gpus


def _invalidate_bundle_cache() -> None:
    """Force the next ``_resolve_bundles()`` call to re-read from disk."""
    global _bundle_cache, _bundle_cache_ts
    _bundle_cache = {}
    _bundle_cache_ts = 0.0


def _get_bundle_for_service(service_name: str, bundles: dict | None = None) -> dict | None:
    """Return the bundle dict that contains *service_name*, or None.

    Searches the ``services`` list inside each bundle.
    """
    if not service_name:
        return None
    if bundles is None:
        bundles = _resolve_bundles()
    for bundle_name, bundle in bundles.items():
        if service_name in bundle.get("services", []):
            # Callers that commit GPU ownership must use the configured
            # bundle identity, never the raw service name. Returning a copy
            # avoids mutating the cached bundle registry.
            resolved = dict(bundle)
            resolved["bundle_name"] = bundle_name
            return resolved
    return None


# ── Plan 4.7: evict_only_when_idle bundles (strata-rx) ─────────────────
# A bundle with ``evict_only_when_idle`` is never unloaded while it serves a
# request. Only a non-idle requester with a higher configured priority may
# replace it, and only after it goes idle. The occupant's CONFIG priority is
# compared, not gs.bundle_priority (that records the requester's priority).
_EVICT_ONLY_WHEN_IDLE_WAIT_SECONDS = 120.0
_EVICT_ONLY_WHEN_IDLE_POLL_SECONDS = 2.0


def _bundle_evict_only_when_idle(bundle_cfg: Mapping | None) -> bool:
    return bool(isinstance(bundle_cfg, Mapping) and bundle_cfg.get("evict_only_when_idle"))


def _protected_bundles_on_gpu(
    gpu_id: str,
    bundles: Mapping,
    skip_bundle_name: str | None = None,
) -> list[str]:
    """evict_only_when_idle bundles currently loaded on *gpu_id*."""
    gs = _gpu_states.get(gpu_id) if isinstance(_gpu_states, dict) else None
    if gs is None:
        return []
    names: list[str] = []
    for name in [getattr(gs, "loaded_bundle", None), *list(getattr(gs, "loaded_bundles", None) or [])]:
        if isinstance(name, str) and name.startswith("llm:"):
            name = name[len("llm:"):]
        if (
            name
            and name != skip_bundle_name
            and name not in names
            and _bundle_evict_only_when_idle(bundles.get(name))
        ):
            names.append(name)
    return names


def _protected_occupant_refusal(
    requester_name: str | None,
    requester_cfg: Mapping | None,
    occupant_name: str,
    occupant_cfg: Mapping,
) -> str | None:
    """Why *requester* may never evict *occupant*, or None when it may (once idle)."""
    requester_cfg = requester_cfg or {}
    if requester_cfg.get("idle"):
        return f"idle bundle {requester_name} never evicts {occupant_name}"
    try:
        req_priority = int(requester_cfg.get("priority", 5))
        occ_priority = int(occupant_cfg.get("priority", 0))
    except (TypeError, ValueError):
        return f"unparseable priority for {requester_name} or {occupant_name}"
    if req_priority <= occ_priority:
        return (
            f"{requester_name} priority {req_priority} <= {occupant_name} "
            f"priority {occ_priority}"
        )
    return None


async def _bundle_busy(bundle_name: str, bundles: Mapping | None = None) -> bool:
    """True while *bundle_name* serves a request or cannot prove it is idle.

    Fails closed (busy) on a timeout, a non-200 or an unparseable /slots body.
    A refused connection means no process is listening, so nothing can be
    interrupted and the bundle counts as idle.
    """
    if bundles is None:
        bundles = _resolve_bundles()
    cfg = bundles.get(bundle_name) or {}
    for gid in _bundle_physical_gpu_set(bundle_name, bundles=bundles):
        gs = _gpu_states.get(gid) if isinstance(_gpu_states, dict) else None
        if gs is not None and int(getattr(gs, "worker_in_flight", 0) or 0) > 0:
            return True
    services_cfg = (_load_services_config() or {}).get("services", {})
    for svc_name in cfg.get("services", []):
        if capacity_tracker is not None and capacity_tracker._active.get(svc_name, 0) > 0:
            return True
        port = (services_cfg.get(svc_name) or {}).get("port")
        if not port:
            return True
        try:
            async with ClientSession(timeout=ClientTimeout(total=3)) as session:
                async with session.get(f"http://127.0.0.1:{int(port)}/slots") as resp:
                    if resp.status != 200:
                        return True
                    slots = await resp.json(content_type=None)
        except ClientConnectorError:
            continue
        except Exception:
            return True
        if not isinstance(slots, list):
            return True
        if any(isinstance(slot, Mapping) and slot.get("is_processing") for slot in slots):
            return True
    return False


async def _protected_occupant_busy_on_gpu(
    gpu_id: str,
    skip_bundle_name: str | None = None,
) -> str | None:
    """Name of a busy evict_only_when_idle bundle on *gpu_id*, else None."""
    bundles = _resolve_bundles()
    for occupant in _protected_bundles_on_gpu(gpu_id, bundles, skip_bundle_name):
        if await _bundle_busy(occupant, bundles):
            return occupant
    return None


async def _evict_llm_unless_protected_busy(vram, reason: str, target_gpu: str | None = None,
                                           skip_bundle_name: str | None = None,
                                           admission_authorized: bool = False) -> bool:
    """``vram.evict_llm`` that refuses while an evict_only_when_idle bundle serves a request.

    Plan 4.7: every eviction path goes through here; VRAMLifecycleManager is a
    frozen template, so the guard lives in the facade.
    """
    gpus = [target_gpu] if target_gpu else sorted(_gpu_states or {})
    for gpu_id in gpus:
        occupant = await _protected_occupant_busy_on_gpu(gpu_id, skip_bundle_name)
        if occupant:
            logger.warning(
                "VRAM: refusing LLM eviction on %s (%s): %s is serving a request",
                gpu_id, reason, occupant,
            )
            return False
    return await vram.evict_llm(
        reason=reason, target_gpu=target_gpu, skip_bundle_name=skip_bundle_name,
        admission_authorized=admission_authorized,
    )


def _bundle_resident_on_all_gpus(bundle_name: str, bundles: Mapping) -> bool:
    gpus = _bundle_physical_gpu_set(bundle_name, bundles=bundles)
    if not gpus:
        return False
    for gid in gpus:
        gs = _gpu_states.get(gid) if isinstance(_gpu_states, dict) else None
        if gs is None or getattr(gs, "state", None) in ("loading", "evicting", "draining"):
            return False
        loaded = [getattr(gs, "loaded_bundle", None), *list(getattr(gs, "loaded_bundles", None) or [])]
        if bundle_name not in loaded:
            return False
    return True


_COLD_LLM_ADMIT_LOCKS: dict[str, asyncio.Lock] = {}


async def _admit_cold_llm_service_inline(service_name: str, gpu_id: str) -> str | None:
    """Admit a cold bundle-backed LLM from the proxy. None = loaded, else why not."""
    bundles = _resolve_bundles()
    service_bundle = _get_bundle_for_service(service_name, bundles=bundles)
    if not service_bundle:
        return "unbundled"
    priority = int(service_bundle.get("priority", 0) or 0)
    bundle_name = service_bundle["bundle_name"]
    llm.active_requests += 1  # keep the idle manager from swapping mid-load
    try:
        # One load per GPU at a time: a request arriving mid-load waits, then
        # finds the bundle resident and skips admission.
        async with _COLD_LLM_ADMIT_LOCKS.setdefault(gpu_id, asyncio.Lock()):
            if _bundle_resident_on_all_gpus(bundle_name, bundles):
                return None
            for target_gpu in sorted(_bundle_physical_gpu_set(bundle_name, bundles=bundles) or {gpu_id}):
                gs = _gpu_states.get(target_gpu) if isinstance(_gpu_states, dict) else None
                for name in [getattr(gs, "loaded_bundle", None), *list(getattr(gs, "loaded_bundles", None) or [])]:
                    name = str(name or "").removeprefix("llm:")
                    if not name or name == bundle_name:
                        continue
                    occupant = bundles.get(name)
                    if occupant and occupant.get("idle"):
                        continue
                    # evict_llm stops only LLM units: never load next to an unknown,
                    # equal or higher-priority tenant (generation backends, strata).
                    if not occupant or int(occupant.get("priority", 0) or 0) >= priority:
                        return f"GPU {target_gpu} holds {name} at equal or higher priority"
            admitted, _ = await _admit_bundle_backed_llm_service(service_name, priority=priority)
    finally:
        llm.active_requests -= 1
    return None if admitted else "bundle admission failed"


async def _admit_bundle_backed_llm_service(
    service_name: str,
    priority: int,
) -> tuple[bool, dict | None]:
    """Atomically admit a cold bundle-backed LLM across its physical GPUs."""
    bundles = _resolve_bundles()
    service_bundle = _get_bundle_for_service(service_name, bundles=bundles)
    if not service_bundle:
        return False, None
    bundle_name = service_bundle["bundle_name"]
    if _bundle_evict_only_when_idle(service_bundle) and _bundle_resident_on_all_gpus(
        bundle_name, bundles
    ):
        # Already loaded: a repeat admission must not unload it mid-answer.
        return True, service_bundle
    for target_gpu in sorted(_bundle_physical_gpu_set(bundle_name, bundles=bundles)):
        for occupant in _protected_bundles_on_gpu(target_gpu, bundles, bundle_name):
            refusal = _protected_occupant_refusal(
                bundle_name, service_bundle, occupant, bundles.get(occupant) or {}
            )
            if refusal is None and await _bundle_busy(occupant, bundles):
                refusal = f"{occupant} is serving a request"
            if refusal is not None:
                logger.warning(
                    "LLM queue bundle admission refused on GPU %s for %s: %s",
                    target_gpu, bundle_name, refusal,
                )
                return False, service_bundle
    async def _admit_operation() -> bool:
        for target_gpu in sorted(_bundle_physical_gpu_set(bundle_name, bundles=bundles)):
            if not await _evict_llm_unless_protected_busy(
                vram,
                reason=f"llm_queue_bundle_admission:{bundle_name}",
                target_gpu=target_gpu,
                admission_authorized=True,
            ):
                logger.error(
                    "LLM queue bundle admission failed to evict GPU %s for %s",
                    target_gpu,
                    bundle_name,
                )
                return False
        return await _load_bundle(
            bundle_name,
            priority=priority,
            allow_worker_in_flight=True,
        )

    loaded = await _run_bundle_transition(
        bundle_name,
        _admit_operation,
        desired_state=BundleDesiredState.RUNNING,
        reason=f"llm-queue-bundle-admission:{service_name}",
    )
    return bool(loaded), service_bundle


def _get_bundle_by_port(port: int | str, bundles: dict | None = None) -> dict | None:
    """Return the bundle whose ``proxy_port`` matches *port*, or None.

    Used for inbound proxy routing — maps an external port to the
    right bundle of backend services.  Includes ``bundle_name`` key.
    """
    if port is None:
        return None
    port = int(port)
    if bundles is None:
        bundles = _resolve_bundles()
    for bundle_name, bundle in bundles.items():
        bp = bundle.get("proxy_port")
        if bp is not None and int(bp) == port:
            b_copy = dict(bundle)
            b_copy["bundle_name"] = bundle_name
            return b_copy
    return None


def _get_linked_bundles(bundle_name: str, bundles: dict | None = None) -> list[str]:
    """Return all bundle names linked to *bundle_name* across GPUs.

    Linking is bidirectional: if bundle A lists bundle B in its
    ``linked_to``, querying either will return the other.  Also
    follows ``linked_from`` fields.  Results are sorted alphabetically.
    """
    if not bundle_name:
        return []
    if bundles is None:
        bundles = _resolve_bundles()
    me = bundles.get(bundle_name)
    if me is None:
        return []

    linked: set[str] = set()

    # Forward links (linked_to field on this bundle)
    linked.update(me.get("linked_to", []))

    # Forward links via the field name used by the existing config
    linked.update(me.get("linked_bundles", []))

    # Reverse links: any other bundle that points at us
    for name, bundle in bundles.items():
        if name == bundle_name:
            continue
        if bundle_name in bundle.get("linked_to", []):
            linked.add(name)
        if bundle_name in bundle.get("linked_bundles", []):
            linked.add(name)
        if bundle_name in bundle.get("linked_from", []):
            linked.add(name)

    # Don't include self
    linked.discard(bundle_name)
    return sorted(linked)


def _expand_bundle_transition_members(
    transitions: list[tuple[str, Any]],
    bundles: dict | None = None,
) -> list[tuple[str, Any]]:
    """Expand root transitions to every linked member with conflict detection."""
    if bundles is None:
        bundles = _resolve_bundles()
    expanded: dict[str, Any] = {}
    for root_name, desired_state in transitions:
        members = [root_name, *_get_linked_bundles(root_name, bundles=bundles)]
        for member_name in members:
            previous = expanded.get(member_name)
            if previous is not None and previous != desired_state:
                raise ValueError(
                    f"conflicting desired states for linked bundle {member_name}: "
                    f"{previous!r} vs {desired_state!r}"
                )
            expanded[member_name] = desired_state
    return sorted(expanded.items())


async def _bundle_group_owned_and_healthy(bundle_name: str) -> bool:
    """Return True only when the full linked bundle group is already usable.

    This is a read-only warm-batch fast path. Ownership must name every linked
    member on its configured GPU and the bundle's service health must pass.
    A partial/stale roster or an unhealthy service fails closed so normal
    admission can repair the state.
    """
    bundles = _resolve_bundles()
    primary = bundles.get(bundle_name)
    if not primary:
        return False

    members = list(dict.fromkeys(
        [bundle_name, *_get_linked_bundles(bundle_name, bundles=bundles)]
    ))
    for member_name in members:
        member = bundles.get(member_name) or {}
        gpu_id = member.get("gpu_id")
        if not gpu_id:
            return False
        gpu_state = _get_gpu_state(gpu_id)
        loaded = list(getattr(gpu_state, "loaded_bundles", []) or [])
        if member_name not in loaded:
            return False

    try:
        health = await _get_bundle_health(bundle_name)
    except Exception:
        logger.exception(
            "WarmBundle: health check raised for already-owned %s", bundle_name
        )
        return False
    return bool(isinstance(health, dict) and health.get("ok") is True)


def _transition_linked_bundle_state(
    primary_name: str,
    target_loaded: list[str] | None,
    source: str = "linked_transition",
    *,
    effective_priorities: dict[str, int] | None = None,
) -> None:
    """Atomically update one linked group while preserving unrelated ownership.

    ``target_loaded`` activates the linked group when it contains any member;
    an empty roster removes only this group's members. Other idle/restore
    bundles already recorded on the same GPU survive rollback.
    """
    bundles = _resolve_bundles()
    primary = bundles.get(primary_name)
    if not primary:
        return
    linked_names = _get_linked_bundles(primary_name, bundles=bundles)
    members = list(dict.fromkeys([primary_name, *linked_names]))
    member_set = set(members)
    requested = set(target_loaded or [])
    activate_group = bool(requested & member_set)

    effective_priorities = effective_priorities or {}

    def _resolve_priority(bundle_name: str, bundle_cfg: dict) -> int:
        if bundle_name in effective_priorities:
            return int(effective_priorities[bundle_name] or 0)
        if "priority" in bundle_cfg:
            return int(bundle_cfg.get("priority", 0) or 0)
        return int(primary.get("priority", 0) or 0)

    for name in members:
        bundle = bundles.get(name) or {}
        gpu_id = bundle.get("gpu_id")
        if not gpu_id:
            continue
        gs = _get_gpu_state(gpu_id)
        if gs is None:
            continue

        current = list(getattr(gs, "loaded_bundles", []) or [])
        prior_owner = getattr(gs, "loaded_bundle", None)
        preserved = [entry for entry in current if entry not in member_set]
        new_roster = list(preserved)
        if activate_group and name not in new_roster:
            new_roster.append(name)

        gs.set_loaded_bundles(new_roster, source=source)
        if activate_group:
            priority = _resolve_priority(name, bundle)
            gs.loaded_bundle = name
            gs.bundle_priority = priority
            gs.state = "loaded"
            gs.set_current_priority(priority, source=source)
            # The 30 s authoritative reconcile re-asserts resident bundles;
            # re-stamping there would reset the idle-unload clock forever.
            if name not in current:
                gs.touch_activity(source=source)
        elif new_roster:
            # Preserve a canonical owner only when it independently survived
            # this linked-group rollback. Never invent ownership from list
            # ordering: a roster can contain reservations or stale audit names.
            if isinstance(prior_owner, str) and prior_owner in new_roster:
                owner_cfg = bundles.get(prior_owner) or {}
                priority = _resolve_priority(prior_owner, owner_cfg)
                gs.loaded_bundle = prior_owner
                gs.bundle_priority = priority
            else:
                priority = max(
                    (
                        _resolve_priority(
                            entry,
                            bundles.get(entry) or {},
                        )
                     for entry in new_roster),
                    default=0,
                )
                gs.loaded_bundle = None
                gs.bundle_priority = 0
            gs.state = "loaded"
            gs.set_current_priority(priority, source=source)
        else:
            gs.loaded_bundle = None
            gs.bundle_priority = 0
            gs.state = "idle"
            gs.set_current_priority(0, source=source)


def _get_bundles_for_gpu(gpu_id: str, bundles: dict | None = None) -> list[dict]:
    """Return all bundles assigned to *gpu_id*, sorted by priority (highest first).

    Priority is taken from the ``priority`` field (default 5).
    Higher numbers win; ties are broken alphabetically by bundle name.
    Each returned dict includes a ``bundle_name`` key for identification.
    """
    if not gpu_id:
        return []
    if bundles is None:
        bundles = _resolve_bundles()
    result = []
    for name, b in bundles.items():
        if b.get("gpu_id") == gpu_id:
            b_copy = dict(b)
            b_copy["bundle_name"] = name
            result.append(b_copy)
    result.sort(key=lambda b: (b.get("priority", 5), b.get("bundle_name", "")), reverse=True)
    return result


def _get_idle_bundles(bundles: dict | None = None) -> dict:
    """Return only bundles marked as idle (all GPUs)."""
    if bundles is None:
        bundles = _resolve_bundles()
    return {
        name: bundle
        for name, bundle in bundles.items()
        if bundle.get("idle", False)
    }


def _get_idle_bundle(gpu_id: str, bundles: dict | None = None) -> dict | None:
    """Return the idle bundle for a specific *gpu_id*.

    If multiple bundles are marked idle on the same GPU, the one
    with the highest priority wins.  Returns None if no idle bundle
    is configured for the GPU.  Includes ``bundle_name`` key.
    """
    if not gpu_id:
        return None
    if bundles is None:
        bundles = _resolve_bundles()
    idle = []
    for name, b in bundles.items():
        if b.get("gpu_id") == gpu_id and b.get("idle", False):
            b_copy = dict(b)
            b_copy["bundle_name"] = name
            idle.append(b_copy)
    if not idle:
        return None
    idle.sort(key=lambda b: (b.get("priority", 5), b.get("bundle_name", "")), reverse=True)
    return idle[0]


async def _is_bundle_ready(bundle_name: str, bundles: dict | None = None) -> bool:
    """Return True when every service in the bundle is reachable on its port.

    Uses a lightweight TCP connect (1-second timeout) — no HTTP required.
    Returns False if the bundle does not exist or has no services.
    """
    if not bundle_name:
        return False
    if bundles is None:
        bundles = _resolve_bundles()
    bundle = bundles.get(bundle_name)
    if bundle is None:
        return False

    config = _load_services_config()
    services_cfg = config.get("services", {})
    member_names = bundle.get("services", [])
    if not member_names:
        return False

    for svc_name in member_names:
        svc = services_cfg.get(svc_name, {})
        port = svc.get("port")
        if not port:
            return False
        try:
            reader, writer = await asyncio.wait_for(
                asyncio.open_connection("127.0.0.1", int(port)),
                timeout=1.0,
            )
            writer.close()
            await writer.wait_closed()
        except (OSError, TimeoutError, asyncio.TimeoutError):
            return False

    return True


async def _check_service_port(port: int, timeout: float = 2.0) -> str:
    """Return 'healthy' / 'unhealthy' / 'skipped' for a single service port.

    Mirrors the readiness check used inside ``_load_bundle`` so the
    post-load health report in the ``start_bundle`` MCP tool matches
    what the loader actually waited for.
    """
    if not port:
        return "skipped"
    try:
        # TCP connect probe — fast, doesn't depend on /health path.
        _, writer = await asyncio.wait_for(
            asyncio.open_connection("127.0.0.1", int(port)),
            timeout=timeout,
        )
        writer.close()
        try:
            await writer.wait_closed()
        except Exception:
            pass
        return "healthy"
    except (OSError, TimeoutError, asyncio.TimeoutError):
        return "unhealthy"


async def _get_bundle_health(bundle_name: str) -> dict:
    """Return per-service health for a bundle and its linked bundles.

    The ``start_bundle`` MCP tool reports structured health so partial
    success (1 of N services healthy) with full success (all N
    healthy). This helper walks the same bundle graph as
    ``_load_bundle`` and returns a structured report so the caller
    can distinguish the two cases.

    The check is read-only: it does not start or stop anything, it
    only inspects the current port state of each member service.
    That keeps it safe to call immediately after ``_load_bundle``
    (it sees the same state the loader just verified) and also
    independently as a status check.

    Returns::

        {
            "ok": True | False,            # all services healthy
            "primary_healthy": True|False, # this bundle's services
            "linked_healthy": True | False | "none",  # linked bundles
            "services": {                  # service -> "healthy"|"unhealthy"|"skipped"
                "svc-name": "healthy",
                ...
            },
            "errors": ["..."],              # human-readable, may be empty
        }
    """
    bundles = _resolve_bundles()
    bundle = bundles.get(bundle_name)
    if bundle is None:
        return {
            "ok": False,
            "primary_healthy": False,
            "linked_healthy": "none",
            "services": {},
            "errors": [f"Unknown bundle '{bundle_name}'"],
        }

    config = _load_services_config()
    services_cfg = config.get("services", {})

    services: dict[str, str] = {}
    errors: list[str] = []

    async def _classify(svc_names: list[str], label: str) -> bool:
        all_ok = True
        for svc_name in svc_names:
            svc = services_cfg.get(svc_name, {})
            port = svc.get("port")
            if not port:
                services[svc_name] = "skipped"
                # No port = not a health failure (e.g. VRAM marker,
                # orchestrator).  Don't downgrade primary_healthy.
                continue
            status = await _check_service_port(int(port))
            services[svc_name] = status
            if status != "healthy":
                all_ok = False
                errors.append(
                    f"{label} service '{svc_name}' port {port} is {status}"
                )
        return all_ok

    # Primary bundle members
    member_names = list(bundle.get("services", []))
    primary_ok = await _classify(member_names, "primary")

    # Linked bundles (recursive graph, same as _load_bundle)
    linked_ok: bool | str = "none"
    visited: set[str] = set()
    queue: list[str] = list(bundle.get("linked_to", []) or [])
    while queue:
        linked_name = queue.pop(0)
        if linked_name in visited:
            continue
        visited.add(linked_name)
        linked_bundle = bundles.get(linked_name)
        if linked_bundle is None:
            errors.append(f"linked bundle '{linked_name}' not found")
            linked_ok = False
            continue
        linked_members = list(linked_bundle.get("services", []))
        if not await _classify(linked_members, f"linked:{linked_name}"):
            linked_ok = False
        # Follow further links
        for nxt in linked_bundle.get("linked_to", []) or []:
            if nxt not in visited:
                queue.append(nxt)
    if linked_ok == "none" and visited:
        # Linked bundles were visited but never set False → True
        linked_ok = True

    ok = bool(primary_ok) and (linked_ok is True or linked_ok == "none")
    return {
        "ok": ok,
        "primary_healthy": primary_ok,
        "linked_healthy": linked_ok,
        "services": services,
        "errors": errors,
    }


_SYSTEMD_CGROUP_ROOT = "/sys/fs/cgroup"


async def _get_systemd_unit_pids(unit: str) -> set[int]:
    """Return MainPID plus every process in a systemd unit's cgroup."""
    pids: set[int] = set()
    if not unit:
        return pids
    try:
        proc = await asyncio.create_subprocess_exec(
            "systemctl", "show", unit,
            "--property", "MainPID",
            "--property", "ControlGroup",
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.DEVNULL,
        )
        stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=5)
        if proc.returncode != 0:
            return pids
        values: dict[str, str] = {}
        for line in stdout.decode(errors="replace").splitlines():
            key, sep, value = line.partition("=")
            if sep:
                values[key] = value.strip()
        try:
            main_pid = int(values.get("MainPID", "0") or 0)
            if main_pid > 0:
                pids.add(main_pid)
        except (TypeError, ValueError):
            pass
        control_group = values.get("ControlGroup", "").strip().lstrip("/")
        if control_group:
            procs_path = os.path.join(
                _SYSTEMD_CGROUP_ROOT, control_group, "cgroup.procs"
            )
            try:
                with open(procs_path, "r", encoding="utf-8") as handle:
                    for raw_pid in handle:
                        try:
                            pid = int(raw_pid.strip())
                            if pid > 0:
                                pids.add(pid)
                        except ValueError:
                            continue
            except OSError:
                # MainPID remains a conservative fallback when cgroupfs is
                # unavailable; an empty result still fails residency closed.
                pass
    except Exception:
        return pids
    return pids


def _get_checked_runtime_controller() -> CheckedRuntimeController:
    global _checked_runtime_controller_instance
    if _checked_runtime_controller_instance is None:
        _checked_runtime_controller_instance = CheckedRuntimeController(
            state_path=RUNTIME_STATE_FILE,
            socket_path=os.environ.get("GPU_MANAGER_HOST_SUPERVISOR_SOCKET"),
        )
    return _checked_runtime_controller_instance


async def _transition_checked_bundle_runtime(
    config: Mapping[str, Any],
    bundle_name: str,
    *,
    desired_state: str,
    timeout: float,
):
    """Use the host supervisor when a bundle declares a checked runtime."""

    return await _get_checked_runtime_controller().transition_if_configured(
        config,
        bundle_name,
        desired_state=desired_state,
        timeout_seconds=timeout,
    )


async def _start_bundle_members(
    config: Mapping[str, Any],
    bundle_name: str,
    member_names: list[str],
    services_cfg: Mapping[str, Any],
    *,
    timeout: float,
) -> tuple[bool, list[str], bool]:
    """Start one bundle through its checked runtime or the legacy launcher."""

    try:
        binding = resolve_checked_runtime_binding(config, bundle_name)
    except CheckedRuntimeError as exc:
        logger.error("LoadBundle: checked runtime configuration rejected: %s", exc)
        return False, [], True

    if binding is not None:
        for service_name in member_names:
            if event_bus is not None:
                event_bus.mark_planned_stop(service_name)
        try:
            record = await _transition_checked_bundle_runtime(
                config,
                bundle_name,
                desired_state="ready",
                timeout=timeout,
            )
            if record is None or record.state.value != "ready" or not record.accepting:
                raise CheckedRuntimeError("host supervisor did not publish ready state")
            for service_name in member_names:
                unit = str((services_cfg.get(service_name) or {}).get("systemd_unit") or "")
                if scheduler is not None and unit:
                    pid = await scheduler._get_service_main_pid(unit)
                    if pid and pid > 0:
                        scheduler._register_expected_pid(pid)
            logger.info(
                "LoadBundle: checked runtime %s reached ready for '%s'",
                binding.instance_id,
                bundle_name,
            )
            return True, [], True
        except Exception as exc:
            logger.error("LoadBundle: checked runtime transition failed: %s", exc)
            return False, [], True

    started_units: list[str] = []
    for service_name in member_names:
        service = services_cfg.get(service_name, {})
        unit = service.get("systemd_unit", "")
        if not unit:
            logger.error("LoadBundle: service '%s' has no systemd_unit", service_name)
            return False, started_units, False
        try:
            process = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", "start", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await process.communicate()
            if process.returncode != 0:
                logger.error(
                    "LoadBundle: systemctl start %s failed (rc=%s): %s",
                    unit,
                    process.returncode,
                    (stderr or stdout).decode(errors="replace").strip(),
                )
                return False, started_units, False
            started_units.append(unit)
            logger.info("LoadBundle: started %s", unit)
            if event_bus is not None:
                event_bus.mark_planned_stop(service_name)
            if scheduler is not None:
                try:
                    pid = await scheduler._get_service_main_pid(unit)
                    if pid and pid > 0:
                        scheduler._register_expected_pid(pid)
                except Exception as exc:
                    logger.debug(
                        "LoadBundle: PID registration for %s failed: %s", unit, exc
                    )
        except Exception as exc:
            logger.error("LoadBundle: systemctl start %s error: %s", unit, exc)
            return False, started_units, False
    return True, started_units, False


async def _rollback_bundle_start(
    config: Mapping[str, Any],
    bundle_name: str,
    member_names: list[str],
    started_units: list[str],
    *,
    checked_runtime_used: bool,
    timeout: float,
) -> bool:
    if not checked_runtime_used:
        return await _rollback_started_units(started_units)
    try:
        record = await _transition_checked_bundle_runtime(
            config,
            bundle_name,
            desired_state="stopped",
            timeout=timeout,
        )
        return record is not None and record.state.value == "stopped"
    except Exception as exc:
        logger.error("Bundle rollback: checked runtime stop failed: %s", exc)
        return False
    finally:
        for service_name in member_names:
            if event_bus is not None:
                event_bus.clear_planned_stop(service_name)


async def _stop_bundle_members(
    config: Mapping[str, Any],
    bundle_name: str,
    member_names: list[str],
    services_cfg: Mapping[str, Any],
    *,
    timeout: float,
) -> bool:
    """Stop one bundle through the same authority that started it."""

    try:
        binding = resolve_checked_runtime_binding(config, bundle_name)
    except CheckedRuntimeError as exc:
        logger.error("UnloadBundle: checked runtime configuration rejected: %s", exc)
        return False

    if binding is not None:
        for service_name in member_names:
            if event_bus is not None:
                event_bus.mark_planned_stop(service_name)
        try:
            record = await _transition_checked_bundle_runtime(
                config,
                bundle_name,
                desired_state="stopped",
                timeout=timeout,
            )
            stopped = record is not None and record.state.value == "stopped"
            if stopped and event_bus is not None:
                for service_name in member_names:
                    event_bus.emit(service_name, "unhealthy")
            return stopped
        except Exception as exc:
            logger.error("UnloadBundle: checked runtime transition failed: %s", exc)
            return False
        finally:
            for service_name in member_names:
                if event_bus is not None:
                    event_bus.clear_planned_stop(service_name)

    all_ok = True
    for service_name in member_names:
        service = services_cfg.get(service_name, {})
        unit = service.get("systemd_unit", "")
        if not unit:
            logger.warning("UnloadBundle: service '%s' has no systemd_unit", service_name)
            continue
        stopped_pid = None
        try:
            if event_bus is not None:
                event_bus.mark_planned_stop(service_name)
            if scheduler is not None:
                stopped_pid = await scheduler._get_service_main_pid(unit)
            process = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", "stop", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            await process.wait()
            if process.returncode != 0:
                logger.warning(
                    "UnloadBundle: systemctl stop %s returned rc=%s",
                    unit,
                    process.returncode,
                )
            logger.info("UnloadBundle: stopped %s", unit)
            if scheduler is not None and stopped_pid and stopped_pid > 0:
                scheduler._unregister_expected_pid(stopped_pid)
            if event_bus is not None:
                event_bus.emit(service_name, "unhealthy")
        except Exception as exc:
            logger.warning("UnloadBundle: systemctl stop %s error: %s", unit, exc)
            all_ok = False
        finally:
            if event_bus is not None:
                event_bus.clear_planned_stop(service_name)
    return all_ok


def _gpu_has_expected_tenant(
    processes: list[dict], expected_pids: set[int]
) -> bool:
    """Return True when a unit cgroup process owns a GPU telemetry tenant.

    ComfyUI opens the ROCm devices at startup but intentionally allocates no
    VRAM until its first prompt. Positive model residency is therefore a
    post-dispatch qualification signal, not a valid pre-dispatch predicate.
    """
    return any(
        int(process.get("pid", 0) or 0) in expected_pids
        for process in processes
    )


async def _rollback_started_units(started_units: list[str]) -> bool:
    """Stop newly-started units in reverse order with authoritative ComfyUI state."""
    global vram
    all_stopped = True
    for unit in reversed(started_units):
        try:
            if unit == "comfyui.service":
                if vram is None:
                    if session is None:
                        logger.error(
                            "Bundle rollback cannot initialize ComfyUI lifecycle "
                            "manager without an HTTP session"
                        )
                        all_stopped = False
                        continue
                    vram = VRAMLifecycleManager(session, logger)
                stopped = await vram.stop_comfyui(reason="bundle_rollback")
                if stopped:
                    # The failed admission is terminal. Do not restart ComfyUI
                    # solely to clear an allocator that no job ever used.
                    vram._comfyui_auto_stopped = True
                all_stopped = bool(stopped) and all_stopped
                continue
            proc = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", "stop", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            await proc.wait()
            all_stopped = proc.returncode == 0 and all_stopped
        except Exception as exc:
            logger.warning("Bundle rollback failed to stop %s: %s", unit, exc)
            all_stopped = False
    return all_stopped


def _worker_pool_commit_ready(service_name: str, service_cfg: dict) -> bool:
    """Accept the service's authoritative queue consumer for TX_VERIFY.

    Combined-Gemma's durable broker intentionally owns its concrete 12B
    services, so WorkerSupervisor suppresses their duplicate local pools.
    Other queued services must retain a running, fully-sized local pool.
    """
    if _combined_gemma_broker_owns_service(service_name, service_cfg):
        return True
    if worker_supervisor is None:
        return False
    pool = worker_supervisor._pools.get(service_name)
    return bool(
        pool is not None
        and getattr(pool, "_running", False)
        and len(getattr(pool, "_workers", []) or [])
        >= int(getattr(pool, "desired_slots", 1) or 1)
    )


async def _verify_bundle_runtime_for_commit(
    bundle_name: str,
    bundles: dict,
    services_cfg: dict,
    timeout: float = 20.0,
    allow_worker_in_flight: bool = False,
) -> tuple[bool, dict]:
    """Verify authoritative runtime evidence before ownership commit."""
    linked = _get_linked_bundles(bundle_name, bundles=bundles)
    member_bundles = list(dict.fromkeys([bundle_name, *linked]))
    service_names: list[str] = []
    gpu_ids: list[str] = []
    service_gpu_ids: list[str] = []
    reservation_gpu_ids: list[str] = []
    for name in member_bundles:
        cfg = bundles.get(name) or {}
        gpu_id = cfg.get("gpu_id")
        members = list(cfg.get("services", []) or [])
        if gpu_id and gpu_id not in gpu_ids:
            gpu_ids.append(gpu_id)
        if gpu_id:
            target = service_gpu_ids if members else reservation_gpu_ids
            if gpu_id not in target:
                target.append(gpu_id)
        for svc_name in members:
            if svc_name not in service_names:
                service_names.append(svc_name)

    deadline = time.time() + max(1.0, float(timeout))
    last: dict = {}
    while time.time() < deadline:
        expected_pids: set[int] = set()
        systemd_running = bool(service_names)
        health_http_200 = bool(service_names)
        worker_pool_ready = bool(service_names)
        readiness_ok = True
        readiness_reasons: list[str] = []
        readiness_evidence: dict[str, dict] = {}

        for svc_name in service_names:
            svc = services_cfg.get(svc_name, {}) or {}
            unit = svc.get("systemd_unit", "")
            port = int(svc.get("port", 0) or 0)
            health_path = str(svc.get("health_path") or "/health")
            readiness_required_fields = _normalize_readiness_required_fields(
                svc.get("readiness_gate_required_fields")
            )
            readiness_required_value_fields = svc.get("readiness_gate_required_value_fields")
            readiness_gate_path = (
                svc.get("readiness_gate_path")
                or svc.get("readiness_gate_path")
                or health_path
            )

            unit_active = False
            if unit:
                try:
                    proc = await asyncio.create_subprocess_exec(
                        "systemctl", "is-active", unit,
                        stdout=asyncio.subprocess.PIPE,
                        stderr=asyncio.subprocess.DEVNULL,
                    )
                    stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=5)
                    unit_active = stdout.decode(errors="replace").strip() == "active"
                except Exception:
                    unit_active = False
            systemd_running = systemd_running and unit_active

            if unit_active:
                expected_pids.update(await _get_systemd_unit_pids(unit))

            http_ok = False
            if port and session is not None:
                try:
                    async with session.get(
                        f"http://127.0.0.1:{port}{health_path}",
                        timeout=ClientTimeout(total=3, connect=1),
                    ) as resp:
                        http_ok = resp.status == 200
                except Exception:
                    http_ok = False
            health_http_200 = health_http_200 and http_ok

            # Config-backed readiness contract: when required_fields are
            # configured for this service, evaluate the readiness_gate_path
            # response via the shared evaluator. The presence of the
            # configured fields is the only claim — no residency inference.
            if readiness_required_fields and port and session is not None:
                gate_url = f"http://127.0.0.1:{port}{readiness_gate_path}"
                gate_payload = None
                gate_status = 0
                try:
                    async with session.get(
                        gate_url,
                        timeout=ClientTimeout(total=3, connect=1),
                    ) as resp:
                        gate_status = int(getattr(resp, "status", 0) or 0)
                        try:
                            gate_payload = await resp.json()
                        except Exception:
                            gate_payload = None
                except Exception:
                    gate_status = 0
                    gate_payload = None
                gate_ok, gate_reason = _evaluate_readiness_payload(
                    status=gate_status,
                    payload=gate_payload,
                    required_fields=readiness_required_fields,
                    required_value_fields=readiness_required_value_fields,
                    service_name=svc_name,
                )
                readiness_evidence[svc_name] = {
                    "url": gate_url,
                    "status": gate_status,
                    "required_fields": list(readiness_required_fields),
                    "ok": gate_ok,
                    "reason": gate_reason,
                }
                if not gate_ok:
                    readiness_ok = False
                    readiness_reasons.append(f"{svc_name}: {gate_reason}")

            pool_ok = _worker_pool_commit_ready(svc_name, svc)
            worker_pool_ready = worker_pool_ready and pool_ok

        # Before the first workflow runs, ComfyUI has a GPU tenant but lazily
        # allocates zero VRAM. Require cgroup PID presence on service-owning
        # GPUs; the qualification job proves positive model residency on both
        # service and reservation GPUs after dispatch.
        gpu_tenant_ready = bool(service_gpu_ids and expected_pids)
        if gpu_tenant_ready:
            try:
                vram_snapshot = await _poll_vram()
                for gpu_id in service_gpu_ids:
                    gpu_entry = _get_vram_entry_for_gpu(vram_snapshot, gpu_id)
                    processes = (gpu_entry or {}).get("processes", []) or []
                    if not _gpu_has_expected_tenant(processes, expected_pids):
                        gpu_tenant_ready = False
                        break
            except Exception:
                gpu_tenant_ready = False

        transition_active = False
        # This transaction already holds the physical-resource fences for
        # gpu_ids. Loading on disjoint GPUs is not a competing owner and must
        # not prevent independent idle model restoration from committing.

        worker_in_flight = _bundle_worker_in_flight(bundle_name, bundles)
        # Idle bundles may consume queued logical-group backlog immediately.
        # A generation bundle may likewise have its own WorkerPool job in
        # flight while its ComfyUI admission lease is held; that is the
        # authorized request this readiness transaction is preparing, not a
        # conflicting owner.  Every other in-flight worker remains a strict
        # fail-closed commit blocker.
        worker_in_flight_allowed = bool(
            (bundles.get(bundle_name) or {}).get("idle", False)
            or allow_worker_in_flight
        )
        ok, reasons = _bundle_commit_preconditions(
            systemd_running=systemd_running,
            health_http_200=health_http_200,
            worker_pool_ready=worker_pool_ready,
            gpu_resident=gpu_tenant_ready,
            worker_in_flight=worker_in_flight,
            transition_active=transition_active,
            allow_worker_in_flight=worker_in_flight_allowed,
        )
        if ok and not readiness_ok:
            ok = False
            reasons = list(reasons) + list(readiness_reasons)
        last = {
            "systemd_running": systemd_running,
            "health_http_200": health_http_200,
            "worker_pool_ready": worker_pool_ready,
            "gpu_resident": gpu_tenant_ready,
            "gpu_tenant_ready": gpu_tenant_ready,
            "worker_in_flight": worker_in_flight,
            "worker_in_flight_allowed": worker_in_flight_allowed,
            "transition_active": transition_active,
            "expected_pids": sorted(expected_pids),
            "gpu_ids": gpu_ids,
            "service_gpu_ids": service_gpu_ids,
            "reservation_gpu_ids": reservation_gpu_ids,
            "readiness_ok": readiness_ok,
            "readiness_reasons": list(readiness_reasons),
            "readiness_evidence": readiness_evidence,
            "reasons": reasons,
        }
        if ok:
            return True, last
        await asyncio.sleep(1)

    return False, last


def _bundle_resource_ids(
    bundle_name: str,
    *,
    bundles: dict | None = None,
) -> tuple[str, ...]:
    """Return namespaced canonical resources required by a bundle transition."""
    gpu_ids = _bundle_physical_gpu_set(bundle_name, bundles=bundles)
    return tuple(f"gpu:{gpu_id}" for gpu_id in gpu_ids)


async def _acquire_bundle_resource_lease(
    controller: Any,
    resource_ids: tuple[str, ...],
    *,
    reason: str,
):
    """Acquire the durable resource fence when the controller supports it.

    Older test doubles and compatibility controllers may only implement the
    bundle transition fence.  They retain the existing in-process guard; the
    production controller implements this method and fails closed when an
    overlapping resource is already owned.
    """
    acquire = getattr(controller, "acquire_resources", None)
    if not resource_ids or not callable(acquire):
        return None, False
    try:
        lease = await acquire(resource_ids, reason=reason)
    except Exception:
        logger.error(
            "durable resource admission unavailable (%s): %s",
            reason,
            resource_ids,
            exc_info=True,
        )
        return None, True
    if lease is None:
        logger.info(
            "durable resource admission deferred (%s): resources=%s",
            reason,
            resource_ids,
        )
    return lease, True


async def _release_bundle_resource_lease(controller: Any, lease: Any, *, reason: str) -> None:
    if lease is None:
        return
    release = getattr(controller, "release_resources", None)
    if not callable(release):
        return
    try:
        if not await release(lease):
            logger.warning("durable resource release fenced or expired (%s)", reason)
    except Exception:
        logger.error("durable resource release failed (%s)", reason, exc_info=True)


class BundleAdmissionDeferred(RuntimeError):
    """Temporary lifecycle contention; no backend attempt has occurred."""


def _admission_waits(reason) -> bool:
    """Queued callers (worker reserve, per-GPU bundle queue, ACE-Step) wait on
    a busy/foreign-held GPU instead of failing; direct callers still refuse."""
    r = str(reason)
    return r.startswith(("worker_reserve", "gpu-queue:")) or r == "acestep_job"


async def _run_bundle_transition(
    bundle_name: str,
    operation: Callable[[], Any],
    *,
    desired_state: BundleDesiredState,
    reason: str,
) -> bool:
    """Run a non-queue bundle mutation under the durable lifecycle fence."""
    controller = bundle_lifecycle_controller
    if controller is None:
        logger.error(
            "bundle transition refused without lifecycle controller for %s (%s)",
            bundle_name,
            reason,
        )
        return False
    resource_ids = _bundle_resource_ids(bundle_name)
    resource_lease, resource_guard_enabled = await _acquire_bundle_resource_lease(
        controller,
        resource_ids,
        reason=reason,
    )
    if resource_guard_enabled and resource_lease is None:
        if _admission_waits(reason):
            raise BundleAdmissionDeferred(f"resource ownership unavailable: {resource_ids}")
        return False
    try:
        try:
            transition_kwargs = {
                "desired_state": desired_state,
                "reason": reason,
            }
            if resource_lease is not None:
                transition_kwargs["resource_lease"] = resource_lease
            acquired, result, admission_reason = await controller.run_transition(
                bundle_name,
                operation,
                **transition_kwargs,
            )
        finally:
            await _release_bundle_resource_lease(
                controller,
                resource_lease,
                reason=reason,
            )
    except Exception:
        logger.error(
            "bundle transition failed for %s (%s)", bundle_name, reason, exc_info=True
        )
        return False
    if not acquired:
        logger.info(
            "bundle transition deferred for %s (%s): %s",
            bundle_name,
            reason,
            admission_reason,
        )
        if _admission_waits(reason):
            raise BundleAdmissionDeferred(f"bundle transition busy: {admission_reason}")
        return False
    if admission_reason == "stale_transition":
        logger.error(
            "bundle transition completed after its fence expired for %s (%s)",
            bundle_name,
            reason,
        )
        return False
    return bool(result)


async def _run_bundle_group_transition(
    transitions: list[tuple[str, BundleDesiredState]],
    operation: Callable[[], Any],
    *,
    reason: str,
) -> bool:
    """Run one linked-bundle mutation under the durable group fence.

    The controller owns admission, exception cleanup, and stale completion.
    Controller loss is a fail-closed lifecycle error: the mutation callback is
    never run without a durable group owner.
    """
    controller = bundle_lifecycle_controller
    if controller is None:
        logger.error(
            "bundle group transition refused without lifecycle controller (%s)",
            reason,
        )
        return False
    resource_ids = tuple(sorted({
        resource_id
        for bundle_name, _desired_state in transitions
        for resource_id in _bundle_resource_ids(bundle_name)
    }))
    resource_lease, resource_guard_enabled = await _acquire_bundle_resource_lease(
        controller,
        resource_ids,
        reason=reason,
    )
    if resource_guard_enabled and resource_lease is None:
        return False
    try:
        try:
            transition_kwargs = {"reason": reason}
            if resource_lease is not None:
                transition_kwargs["resource_lease"] = resource_lease
            acquired, result, admission_reason = await controller.run_group_transition(
                transitions,
                operation,
                **transition_kwargs,
            )
        finally:
            await _release_bundle_resource_lease(
                controller,
                resource_lease,
                reason=reason,
            )
    except Exception:
        logger.error(
            "bundle group transition failed (%s)", reason, exc_info=True
        )
        return False
    if not acquired:
        logger.info(
            "bundle group transition deferred (%s): %s",
            reason,
            admission_reason,
        )
        return False
    if admission_reason == "stale_transition":
        logger.error(
            "bundle group transition completed after its fence expired (%s)",
            reason,
        )
        return False
    return bool(result)


async def _evict_then_load_bundle(
    bundle_name: str,
    reason: str = "queue_path",
    priority: int | None = None,
) -> bool:
    """Run queue admission through the canonical fenced transition runner."""

    async def operation() -> bool:
        async with _get_bundle_admission_lock(bundle_name):
            return await _evict_then_load_bundle_unlocked(
                bundle_name,
                reason=reason,
                priority=priority,
            )

    return await _run_bundle_transition(
        bundle_name,
        operation,
        desired_state=BundleDesiredState.RUNNING,
        reason=reason,
    )


# ── Catalog 5e: warm-pool pre-load (flag GPU_MANAGER_WARM_POOL_PRELOAD) ──
# Queue look-ahead: the main dispatcher loads pending_groups[0]; this preloads
# the bundle of a LATER pending group whose durable head job is still queued,
# onto GPUs no higher-ranked group needs and no job is running on. It loads
# through _evict_then_load_bundle with scheduler-path semantics (only
# worker_reserve: reasons defer); protected services are never evicted there
# (evict_llm unloads bundles + priority<10 services, VRAM freeing skips protected).
# shortcut: on the live topology (idle member on both GPUs, protected service on one) it only
# fires when a finished generation bundle still holds every target GPU; widen
# (e.g. to idle-member slots) only with an explicit no-thrash design.
_warm_pool_memory = _warm_pool.WarmPoolMemory()


async def _warm_pool_gpu_blocker(gid: str, bundles: dict, pending_bundles: set) -> str | None:
    gs = _get_gpu_state(gid)
    reason = _warm_pool.gpu_blocker(
        gs,
        bundles=bundles,
        gpu_has_idle_member=_get_idle_bundle(gid, bundles) is not None,
        pending_bundles=pending_bundles,
    )
    if reason:
        return reason
    try:
        orch = getattr(scheduler, "_placement_orchestrator", None) if scheduler is not None else None
        if orch is not None and orch.is_idle_held(gid):
            return "idle_hold"
    except Exception:
        return "idle_hold_unknown"
    for occupant in _warm_pool.loaded_names(gs):
        if _bundle_worker_in_flight(occupant, bundles) > 0 or _auto_evict_bundle_blockers(
            occupant, bundles=bundles
        ):
            return "occupant_busy"
        try:
            if await asyncio.to_thread(_bundle_tracker_in_flight_jobs, occupant, bundles):
                return "occupant_tracker_in_flight"
        except Exception:
            return "occupant_tracker_unknown"
    return None


async def _warm_pool_fit_blocker(bundle: str, bundles: dict) -> str | None:
    snapshot = _vram_cache or None
    if not _fit_validator._snapshot_ok(snapshot):
        return "fit_no_live_vram_snapshot"
    owners = {bundle, *_get_linked_bundles(bundle, bundles=bundles)}
    try:
        findings = await asyncio.to_thread(
            _fit_validator.evaluate, _load_services_config(), snapshot, owners=owners
        )
    except Exception as exc:
        return f"fit_validator_error:{type(exc).__name__}"
    errors = sorted({f"{f['rule']}:{f['component']}" for f in findings if f.get("severity") == "error"})
    return f"fit_refused:{','.join(errors)}" if errors else None


async def _warm_pool_load(bundle: str, group: str, priority) -> bool:
    try:
        loaded = await _evict_then_load_bundle(bundle, reason=f"warm_pool:{group}", priority=priority)
    except Exception as exc:
        logger.warning("warm_pool: preload %s raised %s: %s", bundle, type(exc).__name__, exc)
        return False
    logger.info("warm_pool: preload %s %s", bundle, "loaded" if loaded else "refused by the load path")
    return bool(loaded)


async def _warm_pool_preload_tick() -> dict | None:
    """Start at most one look-ahead preload; returns what it started (tests/telemetry)."""
    mem = _warm_pool_memory
    if mem.busy() or _bundle_transition_is_active():
        return None
    # Grace, dwell hold and idle never preload: only live demand does.
    if not str((_last_next_decision or {}).get("next_decision", "")).startswith("demand:"):
        return None
    pending = [g.get("group") for g in (_last_pending_groups or []) if isinstance(g, Mapping) and g.get("group")]
    if len(pending) < 2 or any(_active_group_still_draining(g) for g in pending):
        return None
    bundles = _resolve_bundles()
    resolved = {g: _resolve_scheduler_bundle_for_group(g) for g in pending}
    pending_bundles = {b for b, _p, err in resolved.values() if b and not err}
    claimed: set = set()  # GPUs a higher-ranked pending group needs
    for idx, group in enumerate(pending):
        bundle, priority, err = resolved[group]
        gpus = set(_bundle_physical_gpu_set(bundle, bundles=bundles)) if bundle and not err else set()
        overlap = gpus & claimed
        claimed |= gpus or set(_resolve_group_target_gpus(group) or [])
        if idx == 0 or not gpus or _bundle_resident_on_all_gpus(bundle, bundles):
            continue
        head = _scheduler_precheck_head_jobs(group).get("head_job_ids") or []
        if not head:
            continue
        job_id = str(head[0])
        reason = mem.hysteresis(job_id, bundle)
        if not reason and overlap:
            reason = "gpu_needed_by_higher_pending_group"
        for gid in ([] if reason else sorted(gpus)):
            reason = await _warm_pool_gpu_blocker(gid, bundles, pending_bundles)
            if reason:
                reason = f"{gid}:{reason}"
                break
        if not reason:
            reason = await _warm_pool_fit_blocker(bundle, bundles)
        if reason:
            mem.log_once(logger, job_id, reason, "warm_pool: skip %s for job %s (group %s): %s",
                         bundle, job_id, group, reason)
            continue
        mem.record(job_id, bundle)
        mem.log_once(logger, job_id, "preload", "warm_pool: preload %s on %s for queued job %s (group %s)",
                     bundle, sorted(gpus), job_id, group)
        mem.task = asyncio.create_task(_warm_pool_load(bundle, group, priority))
        return {"group": group, "bundle": bundle, "job_id": job_id}
    return None


async def _active_resident_unit(gpu_id: str) -> str | None:
    """First active unit in gpu_devices.<gpu>.resident_units (foreign tenants such as Breccia)."""
    gdev = ((_load_services_config().get("gpu_devices") or {}).get(gpu_id)) or {}
    for unit in gdev.get("resident_units") or []:
        try:
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", "--quiet", unit,
                stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL,
            )
            if await asyncio.wait_for(proc.wait(), timeout=3) == 0:
                return unit
        except Exception:
            return unit  # cannot tell: fail closed, never risk the tenant's VRAM
    return None


async def _evict_then_load_bundle_unlocked(
    bundle_name: str,
    reason: str = "queue_path",
    priority: int | None = None,
) -> bool:
    """Coordinated multi-GPU eviction before bundle load.

    Resolves all GPUs the bundle touches (primary + linked_to/linked_from),
    pre-checks each for a higher-priority loaded bundle, evicts LLMs in
    sequence, then calls _load_bundle. Used by the queue-path entry points
    so that a request arriving via nginx actually frees the VRAM it needs
    before sd-server / comfyui / acestep tries to allocate.

    Pre-check policy (priority-aware, NOT VRAM-threshold):
      - If a GPU has a different bundle already loaded with
        ``bundle_priority > our priority``, refuse to evict (refuse to
        disrupt a higher-priority workload).
      - If no bundle is loaded, or the loaded bundle has lower-or-equal
        priority, proceed: ``_load_bundle`` / ``_unload_bundle`` will
        handle the swap, and ``evict_llm`` will free the idle LLM.

    Per the user's design: if any GPU is in a bad state to evict, we
    do NOT evict any of them. Coordinated, not just primary-GPU-only.

    Slice B: also hold the physical-resource-set admission lock so a
    second bundle touching the same GPUs (e.g. Krea vs Qwen both on
    {gpu_primary, gpu_secondary}) cannot start concurrently. The lock is held for
    the entire eviction+load transaction. ``evict_llm() == False`` is
    treated as structured admission denial — no systemctl start follows.
    """
    bundles = _resolve_bundles()
    bundle = bundles.get(bundle_name)
    if bundle is None:
        return False
    # Resolve our priority the same way _load_bundle does, so the
    # pre-check matches what the actual load will request.
    effective_priority = priority if priority is not None else bundle.get("priority", 5)
    primary_gpu = bundle.get("gpu_id")
    # S1: consolidated linked-walk via _collect_linked_gpus.
    secondary_gpus = [
        g for g in _collect_linked_gpus(
            bundle, bundles, bundle_name=bundle_name
        )
        if g and g != primary_gpu
    ]
    target_gpus = [g for g in [primary_gpu] + secondary_gpus if g]

    # Slice B: acquire the physical-resource-set admission lock for the
    # entire linked-group eviction+load transaction. Two bundles sharing
    # the same GPUs (Krea vs Qwen both touch {gpu_primary, gpu_secondary}) must
    # serialize through this lock.
    physical_gpu_set = _bundle_physical_gpu_set(bundle_name, bundles=bundles)
    physical_lock = (
        _get_physical_resource_lock(physical_gpu_set)
        if physical_gpu_set else None
    )

    async def _transaction():
        # Priority-aware pre-check: only refuse if a HIGHER-priority bundle
        # is already loaded on the GPU. The idle LLM is what we are SUPPOSED
        # to evict, so we deliberately do NOT block on VRAM amount here.
        sched_obj = globals().get("scheduler")
        placement_orch = getattr(sched_obj, "_placement_orchestrator", None) if sched_obj is not None else None

        for gid in target_gpus:
            resident = await _active_resident_unit(gid)
            if resident:
                if _admission_waits(reason):
                    raise BundleAdmissionDeferred(f"resident tenant {resident} holds {gid}")
                # shortcut: other entry points refuse (job fails) instead of a queued WAIT; resident tenants are never stopped here.
                logger.warning(
                    f"queue_path: GPU {gid} holds resident tenant '{resident}' - "
                    f"refusing to load bundle {bundle_name} (resident units are never stopped)"
                )
                return False
            if placement_orch is not None and placement_orch.is_idle_held(gid):
                logger.warning(
                    f"queue_path: GPU {gid} is held by active idle hold - refusing to evict for bundle {bundle_name}"
                )
                return False

            gs = _get_gpu_state(gid)
            if (
                gs is not None
                and gs.loaded_bundle
                and gs.loaded_bundle != bundle_name
                and gs.bundle_priority > effective_priority
            ):
                logger.warning(
                    f"queue_path: GPU {gid} has higher-priority bundle "
                    f"'{gs.loaded_bundle}' (priority {gs.bundle_priority} > "
                    f"{effective_priority}) - refusing to evict for bundle {bundle_name}"
                )
                return False

        # Plan 4.7: an evict_only_when_idle occupant is replaced only by a
        # higher-priority non-idle bundle, and only once it is idle.
        for gid in target_gpus:
            for occupant in _protected_bundles_on_gpu(gid, bundles, bundle_name):
                refusal = _protected_occupant_refusal(
                    bundle_name, bundle, occupant, bundles.get(occupant) or {}
                )
                if refusal is not None:
                    logger.warning(
                        f"queue_path: GPU {gid} keeps '{occupant}' - {refusal}; "
                        f"refusing to evict for bundle {bundle_name}"
                    )
                    return False
                deadline = time.monotonic() + _EVICT_ONLY_WHEN_IDLE_WAIT_SECONDS
                while await _bundle_busy(occupant, bundles):
                    if _admission_waits(reason):
                        raise BundleAdmissionDeferred(
                            f"{occupant} on {gid} is serving a request"
                        )
                    if time.monotonic() >= deadline:
                        logger.warning(
                            f"queue_path: '{occupant}' on GPU {gid} still busy after "
                            f"{_EVICT_ONLY_WHEN_IDLE_WAIT_SECONDS:.0f}s - refusing to "
                            f"evict for bundle {bundle_name}"
                        )
                        return False
                    await asyncio.sleep(_EVICT_ONLY_WHEN_IDLE_POLL_SECONDS)

        # Begin a backend-local drain only after the priority precheck passes.
        # The logical Gemma routing group remains live through CPU/secondary GPU members.
        planned_services: list[str] = []
        for gid in target_gpus:
            gs = _get_gpu_state(gid)
            loaded_name = getattr(gs, 'loaded_bundle', None) if gs is not None else None
            loaded_cfg = bundles.get(loaded_name, {}) if loaded_name else {}
            if loaded_cfg.get('idle') and event_bus is not None:
                for svc_name in loaded_cfg.get('services', []):
                    event_bus.mark_planned_stop(svc_name)
                    planned_services.append(svc_name)
                    logger.info(
                        f'Logical drain: marked {svc_name} planned_stop before '
                        f'swap to {bundle_name}'
                    )

        for svc_name in planned_services:
            drained = await _drain_combined_gemma_member_before_stop(svc_name)
            if not drained:
                logger.warning(
                    "queue_path: drain before bundle admission denied for %s "
                    "(bundle=%s, planned_services=%s)",
                    svc_name,
                    bundle_name,
                    planned_services,
                )
                if event_bus is not None:
                    for marked_name in planned_services:
                        event_bus.clear_planned_stop(marked_name)
                return False

        # Evict each GPU in order (primary first). Phase 5.1.6: pass
        # skip_bundle_name so evict_llm doesn't unload the very bundle
        # we're about to (re)load — the start/stop race otherwise kills
        # the new instance before its port comes up.
        # Slice B: track per-GPU refusal. A False from evict_llm is
        # treated as structured admission denial — the entire coordinated
        # swap is aborted (no systemctl start, no further evictions on
        # remaining GPUs). This is the fail-closed contract for Task 3.
        eviction_denied = False
        denied_reason = ""
        # While doing this coordinated swap, pause idle auto-restoration / crash
        # recovery. Otherwise the idle watchdog can see the intentionally-stopped
        # LLM as a crash and restart it before the generation bundle loads.
        sched_obj = globals().get("scheduler")
        prev_pause = None
        if sched_obj is not None:
            prev_pause = (
                getattr(sched_obj, "_coexistence_paused", False),
                getattr(sched_obj, "_coexistence_pause_expires", 0.0),
                getattr(sched_obj, "_coexistence_paused_at", 0.0),
            )
            sched_obj._coexistence_paused = True
            sched_obj._coexistence_pause_expires = 0.0
            sched_obj._coexistence_paused_at = time.time()
        try:
            for gid in target_gpus:
                try:
                    ev_ok = await _evict_llm_unless_protected_busy(
                        vram,
                        reason=f"{reason}:{bundle_name}",
                        target_gpu=gid,
                        skip_bundle_name=bundle_name,
                        admission_authorized=True,
                    )
                except Exception as e:
                    logger.warning(f"queue_path: evict_llm on {gid} raised: {e}")
                    return False
                if not ev_ok:
                    eviction_denied = True
                    denied_reason = (
                        f"evict_llm refused on {gid} (bundle={bundle_name}); "
                        "no systemctl start follows"
                    )
                    logger.warning(
                        f"queue_path: FAIL-CLOSED — {denied_reason}"
                    )
                    return False
            # Now load
            return await _load_bundle(
                bundle_name,
                priority=effective_priority,
                _physical_transaction_owned=physical_lock is not None,
            )
        finally:
            if event_bus is not None:
                for svc_name in planned_services:
                    event_bus.clear_planned_stop(svc_name)
            if sched_obj is not None and prev_pause is not None:
                (
                    sched_obj._coexistence_paused,
                    sched_obj._coexistence_pause_expires,
                    sched_obj._coexistence_paused_at,
                ) = prev_pause

    if physical_lock is not None:
        async with _get_dual_swap_lock():
            async with physical_lock:
                return await _transaction()
    async with _get_dual_swap_lock():
        return await _transaction()


def _reconcile_loaded_configured_idle_bundle(
    bundle: Mapping[str, Any], config: Mapping[str, Any]
) -> bool:
    """Clear eviction latches after a configured per-GPU idle bundle loads."""
    scheduling = config.get("scheduling") or {}
    idle_services = scheduling.get("idle_services") or {}
    if not isinstance(idle_services, Mapping):
        return False
    gpu_id = str(bundle.get("gpu_id") or "").strip()
    configured_idle = str(idle_services.get(gpu_id) or "").strip()
    member_names = {
        str(name).strip()
        for name in (bundle.get("services") or [])
        if str(name).strip()
    }
    if not gpu_id or not configured_idle or configured_idle not in member_names:
        return False
    if vram is None:
        return False
    vram.mark_llm_evicted(False, source="_load_bundle:configured_idle")
    gpu_evicted = getattr(vram, "_gpu_evicted", None)
    if isinstance(gpu_evicted, dict):
        gpu_evicted.pop(gpu_id, None)
    return True


async def _load_bundle(
    bundle_name: str,
    priority: int | None = None,
    timeout: float = 120.0,
    _visited: set[str] | None = None,
    _physical_transaction_owned: bool = False,
    allow_worker_in_flight: bool = False,
) -> bool:
    """Load a bundle and all its linked bundles.

    Steps:
      1. Resolve the bundle config from ``_resolve_bundles()``.
      2. If ``linked_to`` is non-empty, load every linked bundle first
         (recursively).  All linked bundles must succeed.
      3. Start each service in the bundle via ``systemctl start``.
      4. Wait for every service port to respond (TCP connect) within
         *timeout* seconds.
      5. Update per-GPU state (``loaded_bundles``, ``current_priority``).
      6. On success, resolve any pending ``BundleRequestQueue`` entries
         for this bundle.  On failure, reject them with False.

    Returns True when all services in the bundle (and linked bundles)
    are healthy, False on any failure.
    """
    if _visited is None:
        _visited = set()
    visited_before = set(_visited)
    if bundle_name in _visited:
        logger.debug(
            f"LoadBundle: '{bundle_name}' already visited in linked load walk; skipping recursion"
        )
        return True
    _visited.add(bundle_name)

    bundles = _resolve_bundles()
    bundle = bundles.get(bundle_name)
    if bundle is None:
        logger.error(f"LoadBundle: unknown bundle '{bundle_name}'")
        return False

    gpu_id = bundle.get("gpu_id")
    bundle_priority = priority if priority is not None else bundle.get("priority", 5)
    bundle_timeout = bundle.get("timeout", timeout)
    config = _load_services_config()
    services_cfg = config.get("services", {})
    member_names = bundle.get("services", [])

    # Slice B: acquire the physical-resource-set admission lock so a
    # second bundle touching the same GPUs cannot start its systemd
    # units concurrently. The lock is held for the entire
    # _load_bundle transaction (linked-bundle recursion, systemd start,
    # port readiness, TX_VERIFY, and commit). The lock is released by
    # _unload_bundle / authoritative reconcile when the worker lease,
    # backend prompt, systemd cgroup, and port are all terminal/absent.
    physical_gpu_set = _bundle_physical_gpu_set(bundle_name, bundles=bundles)
    physical_lock = (
        _get_physical_resource_lock(physical_gpu_set)
        if physical_gpu_set else None
    )
    if (
        physical_lock is not None
        and physical_lock.locked()
        and not _physical_transaction_owned
    ):
        logger.warning(
            f"LoadBundle: REFUSING '{bundle_name}' — physical resource "
            f"lock {physical_gpu_set!r} is already held by another "
            "bundle in mid-load"
        )
        q = _get_bundle_request_queue(bundle_name)
        await q.resolve_all(success=False)
        return False

    # Hard admission guard for display-sensitive GPUs. This runs before any
    # systemd start so an already-over-cap RX is never asked to load more work.
    if gpu_id:
        cap_ok, cap_reason = await _check_gpu_vram_ceiling(
            gpu_id, phase=f"bundle-admission:{bundle_name}"
        )
        if not cap_ok:
            logger.error(f"LoadBundle: REFUSING '{bundle_name}' — {cap_reason}")
            q = _get_bundle_request_queue(bundle_name)
            await q.resolve_all(success=False)
            return False
    await asyncio.to_thread(_fit_validator.warn_if_unfit, logger, config, _vram_cache or None,
                            [bundle_name], project_root=PROJECT_ROOT)

    # BUGFIX: Mark GPU as loading so the watchdog does not race the load.
    _gs_obj = _get_gpu_state(gpu_id) if gpu_id else None
    if _gs_obj is not None:
        _gs_obj.state = "loading"
    # Phase 0: route through setter (single source of truth).
    if _gs_obj is not None and scheduler is not None and gpu_id in getattr(scheduler, "_gpu_state", {}):
        _gs_obj.set_loading(True, source="_load_bundle")
    # M3: stamp at start so a partially-failed load still extends
    # the idle window for whatever IS currently loaded on this GPU.
    # Without this, a previous load 5min ago could trigger auto-
    # evict between retries of a slow load.
    if _gs_obj is not None:
        _gs_obj.touch_activity(source="_load_bundle:start")

    logger.info(
        f"LoadBundle: '{bundle_name}' on GPU {gpu_id} "
        f"(priority={bundle_priority}, services={member_names})"
    )

    # ── Steps 1-5: Load linked bundles, start services, wait healthy,
    #     update state, resolve requests. All wrapped in try/finally
    #     so the "loading" state is always cleared, even on any of the
    #     four return False paths (linked bundle fail, linked port
    #     not ready, primary services fail, primary port not ready)
    #     and on any unhandled exception.
    # Def-1: per-bundle asyncio.Lock prevents concurrent in-process
    # _load_bundle calls for the same bundle (e.g. /v1/submit and
    # MCP submit_generation landing on the same bundle in the same
    # tick). Per-bundle-name, not per-GPU: sulphur-diffusion +
    # sulphur-encoder must be serialised as a pair.
    _bundle_lock = _get_bundle_load_lock(bundle_name)
    async with _bundle_lock:
        try:
            # ── Step 1: Load linked bundles first ──────────────────────────
            # Walk BOTH linked_to AND linked_from so the sulphur-encoder↔
            # sulphur-diffusion cross-GPU pair is loaded symmetrically.
            linked = _get_linked_bundles(bundle_name, bundles=bundles)
            if linked:
                logger.info(
                    f"LoadBundle: '{bundle_name}' has {len(linked)} linked bundle(s): {linked}"
                )
                linked_ok = True
                for linked_name in linked:
                    if linked_name not in bundles:
                        logger.error(
                            f"LoadBundle: linked bundle '{linked_name}' not found"
                        )
                        linked_ok = False
                        break
                    # Linked bundles share the same priority
                    ok = await _load_bundle(
                        linked_name,
                        priority=bundle_priority,
                        timeout=bundle_timeout,
                        _visited=_visited,
                        _physical_transaction_owned=_physical_transaction_owned,
                        allow_worker_in_flight=allow_worker_in_flight,
                    )
                    if not ok:
                        logger.error(
                            f"LoadBundle: linked bundle '{linked_name}' failed to load"
                        )
                        linked_ok = False
                        break

                if not linked_ok:
                    _transition_linked_bundle_state(
                        bundle_name, [], source="_load_bundle:linked_fail"
                    )
                    # Reject any pending requests for this bundle
                    q = _get_bundle_request_queue(bundle_name)
                    await q.resolve_all(success=False)
                    return False

                # Wait for all linked bundles to be ready (they load concurrently
                # but we still verify). If a linked bundle points back at a parent
                # already in the load stack, do not wait for the parent's ports
                # here; the parent has not started its services yet.
                for linked_name in linked:
                    if linked_name in visited_before:
                        logger.debug(
                            f"LoadBundle: linked bundle '{linked_name}' was already in load stack; "
                            "skipping readiness wait to avoid parent-child deadlock"
                        )
                        continue
                    linked_bundle = bundles.get(linked_name, {})
                    for svc_name in linked_bundle.get("services", []):
                        svc = services_cfg.get(svc_name, {})
                        linked_port = svc.get("port")
                        if linked_port:
                            ready = await _wait_port_ready(svc_name, int(linked_port), bundle_timeout)
                            if not ready:
                                logger.error(
                                    f"LoadBundle: linked service '{svc_name}' "
                                    f"port {linked_port} not ready"
                                )
                                _transition_linked_bundle_state(
                                    bundle_name, [], source="_load_bundle:linked_port_fail"
                                )
                                q = _get_bundle_request_queue(bundle_name)
                                await q.resolve_all(success=False)
                                return False
                            if event_bus:
                                event_bus.emit(svc_name, "healthy")
                                logger.debug(f"LoadBundle: emitted healthy event for linked {svc_name}")

            # Reservation-only linked roles (for example krea2-encoder on
            # secondary GPU) run inside the primary service process. They have no
            # independent systemd service or worker pool, so defer both
            # verification and ownership commit to the parent linked-group
            # transaction.
            if not member_names and visited_before:
                logger.info(
                    "LoadBundle: reservation-only linked role '%s' deferred "
                    "to parent transaction",
                    bundle_name,
                )
                return True

            # ── Step 2: Start through the checked host boundary when the
            # bundle declares runtime_instance/runtime_profile. Unmigrated
            # bundles retain the established launcher until their profile is
            # explicitly qualified.
            all_ok, started_units, checked_runtime_used = await _start_bundle_members(
                config,
                bundle_name,
                list(member_names),
                services_cfg,
                timeout=float(bundle_timeout),
            )

            if not all_ok:
                # Rollback: stop any services we started
                await _rollback_bundle_start(
                    config,
                    bundle_name,
                    list(member_names),
                    started_units,
                    checked_runtime_used=checked_runtime_used,
                    timeout=float(bundle_timeout),
                )
                q = _get_bundle_request_queue(bundle_name)
                await q.resolve_all(success=False)
                return False

            # ── Step 2.5 (Phase 5.2.19): close TOCTOU window ─────────────
            # systemd-start returns when the process exits, but PyTorch
            # CUDA caching allocator may still hold VRAM for up to ~1s
            # after the prior bundle's stop (verified in
            # RESEARCH_PHASE_5_2_19_EVIDENCE.md). Wait until the new
            # bundle's target VRAM is actually free before HTTP probe.
            #
            # Per-bundle vram_target_mib (default 4096):
            #   comfyui=8192, sulphur-diffusion=16384,
            #   acestep=10240
            #
            # Linked bundles share the same priority and are loaded first
            # in Step 1, so by the time we reach here, all linked-bundle
            # service starts have completed. Atomic multi-GPU: we wait
            # on the bundle's primary gpu_id plus any GPUs from
            # linked bundles. Does NOT fail the load on timeout — OOM
            # watchdog catches real failure (5.2.11 bug pattern).
            vram_target = bundle.get("vram_target_mib", 4096)
            gpus_to_wait = [gpu_id] if gpu_id else []
            try:
                for linked_name in linked:
                    linked_bundle = bundles.get(linked_name, {})
                    linked_gpu = linked_bundle.get("gpu_id")
                    if linked_gpu and linked_gpu not in gpus_to_wait:
                        gpus_to_wait.append(linked_gpu)
            except Exception:
                pass
            for g in gpus_to_wait:
                try:
                    global vram
                    if vram is None:
                        vram = VRAMLifecycleManager(session, logger)
                    ok = await vram.wait_for_free_mib(g, vram_target, timeout_s=5.0)
                    if ok:
                        logger.info(
                            f"LoadBundle: VRAM free ≥ {vram_target} MiB on {g} "
                            f"before HTTP probe"
                        )
                except Exception as e:
                    logger.warning(f"LoadBundle: wait_for_free_mib({g}) error: {e}")

            # ── Step 3: Wait for all services to be healthy ─────────────────
            for svc_name in member_names:
                svc = services_cfg.get(svc_name, {})
                port = svc.get("port")
                if not port:
                    logger.error(f"LoadBundle: service '{svc_name}' has no port")
                    all_ok = False
                    break
                ready = await _wait_port_ready(svc_name, int(port), bundle_timeout)
                if not ready:
                    logger.error(
                        f"LoadBundle: service '{svc_name}' port {port} "
                        f"not ready after {bundle_timeout}s"
                    )
                    all_ok = False
                    break
                logger.info(f"LoadBundle: {svc_name} port {port} ready")
                if event_bus:
                    event_bus.emit(svc_name, "healthy")
                    logger.debug(f"LoadBundle: emitted healthy event for {svc_name}")

            if all_ok:
                for g in gpus_to_wait:
                    cap_ok, cap_reason = await _check_gpu_vram_ceiling(
                        g, phase=f"bundle-post-load:{bundle_name}"
                    )
                    if not cap_ok:
                        logger.error(
                            f"LoadBundle: '{bundle_name}' exceeded VRAM admission cap — {cap_reason}"
                        )
                        all_ok = False
                        break

            # A healthy port is not enough for a broker-owned LLM member. Its
            # durable lifecycle record must also complete the generation-fenced
            # OFFLINE -> JOINING -> READY_ACCEPTING transition before this
            # bundle can commit ownership or accept work.
            if all_ok:
                all_ok = await _rejoin_combined_gemma_bundle_members_after_start(
                    list(member_names),
                    services_cfg,
                    timeout=float(bundle_timeout),
                )

            # TX_VERIFY: checked profiles already carry host-supplied process,
            # model and accepting evidence. Legacy bundles retain the existing
            # systemd/HTTP/worker/PID verification path.
            if all_ok:
                if checked_runtime_used:
                    deadline = time.monotonic() + min(30.0, float(bundle_timeout))
                    admission_errors = ["runtime evidence not checked"]
                    worker_ready = False
                    while time.monotonic() < deadline:
                        admission_errors = await _get_checked_runtime_controller().admission_errors_if_configured(
                            config, bundle_name
                        ) or []
                        worker_ready = all(
                            _worker_pool_commit_ready(name, services_cfg.get(name, {}))
                            for name in member_names
                        )
                        if not admission_errors and worker_ready:
                            break
                        await asyncio.sleep(0.5)
                    verified = not admission_errors and worker_ready
                    evidence = {
                        "authority": "checked-runtime",
                        "runtime_admission_errors": admission_errors or [],
                        "worker_pool_ready": worker_ready,
                    }
                else:
                    verified, evidence = await _verify_bundle_runtime_for_commit(
                        bundle_name,
                        bundles,
                        services_cfg,
                        timeout=min(30.0, float(bundle_timeout)),
                        allow_worker_in_flight=(
                            allow_worker_in_flight
                            or bool(_comfyui_admission_in_flight())
                        ),
                    )
                if not verified:
                    logger.error(
                        "LoadBundle: TX_VERIFY failed for '%s': %s",
                        bundle_name,
                        evidence,
                    )
                    all_ok = False
                else:
                    logger.info(
                        "LoadBundle: TX_VERIFY passed for '%s': %s",
                        bundle_name,
                        evidence,
                    )

            if not all_ok:
                _transition_linked_bundle_state(
                    bundle_name, [], source="_load_bundle:rollback"
                )
                # Roll back services started by this bundle. A post-load ceiling
                # violation must not leave a display GPU resident above cap.
                await _rollback_bundle_start(
                    config,
                    bundle_name,
                    list(member_names),
                    started_units,
                    checked_runtime_used=checked_runtime_used,
                    timeout=float(bundle_timeout),
                )
                q = _get_bundle_request_queue(bundle_name)
                await q.resolve_all(success=False)
                return False

            # ── Step 4: Atomically commit per-GPU ownership ────────────────
            if gpu_id:
                gpu_state = _get_gpu_state(gpu_id)
                try:
                    _transition_linked_bundle_state(
                        bundle_name, [bundle_name], source="_load_bundle"
                    )
                    if scheduler is not None and gpu_id in getattr(scheduler, "_gpu_state", {}):
                        gpu_state.set_evicting(False, source="_load_bundle")
                        gpu_state.set_draining(False, source="_load_bundle")
                except Exception as commit_error:
                    logger.exception(
                        "LoadBundle: TX_COMMIT failed for '%s': %s",
                        bundle_name,
                        commit_error,
                    )
                    _transition_linked_bundle_state(
                        bundle_name, [], source="_load_bundle:commit_rollback"
                    )
                    await _rollback_bundle_start(
                        config,
                        bundle_name,
                        list(member_names),
                        started_units,
                        checked_runtime_used=checked_runtime_used,
                        timeout=float(bundle_timeout),
                    )
                    q = _get_bundle_request_queue(bundle_name)
                    await q.resolve_all(success=False)
                    return False

            # ComfyUI lifecycle caches become running only after the bundle
            # ownership transaction has committed and the bundle's exact
            # systemd unit still says active.
            comfyui_units = [
                str((services_cfg.get(svc_name) or {}).get("systemd_unit") or "")
                for svc_name in member_names
                if svc_name in {"comfyui", "comfyui-qwen"}
            ]
            if comfyui_units:
                if vram is None and session is not None:
                    vram = VRAMLifecycleManager(session, logger)
                _running_committed = (
                    vram is not None
                    and await vram.mark_comfyui_running_after_commit(
                        unit=comfyui_units[0]
                    )
                )
                if not _running_committed:
                    if session is None:
                        logger.error(
                            "LoadBundle: cannot commit ComfyUI running state without HTTP session"
                        )
                    _transition_linked_bundle_state(
                        bundle_name, [], source="_load_bundle:running_state_rollback"
                    )
                    await _rollback_bundle_start(
                        config,
                        bundle_name,
                        list(member_names),
                        started_units,
                        checked_runtime_used=checked_runtime_used,
                        timeout=float(bundle_timeout),
                    )
                    q = _get_bundle_request_queue(bundle_name)
                    await q.resolve_all(success=False)
                    return False

            # ── Step 5: Resolve pending requests ────────────────────────────
            q = _get_bundle_request_queue(bundle_name)
            await q.resolve_all(success=True)

            _reconcile_loaded_configured_idle_bundle(bundle, config)

            logger.info(
                f"LoadBundle: '{bundle_name}' loaded successfully on GPU {gpu_id} "
                f"(priority={bundle_priority})"
            )

            # Phase 5.1 P0-1: stamp bundle_loaded_at so auto-evict skips this
            # bundle for BUNDLE_LOAD_GRACE_SECONDS (worker spin-up window).
            if _gs_obj is not None:
                _gs_obj.bundle_loaded_at = time.time()
                # Phase 5.2.4: also stamp the post-load grace deadline.
                # The auto-evict uses this to skip bundles that are still
                # in their post-load grace window (e.g. ComfyUI warming
                # up after port-ready but before HTTP handler is ready).
                # Read from bundle config (preferred) or per-service
                # config (5.2.2 compat). Default 0 = no grace.
                try:
                    _bundle_cfg = bundles.get(bundle_name, {}) or {}
                    # member_names is the bundle's services list (set at top
                    # of _load_bundle). Fall back to the bundle's gpu_id's
                    # idle service if member_names is empty.
                    _first_svc = (member_names or [""])[0] if member_names else ""
                    _svc_cfg = services_cfg.get(_first_svc, {}) or {}
                    _grace_s = int(
                        _bundle_cfg.get("post_load_grace_seconds")
                        or _svc_cfg.get("post_load_grace_seconds")
                        or 0
                    )
                except Exception:
                    _grace_s = 0
                if _grace_s > 0:
                    _gs_obj.bundle_post_load_grace_at = _gs_obj.bundle_loaded_at + _grace_s
            # Phase 4g: stamp activity so auto-evict doesn't immediately unload
            # a freshly-loaded bundle before its first job runs.
            if _gs_obj is not None:
                _gs_obj.touch_activity(source="_load_bundle")
                # Phase 4h.1: also stamp activity on linked bundles' GPUs so
                # multi-GPU jobs don't auto-evict the secondary GPU.
                # S1: consolidated linked-walk via _collect_linked_gpus.
                for _lg in _collect_linked_gpus(bundle, bundles):
                    if _lg == gpu_id:
                        continue
                    _lgs = _get_gpu_state(_lg)
                    if _lgs is not None:
                        _lgs.touch_activity(source="_load_bundle:linked")
            return True
        finally:
            # BUGFIX: Always clear the loading state, even on any of the
            # four return False paths (linked bundle fail, linked port
            # not ready, primary services fail, primary port not ready)
            # and on any unhandled exception. Without this, the watchdog
            # would permanently skip this GPU until GPU Manager restart.
            if _gs_obj is not None:
                _gs_obj.state = (
                    "loaded" if list(getattr(_gs_obj, "loaded_bundles", []) or [])
                    else "idle"
                )
            # Clear transaction flags on every linked GPU on both commit and
            # rollback. Leaving evicting=True after TX_VERIFY failure blocks
            # idle-service restoration indefinitely.
            for _tx_gpu in _collect_linked_gpus(bundle, bundles):
                _tx_state = _get_gpu_state(_tx_gpu)
                if _tx_state is None:
                    continue
                _tx_state.set_loading(False, source="_load_bundle:finally")
                _tx_state.set_evicting(False, source="_load_bundle:finally")
                _tx_state.set_draining(False, source="_load_bundle:finally")


async def _unload_bundle(bundle_name: str) -> bool:
    """Unload a bundle by stopping all its services.

    Stops every service in the bundle via ``systemctl stop`` and
    updates per-GPU state.  Does NOT unload linked bundles — they
    may be needed by other bundles.

    Returns True if all services were stopped successfully.
    """
    bundles = _resolve_bundles()
    bundle = bundles.get(bundle_name)
    if bundle is None:
        logger.error(f"UnloadBundle: unknown bundle '{bundle_name}'")
        return False

    gpu_id = bundle.get("gpu_id")
    member_names = bundle.get("services", [])
    config = _load_services_config()
    services_cfg = config.get("services", {})
    native_helper_token_file = None
    if any(
        isinstance(services_cfg.get(member_name), Mapping)
        and (services_cfg.get(member_name) or {}).get("native_task_host_url")
        for member_name in member_names
    ):
        try:
            native_helper_token_file = _required_native_helper_token_file()
        except Exception as exc:
            logger.warning("UnloadBundle: native-task helper credential unavailable: %s", exc)
            return False

    for member_name in member_names:
        host_url = (services_cfg.get(member_name) or {}).get("native_task_host_url")
        if host_url:
            from native_task_client import native_host_has_unresolved
            if session is None or await native_host_has_unresolved(
                session, host_url, service_token_file=native_helper_token_file
            ):
                logger.warning("UnloadBundle: %s retains an unresolved native task", bundle_name)
                return False

    logger.info(
        f"UnloadBundle: '{bundle_name}' from GPU {gpu_id} "
        f"(services={member_names})"
    )

    all_ok = await _stop_bundle_members(
        config,
        bundle_name,
        list(member_names),
        services_cfg,
        timeout=float(bundle.get("timeout", 120.0)),
    )
    if not all_ok:
        # Failed/unknown stop is not evidence that residency disappeared.
        return False

    # ── Update per-GPU state ────────────────────────────────────────
    if gpu_id:
        gpu_state = _get_gpu_state(gpu_id)
        remaining = [
            b for b in list(getattr(gpu_state, "loaded_bundles", []) or [])
            if b != bundle_name
        ]
        gpu_state.set_loaded_bundles(remaining, source="_unload_bundle")
        if gpu_state.loaded_bundle == bundle_name or gpu_state.loaded_bundle not in remaining:
            gpu_state.loaded_bundle = None
            gpu_state.bundle_priority = 0
        if remaining:
            gpu_state.state = "loaded"
            surviving_priority = max(
                (int((bundles.get(name) or {}).get("priority", 0) or 0)
                 for name in remaining),
                default=0,
            )
            gpu_state.set_current_priority(surviving_priority, source="_unload_bundle")
        else:
            gpu_state.state = "idle"
            gpu_state.set_current_priority(0, source="_unload_bundle")

    # Reservation-only dependents have no service process and therefore cannot
    # release themselves.  When their declared primary unloads, remove only
    # those dependent audit/ownership entries while preserving unrelated idle
    # bundles and real linked services that may still be in use.
    for linked_name in _get_linked_bundles(bundle_name, bundles=bundles):
        linked_bundle = bundles.get(linked_name) or {}
        if linked_bundle.get("services"):
            continue
        if bundle_name not in set(linked_bundle.get("linked_from", []) or []):
            continue
        linked_gpu_id = linked_bundle.get("gpu_id")
        if not linked_gpu_id:
            continue
        linked_state = _get_gpu_state(linked_gpu_id)
        linked_current = list(
            getattr(linked_state, "loaded_bundles", []) or []
        )
        if linked_name not in linked_current:
            continue

        def _link_names(value: object) -> set[str]:
            if isinstance(value, str):
                return {value}
            if isinstance(value, (list, tuple, set)):
                return {str(item) for item in value if item}
            return set()

        shared_loaded_owner = False
        declared_owners = _link_names(linked_bundle.get("linked_from"))
        for candidate_name, candidate_bundle in bundles.items():
            if candidate_name in {bundle_name, linked_name}:
                continue
            candidate_gpu_id = (candidate_bundle or {}).get("gpu_id")
            if not candidate_gpu_id:
                continue
            try:
                candidate_state = _get_gpu_state(candidate_gpu_id)
            except Exception:
                continue
            candidate_loaded = set(
                getattr(candidate_state, "loaded_bundles", []) or []
            )
            if candidate_name not in candidate_loaded:
                continue
            candidate_links = _link_names(
                (candidate_bundle or {}).get("linked_to")
            )
            if linked_name in candidate_links or candidate_name in declared_owners:
                shared_loaded_owner = True
                logger.info(
                    "UnloadBundle: preserving reservation-only linked bundle "
                    f"'{linked_name}' because loaded bundle '{candidate_name}' "
                    "still declares ownership"
                )
                break
        if shared_loaded_owner:
            continue

        linked_remaining = [
            name for name in linked_current if name != linked_name
        ]
        linked_state.set_loaded_bundles(
            linked_remaining, source="_unload_bundle:reservation_release"
        )
        if linked_state.loaded_bundle == linked_name:
            linked_state.loaded_bundle = None
            linked_state.bundle_priority = 0
        if linked_remaining:
            linked_state.state = "loaded"
            linked_priority = max(
                (int((bundles.get(name) or {}).get("priority", 0) or 0)
                 for name in linked_remaining),
                default=0,
            )
            linked_state.set_current_priority(
                linked_priority, source="_unload_bundle:reservation_release"
            )
        else:
            linked_state.state = "idle"
            linked_state.set_current_priority(
                0, source="_unload_bundle:reservation_release"
            )

    logger.info(
        f"UnloadBundle: '{bundle_name}' unloaded from GPU {gpu_id} "
        f"(ok={all_ok})"
    )
    return all_ok


def _active_bundle_children(bundle_name: str, bundles: dict) -> set[str]:
    """Find linked child bundles whose own GPU has accepted worker activity."""
    children = set(_get_linked_bundles(bundle_name, bundles=bundles))
    active = set()
    for name in children:
        gpu_id = (bundles.get(name) or {}).get("gpu_id")
        state = _get_gpu_state(gpu_id) if gpu_id else None
        if int(getattr(state, "worker_in_flight", 0) or 0) > 0:
            active.add(name)
    return active


def _linked_bundle_unload_order(
    bundle_name: str,
    bundles: dict | None = None,
) -> list[str]:
    """Return connected linked bundles in dependency-first unload order."""
    if bundles is None:
        bundles = _resolve_bundles()
    if bundle_name not in bundles:
        return []
    visited: set[str] = set()
    order: list[str] = []

    def _visit(name: str) -> None:
        if name in visited or name not in bundles:
            return
        visited.add(name)
        for linked_name in _get_linked_bundles(name, bundles=bundles):
            _visit(linked_name)
        order.append(name)

    _visit(bundle_name)
    return order


async def _teardown_bundle_graph(
    bundle_name: str,
    *,
    reason: str,
) -> bool:
    """Tear down a linked bundle graph under one durable group fence."""
    bundles = _resolve_bundles()
    teardown_order = _linked_bundle_unload_order(bundle_name, bundles=bundles)
    if not teardown_order:
        logger.error("bundle teardown refused: unknown bundle graph %s", bundle_name)
        return False
    try:
        transition_members = _expand_bundle_transition_members(
            [(bundle_name, BundleDesiredState.STOPPED)],
            bundles=bundles,
        )
    except Exception as exc:
        logger.error(
            "bundle teardown refused for %s: invalid bundle group: %s",
            bundle_name,
            exc,
        )
        return False

    active_children = _active_bundle_children(bundle_name, bundles)
    transition_members = _exclude_active_child_transitions(
        bundle_name, transition_members, active_children=active_children
    )
    teardown_order = [name for name in teardown_order if name not in active_children]

    async def _unload_graph() -> bool:
        for name in teardown_order:
            if not await _unload_bundle(name):
                return False
        return True

    return await _run_bundle_group_transition(
        transition_members,
        _unload_graph,
        reason=reason,
    )


async def _teardown_acestep_bundle(
    bundle_name: str,
    *,
    reason: str,
) -> bool:
    """Tear down an ACE-Step bundle graph under one durable group fence."""
    return await _teardown_bundle_graph(bundle_name, reason=reason)


async def _run_bundle_eviction_for_vram(
    bundle_name: str,
    *,
    reason: str,
    bundles: dict | None = None,
) -> bool:
    """Evict one bundle graph under the controller-owned group fence.

    ``evict_for_vram`` is an older service-oriented entry point, but a
    configured bundle is the lifecycle unit. Keep the actual unload callback
    inside the durable group transition so linked reservations and primary
    services cannot be split by a raw systemd fallback.
    """
    if bundle_lifecycle_controller is None:
        logger.error(
            "bundle VRAM eviction refused without lifecycle controller: %s (%s)",
            bundle_name,
            reason,
        )
        return False
    if bundles is None:
        bundles = _resolve_bundles()
    unload_order = _linked_bundle_unload_order(bundle_name, bundles=bundles)
    if not unload_order:
        logger.error(
            "bundle VRAM eviction refused for unknown bundle graph: %s",
            bundle_name,
        )
        return False
    try:
        transition_members = _expand_bundle_transition_members(
            [(bundle_name, BundleDesiredState.STOPPED)],
            bundles=bundles,
        )
    except Exception as exc:
        logger.error(
            "bundle VRAM eviction refused for %s: invalid group: %s",
            bundle_name,
            exc,
        )
        return False

    async def _unload_graph() -> bool:
        for member_name in unload_order:
            if not await _unload_bundle(member_name):
                return False
        return True

    active_children = _active_bundle_children(bundle_name, bundles)
    transition_members = _exclude_active_child_transitions(
        bundle_name, transition_members, active_children=active_children
    )
    unload_order = [name for name in unload_order if name not in active_children]

    return await _run_bundle_group_transition(
        transition_members,
        _unload_graph,
        reason=reason,
    )


async def _run_standalone_llm_eviction(
    vram_manager: Any,
    *,
    reason: str,
    target_gpu: str | None = None,
    skip_bundle_name: str | None = None,
) -> bool:
    """Run a direct LLM eviction under one durable target-group fence."""
    work_gpu = target_gpu or getattr(vram_manager, "_evicted_gpu_id", None) or "gpu_primary"
    bundles = _resolve_bundles()
    roots = [
        name
        for name, bundle in bundles.items()
        if (bundle or {}).get("gpu_id") == work_gpu
        and name != skip_bundle_name
    ]
    if not roots:
        logger.error(
            "standalone LLM eviction refused: no configured bundle roots on GPU %s",
            work_gpu,
        )
        return False
    try:
        transition_members = _expand_bundle_transition_members(
            [(name, BundleDesiredState.STOPPED) for name in roots],
            bundles=bundles,
        )
    except Exception as exc:
        logger.error(
            "standalone LLM eviction refused on GPU %s: invalid bundle group: %s",
            work_gpu,
            exc,
        )
        return False

    async def _evict() -> bool:
        return await _evict_llm_unless_protected_busy(
            vram_manager,
            reason=reason,
            target_gpu=work_gpu,
            skip_bundle_name=skip_bundle_name,
            admission_authorized=True,
        )

    return await _run_bundle_group_transition(
        transition_members,
        _evict,
        reason=f"llm-evict:{reason}",
    )


async def _rollback_bundle_graph(
    bundle_name: str,
    *,
    bundles: dict | None = None,
    preserve: set[str] | None = None,
) -> dict:
    """Best-effort rollback of newly loaded members in a linked bundle graph.

    Every non-preserved member is attempted even after an earlier unload
    failure. The returned report is included in the failed start_bundle RPC so
    partial rollback is visible instead of being hidden in logs.
    """
    if bundles is None:
        bundles = _resolve_bundles()
    preserve = set(preserve or set())
    active_children = _active_bundle_children(bundle_name, bundles)
    preserve.update(active_children)
    order = _linked_bundle_unload_order(bundle_name, bundles)
    attempted: list[str] = []
    preserved: list[str] = []
    errors: list[str] = []

    # Drain only this root's own accepted work. A linked child has an independent
    # owner and is preserved below rather than delaying or being torn down by
    # this rollback.
    deadline = time.monotonic() + DRAIN_TIMEOUT
    root_gpu_id = (bundles.get(bundle_name) or {}).get("gpu_id")
    root_state = _get_gpu_state(root_gpu_id) if root_gpu_id else None
    in_flight = int(getattr(root_state, "worker_in_flight", 0) or 0)
    while in_flight > 0 and time.monotonic() < deadline:
        await asyncio.sleep(0.1)
        in_flight = int(getattr(root_state, "worker_in_flight", 0) or 0)
    if in_flight > 0:
        errors.append(f"rollback drain blocked by {in_flight} in-flight worker(s)")
        return {
            "ok": False,
            "attempted": attempted,
            "preserved": preserved,
            "errors": errors,
        }

    for name in order:
        if name in preserve:
            preserved.append(name)
            continue
        attempted.append(name)
        try:
            ok = await _unload_bundle(name)
        except Exception as exc:
            ok = False
            errors.append(f"rollback unload for '{name}' raised: {exc}")
        if not ok and not any(f"'{name}'" in error for error in errors):
            errors.append(f"rollback unload for '{name}' failed")
    report = {
        "ok": not errors,
        "attempted": attempted,
        "preserved": preserved,
        "errors": errors,
    }
    if errors:
        logger.warning(
            "start_bundle rollback incomplete for %s: %s",
            bundle_name,
            errors,
        )
    return report


async def _wait_port_ready(
    service_name: str,
    port: int,
    timeout: float = 30.0,
) -> bool:
    """Wait until *port* responds with HTTP 200 on its health path within *timeout* seconds.

    Looks up the per-service `health_path` from services.json (added by PR2 so each
    backend can advertise its own liveness URL — sd-server uses `/`, ComfyUI uses
    `/health`, etc.). Falls back to `/health` if the field is missing or the config
    can't be loaded. HTTP-only by design: a TCP probe would treat a half-loaded
    sd-server (port open, no routes registered) as "ready" and cause the first
    request to 404.
    """
    health_path = "/health"  # default
    try:
        config = _load_services_config()
        svc_cfg = (config or {}).get("services", {}).get(service_name, {})
        configured = svc_cfg.get("health_path")
        if configured:
            health_path = configured
    except Exception:
        pass  # fall back to /health on any error

    url = f"http://127.0.0.1:{port}{health_path}"
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        try:
            async with session.get(
                url,
                timeout=ClientTimeout(total=3),
            ) as resp:
                if resp.status == 200:
                    return True
        except Exception:
            pass
        await asyncio.sleep(2)
    return False


def _job_cancel_requested(tracker, job_id: str) -> bool:
    """Return True when a JobTracker record shows cooperative cancel intent.

    Accepts either ``status=cancelled`` or the explicit
    ``cancellation_intent`` marker set by ``handle_cancel_job``.
    The helper is intentionally best-effort and must never raise.
    """
    if not tracker or not job_id:
        return False
    try:
        record = tracker.get_job(job_id) or {}
    except Exception:
        return False
    if str(record.get("status", "")).lower() == "cancelled":
        return True
    intent = record.get("cancellation_intent")
    if intent is None:
        return False
    return str(intent).strip().lower() not in ("", "0", "false", "none")


async def _run_terminalization_step(label: str, operation, attempts: int = 3):
    last_error: Exception | None = None
    for attempt in range(1, attempts + 1):
        try:
            result = operation()
            if asyncio.iscoroutine(result):
                result = await result
            if result is False:
                raise RuntimeError(f"{label} returned false")
            return result
        except Exception as exc:
            last_error = exc
            logger.exception(
                "terminalization step %s failed (attempt %d/%d)",
                label,
                attempt,
                attempts,
            )
            if attempt < attempts:
                await asyncio.sleep(0.05)
    raise RuntimeError(
        f"terminalization step {label} failed after {attempts} attempts: {last_error}"
    ) from last_error


async def _terminalize_pre_forward_job(
    *,
    job_id: str,
    entry_id: str,
    service_name: str,
    routing_group: str | None,
    consumer_name: str,
    status: str,
    reason: str,
    error_type: str | None = None,
) -> None:
    """Terminalize and ACK a job that exits before backend forward.

    Both operations are retried and failures propagate. Returning normally is
    therefore proof that tracker state and stream ownership agree.
    """
    tracker = job_tracker
    if tracker is None:
        raise RuntimeError("cannot terminalize pre-forward job: job tracker unavailable")
    await _run_terminalization_step(
        "job_tracker.update_status",
        lambda: tracker.update_status(
            job_id, status, error=reason, **({"error_type": error_type} if error_type else {})
        ),
    )

    if entry_id:
        queue = async_queue
        if queue is None:
            raise RuntimeError("cannot terminalize pre-forward job: async queue unavailable")
        kwargs = {}
        if routing_group:
            kwargs["routing_group"] = routing_group
        await _run_terminalization_step(
            "async_queue.ack",
            lambda: queue.ack(
                service_name, consumer_name, entry_id, **kwargs
            ),
        )


READINESS_GATE_DEFAULT_TIMEOUT_S = 120.0
READINESS_GATE_MIN_POLL_HTTP_TIMEOUT_S = 10.0
READINESS_GATE_LOG_BODY_CHARS = 512


async def _readiness_cancel_requested(job_id: str) -> bool:
    """Best-effort cooperative cancel check for readiness-gated jobs."""
    return _job_cancel_requested(job_tracker, job_id)


async def _wait_service_readiness_gate(
    *,
    session_obj,
    job_id: str,
    entry_id: str,
    routing_group: str | None,
    consumer_name: str,
    worker_id: int,
    service_name: str,
    readiness_service_name: str,
    readiness_path: str,
    readiness_timeout_s: float,
    readiness_poll_interval_s: float,
    predicate_field: str | None,
    predicate_value,
    readiness_required_fields=None,
    readiness_required_value_fields=None,
) -> bool:
    """Poll a named service readiness signal until ready, cancelled, or timeout.

    The newer config-backed contract (``readiness_required_fields``) is
    layered on top via :func:`_evaluate_readiness_payload`: when the
    list is non-empty the HTTP 200 response payload MUST contain every
    named field. The shared evaluator never inspects values to infer
    model residency — presence is the only claim it makes. Legacy
    ``predicate_field`` / ``predicate_value`` semantics are preserved
    and evaluated AFTER the required-fields check.
    """
    config = _load_services_config() or {}
    svc_cfg = (config.get("services", {}) or {}).get(readiness_service_name, {})
    port = svc_cfg.get("port")
    if not port:
        await _terminalize_pre_forward_job(
            job_id=job_id,
            entry_id=entry_id,
            service_name=service_name,
            routing_group=routing_group,
            consumer_name=consumer_name,
            status="failed",
            reason=f"readiness gate missing port for service '{readiness_service_name}'",
        )
        return False
    # An unset or non-positive timeout means "use the default", never "wait
    # forever" and never "fail on the first poll".
    timeout_s = float(readiness_timeout_s or 0)
    if timeout_s <= 0:
        timeout_s = READINESS_GATE_DEFAULT_TIMEOUT_S
    deadline = time.monotonic() + timeout_s
    readiness_path = readiness_path or svc_cfg.get("health_path") or "/health"
    poll_interval = max(0.01, float(readiness_poll_interval_s or 0.1))
    poll_http_timeout = max(READINESS_GATE_MIN_POLL_HTTP_TIMEOUT_S, poll_interval)
    url = f"http://127.0.0.1:{int(port)}{readiness_path}"
    required_fields = _normalize_readiness_required_fields(readiness_required_fields)
    last_status: int | None = None
    last_body = ""
    last_reason = ""
    while True:
        if await _readiness_cancel_requested(job_id):
            await _terminalize_pre_forward_job(
                job_id=job_id,
                entry_id=entry_id,
                service_name=service_name,
                routing_group=routing_group,
                consumer_name=consumer_name,
                status="cancelled",
                reason="cancelled during readiness gate",
            )
            return False
        try:
            get_result = session_obj.get(url, timeout=ClientTimeout(total=poll_http_timeout))
            if asyncio.iscoroutine(get_result):
                get_result = await get_result
            async with get_result as resp:
                status_code = int(getattr(resp, "status", 0) or 0)
                last_status = status_code
                payload = None
                if required_fields or predicate_field:
                    try:
                        payload = await resp.json()
                    except Exception:
                        payload = None
                if payload is not None:
                    try:
                        last_body = json.dumps(payload, default=str)[:READINESS_GATE_LOG_BODY_CHARS]
                    except Exception:
                        last_body = repr(payload)[:READINESS_GATE_LOG_BODY_CHARS]
                else:
                    try:
                        last_body = (await resp.text())[:READINESS_GATE_LOG_BODY_CHARS]
                    except Exception:
                        last_body = ""
                evaluator_kwargs = {
                    "status": status_code,
                    "payload": payload,
                    "required_fields": required_fields,
                    "service_name": readiness_service_name,
                }
                if readiness_required_value_fields:
                    evaluator_kwargs["required_value_fields"] = readiness_required_value_fields
                ok, reason = _evaluate_readiness_payload(**evaluator_kwargs)
                if ok and predicate_field:
                    predicate_present, predicate_observed = _readiness_payload_lookup(
                        payload, predicate_field
                    )
                    if not predicate_present or predicate_observed != predicate_value:
                        ok = False
                        reason = (
                            f"readiness: predicate '{predicate_field}' != "
                            f"{predicate_value!r}"
                        )
                if ok:
                    logger.debug(
                        "Worker-%d: readiness gate satisfied for %s (%s)",
                        worker_id,
                        readiness_service_name,
                        reason,
                    )
                    return True
                last_reason = str(reason)
                logger.debug(
                    "Worker-%d: readiness gate not yet satisfied for %s (%s)",
                    worker_id,
                    readiness_service_name,
                    reason,
                )
        except Exception as exc:
            last_reason = f"poll exception: {exc!r}"
            logger.debug(
                "Worker-%d: readiness poll exception for %s: %s",
                worker_id,
                readiness_service_name,
                exc,
            )
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            logger.error(
                "Worker-%d: readiness_gate_timeout for %s after %ss: url=%s "
                "last_status=%s last_reason=%s last_body=%s",
                worker_id,
                readiness_service_name,
                timeout_s,
                url,
                last_status,
                last_reason,
                last_body,
            )
            await _terminalize_pre_forward_job(
                job_id=job_id,
                entry_id=entry_id,
                service_name=service_name,
                routing_group=routing_group,
                consumer_name=consumer_name,
                status="failed",
                reason=(
                    f"readiness_gate_timeout: {readiness_service_name}{readiness_path} "
                    f"not ready after {timeout_s}s (last_status={last_status}, "
                    f"last_reason={last_reason})"
                ),
                error_type="readiness_gate_timeout",
            )
            return False
        await asyncio.sleep(min(poll_interval, remaining))


    """Convert old-format services.json to new bundle format.

    Does NOT auto-save. Logs a warning that migration is available.
    Returns the migrated config dict, or None if already in new format.
    """
    if config is None:
        config = _load_services_config()

    if "bundles" in config and config["bundles"]:
        # Already has bundles — nothing to migrate
        return None

    logger.warning(
        "CONFIG MIGRATION AVAILABLE: services.json uses old format without 'bundles' section. "
        "Bundle resolution is happening at runtime via _resolve_bundles(). "
        "Run _migrate_config(save=True) to persist the new format to disk."
    )

    # Build the migrated config
    migrated = json.loads(json.dumps(config))  # deep copy
    migrated["bundles"] = _resolve_bundles(config)
    return migrated


def _migrate_config_and_save(config: dict | None = None) -> bool:
    """Migrate config to bundle format and persist to disk.

    Returns True if migration was performed, False if already in new format.
    """
    migrated = _migrate_config(config)
    if migrated is None:
        return False
    _save_services_config(migrated)
    logger.info("Config migrated to bundle format and saved to disk")
    return True


# ── State Persistence Helpers ─────────────────────────────────────
# ── State Persistence Helpers ─────────────────────────────────────
STATE_DIR = os.path.dirname(STATE_FILE)
STATE_ROLLING_MAX = 5  # Keep up to 5 state snapshots (current + 4 previous)


# Plan 04 §4 — Schema namespace is intentionally split:
#   * Top-level manager state (this file) is schema "state_version" v4.
#     The default below is v4; the migration gate below migrates v1→v4
#     and warns on v>4.
#   * Nested per-GPU bundle state (GpuBundleState.from_dict) is schema
#     "state_version" v5 — it lives inside ``gpu_states`` and carries
#     additional fields (worker_in_flight, last_activity_at). The two
#     schemas evolve independently; never bump one to "fix" the other.
# Tests assert the version-pair and the test module ``gpu_manager_semantics``
# imports ``MANAGER_STATE_SCHEMA_VERSION`` / ``BUNDLE_STATE_SCHEMA_VERSION``
# from gpu_manager_semantics as the canonical reference for consumers.


def _load_state() -> dict:
    """Load GPU Manager state from disk.

    Returns the persisted state dict, or a default empty state on any error.
    This is used on startup to understand what was happening before the last
    shutdown — but the actual system state is detected from systemd, not
    blindly restored from this file.

    On normal startup, loads state.json (the clean shutdown state).
    For crash recovery, state.1.json through state.4.json are available
    as fallbacks (the rolling log from periodic saves).

    IMPORTANT — backup protocol (Phase 6):
        Before any destructive state.json change, back up the file with a
        timestamped copy so it can be inspected or restored if the migration
        is wrong:

            cp ~/.config/gpu-manager/state.json \\
               ~/.config/gpu-manager/state.json.bak.$(date +%Y%m%d-%H%M%S)

        state.json contains live scheduler state, OOM counters, the watchdog
        heartbeat timestamp, and GpuBundleState instances for each GPU. Loss
        of this file forces full re-discovery on next startup (Gemma services
        stay loaded, but idle baselines need to be re-snapshotted before the
        next eviction decision).
    """
    default = {
        "state_version": MANAGER_STATE_SCHEMA_VERSION,
        "gpu_state": "llm_loaded",
        "llm_evicted": False,
        # Legacy alias retained; see llm_service_semantics.
        "llm_service": "",
        "configured_idle_service": "",
        "loaded_runtime_services": [],
        "loaded_runtime_bundles": [],
        "llm_service_semantics": "configured_idle_service_legacy_alias",
        "scheduler_running": False,
        "pinned_service": None,
        "maintenance_mode": False,
        "last_updated": None,
        "gpu_states": {},  # Per-GPU bundle states
    }
    try:
        if os.path.exists(STATE_FILE):
            with open(STATE_FILE) as f:
                saved = json.load(f)
            # State-version migration gate.
            #   v1 (pre-Phase 1): no state_version key at all and no oom_* fields.
            #   v2 (Phase 1):    OOM recovery state machine fields.
            #   v3 (Phase 5/7):  + oom_last_service_name + oom_state_changed_at
            #                    on every GpuBundleState inside gpu_states.
            #   v4 (Phase 7):    + explicit configured_idle_service and
            #                    loaded_runtime_{services,bundles} fields.
            # We accept any newer version we don't know about (forward compat)
            # and log a warning so an old binary on a new state file is visible.
            saved_version = int(saved.get("state_version", 1))
            if saved_version < 2:
                logger.info(
                    f"state.json: migrating v{saved_version} → v2 "
                    f"(adding OOM recovery fields)"
                )
            if saved_version < 3:
                logger.info(
                    f"state.json: migrating v{saved_version} → v3 "
                    f"(per-GPU oom_last_service_name + oom_state_changed_at)"
                )
            if saved_version < 4:
                logger.info(
                    f"state.json: migrating v{saved_version} → v4 "
                    f"(configured idle vs runtime-loaded telemetry)"
                )
            elif saved_version > MANAGER_STATE_SCHEMA_VERSION:
                logger.warning(
                    f"state.json: file is v{saved_version}, this binary "
                    f"understands up to v{MANAGER_STATE_SCHEMA_VERSION} — proceeding with best-effort load"
                )
            # Merge with defaults to handle missing keys from older saves
            default.update(saved)
            # Force our current understanding of the schema version
            default["state_version"] = max(saved_version, MANAGER_STATE_SCHEMA_VERSION)
            logger.debug(f"State file loaded: {STATE_FILE} (updated: {default.get('last_updated')}, version={default['state_version']})")
            return default
    except Exception as e:
        logger.warning(f"Failed to load state file {STATE_FILE}: {e}")
    return default


def _save_state(shutdown: bool = False):
    """Save current GPU Manager state to disk.

    Uses a rolling 5-state system:
      state.json     — current state (clean shutdown marker)
      state.1.json   — most recent periodic save
      state.2.json   — second most recent
      state.3.json   — third most recent
      state.4.json   — oldest periodic save

    On periodic saves (shutdown=False): rotates the rolling states first,
    then writes the new state.

    On shutdown (shutdown=True): wipes all rolling states first, then
    writes a single clean state.json. This ensures startup always reads
    the clean shutdown state.
    """
    try:
        os.makedirs(os.path.dirname(STATE_FILE), exist_ok=True)

        # ── Build per-GPU states ──
        gpu_states_dict = {}
        for gpu_id, gpu_state in _gpu_states.items():
            gpu_states_dict[gpu_id] = gpu_state.to_dict()
        configured_idle_service = _get_idle_service_name() if vram else ""
        runtime_snapshot = (
            _get_loaded_runtime_snapshot()
            if vram else {"services": [], "bundles": []}
        )

        state = {
            "state_version": MANAGER_STATE_SCHEMA_VERSION,
            "gpu_state": vram.gpu_state.value if vram else "llm_loaded",
            "llm_evicted": vram._llm_evicted if vram else False,
            # ``llm_service`` is retained as a legacy configured-idle alias.
            "llm_service": configured_idle_service,
            "configured_idle_service": configured_idle_service,
            "loaded_runtime_services": runtime_snapshot["services"],
            "loaded_runtime_bundles": runtime_snapshot["bundles"],
            "llm_service_semantics": "configured_idle_service_legacy_alias",
            "scheduler_running": scheduler._running if scheduler else False,
            "pinned_service": scheduler._pinned_service if scheduler else None,
            "maintenance_mode": _maintenance_mode_enabled(
                _services_config.get("scheduling", {}) if _services_config else {}
            ),
            "last_updated": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
            "gpu_states": gpu_states_dict,
            "llm_request_metrics": llm.counters(),
        }
        _apply_runtime_semantics(state)

        if shutdown:
            # On shutdown: wipe all rolling states, save clean state.json only
            _clear_rolling_states()
        else:
            # On periodic save: rotate rolling states first
            _rotate_rolling_states()

        with open(STATE_FILE, "w") as f:
            json.dump(state, f, indent=2)
        logger.debug(f"State saved: gpu_state={state['gpu_state']}, evicted={state['llm_evicted']}, "
                     f"gpus={list(gpu_states_dict.keys())}")
    except Exception as e:
        logger.warning(f"Failed to save state to {STATE_FILE}: {e}")


def _rotate_rolling_states():
    """Rotate rolling state files: state.4.json is discarded,
    state.3→state.4, state.2→state.3, state.1→state.2, current→state.1.

    This is called before each periodic save to maintain the rolling log.
    """
    for i in range(STATE_ROLLING_MAX - 1, 0, -1):
        src = os.path.join(STATE_DIR, f"state.{i}.json")
        dst = os.path.join(STATE_DIR, f"state.{i + 1}.json")
        if os.path.exists(src):
            try:
                if i + 1 >= STATE_ROLLING_MAX:
                    os.remove(src)  # Discard oldest
                else:
                    os.rename(src, dst)
            except OSError:
                pass
    # Current state.json → state.1.json
    if os.path.exists(STATE_FILE):
        dst = os.path.join(STATE_DIR, "state.1.json")
        try:
            os.rename(STATE_FILE, dst)
        except OSError:
            pass


def _clear_rolling_states():
    """Remove all rolling state files (state.1.json through state.4.json).

    Called on shutdown before saving the clean state.json.
    """
    for i in range(1, STATE_ROLLING_MAX + 1):
        path = os.path.join(STATE_DIR, f"state.{i}.json")
        if os.path.exists(path):
            try:
                os.remove(path)
            except OSError:
                pass


# ── Queue Management Handlers ───────────────────────────────────────

async def handle_queue_move(request: web.Request):
    """POST /queue/move — Reorder a job in the queue."""
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    job_id = data.get("job_id")
    new_position = data.get("position", 0)

    if not job_id:
        return web.json_response({"error": "Missing job_id"}, status=400)

    job = scheduler.get_job(job_id)
    if not job:
        return web.json_response({"error": f"Job {job_id} not found"}, status=404)

    if job.status != "queued":
        return web.json_response(
            {"error": f"Job {job_id} is {job.status}, can only move queued jobs"},
            status=409,
        )

    # Move in the correct queue
    if job.backend == "comfyui":
        # Remove from current position
        scheduler._comfyui_queue = [j for j in scheduler._comfyui_queue if j.id != job_id]
        # Insert at new position
        pos = max(0, min(new_position, len(scheduler._comfyui_queue)))
        scheduler._comfyui_queue.insert(pos, job)
    else:
        scheduler._acestep_queue = [j for j in scheduler._acestep_queue if j.id != job_id]
        pos = max(0, min(new_position, len(scheduler._acestep_queue)))
        scheduler._acestep_queue.insert(pos, job)

    logger.info(f"Queue: moved job {job_id} to position {new_position}")
    return web.json_response({"status": "moved", "job_id": job_id, "position": new_position})


async def handle_queue_insert(request: web.Request):
    """POST /queue/insert — Insert a workflow at a specific position."""
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, Mapping):
        return web.json_response({"error": "JSON body must be an object"}, status=400)

    workflow = data.get("workflow") or data.get("prompt")
    position = data.get("position", 0)
    priority = data.get("priority", 5)
    backend = data.get("backend", "comfyui")

    if str(backend).startswith("acestep"):
        return web.json_response(
            {
                "error": "ACE-Step generation is retired",
                "reason": "acestep_retired",
                "replacement": "minimax-music3-full",
            },
            status=410,
        )
    if backend != "comfyui":
        return web.json_response(
            {
                "error": "raw queue insertion supports only retained ComfyUI jobs; use /v1/submit/generation for registered services"
            },
            status=400,
        )

    if not workflow:
        return web.json_response({"error": "Missing workflow/prompt"}, status=400)

    # Phase 5.2.79 (R2): sanitize raw workflow from external callers BEFORE
    # constructing the Job. Same defensive shape as handle_pipeline_submit.
    if backend == "comfyui" and isinstance(workflow, dict):
        from comfyui_workflow_sanitize import sanitize_comfyui_workflow
        workflow = sanitize_comfyui_workflow(workflow, source="handle_queue_insert")

    job = Job(workflow, data.get("callback_url"), priority, data.get("metadata"))
    scheduler.comfyui_jobs[job.id] = job
    pos = max(0, min(position, len(scheduler._comfyui_queue)))
    scheduler._comfyui_queue.insert(pos, job)

    logger.info(f"Queue: inserted job {job.id} at position {position} in {backend}")
    return web.json_response({
        "job_id": job.id,
        "status": job.status,
        "position": position,
        "backend": backend,
    }, status=201)


async def handle_queue_cancel(request: web.Request):
    """POST /queue/cancel — Cancel a queued job by job_id."""
    try:
        data = await request.json()
        job_id = data.get("job_id")
    except Exception:
        job_id = request.query.get("job_id")

    if not job_id:
        return web.json_response({"error": "Missing job_id"}, status=400)

    if scheduler.cancel(job_id):
        return web.json_response({"status": "cancelled", "job_id": job_id})
    return web.json_response({"error": "Job not found or not cancellable"}, status=404)


async def handle_queue_cancel_running(request: web.Request):
    """POST /queue/cancel-running/{job_id} — Cancel a running job via backend interrupt."""
    job_id = request.match_info.get("job_id")
    if not job_id:
        return web.json_response({"error": "Missing job_id"}, status=400)

    job = scheduler.get_job(job_id)
    if not job:
        return web.json_response({"error": f"Job {job_id} not found"}, status=404)

    if job.status != "running":
        return web.json_response(
            {"error": f"Job {job_id} is {job.status}, not running"},
            status=409,
        )

    if job.backend == "comfyui" and hasattr(job, "comfyui_prompt_id") and job.comfyui_prompt_id:
        try:
            async with session.post(
                f"{COMFYUI_URL}/interrupt",
                timeout=ClientTimeout(total=10),
            ) as resp:
                job.status = "cancelled"
                job.finished_at = time.time()
                job.result = {"error": "Cancelled by user"}
                logger.info(f"Queue: cancelled running ComfyUI job {job_id} (prompt {job.comfyui_prompt_id})")
                return web.json_response({"status": "cancelled", "job_id": job_id})
        except Exception as e:
            return web.json_response({"error": f"ComfyUI interrupt failed: {e}"}, status=502)

    elif job.backend == "acestep":
        if await scheduler.cancel_acestep_running(job):
            return web.json_response({"status": "cancelled", "job_id": job_id})
        return web.json_response(
            {"error": f"ACE-Step task cancellation was not acknowledged for {job_id}"},
            status=502,
        )

    return web.json_response({"error": f"No backend handle for job {job_id}"}, status=409)


async def handle_queue_clear(request: web.Request):
    """POST /queue/clear — Cancel all queued (and optionally running) jobs for a backend."""
    try:
        data = await request.json()
    except Exception:
        data = {}

    backend = data.get("backend")
    cancel_running = data.get("cancel_running", False)
    cancelled = 0

    if not backend or backend == "comfyui":
        for j in scheduler._comfyui_queue:
            if j.status == "queued":
                j.status = "cancelled"
                j.finished_at = time.time()
                j.result = {"error": "Queue cleared by user"}
                cancelled += 1
        scheduler._comfyui_queue = [j for j in scheduler._comfyui_queue if j.status != "cancelled"]

    if not backend or backend == "acestep":
        for j in scheduler._acestep_queue:
            if j.status == "queued":
                j.status = "cancelled"
                j.finished_at = time.time()
                j.result = {"error": "Queue cleared by user"}
                cancelled += 1
        scheduler._acestep_queue = [j for j in scheduler._acestep_queue if j.status != "cancelled"]

    logger.info(f"Queue: cleared {cancelled} jobs ({backend or 'all'})")
    return web.json_response({"status": "cleared", "cancelled": cancelled, "backend": backend or "all"})


async def handle_queue_bump(request: web.Request):
    """POST /queue/bump/{job_id} — Increase priority to HIGH tier."""
    job_id = request.match_info.get("job_id")
    if not job_id:
        return web.json_response({"error": "Missing job_id"}, status=400)

    job = scheduler.get_job(job_id)
    if not job:
        return web.json_response({"error": f"Job {job_id} not found"}, status=404)

    if job.status != "queued":
        return web.json_response(
            {"error": f"Job {job_id} is {job.status}, can only bump queued jobs"},
            status=409,
        )

    old_tier = job.priority_tier.name
    job.priority = 1  # HIGH tier, top of HIGH

    # Re-sort the correct queue
    if job.backend == "comfyui":
        scheduler._comfyui_queue.sort(
            key=lambda j: (scheduler.effective_tier(j).value, -j.priority, j.created_at)
        )
    else:
        scheduler._acestep_queue.sort(
            key=lambda j: (scheduler.effective_tier(j).value, -j.priority, j.created_at)
        )

    logger.info(f"Queue: bumped job {job_id} from {old_tier} to HIGH (priority={job.priority})")
    return web.json_response({
        "status": "bumped",
        "job_id": job_id,
        "priority": job.priority,
        "tier": job.priority_tier.name,
        "old_tier": old_tier,
    })


async def handle_queue_demote(request: web.Request):
    """POST /queue/demote/{job_id} — Decrease priority to LOW tier."""
    job_id = request.match_info.get("job_id")
    if not job_id:
        return web.json_response({"error": "Missing job_id"}, status=400)

    job = scheduler.get_job(job_id)
    if not job:
        return web.json_response({"error": f"Job {job_id} not found"}, status=404)

    if job.status != "queued":
        return web.json_response(
            {"error": f"Job {job_id} is {job.status}, can only demote queued jobs"},
            status=409,
        )

    old_tier = job.priority_tier.name
    job.priority = 10  # LOW tier

    # Re-sort the correct queue
    if job.backend == "comfyui":
        scheduler._comfyui_queue.sort(
            key=lambda j: (scheduler.effective_tier(j).value, -j.priority, j.created_at)
        )
    else:
        scheduler._acestep_queue.sort(
            key=lambda j: (scheduler.effective_tier(j).value, -j.priority, j.created_at)
        )

    logger.info(f"Queue: demoted job {job_id} from {old_tier} to LOW (priority={job.priority})")
    return web.json_response({
        "status": "demoted",
        "job_id": job_id,
        "priority": job.priority,
        "tier": job.priority_tier.name,
        "old_tier": old_tier,
    })


async def handle_idle_job(request: web.Request):
    """GET /idle-job — Return idle job config. POST /idle-job — Update config."""
    config = _load_services_config()
    if request.method == "GET":
        return web.json_response(config.get("scheduling", {}).get("idle_job", {}))

    data = await request.json()
    if "scheduling" not in config:
        config["scheduling"] = {}
    config["scheduling"]["idle_job"] = data
    _save_services_config(config)
    logger.info(f"Idle job config updated: enabled={data.get('enabled')}, backend={data.get('backend')}")
    return web.json_response({"success": True, "idle_job": data})


async def handle_idle_job_toggle(request: web.Request):
    """POST /idle-job/enable or /idle-job/disable."""
    action = request.match_info.get("action", "enable")
    config = _load_services_config()
    if "scheduling" not in config:
        config["scheduling"] = {}
    if "idle_job" not in config["scheduling"]:
        config["scheduling"]["idle_job"] = {}
    config["scheduling"]["idle_job"]["enabled"] = (action == "enable")
    _save_services_config(config)
    logger.info(f"Idle job {action}d")
    return web.json_response({"success": True, "idle_job": config["scheduling"]["idle_job"]})


async def handle_idle_service(request: web.Request):
    """GET/PUT /scheduling/idle-service — Get or set the idle/default LLM service.

    GET response includes:
      - idle_service: global fallback (string)
      - idle_services: per-GPU dict {gpu_id: service_name}
      - available: list of enabled LLM service names

    PUT accepts:
      Legacy (backward compat):
        {"idle_service": "llm-secondary"}           → sets global fallback
      Per-GPU:
        {"gpu_id": "gpu_secondary", "idle_service": "llm-secondary"}  → sets per-GPU idle
      Clear a per-GPU entry:
        {"gpu_id": "gpu_secondary", "idle_service": ""}   → removes per-GPU idle
    """
    config = _load_services_config()
    if "scheduling" not in config:
        config["scheduling"] = {}

    if request.method == "GET":
        scheduling = config["scheduling"]
        idle_svc = scheduling.get("idle_service", "")
        idle_services = scheduling.get("idle_services", {})
        return web.json_response({
            "idle_service": idle_svc,
            "idle_services": idle_services,
            "available": [
                name for name, svc in config.get("services", {}).items()
                if svc.get("type") == "llm_backend" and svc.get("enabled")
            ]
        })

    # PUT
    data = await request.json()
    gpu_id = data.get("gpu_id")
    svc_name = data.get("idle_service", "")

    if svc_name and svc_name not in config.get("services", {}):
        return web.json_response({"error": f"Service '{svc_name}' not found"}, status=404)

    if gpu_id:
        # Per-GPU idle service
        config["scheduling"].setdefault("idle_services", {})
        if svc_name:
            config["scheduling"]["idle_services"][gpu_id] = svc_name
            logger.info(f"Per-GPU idle service: gpu={gpu_id} → {svc_name}")
        else:
            # Clear per-GPU entry
            config["scheduling"]["idle_services"].pop(gpu_id, None)
            logger.info(f"Per-GPU idle service: gpu={gpu_id} cleared")
        _save_services_config(config)
        # Signal scheduler to check idle immediately
        if scheduler:
            scheduler._idle_check_event.set()
        return web.json_response({
            "success": True,
            "idle_service": config["scheduling"].get("idle_service", ""),
            "idle_services": config["scheduling"].get("idle_services", {}),
        })
    else:
        # Legacy: global idle_service
        config["scheduling"]["idle_service"] = svc_name
        _save_services_config(config)
        logger.info(f"Idle service (global) set to: {svc_name or '(none)'}")
        # Signal scheduler to check idle immediately
        if scheduler:
            scheduler._idle_check_event.set()
        return web.json_response({
            "success": True,
            "idle_service": svc_name,
            "idle_services": config["scheduling"].get("idle_services", {}),
        })


async def handle_pin_service(request: web.Request):
    """POST /scheduling/pin — Pin a service (queue override).
    Body: {"service": "LLM-Primary"} or {"service": null} to unpin.
    """
    global scheduler, _services_config
    if not scheduler:
        return web.json_response({"error": "Scheduler not running"}, status=503)

    data = await request.json()
    svc_name = data.get("service")

    if svc_name is None:
        # Unpin
        scheduler._pinned_service = None
        scheduler._pinned_service_since = None  # Phase 5.2.53 Fix B
        # Persist unpin
        _services_config = _load_services_config()
        _services_config.setdefault("scheduling", {})["pinned_service"] = None
        _save_services_config(_services_config)
        logger.info("Queue pin removed")
        return web.json_response({"success": True, "pinned_service": None})

    # Queue policy cannot target an unavailable or retired service.
    config = _load_services_config()
    rejection = _pin_service_rejection(config, str(svc_name))
    if rejection is not None:
        status, body = rejection
        return web.json_response(body, status=status)
    svc = config["services"][svc_name]

    # Map to backend type
    svc_type = svc.get("type", "")
    if svc_type == "generation_backend":
        # Determine backend from port
        if "comfyui" in svc_name.lower():
            backend = "comfyui"
        elif "acestep" in svc_name.lower():
            backend = "acestep"
        else:
            backend = svc_name
    else:
        backend = svc_name  # LLM services — pin means "only use this LLM"

    scheduler._pinned_service = backend
    scheduler._pinned_service_since = time.time()  # Phase 5.2.53 Fix B
    # Persist pin
    _services_config = _load_services_config()
    _services_config.setdefault("scheduling", {})["pinned_service"] = svc_name
    _save_services_config(_services_config)
    logger.info(f"Queue pinned to: {svc_name} (backend={backend})")
    return web.json_response({"success": True, "pinned_service": backend, "service": svc_name})


async def handle_queue_detail(request: web.Request):
    """GET /queue/detail — Full queue details for WebSocket/dashboard."""
    status = scheduler.get_queue_status() if scheduler else {}

    # Add per-job details for the dashboard
    queued_jobs = []
    for j in scheduler._comfyui_queue:
        if j.status == "queued":
            d = j.to_dict()
            d["priority_tier"] = j.priority_tier.name
            d["effective_tier"] = scheduler.effective_tier(j).name if scheduler else j.priority_tier.name
            queued_jobs.append(d)
    for j in scheduler._acestep_queue:
        if j.status == "queued":
            d = j.to_dict()
            d["priority_tier"] = j.priority_tier.name
            d["effective_tier"] = scheduler.effective_tier(j).name if scheduler else j.priority_tier.name
            queued_jobs.append(d)

    # Sort by effective tier (HIGH first) then priority then creation time
    queued_jobs.sort(key=lambda j: (
        PriorityTier[j["effective_tier"]].value if j["effective_tier"] in PriorityTier.__members__ else 3,
        -j["priority"],
        j["created_at"],
    ))

    running_jobs = []
    for j in list(scheduler.comfyui_jobs.values()) + list(scheduler.acestep_jobs.values()):
        if j.status == "running":
            d = j.to_dict()
            d["priority_tier"] = j.priority_tier.name
            running_jobs.append(d)

    status["queued_detail"] = queued_jobs
    status["running_detail"] = running_jobs
    return web.json_response(status)


# ── Service Config Handlers ─────────────────────────────────────────

# ── Maintenance Mode ──────────────────────────────────────────────

async def handle_maintenance(request: web.Request):
    """GET /maintenance — Return current maintenance mode status."""
    config = _load_services_config()
    scheduling = config.get("scheduling", {})
    enabled = _maintenance_mode_enabled(scheduling)
    expires = scheduling.get("maintenance_mode_expires")
    remaining = None
    if enabled and expires:
        remaining = max(0, int(expires - time.time()))
    return web.json_response({
        "maintenance_mode": enabled,
        "expires_in_seconds": remaining,
    })


async def handle_maintenance_toggle(request: web.Request):
    """POST /maintenance/enable or /maintenance/disable — Toggle maintenance mode.

    Body: {"timeout_minutes": 30}  (optional, 0 = no timeout, default: no timeout)

    When active, gpu-manager will NOT:
    - Auto-start any services (ensure_services_running)
    - Restore idle LLM after GPU work (_restore_after_gpu_work)
    - Ensure idle service is running (_ensure_idle_service)
    - Auto-restore from background_loop idle monitor

    Services can still be manually started/stopped via the API/MCP tools.
    """
    global _services_config
    enable = request.path.endswith("/enable")
    config = _load_services_config()
    if "scheduling" not in config:
        config["scheduling"] = {}

    config["scheduling"]["maintenance_mode"] = enable

    # Handle timeout
    timeout_minutes = 0
    if enable and request.can_read_body:
        try:
            data = await request.json()
            timeout_minutes = int(data.get("timeout_minutes", 0))
        except Exception:
            pass

    if enable and timeout_minutes > 0:
        config["scheduling"]["maintenance_mode_expires"] = time.time() + (timeout_minutes * 60)
        logger.info(f"Maintenance mode enabled with {timeout_minutes}min timeout")
    elif not enable:
        config["scheduling"].pop("maintenance_mode_expires", None)

    _save_services_config(config)

    state = "enabled" if enable else "disabled"
    logger.info(f"Maintenance mode {state}")

    return web.json_response({
        "success": True,
        "maintenance_mode": enable,
        "timeout_minutes": timeout_minutes if enable else 0,
        "message": f"Maintenance mode {state} — gpu-manager will {'NOT ' if enable else ''}manage services automatically"
    })


# ── Coexistence Mode (Phase 5.2.66) ───────────────────────────────
# SRE-controlled pause of the scheduler's auto-restoration loop.
# Unlike /maintenance (which is persisted to services.json), coexistence mode
# is IN-MEMORY ONLY — restarting gpu-manager clears the pause. This is
# intentional: coexistence mode is for short, interactive maintenance windows
# (5-15 min), not for long-running hackathons. Use /maintenance for those.
#
# Effect of pause=True:
#   - _ensure_idle_service skips ALL auto-restore paths, including the
#     CRASH RECOVERY branch (so a paused LLM that crashes stays down)
#   - Manual starts via /v1/services/{name}/toggle still work
#   - Explicit LLM restore via /vram/restore-llm still works
#   - Queue processing is NOT affected — pinned/active jobs still run
#
# State semantics (mirrors /scheduling/pin):
#   - {"action": "pause", "duration_seconds": 300}  → pause for 5 min
#   - {"action": "pause"}                          → pause indefinitely
#   - {"action": "resume"}                         → clear pause
#   - GET → return current state

async def handle_coexistence_mode(request: web.Request):
    """GET/POST /v1/coexistence/mode — manual SRE pause of auto-restoration."""
    global scheduler

    # GET → return current state (no scheduler dependency)
    if request.method == "GET":
        if not scheduler:
            return web.json_response({
                "paused": False,
                "expires_in_seconds": None,
                "note": "Scheduler not initialized — coexistence mode is in-memory only",
            })
        paused = bool(scheduler._coexistence_paused)
        expires_in = None
        if paused and scheduler._coexistence_pause_expires > 0:
            expires_in = max(0, int(scheduler._coexistence_pause_expires - time.time()))
        return web.json_response({
            "paused": paused,
            "paused_at": scheduler._coexistence_paused_at if paused else None,
            "expires_in_seconds": expires_in,
            "ephemeral": True,  # in-memory only — restart clears the pause
        })

    # POST → mutate state
    if not scheduler:
        return web.json_response({"error": "Scheduler not running"}, status=503)

    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON body"}, status=400)

    action = (data.get("action") or "").lower().strip()
    if action not in ("pause", "resume"):
        return web.json_response({
            "error": "action must be 'pause' or 'resume'",
        }, status=400)

    if action == "resume":
        was_paused = scheduler._coexistence_paused
        scheduler._coexistence_paused = False
        scheduler._coexistence_pause_expires = 0.0
        scheduler._coexistence_paused_at = 0.0
        if was_paused:
            logger.warning(
                "Coexistence mode RESUMED — auto-restoration re-enabled"
            )
        else:
            logger.debug("Coexistence resume called but not paused")
        return web.json_response({
            "success": True,
            "paused": False,
            "message": "Coexistence mode cleared — auto-restoration active",
        })

    # action == "pause"
    duration_seconds = data.get("duration_seconds")
    if duration_seconds is not None:
        try:
            duration_seconds = int(duration_seconds)
            if duration_seconds < 0:
                raise ValueError("must be >= 0")
        except (TypeError, ValueError) as e:
            return web.json_response({
                "error": f"duration_seconds must be a non-negative integer: {e}",
            }, status=400)
    else:
        duration_seconds = 0  # 0 = no auto-expiry

    scheduler._coexistence_paused = True
    scheduler._coexistence_paused_at = time.time()
    scheduler._coexistence_pause_expires = (
        scheduler._coexistence_paused_at + duration_seconds
        if duration_seconds > 0 else 0.0
    )

    if duration_seconds > 0:
        logger.warning(
            f"Coexistence mode PAUSED for {duration_seconds}s "
            f"({duration_seconds // 60}m{duration_seconds % 60:02d}s) — "
            f"auto-restoration disabled (crash recovery OFF). "
            f"Manual starts via /v1/services/{{name}}/toggle still work."
        )
    else:
        logger.warning(
            "Coexistence mode PAUSED indefinitely — auto-restoration disabled "
            "(crash recovery OFF). Manual starts via /v1/services/{name}/toggle "
            "still work. Send {\"action\":\"resume\"} to re-enable."
        )

    return web.json_response({
        "success": True,
        "paused": True,
        "duration_seconds": duration_seconds,
        "expires_in_seconds": duration_seconds if duration_seconds > 0 else None,
        "message": "Coexistence mode active — auto-restoration disabled",
    })


async def handle_services_list(request: web.Request):
    """GET /services — List all configured services.

    Non-mutating read path: invokes _load_services_config() so that a fresh
    valid external edit to services.json is visible on the next call,
    without a process restart. The cached module-level ``_services_config``
    is updated atomically by the loader so the response stays consistent
    with the scheduler / active endpoints.
    """
    return web.json_response(_load_services_config())


