def _service_activation_blockers(
    config: Mapping[str, Any], service: Mapping[str, Any]
) -> list[str]:
    """Return unresolved declarative references that must block activation."""
    blockers: list[str] = []
    workflow_ref = service.get("workflow_ref")
    if isinstance(workflow_ref, str) and workflow_ref and not isinstance(service.get("workflow"), Mapping):
        workflows = config.get("workflows") if isinstance(config, Mapping) else None
        if not isinstance(workflows, Mapping) or workflow_ref not in workflows:
            blockers.append("workflow_ref_not_resolved")
    profile_name = service.get("runtime_profile")
    if isinstance(profile_name, str) and profile_name:
        profiles = config.get("runtime_profiles") if isinstance(config, Mapping) else None
        if not isinstance(profiles, Mapping) or profile_name not in profiles:
            blockers.append("runtime_profile_not_resolved")
    for field, section_name, blocker in (
        ("operation_catalog_ref", "operation_catalogs", "operation_catalog_ref_not_resolved"),
        ("source_lock_ref", "source_locks", "source_lock_ref_not_resolved"),
    ):
        reference = service.get(field)
        if not isinstance(reference, str) or not reference:
            continue
        if isinstance(service.get(field.removesuffix("_ref")), Mapping):
            continue
        section = config.get(section_name) if isinstance(config, Mapping) else None
        if not isinstance(section, Mapping) or reference not in section:
            blockers.append(blocker)
    return blockers


def _compile_declarative_processing(
    config: Mapping[str, Any], service: Mapping[str, Any]
) -> dict[str, Any]:
    """Compile GUI processing only when it selects a reviewed catalog.

    A service draft without a catalog remains visibly draft-only.  Once a
    catalog is selected, every processing entry must resolve through the pure
    workflow compiler; unsupported mappings become an activation blocker before
    any registry write or queue admission.
    """

    processing = service.get("processing")
    if not isinstance(processing, list) or not processing:
        return {"status": "not_requested", "errors": [], "blockers": []}

    catalog_ref = service.get("operation_catalog_ref")
    catalogs = config.get("operation_catalogs") if isinstance(config, Mapping) else None
    catalog = None
    if isinstance(catalogs, Mapping) and isinstance(catalog_ref, str):
        catalog = catalogs.get(catalog_ref)
    if not isinstance(catalog, Mapping):
        return {
            "status": "draft_only",
            "errors": [],
            "blockers": [],
            "reason": "operation_catalog_required",
        }

    try:
        from declarative_workflow_registration import (
            DraftWorkflowCompilationError,
            compile_service_processing,
        )

        result = compile_service_processing(
            service,
            catalog,
            config=config,
            service_definitions=(
                config.get("services")
                if isinstance(config.get("services"), Mapping)
                else None
            ),
            runtime_profiles=(
                config.get("runtime_profiles")
                if isinstance(config.get("runtime_profiles"), Mapping)
                else None
            ),
        )
    except DraftWorkflowCompilationError as exc:
        return {
            "status": "blocked",
            "errors": list(exc.errors),
            "blockers": ["processing_mapping_unsupported"],
            "reason": "processing_mapping_unsupported",
        }
    except Exception as exc:
        logger.warning(
            "declarative processing compiler failed for %s: %s",
            service.get("name", "<unnamed>"),
            str(exc)[:500],
        )
        return {
            "status": "blocked",
            "errors": [f"compiler_error:{type(exc).__name__}"],
            "blockers": ["processing_compiler_error"],
            "reason": "processing_compiler_error",
        }
    return result


def _service_qualification_blockers(
    config: Mapping[str, Any], service: Mapping[str, Any]
) -> list[str]:
    """Require the shared qualification contract for revision activation."""
    return service_qualification_blockers(config, service)


def _revision_registry_conflict(
    config: Mapping[str, Any], expected_fingerprint: object
) -> web.Response | None:
    current = registry_summary(config, owner="controller")["fingerprint"]
    if not isinstance(expected_fingerprint, str) or expected_fingerprint != current:
        return web.json_response(
            {
                "error": "registry changed or compare-and-swap fingerprint is missing",
                "code": "registry_revision_conflict",
                "current_fingerprint": current,
            },
            status=409,
        )
    return None


async def handle_service_revision_list(request: web.Request):
    """List immutable revisions for one service without executable fields."""
    name = request.match_info["name"]
    config = _load_services_config()
    try:
        catalog = service_revision_catalog_from_document(
            config.get("service_revision_catalog")
        )
    except ServiceRevisionError as exc:
        return web.json_response({"error": str(exc)}, status=503)
    records = catalog.export(sanitize=True).get("services", {}).get(name, [])
    return web.json_response(
        {
            "service": name,
            "revisions": records,
            "registry_fingerprint": registry_summary(config, owner="controller")[
                "fingerprint"
            ],
        }
    )


async def handle_service_revision_publish(request: web.Request):
    """Publish a disabled immutable draft without installing it as a service."""
    name = request.match_info["name"]
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, Mapping) or not isinstance(data.get("definition"), Mapping):
        return web.json_response({"error": "definition must be an object"}, status=400)
    config = _load_services_config()
    conflict = _revision_registry_conflict(
        config, data.get("expected_registry_fingerprint")
    )
    if conflict is not None:
        return conflict
    definition = copy.deepcopy(dict(data["definition"]))
    if definition.get("name", name) != name:
        return web.json_response({"error": "definition name does not match route"}, status=400)
    definition["name"] = name
    if definition.get("enabled") is not False:
        return web.json_response(
            {"error": "published declarative revisions must be disabled drafts"},
            status=400,
        )
    runtime_fields = _declarative_runtime_field_errors(definition)
    if runtime_fields:
        return web.json_response(
            {"error": "declarative revisions cannot set runtime controls", "fields": runtime_fields},
            status=400,
        )
    validation_config = copy.deepcopy(config)
    validation_config.setdefault("services", {})[name] = definition
    workflow_compilation = _compile_declarative_processing(
        validation_config, definition
    )
    if workflow_compilation.get("status") == "blocked":
        return web.json_response(
            {
                "error": "service processing does not compile",
                "activation_blockers": workflow_compilation.get("blockers", []),
                "workflow_compilation": {
                    key: value
                    for key, value in workflow_compilation.items()
                    if key in {"status", "errors", "blockers", "reason"}
                },
            },
            status=400,
        )
    if workflow_compilation.get("status") == "compiled":
        definition["workflow"] = copy.deepcopy(workflow_compilation["workflow"])
        reviewed_fingerprint = data.get("reviewed_workflow_fingerprint")
        if reviewed_fingerprint is not None:
            if reviewed_fingerprint != workflow_compilation.get("workflow_fingerprint"):
                return web.json_response(
                    {"error": "reviewed workflow fingerprint mismatch", "code": "revision_conflict"},
                    status=409,
                )
            # Explicit operator review of the previewed graph, not automatic
            # qualification on create. The normal activation gate still checks
            # the catalog, providers, runtime profiles and model identities.
            definition["workflow"]["status"] = "qualified"
            definition["workflow"]["activation"]["state"] = "qualified"
            definition["workflow"]["activation"]["reviewed_fingerprint"] = reviewed_fingerprint
        validation_config["services"][name] = copy.deepcopy(definition)
    elif workflow_compilation.get("status") == "draft_only":
        # Do not carry a stale executable graph into a draft revision when the
        # processing declaration has no reviewed operation catalog yet.
        if isinstance(definition.get("processing"), list):
            definition.pop("workflow", None)
            validation_config["services"][name] = copy.deepcopy(definition)
    errors = validate_registry(validation_config)
    if errors:
        return web.json_response(
            {"error": "invalid service revision", "details": sorted(set(errors))},
            status=400,
        )
    try:
        catalog = service_revision_catalog_from_document(
            config.get("service_revision_catalog")
        )
        record = catalog.publish(
            name,
            definition,
            expected_latest_fingerprint=data.get("expected_latest_fingerprint"),
        )
    except RevisionConflict as exc:
        return web.json_response({"error": str(exc), "code": "revision_conflict"}, status=409)
    except ServiceRevisionError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    candidate = copy.deepcopy(config)
    candidate["service_revision_catalog"] = catalog.export()
    _save_services_config(candidate)
    return web.json_response(
        {
            "status": "published",
            "revision": record.to_dict(),
            "activation_blockers": _service_qualification_blockers(
                validation_config, definition
            ),
            "workflow_compilation": {
                key: value
                for key, value in workflow_compilation.items()
                if key
                in {
                    "status",
                    "reason",
                    "stage_count",
                    "stage_ids",
                    "workflow_fingerprint",
                }
            },
            "starts_processes": False,
            "registry_fingerprint": registry_summary(candidate, owner="controller")[
                "fingerprint"
            ],
        },
        status=201,
    )


async def handle_service_revision_activate(request: web.Request):
    """Atomically project one qualified revision into the active registry."""
    name = request.match_info["name"]
    try:
        revision = int(request.match_info["revision"])
        data = await request.json()
    except (TypeError, ValueError):
        return web.json_response({"error": "revision must be an integer"}, status=400)
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, Mapping):
        return web.json_response({"error": "JSON body must be an object"}, status=400)
    config = _load_services_config()
    conflict = _revision_registry_conflict(
        config, data.get("expected_registry_fingerprint")
    )
    if conflict is not None:
        return conflict
    try:
        catalog = service_revision_catalog_from_document(
            config.get("service_revision_catalog")
        )
    except ServiceRevisionError as exc:
        return web.json_response({"error": str(exc)}, status=503)
    try:
        target = catalog.get(name, revision)
    except ServiceRevisionError as exc:
        return web.json_response({"error": str(exc)}, status=404)
    expected_revision = data.get("expected_revision_fingerprint")
    if not isinstance(expected_revision, str) or expected_revision != target.fingerprint:
        return web.json_response(
            {"error": "target revision fingerprint mismatch", "code": "revision_conflict"},
            status=409,
        )
    definition = target.to_dict()["definition"]
    projected = copy.deepcopy(definition)
    projected["enabled"] = True
    projected["service_revision"] = target.revision
    projected["service_revision_fingerprint"] = target.fingerprint
    candidate = copy.deepcopy(config)
    candidate.setdefault("services", {})[name] = projected
    blockers = _service_qualification_blockers(candidate, projected)
    blockers.extend(service_registration_conflicts(candidate, name, projected))
    errors = validate_registry(candidate)
    if errors or blockers:
        return web.json_response(
            {
                "error": "service revision is not activatable",
                "details": sorted(set(errors)),
                "activation_blockers": blockers,
            },
            status=409,
        )
    await asyncio.to_thread(_fit_validator.warn_if_unfit, logger, candidate, _vram_cache or None,
                            [f"{name}@r{revision}"], service=name, project_root=PROJECT_ROOT)
    try:
        active = catalog.activate(
            name,
            revision,
            expected_fingerprint=expected_revision,
            expected_active_fingerprint=data.get("expected_active_fingerprint"),
        )
    except RevisionConflict as exc:
        return web.json_response({"error": str(exc), "code": "revision_conflict"}, status=409)
    except ServiceRevisionError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    candidate["service_revision_catalog"] = catalog.export()
    _save_services_config(candidate)
    return web.json_response(
        {
            "status": "activated",
            "revision": active.to_dict(),
            "registry_fingerprint": registry_summary(candidate, owner="controller")[
                "fingerprint"
            ],
            "runtime_transition_requested": False,
        }
    )


async def handle_service_revision_deprecate(request: web.Request):
    """Deprecate an inactive revision while preserving pinned job identity."""
    name = request.match_info["name"]
    try:
        revision = int(request.match_info["revision"])
        data = await request.json()
    except (TypeError, ValueError):
        return web.json_response({"error": "revision must be an integer"}, status=400)
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, Mapping):
        return web.json_response({"error": "JSON body must be an object"}, status=400)
    config = _load_services_config()
    conflict = _revision_registry_conflict(
        config, data.get("expected_registry_fingerprint")
    )
    if conflict is not None:
        return conflict
    try:
        catalog = service_revision_catalog_from_document(
            config.get("service_revision_catalog")
        )
    except ServiceRevisionError as exc:
        return web.json_response({"error": str(exc)}, status=503)
    try:
        target = catalog.get(name, revision)
        if target.state is RevisionState.ACTIVE:
            return web.json_response(
                {"error": "activate a replacement before deprecating the active revision"},
                status=409,
            )
        deprecated = catalog.deprecate(
            name,
            revision,
            expected_fingerprint=data.get("expected_revision_fingerprint"),
        )
    except RevisionConflict as exc:
        return web.json_response({"error": str(exc), "code": "revision_conflict"}, status=409)
    except ServiceRevisionError as exc:
        return web.json_response({"error": str(exc)}, status=404)
    candidate = copy.deepcopy(config)
    candidate["service_revision_catalog"] = catalog.export()
    _save_services_config(candidate)
    return web.json_response(
        {
            "status": "deprecated",
            "revision": deprecated.to_dict(),
            "registry_fingerprint": registry_summary(candidate, owner="controller")[
                "fingerprint"
            ],
        }
    )


async def handle_service_update(request: web.Request):
    """PUT /services/{name} — Update a service's config."""
    name = request.match_info["name"]
    svc = _services_config.get("services", {}).get(name)
    if not svc:
        return web.json_response({"error": f"Service '{name}' not found"}, status=404)

    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"error": "JSON body must be an object"}, status=400)

    expected_fingerprint = data.get("expected_registry_fingerprint")
    if expected_fingerprint is not None:
        current_fingerprint = registry_summary(_services_config, owner="controller")["fingerprint"]
        if expected_fingerprint != current_fingerprint:
            return web.json_response(
                {
                    "error": "registry changed; refresh before updating",
                    "code": "registry_revision_conflict",
                    "current_fingerprint": current_fingerprint,
                },
                status=409,
            )

    # Process exempt fields first (allowed even on protected services)
    exempt_changes = {}
    for field in ("protected", "cpu_only", "proxy_port"):
        if field in data:
            exempt_changes[field] = data[field]

    allowed_fields = {
        "display", "model_path", "launch_args", "priority", "enabled",
        "port", "cpuset", "systemd_unit", "type", "speculative_decoding",
        "health_path", "env_overrides", "gpu_id", "routing_group",
        "routing_group_type", "bundle", "linked_to", "linked_from", "http_path",
    } | _DYNAMIC_SERVICE_FIELDS
    unknown_fields = sorted(
        set(data) - set(exempt_changes) - allowed_fields - _SERVICE_REGISTRY_CONTROL_FIELDS
    )
    if unknown_fields:
        return web.json_response(
            {"error": "unsupported service fields", "fields": unknown_fields},
            status=400,
        )

    declarative_update = bool(
        svc.get("type") == "orchestrator"
        or any(field in data for field in _DYNAMIC_SERVICE_FIELDS)
    )
    if declarative_update:
        runtime_fields = _declarative_runtime_field_errors(data)
        if runtime_fields:
            return web.json_response(
                {
                    "error": "declarative services cannot set runtime controls",
                    "fields": runtime_fields,
                },
                status=400,
            )
        if data.get("enabled") is True:
            return web.json_response(
                {
                    "error": "declarative services require reviewed activation",
                    "activation_blockers": ["declarative_activation_required"],
                },
                status=400,
            )

    candidate = dict(svc)
    candidate.setdefault("name", name)
    candidate.update(exempt_changes)
    candidate.update({key: data[key] for key in allowed_fields if key in data})
    validation_errors = validate_service_definition(name, candidate)
    if validation_errors:
        return web.json_response(
            {"error": "invalid service definition", "details": validation_errors},
            status=400,
        )

    # Protected services are immutable through the ordinary GUI/API update
    # path. Check this before applying exempt fields so a request cannot
    # unprotect a service (or partially mutate it) and then continue below.
    if svc.get("protected"):
        requested_protected = data.get("protected", True)
        if requested_protected is not True or any(
            key not in {"protected"} | _SERVICE_REGISTRY_CONTROL_FIELDS for key in data
        ):
            return web.json_response(
                {"error": f"Service '{name}' is protected"}, status=403
            )
    candidate_config = copy.deepcopy(_services_config or {})
    candidate_config.setdefault("services", {})[name] = copy.deepcopy(candidate)
    workflow_compilation = _compile_declarative_processing(
        candidate_config, candidate
    )
    if workflow_compilation.get("status") == "blocked":
        return web.json_response(
            {
                "error": "service processing does not compile",
                "activation_blockers": workflow_compilation.get("blockers", []),
                "workflow_compilation": {
                    key: value
                    for key, value in workflow_compilation.items()
                    if key in {"status", "errors", "blockers", "reason"}
                },
            },
            status=400,
        )
    if workflow_compilation.get("status") == "compiled":
        candidate["workflow"] = copy.deepcopy(workflow_compilation["workflow"])
        candidate_config["services"][name] = copy.deepcopy(candidate)
    elif workflow_compilation.get("status") == "draft_only" and "processing" in data:
        # A changed declarative graph must not retain an old executable graph
        # when the reviewed catalog has been removed or is not yet available.
        candidate.pop("workflow", None)
        candidate_config["services"][name] = copy.deepcopy(candidate)
    registration_conflicts = service_registration_conflicts(
        candidate_config, name, candidate
    )
    registry_errors = validate_registry(candidate_config)
    activation_blockers = _service_activation_blockers(candidate_config, candidate)
    if registration_conflicts:
        activation_blockers.extend(registration_conflicts)
    if registry_errors or activation_blockers:
        return web.json_response(
            {
                "error": "service is not activatable",
                "details": sorted(set(registry_errors)),
                "activation_blockers": sorted(set(activation_blockers)),
            },
            status=400,
        )

    # Handle proxy_port lifecycle if changing
    if "proxy_port" in exempt_changes:
        new_proxy_port = exempt_changes["proxy_port"]
        old_proxy_port = svc.get("proxy_port")
        # PortProxy disabled — nginx handles proxy routing via nginx-manager.sh
        logger.info(f"Service config: updated proxy_port for '{name}' to {new_proxy_port}")
        asyncio.create_task(_regenerate_nginx_config())

    # Apply all exempt changes at once
    for field, value in exempt_changes.items():
        svc[field] = value

    # Save if any exempt fields changed
    if exempt_changes:
        _services_config["services"][name] = svc
        _save_services_config(_services_config)
        logger.info(f"Service config: toggled {' '.join(exempt_changes.keys())} for '{name}'")

    # Strip exempt fields from data so they aren't processed again
    data = {
        k: v for k, v in data.items()
        if k not in exempt_changes and k not in _SERVICE_REGISTRY_CONTROL_FIELDS
    }

    # Update allowed fields.  The same allowlist is used for validation and
    # persistence so a GUI edit cannot be silently discarded.  Exempt fields
    # (handled above): protected, cpu_only, proxy_port.
    workflow_changed = workflow_compilation.get("status") == "compiled" or (
        workflow_compilation.get("status") == "draft_only" and "processing" in data
    )
    if data:
        for field in allowed_fields:
            if field in data:
                svc[field] = data[field]
        # The executable graph is controller-owned output of the reviewed
        # compiler; never let a raw GUI field overwrite it after validation.
        if workflow_compilation.get("status") == "compiled":
            svc["workflow"] = copy.deepcopy(workflow_compilation["workflow"])
        elif workflow_changed:
            svc.pop("workflow", None)
        _services_config["services"][name] = svc
        _save_services_config(_services_config)
        logger.info(f"Service config: updated '{name}' — {list(data.keys())}")
        if any(k in data for k in ("port", "enabled", "proxy_port")):
            asyncio.create_task(_regenerate_nginx_config())
    elif workflow_changed:
        if workflow_compilation.get("status") == "compiled":
            svc["workflow"] = copy.deepcopy(workflow_compilation["workflow"])
        else:
            svc.pop("workflow", None)
        _services_config["services"][name] = svc
        _save_services_config(_services_config)

    return web.json_response({"status": "updated", "service": svc})


async def handle_service_preview(request: web.Request):
    """POST /v1/services/preview — validate a declarative service draft.

    Preview is intentionally side-effect free.  It lets the GUI describe an
    input contract, processing graph, resources and model targets without
    creating a systemd unit, changing scheduler state, or writing the live
    registry.  Activation remains the existing CAS-protected create/update
    operation after a human or policy gate accepts this result.
    """
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"error": "JSON body must be an object"}, status=400)

    expected_fingerprint = data.get("expected_registry_fingerprint")
    current_fingerprint = registry_summary(
        _services_config, owner="controller"
    )["fingerprint"]
    if (
        expected_fingerprint is not None
        and expected_fingerprint != current_fingerprint
    ):
        return web.json_response(
            {
                "error": "registry changed; refresh before preview",
                "code": "registry_revision_conflict",
                "current_fingerprint": current_fingerprint,
            },
            status=409,
        )

    name = data.get("name")
    if not name:
        return web.json_response({"error": "Missing 'name'"}, status=400)
    operation = str(data.get("operation", "create")).strip().lower()
    if operation not in {"create", "update"}:
        return web.json_response(
            {"error": "operation must be 'create' or 'update'"}, status=400
        )

    control_fields = {
        "name",
        "operation",
        "expected_registry_fingerprint",
    }
    candidate = {
        key: copy.deepcopy(value)
        for key, value in data.items()
        if key not in control_fields
    }
    candidate.setdefault("enabled", False)
    candidate.setdefault("port", 0)
    candidate.setdefault("type", "other")
    candidate.setdefault("routing_group_type", "llm")
    # The preview payload keeps the route name outside the service body.  Add
    # it to the candidate before compiling so the workflow compiler can derive
    # a stable graph identity (the create path already includes ``name``).
    candidate.setdefault("name", str(name))

    errors = list(validate_service_definition(str(name), candidate))
    runtime_fields = _declarative_runtime_field_errors(candidate)
    if runtime_fields:
        errors.append(
            "declarative services cannot set runtime controls: "
            + ", ".join(runtime_fields)
        )
    activation_blockers: list[str] = []
    if candidate.get("enabled") is True:
        activation_blockers.append("declarative_activation_required")
    existing = (_services_config.get("services") or {}).get(name)
    if operation == "create" and existing is not None:
        errors.append("service already exists; use operation='update'")
    if operation == "update" and existing is None:
        errors.append("service does not exist; use operation='create'")

    candidate_config = copy.deepcopy(_services_config or {})
    services = candidate_config.setdefault("services", {})
    if isinstance(services, dict):
        services[str(name)] = candidate
    workflow_compilation = _compile_declarative_processing(candidate_config, candidate)
    if workflow_compilation.get("status") == "compiled":
        candidate["workflow"] = copy.deepcopy(workflow_compilation["workflow"])
        if isinstance(services, dict):
            services[str(name)] = candidate
    elif workflow_compilation.get("status") == "blocked":
        activation_blockers.extend(workflow_compilation.get("blockers", []))
    activation_blockers.extend(
        service_registration_conflicts(candidate_config, str(name), candidate)
    )
    errors.extend(validate_registry(candidate_config))

    # A reference is metadata until its reviewed manifest is present.  Keep
    # this visible as an activation blocker instead of silently treating a
    # path/ID as an executable instruction.
    activation_blockers.extend(_service_activation_blockers(candidate_config, candidate))

    revision_preview = None
    if not errors:
        try:
            revision_catalog = service_revision_catalog_from_document(
                candidate_config.get("service_revision_catalog")
            )
            latest_revision = revision_catalog.latest(str(name))
            revision = make_service_revision(
                str(name),
                candidate,
                revision=(latest_revision.revision + 1) if latest_revision else 1,
            )
            revision_preview = {
                "schema_version": revision.schema_version,
                "name": revision.name,
                "revision": revision.revision,
                "fingerprint": revision.fingerprint,
                "state": revision.state.value,
            }
        except ServiceRevisionError as exc:
            errors.append(str(exc))

    try:
        from sanitize_registry import sanitize_registry

        safe_candidate = sanitize_registry({"name": name, **candidate})
    except Exception:
        # Sanitization is a presentation aid; validation must remain usable if
        # an optional export helper is unavailable in a minimal test image.
        safe_candidate = {"name": name, **candidate}

    return web.json_response(
        {
            "status": "preview",
            "valid": not errors and not activation_blockers,
            "errors": sorted(set(errors)),
            "activation_blockers": sorted(set(activation_blockers)),
            "registry_fingerprint": current_fingerprint,
            "service": safe_candidate,
            "service_revision_preview": revision_preview,
            "resource_preview": {
                "dependencies": list(candidate.get("dependencies", []))
                if isinstance(candidate.get("dependencies"), list)
                else [],
                "models": list(candidate.get("models", []))
                if isinstance(candidate.get("models"), list)
                else [],
                "resource_requirements": copy.deepcopy(
                    candidate.get("resource_requirements", {})
                )
                if isinstance(candidate.get("resource_requirements"), Mapping)
                else {},
            },
            "workflow_compilation": {
                key: value
                for key, value in workflow_compilation.items()
                if key
                in {
                    "status",
                    "errors",
                    "blockers",
                    "reason",
                    "stage_count",
                    "stage_ids",
                    "workflow_fingerprint",
                    "workflow",
                }
            },
            "writes_registry": False,
            "starts_processes": False,
        }
    )


async def handle_service_create(request: web.Request):
    """POST /services — Create a new service endpoint."""
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"error": "JSON body must be an object"}, status=400)

    expected_fingerprint = data.get("expected_registry_fingerprint")
    if expected_fingerprint is not None:
        current_fingerprint = registry_summary(_services_config, owner="controller")["fingerprint"]
        if expected_fingerprint != current_fingerprint:
            return web.json_response(
                {
                    "error": "registry changed; refresh before creating service",
                    "code": "registry_revision_conflict",
                    "current_fingerprint": current_fingerprint,
                },
                status=409,
            )

    name = data.get("name")
    if not name:
        return web.json_response({"error": "Missing 'name'"}, status=400)

    create_allowed_fields = {
        "name", "display", "type", "enabled", "systemd_unit", "port",
        "model_path", "launch_args", "priority", "cpuset", "protected",
        "cpu_only", "proxy_port", "speculative_decoding", "health_path",
        "env_overrides", "gpu_id", "routing_group", "routing_group_type",
        "bundle", "linked_to", "linked_from", "http_path",
    } | _DYNAMIC_SERVICE_FIELDS
    unknown_fields = sorted(
        set(data) - create_allowed_fields - _SERVICE_REGISTRY_CONTROL_FIELDS
    )
    if unknown_fields:
        return web.json_response(
            {"error": "unsupported service fields", "fields": unknown_fields},
            status=400,
        )

    declarative_create = bool(
        data.get("type") == "orchestrator"
        or any(field in data for field in _DYNAMIC_SERVICE_FIELDS)
    )
    if declarative_create:
        runtime_fields = _declarative_runtime_field_errors(data)
        if runtime_fields:
            return web.json_response(
                {
                    "error": "declarative services cannot set runtime controls",
                    "fields": runtime_fields,
                },
                status=400,
            )
        if data.get("enabled") is True:
            return web.json_response(
                {
                    "error": "declarative services require reviewed activation",
                    "activation_blockers": ["declarative_activation_required"],
                },
                status=400,
            )

    if name in _services_config.get("services", {}):
        return web.json_response({"error": f"Service '{name}' already exists"}, status=409)

    svc = {
        "name": name,
        "display": data.get("display", name),
        "type": data.get("type", "other"),
        "enabled": data.get("enabled", False),
        "systemd_unit": data.get(
            "systemd_unit", None if declarative_create else f"{name}.service"
        ),
        "port": data.get("port", 0),
        "model_path": data.get("model_path", ""),
        "launch_args": data.get("launch_args", []),
        "priority": data.get("priority", 50),
        "cpuset": data.get("cpuset", ""),
        "protected": data.get("protected", False),
        "cpu_only": data.get("cpu_only", False),
        "proxy_port": data.get("proxy_port"),  # None = disabled
    }
    # Preserve every validated field accepted by this API. The previous loop
    # copied only workflow fields and silently discarded ordinary routing,
    # bundle and health fields after validating them.
    for field in create_allowed_fields - {"name"}:
        if field in data:
            svc[field] = data[field]

    validation_errors = validate_service_definition(name, svc)
    if validation_errors:
        return web.json_response(
            {"error": "invalid service definition", "details": validation_errors},
            status=400,
        )

    candidate_config = copy.deepcopy(_services_config or {})
    candidate_config.setdefault("services", {})[name] = copy.deepcopy(svc)
    workflow_compilation = _compile_declarative_processing(candidate_config, svc)
    if workflow_compilation.get("status") == "blocked":
        return web.json_response(
            {
                "error": "service processing does not compile",
                "activation_blockers": workflow_compilation.get("blockers", []),
                "workflow_compilation": {
                    key: value
                    for key, value in workflow_compilation.items()
                    if key in {"status", "errors", "blockers", "reason"}
                },
            },
            status=400,
        )
    if workflow_compilation.get("status") == "compiled":
        svc["workflow"] = copy.deepcopy(workflow_compilation["workflow"])
        candidate_config["services"][name] = copy.deepcopy(svc)
    registration_conflicts = service_registration_conflicts(
        candidate_config, name, svc
    )
    registry_errors = validate_registry(candidate_config)
    activation_blockers = _service_activation_blockers(candidate_config, svc)
    if registration_conflicts:
        activation_blockers.extend(registration_conflicts)
    if registry_errors or activation_blockers:
        return web.json_response(
            {
                "error": "service is not activatable",
                "details": sorted(set(registry_errors)),
                "activation_blockers": sorted(set(activation_blockers)),
            },
            status=400,
        )

    if "services" not in _services_config:
        _services_config["services"] = {}
    _services_config["services"][name] = svc
    _save_services_config(_services_config)
    # Start proxy if proxy_port set and service enabled
    proxy_port = svc.get("proxy_port")
    # PortProxy disabled — nginx handles proxy routing via nginx-manager.sh
    logger.info(f"Service config: created '{name}'")
    if svc.get("proxy_port"):
        asyncio.create_task(_regenerate_nginx_config())
    return web.json_response({"status": "created", "service": svc}, status=201)


async def handle_service_delete(request: web.Request):
    """DELETE /services/{name} — Remove a service config."""
    name = request.match_info["name"]
    svc = _services_config.get("services", {}).get(name)
    if not svc:
        return web.json_response({"error": f"Service '{name}' not found"}, status=404)

    if svc.get("protected"):
        return web.json_response({"error": f"Service '{name}' is protected"}, status=403)

    # Stop proxy if running
    if name in _port_proxies:
        asyncio.create_task(_port_proxies[name].stop())
        del _port_proxies[name]

    del _services_config["services"][name]
    _save_services_config(_services_config)
    logger.info(f"Service config: deleted '{name}'")
    return web.json_response({"status": "deleted", "name": name})


async def handle_service_restart(request: web.Request):
    """POST /services/{name}/restart — Restart a service via explicit stop→wait→start."""
    name = request.match_info["name"]
    svc = _services_config.get("services", {}).get(name)
    if not svc:
        return web.json_response({"error": f"Service '{name}' not found"}, status=404)

    unit = svc.get("systemd_unit")
    if not unit:
        return web.json_response({"error": f"No systemd unit for '{name}'"}, status=400)

    try:
        # Step 1: Stop the service
        logger.info(f"Service restart: stopping '{name}' ({unit})")
        proc = await asyncio.create_subprocess_exec(
            "sudo", "systemctl", "stop", unit,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
        if proc.returncode != 0:
            return web.json_response(
                {"error": f"systemctl stop failed: {stderr.decode().strip()}"},
                status=502,
            )

        # Step 2: Wait for unit to become inactive
        deadline = time.time() + 15
        while time.time() < deadline:
            check = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL,
            )
            sout, _ = await asyncio.wait_for(check.communicate(), timeout=5)
            if sout.decode().strip() != "active":
                break
            await asyncio.sleep(0.5)
        else:
            logger.warning(f"Service restart: '{name}' did not become inactive in time")

        # Step 3: Start the service
        logger.info(f"Service restart: starting '{name}' ({unit})")
        proc = await asyncio.create_subprocess_exec(
            "sudo", "systemctl", "start", unit,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
        if proc.returncode != 0:
            return web.json_response(
                {"error": f"systemctl start failed: {stderr.decode().strip()}"},
                status=502,
            )

        # Step 4: Wait for unit to become active
        deadline = time.time() + 30
        active = False
        while time.time() < deadline:
            check = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL,
            )
            sout, _ = await asyncio.wait_for(check.communicate(), timeout=5)
            if sout.decode().strip() == "active":
                active = True
                break
            await asyncio.sleep(0.5)

        if active:
            logger.info(f"Service: restarted '{name}' ({unit})")
            return web.json_response({"status": "restarted", "service": name, "unit": unit, "active": True})
        else:
            return web.json_response(
                {"status": "started", "service": name, "unit": unit, "active": False,
                 "warning": "Unit did not report active within timeout"},
            )
    except Exception as e:
        return web.json_response({"error": str(e)}, status=502)


async def handle_service_status(request: web.Request):
    """GET /services/{name}/status — Check if service is running."""
    name = request.match_info["name"]
    svc = _services_config.get("services", {}).get(name)
    if not svc:
        return web.json_response({"error": f"Service '{name}' not found"}, status=404)

    unit = svc.get("systemd_unit")
    if not unit:
        return web.json_response({"active": "unknown", "reason": "no systemd unit"})

    try:
        proc = await asyncio.create_subprocess_exec(
            "systemctl", "is-active", unit,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=10)
        active = stdout.decode().strip() if proc.returncode == 0 else "inactive"
        return web.json_response({"service": name, "unit": unit, "active": active})
    except Exception as e:
        return web.json_response({"error": str(e)}, status=502)


async def handle_service_toggle(request: web.Request):
    """POST /services/{name}/toggle — Start if stopped, stop if running."""
    name = request.match_info["name"]
    # B1 BUGFIX: fetch a fresh services config for the gated decisions
    # below (protected-check + unit lookup) so a stale module-level
    # _services_config cache from another reload path doesn't cause us
    # to 403/404/400 incorrectly. The actual _load_bundle/_unload_bundle
    # call still reloads config internally, so the action is correct.
    cfg = None
    try:
        cfg = _load_services_config() or _services_config
    except Exception:
        cfg = _services_config
    svc = (cfg or _services_config).get("services", {}).get(name)
    if not svc:
        return web.json_response({"error": f"Service '{name}' not found"}, status=404)
    if svc.get("protected"):
        return web.json_response({"error": f"Service '{name}' is protected"}, status=403)
    unit = svc.get("systemd_unit")
    if not unit:
        return web.json_response({"error": f"No systemd_unit for '{name}'"}, status=400)

    # Check current state
    proc = await asyncio.create_subprocess_exec(
        "systemctl", "is-active", unit,
        stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL
    )
    stdout, _ = await proc.communicate()
    is_active = stdout.decode().strip() == "active"

    action = "stop" if is_active else "start"

    bundles = _resolve_bundles()
    if action == "start":
        bundle = _get_bundle_for_service(name, bundles)
        if bundle:
            bundle_name = bundle.get("bundle_name")
            if bundle_name:
                ok = await _run_bundle_transition(
                    bundle_name,
                    lambda: _load_bundle(bundle_name),
                    desired_state=BundleDesiredState.RUNNING,
                    reason=f"service-toggle-start:{name}",
                )
                return web.json_response({
                    "success": ok,
                    "service": name,
                    "bundle": bundle_name,
                    "action": "start (via fenced bundle transition)",
                })
    elif action == "stop":
        bundle = _get_bundle_for_service(name, bundles)
        if bundle:
            bundle_name = bundle.get("bundle_name")
            if bundle_name:
                ok = await _run_bundle_transition(
                    bundle_name,
                    lambda: _unload_bundle(bundle_name),
                    desired_state=BundleDesiredState.STOPPED,
                    reason=f"service-toggle-stop:{name}",
                )
                return web.json_response({
                    "success": ok,
                    "service": name,
                    "bundle": bundle_name,
                    "action": "stop (via fenced bundle transition)",
                })

    proc = await asyncio.create_subprocess_exec(
        "sudo", "systemctl", action, unit,
        stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.PIPE
    )
    _, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)

    if proc.returncode == 0:
        logger.info(f"Service toggle: {name} {action}ped")
        return web.json_response({"success": True, "service": name, "action": action})
    else:
        return web.json_response(
            {"error": f"systemctl {action} failed: {stderr.decode().strip()}"},
            status=500
        )


async def handle_bundle_preload(request: web.Request):
    """POST /v1/bundles/preload — preload a bundle through queue admission.

    The MCP ``preload_bundle`` tool is deliberately a thin client of the live
    controller.  Keep the eviction, priority, and lifecycle fence in the
    controller's canonical queue path instead of duplicating those decisions
    in the MCP process.
    """
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"ok": False, "preload_state": "invalid_request",
                                  "errors": ["Invalid JSON body"]}, status=400)
    if not isinstance(data, Mapping):
        return web.json_response({"ok": False, "preload_state": "invalid_request",
                                  "errors": ["JSON body must be an object"]}, status=400)
    bundle_name = str(data.get("bundle_name") or "").strip()
    if not bundle_name:
        return web.json_response({"ok": False, "preload_state": "invalid_request",
                                  "errors": ["bundle_name is required"]}, status=400)
    bundles = _resolve_bundles()
    if bundle_name not in bundles:
        return web.json_response({"ok": False, "bundle": bundle_name,
                                  "preload_state": "unknown_bundle",
                                  "errors": [f"Bundle '{bundle_name}' not found"]}, status=404)
    try:
        priority = int(data.get("priority", 5))
    except (TypeError, ValueError):
        return web.json_response({"ok": False, "bundle": bundle_name,
                                  "preload_state": "invalid_request",
                                  "errors": ["priority must be an integer"]}, status=400)
    try:
        wait_timeout = max(1.0, min(900.0, float(data.get("wait_timeout", 120.0))))
    except (TypeError, ValueError):
        return web.json_response({"ok": False, "bundle": bundle_name,
                                  "preload_state": "invalid_request",
                                  "errors": ["wait_timeout must be numeric"]}, status=400)
    try:
        loaded = await asyncio.wait_for(
            _evict_then_load_bundle(
                bundle_name,
                reason="mcp_preload",
                priority=priority,
            ),
            timeout=wait_timeout,
        )
    except asyncio.TimeoutError:
        return web.json_response({"ok": False, "bundle": bundle_name,
                                  "preload_state": "timeout",
                                  "errors": [f"bundle admission exceeded {wait_timeout:.1f}s"]},
                                 status=202)
    except BundleAdmissionDeferred as exc:
        return web.json_response({"ok": False, "bundle": bundle_name,
                                  "preload_state": "deferred",
                                  "errors": [str(exc)]}, status=409)
    except Exception as exc:
        logger.error("bundle preload failed for %s: %s", bundle_name, exc, exc_info=True)
        return web.json_response({"ok": False, "bundle": bundle_name,
                                  "preload_state": "failed",
                                  "errors": [str(exc)]}, status=500)
    if not loaded:
        return web.json_response({"ok": False, "bundle": bundle_name,
                                  "preload_state": "failed",
                                  "errors": ["bundle admission or load failed"]}, status=409)
    return web.json_response({"ok": True, "bundle": bundle_name,
                              "preload_state": "loaded", "priority": priority})


async def handle_service_stop(request: web.Request):
    """POST /services/{name}/stop — idempotent explicit stop, never starts."""
    name = request.match_info["name"]
    try:
        cfg = _load_services_config() or _services_config
    except Exception:
        cfg = _services_config
    svc = (cfg or _services_config).get("services", {}).get(name)
    if not svc:
        return web.json_response({"error": f"Service '{name}' not found"}, status=404)
    if svc.get("protected"):
        return web.json_response({"error": f"Service '{name}' is protected"}, status=403)
    unit = svc.get("systemd_unit")
    if not unit:
        return web.json_response({"error": f"No systemd_unit for '{name}'"}, status=400)

    bundles = _resolve_bundles()
    bundle = _get_bundle_for_service(name, bundles)
    if bundle:
        bundle_name = bundle.get("bundle_name")
        if bundle_name:
            ok = await _run_bundle_transition(
                bundle_name,
                lambda: _unload_bundle(bundle_name),
                desired_state=BundleDesiredState.STOPPED,
                reason=f"service-stop:{name}",
            )
            return web.json_response({
                "success": bool(ok), "service": name, "bundle": bundle_name,
                "action": "stop (via _unload_bundle)", "idempotent": True,
            }, status=200 if ok else 500)

    proc = await asyncio.create_subprocess_exec(
        "systemctl", "is-active", unit,
        stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL,
    )
    stdout, _ = await proc.communicate()
    if stdout.decode().strip() != "active":
        return web.json_response({"success": True, "service": name, "action": "already_stopped", "idempotent": True})

    proc = await asyncio.create_subprocess_exec(
        "sudo", "systemctl", "stop", unit,
        stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.PIPE,
    )
    _, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
    if proc.returncode == 0:
        logger.info(f"Service explicit stop: {name}")
        return web.json_response({"success": True, "service": name, "action": "stop", "idempotent": True})
    return web.json_response(
        {"error": f"systemctl stop failed: {stderr.decode().strip()}"}, status=500
    )


# ── Port Proxy Handlers ──────────────────────────────────────────────

async def handle_port_proxies_list(request: web.Request):
    """GET /port-proxies — List all active port proxies."""
    result = {}
    for name, proxy in _port_proxies.items():
        svc = _services_config.get("services", {}).get(name, {})
        result[name] = {
            "proxy_port": proxy.listen_port,
            "target_host": proxy.target_host,
            "target_port": proxy.target_port,
            "is_running": proxy.is_running,
            "service_config": svc.get("display", name),
            "service_enabled": svc.get("enabled", False),
        }
    return web.json_response(result)


async def handle_port_proxy_start(request: web.Request):
    """POST /port-proxies/{name}/start — Start proxy for a service."""
    name = request.match_info["name"]
    svc = _services_config.get("services", {}).get(name)
    if not svc:
        return web.json_response({"error": f"Service '{name}' not found"}, status=404)

    proxy_port = svc.get("proxy_port")
    if not proxy_port:
        return web.json_response({"error": f"Service '{name}' has no proxy_port configured"}, status=400)

    if name in _port_proxies:
        return web.json_response({"error": f"Proxy for '{name}' already running"}, status=409)

    # PortProxy disabled — nginx handles proxy routing via nginx-manager.sh
    asyncio.create_task(_regenerate_nginx_config())
    return web.json_response({"status": "nginx_configured", "name": name, "port": proxy_port})


async def handle_port_proxy_stop(request: web.Request):
    """POST /port-proxies/{name}/stop — Stop proxy for a service."""
    name = request.match_info["name"]
    if name not in _port_proxies:
        return web.json_response({"error": f"No proxy running for '{name}'"}, status=404)

    # PortProxy disabled — nginx handles proxy routing via nginx-manager.sh
    asyncio.create_task(_regenerate_nginx_config())
    logger.info(f"Port proxy: nginx config updated for '{name}'")
    return web.json_response({"status": "nginx_updated", "name": name})


# ── Bundle Proxy Handlers (Phase 3) ───────────────────────────────

async def _forward_bundle_request(
    request: web.Request,
    bundle: dict,
    sub_path: str = "",
) -> web.Response:
    """Forward an HTTP request to the first healthy service in a bundle.

    If *sub_path* is empty, forwards to the bundle's first service port.
    Otherwise prepends sub_path to the backend URL.
    """
    services = _services_config.get("services", {})
    # Find the first service with a port
    target_port = None
    for svc_name in bundle.get("services", []):
        svc = services.get(svc_name, {})
        if svc.get("port"):
            target_port = int(svc["port"])
            break

    if target_port is None:
        return web.json_response(
            {"error": "Bundle has no services with configured ports"},
            status=502,
        )

    # Build backend URL — preserve the original request path after /proxy/{bundle_name}
    backend_path = sub_path if sub_path else request.path
    if not backend_path.startswith("/"):
        backend_path = "/" + backend_path
    # Preserve query string
    qs = request.query_string
    url = f"http://localhost:{target_port}{backend_path}"
    if qs:
        url = f"{url}?{qs}"

    # Read request body
    body = None
    if request.can_read_body:
        body = await request.read()

    # Forward headers (strip hop-by-hop)
    fwd_headers = {
        k: v for k, v in request.headers.items()
        if k.lower() not in ("host", "content-length", "transfer-encoding", "x-forwarded-for")
    }
    fwd_headers["X-Forwarded-For"] = request.remote or "unknown"
    fwd_headers["X-Bundle-Name"] = bundle.get("bundle_name", bundle.get("_bundle_name", "unknown"))

    try:
        async with session.request(
            method=request.method,
            url=url,
            data=body,
            headers=fwd_headers,
            timeout=ClientTimeout(total=300),
            ssl=False,
        ) as resp:
            resp_body = await resp.read()
            response = web.Response(status=resp.status, body=resp_body)
            # Forward relevant response headers
            for hdr in ("content-type", "content-disposition", "x-request-id"):
                if hdr in resp.headers:
                    response.headers[hdr] = resp.headers[hdr]
            return response
    except asyncio.TimeoutError:
        return web.json_response(
            {"error": f"Backend timeout on port {target_port}"},
            status=504,
        )
    except Exception as e:
        logger.error(f"Bundle proxy forward error ({url}): {e}")
        return web.json_response(
            {"error": f"Backend error: {e}"},
            status=502,
        )


async def _trigger_bundle_load(
    bundle_name: str,
    bundle: dict,
    priority: int | None = None,
) -> bool:
    """Trigger loading of a bundle and all its linked bundles.

    Returns True if all bundles loaded successfully, False on failure.
    Starts services via systemd, polls for health, and signals queues.
    """
    if priority is None:
        priority = bundle.get("priority", 5)

    linked_names = _get_linked_bundles(bundle_name)

    # Collect all bundles to load (self + linked)
    all_bundles_to_load = [(bundle_name, bundle)]
    bundles = _resolve_bundles()
    for linked_name in linked_names:
        linked_bundle = bundles.get(linked_name)
        if linked_bundle:
            all_bundles_to_load.append((linked_name, linked_bundle))

    logger.info(
        f"BUNDLE PROXY: triggering load for {bundle_name} "
        f"(+ {len(linked_names)} linked: {linked_names}) "
        f"priority={priority}"
    )

    # Mark all queues as loading
    for bname, _ in all_bundles_to_load:
        q = _get_bundle_queue(bname)
        q.mark_loading()

    # Enqueue into per-GPU priority queues
    for bname, b in all_bundles_to_load:
        bgpu = b.get("gpu_id")
        if bgpu:
            gpu = _get_gpu_state(bgpu)
            gpu.enqueue(bname, priority, {
                "source": "bundle_proxy",
                "bundle_name": bname,
            })

    # Start services for all bundles in the group via systemd
    services = _services_config.get("services", {})
    for bname, b in all_bundles_to_load:
        for svc_name in b.get("services", []):
            svc = services.get(svc_name, {})
            unit = svc.get("systemd_unit")
            if unit:
                try:
                    await asyncio.create_subprocess_exec(
                        "sudo", "systemctl", "start", unit,
                        stdout=asyncio.subprocess.DEVNULL,
                        stderr=asyncio.subprocess.DEVNULL,
                    )
                    logger.info(f"BUNDLE PROXY: started {unit} for bundle {bname}")
                except Exception as e:
                    logger.warning(f"BUNDLE PROXY: failed to start {unit}: {e}")

    # Poll for all bundles to become healthy
    start_time = time.monotonic()
    all_healthy = True
    timeout = BUNDLE_PROXY_WAIT_TIMEOUT

    while time.monotonic() - start_time < timeout:
        all_ok = True
        for bname, b in all_bundles_to_load:
            if not _check_bundle_services_healthy(b):
                all_ok = False
                break
        if all_ok:
            # All bundles healthy — signal ready
            for bname, _ in all_bundles_to_load:
                _get_bundle_queue(bname).signal_ready()
                # Update GPU state
                bb = bundles.get(bname)
                if bb and bb.get("gpu_id"):
                    gpu = _get_gpu_state(bb["gpu_id"])
                    gpu.loaded_bundle = bname
                    gpu.bundle_priority = priority
                    gpu.state = "loaded"
            logger.info(
                f"BUNDLE PROXY: all bundles healthy: "
                f"{[bn for bn, _ in all_bundles_to_load]}"
            )
            all_healthy = True
            break
        await asyncio.sleep(2)
    else:
        # Timeout — mark all as failed
        all_healthy = False
        for bname, _ in all_bundles_to_load:
            _get_bundle_queue(bname).signal_failed(f"timeout loading bundle {bname}")
        logger.error(
            f"BUNDLE PROXY: timeout loading bundles "
            f"{[bn for bn, _ in all_bundles_to_load]}"
        )

    return all_healthy


async def handle_bundle_proxy(request: web.Request) -> web.Response:
    """POST/GET /proxy/{bundle_name}/{path:.*} — Route requests to a bundle.

    If the bundle's services are loaded and healthy, forwards immediately.
    If not loaded, queues the request, triggers loading, and forwards when ready.
    For linked bundles, loads all simultaneously and waits for all to be healthy.
    """
    bundle_name = request.match_info["bundle_name"]
    sub_path = request.match_info.get("path", "")

    # Look up the bundle
    bundles = _resolve_bundles()
    bundle = bundles.get(bundle_name)
    if not bundle:
        return web.json_response(
            {"error": f"Unknown bundle: '{bundle_name}'"},
            status=404,
        )
    bundle = dict(bundle)
    bundle["bundle_name"] = bundle_name

    queue = _get_bundle_queue(bundle_name)

    # Fast path: bundle already loaded and healthy
    if queue.is_ready and _check_bundle_services_healthy(bundle):
        queue.mark_served()
        return await _forward_bundle_request(request, bundle, sub_path)

    # Slow path: queue request and trigger load
    logger.info(
        f"BUNDLE PROXY: {bundle_name} not ready — queuing {request.method} "
        f"/proxy/{bundle_name}/{sub_path} (queue depth: {queue.queued_count})"
    )

    # Trigger bundle loading (non-blocking)
    asyncio.create_task(
        _trigger_bundle_load(bundle_name, bundle, bundle.get("priority"))
    )

    # Wait for bundle to become ready
    ready = await queue.wait_for_ready(timeout=BUNDLE_PROXY_WAIT_TIMEOUT)
    if ready and not queue.is_failed:
        queue.mark_served()
        return await _forward_bundle_request(request, bundle, sub_path)
    else:
        reason = queue._fail_reason or "bundle load timeout"
        logger.warning(f"BUNDLE PROXY: {bundle_name} failed: {reason}")
        return web.json_response(
            {
                "error": f"Bundle '{bundle_name}' unavailable",
                "reason": reason,
                "retry_after": 30,
            },
            status=503,
        )


async def handle_bundle_proxy_status(request: web.Request) -> web.Response:
    """GET /proxy — List all bundle proxy queues and their status."""
    result = {}
    bundles = _resolve_bundles()
    for bname, bundle in bundles.items():
        q = _get_bundle_queue(bname)
        healthy = _check_bundle_services_healthy(bundle) if bundle.get("services") else False
        result[bname] = {
            **q.to_dict(),
            "proxy_port": bundle.get("proxy_port"),
            "gpu_id": bundle.get("gpu_id"),
            "services": bundle.get("services", []),
            "services_healthy": healthy,
            "linked_to": _get_linked_bundles(bname),
        }
    return web.json_response(result)


async def handle_service_fix_degraded(request: web.Request):
    """POST /services/{name}/fix-degraded — Reset failed unit + restart."""
    name = request.match_info["name"]
    svc = _services_config.get("services", {}).get(name)
    if not svc:
        return web.json_response({"error": f"Service '{name}' not found"}, status=404)
    unit = svc.get("systemd_unit")
    if not unit:
        return web.json_response({"error": f"No systemd_unit for '{name}'"}, status=400)

    try:
        # Step 1: Kill any orphan process holding the port
        port = svc.get("port")
        if port:
            logger.info(f"Fix-degraded: killing any process on port {port}")
            fuser_proc = await asyncio.create_subprocess_exec(
                "sudo", "fuser", "-k", f"{port}/tcp",
                stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL,
            )
            await asyncio.wait_for(fuser_proc.communicate(), timeout=10)
            # Small delay to let the port free
            await asyncio.sleep(0.5)

        logger.info(f"Fix-degraded: reset-failed {unit}")
        proc = await asyncio.create_subprocess_exec(
            "sudo", "systemctl", "reset-failed", unit,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
        )
        await asyncio.wait_for(proc.communicate(), timeout=10)

        logger.info(f"Fix-degraded: restarting {unit}")
        proc = await asyncio.create_subprocess_exec(
            "sudo", "systemctl", "restart", unit,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=60)

        if proc.returncode == 0:
            logger.info(f"Fix-degraded: {unit} restarted successfully")
            return web.json_response({"success": True, "service": name, "unit": unit})
        else:
            return web.json_response(
                {"error": f"restart failed: {stderr.decode().strip()}"},
                status=502,
            )
    except Exception as e:
        return web.json_response({"error": str(e)}, status=502)


