# Headers whose presence on caller-supplied outbound requests would
# smuggle a credential past the upstream.  Forwarding them unchanged
# defeats the loopback allowlist.
_FORBIDDEN_PROXY_HEADER_NAMES = frozenset(
    {"authorization", "cookie", "proxy-authorization", "x-api-key"}
)


def _strip_credential_headers(headers: Any) -> dict[str, str]:
    """Return a copy of *headers* with credential headers removed.

    Non-dict inputs return an empty dict.  String values are preserved
    unchanged; bytes values are decoded as UTF-8 with replacement so
    that header construction cannot fail on caller-supplied garbage.
    """
    if not isinstance(headers, Mapping):
        return {}
    result: dict[str, str] = {}
    for key, value in headers.items():
        if not isinstance(key, str) or not key:
            continue
        # Header field names cannot legally contain surrounding whitespace,
        # but normalize it here so malformed caller-supplied mappings cannot
        # evade the credential denylist before aiohttp serializes them.
        if key.strip().lower() in _FORBIDDEN_PROXY_HEADER_NAMES:
            continue
        if isinstance(value, bytes):
            try:
                value = value.decode("utf-8")
            except UnicodeDecodeError:
                value = value.decode("utf-8", errors="replace")
        if not isinstance(value, str):
            continue
        result[key] = value
    return result


def _api_proxy_target_url(url: Any) -> str | None:
    """Validate *url* and return its canonical loopback target URL.

    Only http/https loopback URLs are considered.  Userinfo, missing
    or malformed ports, the controller's own LISTEN_PORT, and ports
    that are not declared on any enabled service in
    ``_services_config`` are rejected.  The returned URL is rebuilt from
    these validated parsed components, never from the caller's raw string.
    """
    from urllib.parse import urlparse, urlunparse

    if not isinstance(url, str) or not url:
        return None
    if any(ord(char) < 0x20 for char in url):
        return None
    try:
        parsed = urlparse(url)
    except ValueError:
        return None
    scheme = parsed.scheme.lower()
    if scheme not in {"http", "https"}:
        return None
    if parsed.username is not None or parsed.password is not None:
        return None
    hostname = parsed.hostname
    if hostname is None:
        return None
    hostname = hostname.lower()
    if hostname not in {"localhost", "127.0.0.1", "::1"}:
        return None
    try:
        port = parsed.port
    except ValueError:
        return None
    if port is None:
        return None
    if port == LISTEN_PORT:
        return None

    cfg = _services_config if isinstance(_services_config, Mapping) else {}
    services = cfg.get("services") if isinstance(cfg, Mapping) else None
    if not isinstance(services, Mapping):
        return None
    declared = False
    for svc in services.values():
        if not isinstance(svc, Mapping):
            continue
        if not svc.get("enabled", False):
            continue
        declared_ports = set()
        for field in ("port", "proxy_port"):
            value = svc.get(field)
            if isinstance(value, bool):
                continue
            if isinstance(value, int) and 0 < value < 65536:
                declared_ports.add(value)
        if port in declared_ports:
            declared = True
            break
    if not declared:
        return None

    # Rebuild the authority from the validated hostname and explicit port.
    # Brackets are required for the IPv6 loopback literal.
    authority_host = f"[{hostname}]" if ":" in hostname else hostname
    return urlunparse((scheme, f"{authority_host}:{port}", parsed.path, "", parsed.query, ""))


def _api_proxy_target_is_allowed(url: Any) -> bool:
    """Return True iff *url* points at an enabled service's declared port."""
    return _api_proxy_target_url(url) is not None


async def handle_api_proxy(request: web.Request) -> web.Response:
    """POST /api/proxy — Forward arbitrary HTTP requests to localhost backends (CORS proxy).

    Only explicit loopback http/https URLs whose port is declared as
    ``port`` or ``proxy_port`` on an enabled service in
    ``_services_config`` are accepted.  Userinfo, missing/malformed
    ports, the controller's own LISTEN_PORT, and undeclared ports are
    all rejected before any I/O.  Authorization, Cookie,
    Proxy-Authorization and X-API-Key headers are stripped from
    caller-supplied headers before forwarding.
    """
    try:
        body = await request.json()
    except (ValueError, json.JSONDecodeError):
        return web.json_response({"error": "Invalid JSON body"}, status=400)

    url = body.get("url")
    if not url:
        return web.json_response({"error": "Missing 'url' field"}, status=400)

    method = body.get("method", "GET").upper()
    allowed_methods = {"GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"}
    if method not in allowed_methods:
        return web.json_response({"error": f"Unsupported method: {method}"}, status=400)

    target_url = _api_proxy_target_url(url)
    if target_url is None:
        return web.json_response(
            {"error": "proxy target is not an enabled service port"},
            status=403,
        )

    req_headers = body.get("headers", {})
    safe_headers = _strip_credential_headers(req_headers)
    req_body = body.get("body")

    if req_body and isinstance(req_body, str):
        body_bytes = req_body.encode("utf-8")
    elif req_body:
        body_bytes = json.dumps(req_body).encode("utf-8")
    else:
        body_bytes = None

    if body_bytes and len(body_bytes) > 10 * 1024 * 1024:
        return web.json_response({"error": "Request body exceeds 10MB limit"}, status=413)

    timeout = ClientTimeout(total=30)
    start = time.monotonic()
    try:
        async with session.request(
            method,
            target_url,
            headers=safe_headers,
            data=body_bytes,
            timeout=timeout,
            ssl=False,
        ) as resp:
            elapsed_ms = int((time.monotonic() - start) * 1000)
            try:
                resp_body = await resp.text()
            except Exception:
                resp_body = ""
            return web.json_response({
                "status": resp.status,
                "headers": dict(resp.headers),
                "body": resp_body,
                "elapsed_ms": elapsed_ms,
            })
    except asyncio.TimeoutError:
        return web.json_response({"error": "Upstream request timed out"}, status=504)
    except aiohttp.ClientError as e:
        return web.json_response({"error": f"Upstream connection error: {e}"}, status=502)
    except Exception as e:
        return web.json_response({"error": str(e)}, status=500)


# ── Application Setup ──────────────────────────────────────────────

# ── Phase 4: explicit OOM recovery watchdog + scheduler health + MCP killer ─
# These three loops are the always-on "watchdog" tier. They run independently
# of any pusher / worker so that even if the vram pusher or scheduler stalls,
# OOM recovery still fires and stale MCP siblings still get killed.


async def _oom_recovery_watchdog_loop():
    """Dedicated OOM recovery watchdog. Runs every OOM_WATCHDOG_POLL_INTERVAL_S.

    Per adversarial #17: wrap entire body in try/except so the loop never dies.
    Per adversarial #19: use job-specific stall detection, not blanket timeout.
    Per adversarial #21: per-GPU stall timeout (180s gpu_primary, 120s gpu_secondary).

    Responsibilities:
      1. Update _last_oom_heartbeat_ts and (best-effort) write the Redis
         OOM_REDIS_HEARTBEAT key so peers can see this manager is alive.
      2. Promote GPUs stuck in 'detected' for too long to 'permanent_failed'
         so the system never hangs waiting for a recovery that won't run.
      3. Reset GPUs stuck in 'draining'/'verifying'/'recovering' back to
         'detected' so the pipeline can retry.
      4. Trigger recovery for any GPU currently in 'detected' (the primary
         recovery trigger — the vram pusher also fires, but this one is
         always on).
    """
    global _last_oom_heartbeat_ts
    logger.info("[oom-watchdog] Starting OOM recovery watchdog")
    while True:
        try:
            await asyncio.sleep(OOM_WATCHDOG_POLL_INTERVAL_S)

            # ── Heartbeat: always-on (every poll = every 2s) ──
            now = time.time()
            _last_oom_heartbeat_ts = now

            # Best-effort Redis write every OOM_WATCHDOG_HEARTBEAT_INTERVAL_S
            # (default 10s). We deliberately don't fail the loop if Redis
            # is unreachable.
            heartbeat_count = getattr(_oom_recovery_watchdog_loop, "_heartbeat_count", 0) + 1
            # Functions accept arbitrary attribute assignment at runtime;
            # Pyright models them as plain FunctionType so we silence.
            _oom_recovery_watchdog_loop._heartbeat_count = heartbeat_count  # type: ignore[attr-defined]
            # Phase 5: refresh dead-letter cache every ~30s (15 polls * 2s)
            if heartbeat_count % 15 == 0:
                try:
                    await _refresh_dead_letter_cache()
                except Exception as _dl_cache_err:
                    logger.debug(f"[oom-watchdog] dead-letter cache refresh failed: {_dl_cache_err}")
            if heartbeat_count % max(
                1, OOM_WATCHDOG_HEARTBEAT_INTERVAL_S // OOM_WATCHDOG_POLL_INTERVAL_S
            ) == 0:
                try:
                    redis_client = globals().get("_redis_client") or globals().get("redis_client")
                    if redis_client is not None:
                        payload = json.dumps({
                            "ts": now,
                            "count": heartbeat_count,
                            "hostname": socket.gethostname(),
                        })
                        await asyncio.to_thread(
                            redis_client.set,
                            OOM_REDIS_HEARTBEAT,
                            payload,
                            ex=60,  # 60s TTL — peer treats key absence as dead
                        )
                except Exception as e:
                    logger.debug(f"[oom-watchdog] heartbeat write failed: {e}")

            # ── Stale `evicting` flags: owner-aware and bounded ──
            try:
                _reap_stale_evicting_flags(now)
            except Exception as _stale_evict_err:
                logger.debug(f"[oom-watchdog] stale evicting sweep failed: {_stale_evict_err}")

            # ── Stall detection: GPUs stuck in 'detected' → permanent_failed ──
            for gpu_id, bs in list(_gpu_states.items()):
                if bs.oom_state == "detected" and bs.oom_state_since > 0:
                    age = now - bs.oom_state_since
                    # Per adversarial #21: per-GPU timeout. The constants
                    # are deliberately re-checked (not snapshotted) so a
                    # future per-GPU config can override without touching
                    # this loop.
                    timeout = OOM_EVICTING_STUCK_TIMEOUT_S  # default 180s
                    if gpu_id == "gpu_primary":
                        timeout = 180
                    elif gpu_id == "gpu_secondary":
                        timeout = 120
                    if age > timeout:
                        logger.error(
                            f"[oom-watchdog] {gpu_id} stuck in 'detected' for "
                            f"{age:.1f}s (> {timeout}s), forcing permanent_failed"
                        )
                        try:
                            bs.set_oom_state(
                                "permanent_failed",
                                source="_oom_recovery_watchdog_loop",
                                reason=f"stuck in detected for {age:.1f}s",
                            )
                            bs.oom_permanent_failure_count += 1
                            # Phase 5: record to dead-letter list if we know the job
                            try:
                                wid = bs.oom_active_recovery_job_id or ""
                                if wid:
                                    await _add_to_dead_letter(
                                        job_id=wid,
                                        gpu_id=gpu_id,
                                        reason=f"stuck_in_detected {age:.1f}s",
                                        last_state="permanent_failed",
                                    )
                            except Exception as _dl_err:
                                logger.debug(f"[oom-watchdog] dead-letter add failed: {_dl_err}")
                        except Exception as e:
                            logger.warning(f"[oom-watchdog] set_oom_state failed: {e}")

                elif (
                    bs.oom_state in ("draining", "verifying", "recovering")
                    and bs.oom_state_since > 0
                ):
                    age = now - bs.oom_state_since
                    timeout = OOM_RECOVERY_TIMEOUT_S  # 30s for non-detected stages
                    if age > timeout:
                        logger.warning(
                            f"[oom-watchdog] {gpu_id} stuck in "
                            f"'{bs.oom_state}' for {age:.1f}s, "
                            f"escalating to detected for retry"
                        )
                        try:
                            bs.set_oom_state(
                                "detected",
                                source="_oom_recovery_watchdog_loop",
                                reason=f"stuck in {bs.oom_state}",
                            )
                        except Exception as e:
                            logger.warning(f"[oom-watchdog] reset to detected failed: {e}")

            # ── Recovery trigger: any GPU in 'detected' → kick pipeline ──
            for gpu_id, bs in list(_gpu_states.items()):
                if bs.oom_state != "detected":
                    continue
                inflight_ts = _oom_recovery_in_progress.get(gpu_id)
                if inflight_ts and now - inflight_ts < OOM_RECOVERY_TIMEOUT_S:
                    # Recovery already running — don't pile up
                    continue
                service_name = _resolve_service_for_gpu(gpu_id)
                _oom_recovery_in_progress[gpu_id] = now
                job_id = bs.oom_active_recovery_job_id or ""
                reason = bs.oom_last_reason or "watchdog_detected"
                try:
                    asyncio.create_task(
                        _run_recovery_with_cleanup(gpu_id, service_name, job_id, reason)
                    )
                except Exception as e:
                    logger.error(f"[oom-watchdog] create_task for {gpu_id} failed: {e}")
                    _oom_recovery_in_progress.pop(gpu_id, None)

        except asyncio.CancelledError:
            logger.info("[oom-watchdog] Shutting down")
            raise
        except Exception as e:
            # Per adversarial #17: never let the watchdog die.
            logger.exception(f"[oom-watchdog] Unhandled exception in loop: {e}")
            await asyncio.sleep(1)  # back off briefly


async def _run_recovery_with_cleanup(
    gpu_id: str, service_name: str, job_id: str, reason: str
):
    """Wrap _oom_recovery_pipeline with bookkeeping for _oom_recovery_in_progress.

    The watchdog fires every 2s; without this wrapper two ticks could both
    decide the GPU is detected and both schedule a recovery. The wrapper
    guarantees _oom_recovery_in_progress is cleared even if the pipeline
    raises (so the next tick can re-evaluate).
    """
    try:
        await _oom_recovery_pipeline(
            gpu_id, service_name, job_id=job_id, oom_reason=reason
        )
    except Exception as e:
        logger.warning(
            f"[oom-watchdog] _oom_recovery_pipeline({gpu_id}) raised: {e}"
        )
    finally:
        _oom_recovery_in_progress.pop(gpu_id, None)


# Phase 5.2.49: stale-job reaper. Periodically scans Redis for in_flight jobs
# whose started_at is older than the safe deadline (forward_timeout +
# post_load_grace + 5min buffer). Force-fails them so the scheduler stops
# re-feeding the queue. Complements the Redis TTL added in queue_engine.py.
_STALE_JOB_REAPER_INTERVAL_S = 60   # poll every 60s
_STALE_JOB_DEFAULT_DEADLINE_S = 2700  # 45 min — same as TTL in queue_engine.py


async def _stale_job_continuation_signals(redis_client, data: dict) -> tuple[bool, bool, bool]:
    """Return (PEL owns job, stream contains job, backend running).

    Inspection failures are treated conservatively as continuation signals so
    the reaper cannot terminalize a job on incomplete evidence.
    """
    job_id = data.get("job_id", "")
    routing_group = data.get("routing_group") or data.get("service_name") or ""
    stream_has_entry = True
    stream_has_pel = True

    if routing_group and job_id:
        try:
            queue = globals().get("queue_engine")
            if queue is not None and getattr(queue, "priority_lanes_enabled", False):
                stream_specs = queue._stream_specs(
                    routing_group, routing_group=routing_group
                )
            else:
                stream_specs = [(f"queue:{routing_group}", None)]
            found_entry = False
            found_pel = False
            for stream, _lane in stream_specs:
                entries = redis_client.xrange(stream, min="-", max="+", count=1000)
                matching_ids = {
                    str(entry_id)
                    for entry_id, fields in entries
                    if str((fields or {}).get("job_id", "")) == str(job_id)
                }
                if matching_ids:
                    found_entry = True
                    pending = redis_client.xpending_range(
                        stream, RedisQueue.GROUP, min="-", max="+", count=1000
                    )
                    if any(
                        str((item or {}).get("message_id", "")) in matching_ids
                        for item in (pending or [])
                    ):
                        found_pel = True
            stream_has_entry = found_entry
            stream_has_pel = found_pel
        except Exception:
            logger.exception(
                "[stale-reaper] continuation inspection failed for job=%s routing_group=%s",
                job_id, routing_group,
            )
            stream_has_entry = True
            stream_has_pel = True

    service_running = True
    service_name = data.get("service_name", "")
    try:
        svc = (_load_services_config().get("services", {}) or {}).get(service_name, {})
        unit = svc.get("systemd_unit", "")
        if unit:
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL,
            )
            stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=5)
            service_running = stdout.decode(errors="replace").strip() == "active"
    except Exception:
        logger.exception(
            "[stale-reaper] backend-state inspection failed for job=%s service=%s",
            job_id, service_name,
        )
        service_running = True

    return stream_has_pel, stream_has_entry, service_running


async def _stale_job_reaper_loop() -> None:
    """Force-fail orphaned in_flight jobs whose worker died mid-poll.

    Scans Redis `job:*` hashes every 60s. For each entry where:
      - status == "in_flight"
      - started_at is older than (now - deadline)

    mark it failed with an audit message. The TTL in queue_engine.py would
    eventually auto-expire these, but the watchdog lets us react faster and
    keeps scheduler state in sync with Redis.
    """
    from datetime import datetime, timezone
    logger.info("[stale-reaper] Starting stale-job reaper (interval=%ds)",
                _STALE_JOB_REAPER_INTERVAL_S)
    while True:
        try:
            await asyncio.sleep(_STALE_JOB_REAPER_INTERVAL_S)
            now = time.time()
            # Allow override via env var for tighter testing
            deadline_s = int(os.environ.get(
                "GPU_MANAGER_STALE_JOB_DEADLINE_S",
                _STALE_JOB_DEFAULT_DEADLINE_S))
            # Best-effort: get redis handle. Prefer _queue_redis module global
            # set by create_app; fall back to constructing a fresh client.
            redis_client = globals().get("_queue_redis")
            if redis_client is None:
                try:
                    redis_client = _redis_mod.Redis(**_redis_connection_kwargs())
                except Exception as e:
                    logger.debug("[stale-reaper] cannot create redis client: %s", e)
                    continue
            reaped = 0
            for key in redis_client.scan_iter(match="job:*", count=100):
                try:
                    data = redis_client.hgetall(key)
                    if not data:
                        continue
                    if data.get("status") != "in_flight":
                        continue
                    started_at = data.get("started_at")
                    if not started_at:
                        continue
                    # started_at is ISO-8601. Parse to epoch.
                    try:
                        started_ts = datetime.fromisoformat(
                            started_at.replace("Z", "+00:00")
                        ).timestamp()
                    except (ValueError, AttributeError):
                        continue
                    age_s = now - started_ts
                    if age_s < deadline_s:
                        continue
                    # Orphan candidate. Terminalize only when the stream PEL,
                    # stream body, and backend state all prove continuation is
                    # impossible. Any positive/unknown signal preserves it.
                    job_id = data.get("job_id") or key.split(":", 1)[-1]
                    stream_has_pel, stream_has_entry, service_running = (
                        await _stale_job_continuation_signals(redis_client, data)
                    )
                    tracker = JobTracker(r=redis_client)
                    decision = terminalize_job_if_impossible(
                        tracker,
                        job_id,
                        stream_has_pel=stream_has_pel,
                        stream_has_entry=stream_has_entry,
                        service_running=service_running,
                        force=True,
                    )
                    if decision.get("action") == "terminalized":
                        logger.warning(
                            "[stale-reaper] terminalized job=%s age=%.0fs deadline=%ds",
                            job_id, age_s, deadline_s,
                        )
                        reaped += 1
                    else:
                        logger.info(
                            "[stale-reaper] preserved job=%s age=%.0fs reason=%s",
                            job_id, age_s, decision.get("reason", "unknown"),
                        )
                except Exception:
                    # Per-pattern from OOM watchdog: never let inner loop die.
                    logger.exception("[stale-reaper] error processing key %s", key)
            if reaped:
                logger.info("[stale-reaper] reaped %d orphaned in_flight job(s)",
                            reaped)
        except Exception:
            # Per-pattern from OOM watchdog: never let loop die.
            logger.exception("[stale-reaper] outer loop error, continuing")


async def _scheduler_health_check_loop():
    """Periodically check if the scheduler is running. Restart if dead.

    Per adversarial C.6: if scheduler_running=false for >30s, restart.

    The scheduler is started once in background_loop. If its loop task dies
    (uncaught exception, GC pressure, etc.), the whole queue system freezes
    silently — services stay running but no new jobs are dispatched. This
    loop catches that and either:
      - logs a clear warning so operators can intervene, or
      - if `scheduler.run()` exists and is safe to call, restarts it.

    We do NOT auto-restart by default (the scheduler class has internal
    state we don't want to clobber). We log + emit an event so the failure
    is visible.
    """
    last_false_ts: float | None = None
    last_durable_false_ts: float | None = None
    check_interval = 15  # s
    fail_threshold = 30  # s — how long it can be down before we shout
    while True:
        try:
            await asyncio.sleep(check_interval)
            owner_mode = _queue_owner_mode()
            scheduler_obj = globals().get("scheduler")
            if owner_mode == 'durable':
                # The compatibility scheduler is intentionally not started in
                # this mode.  Observe only the durable owner; never restart or
                # construct the legacy dispatcher from this watchdog.
                durable = globals().get("worker_supervisor")
                if durable is not None:
                    durable_running = bool(
                        getattr(durable, "_running", False)
                        or getattr(durable, "running", False)
                    )
                    now = time.time()
                    if not durable_running:
                        if last_durable_false_ts is None:
                            last_durable_false_ts = now
                        elif now - last_durable_false_ts > fail_threshold:
                            logger.warning(
                                "[scheduler-health] durable worker supervisor "
                                "running=false for >%ss — Redis generation dispatch may be stalled",
                                fail_threshold,
                            )
                            last_durable_false_ts = now
                    else:
                        last_durable_false_ts = None
                continue
            if scheduler_obj is None:
                continue
            running = bool(
                getattr(scheduler_obj, "_running", False)
                or getattr(scheduler_obj, "running", False)
            )
            now = time.time()
            if not running:
                if last_false_ts is None:
                    last_false_ts = now
                elif now - last_false_ts > fail_threshold:
                    logger.warning(
                        f"[scheduler-health] scheduler_running=false for "
                        f">{fail_threshold}s — queue dispatch may be stalled"
                    )
                    # Phase 5: prefer first-class scheduler.restart(); fall back
                    # to getattr(run_async/run) for backward compatibility.
                    restart_method = getattr(scheduler_obj, "restart", None)
                    if callable(restart_method):
                        try:
                            # restart is async in our impl
                            coro = restart_method()
                            if asyncio.iscoroutine(coro):
                                asyncio.create_task(coro)
                            else:
                                # Sync restart fallback
                                restart_method()
                            logger.info(
                                "[scheduler-health] Scheduler restart triggered via scheduler.restart()"
                            )
                            last_false_ts = None
                        except Exception as e:
                            logger.error(
                                f"[scheduler-health] scheduler.restart() failed: {e}"
                            )
                    else:
                        # Attempt restart: prefer run_async if available, else run.
                        # If neither is callable, we just keep logging.
                        run_method = (
                            getattr(scheduler_obj, "run_async", None)
                            or getattr(scheduler_obj, "run", None)
                        )
                        if callable(run_method):
                            try:
                                # run_method is a coroutine function (e.g.
                                # scheduler.run_async); Pyright can't infer this
                                # through getattr.
                                coro = run_method()  # type: ignore[func-returns-value]
                                asyncio.create_task(coro)  # type: ignore[arg-type]
                                logger.info(
                                    "[scheduler-health] Scheduler restart triggered (fallback run_method)"
                                )
                                last_false_ts = None
                            except Exception as e:
                                logger.error(
                                    f"[scheduler-health] Restart failed: {e}"
                                )
                    # Reset last_false_ts so we don't spam every iteration;
                    # next false-streak will re-arm.
                    last_false_ts = now
            else:
                last_false_ts = None

            # The Redis worker owner is a separate dispatch authority.  Do
            # not call its supervisor loop from this watchdog (that could
            # create duplicate pools); retain a bounded warning/health signal
            # until the ownership consolidation slice gives it a dedicated
            # restart contract.
            durable = globals().get("worker_supervisor")
            if durable is not None and owner_mode != 'legacy':
                durable_running = bool(
                    getattr(durable, "_running", False)
                    or getattr(durable, "running", False)
                )
                if not durable_running:
                    if last_durable_false_ts is None:
                        last_durable_false_ts = now
                    elif now - last_durable_false_ts > fail_threshold:
                        logger.warning(
                            "[scheduler-health] durable worker supervisor "
                            "running=false for >%ss — Redis generation dispatch may be stalled",
                            fail_threshold,
                        )
                        # Re-arm after the warning; lifecycle/restart ownership
                        # remains with WorkerSupervisor until the two-owner
                        # migration is complete.
                        last_durable_false_ts = now
                else:
                    last_durable_false_ts = None
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.debug(f"[scheduler-health] health check error: {e}")


def _kill_stale_mcp_siblings():
    """Kill any other gpu-manager.py --mcp processes besides this one.

    Per Phase 1 known issue: stale --mcp processes from earlier sessions
    don't reload the new code and report stale state. We walk /proc for
    processes whose cmdline contains 'gpu-manager.py --mcp', skip ourselves,
    and send SIGTERM to each. We deliberately do NOT send SIGKILL — if the
    sibling is mid-write to a state file, SIGTERM gives it a chance to
    clean up. systemd will restart it if appropriate.

    Phase 6 — companion cron on zeroclaw-pi:
        This function is the in-process cleanup, but it only runs at
        process start. If an --mcp child process becomes orphaned (parent
        gone, but the child lingers because of broken stdio), nothing here
        can detect it. The cron spec is documented in
        scripts/PHASE6_OUTCOME.md § "Orphan --mcp cleanup cron". Per the
        user's standing rule (2026-06-14), that cron lives INSIDE
        zeroclaw, not as a systemd timer.
    """
    my_pid = os.getpid()
    try:
        with open(f"/proc/{my_pid}/cmdline", "rb") as f:
            my_cmdline = f.read().decode("utf-8", errors="replace")
        if "--mcp" not in my_cmdline:
            # Only kill siblings if WE are an --mcp process — otherwise we
            # shouldn't be in the MCP-killer business at all.
            return
    except Exception:
        return

    for entry in os.listdir("/proc"):
        if not entry.isdigit():
            continue
        pid = int(entry)
        if pid == my_pid:
            continue
        try:
            with open(f"/proc/{pid}/cmdline", "rb") as f:
                cmdline = f.read().decode("utf-8", errors="replace")
        except (FileNotFoundError, ProcessLookupError, PermissionError):
            continue
        if "gpu-manager.py" not in cmdline or "--mcp" not in cmdline:
            continue
        try:
            os.kill(pid, signal.SIGTERM)
            logger.info(
                f"[mcp-cleanup] Sent SIGTERM to stale --mcp process {pid}"
            )
        except ProcessLookupError:
            pass
        except Exception as e:
            logger.debug(f"[mcp-cleanup] Could not kill PID {pid}: {e}")



async def _expire_reservations_loop():
    while True:
        try:
            expired = expire_reservations()
            if expired:
                logger.info(f"Released expired GPU reservations for: {expired}")
        except Exception as e:
            logger.error(f"Error in expire reservations tick: {e}")
        await asyncio.sleep(5)

async def handle_debug_reserve_gpus(request: web.Request):
    """POST /v1/debug/reserve-gpus — Stage 3 debug hook.

    Body: {"gpus": ["gpu_primary","gpu_secondary"], "hold_s": <1..30>, "reason": "..."}
    Returns 200 {token, expires_at} on success; 409 {"error":"Conflict", ...}
    on overlap; 400/422 on bad input. Always clamps hold_s into [1, 30].
    Only registered when gpu-manager is launched with --debug-reservations.
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    gpus = body.get("gpus", [])
    hold_s = body.get("hold_s", 10)
    if not isinstance(gpus, list) or len(gpus) == 0:
        return web.json_response({"error": "gpus must be a non-empty list"}, status=422)
    configured_gpu_ids = set(
        ((_load_services_config().get("gpu_devices", {}) or {}).keys())
    )
    if (
        not all(isinstance(g, str) for g in gpus)
        or not set(gpus).issubset(configured_gpu_ids)
    ):
        return web.json_response(
            {"error": "gpus must be registered device identifiers"}, status=422
        )
    try:
        hold_s = float(hold_s)
    except Exception:
        return web.json_response({"error": "hold_s must be a number"}, status=400)

    # Hard cap: no caller-supplied value may exceed the 30s ceiling.
    hold_s = max(1.0, min(30.0, hold_s))

    token_hex = uuid.uuid4().hex
    ok, data = reserve_gpus(group="debug", gpu_ids=gpus, hold_s=int(hold_s), token=token_hex)
    if not ok:
        # Surface "Conflict" explicitly so test harness can match on it.
        conflict_body = {"error": "Conflict"}
        if isinstance(data, dict):
            conflict_body.update(data)
        return web.json_response(conflict_body, status=409)
    return web.json_response(data)

async def handle_debug_release_gpus(request: web.Request):
    """POST /v1/debug/release-gpus — Stage 3 debug hook.

    Body: {"token": "<uuid4 hex>"}
    Returns 200 {released: [...]} on success; 404 if token unknown/expired.
    Only registered when gpu-manager is launched with --debug-reservations.
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    token = body.get("token")
    if not token:
        return web.json_response({"error": "token required"}, status=400)
    ok, data = release_gpus(group="debug", token=token, reason="debug_release")
    if not ok:
        return web.json_response({"error": "Not found or expired"}, status=404)
    return web.json_response(data)

async def handle_debug_list_reservations(request: web.Request):
    return web.json_response({"gpu_reservations": _gpu_reservations})


async def _delayed_stale_mcp_cleanup():
    """Wait for this process to fully initialize, then kill stale MCP siblings.

    30s delay: gives our own MCP server (if we're an --mcp instance) time to
    bind its stdio / register tools before we start killing siblings. If we
    ARE the stale one (e.g. a fresh restart replacing an old instance), the
    30s gives the old instance a chance to notice systemd's stop signal and
    shut down cleanly.
    """
    await asyncio.sleep(30)
    _kill_stale_mcp_siblings()



async def handle_debug_simulate_oom(request: web.Request):
    """POST /v1/debug/simulate-oom — Stage 4 safe OOM simulation hook."""
    import uuid
    try:
        body = await request.json()
    except Exception:
        body = {}

    gpu_id = body.get("gpu_id")
    configured_gpu_ids = set(
        ((_load_services_config().get("gpu_devices", {}) or {}).keys())
    ) | set(_gpu_states)
    if not isinstance(gpu_id, str) or gpu_id not in configured_gpu_ids:
        return web.json_response(
            {"error": "gpu_id required and must identify a registered device"},
            status=422,
        )

    service_name = body.get("service_name", "debug-oom-sim")
    job_id = body.get("job_id", f"debug-oom-{uuid.uuid4().hex[:8]}")
    reason = body.get("reason", "synthetic OOM simulation")
    details = body.get("details", "debug endpoint, no real VRAM exhaustion")

    try:
        result = _handle_oom_event(
            gpu_id=gpu_id,
            service_name=service_name,
            job_id=job_id,
            detection_source="debug-simulate-oom",
            reason=reason,
            details=details
        )
        gpu_state = _gpu_states.get(gpu_id)
        recorded = bool(result.get("recorded")) if isinstance(result, dict) else False
        status = 200 if recorded else 422
        return web.json_response({
            "ok": recorded,
            "event": result,
            "gpu_oom_state": gpu_state.oom_state if gpu_state else "unknown",
            "gpu_id": gpu_id,
            "job_id": job_id
        }, status=status)
    except Exception as e:
        logger.error(f"Error in simulate OOM hook: {e}")
        return web.json_response({"error": str(e)}, status=500)

async def handle_debug_oom_state(request: web.Request):
    """GET /v1/debug/oom-state/{gpu_id}"""
    gpu_id = request.match_info.get("gpu_id")
    if gpu_id not in _gpu_states:
        return web.json_response({"error": "Unknown GPU"}, status=404)

    state = _gpu_states[gpu_id]
    return web.json_response({
        "oom_state": state.oom_state,
        "oom_event_count": state.oom_event_count,
        "oom_last_reason": state.oom_last_reason,
        "oom_recovery_count": state.oom_recovery_count
    }, status=200)

def _coordinator_job_dict(job):
    if job is None:
        return None
    if isinstance(job, dict):
        return dict(job)
    if hasattr(job, "to_dict"):
        return job.to_dict()
    return dict(vars(job))


async def _admit_internal_generation_leaf(service_id, resource_id, job_id, trusted_config):
    """Admit one deterministic coordinator child through the durable queue."""
    if queue_engine is None or job_tracker is None:
        raise RuntimeError("generation queue unavailable")
    identity_sha = hashlib.sha256(json.dumps(
        {"service_id": service_id, "resource_id": resource_id, "config": trusted_config},
        sort_keys=True, separators=(",", ":"),
    ).encode()).hexdigest()
    existing = _coordinator_job_dict(job_tracker.get_job(job_id))
    if existing is not None:
        if str(existing.get("parent_job_id") or "") != str(trusted_config.get("parent_job_id") or ""):
            raise RuntimeError("deterministic child identity conflict")
        if existing.get("request_sha256") and existing["request_sha256"] != identity_sha:
            raise RuntimeError("deterministic child request conflict")
        if not existing.get("entry_id"):
            raise RuntimeError("child outcome unknown: missing queue admission receipt")
        return {"job_id": job_id, "service_id": service_id, "resource_id": resource_id}

    resolved = dict(trusted_config.get("resolved_inputs") or {})
    native = dict(resolved.get("native_brief") or {})
    duration = max(10, min(60, int(resolved.get("duration_seconds") or 60)))
    request_params = {
        "model": "minimax-music3-audiocpp-q8-bf16",
        "request": {
            "text": str(native.get("caption") or native.get("prompt") or ""),
            "lyrics": str(native.get("lyrics") or "[Instrumental]"),
            "options": {
                "duration_sec": float(duration),
                "num_inference_steps": 30,
                "guidance_scale": 1.7,
                "ar_guidance_scale": 1.5,
                "top_k": 50,
                "seed": int(hashlib.sha256(job_id.encode()).hexdigest()[:8], 16),
                "flow_uncond_interval": 1,
                "flow_uncond_warmup": 2,
                "flow_chunk_hop_frames": 0,
                "ensemble_takes": 1,
                "ensemble_prefix_frames": 0,
            },
        },
    }
    parent_job_id = str(trusted_config.get("parent_job_id") or "")
    parent = _coordinator_job_dict(job_tracker.get_job(parent_job_id)) or {}
    priority = int(parent.get("priority", 50))
    priority_class = parent.get("priority_class") or None
    metadata = {
        "parent_job_id": parent_job_id,
        "parent_run_id": trusted_config.get("parent_run_id"),
        "stage_id": trusted_config.get("id"),
        "idempotency_key": trusted_config.get("idempotency_key"),
        "candidate": "audio-cpp-q8-20260908",
        "workflow_timeout_s": 7200,
    }
    source_artifact = None
    if native:
        entry, error = await _build_generation_entry(
            gen_type="minimax-music3-audiocpp-bf16-dit-qualification",
            params=request_params, priority=priority, priority_class=priority_class,
            parent_priority=priority, parent_priority_class=priority_class,
            callback_url=None, metadata=metadata,
        )
    else:
        # Existing protocols are selected by reviewed provider + template,
        # not by a growing controller list of individual service names.
        config = _load_services_config()
        provider = (config.get("pipeline_providers") or {}).get(service_id) or {}
        template = copy.deepcopy((config.get("generation_templates") or {}).get(resource_id) or {})
        backend = template.get("backend")
        service = (config.get("services") or {}).get(backend) or {}
        if (provider.get("adapter") != "gpu_manager_generation"
                or provider.get("endpoint_ref") != backend
                or not _service_is_publicly_qualified(template)
                or not _service_is_publicly_qualified(service)):
            raise RuntimeError("reviewed leaf provider/template binding unavailable")
        error = (_validate_template_qualification(resource_id, template)
                 or _validate_q5_template_identity(resource_id, template))
        if error:
            raise RuntimeError(str(error.get("error")))
        context = trusted_config.get("context") or {}
        request_params = dict(context.get("request_params") or {})
        request_params["prompt"] = str(context.get("effective_prompt") or request_params.get("prompt") or "")
        request_params.setdefault("seed", int(hashlib.sha256(job_id.encode()).hexdigest()[:8], 16))
        stage_params = trusted_config.get("params") or {}
        for key in {item[0] for item in _resolve_inject_keys(template)}:
            if key in stage_params:
                request_params[key] = stage_params[key]
        metadata.pop("candidate", None)
        if template.get("workflow_backend") == "comfyui" or backend == "comfyui":
            # Parent coordinator owns preparation/QC. Do not recursively run
            # inline enhancement or correction inside its generation child.
            template.pop("prompt_enhance", None)
            template.pop("post_generate", None)
            template.pop("service_pipeline_id", None)
            image_targets = [item for item in _resolve_inject_keys(template) if item[0] == "source_image"]
            if image_targets:
                source_artifact = context.get("artifact")
                if not isinstance(source_artifact, Mapping) or not source_artifact.get("sha256"):
                    raise RuntimeError("image correction requires a persisted source artifact")
                request_params["source_image"] = f"{job_id}-source.png"
                metadata["source_image_target"] = list(image_targets[0][1:])
                if context.get("qc_verdict"):
                    request_params["prompt"] += "\nCorrect these observed issues while preserving the requested image: " + json.dumps(context["qc_verdict"].get("report") or {}, sort_keys=True)
            allowed = set(template.get("allowed_params") or [])
            if allowed:
                request_params = {k: v for k, v in request_params.items() if k in allowed}
            entry, error = await _build_comfyui_workflow_entry(
                service_name=backend, tmpl=template, params=request_params,
                job_id=job_id, priority=priority, priority_class=priority_class,
                callback_url=None, metadata=metadata,
            )
        else:
            entry, error = await _build_generation_entry(
                gen_type=resource_id, params=request_params, priority=priority,
                priority_class=priority_class, parent_priority=priority,
                parent_priority_class=priority_class, callback_url=None, metadata=metadata,
            )
    if error or entry is None:
        _reason = str((error or {}).get("reason") or "")
        if _reason in {"workflow_asset_missing", "workflow_asset_invalid"}:
            from pipeline_coordinator import TerminalLeafError
            raise TerminalLeafError(_reason, str((error or {}).get("error") or ""))
        raise RuntimeError((error or {}).get("error", "generation entry build failed"))
    entry["job_id"] = job_id
    if source_artifact is not None:
        entry["coordinator_source_artifact"] = dict(source_artifact)
    tracked_job = {
        "job_id": job_id, "service_name": entry.get("service_name") or "",
        "source": "pipeline_coordinator_child", "status": "queued",
        "submitted_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "routing_group": entry.get("routing_group") or "",
        "priority": priority, "priority_class": priority_class,
        "parent_job_id": parent_job_id, "request_sha256": identity_sha,
        "stage_id": trusted_config.get("id") or "",
        "idempotency_key_sha256": hashlib.sha256(str(trusted_config.get("idempotency_key") or "").encode()).hexdigest(),
    }
    try:
        entry_id = await asyncio.get_running_loop().run_in_executor(
            None, lambda: queue_engine.enqueue(
                entry.get("service_name") or entry.get("routing_group"), entry,
                entry.get("routing_group"), tracked_job=tracked_job,
            ),
        )
    except Exception:
        # Redis may have committed before the connection failed. Do not
        # overwrite an accepted child's lifecycle with a guessed failure.
        raise
    if not entry_id:
        raise RuntimeError("child admission outcome unknown; reconcile deterministic identity")
    return {"job_id": job_id, "service_id": service_id, "resource_id": resource_id}


def _poll_internal_generation_leaf(job_id):
    job = _coordinator_job_dict(job_tracker.get_job(job_id) if job_tracker else None)
    if not job:
        return {"status": "unknown", "error": "child job not found"}
    result = job.get("result")
    if isinstance(result, str):
        try:
            result = json.loads(result)
        except (TypeError, json.JSONDecodeError):
            result = {}
    result = result if isinstance(result, dict) else {}
    raw_artifact = result.get("artifact")
    if not isinstance(raw_artifact, Mapping):
        files = result.get("files") or result.get("images") or []
        raw_artifact = files[0] if files and isinstance(files[0], Mapping) else None
    artifact = None
    if isinstance(raw_artifact, Mapping):
        path = raw_artifact.get("path_or_url") or raw_artifact.get("path") or raw_artifact.get("url")
        if path:
            artifact = {
                "path_or_url": str(path), "sha256": str(raw_artifact.get("sha256") or ""),
                "producer_stage_id": job.get("stage_id") or "generate-audiocpp", "produced_at": str(raw_artifact.get("produced_at") or ""),
            }
    output = {}
    if artifact:
        output = ({"artifact": artifact, "images": [artifact]}
                  if result.get("images") else
                  {"original_audio": artifact,
                   "generation_receipt": result.get("generation_receipt") or {}})
    return {"status": str(job.get("status") or "unknown"), "artifact": artifact, "output": output, "error": job.get("error") or None}


def _cancel_internal_generation_leaf(job_id):
    job = _coordinator_job_dict(job_tracker.get_job(job_id) if job_tracker else None)
    if not job or job.get("status") in {"completed", "failed", "cancelled"}:
        return False
    if job.get("status") == "in_flight":
        result = job_tracker.mark_cancellation_intent_if_in_flight(job_id)
        return bool(result.get("updated"))
    if job.get("status") == "queued" and job.get("entry_id"):
        result = queue_engine.cancel_queued_atomically(
            service_name=job.get("service_name") or "",
            routing_group=job.get("routing_group") or None,
            entry_id=job["entry_id"], consumer="pipeline-coordinator",
            job_id=job_id, error="parent_cancelled", audit_source="pipeline-coordinator",
            cancelled_by="pipeline-coordinator",
        )
        return bool(result is True or (isinstance(result, dict) and result.get("removed_and_terminalized")))
    return False


def _build_production_coordinator_runtime(config):
    if _queue_redis is None:
        return None
    try:
        from pipeline_coordinator import RedisCoordinatorStore
        from gpu_manager_pipeline_runtime import GPUManagerLeafGenerationClient
        from workflow_coordinator_runtime import build_controller_runtime_from_config
        from minimax_recovered_callbacks import build_recovered_minimax_callbacks

        loop = asyncio.get_running_loop()
        def submit_leaf(service_id, resource_id, job_id, params):
            future = asyncio.run_coroutine_threadsafe(
                _admit_internal_generation_leaf(service_id, resource_id, job_id, params), loop
            )
            return future.result(timeout=420)
        leaf = GPUManagerLeafGenerationClient(
            submit_leaf=submit_leaf,
            poll_leaf=_poll_internal_generation_leaf,
            cancel_leaf=_cancel_internal_generation_leaf,
        )
        runtime, callbacks = build_controller_runtime_from_config(
            config, store=RedisCoordinatorStore(_queue_redis), leaf_client=leaf,
            generic_transport_factory=lambda _provider_id, _provider_cfg: _AiohttpTransport(session, owner_loop=loop),
            custom_callback_factory=build_recovered_minimax_callbacks,
            operation_catalogs=config.get("operation_catalogs") or {},
            leaf_adapters={"audio.cpp", "gpu_manager_generation"},
            external_adapters={"llm", "minimax.preparation", "research.http", "research.validator", "audio.analysis", "local-audio-qc", "artifact-store", "http_json", "http_openai_compatible", "http_flow", "local_pipeline"},
            consumer_name=f"controller-{os.getpid()}",
        )
        logger.info("Production workflow coordinator constructed with %d reviewed adapters", len(callbacks.registry._bindings))
        return runtime
    except Exception:
        logger.exception("Production workflow coordinator initialization failed")
        return None


def create_app(debug_reservations=False, debug_oom_sim=False) -> web.Application:
    global scheduler, vram, _services_config
    app = web.Application(middlewares=[_api_auth_middleware], client_max_size=32 * 1024 * 1024)
    # External broker authentication is a separate release boundary. Scope
    # this credential only to the controller's embedded logical Gemma route.
    app[_KDA_GEMMA_SCOPED_GATE_APP_KEY] = _combined_gemma_broker_embedded
    app[_KDA_GEMMA_MEMBER_PINS_APP_KEY] = _scoped_token_backends
    app[_KDA_GEMMA_DEFAULT_PIN_APP_KEY] = lambda: _SCOPED_DEFAULT_PIN
    app["debug_reservations"] = debug_reservations
    app["debug_oom_sim"] = debug_oom_sim


    # Create with None session — will be set in background_loop
    scheduler = GPUScheduler(None, logger)
    vram = VRAMLifecycleManager(None, logger)

    # Load services config
    _services_config = _load_services_config()

    # Observe-only GPU attribution; keep the registration local to app startup.
    from gpu_manager.gpu_guard import register_gpu_guard
    _guard_services = _services_config.get("services", {})
    _guard_managed_units = sorted({
        str(item.get("systemd_unit")) for item in _guard_services.values()
        if isinstance(item, Mapping) and item.get("systemd_unit")
    }) if isinstance(_guard_services, Mapping) else []
    _guard_config = _services_config.get("gpu_guard", {"enabled": False})
    register_gpu_guard(app, config=_guard_config, managed_units=_guard_managed_units,
                       desktop_allowlist=_guard_config.get("desktop_allowlist", ()))

    # Load providers config
    global _providers_config, _peer_monitor
    _providers_config = _load_providers_config()
    logger.info(f"Loaded providers.json: {len(_providers_config.get('providers',{}))} providers")
    # A pipeline may reference a provider identity supplied only by the
    # companion providers registry. Rebuild once after that registry is loaded
    # so startup order cannot leave a valid graph disabled.
    _load_service_pipelines_from_config(_services_config)

    # Initialize peer monitor for mesh health
    _peer_monitor = PeerMonitor(_providers_config, _services_config)
    logger.info(f"Peer monitor: tracking {len(_peer_monitor.instances)} instances + cloud providers")

    # Initialize model validator
    global _model_validator
    _model_validator = ModelValidator(_providers_config)
    logger.info(f"Model validator initialized: {len(_model_validator.rules)} routing rules")

    # ── Redis Queue Engine ──
    # NOTE: `queue_metrics` MUST be in this `global` declaration. Without it,
    # the `queue_metrics = QueueMetrics(_queue_redis)` assignment below binds
    # a LOCAL name, leaving the module-level `queue_metrics` at None and
    # causing /v1/metrics to return 503 forever. See scripts/test_queue_metrics_initialization.py.
    global queue_engine, job_tracker, slot_manager, routing_engine, capacity_reporter, capacity_tracker, fleet_gossiper, queue_metrics, _queue_redis
    global _async_redis, async_queue, async_slot_manager, async_capacity, async_gossiper, bundle_lifecycle_controller
    try:
        _queue_redis = _redis_mod.Redis(**_redis_connection_kwargs())
        _queue_redis.ping()  # verify Redis is up
        assert _queue_redis.connection_pool.connection_kwargs.get("decode_responses") is True, (
            "queue engine Redis must use decode_responses=True"
        )
        _priority_queue_config = _phase3_scheduling_config()
        queue_engine = RedisQueue(
            _queue_redis,
            externally_owned_routing_groups=_broker_owned_queue_routing_groups(),
            priority_lanes_enabled=_priority_queue_config.get(
                'priority_lanes_enabled', False
            ),
            priority_aging_interval_s=_priority_queue_config.get(
                'priority_aging_interval_s', 60
            ),
            priority_aging_cap=_priority_queue_config.get(
                'queue_priority_aging_cap', 3
            ),
        )
        job_tracker = JobTracker(_queue_redis)
        logger.info("Preserved %s legacy unfinished job receipts without replay",
                    job_tracker.preserve_unfinished_receipts())
        # Build slot config from services.json
        # Admit
        # generation_backend services (e.g. sd-server, comfyui, acestep) in
        # addition to llm_backend. _REDIS_QUEUE_ADMIT_TYPES is defined at
        # module scope.
        _slot_config = {}
        for _sn, _sc in _services_config.get("services", {}).items():
            if _is_queue_consumer_service(_sc):
                _slot_config[_sn] = int(_sc.get("parallel", 1))
        slot_manager = SlotManager(_queue_redis, service_slots=_slot_config)
        # Build routing config from services.json
        # Build routing config and enforce a cross-type guard to admit
        # generation_backend services AND enforce a cross-type guard so
        # that a misconfigured services.json cannot route LLM traffic to a
        # generation backend (or vice versa). _routing_group_seen_types
        # records the routing_group_type that was first admitted for each
        # routing_group; if a later service in the same group has a
        # different type it is rejected (logged + skipped). The plan calls
        # this the "safety belt for the whole rollout" — treat any
        # "routing_group_type" log line as P0 until cleared.
        _routing_config = {}
        _routing_group_seen_types = {}
        for _sn, _sc in _services_config.get("services", {}).items():
            if not _is_queue_consumer_service(_sc):
                continue
            _rg = _sc.get("routing_group", "")
            _rg_type = _sc.get("routing_group_type", "llm")
            # Cross-type guard (CRITICAL — safety belt for the rollout).
            if _rg and _rg in _routing_group_seen_types \
                    and _routing_group_seen_types[_rg] != _rg_type:
                logger.error(
                    "routing_group '%s' mixes types "
                    "(%s vs %s); skipping service %s",
                    _rg, _routing_group_seen_types[_rg], _rg_type, _sn,
                )
                continue
            if _rg:
                _routing_group_seen_types[_rg] = _rg_type
            _routing_config[_sn] = {
                "type": _sc.get("type"),
                "routing_group": _rg,
                "routing_group_type": _rg_type,
                "parallel": int(_sc.get("parallel", 1)),
                "speed": int(_sc.get("speed", 0)),
                "priority": int(_sc.get("priority", 0)),
                "lane": int(_sc.get("lane", 0) or 0),
            }
        capacity_tracker = CapacityTracker(_queue_redis, health_check_fn=_service_health_check)
        # Seed capacity tracking for every admitted service. The
        # init loop was widened in PR4 for SlotManager (Step 3) and
        # RoutingEngine (Step 4) but THIS loop (which seeds _active/_pending
        # dicts for every admitted service) was missed.  Use the same
        # _REDIS_QUEUE_ADMIT_TYPES so generation_backend services (sd-server,
        # comfyui, acestep) get capacity tracked too.  Without this, the
        # capacity_tracker would report 0 capacity for every gen backend and
        # PR5's /v1/submit/generation endpoint would never admit work.
        for svc_name, svc_cfg in _services_config.get("services", {}).items():
            if _is_queue_consumer_service(svc_cfg):
                if svc_name not in capacity_tracker._active:
                    capacity_tracker._active[svc_name] = 0
                if svc_name not in capacity_tracker._pending:
                    capacity_tracker._pending[svc_name] = 0
        routing_engine = RoutingEngine(
            _queue_redis,
            _routing_config,
            slot_manager,
            capacity_tracker,
            priority_lanes_enabled=_priority_queue_config.get(
                'priority_lanes_enabled', False
            ),
        )
        capacity_reporter = CapacityReporter(
            _queue_redis, slot_manager, queue_engine, _routing_config,
        )
        # ── Fleet Gossip ──
        # Fleet peers are private deployment topology, not controller source.
        # A missing block safely disables cross-host gossip while retaining the
        # local durable queue.
        _raw_fleet_peers = _providers_config.get("fleet_peers", {})
        _fleet_peers = {
            str(name): str(host)
            for name, host in _raw_fleet_peers.items()
            if isinstance(name, str)
            and name
            and isinstance(host, str)
            and host
        } if isinstance(_raw_fleet_peers, Mapping) else {}
        fleet_gossiper = FleetGossiper(
            local_redis=_queue_redis,
            machine_id=socket.gethostname(),
            peers=_fleet_peers,
            password=_redis_password(),
            local_capacity_fn=lambda: capacity_reporter.get_local_capacity(),
        )
        # ── Queue Metrics ──
        queue_metrics = QueueMetrics(_queue_redis)
        logger.info(f"Queue engine initialized: {len(_slot_config)} services, {len(_routing_config)} routes, fleet gossip with {len(_fleet_peers)} peers")
        # ── Async Queue Engine (Phase 3) ──
        try:
            import redis.asyncio as _aioredis_mod
            _async_pool = _aioredis_mod.ConnectionPool(
                **_redis_connection_kwargs(), max_connections=30,
            )
            _async_redis = _aioredis_mod.Redis(connection_pool=_async_pool)
            # All bundle-aware backends share one durable lifecycle controller;
            # service-specific brokers may still publish readiness observations,
            # but they do not own transitions or restart fencing.
            bundle_lifecycle_controller = BundleLifecycleController(
                RedisBundleLifecycleStore(_async_redis),
                owner=f"gpu-manager:{socket.gethostname()}:{os.getpid()}",
            )
            # Use the same shared async connection pool for all async objects.
            # Lane routing remains an explicit scheduling-config gate so a
            # source-only audit cannot change the live stream topology.
            async_queue = AsyncRedisQueue(
                _async_redis,
                priority_lanes_enabled=_priority_queue_config.get(
                    'priority_lanes_enabled', False
                ),
                priority_aging_interval_s=_priority_queue_config.get(
                    'priority_aging_interval_s', 60
                ),
            priority_aging_cap=_priority_queue_config.get(
                'queue_priority_aging_cap', 3
                ),
            )
            async_slot_manager = AsyncSlotManager(_async_redis, service_slots=_slot_config)
            async_capacity = AsyncCapacityReporter(
                _async_redis, async_slot_manager, async_queue, _routing_config,
            )
            async_gossiper = AsyncFleetGossiper(
                local_redis=_async_redis,
                machine_id=socket.gethostname(),
                peers=_fleet_peers,
                password=_redis_password(),
                local_capacity_fn=lambda: async_capacity.get_local_capacity(),
            )
            logger.info("Async queue engine initialized (Phase 3)")
        except Exception as _aqe_exc:
            logger.warning(f"Async queue engine init failed: {_aqe_exc}")
            async_queue = async_slot_manager = async_capacity = async_gossiper = None
            _async_redis = None
            bundle_lifecycle_controller = None
        # ── Post-reboot reconciliation ──
        _flushed = _reconcile_stale_queues()
        _recovered = _crash_recovery()
        if _flushed or _recovered:
            logger.info(f"Reconciliation: flushed {_flushed} stale entries, recovered {_recovered} orphaned jobs")
    except Exception as _qe_exc:
        logger.warning(f"Queue engine init failed (Redis unavailable?): {_qe_exc}")
        queue_engine = job_tracker = slot_manager = routing_engine = capacity_reporter = capacity_tracker = fleet_gossiper = queue_metrics = None
        _queue_redis = None

    # Construct exactly one durable coordinator from the same Valkey owner and
    # attach it before the delayed WorkerSupervisor admission tier starts.
    # Restore persisted pin
    persisted_pin = _services_config.get("scheduling", {}).get("pinned_service")
    if persisted_pin:
        rejection = _pin_service_rejection(_services_config, str(persisted_pin))
        if rejection is not None:
            logger.warning("Discarding unavailable persisted pin: %s", persisted_pin)
            _services_config.setdefault("scheduling", {})["pinned_service"] = None
            try:
                _save_services_config(_services_config)
            except Exception as exc:
                # A stale policy value must not turn a read-only or temporarily
                # unavailable registry into a controller startup failure. The
                # runtime pin remains cleared for this process.
                logger.warning("Could not persist stale pin removal: %s", exc)
        else:
            scheduler._pinned_service = persisted_pin
            scheduler._pinned_service_since = time.time()  # Phase 5.2.53 Fix B
            logger.info(f"Restored persisted pin: {persisted_pin}")

    # Health / status
