async def ensure_services_running():
    """Fire-and-forget: restore compatible startup services.

    In the default split/legacy modes this preserves the historical Idle LLM
    and ComfyUI startup behavior.  Durable queue-owner mode still observes and
    reconciles configured state, but does not issue a direct ComfyUI systemd
    start because generation lifecycle belongs to the durable worker path.

    Uses the CONFIGURED idle_service (from services.json → scheduling.idle_service),
    NOT a hardcoded LLM name. Only starts an LLM if no GPU LLM is already running
    — respects whatever state the system was left in before gpu-manager restarted.

    STATE RESTORE: Reads the persisted state file to understand what was
    happening before the last shutdown. If the LLM was loaded (not evicted),
    ensures it's still running. Detects actual state from systemd rather
    than blindly restoring.

    MAINTENANCE MODE: Skips all auto-starts when active.
    Also checks `systemctl is-enabled` — won't start a service that was
    explicitly disabled by the user.
    """
    # Startup auto-restore can invoke full-GPU telemetry and systemd starts.
    # Keep it behind the same process-wide grace as the VRAM pusher so startup
    # never performs an autonomous first-tick amdgpu_top probe.
    await asyncio.sleep(GPU_PROBE_STARTUP_GRACE_S)
    global _services_config, vram, scheduler
    if _services_config is None:
        _services_config = _load_services_config()

    # ── State Restore ──────────────────────────────────────────────
    # Read persisted state to understand pre-shutdown context
    saved_state = _load_state()
    if saved_state.get("last_updated"):
        logger.info(
            f"State restore: last state was gpu_state={saved_state.get('gpu_state')}, "
            f"llm_evicted={saved_state.get('llm_evicted')}, "
            f"pinned={saved_state.get('pinned_service')}, "
            f"maintenance={saved_state.get('maintenance_mode')}, "
            f"saved at {saved_state.get('last_updated')}"
        )

    llm.restore_counters(saved_state.get("llm_request_metrics"))

    # Restore pinned_service from state (if saved, overrides default)
    if saved_state.get("pinned_service"):
        saved_pin = str(saved_state["pinned_service"])
        pin_rejection = _pin_service_rejection(_services_config, saved_pin)
        if scheduler and not scheduler._pinned_service and pin_rejection is None:
            scheduler._pinned_service = saved_pin
            logger.info(f"State restore: pinned_service = {saved_pin}")
        elif pin_rejection is not None:
            logger.warning("Ignoring unavailable saved-state pin: %s", saved_pin)

    # Restore maintenance_mode from state
    if saved_state.get("maintenance_mode"):
        if _services_config is None:
            _services_config = _load_services_config()
        if not _maintenance_mode_enabled(_services_config.get("scheduling", {})):
            _services_config.setdefault("scheduling", {})["maintenance_mode"] = True
            _save_services_config(_services_config)
            logger.info("State restore: maintenance_mode restored from state file")

    # Maintenance mode: hands off everything
    if _maintenance_mode_enabled(_services_config.get("scheduling", {})):
        logger.info("Maintenance mode active — skipping auto-start of critical services")
        return

    scheduling = _services_config.get("scheduling", {})
    idle_svc_name = scheduling.get("idle_service", "")
    services = _services_config.get("services", {})

    async def _ensure_unit_running(name: str, unit: str) -> bool:
        """Start a systemd unit if enabled and not already running. Returns True if started."""
        try:
            # Check is-enabled FIRST — respect explicit user disables
            enabled_proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-enabled", unit,
                stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL,
            )
            stdout, _ = await asyncio.wait_for(enabled_proc.communicate(), timeout=3)
            if stdout.decode().strip() != "enabled":
                logger.info(f"Auto-start: skipping {name} (is-enabled: {stdout.decode().strip()})")
                return False

            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", "--quiet", unit,
                stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL,
            )
            await asyncio.wait_for(proc.wait(), timeout=3)
            if proc.returncode != 0:
                logger.info(f"Auto-start: {name} not running, starting {unit}")
                start_proc = await asyncio.create_subprocess_exec(
                    "sudo", "systemctl", "start", unit,
                    stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
                )
                stdout, stderr = await asyncio.wait_for(start_proc.communicate(), timeout=30)
                if start_proc.returncode == 0:
                    logger.info(f"Auto-start: {name} started successfully")
                    return True
                else:
                    logger.warning(f"Auto-start: failed to start {name}: {stderr.decode().strip()}")
            else:
                logger.info(f"Auto-start: {name} already running")
            return False
        except asyncio.TimeoutError:
            logger.warning(f"Auto-start: timeout checking {name}")
        except Exception as e:
            logger.warning(f"Auto-start: error checking {name}: {e}")
        return False

    # ── Phase 1: ComfyUI (generation backend — always needed) ──
    # In durable-owner mode WorkerSupervisor plus the bundle lifecycle path own
    # generation-service admission.  Starting ComfyUI here would reintroduce a
    # second lifecycle authority during the very cutover this mode is meant to
    # fence.  Keep the observation/reconcile pass below, but do not issue a
    # systemd start from this compatibility startup helper.
    comfy_svc = services.get("comfyui", {})
    comfy_unit = comfy_svc.get("systemd_unit", "")
    if comfy_unit and _queue_owner_mode(scheduling) != "durable":
        await _ensure_unit_running("comfyui", comfy_unit)
    elif comfy_unit:
        logger.info(
            "Queue owner=durable; skipping direct ComfyUI auto-start from "
            "ensure_services_running"
        )

    # ── Phase 2: Idle LLM(s) — start per-GPU idle services independently ──
    all_idle = _get_all_idle_services()
    if not all_idle:
        # Fallback: try global idle_service for backward compat
        idle_svc_name = scheduling.get("idle_service", "")
        if not idle_svc_name:
            logger.info("Auto-start: no idle service configured — skipping LLM start")
            return
        all_idle = [{"gpu_id": None, "service_name": idle_svc_name,
                      "systemd_unit": services.get(idle_svc_name, {}).get("systemd_unit", ""),
                      "port": services.get(idle_svc_name, {}).get("port", 0)}]

    # BUGFIX (2026-05-20d): Don't auto-start LLM if GPU work is pending or
    # services were evicted. This prevents the auto-start from re-loading a
    # 7 GB model while a generation runtime is trying to load into the same VRAM.
    if vram and vram._llm_evicted:
        logger.info("Auto-start: LLM evicted (GPU work active) — skipping idle service start")
        return
    if vram and (scheduler._comfyui_queue or scheduler._acestep_queue):
        c_pending = len([j for j in scheduler._comfyui_queue if j.status == "queued"])
        a_pending = len([j for j in scheduler._acestep_queue if j.status == "queued"])
        logger.info(f"Auto-start: GPU work pending (comfyui={c_pending}, acestep={a_pending}) — skipping idle service start")
        return

    # Phase 5.2.50: VRAM gate. If gpu_primary already has > 8 GiB used
    # (ComfyUI is loaded with its models, or both Coexisted), skip the
    # idle LLM entry targeting that GPU. LLM-Primary uses ~13 GiB; combined
    # with comfyui that's ~17 GiB on a 16 GiB card → CUDA OOM.
    try:
        vram_data = await _poll_vram()
        gpu_primary_entry = _get_vram_entry_for_gpu(vram_data, "gpu_primary")
        gpu_primary_used = gpu_primary_entry.get("vram_used_mib", 0) if gpu_primary_entry else 0
        if gpu_primary_used > 8000:
            logger.warning(
                f"Auto-start: skipping idle LLM on gpu_primary — current usage "
                f"{gpu_primary_used} MiB; would OOM if LLM-Primary (~13 GiB) also loaded"
            )
            all_idle = [e for e in all_idle if e.get("gpu_id") != "gpu_primary"]
    except Exception as _phase1_vram_err:
        logger.debug(f"Auto-start: Phase 2 VRAM check failed: {_phase1_vram_err}")

    for idle_entry in all_idle:
        gpu_id = idle_entry["gpu_id"]
        idle_svc_name = idle_entry["service_name"]
        idle_unit = idle_entry["systemd_unit"]

        if not idle_svc_name or not idle_unit:
            continue

        tag = f" (gpu={gpu_id})" if gpu_id else ""

        # Check if a GPU LLM is already running on this GPU
        already_running = await _check_llm_running_on_gpu(
            services, gpu_id, exclude_svc=idle_svc_name
        )
        if already_running:
            logger.info(
                f"Auto-start: GPU LLM {already_running} already running on "
                f"gpu={gpu_id} — not starting idle service {idle_svc_name}{tag}"
            )
            continue

        # No LLM running on this GPU — start the idle service
        await _ensure_unit_running(idle_svc_name + tag, idle_unit)

    # Direct systemd starts above happen after the early startup probe. Do a
    # second authoritative pass so physical idle tenants become configured
    # bundle IDs in the scheduler ledger rather than an empty/stale cache.
    await _reconcile_authoritative_bundle_state()


async def _seed_comfyui_idle_timer():
    """Set ComfyUI idle timestamp on startup if it's already running.

    When gpu-manager starts, ComfyUI may already be active (e.g., from
    systemd on boot). Without this, the auto-stop timer would never
    trigger because _comfyui_idle_since remains None.
    """
    await asyncio.sleep(10)  # Wait for ensure_services_running to finish
    global vram
    if not vram:
        return
    if _queue_owner_mode() == "durable":
        # The legacy direct-idle monitor is fenced with the legacy scheduler;
        # durable mode must not seed a timer that can later be interpreted as
        # authority to stop a WorkerSupervisor-owned generation bundle.
        logger.info(
            "Queue owner=durable; skipping legacy ComfyUI idle-timer seed"
        )
        return
    try:
        proc = await asyncio.create_subprocess_exec(
            "systemctl", "is-active", "--quiet", "comfyui.service",
            stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL,
        )
        await asyncio.wait_for(proc.wait(), timeout=3)
        if proc.returncode == 0:
            # ComfyUI is running — start the idle countdown.
            # At startup there are no pending jobs, so safe to seed.
            if vram._comfyui_idle_since is None:
                vram._comfyui_idle_since = time.time()
                logger.info(
                    f"ComfyUI already running at startup — "
                    f"idle timer seeded (cooldown={COMFYUI_IDLE_COOLDOWN}s)"
                )
    except Exception as e:
        logger.debug(f"ComfyUI idle timer seed skipped: {e}")


async def _recover_forwarded_comfyui_job_after_restart(
    job_id: str,
    job: dict,
    prompt_id: str,
) -> None:
    """Finish a ComfyUI job whose /prompt ACK was persisted before restart.

    The worker has already crossed the side-effect boundary, so resubmitting
    the workflow is unsafe. Poll the same prompt handle, fetch the generated
    images through ComfyUI's normal /view endpoint, and commit the same
    durable result shape as the normal worker path.
    """
    if session is None or job_tracker is None:
        return
    # Keep this recovery task self-contained: unlike the normal worker path it
    # is scheduled directly during startup, before the worker's local base64
    # alias is imported.
    import base64 as _b64
    endpoint = str(job.get("comfyui_endpoint") or "").strip()
    if not endpoint:
        endpoint = COMFYUI_URL.rstrip("/") + "/prompt"
    comfyui_base = endpoint.rstrip("/")
    if comfyui_base.endswith("/prompt"):
        comfyui_base = comfyui_base[: -len("/prompt")]
    try:
        metadata = json.loads(job.get("metadata") or "{}")
    except (TypeError, json.JSONDecodeError):
        metadata = {}
    timeout_s = generation_poll_deadline_s(metadata)
    deadline = time.time() + timeout_s
    job_tracker.update_status(
        job_id,
        "in_flight",
        restart_recovery="polling_existing_prompt",
        comfyui_prompt_id=prompt_id,
    )
    try:
        while time.time() < deadline:
            try:
                async with session.get(
                    f"{comfyui_base}/history/{prompt_id}",
                    timeout=ClientTimeout(total=10),
                ) as response:
                    history = await response.json()
            except Exception as exc:
                logger.debug("restart recovery history poll failed for %s: %s", job_id, exc)
                await asyncio.sleep(5)
                continue
            entry = history.get(prompt_id) if isinstance(history, dict) else None
            if not entry:
                await asyncio.sleep(5)
                continue
            status = entry.get("status") or {}
            if status.get("status_str") == "error" or entry.get("node_errors"):
                error = "ComfyUI node errors: " + json.dumps(entry.get("node_errors") or {})[:500]
                job_tracker.update_status(
                    job_id, "failed", error=error,
                    comfyui_prompt_id=prompt_id, restart_recovery="terminal",
                )
                return
            if not status.get("completed"):
                await asyncio.sleep(5)
                continue

            image_data: list[dict] = []
            for output in (entry.get("outputs") or {}).values():
                for image in (output.get("images") or []):
                    view_params = {
                        "filename": image.get("filename", ""),
                        "type": image.get("type", "output"),
                        "subfolder": image.get("subfolder", ""),
                    }
                    try:
                        async with session.get(
                            f"{comfyui_base}/view",
                            params=view_params,
                            timeout=ClientTimeout(total=60),
                        ) as view_response:
                            image_bytes = await view_response.read()
                            content_type = str(view_response.headers.get("Content-Type") or "")
                            if view_response.status != 200 or not content_type.startswith("image/"):
                                raise RuntimeError(
                                    f"ComfyUI view returned {view_response.status} {content_type}"
                                )
                            _verified_image_bytes(image_bytes)
                        image_data.append({
                            **view_params,
                            "data_b64": _b64.b64encode(image_bytes).decode("ascii"),
                        })
                    except Exception as exc:
                        logger.warning("restart recovery could not fetch %s: %s", view_params, exc)
            if not image_data:
                job_tracker.update_status(
                    job_id, "failed",
                    error="ComfyUI completed without retrievable image output",
                    comfyui_prompt_id=prompt_id, restart_recovery="terminal",
                )
                return
            result_payload = {
                "prompt_id": prompt_id, "status": "success", "images": image_data,
            }
            artifacts = await asyncio.to_thread(
                lambda: [_persist_generated_image(job_id, item, index)
                         for index, item in enumerate(image_data)]
            )
            result_payload["artifact"] = artifacts[0]
            result_payload["artifacts"] = artifacts
            job_tracker.update_status(
                job_id, "completed", result=json.dumps(result_payload),
                comfyui_prompt_id=prompt_id, restart_recovery="completed",
            )
            logger.info(
                "Restart recovery completed ComfyUI job %s using existing prompt_id=%s",
                job_id, prompt_id,
            )
            return
        job_tracker.update_status(
            job_id, "failed",
            error=f"ComfyUI job {prompt_id} timed out during restart recovery",
            comfyui_prompt_id=prompt_id, restart_recovery="timeout",
        )
    except Exception as exc:
        logger.error("restart recovery failed for %s: %s", job_id, exc, exc_info=True)
        job_tracker.update_status(
            job_id, "failed", error=f"restart recovery failed: {exc}",
            comfyui_prompt_id=prompt_id, restart_recovery="failed",
        )


async def _peer_health_loop():
    """Check peer health every 15 seconds after process-wide GPU probe grace."""
    logger.info(
        "Peer health startup grace: waiting %.1fs before first local GPU probe",
        GPU_PROBE_STARTUP_GRACE_S,
    )
    await asyncio.sleep(GPU_PROBE_STARTUP_GRACE_S)
    while True:
        try:
            if _peer_monitor:
                await _peer_monitor.check_all()
        except Exception as e:
            logger.error(f"Peer health check failed: {e}")
        await asyncio.sleep(15)


def _active_recovery_job_ids() -> set[str]:
    """Job ids whose upstream handle a live recovery task of this process owns."""
    prefix = "gpu-manager:restart-recovery:"
    ids: set[str] = set()
    for task in list(_restart_recovery_tasks):
        if task.done():
            continue
        name = task.get_name()
        if name.startswith(prefix):
            ids.add(name[len(prefix):])
    return ids


async def _reconcile_slots_after_restart() -> int:
    """Release busy slot leases that a previous incarnation left behind.

    A slot acquired before this process started has no live worker behind it.
    Without this it would block new work until the time-based reaper expires it
    (``forward_timeout`` + margin: hours for ComfyUI). A slot stays only when a
    retained recovery task of this process owns the job's upstream handle. The
    release is a compare-and-release, so a lease a worker acquires between
    classification and release is never freed.
    """
    manager = async_slot_manager
    if manager is None or job_tracker is None:
        return 0
    from datetime import datetime as _datetime, timezone as _timezone
    process_started = _datetime.fromtimestamp(_PROCESS_STARTED_AT, tz=_timezone.utc)
    recovery_ids = _active_recovery_job_ids()
    released = 0
    services = (_load_services_config() or {}).get('services', {}) or {}
    for svc_name, svc_cfg in services.items():
        if not svc_cfg.get('enabled') or not (
            svc_cfg.get('type') in ('llm_backend', 'generation_backend')
            or _is_internal_workflow_service(svc_cfg)
        ):
            continue
        try:
            slots = await manager.get_slots(svc_name)
            for slot_id, slot in slots.items():
                if not isinstance(slot, dict) or slot.get('status') != 'busy':
                    continue
                job_id = str(slot.get('job_id') or '')
                job = (
                    await asyncio.to_thread(job_tracker.get_job, job_id)
                    if job_id else None
                )
                decision = classify_boot_slot(
                    slot=slot,
                    job=job,
                    process_started_at=process_started,
                    recovery_job_ids=recovery_ids,
                )
                if decision.action is not SlotAction.RELEASE:
                    continue
                if await manager.release_slot_if_unchanged(
                    svc_name, int(slot_id), job_id, str(slot.get('started_at') or '')
                ):
                    released += 1
                    logger.warning(
                        "Restart reconcile: released orphaned slot %s/%s "
                        "(job=%s, %s)",
                        svc_name, slot_id, job_id or '-', decision.reason,
                    )
        except Exception as exc:
            logger.warning(
                "Restart reconcile: slot sweep failed for %s: %s", svc_name, exc
            )
    _queue_recovery_stats['slots_released_at_boot'] += released
    return released


async def _reconcile_inflight_after_restart() -> dict[str, int]:
    """Reconcile pending-entry leases left behind by a previous incarnation.

    Every pending entry is judged by ``classify_pel_entry``. An entry delivered
    after this process started belongs to a live worker and is never touched.
    An older one is acked (terminal), cancelled, handed to forwarded-job
    recovery (never requeued: that would resubmit the prompt), held inside its
    restart backoff window, requeued atomically, or, once its bounded requeue
    budget is spent, dead-lettered. Safe to run repeatedly. The returned
    counters tell the sweep loop whether another pass is needed (``waiting`` or
    ``failed_groups`` > 0).
    """
    summary = {
        "preserved": 0, "waiting": 0, "requeued": 0, "dead_lettered": 0,
        "acked_terminal": 0, "cancelled": 0, "forwarded": 0, "failed_groups": 0,
    }
    if async_queue is None or job_tracker is None:
        return summary
    _queue_recovery_stats["reconcile_sweeps"] += 1
    uptime_ms = int((time.time() - _PROCESS_STARTED_AT) * 1000)
    recovery_ids = _active_recovery_job_ids()
    cfg = _load_services_config() or {}
    groups = set()
    for svc_name, svc in (cfg.get('services', {}) or {}).items():
        if svc.get('routing_group'):
            groups.add(svc['routing_group'])
    for tmpl in (cfg.get('generation_templates', {}) or {}).values():
        if isinstance(tmpl, dict) and tmpl.get('routing_group'):
            groups.add(tmpl['routing_group'])
    for group in sorted(groups):
        try:
            try:
                pending = await async_queue.get_pending(
                    group, routing_group=group, strict=True
                )
            except TypeError as exc:
                # Narrow staging doubles from older queue adapters may not yet
                # expose the strict keyword.  Preserve compatibility for those
                # doubles, while production AsyncRedisQueue takes the strict
                # path and surfaces a Redis outage to this reconcile loop.
                if "strict" not in str(exc):
                    raise
                pending = await async_queue.get_pending(
                    group, routing_group=group
                )
            if not pending:
                continue
            conn = await async_queue._get_conn()
            for item in pending:
                entry_id = item.get('entry_id')
                # Priority-lane handles are opaque outside the queue engine;
                # resolve them before the payload lookup while retaining the
                # original handle for ACK/YIELD so the exact PEL entry is
                # acknowledged.
                resolver = getattr(async_queue, 'resolve_entry_stream', None)
                if callable(resolver):
                    stream, raw_entry_id, _lane = resolver(
                        group, entry_id or '', routing_group=group
                    )
                else:
                    # Compatibility for narrow test doubles and older queue
                    # adapters; production AsyncRedisQueue always exposes the
                    # resolver once lane handles are enabled.
                    stream = async_queue._stream(group, routing_group=group)
                    raw_entry_id = entry_id or ''
                rows = await conn.xrange(
                    stream, min=raw_entry_id, max=raw_entry_id, count=1
                )
                payload = rows[0][1] if rows else {}
                job_id = payload.get('job_id', '')
                if isinstance(job_id, bytes):
                    job_id = job_id.decode()
                raw_requeues = payload.get('_restart_requeue_count', 0)
                if isinstance(raw_requeues, bytes):
                    raw_requeues = raw_requeues.decode()
                try:
                    requeues = max(0, int(raw_requeues or 0))
                except (TypeError, ValueError):
                    requeues = 0
                job = await asyncio.to_thread(job_tracker.get_job, job_id) if job_id else None
                decision = classify_pel_entry(
                    job=job,
                    idle_ms=int(item.get('idle_ms', 0) or 0),
                    uptime_ms=uptime_ms,
                    requeues_so_far=requeues,
                    recovery_active=bool(job_id) and job_id in recovery_ids,
                )
                action = decision.action

                if action in (PelAction.ACK_TERMINAL, PelAction.ACK_CANCELLED):
                    if action is PelAction.ACK_CANCELLED:
                        # Only a non-terminal job is ever rewritten to cancelled;
                        # the classifier releases a real terminal outcome as is.
                        await asyncio.to_thread(
                            job_tracker.update_status, job_id, 'cancelled',
                            error='cancelled before restart reconciliation',
                        )
                        summary["cancelled"] += 1
                        _queue_recovery_stats["pel_cancelled"] += 1
                    else:
                        summary["acked_terminal"] += 1
                        _queue_recovery_stats["pel_acked_terminal"] += 1
                    await async_queue.ack(group, 'restart-reconciler', entry_id,
                                          routing_group=group)
                    logger.info(
                        f"Restart reconcile: removed terminal/cancelled PEL job {job_id} "
                        f"from {group} ({decision.reason})"
                    )
                    continue

                if action is PelAction.RECOVER_FORWARDED:
                    # A persisted prompt id proves the worker already crossed the
                    # forward boundary. Never requeue the original payload (that
                    # would submit a duplicate prompt); hand the existing handle
                    # to a retained recovery task and ACK this PEL entry.
                    comfyui_prompt_id = str((job or {}).get('comfyui_prompt_id') or '').strip()
                    await asyncio.to_thread(
                        job_tracker.update_status,
                        job_id,
                        'in_flight',
                        restart_reconcile='existing_prompt_recovery_started',
                        restart_recovery='scheduled',
                    )
                    recovery_task = asyncio.create_task(
                        _recover_forwarded_comfyui_job_after_restart(
                            job_id,
                            job or {},
                            comfyui_prompt_id,
                        ),
                        name=f"gpu-manager:restart-recovery:{job_id}",
                    )
                    _restart_recovery_tasks.add(recovery_task)
                    recovery_task.add_done_callback(_restart_recovery_tasks.discard)
                    await async_queue.ack(
                        group, 'restart-reconciler', entry_id or '',
                        routing_group=group,
                    )
                    summary["forwarded"] += 1
                    _queue_recovery_stats["forwarded_recovered"] += 1
                    logger.warning(
                        f"Restart reconcile: recovering already-forwarded "
                        f"ComfyUI job {job_id} (prompt_id={comfyui_prompt_id}) "
                        "without duplicate submission"
                    )
                    continue

                if action in (PelAction.PRESERVE_ACTIVE, PelAction.PRESERVE_BACKOFF):
                    summary["preserved"] += 1
                    _queue_recovery_stats["pel_preserved"] += 1
                    if decision.reason != "delivered_by_current_process":
                        # Not owned by a live worker: revisit after its window.
                        summary["waiting"] += 1
                        logger.info(
                            f"Restart reconcile: preserving PEL job {job_id} "
                            f"from {group} ({decision.reason}, wait_ms={decision.wait_ms})"
                        )
                    continue

                # REQUEUE / DEAD_LETTER: one atomic, bounded queue operation.
                requeue = getattr(async_queue, 'requeue_after_restart', None)
                if callable(requeue):
                    result = await requeue(
                        group, entry_id, routing_group=group,
                        max_requeues=RESTART_REQUEUE_MAX,
                    )
                elif action is PelAction.DEAD_LETTER:
                    # Older adapters have no bounded requeue: one nack with a
                    # budget of one moves the entry to the dead-letter stream.
                    ok = await async_queue.nack(
                        group, entry_id, routing_group=group, max_retries=1
                    )
                    result = {'outcome': 'dead_lettered' if ok else 'error', 'count': requeues}
                else:
                    ok = await async_queue.yield_pending(
                        group, entry_id, routing_group=group
                    )
                    result = {'outcome': 'requeued' if ok else 'error', 'count': requeues + 1}
                outcome = result.get('outcome')
                if outcome == 'requeued':
                    summary["requeued"] += 1
                    _queue_recovery_stats["pel_requeued"] += 1
                    if job_id:
                        await asyncio.to_thread(
                            job_tracker.update_status, job_id, 'queued',
                            reconciled_after_restart='1',
                            restart_requeue_count=result.get('count', requeues + 1),
                            error='requeued after GPU Manager restart',
                        )
                    logger.info(
                        f"Restart reconcile: requeued unresolved job {job_id} "
                        f"from {group} (restart requeue #{result.get('count')})"
                    )
                elif outcome == 'dead_lettered':
                    summary["dead_lettered"] += 1
                    _queue_recovery_stats["pel_dead_lettered"] += 1
                    if job_id:
                        await asyncio.to_thread(
                            job_tracker.update_status, job_id, 'failed',
                            error=(
                                f"dead-lettered after {result.get('count', requeues)} "
                                "restart requeues"
                            ),
                            error_type='restart_requeue_exhausted',
                            dead_lettered='1',
                        )
                    logger.error(
                        f"Restart reconcile: dead-lettered poison job {job_id} "
                        f"from {group} after {result.get('count', requeues)} restart requeues"
                    )
                elif outcome == 'error':
                    # Redis refused the move: keep the entry and retry next sweep.
                    summary["waiting"] += 1
                    logger.warning(
                        f"Restart reconcile: could not requeue job {job_id} from {group}; "
                        "will retry on the next sweep"
                    )
        except Exception as exc:
            summary["failed_groups"] += 1
            logger.warning(
                f"Restart reconcile: failed for logical group {group}: {exc}"
            )
    return summary


async def _reconcile_inflight_loop() -> None:
    """Run boot reconciliation, then re-sweep until nothing is left waiting.

    The first pass handles every orphan that is already eligible. Entries held
    inside their restart backoff window, and groups whose Redis read failed, are
    revisited every ``RECONCILE_SWEEP_INTERVAL_S`` for at most
    ``RECONCILE_SWEEP_WINDOW_S``; the lease reapers own anything still
    unresolved after that.
    """
    deadline = time.monotonic() + RECONCILE_SWEEP_WINDOW_S
    while True:
        try:
            await _reconcile_slots_after_restart()
            summary = await _reconcile_inflight_after_restart()
            if not summary["waiting"] and not summary["failed_groups"]:
                return
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Restart reconcile sweep failed")
        if time.monotonic() >= deadline:
            logger.warning(
                "Restart reconcile: sweep window elapsed; lease reapers own the remainder"
            )
            return
        await asyncio.sleep(RECONCILE_SWEEP_INTERVAL_S)


async def _reconcile_authoritative_bundle_state() -> None:
    """Rebuild GPU bundle state from healthy configured services after restart.

    Persisted bundle state is only a cache. A stopped generation service must
    not keep claiming its primary GPU or linked reservation-only GPU after a
    manager restart, because that blocks idle restoration indefinitely. Each
    physical GPU set is locked before its first health sample and remains
    locked through the corresponding ownership transition.
    """
    # Never overwrite a ledger while a linked admission/load/unload owns the
    # same physical lanes. The next periodic tick will reconcile it once the
    # transaction has committed or rolled back.
    if _bundle_transition_is_active():
        logger.debug("Authoritative reconcile deferred: bundle transition active")
        return

    cfg = _load_services_config() or {}
    services = cfg.get('services', {})
    bundles = _resolve_bundles()
    claimed_gpu_sets: set[tuple[str, ...]] = set()
    for bundle_name, bundle in bundles.items():
        gpu_id = bundle.get('gpu_id')
        members = [services.get(name, {}) for name in bundle.get('services', [])]
        if not gpu_id or not members:
            continue
        physical_gpu_set = _bundle_physical_gpu_set(
            bundle_name, bundles=bundles
        )
        if not physical_gpu_set:
            logger.warning(
                "Authoritative reconcile: bundle %s has no physical GPU set; "
                "skipping ownership mutation",
                bundle_name,
            )
            continue
        physical_lock = _get_physical_resource_lock(physical_gpu_set)
        async with physical_lock:
            # Re-check after waiting: another transaction may have started
            # while this reconcile was queued on the physical resource.
            if _bundle_transition_is_active():
                logger.debug(
                    "Authoritative reconcile deferred under lock for %s: "
                    "bundle transition active",
                    bundle_name,
                )
                return

            # Retained historical entries can share a port with today's
            # engine. A responding port does not make a retired owner active.
            healthy = all(service_is_publicly_eligible(svc) for svc in members)
            for svc in members:
                if not healthy:
                    break
                port = svc.get('port')
                health_path = str(svc.get('health_path') or '/health')
                if not port or session is None:
                    healthy = False
                    break
                try:
                    async with session.get(
                        f"http://127.0.0.1:{int(port)}{health_path}",
                        timeout=ClientTimeout(total=2, connect=0.5),
                    ) as resp:
                        if resp.status != 200:
                            healthy = False
                            break
                except Exception:
                    healthy = False
                    break

            gs = _get_gpu_state(gpu_id)
            if gs is None:
                continue
            async with _get_bundle_admission_lock(bundle_name):
                if not healthy:
                    # Clear only the unhealthy service-backed owner and its linked
                    # reservations. The shared transition preserves unrelated
                    # bundles already resident on either GPU.
                    if bundle_name in (getattr(gs, "loaded_bundles", []) or []) or \
                       getattr(gs, "loaded_bundle", None) == bundle_name:
                        _transition_linked_bundle_state(
                            bundle_name, [], source="startup_reconcile_unhealthy"
                        )
                        logger.info(
                            f"Startup reconcile: cleared unhealthy bundle "
                            f"'{bundle_name}' from GPU {gpu_id}"
                        )
                    continue

                # A second healthy service touching any already-claimed
                # physical lane is an authority conflict.  Equality is not
                # sufficient here: an RX-only bundle conflicts with a
                # dual-GPU {RX, secondary GPU} bundle even though their tuples differ.
                # Preserve the first deterministic claimant and refuse the
                # incompatible second ledger mutation.
                if any(
                    set(physical_gpu_set).intersection(claimed)
                    for claimed in claimed_gpu_sets
                ):
                    logger.error(
                        "Authoritative reconcile: multiple healthy owners claim "
                        "physical GPU set %s; refusing second owner %s",
                        physical_gpu_set,
                        bundle_name,
                    )
                    _transition_linked_bundle_state(
                        bundle_name, [], source="startup_reconcile_conflict"
                    )
                    continue

                _transition_linked_bundle_state(
                    bundle_name, [bundle_name], source="startup_reconcile"
                )
                claimed_gpu_sets.add(physical_gpu_set)
                gs.state = 'loaded'
                logger.info(
                    f"Startup reconcile: GPU {gpu_id} owns healthy bundle "
                    f"'{bundle_name}' (priority={gs.bundle_priority})"
                )


async def _authoritative_bundle_reconcile_loop() -> None:
    """Continuously heal scheduler ownership from verified service reality.

    This covers direct systemd service operations, which are otherwise
    invisible to the in-memory ledger. It never starts or stops services and
    defers while a bundle transaction is active.
    """
    while True:
        try:
            await asyncio.sleep(30)
            await _reconcile_authoritative_bundle_state()
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.warning("Authoritative bundle reconcile tick failed: %s", exc)



BACKGROUND_TASKS_KEY: web.AppKey[dict[str, asyncio.Task]] = web.AppKey(
    "background_tasks", dict
)
BACKGROUND_STARTUP_HANDLES_KEY: web.AppKey[list[asyncio.TimerHandle]] = web.AppKey(
    "background_startup_handles", list
)
# App-owned coordinator state uses typed keys so an optional staging runtime
# does not add string-key warnings or collide with request/config data.
WORKFLOW_COORDINATOR_RUNTIME_KEY: web.AppKey[Any] = web.AppKey(
    "workflow_coordinator_runtime", object
)
WORKFLOW_COORDINATOR_STOP_KEY: web.AppKey[asyncio.Event] = web.AppKey(
    "workflow_coordinator_stop", asyncio.Event
)
BACKGROUND_TASK_CANCEL_TIMEOUT_SECONDS = 10.0
# Keep scheduler cancellation bounded so aiohttp cleanup completes inside the
# systemd 45-second stop window even if a loop suppresses CancelledError.
SCHEDULER_STOP_TIMEOUT_SECONDS = 10.0
# gpu-manager.service grants 45 seconds for a graceful stop. Keep aiohttp's
# request-drain phase inside that deadline so on_cleanup has time to cancel
# retained workers, close Redis, and persist final ownership state.
AIOHTTP_SHUTDOWN_TIMEOUT_SECONDS = 20.0


def register_background_task(app: web.Application, name: str, coro) -> asyncio.Task:
    """Create and retain one application-owned background task.

    ``on_cleanup`` drains this registry before stopping the scheduler.  Every
    long-lived monitor must use this seam; otherwise a task such as
    ``scheduler_health`` can survive teardown and restart dispatch while the
    service is trying to exit.
    """
    tasks = app.get(BACKGROUND_TASKS_KEY)
    if tasks is None:
        tasks = {}
        app[BACKGROUND_TASKS_KEY] = tasks
    if name in tasks:
        raise RuntimeError(f"background task already registered: {name}")
    task = asyncio.create_task(coro, name=f"gpu-manager:{name}")
    tasks[name] = task
    return task


def register_background_callback(
    app: web.Application, delay: float, callback
) -> asyncio.TimerHandle:
    """Retain a delayed startup callback so cleanup can cancel it."""
    handles = app.get(BACKGROUND_STARTUP_HANDLES_KEY)
    if handles is None:
        handles = []
        app[BACKGROUND_STARTUP_HANDLES_KEY] = handles
    handle = asyncio.get_event_loop().call_later(delay, callback)
    handles.append(handle)
    return handle


def attach_workflow_coordinator_runtime(app: web.Application, runtime: Any) -> None:
    """Attach an already-built coordinator runtime to this controller.

    Attachment is explicit and dependency-injected: the default controller
    does not construct a second Redis stream, discover adapters, or activate a
    candidate workflow.  A staging/bootstrap caller may set a
    ``ControllerPipelineRuntime`` here; the tier-2 startup hook then owns one
    ``CoordinatorConsumer`` task and cleanup cancels it with the other app
    tasks.  Passing a second runtime is rejected so a service registration
    cannot accidentally create duplicate consumers.
    """

    if runtime is None or not callable(getattr(runtime, "process_one", None)):
        raise TypeError("workflow coordinator runtime must expose process_one()")
    if app.get(WORKFLOW_COORDINATOR_RUNTIME_KEY) is not None:
        raise RuntimeError("workflow coordinator runtime already attached")
    app[WORKFLOW_COORDINATOR_RUNTIME_KEY] = runtime


def _start_background_tasks(app: web.Application):
    """Create all background tasks — called AFTER server bind via staggered call_later.

    This is deferred from on_startup to avoid blocking loop.create_server()
    on Python 3.14 + aiohttp 3.13 where all create_task() calls in on_startup
    prevent the TCP socket from binding.

    Tasks are staggered to prevent overwhelming the event loop.
    """
    loop = asyncio.get_event_loop()

    # Tier 1 (immediate): Core services that everything else depends on
    app["bg_task"] = register_background_task(app, "background_loop", background_loop(app))
    app["vram_task"] = register_background_task(app, "vram_pusher", _vram_pusher_loop())
    app["proactive_dispatcher"] = register_background_task(app, "proactive_dispatcher", _proactive_dispatch_loop())
    logger.info("Started proactive_dispatch_loop (dry-run mode)")
    register_background_task(app, "peer_health", _peer_health_loop())
    # An external broker owns the lifecycle state for its members.  Keep its
    # healthy-persisted-JOINING repair in a separate, cancellable monitor so
    # ordinary health reads never mutate broker state and embedded deployments
    # do not create a second lifecycle authority.
    try:
        if _combined_gemma_broker_enabled() and not _combined_gemma_broker_embedded():
            register_background_task(
                app,
                "combined_gemma_rejoin",
                _external_combined_gemma_rejoin_loop(),
            )
    except ValueError:
        logger.error("Invalid Combined Gemma deployment; rejoin monitor disabled", exc_info=True)

    # ── Phase 4: watchdog tier — always-on, independent of vram/scheduler ──
    # These three loops are critical infrastructure: they ensure OOM recovery
    # fires even if the vram pusher stalls, that scheduler dispatch can't
    # silently die, and that stale --mcp siblings don't keep serving stale
    # state. We start them alongside Tier 1 so they're up from second 0.
    app["oom_watchdog"] = register_background_task(app, "oom_watchdog", _oom_recovery_watchdog_loop())
    app["scheduler_health"] = register_background_task(app, "scheduler_health", _scheduler_health_check_loop())
    app["mcp_cleanup"] = register_background_task(app, "mcp_cleanup", _delayed_stale_mcp_cleanup())
    # Phase 5.2.49: stale-job reaper — force-fails orphaned in_flight jobs
    app["stale_job_reaper"] = register_background_task(app, "stale_job_reaper", _stale_job_reaper_loop())
    if app.get("debug_reservations"):
        app["expire_reservations_task"] = register_background_task(app, "expire_reservations", _expire_reservations_loop())

    # Tier 2 (1s later): Queue and proxy infrastructure
    def _start_tier2():
        # OLD: app["queue_worker"] = asyncio.create_task(queue_worker_loop())
        # NEW: WorkerSupervisor handles all queue processing
        global _services_config, event_bus, worker_supervisor, _worker_supervisor_task
        _queue_owner = _queue_owner_mode()
        cfg = _services_config
        if cfg is None:
            cfg = _load_services_config()
            _services_config = cfg
        register_background_task(app, "start_port_proxies", _start_all_port_proxies(cfg))
        # Initialize bundle proxy queues
        bundles = _resolve_bundles()
        for bname in bundles:
            _get_bundle_queue(bname)
        logger.info(f"Bundle proxy: initialized {len(bundles)} bundle queues")

        # ── Dynamic Worker Pool: Initialize event bus and supervisor ──
        event_bus = ServiceEventBus()
        # session is set in on_startup (Option A), which runs before _start_tier2.
        # Guard for type-checker: on_startup guarantees non-None, but the global
        # is typed Optional. We fall back to creating a transient session if (in
        # some future refactor) startup ordering changes.
        if session is None:
            worker_session = ClientSession(timeout=ClientTimeout(total=300, connect=10))
        else:
            worker_session = session
        # Optional, explicit coordinator attachment.  Build the admission
        # and terminal-mirror seams before the worker supervisor so every
        # internal-workflow pool receives the same single handoff object.  No
        # runtime is created here: legacy/Krea workers remain unchanged until
        # a reviewed staging bootstrap attaches one to the app.
        _coordinator_runtime = (
            app.get(WORKFLOW_COORDINATOR_RUNTIME_KEY)
            if _queue_owner != 'legacy'
            else None
        )
        _coordinator_admission = None
        _coordinator_mirror = None
        _coordinator_consumer = None
        if _coordinator_runtime is not None:
            try:
                from workflow_coordinator_runtime import (
                    CoordinatorConsumer,
                    CoordinatorJobMirror,
                    CoordinatorParentAdmission,
                )

                _coordinator_admission = CoordinatorParentAdmission(
                    _coordinator_runtime
                )
                if job_tracker is not None:
                    _coordinator_mirror = CoordinatorJobMirror(
                        job_tracker.update_status
                    )
                # Construct the consumer before exposing admission to workers;
                # a graph entry must never be ACKed into a parent stream that
                # has no consumer object ready to drain it.
                _coordinator_consumer = CoordinatorConsumer(
                    _coordinator_runtime,
                    on_terminal=_coordinator_mirror,
                )
            except Exception:
                logger.exception(
                    "Workflow coordinator admission could not be attached"
                )
                app.pop(WORKFLOW_COORDINATOR_RUNTIME_KEY, None)
                _coordinator_runtime = None

        if _queue_owner == 'legacy':
            # Legacy mode is a deliberate compatibility drain: do not create
            # a stopped durable supervisor that can later be mistaken for a
            # second owner.  The background loop owns GPUScheduler only.
            worker_supervisor = None
            _worker_supervisor_task = None
            logger.info(
                "Queue owner=legacy; durable WorkerSupervisor startup is fenced"
            )
        else:
            worker_supervisor = WorkerSupervisor(
                worker_session,
                coordinator_admission=_coordinator_admission,
            )
            _worker_supervisor_task = register_background_task(app, "worker_supervisor", worker_supervisor.run())
            app["worker_supervisor"] = _worker_supervisor_task  # weak ref for shutdown access
            logger.info("Dynamic Worker Pool: supervisor started")
            register_background_task(app, "reconcile_inflight_after_restart", _reconcile_inflight_loop())

        # The consumer uses the coordinator's own durable parent stream and is
        # registered in the same app task registry for bounded shutdown.
        if (
            _queue_owner != 'legacy'
            and _coordinator_runtime is not None
            and _coordinator_consumer is not None
            and worker_supervisor is not None
        ):
            try:
                _coordinator_stop = asyncio.Event()
                app[WORKFLOW_COORDINATOR_STOP_KEY] = _coordinator_stop
                app["workflow_coordinator"] = _coordinator_consumer
                register_background_task(
                    app,
                    "workflow_coordinator",
                    _coordinator_consumer.run(_coordinator_stop),
                )
                logger.info("Workflow coordinator consumer attached (explicit runtime)")
            except Exception:
                logger.exception("Workflow coordinator consumer could not be attached")
                app.pop(WORKFLOW_COORDINATOR_RUNTIME_KEY, None)
                # The supervisor may already be running its startup grace
                # period.  Remove the admission object immediately so a pool
                # created after this failure cannot ACK graph entries without
                # a coordinator consumer.
                worker_supervisor.coordinator_admission = None
                for _pool in worker_supervisor._pools.values():
                    _pool.coordinator_admission = None

        # ── Startup health probe: emit "healthy" for already-running services ──
        async def _probe_initial_health():
            """Emit healthy events for services already running at startup."""
            await asyncio.sleep(3)  # let supervisor boot
            svcs = cfg.get("services", {})
            for svc_name, svc_cfg in svcs.items():
                if svc_cfg.get("type") != "llm_backend" or not svc_cfg.get("enabled"):
                    continue
                port = svc_cfg.get("port")
                if not port:
                    continue
                try:
                    async with ClientSession(timeout=ClientTimeout(total=3)) as sess:
                        async with sess.get(f"http://127.0.0.1:{port}/health") as resp:
                            if resp.status == 200:
                                event_bus.emit(svc_name, "healthy")
                                logger.info(f"Startup probe: {svc_name} healthy on :{port}")
                except Exception:
                    logger.debug(f"Startup probe: {svc_name} not reachable on :{port}")

            await _reconcile_authoritative_bundle_state()

        register_background_task(app, "initial_health_probe", _probe_initial_health())
        app["authoritative_bundle_reconciler"] = register_background_task(
            app, "authoritative_bundle_reconciler", _authoritative_bundle_reconcile_loop()
        )

    # Tier 3 (2s later): Non-critical startup tasks
    def _start_tier3():
        register_background_task(app, "ensure_services_running", ensure_services_running())
        register_background_task(app, "regenerate_nginx_config", _regenerate_nginx_config())
        register_background_task(app, "seed_comfyui_idle_timer", _seed_comfyui_idle_timer())

    register_background_callback(app, 1.0, _start_tier2)
    register_background_callback(app, 2.0, _start_tier3)


async def on_startup(app: web.Application):
    # ── Initialize shared ClientSession BEFORE any handler can run (Option A) ──
    # Fixes the 24 broken `session.X` call sites that were None at startup.
    # Idempotent: if background_loop re-runs session_init, we still hold one
    # live session with connection pooling, then close on cleanup.
    global session, vram
    if session is None or session.closed:
        session = ClientSession(timeout=ClientTimeout(total=300, connect=10))

    # The application is now inside its definitive running event loop.  Build
    # and attach the coordinator here (before delayed WorkerPool admission),
    # so run_coroutine_threadsafe always targets this server loop.
    if _queue_owner_mode() != "legacy" and _queue_redis is not None:
        _production_coordinator = _build_production_coordinator_runtime(_services_config)
        if _production_coordinator is not None:
            attach_workflow_coordinator_runtime(app, _production_coordinator)

    # The broker uses the already-initialized shared queue Redis and session.
    # It starts fail-closed: no member can accept until semantic probe evidence
    # is refreshed; initialization never starts/stops/restarts a member.
    await _initialize_combined_gemma_broker()

    # Reconcile lifecycle cache from authoritative systemd state before the
    # API or idle gates can observe it. The constructor defaults to "running",
    # which is wrong after a normal direct-idle shutdown followed by manager
    # restart.
    if vram is not None:
        try:
            _startup_comfyui_states = await vram._comfyui_systemd_state()
            if vram._all_comfyui_units_stopped(_startup_comfyui_states):
                vram._comfyui_stopped = True
                vram._comfyui_auto_stopped = True
                logger.info(
                    "Startup reconcile: all ComfyUI units stopped -> stopped "
                    "(%s)",
                    _startup_comfyui_states,
                )
            elif vram._any_comfyui_unit_active(_startup_comfyui_states):
                vram._comfyui_stopped = False
                vram._comfyui_auto_stopped = False
                logger.info(
                    "Startup reconcile: at least one ComfyUI unit active -> running "
                    "(%s)",
                    _startup_comfyui_states,
                )
            else:
                logger.warning(
                    "Startup reconcile: ComfyUI systemd states unknown=%r; "
                    "retaining conservative running cache",
                    _startup_comfyui_states,
                )
        except Exception as _startup_comfyui_err:
            logger.warning(
                "Startup reconcile: ComfyUI state check failed; retaining "
                "conservative running cache: %s",
                _startup_comfyui_err,
            )

    # CRITICAL: Defer background task creation via call_later() so the event loop
    # can process loop.create_server() in site.start() BEFORE tasks start running.
    # Without this, Python 3.14 + aiohttp 3.13 hangs on port binding.
    loop = asyncio.get_event_loop()
    loop.call_later(5.0, _start_background_tasks, app)

    # ── Restore per-GPU state from persisted state ──
    try:
        saved = _load_state()
        saved_gpu_states = saved.get("gpu_states", {})
        for gpu_id, gpu_data in saved_gpu_states.items():
            gpu = _get_gpu_state(gpu_id)
            gpu.loaded_bundle = gpu_data.get("loaded_bundle")
            gpu.bundle_priority = gpu_data.get("bundle_priority", 0)
            gpu.state = gpu_data.get("state", "idle")
            # Don't restore draining state — that's ephemeral
            if gpu_data.get("draining"):
                logger.info(f"GPU[{gpu_id}]: was draining at shutdown — resetting to idle")
                gpu.draining = False
                gpu.drain_started_at = None
            # Don't restore queue — those requests are lost on restart
            logger.info(
                f"GPU[{gpu_id}]: restored state: bundle={gpu.loaded_bundle}, "
                f"priority={gpu.bundle_priority}, state={gpu.state}"
            )
    except Exception as e:
        logger.debug(f"Per-GPU state restore skipped: {e}")

    logger.info("GPU Manager started (dashboard: http://localhost:8091/dashboard)")

    # ── Phase 5: OOM Redis pool init ──
    # Best-effort: dead-letter store is in Redis. If Redis is unavailable
    # at startup, _init_oom_redis logs a warning and sets _oom_redis_pool=None;
    # the watchdog will retry on the next refresh tick.
    try:
        await _init_oom_redis()
    except Exception as e:
        logger.warning(f"[oom-redis] _init_oom_redis from on_startup raised: {e}")
async def on_cleanup(app: web.Application):
    global _controller_shutdown_in_progress
    _controller_shutdown_in_progress = True
    # Save final state before tearing down — this is the clean shutdown state
    _save_state(shutdown=True)
    logger.info("Final state saved on cleanup (clean shutdown)")
    _coordinator_stop = app.get(WORKFLOW_COORDINATOR_STOP_KEY)
    if _coordinator_stop is not None:
        _coordinator_stop.set()
    for handle in app.get(BACKGROUND_STARTUP_HANDLES_KEY, []):
        handle.cancel()
    app[BACKGROUND_STARTUP_HANDLES_KEY] = []
    background_tasks = dict(app.get(BACKGROUND_TASKS_KEY, {}))
    for task in background_tasks.values():
        if not task.done():
            task.cancel()
    if background_tasks:
        done, pending = await asyncio.wait(
            background_tasks.values(),
            timeout=BACKGROUND_TASK_CANCEL_TIMEOUT_SECONDS,
        )
        for name, task in background_tasks.items():
            if task in pending:
                logger.warning(
                    "Background task %s exceeded %.1fs cancellation budget",
                    name,
                    BACKGROUND_TASK_CANCEL_TIMEOUT_SECONDS,
                )
                continue
            try:
                exc = task.exception()
            except asyncio.CancelledError:
                continue
            if exc is not None:
                logger.warning("Background task %s ended during cleanup: %r", name, exc)
    app[BACKGROUND_TASKS_KEY] = {}
    # Close the broker before the shared session/Redis owners begin teardown.
    global _combined_gemma_broker, _combined_gemma_member_cache
    broker = _combined_gemma_broker
    _combined_gemma_broker = None
    _combined_gemma_member_cache = None
    if broker is not None:
        try:
            await broker.close()
        except Exception:
            logger.warning("Combined Gemma broker close failed", exc_info=True)
    # ── Close async Redis connections (Phase 3) ──
    try:
        if async_gossiper:
            await async_gossiper.close()
    except Exception:
        pass
    if _async_redis:
        try:
            await _async_redis.aclose()
        except Exception:
            pass
    await scheduler.stop()
    await _stop_all_port_proxies()
    # Drain all bundle proxy queues with 503 on shutdown
    for bname, q in _bundle_proxy_queues.items():
        q.signal_failed("gpu-manager shutting down")
    _bundle_proxy_queues.clear()
    logger.info("Bundle proxy: all queues drained on shutdown")
    if session:
        try:
            await asyncio.wait_for(session.close(), timeout=5)
        except asyncio.TimeoutError:
            logger.warning("Timed out closing shared HTTP session during shutdown")
    logger.info("GPU Manager shut down")


# ── Main ───────────────────────────────────────────────────────────

def main():
    global LLM_BACKEND_URL, COMFYUI_URL, LISTEN_PORT

    parser = argparse.ArgumentParser(description="GPU Manager — LLM Proxy + Unified GPU Scheduler")
    parser.add_argument("--listen", type=int, default=LISTEN_PORT)
    parser.add_argument("--host", type=str, default="127.0.0.1",
                        help="Host to bind to (default: 127.0.0.1, use 0.0.0.0 for external access)")
    parser.add_argument(
        "--backend", type=int, default=None,
        help="legacy localhost backend port override; otherwise use LLM_BACKEND_URL",
    )
    parser.add_argument(
        "--comfyui", type=int, default=None,
        help="legacy localhost ComfyUI port override; otherwise use COMFYUI_URL",
    )
    parser.add_argument("--mcp", action="store_true", help="Run as MCP stdio server instead of HTTP")
    parser.add_argument("--debug-reservations", action="store_true", help="Enable debug reservation hooks")
    parser.add_argument("--debug-oom-sim", action="store_true", help="Enable safe OOM simulation hook")
    args = parser.parse_args()

    log_directory = os.path.dirname(LOG_FILE)
    if log_directory:
        os.makedirs(log_directory, exist_ok=True)
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(name)s] %(levelname)s: %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
        handlers=[logging.FileHandler(LOG_FILE), logging.StreamHandler()],
    )

    global logger
    logger = logging.getLogger("gpu-manager")

    if args.mcp:
        logger.info("Starting GPU Manager in MCP stdio mode")
        asyncio.run(run_mcp_server())
        return

    if _first_boot_config_failed():
        logger.critical(
            "services config %s exists but failed to load/validate; refusing to serve on "
            "the empty default config (see the warning above)", SERVICES_CONFIG_PATH,
        )
        sys.exit(78)  # EX_CONFIG

    LISTEN_PORT = args.listen
    if args.backend is not None:
        LLM_BACKEND_URL = f"http://localhost:{args.backend}"
    if args.comfyui is not None:
        COMFYUI_URL = f"http://localhost:{args.comfyui}"

    logger.info(f"GPU Manager starting on port {LISTEN_PORT}")
    logger.info(f"Backend: {LLM_BACKEND_URL} | ComfyUI: {COMFYUI_URL}")
    logger.info(f"GPU state machine: LLM_LOADED (default) → DRAINING → GPU_WORK → RESTORING")
    logger.info(f"LLM relief threshold: {LLM_RELIEF_THRESHOLD} | drain timeout: {DRAIN_TIMEOUT}s")

    web.run_app(
        create_app(
            debug_reservations=args.debug_reservations,
            debug_oom_sim=args.debug_oom_sim,
        ),
        host=args.host,
        port=LISTEN_PORT,
        print=lambda msg: logger.info(msg),
        handle_signals=True,
        shutdown_timeout=AIOHTTP_SHUTDOWN_TIMEOUT_SECONDS,
        handler_cancellation=True,
    )


if __name__ == "__main__":
    main()
